// src/App.tsx
import React, { Suspense } from 'react';
import { BrowserRouter as Router, Route, Routes, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Toaster } from 'sileo';

import Dashboard from './components/layout/Dashboard';
import { LoginPage } from './features/auth/pages/LoginPage';
import { PrivateRoute } from './components/auth/PrivateRoute';
import { Spinner } from './components/common/Spinner';
import { useThemeStore } from './stores/theme.store';

// Páginas del dashboard (carga inmediata)
import { DashboardPage } from './features/dashboard/pages/DashboardPage';
import { ReportsPage } from './features/dashboard/pages/ReportsPage';
import { WelcomePage } from './features/dashboard/pages/WelcomePage';

// Lazy loading para componentes pesados
const ClientsListPage = React.lazy(() => import('./features/clients/pages/ClientsListPage').then(module => ({ default: module.ClientsListPage })));
const ClientFormPage = React.lazy(() => import('./features/clients/pages/ClientFormPage').then(module => ({ default: module.ClientFormPage })));

// Páginas de configuración (lazy)
const CompanySettingsPage = React.lazy(() => import('./features/settings/pages/CompanySettingsPage').then(module => ({ default: module.CompanySettingsPage })));
const UsersPage = React.lazy(() => import('./features/settings/pages/UsersPage').then(module => ({ default: module.UsersPage })));
const RolesPage = React.lazy(() => import('./features/settings/pages/RolesPage').then(module => ({ default: module.RolesPage })));
const SettingsIndexPage = React.lazy(() => import('./features/settings/pages/SettingslndexPage'));
const WhatsAppConfigPage = React.lazy(() => import('./features/settings/pages/WhatsAppConfigPage'));
const UpdatesAdminPage = React.lazy(() => import('./features/updates/pages/UpdatesAdminPage'));
const ChangelogPage = React.lazy(() => import('./features/changelog/pages/ChangelogPage'));

// Páginas de ventas (lazy)
const QuotationsListPage = React.lazy(() => import('./features/sales/pages/QuotationsListPage').then(module => ({ default: module.QuotationsListPage })));
const QuotationNewPage = React.lazy(() => import('./features/quotations/pages/QuotationNewPage').then(module => ({ default: module.QuotationNewPage })));
const QuotationDetailPage = React.lazy(() => import('./features/quotations/pages/QuotationDetailPage').then(module => ({ default: module.QuotationDetailPage })));

// Páginas de guías de remisión (lazy)
const RemissionGuidesListPage = React.lazy(() => import('./features/remissionGuides/pages/RemissionGuidesListPage').then(module => ({ default: module.RemissionGuidesListPage })));
const RemissionGuideFormPage = React.lazy(() => import('./features/remissionGuides/pages/RemissionGuideFormPage').then(module => ({ default: module.RemissionGuideFormPage })));
const RemissionGuideDetailPage = React.lazy(() => import('./features/remissionGuides/pages/RemissionGuideDetailPage').then(module => ({ default: module.RemissionGuideDetailPage })));

// Páginas del módulo fluvial (lazy)
const SalesPointPage = React.lazy(() => import('./features/fluvial/pages/SalesPointPage'));
const CitiesPortsPage = React.lazy(() => import('./features/fluvial/pages/CitiesPortsPage').then(module => ({ default: module.CitiesPortsPage })));
const VesselsPage = React.lazy(() => import('./features/fluvial/pages/VesselsPage').then(module => ({ default: module.VesselsPage })));
const FaresByRoutePage = React.lazy(() => import('./features/fluvial/pages/FaresByRoutePage').then(module => ({ default: module.FaresByRoutePage })));
const RoutesPage = React.lazy(() => import('./features/fluvial/pages/RoutesPage').then(module => ({ default: module.RoutesPage })));
const SeatTypesPage = React.lazy(() => import('./features/fluvial/pages/SeatTypesPage').then(module => ({ default: module.SeatTypesPage })));
const ProductsServicesPage = React.lazy(() => import('./features/fluvial/pages/ProductsServicesPage.tsx').then(module => ({ default: module.ProductsServicesPage })));
const ScheduleTripsPage = React.lazy(() => import('./features/fluvial/pages/ScheduleTripsPage').then(module => ({ default: module.ScheduleTripsPage })));
const SeriesAndOfficesPage = React.lazy(() => import('./features/fluvial/pages/SeriesAndOfficesPage').then(module => ({ default: module.DocumentSeriesPage })));
const ReservationsPage = React.lazy(() => import('./features/fluvial/pages/ReservationsPage').then(module => ({ default: module.ReservationsPage })));
const CargoSalePage = React.lazy(() => import('./features/cargo/pages/CargoSalePage').then(module => ({ default: module.CargoSalePage })));
const QuickSalePage = React.lazy(() => import('./features/fluvial/quick-sales/pages/QuickSalePage').then(module => ({ default: module.default })));
const ManifestsPage = React.lazy(() => import('./features/manifests/pages/ManifestsPage').then(module => ({ default: module.ManifestsPage })));
const TripManifestsPage = React.lazy(() => import('./features/manifests/pages/TripManifestsPage').then(module => ({ default: module.TripManifestsPage })));

// Páginas de contabilidad (lazy)
const InvoicesListPage = React.lazy(() => import('./features/accounting/pages/InvoicesListPage').then(module => ({ default: module.InvoicesListPage })));
const InvoiceDetailPage = React.lazy(() => import('./features/accounting/pages/InvoiceDetailPage').then(module => ({ default: module.InvoiceDetailPage })));
const CreditNotesListPage = React.lazy(() => import('./features/accounting/credit-notes/pages/CreditNotesListPage').then(module => ({ default: module.CreditNotesListPage })));
const CreditNoteNewPage = React.lazy(() => import('./features/accounting/credit-notes/pages/CreditNoteNewPage').then(module => ({ default: module.CreditNoteNewPage })));
const CreditNoteFullFormPage = React.lazy(() => import('./features/accounting/credit-notes/pages/CreditNoteFullFormPage').then(module => ({ default: module.CreditNoteFullFormPage })));
const CreditNoteAnnulFormPage = React.lazy(() => import('./features/accounting/credit-notes/pages/CreditNoteAnnulFormPage').then(module => ({ default: module.CreditNoteAnnulFormPage })));
const CreditNoteDetailPage = React.lazy(() => import('./features/accounting/credit-notes/pages/CreditNoteDetailPage').then(module => ({ default: module.CreditNoteDetailPage })));
const DebitNotesListPage = React.lazy(() => import('./features/accounting/debit-notes/pages/DebitNotesListPage').then(module => ({ default: module.DebitNotesListPage })));
const DebitNoteNewPage = React.lazy(() => import('./features/accounting/debit-notes/pages/DebitNoteNewPage').then(module => ({ default: module.DebitNoteNewPage })));
const DebitNoteFormPage = React.lazy(() => import('./features/accounting/debit-notes/pages/DebitNoteFormPage').then(module => ({ default: module.DebitNoteFormPage })));
const DebitNoteAnnulPage = React.lazy(() => import('./features/accounting/debit-notes/pages/DebitNoteAnnulPage').then(module => ({ default: module.DebitNoteAnnulPage })));
const DebitNoteDetailPage = React.lazy(() => import('./features/accounting/debit-notes/pages/DebitNoteDetailPage').then(module => ({ default: module.DebitNoteDetailPage })));

// Páginas de finanzas (lazy)
const ReceivablesPage = React.lazy(() => import('./features/finance/pages/ReceivablesPage'));
const ExpensesPage = () => <div className="p-6"><h1 className="text-2xl font-bold">Gastos</h1><p>Gestión de gastos operativos</p></div>;

// Páginas de supervisor (lazy)
const CancellationRequestsPage = React.lazy(() => import('./features/supervisor/pages/CancellationRequestsPage').then(module => ({ default: module.default })));

// Crear cliente para React Query
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      retry: 1,
      staleTime: 5 * 60 * 1000, // 5 minutos
    },
  },
});

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <AppContent />
    </QueryClientProvider>
  );
}

function AppContent() {
  // Inicializar tema (aplica clase 'dark' al <html> si corresponde)
  const { resolvedTheme } = useThemeStore();
  React.useEffect(() => {
    useThemeStore.getState().init();
  }, []);

  return (
    <Router>
        <Routes>
          <Route path="/login" element={<LoginPage />} />
          <Route path="/welcome" element={
            <PrivateRoute>
              <WelcomePage />
            </PrivateRoute>
          } />

          <Route path="/" element={
            <PrivateRoute>
              <Dashboard />
            </PrivateRoute>
          }>
            {/* Página de inicio para todos los usuarios */}
            <Route index element={<WelcomePage />} />
            {/* Dashboard analítico solo para administradores */}
            <Route path="dashboard" element={<DashboardPage />} />
            <Route path="reports" element={<ReportsPage />} />

            {/* Gestión de Clientes */}
            <Route path="clients" element={
              <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                <ClientsListPage />
              </Suspense>
            } />
            <Route path="clients/new" element={
              <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                <ClientFormPage />
              </Suspense>
            } />
            <Route path="clients/:id" element={
              <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                <ClientFormPage />
              </Suspense>
            } />

            {/* Sistema de Transporte Fluvial */}
            <Route path="fluvial">
              {/* Configuración Fluvial */}
              <Route path="config">
                <Route path="cities-ports" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <CitiesPortsPage />
                  </Suspense>
                } />
                <Route path="vessels" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <VesselsPage />
                  </Suspense>
                } />
                <Route path="routes" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <RoutesPage />
                  </Suspense>
                } />
                <Route path="fares-by-route" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <FaresByRoutePage />
                  </Suspense>
                } />
                <Route path="seat-types" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <SeatTypesPage />
                  </Suspense>
                } />
                <Route path="products-services" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <ProductsServicesPage />
                  </Suspense>
                } />
                <Route path="document-series" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <SeriesAndOfficesPage />
                  </Suspense>
                } />
                <Route path="series-and-offices" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <SeriesAndOfficesPage />
                  </Suspense>
                } />
              </Route>

              {/* Operaciones Fluviales */}
              <Route path="operations">
                <Route path="schedule-trips" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <ScheduleTripsPage />
                  </Suspense>
                } />
                <Route path="sales-point" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <SalesPointPage />
                  </Suspense>
                } />
                <Route path="reservations" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <ReservationsPage />
                  </Suspense>
                } />
                <Route path="cargo-sale" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <CargoSalePage />
                  </Suspense>
                } />
                <Route path="quick-sales" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <QuickSalePage />
                  </Suspense>
                } />
                <Route path="manifests" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <ManifestsPage />
                  </Suspense>
                } />
                <Route path="manifests/trip/:tripId" element={
                  <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                    <TripManifestsPage />
                  </Suspense>
                } />
              </Route>
            </Route>

            {/* Operaciones Comerciales */}
            <Route path="sales">
              <Route path="quotations" element={<QuotationsListPage />} />
              <Route path="quotations/new" element={<QuotationNewPage />} />
              <Route path="quotations/:id" element={<QuotationDetailPage />} />
              <Route path="quotations/:id/edit" element={<QuotationDetailPage />} />
            </Route>

            {/* Contabilidad */}
            <Route path="accounting">
              <Route path="invoices" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <InvoicesListPage />
                </Suspense>
              } />
              <Route path="invoices/:id" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <InvoiceDetailPage />
                </Suspense>
              } />
              <Route path="credit-notes" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <CreditNotesListPage />
                </Suspense>
              } />
              <Route path="credit-notes/new" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <CreditNoteNewPage />
                </Suspense>
              } />
              <Route path="credit-notes/create" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <CreditNoteFullFormPage />
                </Suspense>
              } />
              <Route path="credit-notes/annul" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <CreditNoteAnnulFormPage />
                </Suspense>
              } />
              <Route path="credit-notes/:id" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <CreditNoteDetailPage />
                </Suspense>
              } />
              <Route path="debit-notes" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <DebitNotesListPage />
                </Suspense>
              } />
              <Route path="debit-notes/new" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <DebitNoteNewPage />
                </Suspense>
              } />
              <Route path="debit-notes/create" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <DebitNoteFormPage />
                </Suspense>
              } />
              <Route path="debit-notes/annul" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <DebitNoteAnnulPage />
                </Suspense>
              } />
              <Route path="debit-notes/:id" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <DebitNoteDetailPage />
                </Suspense>
              } />

            </Route>

            {/* Guías de Remisión (importante para carga) */}
            <Route path="remission-guides" element={<RemissionGuidesListPage />} />
            <Route path="remission-guides/new" element={<RemissionGuideFormPage />} />
            <Route path="remission-guides/:id" element={<RemissionGuideDetailPage />} />
            <Route path="remission-guides/:id/edit" element={<RemissionGuideFormPage />} />

            {/* Reportes SUNAT eliminados */}

            {/* Finanzas */}
            <Route path="finance">
              <Route path="receivables" element={<ReceivablesPage />} />
              <Route path="expenses" element={<ExpensesPage />} />
            </Route>

            {/* Supervisor */}
            <Route path="supervisor">
              <Route path="cancellation-requests" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <CancellationRequestsPage />
                </Suspense>
              } />
            </Route>

            {/* Configuración del Sistema */}
            <Route path="settings">
              <Route index element={<SettingsIndexPage />} /> 
              <Route path="company" element={<CompanySettingsPage />} />
              <Route path="users" element={<UsersPage />} />
              <Route path="roles" element={<RolesPage />} />
              <Route path="whatsapp" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <WhatsAppConfigPage />
                </Suspense>
              } />
              <Route path="updates" element={
                <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                  <UpdatesAdminPage />
                </Suspense>
              } />
            </Route>

            {/* Changelog del frontend */}
            <Route path="changelog" element={
              <Suspense fallback={<div className="flex justify-center items-center h-64"><Spinner size="lg" /></div>}>
                <ChangelogPage />
              </Suspense>
            } />
          </Route>

          {/* Ruta para manejar páginas no encontradas */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>

        <Toaster
          position="top-right"
          theme={resolvedTheme}
          options={{
            duration: 4000,
          }}
        />
      </Router>
    );
}

export default App;

// src/components/common/DataTable.tsx
import React from 'react';
import { PencilIcon, TrashIcon, InboxIcon } from '@heroicons/react/24/outline';
import { Spinner } from './Spinner';

export interface Column<T> {
  key: string;
  header: string;
  accessor: (item: T) => React.ReactNode;
  className?: string;
}

interface DataTableProps<T> {
  data: T[];
  columns: Column<T>[];
  isLoading?: boolean;
  error?: any;
  onEdit?: (item: T) => void;
  onDelete?: (item: T) => void;
  keyExtractor: (item: T) => string | number;
  emptyMessage?: string;
  showActions?: boolean;
  customActions?: (item: T) => React.ReactNode;
}

export function DataTable<T>({
  data,
  columns,
  isLoading = false,
  error = null,
  onEdit,
  onDelete,
  keyExtractor,
  emptyMessage = 'No se encontraron registros',
  showActions = true,
  customActions,
}: DataTableProps<T>) {
  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-3">
        <Spinner size="lg" color="text-primary" />
        <p className="text-[13px] text-dm-text-muted">Cargando...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <div className="flex items-center justify-center w-16 h-16 rounded-[20px] bg-red-500/10">
          <InboxIcon className="w-8 h-8 text-red-400" />
        </div>
        <div className="text-center">
          <p className="text-[15px] font-medium text-dm-text-primary">Error al cargar los datos</p>
          <p className="text-[13px] text-dm-text-muted mt-1">
            {typeof error.message === 'string' ? error.message : 'Ocurrió un error inesperado'}
          </p>
        </div>
      </div>
    );
  }

  if (data.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <div className="flex items-center justify-center w-16 h-16 rounded-[20px] bg-dm-bg-secondary">
          <InboxIcon className="w-8 h-8 text-dm-text-muted" />
        </div>
        <div className="text-center">
          <p className="text-[15px] font-medium text-dm-text-primary">{emptyMessage}</p>
        </div>
      </div>
    );
  }

  const hasActions = showActions && (onEdit || onDelete || customActions);

  return (
    <div className="overflow-x-auto">
      <table className="min-w-full">
        <thead className="bg-dm-bg-secondary border-b border-dm-border-primary">
          <tr>
            {columns.map((column) => (
              <th
                key={column.key}
                className={`px-6 py-3.5 text-left text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider ${
                  column.className || ''
                }`}
              >
                {column.header}
              </th>
            ))}
            {hasActions && (
              <th className="px-6 py-3.5 text-right text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider">
                Acciones
              </th>
            )}
          </tr>
        </thead>
        <tbody className="divide-y divide-dm-border-secondary">
          {data.map((item, index) => {
            const rowKey = keyExtractor(item) ?? `row-${index}`;

            return (
              <tr key={rowKey} className="hover:bg-dm-bg-secondary/60 transition-colors">
                {columns.map((column) => {
                  const cellKey = `${rowKey}-${column.key}`;
                  return (
                    <td
                      key={cellKey}
                      className={`px-6 py-4 whitespace-nowrap text-[13px] text-dm-text-primary ${column.className || ''}`}
                    >
                      {column.accessor(item)}
                    </td>
                  );
                })}
                {hasActions && (
                  <td className="px-6 py-4 whitespace-nowrap text-right">
                    <div className="flex items-center justify-end gap-2">
                      {onEdit && (
                        <button
                          onClick={() => onEdit(item)}
                          className="flex items-center justify-center w-8 h-8 rounded-full text-dm-text-muted hover:text-primary hover:bg-primary/10 transition-colors"
                          title="Editar"
                        >
                          <PencilIcon className="h-4 w-4" strokeWidth={1.5} />
                        </button>
                      )}
                      {onDelete && (
                        <button
                          onClick={() => onDelete(item)}
                          className="flex items-center justify-center w-8 h-8 rounded-full text-dm-text-muted hover:text-red-500 hover:bg-red-500/10 transition-colors"
                          title="Desactivar"
                        >
                          <TrashIcon className="h-4 w-4" strokeWidth={1.5} />
                        </button>
                      )}
                      {customActions && customActions(item)}
                    </div>
                  </td>
                )}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export const useConfirmDelete = (
  onConfirm: (item: any) => void,
  getMessage: (item: any) => string
) => {
  const handleDelete = (item: any) => {
    const message = getMessage(item);
    if (window.confirm(message)) {
      onConfirm(item);
    }
  };

  return handleDelete;
};

// src/components/common/LocationSelector.tsx
import React, { useState, useEffect } from 'react';
import { toast } from '@/utils/sileo-toast';
import { Spinner } from './Spinner';
import { 
  geonamesService, 
  Country, 
  AdministrativeArea, 
  City 
} from '../../services/geonames.service';

interface LocationSelectorProps {
  // Valores actuales
  countryCode?: string;
  department?: string;
  province?: string;
  district?: string;

  // Callbacks para cambios
  onCountryChange: (countryCode: string, countryName: string) => void;
  onDepartmentChange: (department: string, departmentGeonameId?: number) => void;
  onProvinceChange: (province: string, provinceGeonameId?: number) => void;
  onDistrictChange: (district: string) => void;

  // Props adicionales
  disabled?: boolean;
  errors?: {
    country_code?: string;
    department?: string;
    province?: string;
    district?: string;
  };
}

export const LocationSelector: React.FC<LocationSelectorProps> = ({
  countryCode,
  department,
  province,
  district,
  onCountryChange,
  onDepartmentChange,
  onProvinceChange,
  onDistrictChange,
  disabled = false,
  errors = {},
}) => {
  // Estados para los datos
  const [countries, setCountries] = useState<Country[]>([]);
  const [departments, setDepartments] = useState<AdministrativeArea[]>([]);
  const [provinces, setProvinces] = useState<AdministrativeArea[]>([]);
  const [districts, setDistricts] = useState<City[]>([]);

  // Estados de carga
  const [loadingCountries, setLoadingCountries] = useState(false);
  const [loadingDepartments, setLoadingDepartments] = useState(false);
  const [loadingProvinces, setLoadingProvinces] = useState(false);
  const [loadingDistricts, setLoadingDistricts] = useState(false);

  // Referencias para los geonameId seleccionados
  const [selectedDepartmentId, setSelectedDepartmentId] = useState<number | null>(null);
  const [selectedProvinceId, setSelectedProvinceId] = useState<number | null>(null);

  // Cargar países al montar el componente
  useEffect(() => {
    loadCountries();
  }, []);

  // Cargar departamentos/estados cuando cambia el país
  useEffect(() => {
    if (countryCode) {
      loadDepartments(countryCode);
    } else {
      setDepartments([]);
      setProvinces([]);
      setDistricts([]);
    }
  }, [countryCode]);

  // Cargar provincias cuando cambia el departamento
  useEffect(() => {
    if (selectedDepartmentId) {
      loadProvinces(selectedDepartmentId);
    } else {
      setProvinces([]);
      setDistricts([]);
    }
  }, [selectedDepartmentId]);

  // Cargar distritos cuando cambia la provincia
  useEffect(() => {
    if (selectedProvinceId) {
      loadDistricts(selectedProvinceId);
    } else {
      setDistricts([]);
    }
  }, [selectedProvinceId]);

  const loadCountries = async () => {
    setLoadingCountries(true);
    try {
      const data = await geonamesService.getCountries();
      setCountries(data);
    } catch (error: any) {
      toast.error(error.message || 'Error al cargar países');
      // Fallback con países básicos
      setCountries([
        { geonameId: 3932488, countryCode: 'PE', countryName: 'Peru', continent: 'SA', capital: 'Lima', languages: 'es', population: 32971854 },
        { geonameId: 3686110, countryCode: 'CO', countryName: 'Colombia', continent: 'SA', capital: 'Bogotá', languages: 'es', population: 50882891 },
        { geonameId: 3658394, countryCode: 'EC', countryName: 'Ecuador', continent: 'SA', capital: 'Quito', languages: 'es', population: 17643054 },
      ]);
    } finally {
      setLoadingCountries(false);
    }
  };

  const loadDepartments = async (selectedCountryCode: string) => {
    setLoadingDepartments(true);
    try {
      let data: AdministrativeArea[];

      // Optimización especial para Perú
      if (selectedCountryCode === 'PE') {
        data = await geonamesService.getPeruDepartments();
      } else {
        data = await geonamesService.getStatesProvinces(selectedCountryCode);
      }

      setDepartments(data);

      // Auto-seleccionar si hay un valor previo
      if (department && data.length > 0) {
        const foundDept = data.find(d => 
          d.name.toLowerCase() === department.toLowerCase() ||
          d.asciiName.toLowerCase() === department.toLowerCase()
        );
        if (foundDept) {
          setSelectedDepartmentId(foundDept.geonameId);
        }
      }
    } catch (error: any) {
      toast.error(error.message || 'Error al cargar departamentos/estados');
      setDepartments([]);
    } finally {
      setLoadingDepartments(false);
    }
  };

  const loadProvinces = async (departmentGeonameId: number) => {
    setLoadingProvinces(true);
    try {
      let data: AdministrativeArea[];

      // Para Perú, usar método específico
      if (countryCode === 'PE') {
        data = await geonamesService.getPeruProvinces(departmentGeonameId);
      } else {
        // Para otros países, usar método genérico
        const response = await geonamesService.getCities(departmentGeonameId);
        data = response.filter(item => item.adminCode2) as AdministrativeArea[];
      }

      setProvinces(data);

      // Auto-seleccionar si hay un valor previo
      if (province && data.length > 0) {
        const foundProv = data.find(p => 
          p.name.toLowerCase() === province.toLowerCase() ||
          p.asciiName.toLowerCase() === province.toLowerCase()
        );
        if (foundProv) {
          setSelectedProvinceId(foundProv.geonameId);
        }
      }
    } catch (error: any) {
      toast.error(error.message || 'Error al cargar provincias');
      setProvinces([]);
    } finally {
      setLoadingProvinces(false);
    }
  };

  const loadDistricts = async (provinceGeonameId: number) => {
    setLoadingDistricts(true);
    try {
      let data: City[];

      // Para Perú, usar método específico
      if (countryCode === 'PE') {
        data = await geonamesService.getPeruDistricts(provinceGeonameId);
      } else {
        data = await geonamesService.getCities(provinceGeonameId);
      }

      setDistricts(data);
    } catch (error: any) {
      toast.error(error.message || 'Error al cargar distritos/ciudades');
      setDistricts([]);
    } finally {
      setLoadingDistricts(false);
    }
  };

  const handleCountryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedCountryCode = e.target.value;
    const selectedCountry = countries.find(c => c.countryCode === selectedCountryCode);

    if (selectedCountry) {
      onCountryChange(selectedCountryCode, selectedCountry.countryName);
    }

    // Reset otros valores
    setSelectedDepartmentId(null);
    setSelectedProvinceId(null);
    onDepartmentChange('');
    onProvinceChange('');
    onDistrictChange('');
  };

  const handleDepartmentChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedName = e.target.value;
    const selectedDept = departments.find(d => d.name === selectedName);

    if (selectedDept) {
      setSelectedDepartmentId(selectedDept.geonameId);
      onDepartmentChange(selectedName, selectedDept.geonameId);
    } else {
      setSelectedDepartmentId(null);
      onDepartmentChange('');
    }

    // Reset valores dependientes
    setSelectedProvinceId(null);
    onProvinceChange('');
    onDistrictChange('');
  };

  const handleProvinceChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedName = e.target.value;
    const selectedProv = provinces.find(p => p.name === selectedName);

    if (selectedProv) {
      setSelectedProvinceId(selectedProv.geonameId);
      onProvinceChange(selectedName, selectedProv.geonameId);
    } else {
      setSelectedProvinceId(null);
      onProvinceChange('');
    }

    // Reset valores dependientes
    onDistrictChange('');
  };

  const handleDistrictChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedName = e.target.value;
    onDistrictChange(selectedName);
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
      {/* País */}
      <div>
        <label className="block text-sm font-medium text-dm-text-primary mb-1">
          País
        </label>
        <div className="relative">
          <select
            value={countryCode || ''}
            onChange={handleCountryChange}
            disabled={disabled || loadingCountries}
            className={`mt-1 block w-full rounded-md shadow-sm p-2 border bg-dm-bg-primary text-dm-text-primary ${
              errors.country_code ? 'border-red-500' : 'border-dm-border-primary'
            } ${disabled ? 'bg-dm-bg-secondary' : ''}`}
          >
            <option value="">Seleccione un país</option>
            {countries.map((country) => (
              <option key={country.countryCode} value={country.countryCode}>
                {country.countryName}
              </option>
            ))}
          </select>
          {loadingCountries && (
            <div className="absolute right-2 top-3">
              <Spinner size="sm" />
            </div>
          )}
        </div>
        {errors.country_code && (
          <p className="mt-1 text-sm text-red-600">{errors.country_code}</p>
        )}
      </div>

      {/* Departamento/Estado */}
      <div>
        <label className="block text-sm font-medium text-dm-text-primary mb-1">
          {countryCode === 'PE' ? 'Departamento' : 'Estado/Región'}
        </label>
        <div className="relative">
          <select
            value={department || ''}
            onChange={handleDepartmentChange}
            disabled={disabled || loadingDepartments || !countryCode}
            className={`mt-1 block w-full rounded-md shadow-sm p-2 border bg-dm-bg-primary text-dm-text-primary ${
              errors.department ? 'border-red-500' : 'border-dm-border-primary'
            } ${disabled || !countryCode ? 'bg-dm-bg-secondary' : ''}`}
          >
            <option value="">
              {!countryCode 
                ? 'Primero seleccione un país' 
                : `Seleccione ${countryCode === 'PE' ? 'departamento' : 'estado/región'}`
              }
            </option>
            {departments.map((dept) => (
              <option key={dept.geonameId} value={dept.name}>
                {dept.name}
              </option>
            ))}
          </select>
          {loadingDepartments && (
            <div className="absolute right-2 top-3">
              <Spinner size="sm" />
            </div>
          )}
        </div>
        {errors.department && (
          <p className="mt-1 text-sm text-red-600">{errors.department}</p>
        )}
      </div>

      {/* Provincia */}
      <div>
        <label className="block text-sm font-medium text-dm-text-primary mb-1">
          Provincia
        </label>
        <div className="relative">
          <select
            value={province || ''}
            onChange={handleProvinceChange}
            disabled={disabled || loadingProvinces || !selectedDepartmentId}
            className={`mt-1 block w-full rounded-md shadow-sm p-2 border bg-dm-bg-primary text-dm-text-primary ${
              errors.province ? 'border-red-500' : 'border-dm-border-primary'
            } ${disabled || !selectedDepartmentId ? 'bg-dm-bg-secondary' : ''}`}
          >
            <option value="">
              {!selectedDepartmentId 
                ? 'Primero seleccione departamento/estado' 
                : 'Seleccione provincia'
              }
            </option>
            {provinces.map((prov) => (
              <option key={prov.geonameId} value={prov.name}>
                {prov.name}
              </option>
            ))}
          </select>
          {loadingProvinces && (
            <div className="absolute right-2 top-3">
              <Spinner size="sm" />
            </div>
          )}
        </div>
        {errors.province && (
          <p className="mt-1 text-sm text-red-600">{errors.province}</p>
        )}
      </div>

      {/* Distrito/Ciudad */}
      <div>
        <label className="block text-sm font-medium text-dm-text-primary mb-1">
          {countryCode === 'PE' ? 'Distrito' : 'Ciudad'}
        </label>
        <div className="relative">
          <select
            value={district || ''}
            onChange={handleDistrictChange}
            disabled={disabled || loadingDistricts || !selectedProvinceId}
            className={`mt-1 block w-full rounded-md shadow-sm p-2 border bg-dm-bg-primary text-dm-text-primary ${
              errors.district ? 'border-red-500' : 'border-dm-border-primary'
            } ${disabled || !selectedProvinceId ? 'bg-dm-bg-secondary' : ''}`}
          >
            <option value="">
              {!selectedProvinceId 
                ? 'Primero seleccione provincia' 
                : `Seleccione ${countryCode === 'PE' ? 'distrito' : 'ciudad'}`
              }
            </option>
            {districts.map((dist) => (
              <option key={dist.geonameId} value={dist.name}>
                {dist.name} 
                {dist.population > 0 && (
                  <span className="text-dm-text-muted"> ({dist.population.toLocaleString()} hab.)</span>
                )}
              </option>
            ))}
          </select>
          {loadingDistricts && (
            <div className="absolute right-2 top-3">
              <Spinner size="sm" />
            </div>
          )}
        </div>
        {errors.district && (
          <p className="mt-1 text-sm text-red-600">{errors.district}</p>
        )}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ChevronDownIcon, MagnifyingGlassIcon } from '@heroicons/react/24/outline';

interface Option {
  value: string | number;
  label: string;
}

interface SearchableSelectProps {
  value: string | number | null;
  onChange: (value: string | number | null) => void;
  options: Option[];
  placeholder: string;
  disabled?: boolean;
  className?: string;
  label?: string;
}

export const SearchableSelect: React.FC<SearchableSelectProps> = ({
  value,
  onChange,
  options,
  placeholder,
  disabled = false,
  className = '',
  label,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const filteredOptions = options.filter(option =>
    option.label.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const selectedOption = options.find(option => option.value === value);

  useEffect(() => {
    if (!isOpen) {
      setSearchTerm('');
      setHighlightedIndex(-1);
    }
  }, [isOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (!isOpen) {
      if (e.key === 'Enter' || e.key === 'ArrowDown') {
        setIsOpen(true);
      }
      return;
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setHighlightedIndex(prev =>
          prev < filteredOptions.length - 1 ? prev + 1 : 0
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setHighlightedIndex(prev =>
          prev > 0 ? prev - 1 : filteredOptions.length - 1
        );
        break;
      case 'Enter':
        e.preventDefault();
        if (highlightedIndex >= 0 && highlightedIndex < filteredOptions.length) {
          handleSelect(filteredOptions[highlightedIndex].value);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        break;
    }
  }, [isOpen, filteredOptions, highlightedIndex]);

  const handleSelect = (selectedValue: string | number) => {
    onChange(selectedValue);
    setIsOpen(false);
    setSearchTerm('');
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
    setHighlightedIndex(-1);
    if (!isOpen) {
      setIsOpen(true);
    }
  };

  const handleInputFocus = () => {
    setIsOpen(true);
  };

  const handleClearSelection = () => {
    onChange(null);
    setSearchTerm('');
  };

  return (
    <div className={`relative ${className}`} ref={containerRef}>
      {label && (
        <label className="block text-sm font-medium text-dm-text-secondary mb-1">
          {label}
        </label>
      )}

      <div className="relative">
        <div className="relative">
          <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-dm-text-muted pointer-events-none" />
          <input
            ref={inputRef}
            type="text"
            value={isOpen ? searchTerm : (selectedOption?.label || '')}
            onChange={handleInputChange}
            onFocus={handleInputFocus}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            disabled={disabled}
            className={`w-full pl-10 pr-10 py-2 border border-dm-border-primary rounded-md bg-dm-bg-primary text-dm-text-primary disabled:bg-dm-bg-secondary disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary ${
              disabled ? 'cursor-not-allowed' : 'cursor-text'
            }`}
          />
          {value && !disabled && (
            <button
              type="button"
              onClick={handleClearSelection}
              className="absolute right-8 top-1/2 transform -translate-y-1/2 text-dm-text-muted hover:text-dm-text-secondary"
            >
              ×
            </button>
          )}
          <button
            type="button"
            onClick={() => !disabled && setIsOpen(!isOpen)}
            className={`absolute right-2 top-1/2 transform -translate-y-1/2 text-dm-text-muted hover:text-dm-text-secondary ${
              disabled ? 'cursor-not-allowed' : 'cursor-pointer'
            }`}
            disabled={disabled}
          >
            <ChevronDownIcon
              className={`h-5 w-5 transition-transform ${isOpen ? 'rotate-180' : ''}`}
            />
          </button>
        </div>

        {isOpen && !disabled && (
          <div className="absolute z-50 w-full mt-1 bg-dm-bg-primary border border-dm-border-primary rounded-md shadow-lg max-h-60 overflow-auto">
            {filteredOptions.length === 0 ? (
              <div className="px-4 py-2 text-dm-text-muted text-sm">
                No se encontraron resultados
              </div>
            ) : (
              filteredOptions.map((option, index) => (
                <div
                  key={option.value}
                  onClick={() => handleSelect(option.value)}
                  className={`px-4 py-2 cursor-pointer hover:bg-dm-bg-accent ${
                    index === highlightedIndex ? 'bg-primary/10' : ''
                  } ${option.value === value ? 'bg-dm-bg-accent font-medium text-dm-text-accent' : 'text-dm-text-primary'}`}
                >
                  {option.label}
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </div>
  );
};

// src/components/common/SplitPaymentForm.tsx

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { SplitIcon, AlertCircle, CreditCard } from 'lucide-react';
import { 
  validateSplitPayment, 
  canEnableSplitPayment,
  requiresOperationCode as checkRequiresOperationCode 
} from '../../utils/splitPaymentValidation';
import { YapeAssistPanel } from './YapeAssistPanel';
import { useYapeAssist } from '../../hooks/useYapeAssist';

/**
 * Opciones estandar de metodos de pago
 */
export const PAYMENT_METHOD_OPTIONS = [
  { value: 'EFE', label: 'Efectivo' },
  { value: 'TRF', label: 'Transferencia Bancaria' },
  { value: 'YAP', label: 'Yape' },
  { value: 'PLN', label: 'Plin' },
  { value: 'DEP', label: 'Deposito en Cuenta' },
  { value: 'OTR', label: 'Otros' },
];

/**
 * Datos del pago dividido
 */
export interface SplitPaymentData {
  isSplitPayment: boolean;
  paymentMethod1: string;
  operationCode1: string;
  amount1: number;
  paymentMethod2: string;
  operationCode2: string;
  amount2: number;
  pagoYapeId?: string | null;
}

interface SplitPaymentFormProps {
  totalAmount: number;
  currencySymbol?: string;
  disabled?: boolean;
  onPaymentDataChange: (data: SplitPaymentData) => void;
  onValidationChange?: (isValid: boolean) => void;
  initialData?: Partial<SplitPaymentData>;
  variant?: 'default' | 'billing';
  customerName?: string;
}

/**
 * Componente reutilizable para manejo de pagos divididos
 * Permite seleccionar hasta 2 metodos de pago diferentes
 */
export const SplitPaymentForm: React.FC<SplitPaymentFormProps> = ({
  totalAmount,
  currencySymbol = 'S/',
  disabled = false,
  onPaymentDataChange,
  onValidationChange,
  initialData,
  variant = 'default',
  customerName = '',
}) => {
  const isBilling = variant === 'billing';

  const selectBillingClass =
    'w-full min-w-0 bg-dm-bg-secondary border border-dm-border-primary rounded-lg py-3 pl-4 pr-11 text-sm text-dm-text-primary appearance-none focus:ring-2 focus:ring-primary/20 focus:outline-none disabled:opacity-60 disabled:cursor-not-allowed';
  const selectDefaultClass =
    'w-full p-2 border border-dm-border-primary rounded-md bg-dm-bg-primary disabled:bg-dm-bg-secondary text-sm text-dm-text-primary';
  const selectClass = isBilling ? selectBillingClass : selectDefaultClass;

  const opInputBillingClass =
    'w-full py-2.5 px-4 bg-dm-bg-secondary border border-dm-border-primary rounded-lg text-sm text-dm-text-primary focus:ring-2 focus:ring-primary/20 focus:outline-none disabled:opacity-60';
  const opInputDefaultClass =
    'w-full p-2 border border-dm-border-primary rounded-md disabled:bg-dm-bg-secondary text-sm text-dm-text-primary';
  const opInputClass = isBilling ? opInputBillingClass : opInputDefaultClass;

  const amountNumClass = isBilling
    ? 'w-full py-2.5 pl-8 pr-4 bg-dm-bg-secondary border border-dm-border-primary rounded-lg text-sm text-dm-text-primary focus:ring-2 focus:ring-primary/20 focus:outline-none disabled:opacity-60'
    : 'w-full p-2 pl-8 border border-dm-border-primary rounded-md disabled:bg-dm-bg-secondary text-sm text-dm-text-primary';

  const splitPanel1Class = isBilling
    ? 'p-4 rounded-xl border border-sky-200 dark:border-sky-800 bg-sky-50/40 dark:bg-sky-950/30'
    : 'p-4 rounded-lg border bg-blue-50 dark:bg-blue-950/30 border-blue-200 dark:border-blue-800';
  const splitPanel2Class = isBilling
    ? 'p-4 rounded-xl border border-emerald-200 dark:border-emerald-800 bg-emerald-50/40 dark:bg-emerald-950/30'
    : 'p-4 rounded-lg border bg-green-50 dark:bg-green-950/30 border-green-200 dark:border-green-800';
  // Estado para activar/desactivar pago dividido
  const [isSplitPayment, setIsSplitPayment] = useState(initialData?.isSplitPayment ?? false);

  // Pago 1 (principal)
  const [paymentMethod1, setPaymentMethod1] = useState(initialData?.paymentMethod1 ?? 'EFE');
  const [operationCode1, setOperationCode1] = useState(initialData?.operationCode1 ?? '');
  const [amount1, setAmount1] = useState<number>(initialData?.amount1 ?? totalAmount);
  const [amount1Display, setAmount1Display] = useState<string>(String(initialData?.amount1 ?? totalAmount));

  // Pago 2 (secundario)
  const [paymentMethod2, setPaymentMethod2] = useState(initialData?.paymentMethod2 ?? 'YAP');
  const [operationCode2, setOperationCode2] = useState(initialData?.operationCode2 ?? '');
  const [amount2, setAmount2] = useState<number>(initialData?.amount2 ?? 0);
  const [amount2Display, setAmount2Display] = useState<string>(String(initialData?.amount2 ?? 0));

  // Calcular diferencia entre total y suma de pagos
  const totalPaid = amount1 + amount2;
  const difference = totalAmount - totalPaid;
  const isValidTotal = Math.abs(difference) < 0.01; // Tolerancia de 1 centavo

  // Verificar si se puede habilitar el pago dividido (necesita precio valido)
  const canEnable = canEnableSplitPayment(totalAmount);

  // Validar el pago actual
  const validation = useMemo(() => {
    return validateSplitPayment({
      isSplitPayment,
      paymentMethod1,
      operationCode1,
      amount1,
      paymentMethod2,
      operationCode2,
      amount2,
    }, totalAmount);
  }, [isSplitPayment, paymentMethod1, operationCode1, amount1, paymentMethod2, operationCode2, amount2, totalAmount]);

  const yapeAssist = useYapeAssist({
    enabled: !disabled && canEnable,
    customerName,
    isSplitPayment,
    paymentMethod1,
    paymentMethod2,
    amount1,
    amount2,
    totalAmount,
    operationCode1,
    operationCode2,
  });

  // Notificar estado de validacion al padre
  useEffect(() => {
    if (onValidationChange) {
      onValidationChange(validation.isValid);
    }
  }, [validation.isValid, onValidationChange]);

  // Notificar cambios al padre
  const notifyChange = useCallback(() => {
    onPaymentDataChange({
      isSplitPayment,
      paymentMethod1,
      operationCode1,
      amount1: isSplitPayment ? amount1 : totalAmount,
      paymentMethod2,
      operationCode2,
      amount2: isSplitPayment ? amount2 : 0,
      pagoYapeId: yapeAssist.selectedPagoId,
    });
  }, [isSplitPayment, paymentMethod1, operationCode1, amount1, paymentMethod2, operationCode2, amount2, totalAmount, onPaymentDataChange, yapeAssist.selectedPagoId]);

  useEffect(() => {
    notifyChange();
  }, [notifyChange]);

  // Actualizar amount1 cuando cambia el total y no es pago dividido
  useEffect(() => {
    if (!isSplitPayment) {
      setAmount1(totalAmount);
      setAmount1Display(String(totalAmount));
      setAmount2(0);
      setAmount2Display('0');
    }
  }, [totalAmount, isSplitPayment]);

  // Limpiar codigo de operacion cuando se cambia a efectivo
  useEffect(() => {
    if (paymentMethod1 === 'EFE') {
      setOperationCode1('');
    }
  }, [paymentMethod1]);

  useEffect(() => {
    if (paymentMethod2 === 'EFE') {
      setOperationCode2('');
    }
  }, [paymentMethod2]);

  // Monto minimo que debe quedar para el otro pago en pago dividido
  const MIN_SPLIT_AMOUNT = 1; // Minimo 1 sol para cada parte

  // Manejar cambio en monto 1 (ajusta automaticamente monto 2)
  const handleAmount1Change = (value: string) => {
    setAmount1Display(value);
    const numValue = parseFloat(value) || 0;
    // En pago dividido, el maximo es totalAmount - MIN_SPLIT_AMOUNT para dejar espacio al otro pago
    const maxValue = isSplitPayment ? totalAmount - MIN_SPLIT_AMOUNT : totalAmount;
    const clampedValue = Math.min(Math.max(0, numValue), Math.max(0, maxValue));
    setAmount1(clampedValue);
    const newAmount2 = Math.max(0, totalAmount - clampedValue);
    setAmount2(newAmount2);
    setAmount2Display(String(newAmount2));

    // Si el valor ingresado supera el maximo permitido, corregir el display
    if (numValue > maxValue && maxValue >= 0) {
      setAmount1Display(String(clampedValue));
    }
  };

  // Manejar cambio en monto 2 (ajusta automaticamente monto 1)
  const handleAmount2Change = (value: string) => {
    setAmount2Display(value);
    const numValue = parseFloat(value) || 0;
    // En pago dividido, el maximo es totalAmount - MIN_SPLIT_AMOUNT para dejar espacio al otro pago
    const maxValue = isSplitPayment ? totalAmount - MIN_SPLIT_AMOUNT : totalAmount;
    const clampedValue = Math.min(Math.max(0, numValue), Math.max(0, maxValue));
    setAmount2(clampedValue);
    const newAmount1 = Math.max(0, totalAmount - clampedValue);
    setAmount1(newAmount1);
    setAmount1Display(String(newAmount1));

    // Si el valor ingresado supera el maximo permitido, corregir el display
    if (numValue > maxValue && maxValue >= 0) {
      setAmount2Display(String(clampedValue));
    }
  };

  // Manejar focus en campo de monto (limpiar si es 0)
  const handleAmountFocus = (currentValue: number, setDisplay: (val: string) => void) => {
    if (currentValue === 0) {
      setDisplay('');
    }
  };

  // Prevenir cambio de valor con scroll del mouse en inputs numericos
  const handleWheel = (e: React.WheelEvent<HTMLInputElement>) => {
    e.currentTarget.blur();
  };

  // Manejar blur en campo de monto (restaurar valor si esta vacio)
  const handleAmount1Blur = () => {
    if (amount1Display === '') {
      setAmount1Display(String(amount1));
    }
  };

  const handleAmount2Blur = () => {
    if (amount2Display === '') {
      setAmount2Display(String(amount2));
    }
  };

  // Toggle pago dividido
  const handleToggleSplitPayment = () => {
    // No permitir activar si no hay precio valido
    if (!canEnable) {
      return;
    }

    if (!isSplitPayment) {
      // Activar pago dividido: dividir el total en 2
      const halfAmount = Math.floor(totalAmount / 2);
      const otherHalf = totalAmount - halfAmount;
      setAmount1(halfAmount);
      setAmount1Display(String(halfAmount));
      setAmount2(otherHalf);
      setAmount2Display(String(otherHalf));
    } else {
      // Desactivar pago dividido: todo al metodo 1
      setAmount1(totalAmount);
      setAmount1Display(String(totalAmount));
      setAmount2(0);
      setAmount2Display('0');
      setPaymentMethod2('YAP');
      setOperationCode2('');
    }
    setIsSplitPayment(!isSplitPayment);
  };

  // Verificar si un metodo requiere codigo de operacion
  const requiresOperationCode = (method: string) => {
    return checkRequiresOperationCode(method);
  };

  return (
    <div className="space-y-4">
      {/* Alerta si no hay precio valido */}
      {!canEnable && (
        <div
          className={`flex items-center bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-lg ${
            isBilling ? 'p-2.5' : 'p-3'
          }`}
        >
          <AlertCircle
            className={`text-amber-600 dark:text-amber-400 mr-2 flex-shrink-0 ${isBilling ? 'w-4 h-4' : 'w-5 h-5'}`}
          />
          <p className={isBilling ? 'text-xs text-amber-800 dark:text-amber-300' : 'text-sm text-amber-700 dark:text-amber-300'}>
            Seleccione un viaje con precio válido para configurar el pago
          </p>
        </div>
      )}

      {/* Pago Completo (solo visible cuando NO es pago dividido) */}
      {!isSplitPayment && (
        <div
          className={
            isBilling ? 'space-y-3' : 'p-4 rounded-lg border bg-dm-bg-secondary border-dm-border-secondary'
          }
        >
          <div className={isBilling ? 'space-y-3' : 'space-y-3'}>
            {/* Selector de metodo */}
            <div>
              {!isBilling && (
                <label className="block text-xs font-medium text-dm-text-secondary mb-1">
                  Método de Pago
                </label>
              )}
              <div className="relative isolate">
                <select
                  value={paymentMethod1}
                  onChange={(e) => setPaymentMethod1(e.target.value)}
                  disabled={disabled || !canEnable}
                  className={selectClass}
                >
                  {PAYMENT_METHOD_OPTIONS.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
                {isBilling && (
                  <span
                    className="pointer-events-none absolute inset-y-0 right-0 flex w-11 items-center justify-center rounded-r-lg border-l border-dm-border-primary/60 bg-dm-bg-secondary/95"
                    aria-hidden
                  >
                    <CreditCard className="h-4 w-4 shrink-0 text-dm-text-muted" />
                  </span>
                )}
              </div>
            </div>

            {/* Codigo de operacion (si aplica) */}
            {paymentMethod1 !== 'EFE' && (
              <div>
                <label className="block text-[11px] font-medium uppercase tracking-wider text-dm-text-muted mb-1 ml-0.5">
                  Código de operación {requiresOperationCode(paymentMethod1) ? '*' : '(opc.)'}
                </label>
                <input
                  type="text"
                  value={operationCode1}
                  onChange={(e) => {
                    if (e.target.value.length <= 20) {
                      setOperationCode1(e.target.value);
                    }
                  }}
                  placeholder="Ingrese el código..."
                  disabled={disabled}
                  className={opInputClass}
                  maxLength={20}
                />
                <div className="text-[10px] text-dm-text-muted mt-1">
                  {operationCode1.length}/20 caracteres
                </div>
              </div>
            )}
            {yapeAssist.hasDigital && (
              <YapeAssistPanel
                loading={yapeAssist.loading}
                montoDigital={yapeAssist.montoDigital}
                customerName={customerName}
                assist={yapeAssist.assist}
                codigoInfo={yapeAssist.codigoInfo}
                selectedPagoId={yapeAssist.selectedPagoId}
                onRefresh={yapeAssist.consultar}
                onSelectPago={yapeAssist.elegirPago}
              />
            )}
          </div>
        </div>
      )}

      {/* Toggle para activar pago dividido */}
      <div
        className={`flex items-center justify-between p-3 rounded-lg ${
          isBilling
            ? !canEnable
              ? 'bg-dm-bg-secondary/80 opacity-60'
              : isSplitPayment
                ? 'bg-blue-50/80 dark:bg-blue-950/30'
                : 'bg-dm-bg-secondary'
            : `border ${
                !canEnable
                  ? 'bg-dm-bg-secondary border-dm-border-secondary opacity-60'
                  : isSplitPayment
                    ? 'bg-blue-50 dark:bg-blue-950/30 border-blue-300 dark:border-blue-800'
                    : 'bg-dm-bg-secondary border-dm-border-secondary'
              }`
        }`}
      >
        <div className={`flex items-center ${isBilling ? 'gap-0' : 'space-x-2'}`}>
          {!isBilling && (
            <SplitIcon className={`w-5 h-5 ${isSplitPayment ? 'text-blue-600' : 'text-dm-text-secondary'}`} />
          )}
          <div className="flex flex-col">
            <p
              className={`${isBilling ? 'text-sm font-semibold text-dm-text-primary' : `text-sm font-medium ${isSplitPayment ? 'text-blue-700 dark:text-blue-300' : 'text-dm-text-secondary'}`}`}
            >
