// src/features/accounting/credit-notes/components/CreditNoteSidebar.tsx

import React, { useState } from 'react';
import { UseFormSetValue } from 'react-hook-form';
import { Button } from '../../../../components/common/Button';
import { Modal } from '../../../../components/common/Modal';
import { toast } from '@/utils/sileo-toast';

interface CreditNoteSidebarProps {
	creditNoteTypeCode: string;
	items: any[];
	setValue: UseFormSetValue<any>;
}

export const CreditNoteSidebar: React.FC<CreditNoteSidebarProps> = ({
	creditNoteTypeCode,
	items,
	setValue
}) => {
	const [discountMode, setDiscountMode] = useState<'field' | 'unit_price'>('field');
	const [globalDiscountAmount, setGlobalDiscountAmount] = useState<number>(0);
	const [decreaseAmount, setDecreaseAmount] = useState<number>(0);
	const [showDecreaseModal, setShowDecreaseModal] = useState(false);
	const [decreaseMode, setDecreaseMode] = useState<'global' | 'per_item'>('global');

	const applyDecreaseProportionally = () => {
		if (!Array.isArray(items) || items.length === 0) return;

		const totalOriginal = items.reduce((acc: number, it: any) => acc + (parseFloat(it.unit_price || 0) * (parseFloat(it.quantity || 0) || 1)), 0);
		if (decreaseAmount <= 0 || decreaseAmount > totalOriginal) {
			toast.error('El monto de disminución debe ser mayor a 0 y menor o igual al total original');
			return;
		}

		// Aplicar disminución proporcionalmente por item
		items.forEach((it: any, idx: number) => {
			const itemTotal = (parseFloat(it.unit_price || 0) * (parseFloat(it.quantity || 0) || 1));
			const proportion = itemTotal / totalOriginal;
			const reductionForItem = decreaseAmount * proportion;
			const reductionPerUnit = reductionForItem / (parseFloat(it.quantity || 0) || 1);
			const newUnitPrice = Math.max(0, (parseFloat(it.unit_price || 0) - reductionPerUnit));
			setValue(`items.${idx}.unit_price`, parseFloat(newUnitPrice.toFixed(10)));
			// recalcular price_with_tax
			setValue(`items.${idx}.price_with_tax`, parseFloat((newUnitPrice * 1.18).toFixed(10)));
		});

		toast.success('Disminución aplicada a los ítems');
	};

	const applyGlobalDiscount = () => {
		if (!Array.isArray(items) || items.length === 0) return;

		const totalOriginal = items.reduce((acc: number, it: any) => acc + (parseFloat(it.unit_price || 0) * (parseFloat(it.quantity || 0) || 1)), 0);
		if (globalDiscountAmount <= 0 || globalDiscountAmount > totalOriginal) {
			toast.error('El monto del descuento debe ser mayor a 0 y menor o igual al total original');
			return;
		}

		// Distribuir proporcionalmente
		items.forEach((it: any, idx: number) => {
			const itemTotal = (parseFloat(it.unit_price || 0) * (parseFloat(it.quantity || 0) || 1));
			const proportion = itemTotal / totalOriginal;
			const discountForItem = globalDiscountAmount * proportion;

			if (discountMode === 'field') {
				// poner discount como monto por ítem
				setValue(`items.${idx}.discount`, parseFloat(discountForItem.toFixed(10)));
			} else {
				// reducir unit_price proporcionalmente
				const reductionPerUnit = discountForItem / (parseFloat(it.quantity || 0) || 1);
				const newUnitPrice = Math.max(0, (parseFloat(it.unit_price || 0) - reductionPerUnit));
				setValue(`items.${idx}.unit_price`, parseFloat(newUnitPrice.toFixed(10)));
				setValue(`items.${idx}.price_with_tax`, parseFloat((newUnitPrice * 1.18).toFixed(10)));
			}
		});

		toast.success('Descuento global aplicado');
	};

	return (
		<>
			<div className="bg-dm-bg-primary rounded-lg shadow p-6">
				<h2 className="text-lg font-semibold text-dm-text-primary mb-4">Información Importante</h2>
				<div className="space-y-3 text-sm text-dm-text-secondary">
					<div className="bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 rounded-lg p-3">
						<p className="font-medium text-blue-800 dark:text-blue-300 mb-1">Información</p>
						<ul className="space-y-1 text-blue-700 dark:text-blue-300">
							<li>• Las notas de crédito reducen la deuda del cliente</li>
							<li>• Se enviarán automáticamente a SUNAT</li>
							<li>• Verificar todos los datos antes de crear</li>
							<li>• El documento afectado debe existir y estar válido</li>
						</ul>
					</div>

					{/* Ayuda específica para tipo 09 - Disminución en el valor */}
					{creditNoteTypeCode === '09' && (
						<div className="mt-4 bg-yellow-50 dark:bg-yellow-950/30 border border-yellow-200 dark:border-yellow-800/50 rounded-lg p-3">
							<p className="font-medium text-yellow-800 dark:text-yellow-300 mb-2">Disminución en el valor (Tipo 09)</p>
							<p className="text-sm text-yellow-700 dark:text-yellow-300 mb-2">Puedes aplicar una disminución global o editar por ítem en una ventana aparte.</p>
							<div className="flex items-center space-x-2">
								<input
									type="number"
									step="0.01"
									min="0"
									value={decreaseAmount}
									onChange={(e) => setDecreaseAmount(parseFloat(e.target.value || '0'))}
									className="w-full p-2 border border-yellow-300 rounded-md bg-dm-bg-primary"
									placeholder="S/ 0.00"
								/>
								<Button onClick={applyDecreaseProportionally} variant="outline">Aplicar</Button>
								<Button onClick={() => setShowDecreaseModal(true)}>Editar</Button>
							</div>
						</div>
					)}

					{/* Ayuda específica para tipo 04 - Descuento global */}
					{creditNoteTypeCode === '04' && (
						<div className="mt-4 bg-green-50 dark:bg-green-950/30 border border-green-200 dark:border-green-800/50 rounded-lg p-3">
							<p className="font-medium text-green-800 dark:text-green-300 mb-2">Descuento global (Tipo 04)</p>
							<p className="text-sm text-green-700 dark:text-green-300 mb-2">Ingrese el monto total de descuento y seleccione cómo aplicarlo.</p>
							<div className="space-y-2">
								<div className="flex items-center space-x-2">
									<select 
										value={discountMode} 
										onChange={(e) => setDiscountMode(e.target.value as any)} 
										className="p-2 border rounded-md"
									>
										<option value="field">Usar campo discount por ítem</option>
										<option value="unit_price">Modificar unit_price</option>
									</select>
								</div>
								<div className="flex items-center space-x-2">
									<input
										type="number"
										step="0.01"
										min="0"
										value={globalDiscountAmount}
										onChange={(e) => setGlobalDiscountAmount(parseFloat(e.target.value || '0'))}
										className="w-full p-2 border border-green-300 rounded-md bg-dm-bg-primary"
										placeholder="S/ 0.00"
									/>
									<Button onClick={applyGlobalDiscount} variant="outline">Aplicar</Button>
								</div>
							</div>
						</div>
					)}
				</div>
			</div>

			{/* Modal para editar disminución (tipo 09) */}
			<Modal isOpen={showDecreaseModal} onClose={() => setShowDecreaseModal(false)} title="Editar Disminución">
				<div className="space-y-4">
					<div>
						<label className="block text-sm font-medium text-dm-text-secondary mb-1">Modo de edición</label>
						<div className="flex space-x-2">
							<button
								type="button"
								onClick={() => setDecreaseMode('global')}
								className={`px-3 py-2 rounded-md border ${decreaseMode === 'global' ? 'bg-dm-bg-secondary border-dm-border-primary' : 'bg-dm-bg-primary border-dm-border-primary'}`}
							>
								Global
							</button>
							<button
								type="button"
								onClick={() => setDecreaseMode('per_item')}
								className={`px-3 py-2 rounded-md border ${decreaseMode === 'per_item' ? 'bg-dm-bg-secondary border-dm-border-primary' : 'bg-dm-bg-primary border-dm-border-primary'}`}
							>
								Por ítem
							</button>
						</div>
					</div>

					{decreaseMode === 'global' && (
						<div>
							<label className="block text-sm font-medium text-dm-text-secondary mb-1">Monto total a disminuir</label>
							<div className="flex space-x-2">
								<input
									type="number"
									step="0.01"
									min="0"
									value={decreaseAmount}
									onChange={(e) => setDecreaseAmount(parseFloat(e.target.value || '0'))}
									className="w-full p-2 border border-dm-border-primary rounded-md"
								/>
								<Button 
									onClick={() => { 
										applyDecreaseProportionally(); 
										setShowDecreaseModal(false); 
									}} 
									variant="outline"
								>
									Aplicar
								</Button>
							</div>
						</div>
					)}

					{decreaseMode === 'per_item' && (
						<div className="space-y-3 max-h-64 overflow-y-auto">
							{items && items.map((it: any, idx: number) => (
								<div key={idx} className="flex items-center space-x-2 border-b pb-2">
									<div className="flex-1">
										<div className="text-sm font-medium">{it.description || `Item ${idx + 1}`}</div>
										<div className="text-xs text-dm-text-muted">Cantidad: {it.quantity}</div>
									</div>
									<div className="w-36">
										<label className="text-xs text-dm-text-muted">Descuento</label>
										<input
											type="number"
											step="0.01"
											min="0"
											defaultValue={it.discount || 0}
											onChange={(e) => setValue(`items.${idx}.discount`, parseFloat(e.target.value || '0'))}
											className="w-full p-2 border border-dm-border-primary rounded-md"
										/>
									</div>
									<div className="w-36">
										<label className="text-xs text-dm-text-muted">Nuevo unit_price</label>
										<input
											type="number"
											step="0.01"
											min="0"
											defaultValue={it.unit_price}
											onChange={(e) => {
												const v = parseFloat(e.target.value || '0');
												setValue(`items.${idx}.unit_price`, v);
												setValue(`items.${idx}.price_with_tax`, parseFloat((v * 1.18).toFixed(10)));
											}}
											className="w-full p-2 border border-dm-border-primary rounded-md"
										/>
									</div>
								</div>
							))}

							<div className="flex justify-end pt-2 space-x-2">
								<Button onClick={() => setShowDecreaseModal(false)} variant="outline">Cerrar</Button>
								<Button onClick={() => { setShowDecreaseModal(false); toast.success('Cambios aplicados'); }}>
									Aplicar cambios
								</Button>
							</div>
						</div>
					)}
				</div>
			</Modal>
		</>
	);
};

// src/features/accounting/credit-notes/components/InvoiceSelector.tsx

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { /*MagnifyingGlassIcon*/ } from '@heroicons/react/24/outline';
import { Modal } from '../../../../components/common/Modal';
import { Button } from '../../../../components/common/Button';
import { useVoidableInvoices } from '../../hooks/useCreditNotes';
import { invoicesService } from '../../../../services/invoices.service';
import { toast } from '@/utils/sileo-toast';

interface InvoiceSelectorProps {
	companyId: number;
	selectedInvoiceDetail: any;
	onInvoiceSelect: (invoiceDetail: any) => void;
	disabled?: boolean;
	/**
	 * Si es true, al seleccionar una factura se cerrará el modal y se navegará
	 * automáticamente a `/accounting/credit-notes/annul` pasando el detalle
	 * de la factura en location.state as { affectedInvoice }
	 */
	redirectToAnnulOnSelect?: boolean;
}

export const InvoiceSelector: React.FC<InvoiceSelectorProps> = ({
	companyId,
	selectedInvoiceDetail,
	onInvoiceSelect,
	disabled = false
	, redirectToAnnulOnSelect = false
}) => {
	const [showModal, setShowModal] = useState(false);
	const [confirmInvoice, setConfirmInvoice] = useState<any | null>(null);
	const [search, setSearch] = useState('');
	const [loadingDetail, setLoadingDetail] = useState(false);
	const navigate = useNavigate();

	const { data: voidableInvoices = [], isLoading } = useVoidableInvoices(companyId);

	const selectInvoice = async (invoice: any) => {
		try {
			setLoadingDetail(true);
			const invoiceDetail = await invoicesService.getById(invoice.id);
			// Si se solicita redireccionar a la página de anulación, cerramos
			// el modal y navegamos enviando el detalle en location.state
			if (redirectToAnnulOnSelect) {
				// En lugar de navegar inmediatamente, mostramos un modal de confirmación
				setShowModal(false);
				setConfirmInvoice(invoiceDetail);
				return;
			}
			onInvoiceSelect(invoiceDetail);
			setShowModal(false);
			setSearch('');
			toast.success('Datos de la factura cargados correctamente');
		} catch (error) {
			console.error('Error al cargar detalle de factura:', error);
			toast.error('Error al cargar los datos de la factura');
		} finally {
			setLoadingDetail(false);
		}
	};

	const filteredInvoices = voidableInvoices.filter(invoice =>
		invoice.series.toLowerCase().includes(search.toLowerCase()) ||
		invoice.number.toString().includes(search) ||
		invoice.client_name.toLowerCase().includes(search.toLowerCase())
	);

	return (
		<>
			<div className="mb-4">
				<label className="block text-sm font-medium text-dm-text-secondary mb-1">Buscar Factura*</label>
				<div className="flex">
					<div onClick={() => !disabled && setShowModal(true)} className="flex-1 p-2 border border-dm-border-primary rounded-md bg-dm-bg-secondary cursor-pointer">
						{selectedInvoiceDetail ? (
							<div>
								<div className="font-medium">
									{selectedInvoiceDetail.series}-{String(selectedInvoiceDetail.number).padStart(8, '0')}
									<span className="ml-2 text-sm text-dm-text-muted">
										({selectedInvoiceDetail.document_type_code === '01' ? 'Factura' : 'Boleta'})
									</span>
								</div>
								<div className="text-sm text-dm-text-muted">
									{selectedInvoiceDetail.client?.name}  {new Intl.NumberFormat('es-PE', {
										style: 'currency',
										currency: 'PEN'
										}).format(selectedInvoiceDetail.total_payable)}
								</div>
							</div>
						) : (
							<div className="text-dm-text-muted">Seleccionar factura a afectar...</div>
						)}
					</div>
				</div>
			</div>

			{/* Información de la factura seleccionada */}
			{selectedInvoiceDetail && (
				<div className="mt-4 p-4 bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 rounded-lg">
					<h4 className="text-sm font-medium text-blue-800 dark:text-blue-300 mb-2">Información de la Factura</h4>
					<div className="grid grid-cols-2 gap-4 text-sm">
						<div>
							<span className="text-blue-700 dark:text-blue-300">Cliente:</span> {selectedInvoiceDetail.client?.name}
						</div>
						<div>
							<span className="text-blue-700 dark:text-blue-300">RUC/DNI:</span> {selectedInvoiceDetail.client?.doc_number}
						</div>
						<div>
							<span className="text-blue-700 dark:text-blue-300">Fecha:</span> {new Date(selectedInvoiceDetail.issue_date).toLocaleDateString('es-PE')}
						</div>
						<div>
							<span className="text-blue-700 dark:text-blue-300">Total:</span> {new Intl.NumberFormat('es-PE', {
								style: 'currency',
								currency: 'PEN'
							}).format(selectedInvoiceDetail.total_payable)}
						</div>
					</div>
				</div>
			)}

			{/* Modal de Selección */}
			<Modal
				isOpen={showModal}
				onClose={() => setShowModal(false)}
				title="Seleccionar Factura a Afectar"
			>
				<div className="space-y-4">
					<div>
						<input
							type="text"
							placeholder="Buscar por serie, número o cliente..."
							value={search}
							onChange={(e) => setSearch(e.target.value)}
							className="w-full p-2 border border-dm-border-primary rounded-md"
						/>
					</div>
					<div className="max-h-96 overflow-y-auto">
						{isLoading ? (
							<div className="text-center py-4">
								<div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-600 mx-auto"></div>
								<p className="mt-2 text-dm-text-secondary">Cargando facturas...</p>
							</div>
						) : (
							<div className="space-y-2">
								{filteredInvoices.map(invoice => (
									<div
										key={invoice.id}
										onClick={() => selectInvoice(invoice)}
										className="p-3 hover:bg-dm-bg-hover cursor-pointer border rounded-md transition-colors"
									>
										<div className="flex justify-between items-start">
											<div className="flex-1">
												<div className="font-medium">
													{invoice.series}-{String(invoice.number).padStart(8, '0')}
													<span className="ml-2 text-sm text-dm-text-muted">
														({invoice.document_type_code === '01' ? 'Factura' : 'Boleta'})
													</span>
												</div>
												<div className="text-sm text-dm-text-secondary mt-1">
													{invoice.client_name}
												</div>
												<div className="text-xs text-dm-text-muted mt-1">
													Emitida: {new Date(invoice.issue_date).toLocaleDateString('es-PE')}
												</div>
											</div>
											<div className="text-right">
												<div className="font-medium text-dm-text-primary">
													{new Intl.NumberFormat('es-PE', {
														style: 'currency',
														currency: 'PEN'
													}).format(parseFloat(invoice.total_payable))}
												</div>
											</div>
										</div>
										{loadingDetail && (
											<div className="mt-2 text-xs text-blue-600 dark:text-blue-400">Cargando detalles...</div>
										)}
									</div>
								))}
								{filteredInvoices.length === 0 && (
									<div className="text-center py-8 text-dm-text-muted">
										{voidableInvoices.length === 0 ? (
											<div>
												<div className="text-lg mb-2">📄</div>
												<div>No hay facturas disponibles para anular</div>
											</div>
										) : (
											<div>No se encontraron facturas que coincidan con la búsqueda</div>
										)}
									</div>
								)}
							</div>
						)}
					</div>

					<div className="bg-yellow-50 dark:bg-yellow-950/30 border border-yellow-200 dark:border-yellow-800/50 rounded-lg p-3">
						<div className="text-sm text-yellow-800 dark:text-yellow-300">
							<strong>Nota:</strong> Solo se muestran facturas que pueden ser afectadas por notas de crédito.
							Al seleccionar una factura, se cargarán automáticamente todos sus datos y productos.
						</div>
					</div>
				</div>
			</Modal>

			{/* Modal de confirmación: muestra detalle y botón para anular (cuando redirectToAnnulOnSelect=true) */}
			<Modal
				isOpen={!!confirmInvoice}
				onClose={() => setConfirmInvoice(null)}
				title="Confirmar anulación">
				{confirmInvoice && (
					<div className="space-y-4">
						<div>
							<div className="font-medium">{confirmInvoice.series}-{String(confirmInvoice.number).padStart(8, '0')}</div>
							<div className="text-sm text-dm-text-secondary">Cliente: {confirmInvoice.client?.name}</div>
							<div className="text-sm text-dm-text-secondary">Doc: {confirmInvoice.client?.doc_number || confirmInvoice.client?.document_number || confirmInvoice.client?.doc || ''}</div>
							{(confirmInvoice.client?.address || confirmInvoice.client_address) && (
								<div className="text-sm text-dm-text-secondary">Dirección: {confirmInvoice.client?.address || confirmInvoice.client_address}</div>
							)}
							<div className="text-sm text-dm-text-secondary">Total: {new Intl.NumberFormat('es-PE',{style: 'currency', currency: 'PEN'}).format(confirmInvoice.total_payable)}</div>
						</div>

						{/* Resumen breve de items/servicios */}
						{confirmInvoice.items && confirmInvoice.items.length > 0 && (
							<div className="mt-2 border-t pt-2">
								<div className="text-sm font-medium text-dm-text-secondary mb-1">Servicios / Ítems incluidos</div>
								<ul className="text-sm text-dm-text-secondary list-disc pl-5 space-y-1">
									{confirmInvoice.items.slice(0,5).map((it: any, idx: number) => (
										<li key={idx}>{it.item_description || it.product_name || it.description || 'Servicio'} — {it.quantity || it.qty || ''} x {new Intl.NumberFormat('es-PE',{style: 'currency', currency: 'PEN'}).format(it.unit_price || it.price_with_tax || 0)}</li>
									))}
									{confirmInvoice.items.length > 5 && <li className="text-xs text-dm-text-muted">+{confirmInvoice.items.length - 5} más</li>}
								</ul>
							</div>
						)}

						<div className="flex justify-end space-x-3 pt-4 border-t">
							<Button variant="outline" onClick={() => setConfirmInvoice(null)}>Cancelar</Button>
							<Button onClick={() => { setConfirmInvoice(null); navigate('/accounting/credit-notes/annul', { state: { affectedInvoice: confirmInvoice, simplifiedAnnul: true } }); }}>
								Anular
							</Button>
						</div>
					</div>
				)}
			</Modal>
		</>
	);
};

// src/features/accounting/credit-notes/pages/CreditNoteAnnulFormPage.tsx

import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useForm, Controller, SubmitHandler } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { toast } from '@/utils/sileo-toast';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import {
  ExclamationTriangleIcon,
  ArrowLeftIcon,
  DocumentTextIcon,
  UserIcon,
  MapPinIcon,
  BanknotesIcon,
  ClipboardDocumentListIcon,
  ChevronRightIcon,
} from '@heroicons/react/24/outline';

import { Button } from '../../../../components/common/Button';
import { Spinner } from '../../../../components/common/Spinner';
import { useCreateCreditNoteByAnnulment } from '../hooks/useCreditNotes';
import { CreditNoteAnnulData } from '../../types';
import { Invoice, User } from '../../../../types';
import { useAccountingDocumentSeriesForBranch } from '../../../../hooks/useAccountingDocumentSeries';
import { authService } from '../../../../services/auth.service';
import RequestCancellationModal from '../../components/RequestCancellationModal';

const CREDIT_NOTE_REASONS = [
  { code: '01', description: 'Anulación de la operación' },
];

const creditNoteSchema = z.object({
  credit_note_type_code: z.string().nonempty('Debe seleccionar un motivo.'),
  reason: z.string().min(10, 'El sustento debe tener al menos 10 caracteres.'),
});

type CreditNoteFormData = z.infer<typeof creditNoteSchema>;

export const CreditNoteAnnulFormPage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { affectedInvoice, simplifiedAnnul, isDebitNote } = (location.state as {
    affectedInvoice: Invoice;
    simplifiedAnnul?: boolean;
    isDebitNote?: boolean;
  }) || {};

  const [selectedCreditNoteSeries, setSelectedCreditNoteSeries] = useState<string>('');
  const [showRequestModal, setShowRequestModal] = useState(false);

  const { mutate: createCreditNote, isPending } = useCreateCreditNoteByAnnulment();
  const queryClient = useQueryClient();

  const { data: currentUser } = useQuery<User>({
    queryKey: ['currentUser'],
    queryFn: async (): Promise<User> => {
      const data = await authService.getProfile();
      return data;
    },
    staleTime: 1000 * 60 * 5,
    retry: 1,
  });

  const { availableCreditNoteSeries, isLoading: isLoadingSeries } =
    useAccountingDocumentSeriesForBranch(
      currentUser?.default_branch_office_id || null,
      currentUser?.company_id || 1
    );

  const {
    control,
    handleSubmit,
    formState: { errors },
  } = useForm<CreditNoteFormData>({
    resolver: zodResolver(creditNoteSchema),
    defaultValues: {
      credit_note_type_code: '01',
      reason: '',
    },
  });

  useEffect(() => {
    const cachedSeries = localStorage.getItem('lastUsedCreditNoteSeries');
    if (availableCreditNoteSeries.length > 0) {
      if (
        cachedSeries &&
        availableCreditNoteSeries.some((s) => s.series_code === cachedSeries)
      ) {
        setSelectedCreditNoteSeries(cachedSeries);
      } else {
        setSelectedCreditNoteSeries(availableCreditNoteSeries[0].series_code);
      }
    }
  }, [availableCreditNoteSeries]);

  const handleCreditNoteSeriesChange = (seriesCode: string) => {
    setSelectedCreditNoteSeries(seriesCode);
    localStorage.setItem('lastUsedCreditNoteSeries', seriesCode);
  };

  if (!affectedInvoice || !affectedInvoice.client) {
    React.useEffect(() => {
      toast.error(
        `No se ha especificado ${isDebitNote ? 'una nota de débito' : 'una factura'} válida para anular.`
      );
      navigate('/accounting/credit-notes/new');
    }, [navigate]);
    return null;
  }

  const handleSimplifiedAnnul = () => {
    if (!selectedCreditNoteSeries) {
      toast.error('No hay serie de nota de crédito seleccionada.');
      return;
    }

    const payload: CreditNoteAnnulData = {
      invoice_id: affectedInvoice.id,
      credit_note_series: selectedCreditNoteSeries,
      reason: 'Anulación simplificada',
    };

    createCreditNote(payload, {
      onSuccess: async () => {
        await queryClient.invalidateQueries({ queryKey: ['creditNotes'] });
        navigate('/accounting/credit-notes');
      },
      onError: (error: any) => {
        if (error?.response?.status === 403) {
          const errorDetail = error?.response?.data?.detail || '';
          if (
            errorDetail.includes('Viaje ya salió') ||
            errorDetail.includes('Solicita aprobación')
          ) {
            setShowRequestModal(true);
          } else {
            toast.error(errorDetail || 'No tienes permisos para realizar esta acción');
          }
        }
      },
    });
  };

  const onSubmit: SubmitHandler<CreditNoteFormData> = (data) => {
    if (!selectedCreditNoteSeries) {
      toast.error('Debe seleccionar una serie para la nota de crédito');
      return;
    }

    const payload: CreditNoteAnnulData = {
      invoice_id: affectedInvoice.id,
      credit_note_series: selectedCreditNoteSeries,
      reason: data.reason,
    };

    createCreditNote(payload, {
      onSuccess: async () => {
        await queryClient.invalidateQueries({ queryKey: ['creditNotes'] });
        navigate('/accounting/credit-notes');
      },
      onError: (error: any) => {
        if (error?.response?.status === 403) {
          const errorDetail = error?.response?.data?.detail || '';
          if (
            errorDetail.includes('Viaje ya salió') ||
            errorDetail.includes('Solicita aprobación')
          ) {
            setShowRequestModal(true);
          } else {
            toast.error(errorDetail || 'No tienes permisos para realizar esta acción');
          }
        }
      },
    });
  };

  // ── Componentes auxiliares de UI ──

  const Breadcrumb = () => (
    <button
      onClick={() => navigate(-1)}
      className="inline-flex items-center gap-1.5 text-[13px] text-dm-text-muted hover:text-dm-text-primary transition-colors mb-6"
    >
      <ArrowLeftIcon className="w-4 h-4" />
      <span>Volver</span>
    </button>
  );

  const SunatAlert = () => (
    <div className="rounded-[12px] border border-dm-border-primary bg-dm-bg-secondary p-5">
      <div className="flex items-start gap-3.5">
        <div className="flex-shrink-0 w-8 h-8 rounded-[8px] bg-amber-50 dark:bg-amber-950/30 flex items-center justify-center">
          <ExclamationTriangleIcon className="w-4.5 h-4.5 text-amber-600 dark:text-amber-400" />
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="text-[13px] font-semibold text-dm-text-primary">
            Requisito importante de SUNAT
          </h3>
          <div className="mt-1.5 text-[13px] text-dm-text-secondary leading-relaxed space-y-1">
            <p>
              Según normativa SUNAT,{' '}
              <span className="font-semibold text-dm-text-primary">
                la serie de la nota de crédito debe ser la misma que la serie del comprobante que afecta
              </span>
              .
            </p>
            <p>
              Ejemplo: si el comprobante es{' '}
              <code className="text-[12px] font-medium text-dm-text-primary bg-dm-bg-primary px-1.5 py-0.5 rounded border border-dm-border-primary">
                B004-00000123
              </code>
              , la serie de la nota de crédito debe ser{' '}
              <code className="text-[12px] font-medium text-dm-text-primary bg-dm-bg-primary px-1.5 py-0.5 rounded border border-dm-border-primary">
                B004
              </code>
              .
            </p>
            <p className="text-[12px] text-dm-text-muted">
              Verifique que la serie seleccionada coincida con la del comprobante a afectar.
            </p>
          </div>
        </div>
      </div>
    </div>
  );

  const DocumentCard = () => {
    const client = affectedInvoice.client!;
    const items = affectedInvoice.items || [];
    const displayItems = items.slice(0, 5);
    const remaining = items.length - 5;

    return (
      <div className="rounded-[12px] border border-dm-border-primary bg-dm-bg-primary overflow-hidden">
        {/* Header del comprobante */}
        <div className="px-6 py-5 border-b border-dm-border-primary">
          <div className="flex items-center gap-2 mb-1">
            <DocumentTextIcon className="w-4 h-4 text-[#1F4690]" />
            <span className="text-[12px] font-semibold text-[#1F4690] uppercase tracking-wider">
              {isDebitNote ? 'Nota de Débito' : 'Comprobante'} a anular
            </span>
          </div>
          <h1 className="text-[22px] font-semibold text-dm-text-primary tracking-tight">
            {affectedInvoice.series}-{String(affectedInvoice.number).padStart(8, '0')}
          </h1>
        </div>

        {/* Datos del cliente */}
        <div className="px-6 py-5 space-y-3">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-[8px] bg-dm-bg-secondary flex items-center justify-center flex-shrink-0">
              <UserIcon className="w-4 h-4 text-dm-text-muted" />
            </div>
            <div className="min-w-0">
              <p className="text-[12px] text-dm-text-muted">Cliente</p>
              <p className="text-[14px] font-medium text-dm-text-primary truncate">
                {client.name}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-[8px] bg-dm-bg-secondary flex items-center justify-center flex-shrink-0">
              <DocumentTextIcon className="w-4 h-4 text-dm-text-muted" />
            </div>
            <div>
              <p className="text-[12px] text-dm-text-muted">Documento</p>
              <p className="text-[14px] font-medium text-dm-text-primary">
                {client.doc_type} - {client.doc_number}
              </p>
            </div>
          </div>

          {(client.address_line || client.address) && (
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-[8px] bg-dm-bg-secondary flex items-center justify-center flex-shrink-0">
                <MapPinIcon className="w-4 h-4 text-dm-text-muted" />
              </div>
              <div className="min-w-0">
                <p className="text-[12px] text-dm-text-muted">Dirección</p>
                <p className="text-[14px] font-medium text-dm-text-primary truncate">
                  {client.address_line ?? client.address}
                </p>
              </div>
            </div>
          )}

          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-[8px] bg-dm-bg-secondary flex items-center justify-center flex-shrink-0">
              <BanknotesIcon className="w-4 h-4 text-dm-text-muted" />
            </div>
            <div>
              <p className="text-[12px] text-dm-text-muted">Total</p>
              <p className="text-[14px] font-semibold text-dm-text-primary">
                S/ {affectedInvoice.total_payable}
              </p>
            </div>
          </div>
        </div>

        {/* Servicios */}
        {items.length > 0 && (
          <div className="px-6 py-5 border-t border-dm-border-primary bg-dm-bg-secondary/50">
            <div className="flex items-center gap-2 mb-3">
              <ClipboardDocumentListIcon className="w-4 h-4 text-dm-text-muted" />
              <span className="text-[12px] font-semibold text-dm-text-secondary uppercase tracking-wider">
                Servicios incluidos
              </span>
            </div>
            <ul className="space-y-2">
              {displayItems.map((it) => (
                <li
                  key={it.id}
                  className="flex items-center justify-between text-[13px]"
                >
                  <span className="text-dm-text-secondary truncate pr-4">
                    {it.item_description ?? it.product?.name ?? 'Ítem'} x{it.quantity}
                  </span>
                  <span className="font-medium text-dm-text-primary whitespace-nowrap">
                    S/ {it.total_line}
                  </span>
                </li>
              ))}
              {remaining > 0 && (
                <li className="text-[12px] text-dm-text-muted pt-1">
                  +{remaining} servicios adicionales
                </li>
              )}
            </ul>
          </div>
        )}
      </div>
    );
  };

  const SeriesSelector = () => (
    <div>
      <label className="block text-[13px] font-medium text-dm-text-primary mb-2">
        Serie de la Nota de Crédito
        <span className="text-red-500 dark:text-red-400 ml-0.5">*</span>
      </label>
      {isLoadingSeries ? (
        <div className="flex items-center gap-2 w-full px-4 py-3 rounded-[12px] border border-dm-border-primary bg-dm-bg-secondary text-[13px] text-dm-text-muted">
          <Spinner size="sm" color="text-dm-text-muted" />
          <span>Cargando series...</span>
        </div>
      ) : availableCreditNoteSeries.length > 0 ? (
        <div className="relative">
          <select
            value={selectedCreditNoteSeries}
            onChange={(e) => handleCreditNoteSeriesChange(e.target.value)}
            className="w-full appearance-none px-4 py-3 pr-10 text-[14px] text-dm-text-primary bg-dm-bg-primary border border-dm-border-primary rounded-[12px] focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-colors"
          >
            {availableCreditNoteSeries.map((series) => (
              <option key={series.id} value={series.series_code}>
                {series.series_code} - Nota de Crédito
              </option>
            ))}
          </select>
          <ChevronRightIcon className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-dm-text-muted rotate-90 pointer-events-none" />
        </div>
      ) : (
        <div className="flex items-center gap-2 w-full px-4 py-3 rounded-[12px] border border-red-200 dark:border-red-800/50 bg-red-50 dark:bg-red-950/50 text-[13px] text-red-700 dark:text-red-300">
          <ExclamationTriangleIcon className="w-4 h-4 flex-shrink-0" />
          <span>No hay series de notas de crédito disponibles para esta sucursal</span>
        </div>
      )}
    </div>
  );

  const FormFooter = ({
    children,
  }: {
    children: React.ReactNode;
  }) => (
    <div className="flex items-center justify-end gap-3 pt-6 border-t border-dm-border-primary">
      {children}
    </div>
  );

  // ── Vista simplificada ──
  if (simplifiedAnnul) {
    return (
      <div className="min-h-screen bg-dm-bg-secondary p-6 lg:p-10">
        <div className="max-w-6xl mx-auto">
          <Breadcrumb />
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-5 items-start">
            {/* Columna izquierda: info del comprobante */}
            <div className="space-y-5">
              <SunatAlert />
              <DocumentCard />
            </div>

            {/* Columna derecha: acción de anulación */}
            <div className="rounded-[12px] border border-dm-border-primary bg-dm-bg-primary p-6 space-y-6">
              <div>
                <h2 className="text-[15px] font-semibold text-dm-text-primary mb-1">
                  Anulación simplificada
                </h2>
                <p className="text-[13px] text-dm-text-muted">
                  Selecciona la serie y confirma para generar la nota de crédito.
                </p>
              </div>

              <SeriesSelector />

              <FormFooter>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => navigate(-1)}
                  className="rounded-full px-5"
                >
                  Cancelar
                </Button>
                <Button
                  variant="primary"
                  onClick={handleSimplifiedAnnul}
                  isLoading={isPending}
                  disabled={!selectedCreditNoteSeries}
                  className="rounded-full px-6"
                >
                  Confirmar anulación
                </Button>
              </FormFooter>
            </div>
          </div>
        </div>

        {showRequestModal && (
          <RequestCancellationModal
            invoiceId={affectedInvoice.id}
            invoiceSeries={affectedInvoice.series}
            invoiceNumber={affectedInvoice.number}
            onClose={() => setShowRequestModal(false)}
            onSuccess={() => navigate('/accounting/invoices')}
          />
        )}
      </div>
    );
  }

  // ── Vista completa con formulario ──
  return (
    <div className="min-h-screen bg-dm-bg-secondary p-6 lg:p-10">
      <div className="max-w-6xl mx-auto">
        <Breadcrumb />
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5 items-start">
          {/* Columna izquierda: info del comprobante */}
          <div className="space-y-5">
            <SunatAlert />
            <DocumentCard />
          </div>

          {/* Columna derecha: formulario */}
          <form
            onSubmit={handleSubmit(onSubmit)}
            className="rounded-[12px] border border-dm-border-primary bg-dm-bg-primary p-6 space-y-6"
          >
            <div>
              <h2 className="text-[15px] font-semibold text-dm-text-primary mb-1">
                Generar Nota de Crédito
              </h2>
              <p className="text-[13px] text-dm-text-muted">
                Complete los datos para registrar la anulación ante SUNAT.
              </p>
            </div>

            <SeriesSelector />

            <div>
              <label className="block text-[13px] font-medium text-dm-text-primary mb-2">
                Motivo de la Nota de Crédito
                <span className="text-red-500 dark:text-red-400 ml-0.5">*</span>
              </label>
              <Controller
                name="credit_note_type_code"
                control={control}
                render={({ field }) => (
                  <div className="relative">
                    <select
                      {...field}
                      className="w-full appearance-none px-4 py-3 pr-10 text-[14px] text-dm-text-primary bg-dm-bg-primary border border-dm-border-primary rounded-[12px] focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-colors"
                    >
                      {CREDIT_NOTE_REASONS.map((reason) => (
                        <option key={reason.code} value={reason.code}>
                          {reason.description}
                        </option>
                      ))}
                    </select>
                    <ChevronRightIcon className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-dm-text-muted rotate-90 pointer-events-none" />
                  </div>
                )}
              />
              {errors.credit_note_type_code && (
                <p className="text-[12px] text-red-600 dark:text-red-400 mt-1.5">
                  {errors.credit_note_type_code.message}
                </p>
              )}
            </div>

            <div>
              <label className="block text-[13px] font-medium text-dm-text-primary mb-2">
                Descripción / Sustento
                <span className="text-red-500 dark:text-red-400 ml-0.5">*</span>
              </label>
              <Controller
                name="reason"
                control={control}
                render={({ field }) => (
                  <textarea
                    {...field}
                    rows={4}
                    className="w-full px-4 py-3 text-[14px] text-dm-text-primary bg-dm-bg-primary border border-dm-border-primary rounded-[12px] placeholder:text-dm-text-muted focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-colors resize-none"
                    placeholder="Ej: El cliente desistió de la compra y solicitó la devolución del dinero."
                  />
                )}
              />
              {errors.reason && (
                <p className="text-[12px] text-red-600 dark:text-red-400 mt-1.5">
                  {errors.reason.message}
                </p>
              )}
            </div>

            <FormFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => navigate(-1)}
                className="rounded-full px-5"
              >
                Cancelar
              </Button>
              <Button
                type="submit"
                isLoading={isPending}
                disabled={!selectedCreditNoteSeries || availableCreditNoteSeries.length === 0}
                className="rounded-full px-6"
              >
                Generar Nota de Crédito
              </Button>
            </FormFooter>
          </form>
        </div>
      </div>

      {showRequestModal && (
        <RequestCancellationModal
          invoiceId={affectedInvoice.id}
          invoiceSeries={affectedInvoice.series}
          invoiceNumber={affectedInvoice.number}
          onClose={() => setShowRequestModal(false)}
          onSuccess={() => navigate('/accounting/invoices')}
        />
      )}
    </div>
  );
};

// src/features/accounting/credit-notes/pages/CreditNoteDetailPage.tsx

import React, { useState, useRef, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import {
  ArrowLeftIcon,
  DocumentArrowDownIcon,
  ArrowPathIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
  PrinterIcon,
  ArrowDownTrayIcon,
  ExclamationTriangleIcon,
} from '@heroicons/react/24/outline';
import { Button } from '../../../../components/common/Button';
import { toast } from '@/utils/sileo-toast';
import {
  useCreditNote,
  useCreditNoteSunatStatus,
  useGenerateCreditNotePdf,
} from '../hooks/useCreditNotes';

type PdfFormatTab = 'ticket80mm' | 'a4';

export const CreditNoteDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [ncPdfTab, setNcPdfTab] = useState<PdfFormatTab>('ticket80mm');
  const [affectedPdfTab, setAffectedPdfTab] = useState<PdfFormatTab>('ticket80mm');
  const [showPdfError, setShowPdfError] = useState(false);
  const pdfIframeRef = useRef<HTMLIFrameElement>(null);

  const creditNoteId = id ? parseInt(id, 10) : null;
  const { data: creditNote, isLoading, dataUpdatedAt } = useCreditNote(creditNoteId);
  const { data: sunatStatus, isLoading: isLoadingStatus } = useCreditNoteSunatStatus(creditNoteId);
  const { mutate: generateCreditNotePdf, isPending: isGeneratingPdf } = useGenerateCreditNotePdf();

  useEffect(() => {
    if (!creditNote) return;
    const t = Boolean(creditNote.pdf_ticket_file_path?.trim());
    const a4 = Boolean(creditNote.pdf_a4_file_path?.trim());
    if (t && !a4) setNcPdfTab('ticket80mm');
    else if (!t && a4) setNcPdfTab('a4');
  }, [creditNote?.pdf_ticket_file_path, creditNote?.pdf_a4_file_path]);

  useEffect(() => {
    if (!creditNote) return;
    const inv = (creditNote as any).affected_invoice;
    if (!inv) return;
    const t = Boolean(inv.pdf_ticket_file_path?.trim());
    const a4 = Boolean(inv.pdf_a4_file_path?.trim());
    if (t && !a4) setAffectedPdfTab('ticket80mm');
    else if (!t && a4) setAffectedPdfTab('a4');
  }, [
    (creditNote as any)?.affected_invoice?.pdf_ticket_file_path,
    (creditNote as any)?.affected_invoice?.pdf_a4_file_path,
  ]);

  const getSunatStatusIcon = (status: string) => {
    switch (status) {
      case 'ACCEPTED':
        return <CheckCircleIcon className="h-6 w-6 text-green-600 dark:text-green-400" />;
      case 'REJECTED':
        return <XCircleIcon className="h-6 w-6 text-red-600 dark:text-red-400" />;
      case 'PENDING':
      case 'SENT':
        return <ClockIcon className="h-6 w-6 text-yellow-600 dark:text-yellow-400" />;
      default:
        return <XCircleIcon className="h-6 w-6 text-dm-text-secondary" />;
    }
  };

  const getSunatStatusColor = (status: string) => {
    const colors = {
      PENDING: 'bg-yellow-50 dark:bg-yellow-950/30 border-yellow-200 dark:border-yellow-800 text-yellow-800 dark:text-yellow-300',
      SENT: 'bg-blue-50 dark:bg-blue-950/30 border-blue-200 dark:border-blue-800/50 text-blue-800 dark:text-blue-300',
      ACCEPTED: 'bg-green-50 dark:bg-green-950/30 border-green-200 dark:border-green-800/50 text-green-800 dark:text-green-300',
      REJECTED: 'bg-red-50 dark:bg-red-950/30 border-red-200 dark:border-red-800/50 text-red-800 dark:text-red-300',
      ERROR: 'bg-dm-bg-secondary border-dm-border-primary text-dm-text-primary',
    };
    return colors[status as keyof typeof colors] || colors.ERROR;
  };

  const getStatusMessage = (status: string) => {
    const messages = {
      PENDING: 'El documento está pendiente de envío a SUNAT',
      SENT: 'El documento ha sido enviado a SUNAT y está siendo procesado',
      ACCEPTED: 'El documento ha sido aceptado por SUNAT',
      REJECTED: 'El documento ha sido rechazado por SUNAT',
      ERROR: 'Ha ocurrido un error en el procesamiento',
    };
    return messages[status as keyof typeof messages] || 'Estado desconocido';
  };

  // Resolver estado SUNAT usando posibles formas de respuesta del backend
  const resolvedSunatStatus =
    (sunatStatus as any)?.sunat_status ??
    (sunatStatus as any)?.state?.data?.sunat_status ??
    creditNote?.sunat_status;

  const resolvedSunatResponseDescription =
    (sunatStatus as any)?.sunat_response_description ??
    (sunatStatus as any)?.state?.data?.sunat_response_description ??
    creditNote?.sunat_response_description;

  const resolvedSunatTicket =
    (sunatStatus as any)?.sunat_ticket ??
    (sunatStatus as any)?.state?.data?.sunat_ticket;

  const formatCurrency = (amount: number | string) => {
    const numAmount = typeof amount === 'string' ? parseFloat(amount) : amount;
    return new Intl.NumberFormat('es-PE', {
      style: 'currency',
      currency: 'PEN'
    }).format(numAmount);
  };

  const formatDate = (dateString: string) => {
    // Manejar fechas en formato YYYY-MM-DD sin zona horaria creando fecha en local
    const dateOnlyMatch = String(dateString).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    const dateObj = dateOnlyMatch
      ? new Date(Number(dateOnlyMatch[1]), Number(dateOnlyMatch[2]) - 1, Number(dateOnlyMatch[3]))
      : new Date(dateString);

    return dateObj.toLocaleDateString('es-PE', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  };

  const formatDateTime = (dateString: string) => {
    // Si sólo viene YYYY-MM-DD, tratar como midnight local
    const dateOnlyMatch = String(dateString).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    const dateObj = dateOnlyMatch
      ? new Date(Number(dateOnlyMatch[1]), Number(dateOnlyMatch[2]) - 1, Number(dateOnlyMatch[3]))
      : new Date(dateString);

    return dateObj.toLocaleString('es-PE', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const handlePrint = () => {
    if (pdfIframeRef.current) {
      try {
        const iframeWindow = pdfIframeRef.current.contentWindow;
        if (iframeWindow) {
          iframeWindow.print();
        } else {
          throw new Error('No se puede acceder al contenido del iframe');
        }
      } catch (error) {
        console.warn('Error al imprimir desde iframe:', error);
        const pdfUrl = ncPdfTab === 'ticket80mm' ? creditNote?.pdf_ticket_file_path : creditNote?.pdf_a4_file_path;
        const printWindow = window.open(pdfUrl, '_blank', 'width=800,height=600');
        if (printWindow) {
          printWindow.onload = () => {
            try {
              printWindow.print();
            } catch (fallbackError) {
              toast.info('Haz clic en "Imprimir" en la ventana que se abrió');
            }
          };
        } else {
          toast.error('El navegador bloqueó la ventana emergente');
        }
      }
    } else {
      toast.error('El visor PDF no está disponible');
    }
  };

  const handleDownload = () => {
    const pdfUrl = ncPdfTab === 'ticket80mm' ? creditNote?.pdf_ticket_file_path : creditNote?.pdf_a4_file_path;
    const fileName = ncPdfTab === 'ticket80mm' 
      ? `nc-ticket-${creditNote?.series}-${String(creditNote?.number).padStart(8, '0')}.pdf`
      : `nc-a4-${creditNote?.series}-${String(creditNote?.number).padStart(8, '0')}.pdf`;

    if (pdfUrl) {
      const link = document.createElement('a');
      link.href = pdfUrl;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      toast.success('PDF descargado correctamente');
    } else {
      toast.error(`No hay PDF ${ncPdfTab === 'ticket80mm' ? '80mm' : 'A4'} disponible para descargar`);
    }
  };

  const handleGenerateOrRegenerateCurrentPdf = () => {
    if (creditNoteId == null) return;
    setShowPdfError(false);
    const size = ncPdfTab === 'ticket80mm' ? '80mm' : 'a4';
    generateCreditNotePdf({ id: creditNoteId, size });
  };

  if (isLoading) {
    return (
      <div className="p-8 text-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
        <p className="mt-4 text-dm-text-secondary">Cargando nota de crédito...</p>
      </div>
    );
  }

  if (!creditNote) {
    return (
      <div className="p-8 text-center">
        <XCircleIcon className="h-12 w-12 text-red-600 dark:text-red-400 mx-auto mb-4" />
        <h2 className="text-xl font-semibold text-dm-text-primary mb-2">Nota de Crédito no encontrada</h2>
        <p className="text-dm-text-secondary mb-4">La nota de crédito solicitada no existe o no tienes permisos para verla.</p>
        <Button onClick={() => navigate('/accounting/credit-notes')}>
          Volver al listado
        </Button>
      </div>
    );
  }

  const hasNcTicket = Boolean(creditNote.pdf_ticket_file_path?.trim());
  const hasNcA4 = Boolean(creditNote.pdf_a4_file_path?.trim());
  const ncPdfSize: '80mm' | 'a4' = ncPdfTab === 'ticket80mm' ? '80mm' : 'a4';
  const hasPdfForCurrentNcTab = ncPdfTab === 'ticket80mm' ? hasNcTicket : hasNcA4;
  const pdfCacheBuster = `${creditNote.updated_at ? new Date(creditNote.updated_at).getTime() : 0}_${dataUpdatedAt}`;
  const ncPdfBase =
    ncPdfTab === 'ticket80mm' ? creditNote.pdf_ticket_file_path : creditNote.pdf_a4_file_path;
  const ncPdfSrc = ncPdfBase ? `${ncPdfBase}?v=${pdfCacheBuster}` : '';

  const clientName = creditNote.client?.name || (creditNote as any).client_name || '—';
  const clientDoc = creditNote.client?.doc_number || (creditNote as any).client_document;

  return (
    <div className="min-h-screen bg-dm-bg-secondary">
      <div className="max-w-7xl mx-auto px-4 py-6 space-y-6">
      {/* Cabecera */}
      <div className="bg-dm-bg-primary rounded-xl border border-dm-border-primary/80 shadow-sm p-5 sm:p-6">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div className="flex items-start gap-3 min-w-0">
            <Button
              variant="outline"
              size="sm"
              onClick={() => navigate('/accounting/credit-notes')}
              className="shrink-0"
            >
              <ArrowLeftIcon className="h-4 w-4" />
            </Button>
            <div className="min-w-0">
              <p className="text-xs font-medium uppercase tracking-wide text-dm-text-muted">Nota de crédito electrónica</p>
              <h1 className="text-2xl sm:text-3xl font-bold text-dm-text-primary tracking-tight">
                {creditNote.series}-{String(creditNote.number).padStart(8, '0')}
              </h1>
              <p className="text-sm text-dm-text-secondary mt-1 truncate" title={clientName}>
                {formatDate(creditNote.issue_date)} · {clientName}
              </p>
              <div className="flex flex-wrap items-center gap-2 mt-3">
                <div className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium border ${getSunatStatusColor(resolvedSunatStatus)}`}>
                  {getSunatStatusIcon(resolvedSunatStatus)}
                  <span className="ml-1.5">
                    {resolvedSunatStatus === 'ACCEPTED' ? 'Aceptada SUNAT' :
                     resolvedSunatStatus === 'REJECTED' ? 'Rechazada' :
                     resolvedSunatStatus === 'SENT' ? 'Enviada' :
                     resolvedSunatStatus === 'PENDING' ? 'Pendiente' : 'Sin estado'}
                  </span>
                </div>
                <span className="text-sm font-semibold text-dm-text-primary">
                  Total {formatCurrency(creditNote.total_payable)}
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Comprobante PDF: un formato por llamada al backend */}
      <div className="bg-dm-bg-primary rounded-xl border border-dm-border-primary/80 shadow-sm overflow-hidden">
        <div className="border-b border-dm-border-secondary px-5 py-4 sm:px-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <div>
              <h2 className="text-base font-semibold text-dm-text-primary">Comprobante PDF</h2>
              <p className="text-sm text-dm-text-muted mt-0.5">
                Elige el formato y genera o regenera únicamente ese PDF (una petición por tamaño).
              </p>
            </div>
          </div>
          <div className="mt-4 flex border-b border-dm-border-primary overflow-x-auto">
            <button
              type="button"
              onClick={() => {
                setNcPdfTab('ticket80mm');
                setShowPdfError(false);
              }}
              className={`px-4 py-2.5 text-sm font-medium transition-colors whitespace-nowrap shrink-0 ${
                ncPdfTab === 'ticket80mm'
                  ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400 -mb-px'
                  : 'text-dm-text-muted hover:text-dm-text-secondary'
              }`}
            >
              Ticket 80&nbsp;mm
            </button>
            <button
              type="button"
              onClick={() => {
                setNcPdfTab('a4');
                setShowPdfError(false);
              }}
              className={`px-4 py-2.5 text-sm font-medium transition-colors whitespace-nowrap shrink-0 ${
                ncPdfTab === 'a4'
