                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center p-2 rounded-lg hover:bg-dm-bg-hover border border-dm-border-primary transition-colors"
                  >
                    <DocumentArrowDownIcon className="h-4 w-4 text-orange-600 dark:text-orange-400 mr-2" />
                    <span className="text-sm font-medium text-dm-text-primary">PDF Ticket</span>
                  </a>
                )}
                {creditNote.pdf_file_path && (
                  <a
                    href={creditNote.pdf_file_path}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center p-2 rounded-lg hover:bg-dm-bg-hover border border-dm-border-primary transition-colors"
                  >
                    <DocumentArrowDownIcon className="h-4 w-4 text-red-600 dark:text-red-400 mr-2" />
                    <span className="text-sm font-medium text-dm-text-primary">PDF General</span>
                  </a>
                )}
                {creditNote.signed_xml_file_path && (
                  <a
                    href={creditNote.signed_xml_file_path}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center p-2 rounded-lg hover:bg-dm-bg-hover border border-dm-border-primary transition-colors"
                  >
                    <DocumentArrowDownIcon className="h-4 w-4 text-blue-600 dark:text-blue-400 mr-2" />
                    <span className="text-sm font-medium text-dm-text-primary">XML Firmado</span>
                  </a>
                )}
                {creditNote.cdr_file_path && (
                  <a
                    href={creditNote.cdr_file_path}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center p-2 rounded-lg hover:bg-dm-bg-hover border border-dm-border-primary transition-colors"
                  >
                    <DocumentArrowDownIcon className="h-4 w-4 text-green-600 dark:text-green-400 mr-2" />
                    <span className="text-sm font-medium text-dm-text-primary">CDR (SUNAT)</span>
                  </a>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
      </div>
    </div>
  );
};

// src/features/accounting/credit-notes/pages/CreditNoteFullFormPage.tsx

import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useForm, SubmitHandler, useFieldArray } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { ArrowLeftIcon } from '@heroicons/react/24/outline';
import { toast } from '@/utils/sileo-toast';

import { Button } from '../../../../components/common/Button';
import { useCreateCreditNote } from '../../hooks/useCreditNotes';
import { CreditNoteCreateData } from '../../types';
import { useAccountingDocumentSeriesForBranch } from '../../../../hooks/useAccountingDocumentSeries';
import { clientsService } from '../../../../services/clients.service';
import { invoicesService } from '../../../../services/invoices.service';
import { productsServicesService } from '../../../../services/products-services.service';
import { authService } from '../../../../services/auth.service';
import { Client, ProductService, User } from '../../../../types';

// Importar componentes modularizados
import {
	AffectedDocumentSection,
	CreditNoteReasonSection,
	CreditNoteItemsSection,
	CreditNoteSidebar
} from '../components';
import { Controller } from 'react-hook-form';

// Esquema de validación según estructura del backend
const creditNoteSchema = z.object({
	client_id: z.number().min(1, "Debe seleccionar un cliente."),
	series: z.string().min(1, "La serie es requerida."),
	currency_code: z.string().min(1, "La moneda es requerida."),
	affected_document_type_code: z.string().min(1, "Tipo de documento afectado requerido."),
	affected_document_series_number: z.string().min(1, "Serie y número del documento afectado requeridos."),
	credit_note_type_code: z.string().min(1, "Debe seleccionar un motivo."),
	reason: z.string().min(10, "La descripción debe tener al menos 10 caracteres."),
	items: z.array(z.object({
		product_id: z.number().min(1, "Debe seleccionar un producto."),
		quantity: z.number().min(0.01, "La cantidad debe ser mayor a 0."),
		unit_code: z.string().min(1, "El código de unidad es requerido."),
		unit_price: z.number().min(0, "El precio unitario no puede ser negativo."),
		discount: z.number().min(0, "El descuento no puede ser negativo.").optional(),
		price_with_tax: z.number().min(0, "El precio con impuesto no puede ser negativo."),
		price_type_code: z.string().min(1, "El código de precio es requerido."),
		tax_category_code: z.string().min(1, "La categoría del impuesto es requerida."),
		description: z.string().min(1, "La descripción es requerida."),
	})).min(1, "Debe agregar al menos un item."),
	igv_applicable: z.boolean().optional(),
});

type CreditNoteFormData = z.infer<typeof creditNoteSchema>;

export const CreditNoteFullFormPage: React.FC = () => {
	const navigate = useNavigate();
	const location = useLocation();
	const { affectedInvoice, selectedType } = (location.state as any) || {};
	const { mutate: createCreditNote, isPending } = useCreateCreditNote();
	const queryClient = useQueryClient();

	// Estados locales
	const [selectedInvoiceDetail, setSelectedInvoiceDetail] = useState<any>(null);

	// Hook de usuario actual
	const { data: currentUser } = useQuery<User>({
		queryKey: ['currentUser'],
		queryFn: async (): Promise<User> => {
			const data = await authService.getProfile();
			return data;
		},
		staleTime: 1000 * 60 * 5,
		retry: 1
	});

	// Cargar datos reales
	const { data: clients = [] } = useQuery<Client[]>({
		queryKey: ['clients', currentUser?.company_id],
		queryFn: () => clientsService.getAll(),
		enabled: !!currentUser?.company_id,
	});

	const { data: products = [], isLoading: loadingProducts } = useQuery<ProductService[]>({
		queryKey: ['products-services', currentUser?.company_id],
		queryFn: () => productsServicesService.getActive(),
		enabled: !!currentUser?.company_id,
	});

	// Series de documentos contables
	const { availableCreditNoteSeries } = useAccountingDocumentSeriesForBranch(
		currentUser?.default_branch_office_id || null, 
		currentUser?.company_id || 0
	);

	const { control, handleSubmit, formState: { errors }, setValue, watch } = useForm<CreditNoteFormData>({
		resolver: zodResolver(creditNoteSchema),
		defaultValues: {
			client_id: 0,
			series: '',
			currency_code: 'PEN',
			affected_document_type_code: '01',
			affected_document_series_number: '',
			credit_note_type_code: '01',
			reason: '',
			items: [{
				product_id: 0,
				quantity: 1,
				unit_code: 'NIU',
				unit_price: 0,
				price_with_tax: 0,
				price_type_code: '01',
				tax_category_code: '10',
				description: '',
			}]
			,
			igv_applicable: true
		}
	});

	const { append, remove } = useFieldArray({
		control,
		name: "items"
	});

	// Si venimos desde la selección rápida, cargar la factura completa y prellenar
	const { data: invoiceData } = useQuery<any>({
		queryKey: ['invoice', affectedInvoice?.id],
		queryFn: async () => affectedInvoice && affectedInvoice.id ? await invoicesService.getById(affectedInvoice.id) : null,
		enabled: !!affectedInvoice?.id,
	});

	useEffect(() => {
		if (invoiceData) {
			handleInvoiceSelect(invoiceData);
		}
	}, [invoiceData]);

	// Seleccionar serie por defecto
	useEffect(() => {
		if (availableCreditNoteSeries.length > 0) {
			const savedSeries = localStorage.getItem('lastUsedCreditNoteSeries');
			const seriesExists = availableCreditNoteSeries.find(s => s.series_code === savedSeries);
			if (seriesExists && savedSeries) {
				setValue('series', savedSeries);
			} else {
				setValue('series', availableCreditNoteSeries[0].series_code);
			}
		}
	}, [availableCreditNoteSeries, setValue]);

	// Auto-seleccionar cliente
	// - Si hay un cliente guardado en localStorage lo usamos
	// - Si solo existe un cliente en la compañía, lo seleccionamos automáticamente
	useEffect(() => {
		const currentClientId = watch('client_id');
		if ((!currentClientId || currentClientId === 0) && clients.length > 0) {
			const saved = localStorage.getItem('lastUsedClientId');
			const savedId = saved ? parseInt(saved, 10) : NaN;
			if (!isNaN(savedId) && clients.some(c => c.id === savedId)) {
				setValue('client_id', savedId);
			} else if (clients.length === 1) {
				setValue('client_id', clients[0].id);
			}
		}
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [clients]);

	// Guardar en localStorage cuando el cliente cambia para futuras autoselecciones
	useEffect(() => {
		const id = watch('client_id');
		if (id && id > 0) {
			localStorage.setItem('lastUsedClientId', String(id));
		}
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [watch('client_id')]);

	// Función para manejar la selección de factura
	const handleInvoiceSelect = (invoiceDetail: any) => {
		try {
			setSelectedInvoiceDetail(invoiceDetail);

			// Autocompletar campos del formulario
			if (invoiceDetail.client?.id) {
				setValue('client_id', invoiceDetail.client.id);
			}
			setValue('affected_document_type_code', invoiceDetail.document_type_code);
			setValue('affected_document_series_number', `${invoiceDetail.series}-${String(invoiceDetail.number).padStart(8, '0')}`);
			setValue('currency_code', invoiceDetail.currency_code);
			// If invoice series matches one of the available credit note series, preselect it
			if (invoiceDetail.series && availableCreditNoteSeries && availableCreditNoteSeries.length > 0) {
				const match = availableCreditNoteSeries.find((s: any) => s.series_code === invoiceDetail.series);
				if (match) setValue('series', invoiceDetail.series);
			}

			// Cargar los items de la factura original
			if (invoiceDetail.items && invoiceDetail.items.length > 0) {
				// Limpiar items existentes
				remove();

				// Determine if IGV applies: any item with igv_percentage > 0 or tax_category_code === '10'
				const igvApplicable = invoiceDetail.items.some((it: any) => {
					const igvPerc = parseFloat(it.igv_percentage || '0');
					return igvPerc > 0 || it.tax_category_code === '10';
				});
				setValue('igv_applicable', igvApplicable);

				// Agregar items de la factura, respetando tax_category_code
				invoiceDetail.items.forEach((item: any, index: number) => {
					const inferredTax = item.tax_category_code || (parseFloat(item.igv_percentage || '0') > 0 ? '10' : '20');
					const itemData = {
						product_id: item.product_id || 0,
						quantity: parseFloat(item.quantity) || 1,
						unit_code: item.unit_code || 'NIU',
						unit_price: parseFloat(item.unit_price) || 0,
						price_with_tax: parseFloat(item.price_with_tax) || 0,
						price_type_code: item.price_type_code || '01',
						tax_category_code: inferredTax,
						description: item.item_description || item.product_name || '',
						discount: 0,
					};

					if (index === 0) {
						setValue('items.0', itemData);
					} else {
						append(itemData);
					}
				});
			}

			// Si se pasó un tipo seleccionado, aplicarlo
			if (selectedType) {
				setValue('credit_note_type_code', selectedType);
			}
		} catch (e) {
			console.error('Error prefilling credit note from invoice:', e);
		}
	};

	const onSubmit: SubmitHandler<CreditNoteFormData> = (data) => {
		if (!currentUser?.company_id) {
			toast.error("No se pudo obtener la información de la empresa");
			return;
		}

		// Guardar serie usada
		localStorage.setItem('lastUsedCreditNoteSeries', data.series);

		const payload: CreditNoteCreateData = {
			company_id: currentUser.company_id,
			client_id: data.client_id,
			series: data.series,
			currency_code: data.currency_code,
			issue_date: new Date().toISOString().split('T')[0],
			issue_time: new Date().toTimeString().split(' ')[0],
			affected_document_type_code: data.affected_document_type_code,
			affected_document_series_number: data.affected_document_series_number,
			credit_note_type_code: data.credit_note_type_code,
			reason: data.reason,
			items: data.items.map(item => ({
				product_id: item.product_id,
				quantity: item.quantity,
				unit_code: item.unit_code,
				unit_price: parseFloat(item.unit_price.toFixed(10)),
				price_with_tax: parseFloat(item.price_with_tax.toFixed(10)),
				price_type_code: item.price_type_code,
				tax_category_code: item.tax_category_code,
				description: item.description,
				...(item.discount ? { discount: typeof item.discount === 'number' ? parseFloat(item.discount.toFixed ? item.discount.toFixed(10) : String(item.discount)) : parseFloat(String(item.discount)) } : {}),
			})),
		};

		createCreditNote(payload, {
			onSuccess: async () => {
				await queryClient.invalidateQueries({ queryKey: ['creditNotes'] });
				navigate('/accounting/credit-notes');
			}
		});
	};

	// selectedClient removed - client is handled as hidden field and via stored values
	const watchedItems = watch('items');

	return (
		<div className="space-y-6">
			{/* Header */}
			<div className="flex items-center justify-between">
				<div className="flex items-center">
					<Button
						variant="outline"
						onClick={() => navigate('/accounting/credit-notes')}
						className="mr-4"
					>
						<ArrowLeftIcon className="h-4 w-4" />
					</Button>
					<div>
						<h1 className="text-3xl font-bold text-dm-text-primary">Nueva Nota de Crédito</h1>
						<p className="text-dm-text-secondary">Crear una nota de crédito detallada con items</p>
					</div>
				</div>
			</div>

			{/* Alerta informativa sobre series */}
			<div className="bg-amber-50 dark:bg-amber-950/30 border border-amber-200 rounded-lg p-4">
				<div className="flex">
					<div className="flex-shrink-0">
						<svg className="h-5 w-5 text-amber-400" viewBox="0 0 20 20" fill="currentColor">
							<path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
						</svg>
					</div>
					<div className="ml-3">
						<h3 className="text-sm font-medium text-amber-800 dark:text-amber-300">
							Requisito importante de SUNAT
						</h3>
						<div className="mt-2 text-sm text-amber-700 dark:text-amber-300">
							<p>
								Según normativa SUNAT, <strong>la serie de la nota de crédito debe ser la misma que la serie del comprobante que afecta</strong>.
							</p>
							<p className="mt-1">
								Ejemplo: Si el comprobante es <code className="bg-amber-100 px-1 py-0.5 rounded">B004-00000123</code>, 
								la serie de la nota de crédito debe ser <code className="bg-amber-100 px-1 py-0.5 rounded">B004</code>.
							</p>
							<p className="mt-2 font-medium">
								📝 Por favor, verifique que la serie seleccionada coincida con la del comprobante a afectar.
							</p>
						</div>
					</div>
				</div>
			</div>

			<form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
				<div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
					{/* Información Principal */}
					<div className="lg:col-span-2 space-y-6">
												{/* Campos ocultos: client_id y series (la selección se hace desde la factura) */}
												<Controller
													name="client_id"
													control={control}
													render={({ field }) => <input type="hidden" {...field} />}
												/>
												<Controller
													name="series"
													control={control}
													render={({ field }) => <input type="hidden" {...field} />}
												/>

						{/* Documento Afectado */}
						<AffectedDocumentSection
							control={control}
							errors={errors}
							companyId={currentUser?.company_id || 0}
							selectedInvoiceDetail={selectedInvoiceDetail}
							onInvoiceSelect={handleInvoiceSelect}
							redirectToAnnulOnSelect={true}
						/>

						{/* Motivo */}
						<CreditNoteReasonSection
							control={control}
							errors={errors}
							watch={watch}
						/>

						{/* Items */}
						<CreditNoteItemsSection
							control={control}
							errors={errors}
							setValue={setValue}
							watch={watch}
							products={products}
							loadingProducts={loadingProducts}
						/>
					</div>

					{/* Panel Lateral */}
					<div className="space-y-6">
						<CreditNoteSidebar
							creditNoteTypeCode={watch('credit_note_type_code')}
							items={watchedItems}
							setValue={setValue}
						/>
					</div>
				</div>

				{/* Botones de Acción */}
				<div className="flex justify-end space-x-3 pt-6 border-t">
					<Button type="button" variant="outline" onClick={() => navigate('/accounting/credit-notes')}>
						Cancelar
					</Button>
					<Button type="submit" isLoading={isPending}>
						Crear Nota de Crédito
					</Button>
				</div>
			</form>
		</div>
	);
};

// src/features/accounting/credit-notes/pages/CreditNoteNewPage.tsx

import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import {
	MagnifyingGlassIcon,
	ArrowLeftIcon,
	CreditCardIcon,
} from '@heroicons/react/24/outline';
import { Button } from '../../../../components/common/Button';
import { useVoidableInvoices } from '../../hooks/useCreditNotes';
import { VoidableInvoice } from '../../types';

export const CreditNoteNewPage: React.FC = () => {
	const navigate = useNavigate();
	const [searchParams] = useSearchParams();
	const [companyId] = useState(1); // TODO: Obtener del contexto de usuario
	const [searchTerm, setSearchTerm] = useState('');

	// Verificar si se pasó un invoice_id específico
	const invoiceIdParam = searchParams.get('invoice_id');

	const { data: voidableInvoices, isLoading } = useVoidableInvoices(companyId);

	// Si se pasó un invoice_id específico, navegar directamente al formulario (anulación simplificada)
	useEffect(() => {
		if (invoiceIdParam && voidableInvoices) {
			const selectedInvoice = voidableInvoices.find(inv => inv.id === parseInt(invoiceIdParam));
			if (selectedInvoice) {
				// mantener el comportamiento actual: navegar directamente a la anulación
				handleSelectInvoice(selectedInvoice);
			}
		}
	}, [invoiceIdParam, voidableInvoices]);





	const filteredInvoices = voidableInvoices?.filter((invoice) =>
		invoice.series.toLowerCase().includes(searchTerm.toLowerCase()) ||
		invoice.number.toString().includes(searchTerm) ||
		invoice.client_name.toLowerCase().includes(searchTerm.toLowerCase())
	) || [];

	const buildAffectedInvoice = (invoice: VoidableInvoice) => ({
		id: invoice.id,
		series: invoice.series,
		number: invoice.number,
		document_type_code: invoice.document_type_code,
		company_id: companyId,
		client: {
			id: 0, // No disponible en VoidableInvoice
			name: invoice.client_name,
			doc_number: '', // No disponible
		},
		total_payable: parseFloat(invoice.total_payable),
		issue_date: invoice.issue_date,
	});

	// Navegación directa a anulación (comportamiento original)
	const handleSelectInvoice = (invoice: VoidableInvoice) => {
		const affectedInvoice = buildAffectedInvoice(invoice);
		navigate('/accounting/credit-notes/annul', {
			state: { affectedInvoice }
		});
	};



	const formatCurrency = (amount: string) => {
		return new Intl.NumberFormat('es-PE', {
			style: 'currency',
			currency: 'PEN'
		}).format(parseFloat(amount));
	};

	const formatDate = (dateString: string) => {
		return new Date(dateString).toLocaleDateString('es-PE');
	};

	return (
		<div className="space-y-6">
			{/* Header */}
			<div className="flex items-center justify-between">
				<div className="flex items-center">
					<Button
						variant="outline"
						onClick={() => navigate('/accounting/credit-notes')}
						className="mr-4"
					>
						<ArrowLeftIcon className="h-4 w-4" />
					</Button>
					<div>
						<h1 className="text-3xl font-bold text-dm-text-primary">Nueva Nota de Crédito</h1>
						<p className="text-dm-text-secondary">Selecciona la factura que deseas anular</p>
					</div>
				</div>
			</div>

			{/* Buscador */}
			<div className="bg-dm-bg-primary rounded-lg shadow p-6">
				<div className="flex items-center space-x-4">
					<div className="flex-1">
						<label className="block text-sm font-medium text-dm-text-secondary mb-1">
							Buscar factura
						</label>
						<div className="relative">
							<MagnifyingGlassIcon className="h-5 w-5 absolute left-3 top-3 text-dm-text-muted" />
							<input
								type="text"
								placeholder="Buscar por serie, número o cliente..."
								value={searchTerm}
								onChange={(e) => setSearchTerm(e.target.value)}
								className="w-full pl-10 pr-4 py-2 border border-dm-border-primary rounded-md focus:ring-blue-500 focus:border-blue-500"
							/>
						</div>
					</div>
				</div>
			</div>

			{/* Lista de Facturas */}
			<div className="bg-dm-bg-primary rounded-lg shadow">
				<div className="px-6 py-4 border-b border-dm-border-primary">
					<h2 className="text-lg font-semibold text-dm-text-primary">
						Facturas Disponibles para Anular
					</h2>
					<p className="text-sm text-dm-text-secondary mt-1">
						Solo se muestran facturas que pueden ser anuladas
					</p>
				</div>

				{isLoading ? (
					<div className="p-8 text-center">
						<div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
						<p className="mt-2 text-dm-text-secondary">Cargando facturas...</p>
					</div>
				) : filteredInvoices.length === 0 ? (
					<div className="p-8 text-center">
						{voidableInvoices?.length === 0 ? (
							<div>
								<CreditCardIcon className="h-12 w-12 text-dm-text-muted mx-auto mb-4" />
								<h3 className="text-lg font-medium text-dm-text-primary mb-2">
									No hay facturas para anular
								</h3>
								<p className="text-dm-text-secondary">
									No se encontraron facturas que puedan ser anuladas en este momento.
								</p>
							</div>
						) : (
							<div>
								<MagnifyingGlassIcon className="h-12 w-12 text-dm-text-muted mx-auto mb-4" />
								<h3 className="text-lg font-medium text-dm-text-primary mb-2">
									No se encontraron resultados
								</h3>
								<p className="text-dm-text-secondary">
									No hay facturas que coincidan con tu búsqueda.
								</p>
							</div>
						)}
					</div>
				) : (
					<div className="divide-y divide-dm-border-primary">
						{filteredInvoices.map((invoice) => {
							const isCancelled = invoice.business_status === 'CANCELLED';
							const isIncreased = invoice.business_status === 'INCREASED';

							return (
								<div
									key={invoice.id}
									className={`p-6 transition-colors ${
										isCancelled 
											? 'bg-dm-bg-secondary cursor-not-allowed opacity-60' 
											: 'hover:bg-dm-bg-hover cursor-pointer'
									}`}
									onClick={() => !isCancelled && handleSelectInvoice(invoice)}
								>
									<div className="flex items-center justify-between">
										<div className="flex-1">
											<div className="flex items-center space-x-4">
												<div>
													<div className={`text-sm font-medium ${isCancelled ? 'text-dm-text-muted' : 'text-dm-text-primary'}`}>
														{invoice.series}-{String(invoice.number).padStart(8, '0')}
													</div>
													<div className="text-sm text-dm-text-muted">
														{invoice.document_type_code === '01' ? 'Factura' : 'Boleta'}
														{isCancelled && (
															<span className="ml-2 inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-300">
																CANCELADO
															</span>
														)}
														{isIncreased && (
															<span className="ml-2 inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-yellow-100 dark:bg-yellow-900/40 text-yellow-800 dark:text-yellow-300">
																AUMENTADO
															</span>
														)}
													</div>
												</div>
												<div className="flex-1">
													<div className={`text-sm font-medium ${isCancelled ? 'text-dm-text-muted' : 'text-dm-text-primary'}`}>
														{invoice.client_name}
													</div>
													<div className="text-sm text-dm-text-muted">
														Emitida el {formatDate(invoice.issue_date)}
													</div>
												</div>
												<div className="text-right">
													<div className={`text-sm font-medium ${isCancelled ? 'text-dm-text-muted' : 'text-dm-text-primary'}`}>
														{formatCurrency(invoice.total_payable)}
													</div>
													<div className="text-sm text-dm-text-muted">Total</div>
												</div>
											</div>
										</div>
										<div className="ml-6">
											<Button 
												size="sm" 
												disabled={isCancelled}
												className={isCancelled ? 'opacity-50 cursor-not-allowed' : ''}
											>
												{isCancelled ? 'No disponible' : 'Anular'}
											</Button>
										</div>
									</div>
								</div>
							);
						})}
					</div>
				)}
			</div>

			{/* Información adicional */}
			<div className="bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 rounded-lg p-4">
				<div className="flex">
					<div className="ml-3">
						<h3 className="text-sm font-medium text-blue-800 dark:text-blue-300">
							Información sobre Notas de Crédito
						</h3>
						<div className="mt-2 text-sm text-blue-700 dark:text-blue-300">
							<ul className="list-disc pl-5 space-y-1">
								<li>Solo puedes anular facturas que no hayan sido anuladas previamente</li>
								<li>Las facturas marcadas como "CANCELADO" no pueden ser anuladas nuevamente</li>
								<li>Las facturas marcadas como "AUMENTADO" pueden ser anuladas si es necesario</li>
								<li>La nota de crédito se generará automáticamente con todos los items</li>
								<li>El documento será enviado automáticamente a SUNAT para su procesamiento</li>
								<li>Podrás descargar el PDF una vez que SUNAT lo procese</li>
							</ul>
						</div>
					</div>
				</div>
			</div>

			{/* Modal selector de tipo de nota eliminado: la selección ahora redirige directamente a la anulación simplificada */}
		</div>
	);
};

// src/features/accounting/credit-notes/pages/CreditNotesListPage.tsx

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import {
  MagnifyingGlassIcon,
  ArrowPathIcon,
  DocumentArrowDownIcon,
  EyeIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  DocumentTextIcon,
  FunnelIcon,
  PlusIcon,
  ClipboardDocumentListIcon,
} from '@heroicons/react/24/outline';
import { DataTable, Column } from '../../../../components/common/DataTable';
import { Spinner } from '../../../../components/common/Spinner';
import { SunatStatusBadge } from '../../components/SunatStatusBadge';
import { useCreditNotes, useRefreshPendingStatuses } from '../hooks/useCreditNotes';
import { CreditNotesListParams } from '../../types';
import { CreditNote } from '../../../../types';
import { useDebounce } from '../../../../hooks/useDebounce';

export const CreditNotesListPage: React.FC = () => {
  const [series, setSeries] = useState('');
  const [sunatStatus, setSunatStatus] = useState('');
  const [issueDate, setIssueDate] = useState('');
  const [currentPage, setCurrentPage] = useState(0);
  const itemsPerPage = 20;

  const debouncedSeries = useDebounce(series, 300);

  const [filters, setFilters] = useState<CreditNotesListParams>({
    company_id: 1,
    skip: 0,
    limit: itemsPerPage,
  });

  const { data: creditNotes, isLoading, refetch } = useCreditNotes(filters);
  const { mutate: refreshStatuses, isPending: isRefreshing } = useRefreshPendingStatuses();

  // Actualizar filtros cuando cambian los campos o la paginación
  useEffect(() => {
    const newFilters: CreditNotesListParams = {
      company_id: 1,
      skip: currentPage * itemsPerPage,
      limit: itemsPerPage,
    };

    if (debouncedSeries) newFilters.series = debouncedSeries;
    if (sunatStatus) newFilters.sunat_status = sunatStatus as any;
    if (issueDate) newFilters.issue_date = issueDate;

    setFilters(newFilters);
  }, [currentPage, debouncedSeries, sunatStatus, issueDate, itemsPerPage]);

  // Polling automático cada 2 minutos para documentos pendientes
  useEffect(() => {
    const interval = setInterval(() => {
      const hasPendingDocs = creditNotes?.some((note) =>
        note.sunat_status === 'PENDING' || note.sunat_status === 'SENT'
      );
      if (hasPendingDocs) {
        refetch();
      }
    }, 120000);

    return () => clearInterval(interval);
  }, [creditNotes, refetch]);

  // Manejadores de cambios en filtros (resetean la paginación)
  const handleSeriesChange = (value: string) => {
    setSeries(value);
    setCurrentPage(0);
  };

  const handleSunatStatusChange = (value: string) => {
    setSunatStatus(value);
    setCurrentPage(0);
  };

  const handleIssueDateChange = (value: string) => {
    setIssueDate(value);
    setCurrentPage(0);
  };

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('es-PE', {
      style: 'currency',
      currency: 'PEN',
    }).format(amount);
  };

  const formatDate = (dateString?: string) => {
    if (!dateString) return '—';
    const dateOnlyMatch = String(dateString).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    try {
      if (dateOnlyMatch) {
        const [, y, m, d] = dateOnlyMatch;
        const date = new Date(Number(y), Number(m) - 1, Number(d));
        return date.toLocaleDateString('es-PE');
      }
      return new Date(dateString).toLocaleDateString('es-PE');
    } catch {
      return String(dateString);
    }
  };

  const columns: Column<CreditNote>[] = [
    {
      key: 'document',
      header: 'Documento',
      accessor: (note) => (
        <div>
          <div className="text-[14px] font-medium text-dm-text-primary">
            {note.series}-{String(note.number).padStart(8, '0')}
          </div>
          <div className="text-[12px] text-dm-text-muted">Nota de Crédito</div>
        </div>
      ),
    },
    {
      key: 'client',
      header: 'Cliente',
      accessor: (note) => (
        <div>
          <div className="text-[14px] font-medium text-dm-text-primary">
            {note.client?.name || (note as any).client_name || 'N/A'}
          </div>
          <div className="text-[12px] text-dm-text-muted">
            {note.client?.doc_number || (note as any).client_document || ''}
          </div>
        </div>
      ),
    },
    {
      key: 'affected',
      header: 'Doc. Afectado',
      accessor: (note) => (
        <div>
          <div className="text-[14px] font-medium text-dm-text-primary">{note.affected_document_series_number}</div>
          <div className="text-[12px] text-dm-text-muted">
            {note.affected_document_type_code === '01' ? 'Factura' : 'Boleta'}
          </div>
        </div>
      ),
    },
    {
      key: 'amount',
      header: 'Monto',
      accessor: (note) => (
        <span className="text-[14px] font-semibold text-dm-text-primary">
          {formatCurrency(note.total_payable)}
        </span>
      ),
    },
    {
      key: 'sunat_status',
      header: 'Estado SUNAT',
      accessor: (note) => <SunatStatusBadge status={note.sunat_status} />,
    },
    {
      key: 'issue_date',
      header: 'Fecha',
      accessor: (note) => (
        <span className="text-[13px] text-dm-text-secondary">
          {note.issue_date ? formatDate(note.issue_date) : formatDate((note as any).created_at)}
        </span>
      ),
    },
  ];

  const customActions = (note: CreditNote) => (
    <div className="flex items-center gap-1">
      <Link
        to={`/accounting/credit-notes/${note.id}`}
        className="flex h-8 w-8 items-center justify-center rounded-full bg-dm-bg-secondary text-dm-text-muted hover:text-[#1F4690] hover:bg-[#1F4690]/10 transition-colors"
        title="Ver detalle"
      >
        <EyeIcon className="h-4 w-4" strokeWidth={1.5} />
      </Link>
      {note.pdf_a4_file_path && (
        <a
          href={note.pdf_a4_file_path}
          target="_blank"
          rel="noopener noreferrer"
          className="flex h-8 w-8 items-center justify-center rounded-full bg-dm-bg-secondary text-dm-text-muted hover:text-[#cf1322] hover:bg-red-50 dark:hover:bg-red-950/30 transition-colors"
          title="Descargar PDF A4"
        >
          <DocumentArrowDownIcon className="h-4 w-4" strokeWidth={1.5} />
        </a>
      )}
      {note.pdf_ticket_file_path && (
        <a
          href={note.pdf_ticket_file_path}
          target="_blank"
          rel="noopener noreferrer"
          className="flex h-8 w-8 items-center justify-center rounded-full bg-dm-bg-secondary text-dm-text-muted hover:text-[#237804] hover:bg-green-50 dark:hover:bg-green-950/30 transition-colors"
          title="Descargar Ticket 80mm"
        >
          <DocumentTextIcon className="h-4 w-4" strokeWidth={1.5} />
        </a>
      )}
    </div>
  );

  // ── Paginación ──
  const hasNextPage = creditNotes && creditNotes.length === itemsPerPage;
  const hasPrevPage = currentPage > 0;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex items-start gap-4">
          <div className="hidden sm:flex h-12 w-12 items-center justify-center rounded-[12px] bg-[#1F4690]/10">
            <ClipboardDocumentListIcon className="h-6 w-6 text-[#1F4690]" strokeWidth={1.5} />
          </div>
          <div>
            <h1
              className="text-[32px] font-medium text-dm-text-primary tracking-[-0.64px] leading-[1.19]"
              style={{ fontFamily: "'Inter', sans-serif" }}
            >
              Notas de Crédito
            </h1>
            <p className="mt-1 text-[15px] text-dm-text-secondary leading-[1.33]">
              Gestiona las anulaciones y notas de crédito
            </p>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full sm:w-auto">
          <button
            onClick={() => refreshStatuses(10)}
            disabled={isRefreshing}
            className="inline-flex items-center justify-center gap-2 px-4 py-2.5 bg-dm-bg-primary border border-dm-border-primary rounded-[20px] text-[14px] font-medium text-dm-text-primary hover:bg-dm-bg-secondary disabled:opacity-50 transition-colors"
          >
            <ArrowPathIcon className={`h-4 w-4 ${isRefreshing ? 'animate-spin' : ''}`} strokeWidth={1.5} />
            Actualizar Estados
          </button>
          <Link
            to="/accounting/credit-notes/new"
            className="inline-flex items-center justify-center gap-2 px-5 py-2.5 bg-[#1F4690] hover:bg-[#163672] text-white text-[14px] font-medium rounded-[20px] transition-colors"
          >
            <PlusIcon className="h-4 w-4" strokeWidth={1.5} />
            Nueva Nota de Crédito
          </Link>
        </div>
      </div>

      {/* Filtros */}
      <div className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary p-4 lg:p-5">
        <div className="flex items-center gap-2 mb-4">
          <FunnelIcon className="w-4 h-4 text-dm-text-muted" strokeWidth={1.5} />
          <span className="text-[13px] font-semibold text-dm-text-primary">Filtros</span>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div>
            <label className="block text-[12px] font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">
              Serie
            </label>
            <input
              type="text"
              placeholder="FC01, BC01..."
              value={series}
              className="w-full px-3 py-2.5 bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] text-[14px] text-dm-text-primary placeholder:text-dm-text-muted focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-all"
              onChange={(e) => handleSeriesChange(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-[12px] font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">
              Estado SUNAT
            </label>
            <select
              value={sunatStatus}
              className="w-full px-3 py-2.5 bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] text-[14px] text-dm-text-primary focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-all appearance-none"
              onChange={(e) => handleSunatStatusChange(e.target.value)}
            >
              <option value="">Todos los estados</option>
              <option value="PENDING">Pendiente</option>
              <option value="SENT">Enviado</option>
              <option value="ACCEPTED">Aceptado</option>
              <option value="REJECTED">Rechazado</option>
            </select>
          </div>
          <div>
            <label className="block text-[12px] font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">
              Fecha de Emisión
            </label>
            <input
              type="date"
              value={issueDate}
              className="w-full px-3 py-2.5 bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] text-[14px] text-dm-text-primary focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-all"
              onChange={(e) => handleIssueDateChange(e.target.value)}
            />
          </div>
          <div className="flex items-end">
            <button
              onClick={() => refetch()}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-4 py-2.5 bg-dm-bg-primary border border-dm-border-primary rounded-[12px] text-[14px] font-medium text-dm-text-primary hover:bg-dm-bg-secondary transition-colors"
            >
              <MagnifyingGlassIcon className="h-4 w-4" strokeWidth={1.5} />
              Buscar
            </button>
          </div>
        </div>
      </div>

      {/* Lista */}
      <div className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary overflow-hidden">
        {/* Desktop */}
        <div className="hidden md:block">
          <DataTable<CreditNote>
            data={creditNotes || []}
            columns={columns}
            keyExtractor={(note) => note.id}
            isLoading={isLoading}
            emptyMessage="No se encontraron notas de crédito"
            showActions={true}
            customActions={customActions}
          />
        </div>

        {/* Mobile cards */}
        <div className="md:hidden">
          {isLoading ? (
            <div className="p-10 flex flex-col items-center justify-center gap-3">
              <Spinner size="md" />
              <p className="text-[14px] text-dm-text-muted">Cargando notas de crédito...</p>
            </div>
          ) : creditNotes?.length === 0 ? (
            <div className="p-10 text-center text-[14px] text-dm-text-muted">
              No se encontraron notas de crédito
            </div>
          ) : (
            <div className="p-4 space-y-3">
              {creditNotes?.map((note) => (
                <div
                  key={note.id}
                  className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary overflow-hidden"
                >
                  {/* Header */}
                  <div className="p-4">
                    <div className="flex justify-between items-start gap-3 mb-2">
                      <div>
                        <span className="text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider">
                          {note.series}-{String(note.number).padStart(8, '0')}
                        </span>
                        <h3 className="text-[15px] font-medium text-dm-text-primary mt-0.5">
                          {note.client?.name || (note as any).client_name || 'N/A'}
                        </h3>
                        <p className="text-[13px] text-dm-text-muted mt-0.5">
                          {(note as any).client_document || note.client?.doc_number || ''}
                        </p>
                      </div>
                      <SunatStatusBadge status={note.sunat_status} />
                    </div>

                    <div className="grid grid-cols-2 gap-3 mt-3">
                      <div>
                        <span className="text-[11px] text-dm-text-muted">Doc. Afectado</span>
                        <p className="text-[13px] font-medium text-dm-text-primary">
                          {note.affected_document_series_number}
                        </p>
                        <p className="text-[11px] text-dm-text-muted">
                          {note.affected_document_type_code === '01' ? 'Factura' : 'Boleta'}
                        </p>
                      </div>
                      <div>
                        <span className="text-[11px] text-dm-text-muted">Monto</span>
                        <p className="text-[18px] font-semibold text-dm-text-primary">
                          {formatCurrency(note.total_payable)}
                        </p>
                      </div>
                    </div>
                  </div>

                  {/* Footer */}
                  <div className="px-4 py-3 border-t border-dm-border-secondary bg-dm-bg-secondary">
                    <div className="flex items-center justify-between">
                      <span className="text-[12px] text-dm-text-muted">
                        {note.issue_date ? formatDate(note.issue_date) : formatDate((note as any).created_at)}
                      </span>
                      <div className="flex items-center gap-1">
                        <Link
                          to={`/accounting/credit-notes/${note.id}`}
                          className="flex h-8 w-8 items-center justify-center rounded-full bg-dm-bg-secondary text-dm-text-muted hover:text-[#1F4690] hover:bg-[#1F4690]/10 transition-colors"
                          title="Ver detalle"
                        >
                          <EyeIcon className="h-4 w-4" strokeWidth={1.5} />
                        </Link>
                        {note.pdf_a4_file_path && (
                          <a
                            href={note.pdf_a4_file_path}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex h-8 w-8 items-center justify-center rounded-full bg-dm-bg-secondary text-dm-text-muted hover:text-[#cf1322] hover:bg-red-50 dark:hover:bg-red-950/30 transition-colors"
                            title="Descargar PDF A4"
                          >
                            <DocumentArrowDownIcon className="h-4 w-4" strokeWidth={1.5} />
                          </a>
                        )}
                        {note.pdf_ticket_file_path && (
                          <a
                            href={note.pdf_ticket_file_path}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex h-8 w-8 items-center justify-center rounded-full bg-dm-bg-secondary text-dm-text-muted hover:text-[#237804] hover:bg-green-50 dark:hover:bg-green-950/30 transition-colors"
                            title="Descargar Ticket 80mm"
                          >
                            <DocumentTextIcon className="h-4 w-4" strokeWidth={1.5} />
                          </a>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Paginación */}
        {!isLoading && creditNotes && creditNotes.length > 0 && (
          <div className="px-4 py-3 border-t border-dm-border-secondary flex items-center justify-between">
            <span className="text-[13px] text-dm-text-muted">
              Página {currentPage + 1} • Mostrando {creditNotes.length} registros
            </span>
            <div className="flex items-center gap-2">
              <button
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={!hasPrevPage}
                className="inline-flex items-center gap-1 px-3 py-1.5 rounded-[8px] border border-dm-border-primary text-[13px] text-dm-text-secondary hover:bg-dm-bg-secondary disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeftIcon className="h-3.5 w-3.5" strokeWidth={1.5} />
                Anterior
              </button>
              <button
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={!hasNextPage}
                className="inline-flex items-center gap-1 px-3 py-1.5 rounded-[8px] border border-dm-border-primary text-[13px] text-dm-text-secondary hover:bg-dm-bg-secondary disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
              >
                Siguiente
                <ChevronRightIcon className="h-3.5 w-3.5" strokeWidth={1.5} />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Info SUNAT */}
      {creditNotes && creditNotes.length > 0 && (
        <div className="bg-[#1F4690]/5 border border-[#1F4690]/10 rounded-[12px] p-5">
          <h3 className="text-[13px] font-semibold text-[#1F4690] mb-2">
            Información sobre Estados SUNAT
          </h3>
          <ul className="space-y-1.5 text-[13px] text-dm-text-secondary">
            <li className="flex items-start gap-2">
              <span className="w-1 h-1 rounded-full bg-[#1F4690] mt-1.5 shrink-0" />
              <span><strong className="text-dm-text-primary">Pendiente:</strong> Documento creado, esperando envío a SUNAT</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="w-1 h-1 rounded-full bg-[#1F4690] mt-1.5 shrink-0" />
              <span><strong className="text-dm-text-primary">Enviado:</strong> Documento enviado, esperando respuesta de SUNAT</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="w-1 h-1 rounded-full bg-[#1F4690] mt-1.5 shrink-0" />
              <span><strong className="text-dm-text-primary">Aceptado:</strong> Documento válido y procesado correctamente</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="w-1 h-1 rounded-full bg-[#1F4690] mt-1.5 shrink-0" />
              <span><strong className="text-dm-text-primary">Rechazado:</strong> Documento con errores, revisar observaciones</span>
            </li>
          </ul>
        </div>
      )}
    </div>
  );
};

// src/features/accounting/debit-notes/hooks/useDebitNotes.ts

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { debitNotesService } from '../services/debitNotes.service.js';
import { 
  DebitNotesListParams, 
  DebitNoteCreateData,
  DebitNoteAnnulData,
} from '../../types';
import { toast } from '@/utils/sileo-toast';

// Hook para listar notas de débito
export const useDebitNotes = (params: DebitNotesListParams) => {
  return useQuery({
    queryKey: ['debitNotes', params],
    queryFn: () => debitNotesService.getAll(params),
    staleTime: 1000 * 60 * 5, // 5 minutos
  });
};

// Hook para obtener una nota de débito por ID
export const useDebitNote = (id: number | null) => {
  return useQuery({
    queryKey: ['debitNote', id],
    queryFn: () => debitNotesService.getById(id!),
    enabled: !!id,
    staleTime: 1000 * 60 * 5, // 5 minutos
  });
};

// Hook para crear una nota de débito
export const useCreateDebitNote = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: DebitNoteCreateData) => debitNotesService.create(data),
    onSuccess: (data: any) => {
      toast.success(`Nota de Débito ${data.identifier || 'generada'} correctamente. Se está enviando a SUNAT.`);
      queryClient.invalidateQueries({ queryKey: ['debitNotes'] });
    },
    onError: (error: any) => {
      toast.error(error.response?.data?.detail || 'Error al crear la nota de débito');
    },
  });
};

// Hook para consultar estado SUNAT
export const useDebitNoteSunatStatus = (id: number | null) => {
  return useQuery({
    queryKey: ['debitNoteSunatStatus', id],
    queryFn: () => debitNotesService.checkSunatStatus(id!),
    enabled: !!id,
    refetchInterval: (data) => {
      // Polling cada 30 segundos si está en estado PENDING o SENT
      if (data?.state.data?.sunat_status === 'PENDING' || data?.state.data?.sunat_status === 'SENT') {
        return 30000;
      }
      return false;
    },
    staleTime: 1000 * 15, // 15 segundos
  });
};

// Hook para refrescar estados pendientes
export const useRefreshDebitNotePendingStatuses = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (limit?: number) => debitNotesService.refreshPendingStatuses(limit),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['debitNotes'] });
      queryClient.invalidateQueries({ queryKey: ['debitNoteSunatStatus'] });
      toast.info('Estados SUNAT actualizados');
    },
    onError: () => {
      toast.error('Error al actualizar estados SUNAT');
    },
  });
};

// Hook para anular nota de débito
export const useAnnulDebitNote = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: DebitNoteAnnulData) => debitNotesService.annul(data),
    onSuccess: (data: any) => {
      toast.success(`Nota de Crédito ${data.series}-${String(data.number).padStart(8, '0')} generada para anular la nota de débito.`);
      queryClient.invalidateQueries({ queryKey: ['debitNotes'] });
      queryClient.invalidateQueries({ queryKey: ['creditNotes'] });
    },
    onError: (error: any) => {
      const errorMessage = error.response?.data?.detail?.[0]?.msg || 
                          error.response?.data?.detail || 
                          error.response?.data?.message || 
                          'Error al anular la nota de débito';
      toast.error(errorMessage);
    },
  });
};

// src/features/accounting/debit-notes/pages/DebitNoteAnnulFormPage.tsx

import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useForm, Controller, SubmitHandler } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { toast } from '@/utils/sileo-toast';
import { useQuery } from '@tanstack/react-query';
import { DocumentPlusIcon, ChevronRightIcon } from '@heroicons/react/24/outline';

import { Button } from '../../../../components/common/Button';
import { useCreateDebitNote } from '../hooks/useDebitNotes';
import { DebitNoteCreateData } from '../../types';
import { Invoice, User } from '../../../../types'; 
import { useAccountingDocumentSeriesForBranch } from '../../../../hooks/useAccountingDocumentSeries';
import { authService } from '../../../../services/auth.service';

// Catálogo de motivos para Nota de Débito (Catálogo 10 SUNAT)
const DEBIT_NOTE_REASONS = [
  { code: '01', description: 'Intereses por mora' },
  { code: '02', description: 'Aumento en el valor' },
  { code: '03', description: 'Penalidades/otros conceptos' },
  { code: '10', description: 'Ajustes de operaciones de exportación' },
  { code: '11', description: 'Ajustes afectos al IVAP' },
];

const debitNoteSchema = z.object({
  debit_note_type_code: z.string().nonempty("Debe seleccionar un motivo."),
  reason: z.string().min(10, "El sustento debe tener al menos 10 caracteres."),
  additional_amount: z.number().min(0.01, "El monto adicional debe ser mayor a 0."),
});

type DebitNoteFormData = z.infer<typeof debitNoteSchema>;

export const DebitNoteAnnulFormPage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  // Tipamos explícitamente el estado que esperamos recibir
  const { affectedInvoice } = (location.state as { affectedInvoice: Invoice }) || {};

  const [selectedDebitNoteSeries, setSelectedDebitNoteSeries] = useState<string>("");

  const { mutate: createDebitNote, isPending } = useCreateDebitNote();

  // Hook de usuario actual
  const { data: currentUser } = useQuery<User>({
    queryKey: ['currentUser'],
    queryFn: async (): Promise<User> => {
      const data = await authService.getProfile();
      console.log('DebitNoteAnnulFormPage - Current user data:', data);
      return data;
    },
    staleTime: 1000 * 60 * 5,
    retry: 1
  });

  // Hook para obtener series de notas de débito por branch office
  const {
    availableDebitNoteSeries,
    isLoading: isLoadingSeries,
  } = useAccountingDocumentSeriesForBranch(
    currentUser?.default_branch_office_id || null,
    currentUser?.company_id || 1 // Valor por defecto si no está definido
  );

  const { control, handleSubmit, formState: { errors } } = useForm<DebitNoteFormData>({
    resolver: zodResolver(debitNoteSchema),
    defaultValues: { 
      debit_note_type_code: '01', 
      reason: '',
      additional_amount: 0
    }
  });

  // Efecto para configurar la serie por defecto
  useEffect(() => {
    const cachedSeries = localStorage.getItem("lastUsedDebitNoteSeries");

    if (availableDebitNoteSeries.length > 0) {
      if (cachedSeries && availableDebitNoteSeries.some((s) => s.series_code === cachedSeries)) {
        setSelectedDebitNoteSeries(cachedSeries);
      } else {
        setSelectedDebitNoteSeries(availableDebitNoteSeries[0].series_code);
      }
    }
  }, [availableDebitNoteSeries]);

  // Handler para cambio de serie
  const handleDebitNoteSeriesChange = (seriesCode: string) => {
    setSelectedDebitNoteSeries(seriesCode);
    localStorage.setItem("lastUsedDebitNoteSeries", seriesCode);
  };

  if (!affectedInvoice || !affectedInvoice.client) {
    React.useEffect(() => {
      toast.error("No se ha especificado una factura válida para crear nota de débito.");
      navigate('/accounting/debit-notes/new'); // Redirigir a selección de factura
    }, [navigate]);
    return null;
  }

  const onSubmit: SubmitHandler<DebitNoteFormData> = (data) => {
    if (!selectedDebitNoteSeries) {
      toast.error("Debe seleccionar una serie para la nota de débito");
      return;
    }

    // Para nota de débito, necesitamos crear con estructura completa
    const payload: DebitNoteCreateData = {
      company_id: currentUser?.company_id || 1,
      client_id: affectedInvoice.client?.id || 0,
      document_type_code: '08', // Siempre 08 para notas de débito
      series: selectedDebitNoteSeries,
      issue_date: new Date().toISOString().split('T')[0], // Fecha actual
      issue_time: new Date().toTimeString().split(' ')[0], // Hora actual
      currency_code: "PEN",
      affected_document_type_code: affectedInvoice.document_type_code || "01",
      affected_document_series_number: `${affectedInvoice.series}-${String(affectedInvoice.number).padStart(8,'0')}`,
      debit_note_type_code: data.debit_note_type_code,
      reason: data.reason,
      items: [
        {
          product_id: 1, // ID de producto genérico - debería venir de configuración
          quantity: 1,
          unit_code: 'NIU', // Unidad común
          unit_price: data.additional_amount,
          price_with_tax: data.additional_amount,
          price_type_code: "01",
          tax_category_code: "20" // Siempre exonerado
        }
      ]
    };

    createDebitNote(payload, {
      onSuccess: () => {
        // Redirigir a una página de listado de notas de débito
        navigate('/accounting/debit-notes'); 
      }
    });
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-start gap-4">
        <div className="hidden sm:flex h-12 w-12 items-center justify-center rounded-[12px] bg-[#1F4690]/10">
          <DocumentPlusIcon className="h-6 w-6 text-[#1F4690]" strokeWidth={1.5} />
        </div>
        <div>
          <h1 className="text-[32px] font-medium text-dm-text-primary tracking-[-0.64px] leading-[1.19]" style={{ fontFamily: "'Inter', sans-serif" }}>
            Crear Nota de Débito
          </h1>
          <p className="mt-1 text-[15px] text-dm-text-secondary leading-[1.33]">
            {affectedInvoice.series}-{String(affectedInvoice.number).padStart(8, '0')} — {affectedInvoice.client.name}
          </p>
        </div>
      </div>

      <div className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary p-4 lg:p-5">
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
          <div>
            <label className="block text-[12px] font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">Serie de la Nota de Débito*</label>
            {isLoadingSeries ? (
              <div className="block w-full px-3 py-2.5 bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] text-[14px] text-dm-text-muted">
                Cargando series...
              </div>
            ) : availableDebitNoteSeries.length > 0 ? (
              <div className="relative">
                <select
                  value={selectedDebitNoteSeries}
                  onChange={(e) => handleDebitNoteSeriesChange(e.target.value)}
                  className="peer block w-full appearance-none px-3 py-2.5 bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] text-[14px] text-dm-text-primary focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-all pr-10"
                >
                  {availableDebitNoteSeries.map((series) => (
                    <option key={series.id} value={series.series_code}>
                      {series.series_code} - Nota de Débito
                    </option>
                  ))}
                </select>
                <ChevronRightIcon className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-dm-text-muted rotate-90 pointer-events-none transition-transform duration-200 peer-focus:-rotate-90" />
              </div>
            ) : (
              <div className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary p-4">
                <p className="text-[13px] text-[#cf1322]">No hay series de notas de débito disponibles para esta sucursal</p>
              </div>
            )}
          </div>

          <div>
            <label className="block text-[12px] font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">Motivo de la Nota de Débito*</label>
            <Controller
              name="debit_note_type_code"
              control={control}
              render={({ field }) => (
                <div className="relative">
                  <select {...field} className="peer block w-full appearance-none px-3 py-2.5 bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] text-[14px] text-dm-text-primary focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-all pr-10">
                    {DEBIT_NOTE_REASONS.map(reason => (
                      <option key={reason.code} value={reason.code}>{reason.description}</option>
                    ))}
                  </select>
                  <ChevronRightIcon className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-dm-text-muted rotate-90 pointer-events-none transition-transform duration-200 peer-focus:-rotate-90" />
                </div>
              )}
            />
            {errors.debit_note_type_code && <p className="mt-1 text-[13px] text-[#cf1322]">{errors.debit_note_type_code.message}</p>}
          </div>

          <div>
            <label className="block text-[12px] font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">Monto Adicional (S/)*</label>
            <Controller
              name="additional_amount"
              control={control}
              render={({ field }) => (
                <input
                  {...field}
                  type="number"
                  step="0.01"
                  min="0.01"
                  className="block w-full px-3 py-2.5 bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] text-[14px] text-dm-text-primary placeholder:text-dm-text-muted focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-all"
                  placeholder="0.00"
                  onChange={(e) => field.onChange(parseFloat(e.target.value))}
                />
              )}
            />
            {errors.additional_amount && <p className="mt-1 text-[13px] text-[#cf1322]">{errors.additional_amount.message}</p>}
          </div>

          <div>
            <label className="block text-[12px] font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">Descripción / Sustento*</label>
            <Controller
              name="reason"
              control={control}
              render={({ field }) => (
                <textarea
                  {...field}
                  rows={4}
                  className="block w-full px-3 py-2.5 bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] text-[14px] text-dm-text-primary placeholder:text-dm-text-muted focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-all resize-none"
                  placeholder="Ej: Intereses por mora según contrato..."
                />
              )}
            />
            {errors.reason && <p className="mt-1 text-[13px] text-[#cf1322]">{errors.reason.message}</p>}
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-dm-border-secondary">
            <Button type="button" variant="outline" onClick={() => navigate(-1)} className="rounded-full px-4 py-2.5 bg-dm-bg-primary border border-dm-border-primary text-[14px] font-medium text-dm-text-primary hover:bg-dm-bg-secondary">Cancelar</Button>
            <Button 
              type="submit" 
              isLoading={isPending}
              disabled={!selectedDebitNoteSeries || availableDebitNoteSeries.length === 0}
              className="rounded-full px-5 py-2.5 bg-[#1F4690] hover:bg-[#163672] text-white text-[14px] font-medium"
            >
              Generar Nota de Débito
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

