export const InvoiceDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [showPdfError, setShowPdfError] = useState(false);
  const [showWhatsAppModal, setShowWhatsAppModal] = useState(false);
  const [showEditSeatModal, setShowEditSeatModal] = useState(false);
  const [showEditPaymentModal, setShowEditPaymentModal] = useState(false);
  const [showRequestCancellationModal, setShowRequestCancellationModal] = useState(false);
  const [activeTab, setActiveTab] = useState<'ticket80mm' | 'a4' | 'sticker100x100'>('ticket80mm');
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isGeneratingSticker, setIsGeneratingSticker] = useState(false);
  const pdfIframeRef = useRef<HTMLIFrameElement>(null);
  const { hasPermission } = usePermissions();
  const currentUser = authService.getCurrentUser();

  const invoiceId = Number(id);

  // Usamos el servicio real para obtener los datos
  const { data: invoice, isLoading, error, dataUpdatedAt } = useQuery({
    queryKey: ['invoice', invoiceId],
    queryFn: () => invoicesService.getById(invoiceId),
    enabled: !isNaN(invoiceId), // Solo ejecuta si el ID es un número válido
    staleTime: 1000 * 30, // Cache por 30 segundos
  });

  // Obtener las solicitudes del vendedor para esta factura
  const { data: vendorRequests = [] } = useQuery({
    queryKey: ['my-cancellation-requests'],
    queryFn: () => cancellationRequestsService.getMyRequests({ limit: 200 }),
    enabled: currentUser?.role_name?.toLowerCase() === 'sales',
    staleTime: 1000 * 30,
  });

  // Encontrar la solicitud más reciente para esta factura
  const requestForThisInvoice = vendorRequests.find(req => req.invoice_id === invoiceId);

  // Determinar si el botón debe estar habilitado
  const canRequestCancellation = invoice && 
    currentUser?.role_name?.toLowerCase() === 'sales' &&
    invoice.sunat_status === 'ACCEPTED' &&
    currentUser?.supervisor_id &&
    (!requestForThisInvoice || requestForThisInvoice.status === 'REJECTED');

  // Determinar el mensaje de tooltip
  const getRequestCancellationTooltip = (): string => {
    if (invoice?.sunat_status !== 'ACCEPTED') {
      return 'Solo se pueden solicitar anulaciones de facturas ACEPTADAS';
    }
    if (!currentUser?.supervisor_id) {
      return 'No tienes supervisor asignado';
    }
    if (requestForThisInvoice?.status === 'PENDING') {
      return 'Ya existe una solicitud pendiente para este comprobante';
    }
    if (requestForThisInvoice?.status === 'APPROVED') {
      return 'Este comprobante ya fue anulado satisfactoriamente';
    }
    return 'Solicitar anulación al supervisor';
  };

  const handleAnular = () => {
    if (!invoice) return;

    if (invoice.sunat_status !== 'ACCEPTED') {
      toast.warn(`No se puede anular una factura con estado "${invoice.sunat_status}".`);
      return;
    }

    // Navegamos al formulario de la Nota de Crédito, pasando la factura completa en el state
    navigate('/accounting/credit-notes/annul', {
      state: {
        affectedInvoice: invoice,
      },
    });
  };

  const handlePrint = () => {
    if (pdfIframeRef.current) {
      try {
        // Intentar imprimir directamente desde el iframe visible
        const iframeWindow = pdfIframeRef.current.contentWindow;
        if (iframeWindow) {
          iframeWindow.print();
        } else {
          throw new Error('No se puede acceder al contenido del iframe');
        }
      } catch (error) {
        console.warn('Error al imprimir desde iframe:', error);
        // Fallback: abrir en nueva ventana
        try {
          const basePdfUrl = activeTab === 'sticker100x100'
            ? invoice?.pdf_sticker_100x100_file_path
            : activeTab === 'ticket80mm' ? invoice?.pdf_ticket_file_path : invoice?.pdf_a4_file_path;
          const backendTimestamp = invoice?.updated_at ? new Date(invoice.updated_at).getTime() : 0;
          const cacheBuster = `${backendTimestamp}_${Date.now()}`;
          const pdfUrl = basePdfUrl ? `${basePdfUrl}?v=${cacheBuster}` : basePdfUrl;
          const printWindow = window.open(pdfUrl ?? undefined, '_blank', 'width=800,height=600');
          if (printWindow) {
            printWindow.onload = () => {
              try {
                printWindow.print();
              } catch (fallbackError) {
                toast.info('Haz clic en "Imprimir" en la ventana que se abrió');
              }
            };
          } else {
            toast.error('El navegador bloqueó la ventana emergente');
          }
        } catch (fallbackError) {
          toast.error('Error al abrir el PDF para imprimir');
        }
      }
    } else {
      toast.error('El visor PDF no está disponible');
    }
  };

  const handleDownload = () => {
    let basePdfUrl: string | null | undefined;
    let fileName: string;

    if (activeTab === 'sticker100x100') {
      basePdfUrl = invoice?.pdf_sticker_100x100_file_path;
      fileName = `sticker-100x100-${invoice?.series}-${String(invoice?.number).padStart(8, '0')}.pdf`;
    } else {
      basePdfUrl = activeTab === 'ticket80mm' ? invoice?.pdf_ticket_file_path : invoice?.pdf_a4_file_path;
      fileName = activeTab === 'ticket80mm'
        ? `ticket-${invoice?.series}-${String(invoice?.number).padStart(8, '0')}.pdf`
        : `ticket-a4-${invoice?.series}-${String(invoice?.number).padStart(8, '0')}.pdf`;
    }

    const backendTimestamp = invoice?.updated_at ? new Date(invoice.updated_at).getTime() : 0;
    const cacheBuster = `${backendTimestamp}_${Date.now()}`;
    const pdfUrl = basePdfUrl ? `${basePdfUrl}?v=${cacheBuster}` : basePdfUrl;

    if (pdfUrl) {
      // Crear enlace de descarga
      const link = document.createElement('a');
      link.href = pdfUrl;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } else {
      const label = activeTab === 'ticket80mm' ? '80mm' : activeTab === 'a4' ? 'A4' : '100x100';
      toast.error(`No hay ticket ${label} disponible para descargar`);
    }
  };

  /**
   * Genera o regenera el sticker de encomienda 100x100mm
   */
  const handleGenerateSticker100x100 = async () => {
    if (!invoice || isGeneratingSticker) return;

    setIsGeneratingSticker(true);
    try {
      await invoicesService.generateSticker100x100(invoiceId);
      await queryClient.invalidateQueries({ queryKey: ['invoice', invoiceId] });
      toast.success('Sticker 100x100 generado exitosamente');
    } catch (error) {
      console.error('Error generando sticker 100x100:', error);
      toast.error(
        error instanceof Error ? error.message : 'Error al generar el sticker.'
      );
    } finally {
      setIsGeneratingSticker(false);
    }
  };

  const handleWhatsAppClick = () => {
    setShowWhatsAppModal(true);
  };

  /**
   * Regenera ambos PDFs (80mm y A4) desde el backend
   * Útil cuando los tickets no se generaron correctamente o se perdió la conexión
   */
  const handleRegeneratePdfs = async () => {
    if (!invoice || isRegenerating) return;

    setIsRegenerating(true);
    setShowPdfError(false);

    try {
      // force=true para sobreescribir el archivo aunque ya exista en el CDN
      await invoicesService.generateBothPdfs(invoiceId, true);

      // Invalidar y refetch la query para obtener las nuevas URLs
      await queryClient.invalidateQueries({ queryKey: ['invoice', invoiceId] });

      toast.success('Tickets regenerados exitosamente');
    } catch (error) {
      console.error('Error regenerando tickets:', error);
      toast.error(
        error instanceof Error 
          ? error.message 
          : 'Error al regenerar los tickets. Por favor, intente nuevamente.'
      );
      setShowPdfError(true);
    } finally {
      setIsRegenerating(false);
    }
  };

  /**
   * Regenera SOLO el PDF del tab activo (80mm, A4 o 100x100).
   * Útil cuando Bunny CDN no almacenó el archivo a tiempo.
   */
  const handleRegenerateCurrentPdf = async () => {
    if (!invoice || isRegenerating) return;
    setIsRegenerating(true);
    setShowPdfError(false);
    try {
      let size: '80mm' | 'a4' | '100x100';
      if (activeTab === 'sticker100x100') {
        size = '100x100';
      } else if (activeTab === 'a4') {
        size = 'a4';
      } else {
        size = '80mm';
      }
      // force=true para sobreescribir el archivo aunque ya exista en el CDN
      await invoicesService.generatePdf(invoiceId, size, true);
      await queryClient.invalidateQueries({ queryKey: ['invoice', invoiceId] });
      toast.success(`Ticket ${activeTab === 'ticket80mm' ? '80mm' : activeTab === 'a4' ? 'A4' : '100x100'} regenerado exitosamente`);
    } catch (error) {
      console.error('Error regenerando PDF:', error);
      toast.error(
        error instanceof Error
          ? error.message
          : 'Error al regenerar el ticket. Por favor, intente nuevamente.'
      );
      setShowPdfError(true);
    } finally {
      setIsRegenerating(false);
    }
  };

  if (isLoading) return <div className="flex justify-center p-8"><Spinner size="lg" /></div>;
  if (error) return <div className="p-6 text-center text-red-600 dark:text-red-400">Error al cargar la factura: {error instanceof Error ? error.message : 'Error desconocido'}</div>;
  if (!invoice) return <div className="p-6 text-center text-dm-text-muted">No se encontró la factura.</div>;

  const hasTicketPdf = invoice.pdf_ticket_file_path && invoice.pdf_ticket_file_path.trim() !== '';
  const hasA4Pdf = invoice.pdf_a4_file_path && invoice.pdf_a4_file_path.trim() !== '';
  const hasStickerPdf = Boolean(invoice.pdf_sticker_100x100_file_path && invoice.pdf_sticker_100x100_file_path.trim() !== '');
  const hasAnyPdf = hasTicketPdf || hasA4Pdf ||
                    (invoice.pdf_file_path && invoice.pdf_file_path.trim() !== '');

  // Detectar si es una encomienda/cargo (heurística centralizada en getSaleKind;
  // el chequeo de sticker PDF se mantiene aquí para conservar el mismo resultado)
  const isCargoInvoice = getSaleKind(invoice) === 'encomienda' || hasStickerPdf;

  // Usar invoice.updated_at del backend como cache buster principal
  const backendTimestamp = invoice.updated_at ? new Date(invoice.updated_at).getTime() : 0;
  const cacheBuster = `${backendTimestamp}_${dataUpdatedAt}`;

  // Determinar el PDF actual según el tab activo
  let basePdfUrl: string | null | undefined;
  if (activeTab === 'sticker100x100') {
    basePdfUrl = invoice.pdf_sticker_100x100_file_path;
  } else {
    basePdfUrl = activeTab === 'ticket80mm' ? invoice.pdf_ticket_file_path : invoice.pdf_a4_file_path;
  }
  const currentPdfUrl = basePdfUrl ? `${basePdfUrl}?v=${cacheBuster}` : basePdfUrl;
  const hasCurrentPdf = activeTab === 'ticket80mm' ? hasTicketPdf
    : activeTab === 'a4' ? hasA4Pdf
    : hasStickerPdf;

  return (
    <div className="min-h-screen bg-dm-bg-secondary">
      {/* Header con información básica */}
      <div className="bg-dm-bg-primary shadow-sm border-b border-dm-border-primary">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
            <div className="flex flex-col md:flex-row items-start md:items-center space-y-4 md:space-y-0 md:space-x-4">
              <Button
                variant="outline"
                size="sm"
                onClick={() => navigate('/accounting/invoices')}
                className="flex items-center"
              >
                <ArrowLeftIcon className="h-4 w-4 mr-2" />
                Volver a Facturas
              </Button>
              <div className="border-l-0 md:border-l pl-0 md:pl-4 mt-4 md:mt-0">
                <h1 className="text-xl font-bold text-dm-text-primary">
                  {invoice.document_type_code === '01' ? 'Factura' : 'Boleta'} {invoice.series}-{String(invoice.number).padStart(8, '0')}
                </h1>
                <div className="flex flex-wrap items-center gap-2 mt-1">
                  <InvoiceStatusBadge 
                    sunatStatus={invoice.sunat_status} 
                    businessStatus={invoice.business_status}
                  />
                  <span className="text-sm text-dm-text-muted">
                    {formatIssueDate(invoice.issue_date)}
                  </span>
                  <span className="text-sm text-dm-text-muted">•</span>
                  <span className="text-sm text-dm-text-primary font-medium">
                    {getCurrencySymbol(invoice.currency_code)} {Number(invoice.total_payable).toFixed(2)}
                  </span>
                  <span className="text-sm text-dm-text-muted">•</span>
                  <span className="text-sm text-dm-text-secondary">
                    {getInvoicePaymentSummary(invoice)}
                  </span>
                </div>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-2 mt-4 md:mt-0">
              {/* Botón Imprimir / Descargar - solo si hay PDF del tab activo */}
              {(hasTicketPdf || hasA4Pdf) && (
                <>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handlePrint}
                    disabled={isRegenerating}
                    className="flex items-center"
                  >
                    <PrinterIcon className="h-4 w-4 mr-2" />
                    Imprimir
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleDownload}
                    disabled={isRegenerating}
                    className="flex items-center"
                  >
                    <ArrowDownTrayIcon className="h-4 w-4 mr-2" />
                    Descargar
                  </Button>
                </>
              )}

              {/* Botón Regenerar ─ siempre visible para forzar regeneración del tab activo */}
              <Button
                variant="outline"
                size="sm"
                onClick={handleRegenerateCurrentPdf}
                disabled={isRegenerating}
                className="flex items-center text-amber-600 dark:text-amber-400 border-amber-300 hover:bg-amber-50 dark:hover:bg-amber-950/30"
                title={`Regenerar ticket ${
                  activeTab === 'ticket80mm' ? '80mm' :
                  activeTab === 'a4' ? 'A4' : '100x100'
                } (usar si el archivo da error o no cargó)`}
              >
                <ArrowPathIcon className={`h-4 w-4 mr-2 ${isRegenerating ? 'animate-spin' : ''}`} />
                {isRegenerating
                  ? 'Regenerando...'
                  : `Regenerar ${
                      activeTab === 'ticket80mm' ? '80mm' :
                      activeTab === 'a4' ? 'A4' : '100x100'
                    }`}
              </Button>

              {/* Botón WhatsApp - disponible si hay cualquier tipo de PDF */}
              {hasAnyPdf && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleWhatsAppClick}
                  className="flex items-center text-green-600 dark:text-green-400 border-green-300 hover:bg-green-50 dark:hover:bg-green-950/30"
                  title="Enviar por WhatsApp"
                >
                  <MessageCircle className="h-4 w-4 mr-2" />
                  WhatsApp
                </Button>
              )}

              {/* Botón Editar asiento - solo para boletas/facturas de pasajeros, no encomiendas */}
              {!isCargoInvoice && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setShowEditSeatModal(true)}
                  className="flex items-center text-blue-600 dark:text-blue-400 border-blue-300 hover:bg-blue-50 dark:hover:bg-blue-950/30"
                  title="Editar asiento del pasajero"
                  disabled={!hasPermission('accounting', 'invoices', 'sales')}
                >
                  <PencilIcon className="h-4 w-4 mr-2" />
                  Editar
                </Button>
              )}

              {currentUser?.role_name?.toLowerCase() === 'sales' && (
                <Button
                  variant="danger"
                  size="sm"
                  onClick={() => setShowRequestCancellationModal(true)}
                  disabled={!canRequestCancellation}
                  title={getRequestCancellationTooltip()}
                >
                  Solicitar Anulación
                </Button>
              )}

              <Button
                variant="danger"
                size="sm"
                onClick={handleAnular}
                disabled={
                  invoice.sunat_status !== 'ACCEPTED' ||
                  !hasPermission('accounting', 'invoices', 'sales') ||
                  (currentUser?.role_name?.toLowerCase() === 'sales' &&
                    (requestForThisInvoice?.status === 'PENDING' || requestForThisInvoice?.status === 'APPROVED'))
                }
                title={
                  invoice.sunat_status !== 'ACCEPTED'
                    ? 'Solo se pueden anular facturas ACEPTADAS'
                    : !hasPermission('accounting', 'invoices', 'sales')
                    ? 'No tienes permisos para anular facturas'
                    : requestForThisInvoice?.status === 'PENDING'
                    ? 'Ya tienes una solicitud pendiente — usa el botón "Solicitar Anulación"'
                    : requestForThisInvoice?.status === 'APPROVED'
                    ? 'Este comprobante ya fue aprobado para anulación'
                    : 'Anular este comprobante'
                }
              >
                Anular
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Contenido principal */}
      <div className="max-w-7xl mx-auto px-4 py-6">
        <div className="grid grid-cols-1 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)] gap-4">
          {/* Columna izquierda: panel de información de la venta */}
          <div>
            <SaleInfoPanel
              invoice={invoice}
              onEditPayment={() => setShowEditPaymentModal(true)}
              canEditPayment={hasPermission('accounting', 'invoices', 'sales')}
            />
          </div>

          {/* Columna derecha: preview del ticket (movida tal cual, sin cambios de lógica) */}
          <div>
        {/* Sección principal del visor:
             - Siempre se muestra para facturas que no son 100% encomienda
             - También se muestra si hay cualquier PDF disponible */}
        {(!isCargoInvoice || hasTicketPdf || hasA4Pdf || hasStickerPdf) ? (
          <div className="bg-dm-bg-primary rounded-lg shadow-sm border border-dm-border-primary">
            {/* Header del visor PDF */}
            <div className="px-6 py-4 border-b border-dm-border-primary bg-dm-bg-secondary rounded-t-lg">
              <div className="flex items-center justify-between gap-3">
                <div className="flex items-center space-x-2 flex-shrink-0">
                  <DocumentTextIcon className="h-5 w-5 text-blue-600 dark:text-blue-400" />
                  <h2 className="font-semibold text-dm-text-primary">Ticket de Venta</h2>
                </div>
                <div
                  className="text-sm text-dm-text-muted min-w-0 truncate"
                  title={invoice.client?.name ?? undefined}
                >
                  Cliente: {invoice.client?.name}
                </div>
              </div>
            </div>

            {/* Tabs para seleccionar formato
                 - Para facturas normales: siempre se muestran 80mm y A4
                   (aunque el PDF no exista aún, para que el usuario pueda regenerarlo)
                 - Sticker 100x100: solo si es encomienda */}
            <div className="px-4 sm:px-6 pt-4">
              <div className="flex border-b border-dm-border-primary overflow-x-auto">
                {/* Tab 80mm: siempre visible para facturas/boletas normales */}
                {!isCargoInvoice && (
                  <button
                    onClick={() => {
                      setActiveTab('ticket80mm');
                      setShowPdfError(false);
                    }}
                    className={`px-4 sm:px-6 py-3 text-sm font-medium transition-colors whitespace-nowrap shrink-0 ${
                      activeTab === 'ticket80mm'
                        ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                        : 'text-dm-text-muted hover:text-dm-text-secondary'
                    }`}
                  >
                    <span className="hidden sm:inline">Ticket 80mm (Térmico)</span>
                    <span className="sm:hidden">80mm</span>
                  </button>
                )}
                {/* Tab 80mm para encomiendas (solo si existe) */}
                {isCargoInvoice && hasTicketPdf && (
                  <button
                    onClick={() => {
                      setActiveTab('ticket80mm');
                      setShowPdfError(false);
                    }}
                    className={`px-4 sm:px-6 py-3 text-sm font-medium transition-colors whitespace-nowrap shrink-0 ${
                      activeTab === 'ticket80mm'
                        ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                        : 'text-dm-text-muted hover:text-dm-text-secondary'
                    }`}
                  >
                    <span className="hidden sm:inline">Ticket 80mm (Térmico)</span>
                    <span className="sm:hidden">80mm</span>
                  </button>
                )}
                {/* Tab A4: siempre visible para facturas/boletas normales */}
                {!isCargoInvoice && (
                  <button
                    onClick={() => {
                      setActiveTab('a4');
                      setShowPdfError(false);
                    }}
                    className={`px-4 sm:px-6 py-3 text-sm font-medium transition-colors whitespace-nowrap shrink-0 ${
                      activeTab === 'a4'
                        ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                        : 'text-dm-text-muted hover:text-dm-text-secondary'
                    }`}
                  >
                    <span className="hidden sm:inline">Ticket A4 (Corporativo)</span>
                    <span className="sm:hidden">A4</span>
                  </button>
                )}
                {/* Tab A4 para encomiendas (solo si existe) */}
                {isCargoInvoice && hasA4Pdf && (
                  <button
                    onClick={() => {
                      setActiveTab('a4');
                      setShowPdfError(false);
                    }}
                    className={`px-4 sm:px-6 py-3 text-sm font-medium transition-colors whitespace-nowrap shrink-0 ${
                      activeTab === 'a4'
                        ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                        : 'text-dm-text-muted hover:text-dm-text-secondary'
                    }`}
                  >
                    <span className="hidden sm:inline">Ticket A4 (Corporativo)</span>
                    <span className="sm:hidden">A4</span>
                  </button>
                )}
                {isCargoInvoice && (
                  <button
                    onClick={() => {
                      setActiveTab('sticker100x100');
                      setShowPdfError(false);
                    }}
                    className={`px-4 sm:px-6 py-3 text-sm font-medium transition-colors flex items-center gap-1 whitespace-nowrap shrink-0 ${
                      activeTab === 'sticker100x100'
                        ? 'border-b-2 border-orange-500 text-orange-600 dark:text-orange-400'
                        : 'text-dm-text-muted hover:text-dm-text-secondary'
                    }`}
                  >
                    <Tag className="h-3.5 w-3.5 shrink-0" />
                    <span className="hidden sm:inline">Sticker 100x100</span>
                    <span className="sm:hidden">100x100</span>
                  </button>
                )}
              </div>
            </div>

            {/* Visor PDF */}
            <div className="p-4 sm:p-6">
              <div className="relative bg-dm-bg-secondary rounded-lg overflow-hidden min-h-[300px] md:min-h-[600px]">
                {!showPdfError && hasCurrentPdf ? (
                  activeTab === 'sticker100x100' ? (
                    <div className="flex justify-center p-3 sm:p-4">
                      <div className="w-full max-w-[420px]">
                        <iframe
                          ref={pdfIframeRef}
                          key={`${activeTab}-${cacheBuster}`}
                          src={`${currentPdfUrl}#toolbar=0&navpanes=0&scrollbar=0`}
                          className="w-full border-0 rounded-lg shadow-sm min-h-[300px] md:min-h-[420px]"
                          title={`Sticker 100x100 ${invoice.series}-${String(invoice.number).padStart(8, '0')}`}
                          onError={() => setShowPdfError(true)}
                        />
                      </div>
                    </div>
                  ) : (
                    <iframe
                      ref={pdfIframeRef}
                      key={`${activeTab}-${cacheBuster}`}
                      src={`${currentPdfUrl}#toolbar=1&navpanes=0&scrollbar=1`}
                      className="w-full h-full border-0 min-h-[350px] md:min-h-[600px]"
                      title={`Ticket ${
                        activeTab === 'ticket80mm' ? '80mm' : 'A4'
                      } ${invoice.series}-${String(invoice.number).padStart(8, '0')}`}
                      onError={() => setShowPdfError(true)}
                    />
                  )
                ) : (
                  <div className="flex flex-col items-center justify-center min-h-[300px] md:min-h-[600px] text-dm-text-muted">
                    <ExclamationTriangleIcon className="h-12 w-12 mb-4 text-amber-400" />
                    <h3 className="text-lg font-medium mb-2 text-dm-text-primary">
                      {activeTab === 'sticker100x100'
                        ? 'Sticker 100x100 no disponible'
                        : `Ticket ${activeTab === 'ticket80mm' ? '80mm' : 'A4'} no disponible`}
                    </h3>
                    <p className="text-sm text-center text-dm-text-muted max-w-sm">
                      El archivo no se encontró o no se generó correctamente.
                      Usa el botón <strong>Regenerar</strong> en la barra superior para solicitarlo de nuevo al servidor.
                    </p>
                  </div>
                )}
              </div>
            </div>
          </div>
        ) : (
          // Fallback: mostrar información básica si no hay PDF
          <div className="bg-dm-bg-primary rounded-lg shadow-sm border border-dm-border-primary p-6">
            <div className="text-center py-12">
              <DocumentTextIcon className="h-16 w-16 text-dm-text-muted mx-auto mb-4" />
              <h3 className="text-lg font-medium text-dm-text-primary mb-2">
                Ticket no disponible
              </h3>
              <p className="text-dm-text-muted mb-4">
                No se encontró el archivo PDF del ticket para esta factura.
              </p>

              {/* Botón para regenerar tickets */}
              <Button
                variant="primary"
                size="md"
                onClick={handleRegeneratePdfs}
                disabled={isRegenerating}
                className="flex items-center mx-auto mb-6"
              >
                <ArrowPathIcon className={`h-5 w-5 mr-2 ${isRegenerating ? 'animate-spin' : ''}`} />
                {isRegenerating ? 'Regenerando tickets...' : 'Regenerar Tickets'}
              </Button>

              {/* Mostrar información básica de la factura */}
              <div className="max-w-2xl mx-auto text-left">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6">
                  <div>
                    <h4 className="font-semibold text-dm-text-secondary mb-2">Cliente</h4>
                    <p className="text-dm-text-primary">{invoice.client?.name}</p>
                    <p className="text-dm-text-secondary">{invoice.client?.doc_type === '6' ? 'RUC' : 'DNI'}: {invoice.client?.doc_number}</p>
                  </div>
                  <div>
                    <h4 className="font-semibold text-dm-text-secondary mb-2">Totales</h4>
                    <p className="text-dm-text-secondary">Subtotal: S/ {Number(invoice.total_taxable).toFixed(2)}</p>
                    <p className="text-dm-text-secondary">IGV: S/ {Number(invoice.total_igv).toFixed(2)}</p>
                    <p className="text-lg font-bold text-dm-text-primary">Total: {getCurrencySymbol(invoice.currency_code)} {Number(invoice.total_payable).toFixed(2)}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
          </div>
        </div>
      </div>

      {/* Modal de WhatsApp */}
      {showWhatsAppModal && invoice && (
        <WhatsAppSendModal
          isOpen={showWhatsAppModal}
          onClose={() => setShowWhatsAppModal(false)}
          backendData={invoice as unknown as BackendInvoiceData}
          initialPhoneNumber={invoice.client?.phone || ''}
          isFromInvoiceList={true}
          preferredPdfType={activeTab === 'a4' ? 'a4' : 'ticket'}
        />
      )}

      {/* Modal de solicitud de anulación al supervisor */}
      {showRequestCancellationModal && invoice && (
        <SellerCancellationRequestModal
          invoiceId={invoice.id}
          invoiceSeries={invoice.series}
          invoiceNumber={invoice.number}
          onClose={() => setShowRequestCancellationModal(false)}
          onSuccess={() => {
            queryClient.invalidateQueries({ queryKey: ['invoice', invoiceId] });
            queryClient.invalidateQueries({ queryKey: ['my-cancellation-requests'] });
          }}
        />
      )}

      {/* Modal de Editar Asiento */}
      {showEditSeatModal && invoice && (
        <EditSeatModal
          isOpen={showEditSeatModal}
          onClose={() => setShowEditSeatModal(false)}
          onSuccess={() => {
            // Refrescar la factura después de editar
            queryClient.invalidateQueries({ queryKey: ['invoice', invoiceId] });
          }}
          invoiceSeries={invoice.series}
          invoiceNumber={invoice.number}
          invoiceId={invoiceId}
        />
      )}

      {/* Modal de Editar Métodos de Pago */}
      {showEditPaymentModal && invoice && (
        <EditPaymentMethodsModal
          isOpen={showEditPaymentModal}
          onClose={() => setShowEditPaymentModal(false)}
          onSuccess={() => {
            queryClient.invalidateQueries({ queryKey: ['invoice', invoiceId] });
          }}
          invoiceId={invoiceId}
          invoiceSeries={invoice.series}
          invoiceNumber={invoice.number}
          totalPayable={Number(invoice.total_payable)}
          currencyCode={invoice.currency_code}
          initialPaymentData={invoiceToSplitPaymentData(invoice)}
        />
      )}
    </div>
  );
};

// src/features/accounting/pages/InvoicesListPage.tsx

import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { toast } from '@/utils/sileo-toast';
import { format, parseISO } from 'date-fns';
import {
  MagnifyingGlassIcon,
  EyeIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  PlusIcon,
  MinusIcon,
  CodeBracketIcon,
  ArrowDownTrayIcon,
  XMarkIcon,
  DocumentTextIcon,
} from '@heroicons/react/24/outline';
import { Button } from '../../../components/common/Button';
import { DataTable, Column } from '../../../components/common/DataTable';
import { Input } from '../../../components/common/Input';
import { useDebounce } from '../../../hooks/useDebounce';
import { InvoiceStatusBadge } from '../components/InvoiceStatusBadge';
import { DateRangeFilter, DateFilterOption } from '../../dashboard/components/DateRangeFilter';
import { invoicesService, InvoiceFilters } from '../../../services/invoices.service';
import { Invoice } from '../../../types';
import { getCurrencySymbol } from '../../../utils/currency';

export const InvoicesListPage: React.FC = () => {
  const navigate = useNavigate();

  // Estados para los filtros
  const [clientSearch, setClientSearch] = useState('');
  const [sunatStatusFilter, setSunatStatusFilter] = useState('');

  // Filtros de fecha (usando DateRangeFilter)
  const [dateOption, setDateOption] = useState<DateFilterOption>('custom');
  const [startDate, setStartDate] = useState<Date | null>(null);
  const [endDate, setEndDate] = useState<Date | null>(null);

  const [series, setSeries] = useState('');
  const [documentNumber, setDocumentNumber] = useState('');

  // Estados para paginación
  const [currentPage, setCurrentPage] = useState(0);
  const [itemsPerPage] = useState(20);

  const debouncedClientSearch = useDebounce(clientSearch, 300);
  const debouncedSeries = useDebounce(series, 300);
  const debouncedDocumentNumber = useDebounce(documentNumber, 300);

  // TODO: Obtener company_id del contexto de autenticación
  const companyId = 1;

  // Construir filtros para la API
  const filters: InvoiceFilters = useMemo(() => {
    const baseFilters: InvoiceFilters = {
      company_id: companyId,
      skip: currentPage * itemsPerPage,
      limit: itemsPerPage,
    };

    if (debouncedClientSearch) baseFilters.client_search = debouncedClientSearch;
    if (sunatStatusFilter) baseFilters.sunat_status = sunatStatusFilter as any;

    if (startDate) baseFilters.start_date = format(startDate, 'yyyy-MM-dd');
    if (endDate) baseFilters.end_date = format(endDate, 'yyyy-MM-dd');

    if (debouncedSeries) baseFilters.series = debouncedSeries;
    if (debouncedDocumentNumber) baseFilters.number = parseInt(debouncedDocumentNumber) || undefined;

    return baseFilters;
  }, [companyId, currentPage, itemsPerPage, debouncedClientSearch, sunatStatusFilter, startDate, endDate, debouncedSeries, debouncedDocumentNumber]);

  const { data: invoices = [], isLoading } = useQuery({
    queryKey: ['invoices', filters],
    queryFn: () => invoicesService.getInvoices(filters),
    staleTime: 1000 * 60, // Cache por 1 minuto - se invalida automaticamente al cambiar filtros
  });

  // Limpiar filtros y resetear paginación cuando cambia la fecha
  const handleDateChange = (newStart: Date | null, newEnd: Date | null) => {
    setStartDate(newStart);
    setEndDate(newEnd);
    setCurrentPage(0);
  };

  const handleOptionChange = (option: DateFilterOption) => {
    setDateOption(option);
    setCurrentPage(0);
  };

  // Funciones para manejar cambios en filtros que deben resetear la paginación
  const handleClientSearchChange = (value: string) => {
    setClientSearch(value);
    setCurrentPage(0);
  };

  const handleSunatStatusChange = (value: string) => {
    setSunatStatusFilter(value);
    setCurrentPage(0);
  };

  const handleSeriesChange = (value: string) => {
    setSeries(value);
    setCurrentPage(0);
  };

  const handleDocumentNumberChange = (value: string) => {
    setDocumentNumber(value);
    setCurrentPage(0);
  };

  const handleClearFilters = () => {
    setClientSearch('');
    setSunatStatusFilter('');
    setSeries('');
    setDocumentNumber('');
    setDateOption('custom');
    setStartDate(null);
    setEndDate(null);
    setCurrentPage(0);
  };

  // Función para navegar entre páginas
  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  // Componente de paginación simple
  const PaginationControls = () => {
    const hasNextPage = invoices.length === itemsPerPage; // Si recibimos el límite completo, probablemente hay más páginas
    const hasPrevPage = currentPage > 0;

    return (
      <div className="flex items-center justify-between px-6 py-3.5 bg-dm-bg-secondary border-t border-dm-border-primary">
        <div className="flex items-center text-[12px] text-dm-text-muted">
          <span>
            Página {currentPage + 1} • Mostrando {invoices.length} registros
          </span>
        </div>
        <div className="flex items-center gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => handlePageChange(currentPage - 1)}
            disabled={!hasPrevPage}
            className="flex items-center rounded-full px-4"
          >
            <ChevronLeftIcon className="h-4 w-4 mr-1" />
            Anterior
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => handlePageChange(currentPage + 1)}
            disabled={!hasNextPage}
            className="flex items-center rounded-full px-4"
          >
            Siguiente
            <ChevronRightIcon className="h-4 w-4 ml-1" />
          </Button>
        </div>
      </div>
    );
  };

  const getDocumentTypeLabel = (code: string) => {
    const types: Record<string, string> = {
      '01': 'Factura',
      '03': 'Boleta',
      '07': 'Nota de Crédito',
      '08': 'Nota de Débito'
    };
    return types[code] || code;
  };

  /** Nombre de archivo SUNAT si viene en la URL (p. ej. .../20478966653-03-B0D1-00000584.xml). */
  const getSignedXmlDownloadFileName = (invoice: Invoice): string => {
    const url = invoice.signed_xml_file_path;
    if (!url) return `${invoice.series}-${String(invoice.number).padStart(8, '0')}.xml`;
    try {
      const last = new URL(url).pathname.split('/').filter(Boolean).pop();
      if (last?.toLowerCase().endsWith('.xml')) return last;
    } catch {
      /* URL inválida: usar respaldo */
    }
    return `${invoice.series}-${String(invoice.number).padStart(8, '0')}.xml`;
  };

  /**
   * Descarga el XML al disco: primero el backend (mismo origen, sin CORS); si falla, intento directo al CDN
   * (solo funciona si el CDN expone CORS al origen del panel).
   */
  const downloadSignedXmlToDisk = async (invoice: Invoice) => {
    const url = invoice.signed_xml_file_path;
    const fallbackName = getSignedXmlDownloadFileName(invoice);
    try {
      let blob: Blob;
      let fileName = fallbackName;

      try {
        const r = await invoicesService.fetchSignedXmlBlob(invoice.id);
        blob = r.blob;
        if (r.fileNameFromHeader) fileName = r.fileNameFromHeader;
      } catch {
        if (!url) throw new Error('NO_XML_SOURCE');
        blob = await invoicesService.getPublicCdnFileBlob(url);
      }

      const objectUrl = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = objectUrl;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(objectUrl);
    } catch {
      toast.warning(
        'No se pudo descargar el XML. El almacenamiento en CDN no permite leer el archivo desde el panel (CORS). Hace falta el endpoint GET /sunat/invoices/{id}/signed-xml en el backend o habilitar CORS en Bunny. Mientras tanto use Ctrl+S en la previsualización.'
      );
    }
  };

  /**
   * Ventana emergente para leer el XML. No usar noopener en la cadena de features: en Chromium
   * window.open devuelve null aunque la ventana se haya abierto, y el toast de “bloqueada” es un falso positivo.
   * En paralelo intenta la descarga automática al disco.
   */
  const handlePreviewSignedXml = (invoice: Invoice) => {
    const url = invoice.signed_xml_file_path;
    if (!url) return;
    const preview = window.open(url, '_blank', 'width=960,height=720');
    if (!preview) {
      toast.error('El navegador bloqueó la ventana emergente. Permite ventanas emergentes para este sitio.');
    }
    void downloadSignedXmlToDisk(invoice);
  };

  const columns: Column<Invoice>[] = [
    {
      key: 'document',
      header: 'Documento',
      accessor: (invoice: Invoice) => (
        <div>
          <div className="font-medium text-dm-text-primary">
            {getDocumentTypeLabel(invoice.document_type_code)}
          </div>
          <div className="text-[12px] text-dm-text-muted">
            {invoice.series}-{String(invoice.number).padStart(8, '0')}
          </div>
        </div>
      ),
    },
    {
      key: 'client',
      header: 'Cliente',
      className: 'max-w-[160px] xl:max-w-[220px]',
      accessor: (invoice: Invoice) => (
        <div className="max-w-[160px] xl:max-w-[220px]">
          <div
            className="font-medium text-dm-text-primary truncate"
            title={invoice.client?.name || 'Cliente no disponible'}
          >
            {invoice.client?.name || 'Cliente no disponible'}
          </div>
          <div className="text-[12px] text-dm-text-muted truncate" title={invoice.client?.doc_number}>
            {invoice.client?.doc_number}
          </div>
        </div>
      ),
    },
    {
      key: 'issue_date',
      header: 'Fecha',
      accessor: (invoice: Invoice) => (
        <div className="text-[13px] text-dm-text-secondary">
          {format(parseISO(invoice.issue_date), 'dd/MM/yyyy')}
        </div>
      ),
    },
    {
      key: 'sunat_status',
      header: 'Estado SUNAT / Negocio',
      accessor: (invoice: Invoice) => (
        <InvoiceStatusBadge 
          sunatStatus={invoice.sunat_status} 
          businessStatus={invoice.business_status}
        />
      ),
    },
    {
      key: 'amount',
      header: 'Monto',
      accessor: (invoice: Invoice) => (
        <div className="text-right">
          <div className="font-medium text-dm-text-primary">
            {getCurrencySymbol(invoice.currency_code)} {invoice.total_payable}
          </div>
        </div>
      ),
    },
  ];

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-start sm:items-center gap-3">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <div className="flex items-center justify-center w-9 h-9 rounded-[8px] bg-[#1F4690]/10">
              <DocumentTextIcon className="w-5 h-5 text-[#1F4690]" />
            </div>
            <h1 className="text-[22px] font-semibold text-dm-text-primary tracking-tight">
              Facturas
            </h1>
          </div>
          <p className="text-[14px] text-dm-text-muted">Gestión de comprobantes electrónicos</p>
        </div>
      </header>

      {/* Filtros */}
      <div className="bg-dm-bg-primary p-5 rounded-[12px] border border-dm-border-primary flex flex-col gap-5">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="w-full md:w-auto">
            <label className="block text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider mb-2">
              Rango de fechas
            </label>
            <DateRangeFilter
              startDate={startDate}
              endDate={endDate}
              onDateChange={handleDateChange}
              selectedOption={dateOption}
              onOptionChange={handleOptionChange}
            />
          </div>

          {(clientSearch || sunatStatusFilter || series || documentNumber || startDate || endDate) && (
            <div className="flex justify-end self-end md:self-auto mb-1">
              <Button
                variant="outline"
                size="sm"
                onClick={handleClearFilters}
                className="text-dm-text-secondary bg-dm-bg-primary hover:bg-dm-bg-secondary border-dm-border-primary flex items-center mb-0 md:mt-6 rounded-full px-4"
              >
                <XMarkIcon className="w-4 h-4 mr-2" />
                Limpiar Filtros
              </Button>
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5 pt-4 border-t border-dm-border-primary">
          <div>
            <label className="block text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider mb-2">
              Cliente
            </label>
            <div className="relative">
              <MagnifyingGlassIcon className="h-4 w-4 text-dm-text-muted absolute left-3.5 top-1/2 -translate-y-1/2" />
              <Input
                type="text"
                placeholder="DNI, RUC o nombre..."
                value={clientSearch}
                onChange={(e) => handleClientSearchChange(e.target.value)}
                className="pl-10 bg-dm-bg-secondary border-dm-border-primary focus:bg-dm-bg-primary transition-colors rounded-[12px]"
              />
            </div>
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider mb-2">
              Serie
            </label>
            <Input
              type="text"
              placeholder="Ej: F001, B001..."
              value={series}
              onChange={(e) => handleSeriesChange(e.target.value)}
              className="bg-dm-bg-secondary border-dm-border-primary focus:bg-dm-bg-primary transition-colors uppercase rounded-[12px]"
            />
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider mb-2">
              Número
            </label>
            <Input
              type="number"
              placeholder="Número correlativo"
              value={documentNumber}
              onChange={(e) => handleDocumentNumberChange(e.target.value)}
              className="bg-dm-bg-secondary border-dm-border-primary focus:bg-dm-bg-primary transition-colors rounded-[12px]"
            />
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider mb-2">
              Estado SUNAT
            </label>
            <select
              value={sunatStatusFilter}
              onChange={(e) => handleSunatStatusChange(e.target.value)}
              className="w-full px-4 py-2.5 border border-dm-border-primary rounded-[12px] bg-dm-bg-secondary focus:bg-dm-bg-primary focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-colors text-[14px] text-dm-text-primary"
            >
              <option value="">Todos los estados</option>
              <option value="PENDING">Pendiente</option>
              <option value="GENERATED">Generado</option>
              <option value="SIGNED">Firmado</option>
              <option value="SENT">Enviado</option>
              <option value="ACCEPTED">Aceptado</option>
              <option value="REJECTED">Rechazado</option>
              <option value="OBSERVED">Observado</option>
              <option value="VOIDED">Anulado</option>
              <option value="ERROR">Error</option>
            </select>
          </div>
        </div>
      </div>

      {/* Tabla */}
      <div className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary overflow-hidden">
        <DataTable
          columns={columns}
          data={invoices}
          isLoading={isLoading}
          keyExtractor={(item) => item.id}
          customActions={(invoice) => (
            <div className="flex items-center justify-end gap-1">
              <button
                onClick={() => navigate(`/accounting/invoices/${invoice.id}`)}
                title="Ver detalle"
                className="flex items-center justify-center w-8 h-8 rounded-full text-dm-text-muted hover:text-[#1F4690] hover:bg-[#1F4690]/5 transition-colors"
              >
                <EyeIcon className="h-4 w-4" />
              </button>

              {invoice.signed_xml_file_path && (
                <button
                  onClick={() => handlePreviewSignedXml(invoice)}
                  title="Previsualizar XML y descargar archivo"
                  className="flex items-center justify-center w-8 h-8 rounded-full text-dm-text-muted hover:text-[#1F4690] hover:bg-[#1F4690]/5 transition-colors"
                >
                  <CodeBracketIcon className="h-4 w-4" />
                </button>
              )}

              {invoice.cdr_file_path && (
                <button
                  onClick={() => window.open(invoice.cdr_file_path!, '_blank')}
                  title="Descargar CDR"
                  className="flex items-center justify-center w-8 h-8 rounded-full text-dm-text-muted hover:text-[#1F4690] hover:bg-[#1F4690]/5 transition-colors"
                >
                  <ArrowDownTrayIcon className="h-4 w-4" />
                </button>
              )}

              {invoice.sunat_status === 'ACCEPTED' && invoice.business_status !== 'CANCELLED' && (
                <>
                  <button
                    onClick={() => navigate(`/accounting/credit-notes/new?invoice_id=${invoice.id}`)}
                    title="Crear Nota de Crédito"
                    className="flex items-center justify-center w-8 h-8 rounded-full text-red-500 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/30 transition-colors"
                  >
                    <MinusIcon className="h-4 w-4" />
                  </button>

                  {invoice.business_status !== 'INCREASED' && (
                    <button
                      onClick={() => navigate(`/accounting/debit-notes/new?invoice_id=${invoice.id}`)}
                      title="Crear Nota de Débito"
                      className="flex items-center justify-center w-8 h-8 rounded-full text-emerald-600 dark:text-emerald-400 hover:bg-emerald-50 dark:hover:bg-emerald-950/30 transition-colors"
                    >
                      <PlusIcon className="h-4 w-4" />
                    </button>
                  )}
                </>
              )}
            </div>
          )}
          emptyMessage={
            clientSearch || series || documentNumber || sunatStatusFilter || startDate || endDate || dateOption !== 'custom'
              ? 'No se encontraron facturas con los filtros aplicados'
              : 'No se encontraron facturas'
          }
        />

        {/* Controles de paginación */}
        {!isLoading && invoices.length > 0 && <PaginationControls />}
      </div>
    </div>
  );
};

// src/features/accounting/services/creditNotes.service.ts

import api from '../../../config/api';
import { CreditNote } from '../../../types';
import { pdfTasksService, GeneratePdfResponse } from '../../../services/pdfTasks.service';
import { 
  CreditNoteCreateData, 
  CreditNoteAnnulData,
  CreditNotesListParams, 
  CreditNoteResponse,
  SunatStatusResponse,
  VoidableInvoice 
} from '../types';

class CreditNotesService {
  // Crear nota de crédito (endpoint principal)
  async create(data: CreditNoteCreateData): Promise<CreditNoteResponse> {
    const response = await api.post<CreditNoteResponse>('/sunat/credit-notes/', data);
    return response.data;
  }

  // Crear nota de crédito por anulación (endpoint alternativo)
  async createByAnnulment(data: CreditNoteAnnulData): Promise<CreditNoteResponse> {
    const response = await api.post<CreditNoteResponse>('/sunat/credit-notes/annul', data);
    return response.data;
  }

  // Listar notas de crédito (actualizado según documentación)
  async getAll(params: CreditNotesListParams): Promise<CreditNote[]> {
    const response = await api.get('/sunat/credit-notes/', { 
      params: {
        company_id: params.company_id,
        skip: params.skip || 0,
        limit: params.limit || 50,
        sunat_status: params.sunat_status,
        issue_date: params.issue_date,
        series: params.series
      }
    });

    // Según la documentación, la respuesta tiene formato: 
    // { credit_notes: [...], total: 0, skip: 0, limit: 0, message: "..." }
    if (response.data && response.data.credit_notes && Array.isArray(response.data.credit_notes)) {
      return response.data.credit_notes;
    }

    // Fallback para otros formatos
    if (response.data && Array.isArray(response.data)) {
      return response.data;
    }

    // Si no es array, devolver array vacío para evitar errores
    return [];
  }

  // Obtener una nota de crédito por ID
  async getById(id: number): Promise<CreditNote> {
    const response = await api.get<CreditNote>(`/sunat/credit-notes/${id}`);
    return response.data;
  }

  /**
   * Genera u obtiene el PDF de la nota de crédito.
   * Maneja la respuesta inteligente del backend (completed vs uploading + polling).
   */
  async generatePdf(id: number, size: '80mm' | 'a4' = 'a4'): Promise<string> {
    const response = await api.post<GeneratePdfResponse>(
      `/sunat/credit-notes/${id}/generate-pdf`,
      null,
      { params: { size } }
    );

    const data = response.data;

    // Respuesta rápida: Bunny terminó dentro del tiempo de espera del backend
    if (data.status === 'completed' && data.url) {
      return data.url;
    }

    // Respuesta lenta: hacer polling desde frontend
    if (data.task_id) {
      const url = await pdfTasksService.pollForUrl(data.task_id);
      if (url) return url;
    }

    // Fallback: obtener URL directamente de la nota de crédito actualizada
    const updatedNote = await this.getById(id);
    const fallbackUrl = size === 'a4'
      ? (updatedNote as any).pdf_a4_file_path
      : (updatedNote as any).pdf_ticket_file_path;
    if (fallbackUrl) return fallbackUrl;

    throw new Error(`No se pudo obtener la URL del PDF ${size} para la NC ${id}`);
  }

  // Consultar estado SUNAT de una nota de crédito
  async checkSunatStatus(id: number): Promise<SunatStatusResponse> {
    const response = await api.get<SunatStatusResponse>(`/sunat/tickets/documents/credit_note/${id}/status`);
    return response.data;
  }

  // Refrescar estados pendientes (útil para polling)
  async refreshPendingStatuses(limit: number = 10): Promise<void> {
    await api.post(`/sunat/documents/credit_note/refresh-pending?limit=${limit}`);
  }

  // Obtener facturas que pueden ser anuladas (para crear NC)
  async getVoidableInvoices(companyId: number): Promise<VoidableInvoice[]> {
    // En lugar de usar un endpoint específico, usamos el listado de facturas
    // filtradas por estado ACCEPTED (que son las que se pueden anular)
    const response = await api.get('/sunat/invoices/', {
      params: {
        company_id: companyId,
        sunat_status: 'ACCEPTED', // Solo facturas aceptadas por SUNAT
        limit: 100 // Límite razonable para selección
      }
    });

    // Convertir las facturas al formato esperado por VoidableInvoice
    const invoices = response.data?.invoices || response.data || [];

    const mappedInvoices = invoices.map((invoice: any) => {
      // Intentar obtener client_id de múltiples fuentes
      let clientId = 0;
      let clientName = 'N/A';

      // Prioridad 1: client_id directo
      if (invoice.client_id && invoice.client_id !== 0) {
        clientId = invoice.client_id;
      }
      // Prioridad 2: client.id
      else if (invoice.client?.id && invoice.client.id !== 0) {
        clientId = invoice.client.id;
      }

      // Obtener nombre del cliente
      if (invoice.client?.name) {
        clientName = invoice.client.name;
      } else if (invoice.client_name) {
        clientName = invoice.client_name;
      }

      return {
        id: invoice.id,
        series: invoice.series,
        number: invoice.number,
        document_type_code: invoice.document_type_code,
        client_id: clientId,
        client_name: clientName,
        total_payable: invoice.total_payable?.toString() || '0.00',
        issue_date: invoice.issue_date,
        currency_code: invoice.currency_code || 'PEN',
        business_status: invoice.business_status || 'ACTIVE' // Campo añadido
      };
    });

    return mappedInvoices;
  }
}

export const creditNotesService = new CreditNotesService();

// src/features/auth/hooks/useAuth.ts
import { useQuery } from '@tanstack/react-query';
import { authService } from '../../../services/auth.service';
import { User } from '../../../types';

export const useAuth = () => {
  const { data: user, isLoading, error } = useQuery<User>({
    queryKey: ['currentUser'],
    queryFn: async (): Promise<User> => {
      try {
        const data = await authService.getProfile();
        return data;
      } catch (error: any) {
        console.error('Error al obtener el perfil del usuario:', error);
        throw error;
      }
    },
    staleTime: 1000 * 60 * 5, // 5 minutos
    retry: 1
  });

  const isAuthenticated = authService.isAuthenticated();

  return {
    user,
    isLoading,
    error,
    isAuthenticated
  };
};

// src/features/cargo/components/CargoItemForm.tsx

import React, { useEffect, useMemo, useRef } from 'react';
import { useForm, Controller } from 'react-hook-form';
import { toast } from '@/utils/sileo-toast';
import Select from 'react-select';
import { Search } from 'lucide-react';

import { Button } from '../../../components/common/Button';
import { Spinner } from '../../../components/common/Spinner';
import { ClientSearchAutocomplete } from '../../../components/common/ClientSearchAutocomplete';
import { useProductsServicesData } from '../../fluvial/hooks/useProductsServicesData';
import { useSunatData } from '../../fluvial/hooks/useSunatData';
import { Client } from '../../../types';
import { CargoItemData } from '../types/cargo-ui.types';
import { DOCUMENT_TYPES, SunatDocType } from '../../fluvial/types/sunat.types';

interface CargoItemFormProps {
  onSubmit: (item: CargoItemData) => void;
  onClose: () => void;
  existingItem?: CargoItemData | null;
  defaultRecipient?: import('../types/cargo-ui.types').RecipientData;
}

type FormValues = Omit<CargoItemData, 'id'>;

const UNIT_OF_MEASURE_OPTIONS = [
  { code: 'ZZ', name: 'Unidad (para servicios)' },
  { code: 'KGM', name: 'Kilogramo' },
  { code: 'PAQ', name: 'Paquete' },
  { code: 'XBX', name: 'Caja' },
  { code: 'TNE', name: 'Tonelada' },
  { code: 'MTR', name: 'Metro' },
  { code: 'MTQ', name: 'Metro Cúbico' },
  { code: 'LTR', name: 'Litro' },
];

/* ── Tokens de diseño (DESIGN.md) ── */
const COLORS = {
  midnight: 'var(--text-primary)',
  canvas: 'var(--bg-primary)',
  slateMist: 'var(--bg-secondary)',
  cloudWhisper: 'var(--bg-secondary)',
  darkShale: 'var(--text-secondary)',
  silverAsh: 'var(--text-muted)',
  lightPearl: 'var(--border-primary)',
  sunset: '#ff682c',
};

const FONT = {
  inter: "'Inter', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  heading: "'Saira', 'Montserrat', ui-sans-serif, system-ui, sans-serif",
};

export const CargoItemForm: React.FC<CargoItemFormProps> = ({
  onSubmit,
  onClose,
  existingItem,
  defaultRecipient,
}) => {
  const { data: allServices = [], isLoading: isLoadingServices } = useProductsServicesData({ is_active: true });
  const { queryDni, isQueryingDni, queryRuc, isQueryingRuc } = useSunatData();
  const cargoServicePrefillAppliedRef = useRef(false);

  const {
    register,
    handleSubmit,
    control,
    watch,
    setValue,
    getValues,
    formState: { errors },
  } = useForm<FormValues>({
    defaultValues: {
      product: existingItem?.product || undefined,
      quantity: existingItem?.quantity || 1,
      description: existingItem?.description || '',
      price: existingItem?.price ?? undefined,
      recipient:
        existingItem?.recipient ||
        defaultRecipient || {
          isSameAsSender: true,
          name: '',
          docType: SunatDocType.DNI,
          docNumber: '',
          phone: '',
        },
      unitOfMeasure: existingItem?.unitOfMeasure || 'ZZ',
    },
  });

  const selectedProduct = watch('product');
  const isSameAsSender = watch('recipient.isSameAsSender');
  const recipientDocType = watch('recipient.docType');

  const isFormLocked = !selectedProduct;

  const cargoServices = useMemo(() => {
    if (!allServices || allServices.length === 0) return [];

    const filtered = allServices.filter((service) => {
      const category = service.service_category?.toUpperCase() || '';
      return category.includes('ENCOMIENDA') || category.includes('CARGA');
    });

    const rank = (service: (typeof filtered)[0]) => {
      const c = service.service_category?.toUpperCase() || '';
      if (c.includes('ENCOMIENDA')) return 0;
      if (c.includes('CARGA')) return 1;
      return 2;
    };

    return [...filtered].sort((a, b) => {
      const d = rank(a) - rank(b);
      if (d !== 0) return d;
      return (a.id ?? 0) - (b.id ?? 0);
    });
  }, [allServices]);

  useEffect(() => {
    if (selectedProduct) {
      if (!existingItem) {
        setValue('description', selectedProduct.name);
      }
    }
  }, [selectedProduct, setValue, existingItem]);

  useEffect(() => {
    if (existingItem) {
      cargoServicePrefillAppliedRef.current = false;
      return;
    }
    if (cargoServices.length === 0) return;
    if (cargoServicePrefillAppliedRef.current) return;
    const first = cargoServices[0];
    setValue('product', first);
    setValue('description', first.name);
    cargoServicePrefillAppliedRef.current = true;
  }, [existingItem, cargoServices, setValue]);

  const handleFormSubmit = (data: FormValues) => {
    if (!data.product) {
      toast.error('Debe seleccionar un servicio.');
      return;
    }

    if (!data.recipient.isSameAsSender) {
      if (!data.recipient.name.trim()) {
        toast.error('El nombre del destinatario es obligatorio.');
        return;
      }
      if (!data.recipient.docNumber.trim()) {
        toast.error('El número de documento del destinatario es obligatorio.');
        return;
      }
    }

    onSubmit({
      ...data,
      id: existingItem?.id || crypto.randomUUID(),
    });
  };

  const handleClientSelect = (client: Client) => {
    setValue('recipient.name', client.name, { shouldValidate: true });
    setValue('recipient.docType', client.doc_type, { shouldValidate: true });
    setValue('recipient.docNumber', client.doc_number, { shouldValidate: true });
    setValue('recipient.phone', client.phone || '', { shouldValidate: true });
    toast.success(`Destinatario seleccionado: ${client.name}`);
  };

  const handleRecipientSearch = async () => {
    const docType = getValues('recipient.docType');
    const docNumber = getValues('recipient.docNumber');

    if (!docNumber.trim()) {
      toast.warning('Ingrese un número de documento para buscar.');
      return;
    }

    try {
      if (docType === SunatDocType.DNI) {
        const data = await queryDni(docNumber);
        if (data) {
          setValue('recipient.name', data.nombreCompleto, { shouldValidate: true });
          if (data.phone) {
            setValue('recipient.phone', data.phone, { shouldValidate: true });
          }
          toast.success('Datos encontrados correctamente.');
        }
      } else if (docType === SunatDocType.RUC) {
        const data = await queryRuc(docNumber);
        if (data) {
          setValue('recipient.name', data.razonSocial, { shouldValidate: true });
          if (data.phone) {
            setValue('recipient.phone', data.phone, { shouldValidate: true });
          }
          toast.success('Datos encontrados correctamente.');
        }
      } else {
        toast.info('La búsqueda automática solo está disponible para DNI y RUC.');
      }
    } catch (error) {
      console.error('Error en la búsqueda del destinatario:', error);
    }
  };

  const productOptions = useMemo(
    () =>
      cargoServices.map((service) => ({
        value: service,
        label: service.name,
      })),
    [cargoServices]
  );

  const isRecipientSearchable =
    recipientDocType === SunatDocType.DNI || recipientDocType === SunatDocType.RUC;
  const isQueryingRecipient = isQueryingDni || isQueryingRuc;

  /* ── Estilos react-select alineados con DESIGN.md ── */
  const selectStyles = {
    control: (base: any, state: any) => ({
      ...base,
      borderRadius: 8,
      borderColor: state.isFocused ? COLORS.midnight : COLORS.lightPearl,
      boxShadow: state.isFocused ? `0 0 0 1px ${COLORS.midnight}` : 'none',
      backgroundColor: isFormLocked ? COLORS.cloudWhisper : COLORS.canvas,
      minHeight: 42,
      fontFamily: FONT.inter,
      fontSize: 15,
      color: COLORS.midnight,
      transition: 'all 0.2s ease',
      '&:hover': {
        borderColor: COLORS.midnight,
      },
    }),
    placeholder: (base: any) => ({
      ...base,
      color: COLORS.silverAsh,
      fontFamily: FONT.inter,
      fontSize: 15,
    }),
    singleValue: (base: any) => ({
      ...base,
      color: COLORS.midnight,
      fontFamily: FONT.inter,
      fontSize: 15,
    }),
    menu: (base: any) => ({
      ...base,
      borderRadius: 8,
      border: `1px solid ${COLORS.lightPearl}`,
      boxShadow: 'none',
      fontFamily: FONT.inter,
      fontSize: 15,
      zIndex: 20,
    }),
    option: (base: any, state: any) => ({
      ...base,
      backgroundColor: state.isSelected
        ? COLORS.slateMist
        : state.isFocused
        ? COLORS.cloudWhisper
        : COLORS.canvas,
      color: COLORS.midnight,
      fontFamily: FONT.inter,
      fontSize: 15,
      cursor: 'pointer',
    }),
    noOptionsMessage: (base: any) => ({
      ...base,
      color: COLORS.silverAsh,
      fontFamily: FONT.inter,
      fontSize: 14,
    }),
    loadingMessage: (base: any) => ({
      ...base,
      color: COLORS.silverAsh,
      fontFamily: FONT.inter,
      fontSize: 14,
    }),
  };

  const inputClass = (hasError?: string, locked?: boolean) =>
    `w-full rounded-lg border px-3 py-2.5 text-[15px] transition duration-200 outline-none ${FONT.inter} ` +
    (hasError
      ? 'border-red-400 focus:border-red-500 focus:ring-1 focus:ring-red-500/20 '
      : `border-[${COLORS.lightPearl}] focus:border-primary focus:ring-1 focus:ring-primary/20 `) +
    (locked ? 'bg-dm-bg-secondary text-dm-text-muted cursor-not-allowed ' : 'bg-dm-bg-primary text-dm-text-primary ');

  const labelClass = `block text-sm font-medium mb-1.5 ${FONT.inter}`;

  const sectionClass = `rounded-lg border border-[${COLORS.lightPearl}] bg-dm-bg-primary p-5 space-y-5`;

  return (
    <div className="max-w-2xl mx-auto">
      <form onSubmit={handleSubmit(handleFormSubmit)} className="space-y-6">
        {/* Encabezado */}
        <div className="space-y-1">
          <h2
            className="font-medium tracking-tight"
            style={{
              fontFamily: FONT.heading,
              fontSize: 18,
              lineHeight: 1.25,
              color: COLORS.midnight,
            }}
          >
            {existingItem ? 'Editar ítem de encomienda' : 'Añadir ítem de encomienda'}
          </h2>
          <p
            style={{
              fontFamily: FONT.inter,
              fontSize: 15,
              lineHeight: 1.33,
              color: COLORS.silverAsh,
            }}
          >
            Complete los datos del servicio, cantidad, precio y destinatario.
          </p>
        </div>

        {/* Sección Servicio */}
        <div
          className="rounded-lg border bg-dm-bg-primary p-5 space-y-4"
          style={{ borderColor: COLORS.lightPearl }}
        >
          <div>
            <label
              className={labelClass}
              style={{ color: COLORS.midnight }}
            >
              Servicio de Encomienda/Carga <span style={{ color: COLORS.sunset }}>*</span>
            </label>
            <Controller
              name="product"
              control={control}
              rules={{ required: 'Debe seleccionar un servicio' }}
              render={({ field }) => (
                <Select
                  {...field}
                  options={productOptions}
                  isLoading={isLoadingServices}
                  isDisabled={false}
                  placeholder="Busque y seleccione un servicio…"
                  noOptionsMessage={() => 'No se encontraron servicios de carga/encomienda'}
                  value={
                    field.value
                      ? productOptions.find((opt) => opt.value.id === field.value.id)
                      : null
                  }
                  onChange={(option) => field.onChange(option?.value)}
                  styles={selectStyles}
                />
              )}
            />
            {errors.product && (
              <p
                className="mt-1.5 text-sm"
                style={{ color: '#d9534f', fontFamily: FONT.inter }}
              >
                {errors.product.message}
              </p>
            )}
            {isFormLocked && (
              <p
                className="mt-2 text-sm"
                style={{ color: COLORS.silverAsh, fontFamily: FONT.inter }}
              >
                Seleccione un servicio para activar el resto del formulario.
              </p>
            )}
          </div>

          {/* Cantidad y Precio */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
            <div>
              <label
                className={labelClass}
                style={{ color: COLORS.midnight }}
              >
                Cantidad <span style={{ color: COLORS.sunset }}>*</span>
              </label>
              <input
                type="number"
                min={1}
                step={1}
                disabled={isFormLocked}
                {...register('quantity', {
                  valueAsNumber: true,
                  min: { value: 1, message: 'La cantidad debe ser al menos 1' },
                  required: 'La cantidad es obligatoria',
                })}
                className={inputClass(errors.quantity?.message, isFormLocked)}
                style={{
                  borderColor: errors.quantity ? '#fca5a5' : COLORS.lightPearl,
                }}
              />
              {errors.quantity && (
                <p
                  className="mt-1.5 text-sm"
                  style={{ color: '#d9534f', fontFamily: FONT.inter }}
                >
                  {errors.quantity.message}
                </p>
              )}
            </div>

            <div>
              <label
                className={labelClass}
                style={{ color: COLORS.midnight }}
              >
                Precio Unitario (S/) <span style={{ color: COLORS.sunset }}>*</span>
              </label>
              <input
                type="number"
                step="0.01"
                disabled={isFormLocked}
                {...register('price', {
                  valueAsNumber: true,
                  required: 'El precio es obligatorio',
                  min: { value: 0.01, message: 'El precio debe ser mayor que 0' },
                })}
                className={inputClass(errors.price?.message, isFormLocked)}
                style={{
                  borderColor: errors.price ? '#fca5a5' : COLORS.lightPearl,
                }}
              />
              {errors.price && (
                <p
                  className="mt-1.5 text-sm"
                  style={{ color: '#d9534f', fontFamily: FONT.inter }}
                >
                  {errors.price.message}
                </p>
              )}
            </div>
          </div>

          {/* Unidad de Medida */}
          <div>
            <label
              className={labelClass}
              style={{ color: COLORS.midnight }}
            >
              Unidad de Medida <span style={{ color: COLORS.sunset }}>*</span>
            </label>
            <select
              {...register('unitOfMeasure', {
                required: 'La unidad de medida es obligatoria',
              })}
              disabled={isFormLocked}
              className={inputClass(errors.unitOfMeasure?.message, isFormLocked)}
              style={{
                borderColor: errors.unitOfMeasure ? '#fca5a5' : COLORS.lightPearl,
              }}
            >
              {UNIT_OF_MEASURE_OPTIONS.map((opt) => (
                <option key={opt.code} value={opt.code} disabled={opt.code !== 'ZZ'}>
                  {opt.name}
                  {opt.code !== 'ZZ' ? ' — Deshabilitado temporalmente' : ''}
