                <CreditCard className="h-4 w-4 text-dm-text-muted" />
              </div>
              <div>
                <p className="text-xs font-medium text-dm-text-muted">Método de Pago</p>
                <p className="text-sm font-semibold text-dm-text-primary">
                  {paymentData.payment_method_code}
