                                className="w-full min-w-0 appearance-none rounded-lg border border-dm-border-primary bg-dm-bg-secondary py-3 pl-4 pr-11 text-sm text-dm-text-primary focus:outline-none focus:ring-2 focus:ring-primary/20 disabled:cursor-not-allowed disabled:opacity-50"
                                disabled={
                                  (isRuc
                                    ? availableFacturaSeries.length
                                    : availableBoletaSeries.length) <= 1
                                }
                              >
                                {(isRuc
                                  ? availableFacturaSeries
                                  : availableBoletaSeries
                                ).map((s) => (
                                  <option key={s.id} value={s.series_code}>
                                    {s.series_code} —{" "}
                                    {isRuc
                                      ? "Factura electrónica"
                                      : "Boleta de venta"}
                                  </option>
                                ))}
                              </select>
                              <span
                                className="pointer-events-none absolute inset-y-0 right-0 flex w-11 items-center justify-center rounded-r-lg border-l border-dm-border-primary/60 bg-dm-bg-secondary/95"
                                aria-hidden
                              >
                                <ChevronDown className="h-4 w-4 shrink-0 text-dm-text-muted" />
                              </span>
                            </div>
                            <p className="ml-1 mt-1.5 text-[10px] text-dm-text-muted">
                              Correlativo asignado automáticamente al emitir
                            </p>
                          </div>
                        )}

                        {!isRuc && (
                          <div>
                            <label className="mb-1.5 ml-1 block text-[11px] font-medium uppercase tracking-wider text-dm-text-muted">
                              Descripción
                            </label>
                            <textarea
                              value={itemDescription}
                              onChange={(e) => {
                                if (e.target.value.length <= 500) {
                                  setItemDescription(e.target.value);
                                }
                              }}
                              placeholder="Ej. Servicio de transporte"
                              rows={2}
                              className="w-full rounded-lg border border-dm-border-primary bg-dm-bg-secondary py-3 px-4 text-sm text-dm-text-primary placeholder:text-dm-text-muted focus:outline-none focus:ring-2 focus:ring-primary/20 resize-y min-h-[80px]"
                            />
                            <p className="mt-1 text-[10px] text-dm-text-muted">
                              {(itemDescription || "").length}/500 caracteres
                            </p>
                          </div>
                        )}

                        <CurrencySelector
                          selectedCurrency={selectedCurrency}
                          onCurrencyChange={setCurrency}
                          disabled={isProcessingSale}
                          variant="pills"
                        />
                      </div>
                    </section>

                    <PriceSummary
                      basePrice={basePrice}
                      seatMultiplier={seatMultiplier}
                      extraCost={extraCost}
                      onExtraCostChange={setExtraCost}
                      extraCostDescription={extraCostDescription}
                      onExtraCostDescriptionChange={setExtraCostDescription}
                      isIgvGravado={isIgvGravado}
                      onIgvGravadoChange={setIsIgvGravado}
                      taxCategoryCodeDefault={
                        passengerService?.tax_category_code ?? null
                      }
                      subtotal={subtotal}
                      igvAmount={igvAmount}
                      discount={discount}
                      onDiscountChange={handleDiscountChange}
                      finalTotal={finalTicketPrice}
                      isRuc={isRuc}
                      representativesCount={representatives.length}
                      isManualPriceMode={isManualPriceMode}
                      manualPrice={manualPrice}
                      onManualPriceChange={handleManualPriceChange}
                      editableBasePrice={editableBasePrice}
                      onEditableBasePriceChange={handleEditableBasePriceChange}
                      currencySymbol={getCurrencySymbol()}
                    />

                    <section className="space-y-4 rounded-xl border border-dm-border-primary/80 bg-dm-bg-primary p-5 shadow-sm sm:p-6">
                      <h2 className="text-lg font-bold tracking-tight text-dm-text-primary">
                        Método de Pago
                      </h2>
                      <SplitPaymentForm
                        variant="billing"
                        totalAmount={finalTicketPrice}
                        currencySymbol={getCurrencySymbol()}
                        disabled={isProcessingSale}
                        onPaymentDataChange={handleSplitPaymentChange}
                        onValidationChange={handleSplitPaymentValidationChange}
                        customerName={passengerData.name}
                      />
                    </section>

                    <div className="space-y-2.5 rounded-xl border border-dm-border-primary/80 bg-dm-bg-primary p-4 shadow-sm lg:space-y-3">
                      <h3 className="text-center text-sm font-semibold text-dm-text-secondary lg:text-base">
                        Acciones
                      </h3>

                      <Button
                        onClick={handleOpenConfirmModal}
                        className={`w-full text-base lg:text-lg py-2.5 lg:py-3 ${
                          areActionsEnabled && !isProcessingSale
                            ? "bg-green-600 hover:bg-green-700"
                            : "bg-gray-400 dark:bg-gray-600 cursor-not-allowed"
                        }`}
                        isLoading={
                          isProcessingClient ||
                          isCreatingInvoice ||
                          isAssigningSeat ||
                          isUpdatingReservation ||
                          isCreating ||
                          isProcessingSale
                        }
                        disabled={!areActionsEnabled || isProcessingSale}
                      >
                        <CreditCard className="h-4 w-4 lg:h-5 lg:w-5 mr-2" />
                        <span className="hidden sm:inline">
                          {isConfirmingMode
                            ? "Confirmar y Cobrar"
                            : isRuc
                              ? "Crear Factura Empresarial con Representantes"
                              : "Generar y Cobrar"}
                        </span>
                        <span className="sm:hidden">
                          {isConfirmingMode
                            ? "Confirmar"
                            : isRuc
                              ? "Factura Empresarial"
                              : "Generar"}
                        </span>
                        {!areActionsEnabled && (
                          <span className="ml-2 text-xs opacity-75">
                            (Desactivado)
                          </span>
                        )}
                      </Button>
                      {!isConfirmingMode && showSeatMap && !isRuc && (
                        <Button
                          onClick={() => setReservationModalOpen(true)}
                          variant="outline"
                          className="w-full text-base lg:text-lg py-2.5 lg:py-3"
                          disabled={!areActionsEnabled || isProcessingSale}
                        >
                          <ClipboardDocumentListIcon className="h-4 w-4 lg:h-5 lg:w-5 mr-2" />
                          Reservar Asiento
                        </Button>
                      )}

                      {isRuc && (
                        <Button
                          onClick={() =>
                            setShowRepresentatives(!showRepresentatives)
                          }
                          variant="outline"
                          className="w-full text-base lg:text-lg py-2.5 lg:py-3 border-blue-600 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/30"
                        >
                          <ClipboardDocumentListIcon className="h-4 w-4 lg:h-5 lg:w-5 mr-2" />
                          {showRepresentatives ? "Ocultar" : "Gestionar"}{" "}
                          Representantes
                        </Button>
                      )}
                    </div>

                    <div className="rounded-xl border border-dm-border-primary/80 bg-gradient-to-br from-slate-50/90 to-white dark:from-slate-700 dark:to-slate-800 p-4 shadow-sm">
                      <div className="flex gap-3">
                        <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[#dbe1ff]/90 dark:bg-blue-900/40">
                          <Info
                            className="h-5 w-5 text-primary"
                            aria-hidden
                          />
                        </div>
                        <div className="min-w-0 flex-1">
                          <p className="text-xs font-semibold text-dm-text-primary">
                            Información
                          </p>
                          <p className="mt-1 text-[11px] leading-snug text-dm-text-secondary">
                            Verifique pasajero, tramo y total antes de cobrar.
                            El comprobante usará la serie indicada y el
                            correlativo se asignará al confirmar. Viaje:{" "}
                            <span className="font-medium text-dm-text-primary">
                              {trip.trip_name}
                            </span>
                            .
                          </p>
                        </div>
                      </div>
                    </div>

                    {!basePrice && !isManualPriceMode && (
                      <div className="flex items-center gap-2 text-sm text-orange-600 dark:text-orange-400 bg-orange-50 dark:bg-orange-950/30 p-3 rounded-md">
                        <AlertTriangle className="h-4 w-4" />
                        <span>Seleccione un destino para ver el precio.</span>
                      </div>
                    )}

                    {isManualPriceMode &&
                      (!manualPrice || manualPrice === 0) && (
                        <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 p-3 rounded-md border border-red-200 dark:border-red-800/50">
                          <AlertTriangle className="h-4 w-4" />
                          <span className="font-medium">
                            Ingrese un precio manual para continuar con la
                            venta.
                          </span>
                        </div>
                      )}

                    {finalTicketPrice === 0 && (basePrice || manualPrice) && (
                      <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 p-3 rounded-md border border-red-200 dark:border-red-800/50">
                        <AlertTriangle className="h-4 w-4" />
                        <span className="font-medium">
                          El monto total no puede ser S/ 0.00. Ajuste el precio
                          o el descuento.
                        </span>
                      </div>
                    )}

                    {splitPaymentData.isSplitPayment &&
                      !isSplitPaymentValid && (
                        <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 p-3 rounded-md border border-red-200 dark:border-red-800/50">
                          <AlertTriangle className="h-4 w-4" />
                          <span className="font-medium">
                            Los montos del pago dividido deben sumar exactamente
                            el total ({getCurrencySymbol()}{" "}
                            {finalTicketPrice.toFixed(2)})
                          </span>
                        </div>
                      )}
                  </>
                )}
              </div>
            </div>
          </div>
        </div>

        {selectedSeat && tripDetails && areActionsEnabled && showSeatMap && (
          <ReservationModal
            isOpen={isReservationModalOpen}
            onClose={() => setReservationModalOpen(false)}
            reservationData={{
              trip: tripDetails,
              tripStops: tripDetails.stops,
              selectedSeat,
              passengerData,
              boardingStopId: selectedBoardingStopId!,
              disembarkingStopId: selectedDisembarkingStopId!,
              totalPrice: finalTicketPrice,
            }}
            onSuccess={onSaleSuccess}
          />
        )}

        {showTicketPreview && ticketBackendData && (
          <TicketPreviewModal
            isOpen={showTicketPreview}
            onClose={() => {
              setShowTicketPreview(false);
              setTicketBackendData(null);
            }}
            backendData={ticketBackendData}
            onSuccess={() => {
              setShowTicketPreview(false);
              setTicketBackendData(null);
              onSaleSuccess();
            }}
            initialPhoneNumber={passengerData.phone}
            onClearForm={clearFormAfterSale}
          />
        )}

        <ConfirmSaleModal
          isOpen={isConfirmSaleModalOpen}
          onClose={() => setIsConfirmSaleModalOpen(false)}
          onConfirm={handleConfirmSale}
          isLoading={isProcessingSale}
          totalAmount={finalTicketPrice}
          currencySymbol={getCurrencySymbol()}
          passengerName={passengerData.name}
          saleType={isRuc ? "company" : "normal"}
          tripName={trip.trip_name}
          representativesCount={representatives.length}
        />
      </>
    );
  }
);

SaleForm.displayName = "SaleForm";

// src/features/fluvial/components/sales-point/SeatAndFareSelector.tsx

import React, { useMemo, useEffect, useCallback } from 'react';
import { Spinner } from '../../../../components/common/Spinner';
import { SearchableSelect } from '../../../../components/common/SearchableSelect';
import { useTripDetails } from '../../hooks/useTripDetails';
import { useSeatTypesData } from '../../hooks/useSeatTypesData';
import { useVessel } from '../../hooks/useVesselsData';
import { useSeatMapRealtime } from '../../hooks/useSeatMapRealtime';
import { SeatMapItem, TripStop, SeatReservation } from '../../../../types';
import { SeatMapRealtime } from '../seat-map/SeatMapRealtime';
import { getSeatZoneName } from '../../utils/seatUtils';

interface SeatAndFareSelectorProps {
  tripId: number;
  // Usar stop IDs en lugar de port IDs
  selectedBoardingStopId: number | null;
  onBoardingStopChange: (stopId: number | null) => void;
  selectedDisembarkingStopId: number | null;
  onDisembarkingStopChange: (stopId: number | null) => void;
  selectedSeat: SeatMapItem | null;
  onSeatSelect: (seat: SeatMapItem | null) => void;
  isConfirmingMode?: boolean;
  reservationToConfirm?: SeatReservation;
  // Nuevas props para WebSocket
  userId?: string;
  userName?: string;
  // Nueva prop para asientos ocupados por representantes
  occupiedSeatNumbers?: string[];
  // prop para indicar modo empresa
  isCompanyMode?: boolean;
  // prop para asientos seleccionados de representantes (modo empresa)
  representativeSelectedSeatIds?: number[];
  // Callbacks para exponer funciones del hook useSeatMapRealtime
  onWebSocketReady?: (functions: {
    selectSeatForRepresentative: (seatId: number, representativeIndex: number, representativeName: string) => boolean;
    releaseSeatForRepresentative: (seatId: number, representativeIndex?: number) => boolean;
    confirmPurchase: (seatIds?: number[]) => boolean;
    activeSeatSelections: Map<number, any>;
    seatMap: SeatMapItem[];
    isWebSocketConnected: boolean;
  }) => void;
  // NUEVO: Función para reservar asiento inmediatamente cuando se selecciona en modo representante
  onSeatReserveForRepresentative?: (seatNumber: string, representativeIndex: number) => Promise<boolean>;
  // NUEVO: Función para liberar asiento de representante
  onSeatReleaseForRepresentative?: (representativeIndex: number) => Promise<void>;
  // NUEVO: Índice del representante actual (cuántos representantes ya existen)
  currentRepresentativeIndex?: number;
}

export const SeatAndFareSelector: React.FC<SeatAndFareSelectorProps> = ({
  tripId,
  selectedBoardingStopId,
  onBoardingStopChange,
  selectedDisembarkingStopId,
  onDisembarkingStopChange,
  selectedSeat,
  onSeatSelect,
  isConfirmingMode = false,
  reservationToConfirm,
  userId = 'default-user',
  userName = 'Usuario',
  occupiedSeatNumbers = [],
  isCompanyMode = false,
  representativeSelectedSeatIds = [],
  onWebSocketReady,
  onSeatReserveForRepresentative,
  onSeatReleaseForRepresentative,
  currentRepresentativeIndex = 0,
}) => {
  const { data: tripDetails, isLoading: isLoadingTrip } = useTripDetails(tripId);
  const { isLoading: isLoadingSeatTypes } = useSeatTypesData();

  // Usar el hook useSeatMapRealtime para obtener las funciones necesarias
  const {
    seatMap,
    selectSeatForRepresentative,
    releaseSeatForRepresentative,
    confirmPurchase,
    activeSeatSelections,
    isConnected: isWebSocketConnected,
  } = useSeatMapRealtime({
    tripId,
    userId,
    userName,
    enabled: !isConfirmingMode, // Solo habilitar WebSocket si no está en modo confirmación
    companyName: undefined, // No es modo empresa en este componente
    isCompanyMode, // Pasar el modo empresa
    enableDebugLogs: true, // Habilitar logs de debug para investigar mensajes WebSocket
  });

  // Exponer las funciones del hook al componente padre - Optimizado
  useEffect(() => {
    if (onWebSocketReady && seatMap) {
      onWebSocketReady({
        selectSeatForRepresentative,
        releaseSeatForRepresentative,
        confirmPurchase,
        activeSeatSelections,
        seatMap,
        isWebSocketConnected,
      });
    }
  }, [
    onWebSocketReady,
    seatMap?.length, // Solo la longitud para evitar recreaciones constantes
    isWebSocketConnected,
    // Remover activeSeatSelections y las funciones individuales que cambian frecuentemente
  ]);

  // Obtener información de la embarcación para las configuraciones de asientos
  const vesselId = tripDetails?.vessel?.id;
  const { data: vesselDetails } = useVessel(vesselId || null);

  // Función utilitaria para enriquecer asientos con información de seat_type - Memoizada
  // Esta función compensa la falta de seat_type en la respuesta del backend /seat-map
  // utilizando las configuraciones de embarcación que ya están disponibles
  const enrichSeatWithType = useMemo(() => {
    return (seat: SeatMapItem): SeatMapItem => {
      if (!vesselDetails?.seat_configurations || !seat.vessel_seat_config_id) {
        return seat;
      }

      const seatConfig = vesselDetails.seat_configurations.find(
        config => config.id === seat.vessel_seat_config_id
      );

      if (seatConfig && seatConfig.seat_type) {
        return {
          ...seat,
          seat_type: seatConfig.seat_type
        };
      }

      return seat;
    };
  }, [vesselDetails?.seat_configurations]); // Solo dependencias estables

  // Este efecto se encarga de pre-seleccionar el asiento
  // cuando el formulario está en modo de confirmación de reserva.
  useEffect(() => {
    // 1. Salir temprano si no estamos en modo de confirmación
    if (!isConfirmingMode || !reservationToConfirm) {
      return;
    }

    // 2. Si ya hay un asiento seleccionado con el ID correcto, no es necesario volver a buscarlo.
    if (selectedSeat && selectedSeat.id === reservationToConfirm.trip_seat_id) {
      return;
    }

    // 3. Para el modo de confirmación, necesitaremos buscar el asiento desde el backend
    // ya que el mapa de asientos ahora se maneja en el componente SeatMapRealtime
    // Por ahora, el efecto queda documentado pero la lógica se maneja en el componente hijo
  }, [isConfirmingMode, reservationToConfirm?.id, selectedSeat?.id]); // Ya optimizado

  // Calcular selectedSeats dependiendo del modo empresa
  const selectedSeatsForMap = useMemo((): Set<number> => {
    if (isCompanyMode) {
      // En modo empresa, incluir todos los asientos de representantes + el actual
      const allSelectedIds = [...representativeSelectedSeatIds];
      if (selectedSeat) {
        allSelectedIds.push(selectedSeat.id);
      }
      return new Set(allSelectedIds);
    } else {
      // En modo individual, solo el asiento seleccionado
      return selectedSeat ? new Set([selectedSeat.id]) : new Set();
    }
  }, [isCompanyMode, representativeSelectedSeatIds.length, selectedSeat?.id]); // Ya optimizado

  // Paradas ordenadas por stop_order para garantizar coherencia
  // independientemente del orden en que el backend las devuelva.
  // Esto es crítico cuando se agregan paradas intermedias a una ruta,
  // ya que pueden aparecer al final del arreglo aunque su stop_order sea menor.
  const sortedStops = useMemo((): TripStop[] => {
    if (!tripDetails?.stops) return [];
    return [...tripDetails.stops].sort((a, b) => a.stop_order - b.stop_order);
  }, [tripDetails?.id, tripDetails?.stops?.length]);

  // Calcular stops disponibles para destino basado en el stop de embarque seleccionado
  const { availableStops } = useMemo(() => {
    if (!selectedBoardingStopId || sortedStops.length === 0) {
      return { availableStops: [] };
    }
    const boardingStop = sortedStops.find(s => s.id === selectedBoardingStopId);
    const boardingStopOrder = boardingStop?.stop_order ?? -1;
    const stops = sortedStops.filter(s => s.stop_order > boardingStopOrder);
    return {
      availableStops: stops,
    };
  }, [sortedStops, selectedBoardingStopId]);

  const handleSeatToggleFromMap = useCallback(async (toggledSeat: SeatMapItem) => {
    // Si estamos en modo de confirmación, no se permite ninguna interacción con el mapa.
    if (isConfirmingMode) return;

    // Enriquecer el asiento con información de seat_type
    const enrichedSeat = enrichSeatWithType(toggledSeat);

    //  SOLUCIÓN: Verificar que el asiento no esté siendo usado por otro vendedor
    const existingSelection = activeSeatSelections?.get(enrichedSeat.id);
    if (existingSelection && existingSelection.userId !== userId) {
      // El asiento está siendo usado por otro vendedor, mostrar mensaje y no permitir selección
      console.warn(`Asiento ${enrichedSeat.seat_number} está siendo usado por ${existingSelection.userName}`);
      return;
    }

    const shouldUseRepresentativeFlow = isCompanyMode;

    if (selectedSeat && selectedSeat.id === enrichedSeat.id) {
      // Deseleccionando asiento
      onSeatSelect(null);

      // Solo en modo empresa liberar reserva temporal de representante
      if (shouldUseRepresentativeFlow && onSeatReleaseForRepresentative) {
        await onSeatReleaseForRepresentative(currentRepresentativeIndex);
      }
    } else {
      // Solo en modo empresa, al cambiar asiento, liberar la reserva anterior
      if (shouldUseRepresentativeFlow && selectedSeat && onSeatReleaseForRepresentative) {
        await onSeatReleaseForRepresentative(currentRepresentativeIndex);
      }

      // Solo en modo empresa reservar inmediatamente para representantes
      if (shouldUseRepresentativeFlow && onSeatReserveForRepresentative) {
        const reserved = await onSeatReserveForRepresentative(
          enrichedSeat.seat_number,
          currentRepresentativeIndex
        );

        if (!reserved) {
          // No se pudo reservar, no seleccionar el asiento
          return;
        }
      }

      // Seleccionar asiento
      onSeatSelect(enrichedSeat);
    }
  }, [isConfirmingMode, enrichSeatWithType, selectedSeat?.id, selectedSeat, onSeatSelect, activeSeatSelections, userId, onSeatReserveForRepresentative, onSeatReleaseForRepresentative, currentRepresentativeIndex]);

  // Función para obtener información de zona del asiento seleccionado - Memoizada
  const getSeatZoneInfo = useMemo(() => {
    return (seat: SeatMapItem) => {
      const enrichedSeat = enrichSeatWithType(seat);
      const seatConfig = vesselDetails?.seat_configurations?.find(
        config => config.id === seat.vessel_seat_config_id
      );
      const seatTypeName = seatConfig?.seat_type?.name || enrichedSeat.seat_type?.name;

      // Obtener colores de fondo y texto que contrasten
      const getZoneColorWithText = (typeName?: string | null): { bgColor: string; textColor: string } => {
        if (!typeName) return { bgColor: 'bg-dm-bg-secondary/80 border border-dm-border-primary', textColor: 'text-dm-text-secondary' };

        const name = typeName.toLowerCase();
        if (name.includes('reclinable')) return { bgColor: 'bg-green-100 dark:bg-green-900/40 border border-green-200 dark:border-green-800', textColor: 'text-green-800 dark:text-green-300' };
        if (name.includes('estático')) return { bgColor: 'bg-yellow-100 dark:bg-yellow-900/40 border border-yellow-200 dark:border-yellow-800', textColor: 'text-yellow-800 dark:text-yellow-300' };
        if (name.includes('premium')) return { bgColor: 'bg-purple-100/80 dark:bg-purple-900/40 border border-purple-200 dark:border-purple-800', textColor: 'text-purple-800 dark:text-purple-300' };
        if (name.includes('vip')) return { bgColor: 'bg-indigo-100 dark:bg-indigo-900/40 border border-indigo-200 dark:border-indigo-800', textColor: 'text-indigo-800 dark:text-indigo-300' };
        if (name.includes('económico') || name.includes('economico')) return { bgColor: 'bg-blue-100 dark:bg-blue-900/40 border border-blue-200 dark:border-blue-800', textColor: 'text-blue-800 dark:text-blue-300' };

        return { bgColor: 'bg-dm-bg-secondary/80 border border-dm-border-primary', textColor: 'text-dm-text-secondary' };
      };

      const { bgColor, textColor } = getZoneColorWithText(seatTypeName);

      return {
        zoneName: getSeatZoneName(enrichedSeat, vesselDetails?.seat_configurations),
        zoneColor: `${bgColor} ${textColor}`,
        seatTypeName
      };
    };
  }, [enrichSeatWithType, vesselDetails?.seat_configurations]); // Dependencias estables

  const isLoading = isLoadingTrip || isLoadingSeatTypes;

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-40">
        <Spinner /><span className="ml-2 text-dm-text-secondary">Cargando...</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <h2 className="text-lg font-semibold text-dm-text-primary">Tramo y Asiento</h2>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 sm:gap-4">
        <SearchableSelect
          label="Origen (Embarque)"
          value={selectedBoardingStopId}
          onChange={(value) => onBoardingStopChange(value ? Number(value) : null)}
          options={sortedStops.slice(0, -1).map(stop => ({
            value: stop.id,
            label: stop.port?.name || 'Sin nombre'
          }))}
          placeholder="Seleccione embarque..."
          disabled={isConfirmingMode}
        />
        <SearchableSelect
          label="Destino (Desembarque)"
          value={selectedDisembarkingStopId}
          onChange={(value) => onDisembarkingStopChange(value ? Number(value) : null)}
          options={availableStops.map(stop => ({
            value: stop.id,
            label: stop.port?.name || 'Sin nombre'
          }))}
          placeholder="Seleccione desembarque..."
          disabled={!selectedBoardingStopId || availableStops.length === 0 || isConfirmingMode}
        />
      </div>

      {selectedSeat && (
        <div className="bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 p-4 rounded-lg">
          <p className="text-sm text-dm-text-secondary text-center mb-3">Asiento Seleccionado</p>
          <div className="flex flex-col sm:flex-row items-center justify-center gap-3 sm:gap-6">
            <div className="text-center">
              <p className="font-bold text-2xl text-blue-700 dark:text-blue-300">
                N° {selectedSeat.seat_number}
              </p>
              <p className="text-xs text-dm-text-muted mt-1">Número</p>
            </div>
            <div className="text-center">
              <div className={`px-4 py-2 rounded-lg text-sm font-semibold shadow-sm ${getSeatZoneInfo(selectedSeat).zoneColor}`}>
                {getSeatZoneInfo(selectedSeat).zoneName}
              </div>
              <p className="text-xs text-dm-text-muted mt-1">Zona</p>
            </div>
          </div>
        </div>
      )}

      <div className="mt-4 border-t pt-4">
        <SeatMapRealtime
          tripId={tripId}
          vesselName={tripDetails?.vessel?.name || 'Embarcación'}
          selectedSeats={selectedSeatsForMap}
          onSeatToggle={handleSeatToggleFromMap}
          isLocked={isConfirmingMode}
          userId={userId}
          userName={userName}
          occupiedSeatNumbers={occupiedSeatNumbers}
          isCompanyMode={isCompanyMode}
          reservationSeatId={isConfirmingMode && reservationToConfirm ? reservationToConfirm.trip_seat_id : undefined}
        />
      </div>
    </div>
  );
};

// src/features/fluvial/components/sales-point/TicketPreviewModal.tsx
// NUEVO: Ahora usa PDFs generados por el backend en lugar de generarlos en frontend

import React, { useState, useEffect } from 'react';
import { Modal } from '../../../../components/common/Modal';
import { Button } from '../../../../components/common/Button';
import { Spinner } from '../../../../components/common/Spinner';
import { Download, Eye, MessageCircle, RefreshCw, Tag } from 'lucide-react';
import { BackendInvoiceData, BackendCompanyInvoiceData } from './tickets/types/backend.types';
import { WhatsAppSendModal } from './WhatsAppSendModal';
import { invoicesService } from '../../../../services/invoices.service';
import { toast } from '@/utils/sileo-toast';
import { getSaleKind } from '../../../../utils/getSaleKind';
import { SaleInfoPanel } from '../../../accounting/components/SaleInfoPanel';
import { EditPaymentMethodsModal } from '../../../accounting/components/EditPaymentMethodsModal';
import { Invoice } from '../../../../types';
import { usePermissions } from '../../../../hooks/usePermissions';
import { invoiceToSplitPaymentData } from '../../../../utils/invoicePaymentMapper';

interface TicketPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  backendData: BackendInvoiceData | BackendCompanyInvoiceData;
  onSuccess: () => void;
  // Número de teléfono inicial para WhatsApp
  initialPhoneNumber?: string;
  // Función para limpiar el formulario cuando se cierre el modal
  onClearForm?: () => void;
  // Mostrar solo el ticket de 80mm (ocultar A4)
  showOnly80mm?: boolean;
}

type TicketFormat = 'ticket80mm' | 'a4' | 'sticker100x100';

export const TicketPreviewModal: React.FC<TicketPreviewModalProps> = ({
  isOpen,
  onClose,
  backendData,
  onSuccess,
  initialPhoneNumber = '',
  onClearForm,
  showOnly80mm = false,
}) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [isGeneratingSticker, setIsGeneratingSticker] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [activeFormat, setActiveFormat] = useState<TicketFormat>('ticket80mm');
  const [previewUrl80mm, setPreviewUrl80mm] = useState<string>('');
  const [previewUrlA4, setPreviewUrlA4] = useState<string>('');
  const [previewUrlSticker100x100, setPreviewUrlSticker100x100] = useState<string>('');
  const [showWhatsAppModal, setShowWhatsAppModal] = useState(false);
  const [generationSuccess, setGenerationSuccess] = useState(false);

  // Extraer invoice ID
  const invoiceId = 'invoice' in backendData ? backendData.invoice.id : backendData.id;
  const invoiceData = 'invoice' in backendData ? backendData.invoice : backendData;

  // Detectar si es una factura de encomienda (cargo) — heurística centralizada
  // en getSaleKind; el chequeo de sticker PDF se mantiene para conservar el
  // mismo resultado que la heurística original.
  const isCargoInvoice =
    getSaleKind(invoiceData) === 'encomienda' ||
    Boolean(invoiceData.pdf_sticker_100x100_file_path);

  // Datos vivos para el panel de resumen: se sincronizan con backendData al
  // abrir y se refrescan tras editar el método de pago (control interno).
  const [panelInvoice, setPanelInvoice] = useState<Invoice>(invoiceData as unknown as Invoice);
  const [showEditPaymentModal, setShowEditPaymentModal] = useState(false);
  const { hasPermission } = usePermissions();

  useEffect(() => {
    if (isOpen) {
      setPanelInvoice(invoiceData as unknown as Invoice);
    }
  }, [isOpen, invoiceData]);

  // Tras guardar la edición de pago: refrescar el detalle para el panel sin
  // cerrar el TicketPreviewModal. El toast de éxito lo emite el modal de edición.
  const handlePaymentUpdated = async () => {
    try {
      const refreshed = await invoicesService.getById(invoiceId);
      setPanelInvoice(refreshed);
    } catch (error) {
      console.error('[TicketPreview] No se pudo refrescar el detalle tras editar el pago.', error);
    }
  };

  // Generar PDFs en el backend cuando se abre el modal
  useEffect(() => {
    if (isOpen && !previewUrl80mm) {
      if (showOnly80mm) {
        generateOnly80mmPdfFromBackend();
      } else {
        generateBothPdfsFromBackend();
      }
    }
  }, [isOpen, showOnly80mm]);

  // Limpiar URLs cuando se cierra el modal
  useEffect(() => {
    if (!isOpen) {
      // Solo limpiar los estados, no hay que revocar URLs porque son URLs remotas
      setPreviewUrl80mm('');
      setPreviewUrlA4('');
      setPreviewUrlSticker100x100('');
      setGenerationSuccess(false);
    }
  }, [isOpen]);

  /**
   * Genera solo el PDF de 80mm (para equipaje extra)
   */
  const generateOnly80mmPdfFromBackend = async () => {
    try {
      setIsGenerating(true);
      setGenerationSuccess(false);

      // generatePdf ya maneja la espera inteligente y retorna la URL directamente
      const url80mm = await invoicesService.generatePdf(invoiceId, '80mm');

      setPreviewUrl80mm(url80mm);
      setGenerationSuccess(true);
      toast.success('Ticket generado exitosamente');
    } catch (error) {
      console.error('Error generando ticket desde el backend:', error);
      toast.error(
        error instanceof Error
          ? error.message
          : 'Error al generar el ticket. Por favor, intente nuevamente.'
      );
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Genera ambos PDFs (80mm y A4) llamando al backend
   */
  const generateBothPdfsFromBackend = async () => {
    try {
      setIsGenerating(true);
      setGenerationSuccess(false);

      // generateBothPdfs llama a generatePdf x2, que ya maneja polling internamente
      const { url80mm, urlA4 } = await invoicesService.generateBothPdfs(invoiceId);

      setPreviewUrl80mm(url80mm);
      setPreviewUrlA4(urlA4);
      setGenerationSuccess(true);
      toast.success('Tickets generados exitosamente');
    } catch (error) {
      console.error('Error generando tickets desde el backend:', error);
      toast.error(
        error instanceof Error
          ? error.message
          : 'Error al generar los tickets. Por favor, intente nuevamente.'
      );
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Genera el sticker de 100x100mm (solo para encomiendas)
   * Se ejecuta de forma lazy cuando el usuario selecciona el tab
   */
  const generateSticker100x100FromBackend = async () => {
    if (previewUrlSticker100x100) return; // Ya generado
    try {
      setIsGeneratingSticker(true);

      // Primero verificar si ya existe la URL en la invoice actual
      const existingUrl = (invoiceData as any).pdf_sticker_100x100_file_path;
      if (existingUrl) {
        setPreviewUrlSticker100x100(existingUrl);
        return;
      }

      // Generar el sticker via backend
      const url = await invoicesService.generateSticker100x100(invoiceId);

      if (!url) {
        throw new Error('Sticker generado pero URL no disponible');
      }

      setPreviewUrlSticker100x100(url);
      toast.success('Sticker 100x100 generado exitosamente');
    } catch (error) {
      console.error('Error generando sticker 100x100:', error);
      toast.error(
        error instanceof Error
          ? error.message
          : 'Error al generar el sticker. Por favor, intente nuevamente.'
      );
    } finally {
      setIsGeneratingSticker(false);
    }
  };

  /**
   * Manejar el cambio de tab — si es el sticker y no está generado, generarlo
   */
  const handleFormatChange = (format: TicketFormat) => {
    setActiveFormat(format);
    if (format === 'sticker100x100' && !previewUrlSticker100x100) {
      generateSticker100x100FromBackend();
    }
  };

  /**
   * Regenerar PDFs (util si hubo error o se quiere actualizar)
   */
  const handleRegeneratePdfs = async () => {
    // Limpiar URLs existentes
    setPreviewUrl80mm('');
    setPreviewUrlA4('');

    // Regenerar según configuración
    if (showOnly80mm) {
      await generateOnly80mmPdfFromBackend();
    } else {
      await generateBothPdfsFromBackend();
    }
  };

  /**
   * Descargar el ticket activo
   */
  const handleDownloadTicket = async () => {
    try {
      setIsDownloading(true);

      let pdfUrl: string | null | undefined;
      let fileName: string;

      if (activeFormat === 'sticker100x100') {
        pdfUrl = previewUrlSticker100x100;
        fileName = `sticker_100x100_${invoiceData.series}-${invoiceData.number}.pdf`;
      } else {
        const size = activeFormat === 'ticket80mm' ? '80mm' : 'a4';
        // Obtener la URL directa del PDF desde la invoice
        const invoice = await invoicesService.getById(invoiceId);
        pdfUrl = size === '80mm' ? invoice.pdf_ticket_file_path : invoice.pdf_a4_file_path;
        fileName = `ticket_${size}_${invoiceData.series}-${invoiceData.number}.pdf`;
      }

      if (!pdfUrl) {
        throw new Error('PDF no disponible');
      }

      // Descargar usando un enlace temporal
      const a = document.createElement('a');
      a.href = pdfUrl;
      a.download = fileName;
      a.target = '_blank'; // Abrir en nueva pestaña si la descarga falla
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);

      toast.success('Ticket descargado exitosamente');
    } catch (error) {
      console.error('Error descargando ticket:', error);
      toast.error('Error al descargar el ticket');
    } finally {
      setIsDownloading(false);
    }
  };

  const handleClose = () => {
    if (!isGenerating && !isGeneratingSticker) {
      onClose();
      onSuccess(); // Forzar recarga del viaje para actualizar estado de asientos
      if (onClearForm) {
        onClearForm();
      }
    }
  };

  return (
    <>
    <Modal
      isOpen={isOpen}
      onClose={handleClose}
      title="Previsualización del Ticket"
      maxWidth="5xl"
    >
      <div className="p-6">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {/* Columna izquierda: resumen de la venta (control interno).
              Scroll propio si es muy largo; el preview queda siempre visible. */}
          <div className="lg:max-h-[80vh] lg:overflow-y-auto lg:pr-1">
            <SaleInfoPanel
              invoice={panelInvoice}
              onEditPayment={() => setShowEditPaymentModal(true)}
              canEditPayment={hasPermission('accounting', 'invoices', 'sales')}
              showEmission={false}
            />
          </div>

          {/* Columna derecha: preview del ticket (siempre visible) */}
          <div>
        {/* Mostrar numero de Encomienda si existe */}
        {invoiceData.items && 
         invoiceData.items.length > 0 && 
         invoiceData.items[0].parcel_number && 
         (invoiceData.items[0].product_name?.toLowerCase().includes('encomienda') || 
          invoiceData.items[0].item_description?.toLowerCase().includes('encomienda')) && (
          <div className="mb-4 p-3 bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 rounded-lg">
            <p className="text-sm text-blue-800 dark:text-blue-300">
              Numero de Encomienda: <span className="font-bold">
                {invoiceData.items[0].parcel_number}
              </span>
            </p>
          </div>
        )}

        {/* Tabs para seleccionar formato */}
        {(!showOnly80mm || isCargoInvoice) && (
          <div className="mb-4">
            <div className="flex border-b border-dm-border-primary">
              <button
                onClick={() => handleFormatChange('ticket80mm')}
                className={`px-4 py-2 text-sm font-medium transition-colors ${
                  activeFormat === 'ticket80mm'
                    ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                    : 'text-dm-text-muted hover:text-dm-text-secondary'
                }`}
              >
                Ticket 80mm (Termico)
              </button>
              {!showOnly80mm && (
                <button
                  onClick={() => handleFormatChange('a4')}
                  className={`px-4 py-2 text-sm font-medium transition-colors ${
                    activeFormat === 'a4'
                      ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                      : 'text-dm-text-muted hover:text-dm-text-secondary'
                  }`}
                >
                  Ticket A4 (Corporativo)
                </button>
              )}
              {isCargoInvoice && (
                <button
                  onClick={() => handleFormatChange('sticker100x100')}
                  className={`px-4 py-2 text-sm font-medium transition-colors flex items-center gap-1 ${
                    activeFormat === 'sticker100x100'
                      ? 'border-b-2 border-orange-500 text-orange-600 dark:text-orange-400'
                      : 'text-dm-text-muted hover:text-dm-text-secondary'
                  }`}
                >
                  <Tag className="h-3.5 w-3.5" />
                  Sticker 100x100
                </button>
              )}
            </div>
          </div>
        )}

        {/* Vista previa del PDF */}
        <div className="mb-4">
          <div className="border border-dm-border-primary rounded-lg overflow-hidden bg-dm-bg-secondary h-[500px] lg:h-[63vh]">
            {(isGenerating || (activeFormat === 'sticker100x100' && isGeneratingSticker)) ? (
              <div className="flex items-center justify-center h-full">
                <div className="text-center">
                  <Spinner size="lg" className="mb-4" />
                  <p className="text-dm-text-secondary">
                    {activeFormat === 'sticker100x100'
                      ? 'Generando sticker 100x100...'
                      : 'Generando tickets...'}
                  </p>
                  <p className="text-sm text-dm-text-muted">
                    {activeFormat === 'sticker100x100'
                      ? 'Creando el sticker y subiendo a la nube...'
                      : 'Generando PDFs (80mm y A4) y subiendo a la nube. Esto puede tomar unos segundos...'}
                  </p>
                </div>
              </div>
            ) : (activeFormat === 'ticket80mm' && previewUrl80mm) ? (
              <iframe
                src={previewUrl80mm}
                className="w-full h-full"
                title="Vista previa del ticket 80mm"
              />
            ) : (activeFormat === 'a4' && previewUrlA4) ? (
              <iframe
                src={previewUrlA4}
                className="w-full h-full"
                title="Vista previa del ticket A4"
              />
            ) : (activeFormat === 'sticker100x100' && previewUrlSticker100x100) ? (
              <iframe
                src={previewUrlSticker100x100}
                className="w-full h-full"
                title="Vista previa del sticker 100x100mm"
              />
            ) : (
              <div className="flex items-center justify-center h-full">
                <div className="text-center text-dm-text-muted">
                  <Eye className="h-12 w-12 mx-auto mb-2 opacity-50" />
                  <p>No se pudo cargar la vista previa</p>
                  <Button
                    onClick={activeFormat === 'sticker100x100' ? generateSticker100x100FromBackend : handleRegeneratePdfs}
                    variant="outline"
                    className="mt-4"
                  >
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Reintentar
                  </Button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Boton de regenerar (solo si hay error) */}
        {((!generationSuccess && !isGenerating) ||
          (activeFormat === 'sticker100x100' && !previewUrlSticker100x100 && !isGeneratingSticker)) && (
          <div className="mb-4">
            <Button
              onClick={activeFormat === 'sticker100x100' ? generateSticker100x100FromBackend : handleRegeneratePdfs}
              variant="outline"
              className="w-full"
              disabled={isGeneratingSticker}
            >
              <RefreshCw className="h-4 w-4 mr-2" />
              {activeFormat === 'sticker100x100' ? 'Generar Sticker 100x100' : 'Regenerar Tickets'}
            </Button>
          </div>
        )}
          </div>
        </div>

        {/* Botones de accion */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-4">
          <Button
            onClick={() => {
              handleDownloadTicket().then(() => {
                handleClose();
              });
            }}
            disabled={
              isGenerating ||
              isDownloading ||
              (activeFormat !== 'sticker100x100' && !generationSuccess) ||
              (activeFormat === 'sticker100x100' && !previewUrlSticker100x100)
            }
            className="bg-green-600 hover:bg-green-700 py-3"
          >
            {isDownloading ? (
              <>
                <Spinner size="sm" className="mr-2" />
                Descargando...
              </>
            ) : (
              <>
                <Download className="h-4 w-4 mr-2" />
                Descargar y Finalizar
              </>
            )}
          </Button>

          <Button
            onClick={() => setShowWhatsAppModal(true)}
            disabled={isGenerating || isDownloading || !generationSuccess}
            className="bg-green-500 hover:bg-green-600 py-3"
          >
            <MessageCircle className="h-4 w-4 mr-2" />
            Enviar por WhatsApp
          </Button>

          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isGenerating || isDownloading}
            className="py-3"
          >
            Cerrar
          </Button>
        </div>

        {/* Modal de edición de métodos de pago (control interno).
            Anidado dentro del Dialog de preview para que Headless UI v2 lo
            reconozca como dialogo anidado y gestione correctamente el foco,
            el inert y el cierre con Escape sin cerrar el preview. */}
        {showEditPaymentModal && (
          <EditPaymentMethodsModal
            isOpen={showEditPaymentModal}
            onClose={() => setShowEditPaymentModal(false)}
            onSuccess={() => { void handlePaymentUpdated(); }}
            invoiceId={invoiceId}
            invoiceSeries={panelInvoice.series}
            invoiceNumber={panelInvoice.number}
            totalPayable={Number(panelInvoice.total_payable)}
            currencyCode={panelInvoice.currency_code}
            initialPaymentData={invoiceToSplitPaymentData(panelInvoice)}
          />
        )}

        {/* Modal de WhatsApp */}
        <WhatsAppSendModal
          isOpen={showWhatsAppModal}
          onClose={() => setShowWhatsAppModal(false)}
          backendData={invoiceData}
          initialPhoneNumber={initialPhoneNumber || invoiceData.client?.phone || ''}
          onClearForm={onClearForm}
          isFromInvoiceList={true}
          preferredPdfType={activeFormat === 'a4' ? 'a4' : 'ticket'}
        />
      </div>
    </Modal>
    </>
  );
};

// src/features/fluvial/components/sales-point/WhatsAppSendModal.tsx
// ACTUALIZADO: Ahora usa la instancia de WhatsApp de la sucursal correspondiente
// con fallback automático a otra sucursal conectada si la principal no está disponible

import React, { useState } from 'react';
import { Modal } from '../../../../components/common/Modal';
import { Button } from '../../../../components/common/Button';
import { Input } from '../../../../components/common/Input';
import { Spinner } from '../../../../components/common/Spinner';
import { MessageCircle, Send, CheckCircle, AlertCircle, AlertTriangle } from 'lucide-react';
import { whatsappService, WhatsAppSendResponse } from '../../../../services/whatsapp.service';
import { BackendInvoiceData } from './tickets/types/backend.types';
import { Invoice } from '../../../../types';
import { useWhatsAppInstanceWithFallback } from '../../../../hooks/useWhatsAppInstance';

type WhatsAppSendModalInvoice = BackendInvoiceData | Invoice;

interface WhatsAppSendModalProps {
  isOpen: boolean;
  onClose: () => void;
  backendData: WhatsAppSendModalInvoice;
  initialPhoneNumber?: string;
  onClearForm?: () => void;
  // Nueva prop para identificar el contexto
  isFromInvoiceList?: boolean;
  // Tipo de PDF preferido para enviar (a4 o ticket)
  preferredPdfType?: 'a4' | 'ticket' | 'legacy';
}

export const WhatsAppSendModal: React.FC<WhatsAppSendModalProps> = ({
  isOpen,
  onClose,
  backendData,
  initialPhoneNumber = '',
  onClearForm,
  isFromInvoiceList = false,
  preferredPdfType = 'ticket'
}) => {
  const [phoneNumber, setPhoneNumber] = useState(initialPhoneNumber);
  const [customMessage, setCustomMessage] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [sendResult, setSendResult] = useState<WhatsAppSendResponse | null>(null);

  // Obtener la instancia de WhatsApp con verificación de conexión y fallback automático
  const whatsAppInstance = useWhatsAppInstanceWithFallback(backendData.branch_office_name || null);
  const businessName = backendData.branch_office_name || 'Nuestra Empresa';

  const defaultMessage = `¡Hola!

Nos alegra mucho que hayas decidido confiar en nosotros.
Adjuntamos a continuación tu comprobante electrónico correspondiente.

Gracias por tu preferencia.
Atentamente,
El equipo de ${businessName}`;

  const handleSend = async () => {
    if (!phoneNumber.trim()) {
      setSendResult({
        success: false,
        error: 'Por favor ingresa un número de teléfono válido'
      });
      return;
    }

    // Verificar que haya una instancia disponible (la original o el fallback)
    if (!whatsAppInstance.effectiveInstanceName) {
      setSendResult({
        success: false,
        error: whatsAppInstance.error || 'No hay ninguna instancia de WhatsApp disponible para enviar'
      });
      return;
    }

    try {
      setIsSending(true);
      setSendResult(null);

      // Detectar qué tipo de PDF está disponible basándose en los campos del backendData
      let pdfType: 'a4' | 'ticket' | 'legacy' = preferredPdfType;

      // Si backendData tiene información de archivos PDF, validar disponibilidad
      const invoiceData = backendData as any;

      // Si el tipo preferido no está disponible, hacer fallback
      if (pdfType === 'ticket' && !invoiceData.pdf_ticket_file_path) {
        if (invoiceData.pdf_a4_file_path) {
          pdfType = 'a4';
        } else if (invoiceData.pdf_file_path) {
          pdfType = 'legacy';
        }
      } else if (pdfType === 'a4' && !invoiceData.pdf_a4_file_path) {
        if (invoiceData.pdf_ticket_file_path) {
          pdfType = 'ticket';
        } else if (invoiceData.pdf_file_path) {
          pdfType = 'legacy';
        }
      }

      // Usar la instancia efectiva (original si está conectada, o fallback)
      const result = await whatsappService.sendInvoicePdf({
        invoiceId: backendData.id as number,
        phoneNumber,
        customMessage: customMessage.trim() || undefined,
        pdfType: pdfType,
        instanceName: whatsAppInstance.effectiveInstanceName,
        businessName: businessName
      });

      setSendResult(result);

      if (result.success) {
        // Limpiar el formulario después del éxito
        setTimeout(() => {
          onClose();
          setPhoneNumber('');
          setCustomMessage('');
          setSendResult(null);
          // Limpiar el formulario principal de venta
          if (onClearForm) {
            onClearForm();
          }
        }, 2000);
      }

    } catch (error: any) {
      setSendResult({
        success: false,
        error: error.message || 'Error desconocido al procesar el envío'
      });
    } finally {
      setIsSending(false);
    }
  };

  const handleClose = () => {
    if (!isSending) {
      onClose();
      // Reset form state
      setPhoneNumber(initialPhoneNumber);
      setCustomMessage('');
      setSendResult(null);
    }
  };

  const isValidPhoneNumber = (phone: string): boolean => {
    const cleaned = phone.replace(/[^\d]/g, '');
    return cleaned.length >= 9; // Mínimo 9 dígitos
  };

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={handleClose}
      title="Enviar Ticket por WhatsApp"
      maxWidth="md"
    >
      <div className="p-6">
        <div className="flex items-center mb-4">
          <MessageCircle className="h-6 w-6 text-green-600 dark:text-green-400 mr-2" />
          <div>
            <h3 className="font-semibold text-dm-text-primary">
              Envío de Comprobante Electrónico
            </h3>
            <p className="text-sm text-dm-text-secondary">
              Documento: {backendData.document_type_code} {backendData.series}-{backendData.number}
            </p>
            {isFromInvoiceList && (
              <p className="text-xs text-blue-600 dark:text-blue-400 mt-1">
                Formato: {preferredPdfType === 'a4' ? 'A4 (Corporativo)' : preferredPdfType === 'ticket' ? 'Ticket 80mm (Térmico)' : 'PDF Estándar'}
              </p>
            )}
            {/* Indicador de sucursal del comprobante */}
            {whatsAppInstance.branchOfficeName && (
              <p className="text-xs text-green-600 dark:text-green-400 mt-1">
               {whatsAppInstance.branchOfficeName}
              </p>
            )}
          </div>
        </div>

        {/* Campo de número de teléfono */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-dm-text-secondary mb-2">
            Número de WhatsApp
          </label>
          <Input
            type="tel"
            value={phoneNumber}
            onChange={(e) => setPhoneNumber(e.target.value)}
            placeholder="Ej: +51 987 654 321 o 987654321"
            disabled={isSending}
            className={`${
              phoneNumber && !isValidPhoneNumber(phoneNumber) 
                ? 'border-red-300 focus:border-red-500' 
                : ''
            }`}
          />
          {phoneNumber && !isValidPhoneNumber(phoneNumber) && (
            <p className="text-xs text-red-600 dark:text-red-400 mt-1">
              Ingresa un número válido (mínimo 9 dígitos)
            </p>
          )}
          <p className="text-xs text-dm-text-muted mt-1">
            Se agregará automáticamente el código de país +51 si no se especifica
          </p>
        </div>

        {/* Campo de mensaje personalizado */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-dm-text-secondary mb-2">
            Mensaje (opcional)
          </label>
          <textarea
            value={customMessage}
            onChange={(e) => setCustomMessage(e.target.value)}
            placeholder={defaultMessage}
            disabled={isSending}
            rows={8}
            className="w-full px-3 py-2 border border-dm-border-primary rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
          />
          <p className="text-xs text-dm-text-muted mt-1">
            Si dejas vacío, se usará el mensaje predeterminado
          </p>
        </div>

        {/* Resultado del envío */}
        {sendResult && (
          <div className={`mb-4 p-3 rounded-lg flex items-center ${
            sendResult.success 
              ? 'bg-green-50 dark:bg-green-950/30 border border-green-200 dark:border-green-800/50' 
              : 'bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800/50'
          }`}>
            {sendResult.success ? (
              <>
                <CheckCircle className="h-5 w-5 text-green-600 dark:text-green-400 mr-2 flex-shrink-0" />
                <div className="text-green-800 dark:text-green-300">
                  <p className="font-medium">¡Enviado exitosamente!</p>
                  <p className="text-sm">{sendResult.message}</p>
                </div>
              </>
            ) : (
              <>
                <AlertCircle className="h-5 w-5 text-red-600 dark:text-red-400 mr-2 flex-shrink-0" />
                <div className="text-red-800 dark:text-red-300">
                  <p className="font-medium">Error al enviar</p>
                  <p className="text-sm">{sendResult.error}</p>
                </div>
              </>
            )}
          </div>
        )}

        {/* Botones de acción */}
        <div className="flex gap-3">
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isSending}
            className="flex-1"
          >
            {sendResult?.success ? 'Cerrar' : 'Cancelar'}
          </Button>

          <Button
            onClick={handleSend}
            disabled={isSending || !phoneNumber.trim() || !isValidPhoneNumber(phoneNumber) || !whatsAppInstance.effectiveInstanceName}
            className="flex-1 bg-green-600 hover:bg-green-700 disabled:bg-dm-text-muted disabled:cursor-not-allowed"
          >
            {isSending ? (
              <>
                <Spinner size="sm" className="mr-2" />
                Enviando...
              </>
            ) : whatsAppInstance.isCheckingConnection ? (
              <>
                <Spinner size="sm" className="mr-2" />
                Verificando...
              </>
            ) : (
              <>
                <Send className="h-4 w-4 mr-2" />
                Enviar por WhatsApp
              </>
            )}
          </Button>
        </div>

        {/* Aviso: Usando sucursal alternativa (fallback) */}
        {whatsAppInstance.usingFallback && whatsAppInstance.effectiveInstanceName && (
          <div className="mt-4 p-3 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 rounded-lg">
            <div className="flex items-start">
              <AlertTriangle className="h-4 w-4 text-amber-600 dark:text-amber-400 mr-2 mt-0.5 flex-shrink-0" />
              <div className="text-amber-800 dark:text-amber-300 text-xs">
                <p className="font-medium mb-1">Usando sucursal alternativa</p>
                <p>
                  La sucursal <strong>"{whatsAppInstance.branchOfficeName}"</strong> no tiene WhatsApp 
                  {whatsAppInstance.hasInstance && !whatsAppInstance.isConnected ? ' conectado' : ' configurado'}.
                </p>
                <p className="mt-1">
                  Se enviará desde: <strong className="text-amber-900 dark:text-amber-200">{whatsAppInstance.effectiveBranchOfficeName}</strong>
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Advertencia si no hay WhatsApp disponible en ninguna sucursal */}
        {!whatsAppInstance.effectiveInstanceName && !whatsAppInstance.isLoading && !whatsAppInstance.isCheckingConnection && (
          <div className="mt-4 p-3 bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800/50 rounded-lg">
            <div className="flex items-start">
              <AlertCircle className="h-4 w-4 text-red-600 dark:text-red-400 mr-2 mt-0.5 flex-shrink-0" />
              <div className="text-red-800 dark:text-red-300 text-xs">
                <p className="font-medium mb-1">WhatsApp no disponible</p>
                <p>
                  {whatsAppInstance.error || `No hay ninguna instancia de WhatsApp conectada disponible.`}
                </p>
                <p className="mt-1">
                  Contacta al administrador para verificar la configuración de WhatsApp.
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Verificando conexión */}
        {whatsAppInstance.isCheckingConnection && (
          <div className="mt-4 p-3 bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 rounded-lg">
            <div className="flex items-center">
              <Spinner size="sm" className="mr-2 text-blue-600 dark:text-blue-400" />
              <span className="text-blue-800 dark:text-blue-300 text-xs">Verificando estado de conexión de WhatsApp...</span>
            </div>
          </div>
        )}

        {/* Nota informativa - Solo mostrar si hay WhatsApp disponible y está conectado directamente */}
        {whatsAppInstance.effectiveInstanceName && !whatsAppInstance.usingFallback && !whatsAppInstance.isCheckingConnection && (
          <div className="mt-4 p-3 bg-green-50 dark:bg-green-950/30 border border-green-200 dark:border-green-800/50 rounded-lg">
            <div className="flex items-start">
              <MessageCircle className="h-4 w-4 text-green-600 dark:text-green-400 mr-2 mt-0.5 flex-shrink-0" />
              <div className="text-green-800 dark:text-green-300 text-xs">
                <p className="font-medium mb-1">WhatsApp conectado</p>
                <ul className="list-disc list-inside space-y-1">
                  <li>Sucursal: <strong>{whatsAppInstance.branchOfficeName}</strong></li>
                  <li>Verifica que el número tenga WhatsApp activo</li>
                </ul>
              </div>
            </div>
          </div>
        )}
      </div>
    </Modal>
  );
};

