      );
    } catch (error) {
      // Los errores ya son manejados por toast en los hooks internos
    } finally {
      // Asegura cerrar el overlay incluso si los hooks internos capturan errores sin relanzarlos
      setIsProcessingSale(false);
    }
  }, [
    isRuc,
    handleCompanyInvoiceWithRepresentatives,
    trip.id,
    selectedBoardingStopId,
    selectedDisembarkingStopId,
    passengerData.name,
    passengerData.docType,
    representatives, // ← Dependencia completa: los infantes viven dentro de cada representante
    branch.name,
    confirmPurchase,
    effectiveBasePrice,
    seatMultiplier,
    extraCost,
    extraCostDescription,
    handleRegularSale,
    selectedSeat?.id,
    itemDescription,
    seatMap.length,
    showSeatMap,
    selectedFacturaSeries,
    selectedBoletaSeries,
    isIgvGravado,
    discount,
    isConfirmingMode,
    reservationToConfirm?.id,
    splitPaymentData,
    selectedCurrency,
    boletaInfants,
  ]);

  // NUEVO: Verificar si el destino está seleccionado para mostrar la barra lateral
  const canShowPriceSidebar = useMemo(() => {
    return !!selectedBoardingStopId && !!selectedDisembarkingStopId;
  }, [selectedBoardingStopId, selectedDisembarkingStopId]);

  // Optimización: Memoizar areActionsEnabled para evitar recálculos
  const areActionsEnabled = useMemo(() => {
    const hasValidPrice = isManualPriceMode 
      ? (manualPrice !== null && manualPrice > 0) 
      : true; // Si no es modo manual, siempre es válido (puede ser que no haya destino seleccionado)

    // CRÍTICO: Validar que el monto final sea mayor a 0 (previene facturas de S/ 0.00)
    const hasFinalPriceGreaterThanZero = finalTicketPrice > 0;

    // NUEVO: Validar que el pago dividido cuadre con el total
    const isSplitPaymentOk = !splitPaymentData.isSplitPayment || isSplitPaymentValid;

    return !!selectedBoardingStopId &&
      !!selectedDisembarkingStopId &&
      !!passengerData.docNumber.trim() &&
      !!passengerData.name.trim() &&
      hasValidPrice && // NUEVO: Validar que haya precio manual si se requiere
      hasFinalPriceGreaterThanZero && // CRÍTICO: El monto final debe ser > 0
      isSplitPaymentOk && // NUEVO: El pago dividido debe cuadrar
      (isRuc ? representatives.length > 0 : !showSeatMap || !!selectedSeat);
  }, [
    selectedBoardingStopId,
    selectedDisembarkingStopId,
    passengerData.docNumber,
    passengerData.name,
    isRuc,
    representatives.length,
    showSeatMap,
    selectedSeat?.id, // Ya optimizado
    isManualPriceMode, // NUEVO
    manualPrice, // NUEVO
    finalTicketPrice, // CRÍTICO: Agregar finalTicketPrice como dependencia
    splitPaymentData.isSplitPayment, // NUEVO: Dependencia del pago dividido
    isSplitPaymentValid, // NUEVO: Dependencia de validación del pago dividido
  ]);
  return {
    showTicketPreview,
    setShowTicketPreview,
    ticketBackendData,
    setTicketBackendData,
    representatives,
    setRepresentatives,
    showRepresentatives,
    setShowRepresentatives,
    showAddForm,
    setShowAddForm,
    boletaInfants,
    setBoletaInfants,
    selectedSeatForRepresentative,
    setSelectedSeatForRepresentative,
    selectedBoardingStopId,
    setSelectedBoardingStopId,
    selectedDisembarkingStopId,
    setSelectedDisembarkingStopId,
    selectedSeat,
    setSelectedSeat,
    passengerData,
    setPassengerData,
    extraCost,
    setExtraCost,
    extraCostDescription,
    setExtraCostDescription,
    discount,
    isIgvGravado,
    setIsIgvGravado,
    manualPrice,
    isManualPriceMode,
    editableBasePrice,
    selectedBoletaSeries,
    setSelectedBoletaSeries,
    selectedFacturaSeries,
    setSelectedFacturaSeries,
    itemDescription,
    setItemDescription,
    splitPaymentData,
    isSplitPaymentValid,
    isReservationModalOpen,
    setReservationModalOpen,
    isConfirmingMode,
    setIsConfirmingMode,
    isProcessingSale,
    setIsProcessingSale,
    isConfirmSaleModalOpen,
    setIsConfirmSaleModalOpen,
    selectedCurrency,
    setCurrency,
    getCurrencySymbol,
    showSeatMap,
    isCreating,
    reserveSeat,
    releaseSeat,
    getReservedSeatNumbers,
    isReserving,
    currentUser,
    tripDetails,
    passengerService,
    availableBoletaSeries,
    availableFacturaSeries,
    isLoadingSeries,
    isProcessingClient,
    isCreatingInvoice,
    isAssigningSeat,
    isUpdatingReservation,
    basePrice,
    seatMultiplier,
    subtotal,
    igvAmount,
    finalTicketPrice,
    handleDiscountChange,
    handleManualPriceChange,
    handleEditableBasePriceChange,
    handleUpdateRepresentativeInfants,
    handleAddRepresentative,
    handleRemoveRepresentative,
    handleSeatReserveForRepresentative,
    handleSeatReleaseForRepresentative,
    handleShowAddFormChange,
    existingDocuments,
    usedSeatNumbers,
    getAllOccupiedSeatNumbers,
    isRuc,
    handleWebSocketReady,
    seatMap,
    representativeSelectedSeatIds,
    handleOpenConfirmModal,
    handleConfirmSale,
    canShowPriceSidebar,
    areActionsEnabled,
    clearFormAfterSale,
    clearStateForVesselChange,
    handleSplitPaymentChange,
    handleSplitPaymentValidationChange,
    handleBoletaSeriesChange,
    handleFacturaSeriesChange,
  };
}

import { describe, it, expect } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useSaleFormState } from './useSaleFormState';
import { SunatDocType } from '../../../types/sunat.types';

describe('useSaleFormState', () => {
  it('initializes with default state', () => {
    const { result } = renderHook(() => useSaleFormState());
    expect(result.current.state.passengerData.docType).toBe(SunatDocType.DNI);
    expect(result.current.state.representatives).toEqual([]);
    expect(result.current.state.isConfirmingMode).toBe(false);
    expect(result.current.state.showRepresentatives).toBe(false);
  });

  it('sets isConfirmingMode when reservationToConfirm is provided', () => {
    const { result } = renderHook(() => useSaleFormState({ id: 1 }));
    expect(result.current.state.isConfirmingMode).toBe(true);
  });

  it('updateState merges partial updates', () => {
    const { result } = renderHook(() => useSaleFormState());
    act(() => result.current.updateState({ extraCost: 50 }));
    expect(result.current.state.extraCost).toBe(50);
    expect(result.current.state.discount).toBe(0); // unchanged
  });

  it('addRepresentative appends to list', () => {
    const { result } = renderHook(() => useSaleFormState());
    const rep = { name: 'Rep1', document_type: '1', document_number: '11111111' } as any;
    act(() => result.current.addRepresentative(rep));
    expect(result.current.state.representatives).toHaveLength(1);
    expect(result.current.state.representatives[0].name).toBe('Rep1');
    expect(result.current.state.showAddForm).toBe(false);
  });

  it('removeRepresentative filters by index', () => {
    const { result } = renderHook(() => useSaleFormState());
    const rep1 = { name: 'R1' } as any;
    const rep2 = { name: 'R2' } as any;
    act(() => {
      result.current.addRepresentative(rep1);
      result.current.addRepresentative(rep2);
    });
    act(() => result.current.removeRepresentative(0));
    expect(result.current.state.representatives).toHaveLength(1);
    expect(result.current.state.representatives[0].name).toBe('R2');
  });

  it('shows representatives when RUC and basic info filled', () => {
    const { result } = renderHook(() => useSaleFormState());
    act(() => {
      result.current.updateState({
        passengerData: {
          docType: SunatDocType.RUC,
          docNumber: '20123456789',
          name: 'Empresa SAC',
          address: '',
          phone: '',
          email: '',
        },
      });
    });
    expect(result.current.state.showRepresentatives).toBe(true);
  });

  it('does not show representatives when docType is not RUC', () => {
    const { result } = renderHook(() => useSaleFormState());
    act(() => {
      result.current.updateState({
        passengerData: {
          docType: SunatDocType.DNI,
          docNumber: '12345678',
          name: 'Juan',
          address: '',
          phone: '',
          email: '',
        },
      });
    });
    expect(result.current.state.showRepresentatives).toBe(false);
  });

  it('does not show representatives when basic info is incomplete', () => {
    const { result } = renderHook(() => useSaleFormState());
    act(() => {
      result.current.updateState({
        passengerData: {
          docType: SunatDocType.RUC,
          docNumber: '',
          name: '',
          address: '',
          phone: '',
          email: '',
        },
      });
    });
    expect(result.current.state.showRepresentatives).toBe(false);
  });
});

// src/features/fluvial/components/sales-point/hooks/useSaleFormState.ts

import { useState, useEffect } from "react";
import { SaleFormState, initialPassengerData, Representative } from "../core/types";
import { SunatDocType } from "../../../types/sunat.types";

export const useSaleFormState = (reservationToConfirm?: any) => {
  const [state, setState] = useState<SaleFormState>({
    selectedBoardingStopId: null,
    selectedDisembarkingStopId: null,
    selectedSeat: null,
    passengerData: initialPassengerData,
    extraCost: 0,
    extraCostDescription: "",
    discount: 0,
    isIgvGravado: false,
    selectedBoletaSeries: "",
    selectedFacturaSeries: "",
    isReservationModalOpen: false,
    isConfirmingMode: !!reservationToConfirm,
    canSellWithoutSeats: false,
    showSeatMap: true,
    representatives: [],
    showRepresentatives: false,
    maxPassengers: 1,
    showAddForm: false,
    selectedSeatForRepresentative: null,
  });

  // Función helper para actualizar estado parcialmente
  const updateState = (updates: Partial<SaleFormState>) => {
    setState(prev => ({ ...prev, ...updates }));
  };

  // Funciones específicas para manejar representantes
  const addRepresentative = (representative: Representative) => {
    setState(prev => ({
      ...prev,
      representatives: [...prev.representatives, representative],
      showAddForm: false,
    }));
  };

  const removeRepresentative = (index: number) => {
    setState(prev => ({
      ...prev,
      representatives: prev.representatives.filter((_, i) => i !== index),
    }));
  };

  // Efecto para mostrar representantes cuando es RUC
  useEffect(() => {
    const isRuc = state.passengerData.docType === SunatDocType.RUC;
    const hasBasicInfo = Boolean(
      state.passengerData.docNumber.trim() && 
      state.passengerData.name.trim()
    );

    updateState({ showRepresentatives: isRuc && hasBasicInfo });
  }, [state.passengerData.docType, state.passengerData.docNumber, state.passengerData.name]);

  return {
    state,
    updateState,
    addRepresentative,
    removeRepresentative,
  };
};

// src/features/fluvial/components/sales-point/representatives/AddRepresentativeForm.tsx
import React, { useState } from 'react';
import { toast } from '@/utils/sileo-toast';
import { useQuery } from '@tanstack/react-query';
import { Button } from '../../../../../components/common/Button';
import { Input } from '../../../../../components/common/Input';
import { SunatDocType } from '../../../types/sunat.types';
import api from '../../../../../config/api';
import { REPRESENTATIVE_ITEM_DESCRIPTION_MAX_CHARS } from '../core/types';

interface Representative {
  document_type: string;
  document_number: string;
  name: string;
  phone: string | null; // ← Permitir null
  email?: string; // ← NUEVO: Campo email
  seat_number?: string;
  item_description?: string; // ← NUEVO: Descripción opcional por representante
}

interface SeatMapItem {
  seat_number: string;
  seat_type_name: string;
  is_available: boolean;
  is_reserved?: boolean;
  reserved_until?: string;
}

interface AddRepresentativeFormProps {
  onAdd: (representative: Representative) => void;
  onCancel: () => void;
  existingDocuments: string[];
  tripId: number;
  usedSeatNumbers: string[];
  selectedSeat: any; // Asiento seleccionado desde el mapa visual
  onSeatSelect: (seat: any) => void; // Función para seleccionar asiento
  representativeIndex: number; // Nuevo: índice del representante
  onSeatReserve?: (seatNumber: string, representativeIndex: number) => Promise<boolean>; // Nueva función para reservar
  onSeatRelease?: (representativeIndex: number) => void; // Nueva función para liberar
}

export const AddRepresentativeForm: React.FC<AddRepresentativeFormProps> = ({
  onAdd,
  onCancel,
  existingDocuments,
  tripId,
  usedSeatNumbers,
  selectedSeat,
  onSeatSelect,
  representativeIndex,
  onSeatReserve,
  onSeatRelease,
}) => {
  const [formData, setFormData] = useState({
    document_type: SunatDocType.DNI,
    document_number: '',
    name: '',
    phone: '',
    email: '', // ← NUEVO: Campo email
    seat_number: '',
    item_description: '', // ← NUEVO: Descripción por ítem/representante
  });

  const [isLoadingDni, setIsLoadingDni] = useState(false);
  const [dniError, setDniError] = useState<string | null>(null);
  const [isReservingSeat, setIsReservingSeat] = useState(false);

  // Obtener mapa de asientos del viaje
  const { data: seatMap } = useQuery({
    queryKey: ['seatMap', tripId],
    queryFn: async () => {
      try {
        const response = await api.get(`/operations/trips/${tripId}/seat-map`);
        if (response.status === 204) {
          return []; // Sin asientos configurados -> devolver array vacío
        }
        return response.data as SeatMapItem[];
      } catch (error) {
        return [];
      }
    },
    enabled: !!tripId,
  });

  // Filtrar asientos disponibles
  const availableSeats = Array.isArray(seatMap)
    ? seatMap.filter(seat => seat.is_available && !usedSeatNumbers.includes(seat.seat_number))
    : [];

  const hasSeats = Array.isArray(seatMap) && seatMap.length > 0;

  // Función para consultar DNI
  const handleDniQuery = async (dni: string) => {
    if (dni.length !== 8) return;

    setIsLoadingDni(true);
    setDniError(null);

    try {
      const response = await api.get(`/external/query-dni?dni=${dni}`, {
        headers: { 'X-Skip-Auth-Redirect': '1' }
      });
      if (response.data && response.data.nombreCompleto) {
        setFormData(prev => ({
          ...prev,
          name: response.data.nombreCompleto,
          phone: response.data.phone || prev.phone // Solo actualizar teléfono si viene en la respuesta
        }));
        toast.success('Datos encontrados automáticamente');
      }
    } catch (error: any) {
      setDniError('No se pudieron obtener los datos del DNI');
      // Mostrar mensaje apropiado según el tipo de error
      if (error?.response?.status === 401) {
        toast.warning('No se pudo realizar la consulta automática del DNI. Puede ingresar los datos manualmente para continuar.');
      } else {
        toast.warning('No se encontraron datos para este DNI. Ingrese el nombre manualmente.');
      }
    } finally {
      setIsLoadingDni(false);
    }
  };

  // Manejar cambio en número de documento
  const handleDocumentNumberChange = (value: string) => {
    setFormData(prev => ({ ...prev, document_number: value }));

    // Auto-consultar si es DNI y tiene 8 dígitos
    if (formData.document_type === SunatDocType.DNI && value.length === 8) {
      handleDniQuery(value);
    }
  };

  // Nueva función: Manejar selección de asiento con reserva
  const handleSeatSelection = async (seat: any) => {
    if (!seat) {
      // Liberar asiento actual si existe
      if (selectedSeat && onSeatRelease) {
        onSeatRelease(representativeIndex);
      }
      onSeatSelect(null);
      return;
    }

    // Intentar reservar el nuevo asiento
    if (onSeatReserve) {
      setIsReservingSeat(true);
      const reserved = await onSeatReserve(seat.seat_number, representativeIndex);
      setIsReservingSeat(false);

      if (reserved) {
        // Liberar asiento anterior si había uno
        if (selectedSeat && selectedSeat.seat_number !== seat.seat_number && onSeatRelease) {
          onSeatRelease(representativeIndex);
        }
        onSeatSelect(seat);
        toast.success(`Asiento ${seat.seat_number} reservado temporalmente`);
      } else {
        toast.error('No se pudo reservar el asiento. Intente con otro.');
      }
    } else {
      // Fallback sin reserva
      onSeatSelect(seat);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validaciones
    if (!formData.document_number.trim()) {
      toast.error('El número de documento es requerido');
      return;
    }

    if (!formData.name.trim()) {
      toast.error('El nombre es requerido');
      return;
    }

    // Verificar duplicados
    if (existingDocuments.includes(formData.document_number.trim())) {
      toast.error('Este documento ya está registrado');
      return;
    }

    // Validar DNI
    if (formData.document_type === SunatDocType.DNI && formData.document_number.length !== 8) {
      toast.error('El DNI debe tener 8 dígitos');
      return;
    }

    // Validar CE (Carné de extranjería)
    if (formData.document_type === SunatDocType.CARNET_EXTRANJERIA && (formData.document_number.length < 8 || formData.document_number.length > 12)) {
      toast.error('El Carné de Extranjería debe tener entre 8 y 12 caracteres');
      return;
    }

    // NUEVA VALIDACIÓN: Para embarcaciones con asientos, es obligatorio seleccionar uno
    if (hasSeats && !selectedSeat) {
      toast.error('Debe seleccionar un asiento en el mapa de abajo');
      return;
    }

    // Determinar número de asiento
    const seatNumber = hasSeats 
      ? (selectedSeat ? selectedSeat.seat_number : "Elección libre")
      : "Sin asientos configurados";

    // Agregar representante
    onAdd({
      document_type: formData.document_type,
      document_number: formData.document_number.trim(),
      name: formData.name.trim(),
      phone: formData.phone.trim() || null, // ← Enviar null si está vacío
      email: formData.email.trim() || undefined, // ← NUEVO: Campo email
      seat_number: seatNumber,
      item_description: formData.item_description.trim() || undefined,
    });

    // Limpiar formulario y asiento seleccionado
    setFormData({
      document_type: SunatDocType.DNI,
      document_number: '',
      name: '',
      phone: '',
      email: '', // ← NUEVO: Campo email
      seat_number: '',
      item_description: '', // ← NUEVO: Descripción por ítem/representante
    });

    // Limpiar selección de asiento
    onSeatSelect(null);
  };

  return (
    <div className="rounded-lg border border-dm-border-primary bg-dm-bg-primary p-3 sm:p-4">
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
        <h4 className="text-sm font-semibold text-dm-text-primary sm:text-base">Agregar Representante</h4>
        <span className="rounded-full bg-dm-bg-secondary px-2.5 py-1 text-[11px] font-medium text-dm-text-muted">
          Paso {representativeIndex + 1}
        </span>
      </div>

      <form onSubmit={handleSubmit} className="space-y-3">
        <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
          <div>
            <label className="mb-1 block text-xs font-semibold uppercase tracking-wide text-dm-text-muted">
              Tipo de Documento
            </label>
            <select
              value={formData.document_type}
              onChange={(e) => setFormData(prev => ({ ...prev, document_type: e.target.value as SunatDocType }))}
              className="w-full rounded-lg border border-dm-border-primary bg-dm-bg-primary px-3 py-2 text-sm text-dm-text-primary focus:border-[#435ee5] focus:outline-none focus:ring-2 focus:ring-[#435ee5]/20"
            >
              <option value={SunatDocType.DNI}>DNI</option>
              <option value={SunatDocType.CARNET_EXTRANJERIA}>Carné de Extranjería</option>
              <option value={SunatDocType.PASAPORTE}>Pasaporte</option>
              <option value={SunatDocType.CEDULA_DIPLOMATICA}>Cédula Diplomática</option>
            </select>
          </div>

          <div>
            <label className="mb-1 block text-xs font-semibold uppercase tracking-wide text-dm-text-muted">
              N° de Documento
            </label>
            <div className="relative">
              <Input
                type="text"
                value={formData.document_number}
                onChange={(e) => handleDocumentNumberChange(e.target.value)}
                placeholder={formData.document_type === SunatDocType.DNI ? "DNI (se consultará automáticamente)" : "Ingrese número"}
                className="text-sm"
                maxLength={formData.document_type === SunatDocType.DNI ? 8 : 20}
                disabled={isLoadingDni}
              />
              {isLoadingDni && (
                <div className="absolute right-2 top-1/2 -translate-y-1/2">
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600"></div>
                </div>
              )}
            </div>
            {dniError && (
              <div className="text-xs text-red-500 dark:text-red-400 mt-1">{dniError}</div>
            )}
            {formData.document_type === SunatDocType.DNI && (
              <div className="mt-1 text-xs text-dm-text-muted">
                Al ingresar 8 dígitos se consultará automáticamente
              </div>
            )}
          </div>
        </div>

        <div>
          <label className="mb-1 block text-xs font-semibold uppercase tracking-wide text-dm-text-muted">
            Nombre Completo
          </label>
          <Input
            type="text"
            value={formData.name}
            onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
            placeholder="Nombre y apellidos del representante"
            className="text-sm"
          />
        </div>

        <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
          <div>
            <label className="mb-1 block text-xs font-semibold uppercase tracking-wide text-dm-text-muted">
            Teléfono <span className="text-dm-text-muted">(opcional)</span>
            </label>
            <Input
              type="tel"
              value={formData.phone}
              onChange={(e) => setFormData(prev => ({ ...prev, phone: e.target.value }))}
              placeholder="Número de teléfono del representante"
              className="text-sm"
            />
          </div>

          {/* ← NUEVO: Campo Email */}
          <div>
            <label className="mb-1 block text-xs font-semibold uppercase tracking-wide text-dm-text-muted">
            Email <span className="text-dm-text-muted">(opcional)</span>
            </label>
            <Input
              type="email"
              value={formData.email}
              onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
              placeholder="Correo electrónico del representante"
              className="text-sm"
            />
          </div>
        </div>

        <div>
          <label className="mb-1 block text-xs font-semibold uppercase tracking-wide text-dm-text-muted">
            Descripción por ítem <span className="font-normal text-red-600 dark:text-red-400">(opcional)</span>
          </label>
          <textarea
            value={formData.item_description}
            onChange={(e) => setFormData(prev => ({ ...prev, item_description: e.target.value }))}
            placeholder="Ej. Pasaje Iquitos-Nauta - PASAJERO: NOMBRE"
            className="w-full resize-none rounded-lg border-2 border-red-300 bg-dm-bg-primary p-2 text-sm text-dm-text-primary placeholder:text-dm-text-muted focus:border-red-500 focus:outline-none focus:ring-2 focus:ring-red-200"
            rows={2}
            maxLength={REPRESENTATIVE_ITEM_DESCRIPTION_MAX_CHARS}
          />
          <div className="mt-1 text-xs text-dm-text-muted">
            {formData.item_description.length}/{REPRESENTATIVE_ITEM_DESCRIPTION_MAX_CHARS} caracteres
          </div>
        </div>

        <div>
          <label className="mb-1 block text-xs font-semibold uppercase tracking-wide text-dm-text-muted">
            Asiento
          </label>
          {hasSeats ? (
            <div className="space-y-2">
              <div className="rounded-md border border-dm-border-primary bg-dm-bg-secondary p-3">
                {selectedSeat ? (
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="font-medium text-green-700 dark:text-green-300">
                        Asiento Seleccionado: {selectedSeat.seat_number}
                      </div>
                      <div className="text-sm text-dm-text-muted">
                        Tipo: {selectedSeat.seat_type_name}
                      </div>
                    </div>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => handleSeatSelection(null)}
                      className="text-xs"
                      disabled={isReservingSeat}
                    >
                      {isReservingSeat ? 'Liberando...' : 'Cambiar'}
                    </Button>
                  </div>
                ) : (
                  <div className="text-center text-dm-text-muted">
                    <div className="font-medium">Seleccione un asiento</div>
                    <div className="text-sm">Use el mapa de asientos de abajo</div>
                    <div className="text-xs text-red-500 dark:text-red-400 mt-1">
                      * Obligatorio para continuar
                    </div>
                  </div>
                )}
              </div>
              <div className="text-xs text-dm-text-muted">
                {availableSeats.length} asientos disponibles en el mapa
              </div>
            </div>
          ) : (
            <div className="rounded-md border border-dm-border-primary bg-dm-bg-secondary p-2 text-sm text-dm-text-muted">
              Esta embarcación no tiene asientos configurados
            </div>
          )}
        </div>

        <div className="flex flex-col gap-2 pt-2 sm:flex-row">
          <Button
            type="submit"
            className="flex-1 bg-gray-900 py-2 text-sm text-white hover:bg-gray-800 dark:bg-gray-100 dark:text-gray-900 dark:hover:bg-gray-200"
            disabled={Boolean((hasSeats && !selectedSeat) || isReservingSeat)}
          >
            {isReservingSeat 
              ? "Reservando asiento..." 
              : hasSeats && !selectedSeat 
                ? "Seleccione un asiento primero" 
                : "Agregar Representante"
            }
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            className="px-4 py-2 text-sm"
            disabled={isReservingSeat}
          >
            Cancelar
          </Button>
        </div>
      </form>
    </div>
  );
};

