// src/features/fluvial/components/sales-point/services/invoiceCreationService.ts

import { format } from "date-fns";
import { PassengerData, Representative, Infant } from "../core/types";
import { SunatInvoiceType, SunatTaxCategory } from "../../../types/sunat.types";
import { productsServicesService } from '../../../../../services/products-services.service';

export interface InvoiceItemData {
  product_id: number;
  quantity: number;
  unit_price: number;
  discount: number;
  tax_category_code: string;
  item_description: string;
  unit_code: string;
  trip_id: number;
  boarding_trip_stop_id: number;
  disembarking_trip_stop_id: number;
  // Campos para asientos
  trip_seat_id?: number; // ID del asiento en la embarcación
  seat_number?: string; // Número del asiento seleccionado por el vendedor
}

export interface InvoiceCreationData {
  client_id: number;
  document_type_code: string;
  series: string;
  issue_date: string;
  issue_time: string;
  operation_type_code: string;
  currency_code: string;
  notes: string;
  items: InvoiceItemData[];
  // Infantes acompañantes (solo para boletas)
  infants?: Infant[];
  // Campos de pago principal
  payment_method_code?: string;
  payment_operation_code?: string;
  // Campos para pago dividido
  payment_amount_1?: number;
  payment_method_code_2?: string;
  payment_operation_code_2?: string;
  payment_amount_2?: number;
  pago_yape_id?: string;
}

export const invoiceCreationService = {
  createInvoiceItems: async (
    passengerData: PassengerData,
    representatives: Representative[],
    basePrice: number,
    seatMultiplier: number,
    extraCost: number,
    extraCostDescription: string,
    discount: number,
    isIgvGravado: boolean,
    tripId: number,
    selectedBoardingStopId: number,
    selectedDisembarkingStopId: number,
    selectedSeat?: any, // Asiento seleccionado para obtener seat_number y trip_seat_id
    itemDescription?: string // ← Descripción opcional del usuario
  ): Promise<InvoiceItemData[]> => {
    const items: InvoiceItemData[] = [];

    // Calcular cantidad según tipo de documento
    const quantity = invoiceCreationService.calculateQuantity(passengerData, representatives);

    // Precio del servicio base
    const baseServicePrice = basePrice * seatMultiplier;
    const baseServiceWithIgv = isIgvGravado ? baseServicePrice * 1.18 : baseServicePrice;

    // Item principal: Servicio de transporte
    // SOLO incluir el nombre del servicio y la descripción opcional del usuario
    // La detección de embarcaciones sin asientos se hace por trip_seat_id y seat_number null
    const optionalDescription = itemDescription?.trim() ? ` - ${itemDescription.trim()}` : "";

    items.push({
      product_id: 1, // ID fijo del servicio de transporte
      quantity: quantity,
      unit_price: parseFloat(baseServiceWithIgv.toFixed(10)),
      discount: discount,
      tax_category_code: isIgvGravado
        ? SunatTaxCategory.GRAVADO
        : SunatTaxCategory.EXONERADO,
      item_description: `Servicio de Transporte Fluvial${optionalDescription}`,
      unit_code: "ZZ", // ZZ = Servicio (CORREGIDO de NIU)
      trip_id: tripId,
      boarding_trip_stop_id: selectedBoardingStopId,
      disembarking_trip_stop_id: selectedDisembarkingStopId,
      // Agregar información del asiento si está disponible
      trip_seat_id: selectedSeat?.id || null,
      seat_number: selectedSeat?.seat_number || null,
    });

  // Item adicional: Costo adicional (si existe)
  if (extraCost > 0) {
      const extraCostWithIgv = isIgvGravado ? extraCost * 1.18 : extraCost;
      // Intentar obtener el nombre del producto/servicio con id 7 y componer la descripción
      let extraProductName = '';
      try {
        const prod = await productsServicesService.getById(7);
        extraProductName = prod?.name || '';
      } catch (e) {
        extraProductName = '';
      }

      const descriptionText = extraCostDescription?.trim() || 'Equipaje en exceso';
      const composedExtraDescription = extraProductName
        ? `${extraProductName} - ${descriptionText}`
        : descriptionText;

      items.push({
        product_id: 7, // ID específico para exceso de equipaje/costos adicionales
        quantity: 1,
        unit_price: parseFloat(extraCostWithIgv.toFixed(10)),
        discount: 0,
        tax_category_code: isIgvGravado
          ? SunatTaxCategory.GRAVADO
          : SunatTaxCategory.EXONERADO,
        item_description: composedExtraDescription,
        unit_code: "ZZ", // ZZ = Servicio (CORREGIDO de NIU)
        trip_id: tripId,
        boarding_trip_stop_id: selectedBoardingStopId,
        disembarking_trip_stop_id: selectedDisembarkingStopId,
        // NO se envía trip_seat_id ni seat_number para costos adicionales (bultos)
      });
    }

    return items;
  },

  createInvoicePayload: (
    clientId: number,
    passengerData: PassengerData,
    series: string,
    branchName: string,
    items: InvoiceItemData[],
    selectedPaymentMethod?: string,
    paymentOperationCode?: string,
    currencyCode: 'PEN' | 'USD' = 'PEN',
    // Parametros para pago dividido
    splitPaymentData?: {
      isSplitPayment: boolean;
      paymentAmount1?: number;
      paymentMethodCode2?: string;
      paymentOperationCode2?: string;
      paymentAmount2?: number;
      pagoYapeId?: string | null;
    },
    infants?: Infant[]
  ): InvoiceCreationData => {
    const isRuc = passengerData.docType === "6"; // RUC

    const basePayload: InvoiceCreationData = {
      client_id: clientId,
      document_type_code: isRuc ? SunatInvoiceType.FACTURA : SunatInvoiceType.BOLETA,
      series: series,
      issue_date: format(new Date(), "yyyy-MM-dd"),
      issue_time: format(new Date(), "HH:mm:ss"),
      operation_type_code: "0101",
      currency_code: currencyCode,
      notes: `Punto de Venta: ${branchName}`,
      items: items,
    };

    // Agregar metodo de pago principal si esta disponible
    if (selectedPaymentMethod) {
      basePayload.payment_method_code = selectedPaymentMethod;
      basePayload.payment_operation_code = paymentOperationCode || undefined;
    }

    // Agregar datos de pago dividido si aplica
    if (splitPaymentData?.isSplitPayment) {
      basePayload.payment_amount_1 = splitPaymentData.paymentAmount1;
      basePayload.payment_method_code_2 = splitPaymentData.paymentMethodCode2;
      basePayload.payment_operation_code_2 = splitPaymentData.paymentOperationCode2 || undefined;
      basePayload.payment_amount_2 = splitPaymentData.paymentAmount2;
    }

    if (splitPaymentData?.pagoYapeId) {
      basePayload.pago_yape_id = splitPaymentData.pagoYapeId;
    }

    if (infants && infants.length > 0) {
      basePayload.infants = infants;
    }

    return basePayload;
  },

  calculateQuantity: (
    passengerData: PassengerData,
    representatives: Representative[]
  ): number => {
    const isRuc = passengerData.docType === "6"; // RUC
    return isRuc ? Math.max(1, representatives.length) : 1;
  },
};

// src/features/fluvial/components/sales-point/services/pdfUploadService.ts

import api from '../../../../../config/api';

export interface UploadResult {
  success: boolean;
  pdf_a4_url?: string;
  pdf_ticket_url?: string;
  error?: string;
}

export const pdfUploadService = {
  /**
   * Sube los PDFs de una factura al backend
   */
  uploadInvoicePDFs: async (
    invoiceId: number,
    pdfA4Blob: Blob,
    pdfTicketBlob: Blob,
    authToken: string
  ): Promise<UploadResult> => {
    try {
      // 1. Subir PDF A4
      const pdfA4URL = await pdfUploadService.uploadPDF({
        file: pdfA4Blob,
        section: 'invoices',
        documentId: invoiceId,
        fileType: 'pdf_a4',
        authToken: authToken
      });

      // 2. Subir PDF Ticket
      const pdfTicketURL = await pdfUploadService.uploadPDF({
        file: pdfTicketBlob,
        section: 'invoices',
        documentId: invoiceId,
        fileType: 'pdf_ticket',
        authToken: authToken
      });

      // 3. Actualizar la factura con las URLs de los PDFs
      await pdfUploadService.updateInvoicePDFPaths(invoiceId, {
        pdf_a4_file_path: pdfA4URL,
        pdf_ticket_file_path: pdfTicketURL
      }, authToken);

      return {
        success: true,
        pdf_a4_url: pdfA4URL,
        pdf_ticket_url: pdfTicketURL
      };

    } catch (error: any) {
      console.error('Error uploading PDFs:', error);
      return {
        success: false,
        error: error.message || 'Error al subir los PDFs'
      };
    }
  },

  /**
   * Función auxiliar para subir un PDF individual
   */
  uploadPDF: async ({ 
    file, 
    section, 
    documentId, 
    fileType, 
    authToken 
  }: {
    file: Blob;
    section: string;
    documentId: number;
    fileType: string;
    authToken: string;
  }): Promise<string> => {
    const formData = new FormData();

    // Crear nombre de archivo descriptivo
    const fileName = `${section}_${documentId}_${fileType}_${Date.now()}.pdf`;

    formData.append('file', file, fileName);
    formData.append('section', section);
    formData.append('document_id', documentId.toString());

    const response = await api.post('/files/upload', formData, {
      headers: {
        'Authorization': `Bearer ${authToken}`,
        'Content-Type': 'multipart/form-data',
      }
    });

    if (response.status !== 200) {
      throw new Error(`Upload failed: ${response.statusText}`);
    }

    const result = response.data;
    return result.data.file_url;
  },

  /**
   * Actualiza los campos PDF en la factura
   */
  updateInvoicePDFPaths: async (
    invoiceId: number, 
    pdfPaths: {
      pdf_a4_file_path?: string;
      pdf_ticket_file_path?: string;
      pdf_file_path?: string;
    }, 
    authToken: string
  ): Promise<any> => {
    const response = await api.patch(`/invoices/${invoiceId}/pdf-paths`, pdfPaths, {
      headers: {
        'Authorization': `Bearer ${authToken}`,
        'Content-Type': 'application/json'
      }
    });

    if (response.status !== 200) {
      throw new Error(`Failed to update PDF paths: ${response.statusText}`);
    }

    return response.data;
  },

  /**
   * Verifica que los PDFs se subieron correctamente
   */
  verifyPDFUpload: async (invoiceId: number, authToken: string): Promise<any[]> => {
    try {
      const response = await api.get(`/files/search?section=invoices&document_id=${invoiceId}`, {
        headers: {
          'Authorization': `Bearer ${authToken}`
        }
      });

      const result = response.data;

      if (result.success && result.data.files.length > 0) {
        const invoice = result.data.files[0];
        const pdfFiles = invoice.files.filter((f: any) => f.type.includes('pdf'));

        console.log('PDFs encontrados:', pdfFiles);
        return pdfFiles;
      }

      return [];
    } catch (error) {
      console.error('Error verificando PDFs:', error);
      return [];
    }
  }
};

import { describe, it, expect } from 'vitest';
import { saleValidationService } from './saleValidationService';
import { SunatDocType } from '../../../types/sunat.types';

describe('saleValidationService', () => {
  const validPassenger = {
    docType: SunatDocType.DNI,
    docNumber: '12345678',
    name: 'Juan Perez',
    address: '',
    phone: '',
    email: '',
  };

  const validSeat = { id: 1, seat_number: 'A1', status: 'AVAILABLE' } as any;

  describe('validateBasicSaleData', () => {
    it('returns valid for complete data', () => {
      const result = saleValidationService.validateBasicSaleData(
        1, 2, validPassenger, { id: 1 }
      );
      expect(result.isValid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    it('fails when boarding or disembarking stop is missing', () => {
      const result = saleValidationService.validateBasicSaleData(
        null, 2, validPassenger, { id: 1 }
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Seleccione origen y destino');
    });

    it('fails when doc number is empty', () => {
      const result = saleValidationService.validateBasicSaleData(
        1, 2, { ...validPassenger, docNumber: '  ' }, { id: 1 }
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Ingrese número de documento');
    });

    it('fails when name is empty', () => {
      const result = saleValidationService.validateBasicSaleData(
        1, 2, { ...validPassenger, name: '' }, { id: 1 }
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Ingrese nombre del pasajero');
    });

    it('fails when passenger service is missing', () => {
      const result = saleValidationService.validateBasicSaleData(
        1, 2, validPassenger, null
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('No se pudo cargar la información del servicio');
    });
  });

  describe('validateSeatSelection', () => {
    it('passes when showSeatMap is false', () => {
      const result = saleValidationService.validateSeatSelection(false, null);
      expect(result.isValid).toBe(true);
    });

    it('passes when showSeatMap is true and seat is selected', () => {
      const result = saleValidationService.validateSeatSelection(true, validSeat);
      expect(result.isValid).toBe(true);
    });

    it('fails when showSeatMap is true but no seat selected', () => {
      const result = saleValidationService.validateSeatSelection(true, null);
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Seleccione un número de asiento');
    });
  });

  describe('validateCompanySale', () => {
    it('passes with at least one representative', () => {
      const result = saleValidationService.validateCompanySale([{ name: 'Rep1' } as any]);
      expect(result.isValid).toBe(true);
    });

    it('fails with no representatives', () => {
      const result = saleValidationService.validateCompanySale([]);
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Agregue al menos un representante para ventas empresariales');
    });
  });

  describe('validateDocumentSeries', () => {
    it('fails for boleta when no boleta series selected', () => {
      const result = saleValidationService.validateDocumentSeries(
        validPassenger, '', 'F001'
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Seleccione una serie de Boleta');
    });

    it('passes for boleta when series is selected', () => {
      const result = saleValidationService.validateDocumentSeries(
        validPassenger, 'B001', 'F001'
      );
      expect(result.isValid).toBe(true);
    });

    it('fails for RUC when no factura series selected', () => {
      const rucPassenger = { ...validPassenger, docType: SunatDocType.RUC };
      const result = saleValidationService.validateDocumentSeries(
        rucPassenger, 'B001', ''
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Seleccione una serie de Factura');
    });

    it('passes for RUC when factura series is selected', () => {
      const rucPassenger = { ...validPassenger, docType: SunatDocType.RUC };
      const result = saleValidationService.validateDocumentSeries(
        rucPassenger, 'B001', 'F001'
      );
      expect(result.isValid).toBe(true);
    });
  });

  describe('validateCompleteSale', () => {
    it('returns basic validation errors first', () => {
      const result = saleValidationService.validateCompleteSale(
        null, 2, validPassenger, [], validSeat, true, { id: 1 }, 'B001', 'F001'
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Seleccione origen y destino');
    });

    it('returns seat validation error when seat missing', () => {
      const result = saleValidationService.validateCompleteSale(
        1, 2, validPassenger, [], null, true, { id: 1 }, 'B001', 'F001'
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Seleccione un número de asiento');
    });

    it('returns company validation error for RUC without representatives', () => {
      const rucPassenger = { ...validPassenger, docType: SunatDocType.RUC };
      const result = saleValidationService.validateCompleteSale(
        1, 2, rucPassenger, [], validSeat, true, { id: 1 }, 'B001', 'F001'
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Agregue al menos un representante para ventas empresariales');
    });

    it('returns series validation error when series missing', () => {
      const result = saleValidationService.validateCompleteSale(
        1, 2, validPassenger, [], validSeat, true, { id: 1 }, '', 'F001'
      );
      expect(result.isValid).toBe(false);
      expect(result.errors).toContain('Seleccione una serie de Boleta');
