import { format, parseISO } from 'date-fns';
import { es } from 'date-fns/locale';

/**
 * Formatea una cantidad de dinero en soles peruanos
 */
export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('es-PE', {
    style: 'currency',
    currency: 'PEN',
    minimumFractionDigits: 2
  }).format(amount);
};

/**
 * Formatea el número de documento (serie-número)
 */
export const formatDocumentNumber = (series: string, number: number): string => {
  return `${series}-${String(number).padStart(8, '0')}`;
};

/**
 * Obtiene el nombre del tipo de documento
 */
export const getDocumentTypeName = (code: string): string => {
  const documentTypes: Record<string, string> = {
    '01': 'Factura Electrónica',
    '03': 'Boleta de Venta Electrónica',
    '07': 'Nota de Crédito Electrónica',
    '08': 'Nota de Débito Electrónica',
    '1': 'DNI',
    '6': 'RUC',
    '4': 'Carnet de Extranjería',
    '7': 'Pasaporte',
    '0': 'Otros'
  };

  return documentTypes[code] || `Documento ${code}`;
};

/**
 * Formatea una fecha en formato legible
 */
export const formatDate = (dateString: string): string => {
  try {
    return format(parseISO(dateString), 'dd/MM/yyyy', { locale: es });
  } catch (error) {
    return dateString;
  }
};

/**
 * Formatea una hora en formato legible
 */
export const formatTime = (timeString: string): string => {
  try {
    // Si viene en formato HH:mm:ss, lo parseamos
    if (timeString.includes(':')) {
      return format(parseISO(`2000-01-01T${timeString}`), 'HH:mm');
    }
    return timeString;
  } catch (error) {
    return timeString;
  }
};

/**
 * Trunca texto si es muy largo
 */
export const truncateText = (text: string, maxLength: number): string => {
  if (text.length <= maxLength) return text;
  return text.substring(0, maxLength - 3) + '...';
};

/**
 * Convierte texto a mayúsculas y elimina caracteres especiales
 */
export const sanitizeText = (text: string): string => {
  return text
    .toUpperCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // Eliminar acentos
    .replace(/[^A-Z0-9\s\-\.]/g, ' ') // Solo letras, números, espacios, guiones y puntos
    .replace(/\s+/g, ' ') // Múltiples espacios a uno solo
    .trim();
};

/**
 * Calcula la altura necesaria para un texto multilínea
 */
export const calculateTextHeight = (
  text: string, 
  maxWidth: number, 
  fontSize: number, 
  lineHeight: number = 1.2
): number => {
  // Estimación aproximada basada en caracteres por línea
  const avgCharWidth = fontSize * 0.6; // Aproximación
  const charsPerLine = Math.floor(maxWidth / avgCharWidth);
  const lines = Math.ceil(text.length / charsPerLine);

  return lines * fontSize * lineHeight;
};

/**
 * Divide texto en líneas que caben en el ancho especificado
 */
export const splitTextToLines = (
  text: string, 
  maxWidth: number, 
  fontSize: number
): string[] => {
  const avgCharWidth = fontSize * 0.6; // Aproximación
  const charsPerLine = Math.floor(maxWidth / avgCharWidth);

  if (text.length <= charsPerLine) {
    return [text];
  }

  const words = text.split(' ');
  const lines: string[] = [];
  let currentLine = '';

  for (const word of words) {
    const testLine = currentLine ? `${currentLine} ${word}` : word;

    if (testLine.length <= charsPerLine) {
      currentLine = testLine;
    } else {
      if (currentLine) {
        lines.push(currentLine);
      }
      currentLine = word;
    }
  }

  if (currentLine) {
    lines.push(currentLine);
  }

  return lines;
};

/**
 * Valida que un número sea válido
 */
export const safeParseFloat = (value: string | number): number => {
  if (typeof value === 'number') return value;
  const parsed = parseFloat(value);
  return isNaN(parsed) ? 0 : parsed;
};

/**
 * Genera un código QR simple (placeholder para futuro)
 */
export const generateQRCode = (data: string): string => {
  // Por ahora retornamos un placeholder
  // En el futuro se puede integrar con una librería de QR
  return `QR:${data}`;
};

/**
 * Calcula totales de la factura
 */
export const calculateTotals = (invoice: any) => {
  const subtotal = safeParseFloat(invoice.total_taxable) + safeParseFloat(invoice.total_exonerated);
  const igv = safeParseFloat(invoice.total_igv);
  const descuento = safeParseFloat(invoice.total_global_discount);
  const total = safeParseFloat(invoice.total_payable);

  return {
    subtotal,
    igv,
    descuento,
    total,
    subtotalFormatted: formatCurrency(subtotal),
    igvFormatted: formatCurrency(igv),
    descuentoFormatted: formatCurrency(descuento),
    totalFormatted: formatCurrency(total)
  };
};

/**
 * Servicio centralizado para detección de embarcaciones sin asientos
 */

import api from '../../../../../config/api';
import { VesselDetectionResult } from './types';
import { vesselDetectionConfig } from './config';

export class VesselDetectionService {

  /**
   * Método principal para detectar si una embarcación tiene asientos
   */
  static async detectVesselType(tripId: number, vesselName?: string): Promise<VesselDetectionResult> {
    try {
      // MÉTODO 1: Consultar API del mapa de asientos
      const apiResult = await this.detectViaAPI(tripId);
      if (apiResult) {
        return apiResult;
      }
    } catch (error) {
      // Error en detección via API, continuar con métodos de respaldo
    }

    // MÉTODO 2: Detección por respaldo usando nombre de embarcación
    if (vesselName) {
      const fallbackResult = this.detectViaFallback(vesselName);
      return fallbackResult;
    }

    // MÉTODO 3: Fallback por defecto (conservador - asume que tiene asientos)
    return {
      hasSeats: true,
      method: 'fallback',
      confidence: 'low'
    };
  }

  /**
   * Detección vía API del mapa de asientos
   */
  private static async detectViaAPI(tripId: number): Promise<VesselDetectionResult | null> {
    try {
      const response = await api.get(`/operations/trips/${tripId}/seat-map`);

      if (response.status === 204) {
        return {
          hasSeats: false,
          method: 'api_204',
          confidence: 'high'
        };
      } else if (response.status === 200) {
        return {
          hasSeats: true,
          method: 'api_200',
          confidence: 'high'
        };
      }
    } catch (error: any) {
      // Si es un error 404 o similar, no es concluyente
      if (error.response?.status === 404) {
        throw error; // Reenviar para que se use el fallback
      }
      throw error;
    }

    return null;
  }

  /**
   * Detección por métodos de respaldo (nombre, listas conocidas)
   */
  private static detectViaFallback(vesselName: string): VesselDetectionResult {
    // MÉTODO 2A: Verificar listas conocidas
    const knownResult = this.detectFromKnownVessels(vesselName);
    if (knownResult) {
      return knownResult;
    }

    // MÉTODO 2B: Detección por keywords en el nombre
    const keywordResult = this.detectFromKeywords(vesselName);
    return keywordResult;
  }

  /**
   * Detectar usando lista de embarcaciones conocidas
   */
  private static detectFromKnownVessels(vesselName: string): VesselDetectionResult | null {
    const lowerName = vesselName.toLowerCase();

    // Buscar coincidencia exacta por nombre
    const knownVessel = vesselDetectionConfig.knownVessels.find(
      vessel => vessel.name.toLowerCase() === lowerName
    );

    if (knownVessel) {
      return {
        hasSeats: knownVessel.hasSeats,
        method: 'known_vessel',
        confidence: 'high'
      };
    }

    return null;
  }

  /**
   * Detectar usando keywords en el nombre de la embarcación
   */
  private static detectFromKeywords(vesselName: string): VesselDetectionResult {
    const lowerName = vesselName.toLowerCase();
    const { withSeats, withoutSeats } = vesselDetectionConfig.keywords;

    // Primero verificar keywords que indican CON asientos (para evitar falsos positivos)
    const hasSeatsKeywords = withSeats.some(keyword => lowerName.includes(keyword));
    if (hasSeatsKeywords) {
      return {
        hasSeats: true,
        method: 'name_keywords',
        confidence: 'medium'
      };
    }

    // Luego verificar keywords que indican SIN asientos
    const hasNoSeatsKeywords = withoutSeats.some(keyword => lowerName.includes(keyword));
    if (hasNoSeatsKeywords) {
      return {
        hasSeats: false,
        method: 'name_keywords',
        confidence: 'medium'
      };
    }

    // Si no hay keywords claros, asumir conservadoramente que tiene asientos
    return {
      hasSeats: true,
      method: 'fallback',
      confidence: 'low'
    };
  }
}

import React, { useState, useEffect } from 'react';
import { toast } from '@/utils/sileo-toast';
import { 
  DocumentTextIcon, 
  UsersIcon, 
  CubeIcon, 
  XMarkIcon 
} from '@heroicons/react/24/outline';
import { Button } from '../../../../components/common/Button';
import { Modal } from '../../../../components/common/Modal';
import { manifestService } from '../../../manifests/services/manifest.service';
import { UnifiedTripViewItem } from '../../hooks/useTripsView';

interface ManifestGenerationModalProps {
  isOpen: boolean;
  onClose: () => void;
  trip: UnifiedTripViewItem;
  onManifestGenerated?: () => void;
  onManifestCreated?: (manifestData: any, tripInfo: any) => void;
}

export const ManifestGenerationModal: React.FC<ManifestGenerationModalProps> = ({
  isOpen,
  onClose,
  trip,
  onManifestGenerated,
  onManifestCreated
}) => {
  const [selectedType, setSelectedType] = useState<'PASSENGER' | 'CARGO'>('PASSENGER');
  const [observations, setObservations] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [cargoValidationStatus, setCargoValidationStatus] = useState<{
    isValidated: boolean;
    canGenerate: boolean;
    message: string;
    itemCount?: number;
  }>({
    isValidated: false,
    canGenerate: true,
    message: ''
  });

  // Efecto para validar la disponibilidad de carga cuando se selecciona el tipo CARGO
  useEffect(() => {
    // Solo validar si el modal está abierto, es tipo CARGO, y no se ha validado previamente
    if (isOpen && selectedType === 'CARGO' && !cargoValidationStatus.isValidated && !isGenerating) {
      const validateCargo = async () => {
        try {
          const result = await validateCargoManifest();
          setCargoValidationStatus({
            isValidated: true,
            canGenerate: result.canGenerate,
            message: result.message,
            itemCount: result.itemCount
          });
        } catch (error) {
          console.warn('Error en validación inicial, usando valores por defecto');
          // En caso de error en la validación, asumir que se puede generar
          // El error real se manejará al intentar crear el manifiesto
        }
      };

      // Agregar un pequeño delay para evitar llamadas inmediatas
      const timeoutId = setTimeout(validateCargo, 300);

      return () => clearTimeout(timeoutId);
    }
  }, [isOpen, selectedType, isGenerating]);

  // Función para validar si se puede generar manifiesto de carga
  const validateCargoManifest = async (): Promise<{ canGenerate: boolean; message: string; itemCount?: number }> => {
    try {
      return await manifestService.validateCargoManifest(trip.trip_id);
    } catch (error: any) {
      console.error('Error en validación de manifiesto de carga:', error);
      return { 
        canGenerate: false, 
        message: 'Error al validar los datos de carga para este viaje' 
      };
    }
  };

  const handleGenerate = async () => {
    // Validación previa opcional para manifiesto de carga
    // Solo bloquear si estamos seguros de que no hay datos
    if (selectedType === 'CARGO' && cargoValidationStatus.isValidated && !cargoValidationStatus.canGenerate) {
      // Solo mostrar error si la validación fue concluyente
      toast.error(cargoValidationStatus.message);
      return;
    }

    setIsGenerating(true);
    try {
      const result = await manifestService.createOrRegenerateManifest({
        trip_id: trip.trip_id,
        manifest_type: selectedType,
        observations: observations.trim() || undefined
      });
      const actionMessage = result.isRegeneration ? 'regenerado' : 'generado';
      toast.success(`Manifiesto ${selectedType === 'PASSENGER' ? 'de Pasajeros' : 'de Carga'} ${actionMessage} exitosamente`);
      onManifestCreated?.(result.data, selectedType);
      if (onManifestGenerated) {
        onManifestGenerated();
      }
      onClose();
      resetForm();
    } catch (error: any) {
      console.error('Error al generar manifiesto:', error);

      // Manejo específico para diferentes tipos de error
      if (error.response?.status === 403) {
        // Error 403 - Sin permisos
        const errorMessage = error.response.data?.detail || 'No tienes permisos para generar manifiestos';
        toast.error(errorMessage);
      } else if (error.response?.status === 401) {
        // Error 401 puede indicar falta de datos en lugar de problema de autenticación
        if (selectedType === 'CARGO') {
          toast.error('No se puede generar el manifiesto de carga: no hay carga registrada para este viaje');
        } else {
          toast.error('No se puede generar el manifiesto de pasajeros: no hay pasajeros registrados para este viaje');
        }
      } else if (error.response?.status === 400 || error.response?.status === 422) {
        // Errores de validación o datos insuficientes
        const errorMessage = error.response.data?.message || error.response.data?.detail;
        toast.error(errorMessage || `No hay datos suficientes para generar el manifiesto de ${selectedType === 'CARGO' ? 'carga' : 'pasajeros'}`);
      } else {
        // Otros errores
        toast.error(error.message || 'Error al generar el manifiesto');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const resetForm = () => {
    setSelectedType('PASSENGER');
    setObservations('');
    setCargoValidationStatus({
      isValidated: false,
      canGenerate: true,
      message: ''
    });
  };

  const handleTypeChange = (newType: 'PASSENGER' | 'CARGO') => {
    setSelectedType(newType);
    // Reset validation status when changing type
    setCargoValidationStatus({
      isValidated: false,
      canGenerate: true,
      message: ''
    });
  };

  const handleClose = () => {
    if (!isGenerating) {
      resetForm();
      onClose();
    }
  };

  const getManifestTypeInfo = (type: 'PASSENGER' | 'CARGO') => {
    return type === 'PASSENGER' 
      ? {
          icon: UsersIcon,
          title: 'Manifiesto de Pasajeros',
          description: 'Genera un manifiesto con la lista oficial de todos los pasajeros del viaje, incluyendo sus datos personales y asientos asignados.',
          color: 'text-blue-600 dark:text-blue-400',
          bgColor: 'bg-blue-50 dark:bg-blue-950/30',
          borderColor: 'border-blue-200 dark:border-blue-800/50',
          hoverColor: 'hover:bg-blue-100 dark:bg-blue-900/40'
        }
      : {
          icon: CubeIcon,
          title: 'Manifiesto de Carga',
          description: 'Genera un manifiesto con la lista oficial de toda la carga y encomiendas transportadas en el viaje.',
          color: 'text-green-600 dark:text-green-400',
          bgColor: 'bg-green-50 dark:bg-green-950/30',
          borderColor: 'border-green-200 dark:border-green-800/50',
          hoverColor: 'hover:bg-green-100 dark:hover:bg-green-900/40'
        };
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="" maxWidth="2xl">
      <div className="space-y-6">
        {/* Header personalizado */}
        <div className="flex items-center justify-between pb-4 border-b border-dm-border-primary">
          <div className="flex items-center space-x-4">
            <div className="p-3 bg-blue-100 dark:bg-blue-900/40 rounded-xl">
              <DocumentTextIcon className="w-8 h-8 text-blue-600 dark:text-blue-400" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-dm-text-primary">
                Generar Manifiesto
              </h2>
              <p className="text-dm-text-secondary mt-1">
                {trip.vessel_name} - {new Date(trip.departure_datetime).toLocaleDateString('es-ES')}
              </p>
            </div>
          </div>

          {!isGenerating && (
            <button
              onClick={handleClose}
              className="p-2 hover:bg-dm-bg-hover rounded-lg transition-colors"
            >
              <XMarkIcon className="w-6 h-6 text-dm-text-muted hover:text-dm-text-secondary" />
            </button>
          )}
        </div>

        {/* Información del viaje compacta */}
        <div className="bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-blue-950/30 dark:to-indigo-950/30 rounded-lg p-4 border border-blue-100 dark:border-blue-800/50">
          <div className="grid grid-cols-2 gap-6">
            {/* Columna izquierda */}
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                <span className="text-sm font-medium text-dm-text-secondary">Ruta:</span>
                <span className="text-sm font-medium text-dm-text-primary">
                  {trip.origin_port_name || 'N/A'} → {trip.destination_port_name || 'N/A'}
                </span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                <span className="text-sm font-medium text-dm-text-secondary">Fecha:</span>
                <span className="text-sm font-medium text-dm-text-primary">
                  {new Date(trip.departure_datetime).toLocaleDateString('es-ES')}
                </span>
              </div>
            </div>

            {/* Columna derecha */}
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <div className="w-2 h-2 bg-orange-500 rounded-full"></div>
                <span className="text-sm font-medium text-dm-text-secondary">Hora:</span>
                <span className="text-sm font-medium text-dm-text-primary">
                  {new Date(trip.departure_datetime).toLocaleTimeString('es-ES', {
                    hour: '2-digit',
                    minute: '2-digit'
                  })}
                </span>
              </div>
              <div className="flex items-center space-x-2">
                <div className="w-2 h-2 bg-purple-500 rounded-full"></div>
                <span className="text-sm font-medium text-dm-text-secondary">Estado:</span>
                <span className="text-sm font-medium text-dm-text-primary">{trip.status}</span>
              </div>
            </div>
          </div>
        </div>

        {/* Selección de tipo de manifiesto más elegante */}
        <div>
          <h3 className="text-lg font-semibold text-dm-text-primary mb-4">Tipo de Manifiesto</h3>
          <div className="grid grid-cols-2 gap-6">
            {(['PASSENGER', 'CARGO'] as const).map((type) => {
              const info = getManifestTypeInfo(type);
              const Icon = info.icon;

              return (
                <div key={type} className="relative">
                  <input
                    type="radio"
                    id={`manifest-type-${type}`}
                    name="manifest_type"
                    value={type}
                    checked={selectedType === type}
                    onChange={(e) => handleTypeChange(e.target.value as 'PASSENGER' | 'CARGO')}
                    className="sr-only"
                    disabled={isGenerating}
                  />
                  <label
                    htmlFor={`manifest-type-${type}`}
                    className={`block cursor-pointer rounded-xl border-2 p-6 transition-all duration-200 ${
                      selectedType === type
                        ? `${info.borderColor} ${info.bgColor} shadow-lg transform scale-105`
                        : `border-dm-border-primary bg-dm-bg-primary hover:border-dm-border-primary hover:shadow-md`
                    } ${isGenerating ? 'opacity-50 cursor-not-allowed' : ''}`}
                  >
                    <div className="text-center">
                      <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4 ${
                        selectedType === type ? info.bgColor : 'bg-dm-bg-secondary'
                      }`}>
                        <Icon className={`w-8 h-8 ${
                          selectedType === type ? info.color : 'text-dm-text-muted'
                        }`} />
                      </div>
                      <h3 className={`text-lg font-semibold mb-2 ${
                        selectedType === type ? info.color : 'text-dm-text-secondary'
                      }`}>
                        {type === 'PASSENGER' ? 'Manifiesto de Pasajeros' : 'Manifiesto de Carga'}
                      </h3>
                      <p className="text-sm text-dm-text-secondary mb-2">
                        {type === 'PASSENGER' 
                          ? 'Lista oficial de pasajeros y asientos' 
                          : 'Lista oficial de carga y encomiendas'
                        }
                      </p>

                      {/* Indicador de disponibilidad para carga */}
                      {type === 'CARGO' && cargoValidationStatus.isValidated && (
                        <div className={`flex items-center space-x-2 text-xs ${
                          cargoValidationStatus.canGenerate 
                            ? 'text-green-600 dark:text-green-400' 
                            : 'text-red-600 dark:text-red-400'
                        }`}>
                          <div className={`w-2 h-2 rounded-full ${
                            cargoValidationStatus.canGenerate 
                              ? 'bg-green-400' 
                              : 'bg-red-400'
                          }`}></div>
                          <span>
                            {cargoValidationStatus.canGenerate 
                              ? (cargoValidationStatus.itemCount 
                                  ? `${cargoValidationStatus.itemCount} items de carga`
                                  : 'Carga disponible'
                                )
                              : 'No hay carga registrada'
                            }
                          </span>
                        </div>
                      )}
                    </div>
                  </label>
                </div>
              );
            })}
          </div>
        </div>

        {/* Observaciones más elegantes */}
        <div>
          <label className="block text-lg font-semibold text-dm-text-primary mb-4">
            Observaciones (Opcional)
          </label>
          <div className="relative">
            <textarea
              value={observations}
              onChange={(e) => setObservations(e.target.value)}
              rows={4}
              className="w-full px-4 py-3 border-2 border-dm-border-primary rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 resize-none text-dm-text-secondary placeholder-gray-400 dark:placeholder-gray-500"
              placeholder="Ingrese observaciones adicionales sobre el manifiesto..."
              disabled={isGenerating}
              maxLength={500}
            />
            <div className="absolute bottom-3 right-3 text-xs text-dm-text-muted">
              {observations.length}/500
            </div>
          </div>
        </div>

        {/* Botones de acción más elegantes */}
        <div className="flex justify-end space-x-4 pt-6 border-t border-dm-border-primary">
          <Button
            type="button"
            variant="secondary"
            onClick={handleClose}
            disabled={isGenerating}
            className="px-8 py-3 text-base"
          >
            Cancelar
          </Button>

          <Button
            type="button"
            variant="primary"
            onClick={handleGenerate}
            disabled={isGenerating}
            className="px-8 py-3 text-base min-w-[180px] bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800"
          >
            {isGenerating ? 'Generando...' : `Generar ${selectedType === 'PASSENGER' ? 'Pasajeros' : 'Carga'}`}
          </Button>
        </div>
      </div>
    </Modal>
  );
};

// src/features/fluvial/components/schedule/ScheduledTemplateFormModal.tsx
import React, { useState, useEffect } from 'react';
import { Modal } from '../../../../components/common/Modal';
import { Input } from '../../../../components/common/Input';
import { Button } from '../../../../components/common/Button';
import { useVessels } from '../../hooks/useVesselsData';
import { useRoutes } from '../../hooks/useVesselsRoutesData';
import { ScheduledRouteTemplate } from '../../../../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  template: ScheduledRouteTemplate | null;
  onSave: (data: any) => void;
  isLoading?: boolean;
}

const DAYS_OF_WEEK = [
  { value: 1, label: 'Lunes' },
  { value: 2, label: 'Martes' },
  { value: 3, label: 'Miércoles' },
  { value: 4, label: 'Jueves' },
  { value: 5, label: 'Viernes' },
  { value: 6, label: 'Sábado' },
  { value: 7, label: 'Domingo' },
];

export const ScheduledTemplateFormModal: React.FC<Props> = ({
  isOpen,
  onClose,
  template,
  onSave,
  isLoading = false,
}) => {
  const { data: vessels = [], isLoading: isLoadingVessels } = useVessels();
  const { data: routes = [], isLoading: isLoadingRoutes } = useRoutes();
  const [formData, setFormData] = useState({
    template_name: '',
    route_id: 0,
    day_of_week: 1,
    departure_time: '',
    vessel_id: 0,
    is_active: true,
    auto_generate_trips: true,
    generate_weeks_ahead: 4 as number | string,
  });

  const [errors, setErrors] = useState<any>({});

  const isEditing = !!template;

  useEffect(() => {
    if (template) {
      setFormData({
        template_name: template.template_name,
        route_id: template.route_id,
        day_of_week: template.day_of_week,
        departure_time: template.departure_time?.substring(0, 5) || '',
        vessel_id: template.vessel_id || 0,
        is_active: template.is_active,
        auto_generate_trips: template.auto_generate_trips,
        generate_weeks_ahead: template.generate_weeks_ahead as number | string,
      });
    } else {
      setFormData({
        template_name: '',
        route_id: 0,
        day_of_week: 1,
        departure_time: '',
        vessel_id: 0,
        is_active: true,
        auto_generate_trips: true,
        generate_weeks_ahead: 4 as number | string,
      });
    }
    setErrors({});
  }, [template]);

  const handleChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors((prev: any) => ({ ...prev, [field]: '' }));
    }
  };

  const validate = () => {
    const newErrors: any = {};
    if (!formData.template_name.trim()) {
      newErrors.template_name = 'El nombre es requerido';
    }
    if (!formData.route_id) {
      newErrors.route_id = 'Debe seleccionar una ruta';
    }
    if (!formData.departure_time) {
      newErrors.departure_time = 'La hora de salida es requerida';
    }
    if (!isEditing && (!formData.vessel_id || formData.vessel_id === 0)) {
      newErrors.vessel_id = 'Debe seleccionar una embarcación';
    }
    const weeksNum = Number(formData.generate_weeks_ahead) || 0;
    if (weeksNum < 1 || weeksNum > 52) {
      newErrors.generate_weeks_ahead = 'Debe ser entre 1 y 52 semanas';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    const departureTimeParts = formData.departure_time.split(':');
    const timeWithSeconds = `${departureTimeParts[0]}:${departureTimeParts[1]}:00`;
    const dataToSave = {
      template_name: formData.template_name,
      route_id: formData.route_id,
      day_of_week: formData.day_of_week,
      departure_time: timeWithSeconds,
      is_active: formData.is_active,
      auto_generate_trips: formData.auto_generate_trips,
      generate_weeks_ahead: Number(formData.generate_weeks_ahead || 0),
      vessel_id: formData.vessel_id > 0 ? formData.vessel_id : undefined,
    };
    onSave(dataToSave);
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title={isEditing ? 'Editar Plantilla de Viaje' : 'Nueva Plantilla de Viaje'}
      maxWidth="lg"
    >
      <form onSubmit={handleSubmit} className="p-6 space-y-4">
        <Input
          label="Nombre de la Plantilla"
          value={formData.template_name}
          onChange={(e) => handleChange('template_name', e.target.value)}
          error={errors.template_name}
          placeholder="Ej: Expreso Matutino a Yurimaguas"
          required
        />

        <div>
          <label className="block text-sm font-medium text-dm-text-secondary mb-1">
            Ruta <span className="text-red-500 dark:text-red-400">*</span>
          </label>
          <select
            value={formData.route_id}
            onChange={(e) => handleChange('route_id', parseInt(e.target.value))}
            className={`w-full rounded-md shadow-sm p-2 border bg-dm-bg-secondary text-dm-text-secondary ${
              errors.route_id ? 'border-red-500' : 'border-dm-border-primary'
            } focus:border-primary focus:ring focus:ring-primary/20 transition-colors disabled:bg-dm-bg-secondary disabled:cursor-not-allowed disabled:text-dm-text-muted`}
            disabled={isLoadingRoutes}
          >
            <option value={0}>Seleccione una ruta</option>
            {routes.map((route) => (
              <option key={route.id} value={route.id}>
                {route.name} ({route.origin_port?.name} → {route.destination_port?.name})
              </option>
            ))}
          </select>
          {errors.route_id && (
            <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.route_id}</p>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-dm-text-secondary mb-1">
              Día de la Semana
            </label>
            <select
              value={formData.day_of_week}
              onChange={(e) => handleChange('day_of_week', parseInt(e.target.value))}
              className="w-full rounded-md border-dm-border-primary shadow-sm p-2 border bg-dm-bg-secondary text-dm-text-secondary focus:border-primary focus:ring focus:ring-primary/20 transition-colors disabled:bg-dm-bg-secondary disabled:cursor-not-allowed disabled:text-dm-text-muted"
            >
              {DAYS_OF_WEEK.map((day) => (
                <option key={day.value} value={day.value}>
                  {day.label}
                </option>
              ))}
            </select>
          </div>
          <Input
            type="time"
            label="Hora de Salida"
            value={formData.departure_time}
            onChange={(e) => handleChange('departure_time', e.target.value)}
            error={errors.departure_time}
            required
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-dm-text-secondary mb-1">
            Embarcación {!isEditing && <span className="text-red-500 dark:text-red-400">*</span>}
          </label>
          <select
            value={formData.vessel_id}
            onChange={(e) => handleChange('vessel_id', parseInt(e.target.value))}
            className="w-full rounded-md border-dm-border-primary shadow-sm p-2 border bg-dm-bg-secondary text-dm-text-secondary focus:border-primary focus:ring focus:ring-primary/20 disabled:text-dm-text-muted"
            disabled={isLoadingVessels}
          >
            <option value={0}>Seleccione una embarcación</option>
            {vessels.map((vessel) => (
              <option key={vessel.id} value={vessel.id}>
                {vessel.name}
              </option>
            ))}
          </select>
          {errors.vessel_id && (
            <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.vessel_id}</p>
          )}
        </div>

        <Input
          type="number"
          label="Generar viajes con anticipación (semanas)"
          value={formData.generate_weeks_ahead}
          onChange={(e) => handleChange('generate_weeks_ahead', e.target.value === '' ? '' : parseInt(e.target.value))}
          onFocus={() => { if (Number(formData.generate_weeks_ahead) === 0) handleChange('generate_weeks_ahead', ''); }}
          onBlur={() => { if (formData.generate_weeks_ahead === '') handleChange('generate_weeks_ahead', 0); }}
          error={errors.generate_weeks_ahead}
          min={1}
          max={52}
        />

        <div className="space-y-2">
          <label className="flex items-center">
            <input
              type="checkbox"
              checked={formData.is_active}
              onChange={(e) => handleChange('is_active', e.target.checked)}
              className="rounded border-dm-border-primary text-primary focus:ring-primary"
            />
            <span className="ml-2 text-sm text-dm-text-secondary">
              Plantilla activa
            </span>
          </label>
          <label className="flex items-center">
            <input
              type="checkbox"
              checked={formData.auto_generate_trips}
              onChange={(e) => handleChange('auto_generate_trips', e.target.checked)}
              className="rounded border-dm-border-primary text-primary focus:ring-primary"
            />
            <span className="ml-2 text-sm text-dm-text-secondary">
              Generar viajes automáticamente
            </span>
          </label>
        </div>

        {!isEditing && (
          <div className="bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 rounded-md p-3">
            <p className="text-sm text-blue-800 dark:text-blue-300">
              Los viajes se generarán automáticamente según la configuración establecida.
              Puede modificar o cancelar los viajes individuales después de su creación.
            </p>
          </div>
        )}

        <div className="flex justify-end gap-3 pt-4 border-t">
          <Button
            type="button"
            variant="outline"
            onClick={onClose}
            disabled={isLoading}
          >
            Cancelar
          </Button>
          <Button
            type="submit"
            variant="primary"
            disabled={isLoading || isLoadingRoutes || isLoadingVessels}
            isLoading={isLoading}
          >
            {isEditing ? 'Actualizar' : 'Crear'} Plantilla
          </Button>
        </div>
      </form>
    </Modal>
  );
};

import React from 'react';
import { format, startOfWeek, endOfWeek, addDays } from 'date-fns';
import { es } from 'date-fns/locale';
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  XMarkIcon,
  MagnifyingGlassIcon,
} from '@heroicons/react/24/outline';
import { Button } from '../../../../components/common/Button';
import { SearchableSelect } from '../../../../components/common/SearchableSelect';
import { useCities } from '../../../../hooks/useCitiesPortsData';

export interface TripAdvancedFilters {
  origin_city_id?: number;
  destination_city_id?: number;
  status?: string;
  search?: string;
}

interface TripFiltersProps {
  currentDate: Date;
  onDateChange: (newDate: Date) => void;
  filters: TripAdvancedFilters;
  onFiltersChange: (filters: Partial<TripAdvancedFilters>) => void;
  viewMode: 'upcoming' | 'week' | 'history';
}

const TRIP_STATUS_OPTIONS = [
  { value: 'SCHEDULED', label: 'Programado' },
  { value: 'BOARDING', label: 'Embarcando' },
  { value: 'DEPARTED', label: 'En Ruta' },
  { value: 'ARRIVED', label: 'Arribado' },
  { value: 'COMPLETED', label: 'Completado' },
  { value: 'CANCELLED', label: 'Cancelado' },
];

export const TripFilters: React.FC<TripFiltersProps> = ({
  currentDate,
  onDateChange,
  filters,
  onFiltersChange,
  viewMode,
}) => {
  const { data: cities = [], isLoading: isLoadingCities } = useCities();

  const weekStart = startOfWeek(currentDate, { weekStartsOn: 1 });
  const weekEnd = endOfWeek(currentDate, { weekStartsOn: 1 });

  const handlePrevWeek = () => onDateChange(addDays(currentDate, -7));
  const handleNextWeek = () => onDateChange(addDays(currentDate, 7));

  const clearFilters = () => {
    onDateChange(new Date());
    onFiltersChange({
      origin_city_id: undefined,
      destination_city_id: undefined,
      status: undefined,
      search: undefined,
    });
  };

  // Verificacion robusta: string vacio no cuenta como filtro activo
  const hasActiveFilters =
    !!filters.origin_city_id ||
    !!filters.destination_city_id ||
    !!filters.status ||
    (typeof filters.search === 'string' && filters.search.trim().length > 0);

  const weekRangeLabel = `${format(weekStart, "d 'de' MMMM", { locale: es })} — ${format(weekEnd, "d 'de' MMMM, yyyy", { locale: es })}`;

  const cityOptions = cities.map((city: any) => ({ value: city.id, label: city.name }));

  const inputBaseClass =
    'w-full px-3 py-2.5 border border-dm-border-primary rounded-lg bg-dm-bg-secondary focus:bg-dm-bg-primary focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-colors text-sm text-dm-text-secondary placeholder-gray-400 dark:placeholder-gray-500';

  return (
    <div className="space-y-4">
      {/* Fila superior: navegador semanal o descripcion + boton limpiar */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        {/* Navegador semanal (solo en modo semana) */}
        {viewMode === 'week' ? (
          <div className="flex items-center gap-1 bg-dm-bg-secondary border border-dm-border-primary rounded-lg self-start">
            <button
              onClick={handlePrevWeek}
              className="p-2 text-dm-text-muted hover:bg-dm-bg-hover rounded-l-lg transition-colors"
              title="Semana anterior"
            >
              <ChevronLeftIcon className="h-4 w-4" />
            </button>
            <span className="px-3 py-2 text-sm font-semibold text-dm-text-secondary min-w-[220px] sm:min-w-[240px] text-center">
              {weekRangeLabel}
            </span>
            <button
              onClick={handleNextWeek}
              className="p-2 text-dm-text-muted hover:bg-dm-bg-hover rounded-r-lg transition-colors"
              title="Semana siguiente"
            >
              <ChevronRightIcon className="h-4 w-4" />
            </button>
          </div>
        ) : (
          <p className="text-sm text-dm-text-muted">
            {viewMode === 'upcoming' && 'Mostrando todos los proximos viajes programados.'}
            {viewMode === 'history' && 'Mostrando historial de viajes del ultimo ano.'}
          </p>
        )}

        {/* Boton limpiar filtros */}
        {hasActiveFilters && (
          <Button
            variant="outline"
            size="sm"
            onClick={clearFilters}
            className="text-dm-text-muted bg-dm-bg-primary hover:bg-dm-bg-hover border-dm-border-primary shadow-sm flex items-center gap-1.5 self-start sm:self-auto w-fit"
          >
            <XMarkIcon className="w-4 h-4" />
            Limpiar filtros
          </Button>
        )}
      </div>

      {/* Grid de filtros */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 pt-3 border-t border-dm-border-secondary">

        {/* Busqueda libre */}
        <div className="sm:col-span-2 lg:col-span-1">
          <label className="block text-xs font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">
            Busqueda
          </label>
          <div className="relative">
            <MagnifyingGlassIcon className="h-4 w-4 text-dm-text-muted absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
            <input
              type="text"
              value={filters.search || ''}
              onChange={(e) => onFiltersChange({ search: e.target.value || undefined })}
              placeholder="Nombre o embarcacion..."
              className={`${inputBaseClass} pl-9`}
            />
          </div>
        </div>

        {/* Estado */}
        <div>
          <label className="block text-xs font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">
            Estado
          </label>
          <select
            value={filters.status || ''}
            onChange={(e) => onFiltersChange({ status: e.target.value || undefined })}
            className={inputBaseClass}
          >
            <option value="">Todos los estados</option>
            {TRIP_STATUS_OPTIONS.map((opt) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        </div>

        {/* Ciudad Origen */}
        <div>
          <label className="block text-xs font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">
            Ciudad Origen
          </label>
          {isLoadingCities ? (
            <div className="w-full h-10 bg-dm-bg-secondary rounded-lg animate-pulse" />
          ) : (
            <SearchableSelect
              value={filters.origin_city_id ?? null}
              onChange={(val) =>
                onFiltersChange({ origin_city_id: val != null ? Number(val) : undefined })
              }
              options={cityOptions}
              placeholder="Buscar ciudad..."
              disabled={isLoadingCities}
            />
          )}
        </div>

        {/* Ciudad Destino */}
        <div>
          <label className="block text-xs font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5">
            Ciudad Destino
          </label>
          {isLoadingCities ? (
            <div className="w-full h-10 bg-dm-bg-secondary rounded-lg animate-pulse" />
          ) : (
            <SearchableSelect
              value={filters.destination_city_id ?? null}
              onChange={(val) =>
                onFiltersChange({ destination_city_id: val != null ? Number(val) : undefined })
              }
              options={cityOptions}
              placeholder="Buscar ciudad..."
              disabled={isLoadingCities}
            />
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  MapPinIcon,
  GlobeAltIcon,
  TagIcon,
  CalendarIcon,
  ClockIcon,
  SignalIcon,
  UserCircleIcon,
  ArrowRightIcon,
  ArrowLeftIcon,
  TicketIcon,
  XMarkIcon,
  ChevronDownIcon,
} from '@heroicons/react/24/outline';
import { Modal } from '../../../../components/common/Modal';
import { Input } from '../../../../components/common/Input';
import { Button } from '../../../../components/common/Button';
import { Spinner } from '../../../../components/common/Spinner';
import { useVessels } from '../../hooks/useVesselsData';
import { useRoutes } from '../../hooks/useVesselsRoutesData';
import { useTripDetails } from '../../hooks/useTrips';
import { useCaptains } from '../../hooks/useUsersData';
import { format, set } from 'date-fns';
import { UnifiedTripViewItem } from '../../hooks/useTripsView';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  trip: UnifiedTripViewItem | null;
  onSave: (data: any) => void;
  onPreviewVesselChange?: (tripId: number, newVesselId: number, data: any) => void;
  isLoading?: boolean;
  initialDate?: Date | null;
}

const TRIP_STATUS_OPTIONS = [
  { value: 'SCHEDULED', label: 'Programado' },
  { value: 'BOARDING', label: 'Embarcando' },
  { value: 'DEPARTED', label: 'En Ruta' },
  { value: 'ARRIVED', label: 'Arribado' },
  { value: 'COMPLETED', label: 'Completado' },
];

const inputWrapperClass = 'relative';
const iconLeftClass = 'absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-dm-text-muted pointer-events-none';
const selectBaseClass =
  'w-full rounded-xl border bg-dm-bg-secondary text-dm-text-secondary py-2.5 pl-10 pr-3 shadow-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all appearance-none cursor-pointer';
const nativeInputBaseClass =
  'w-full rounded-xl border bg-dm-bg-secondary text-dm-text-secondary py-2.5 pl-10 pr-3 shadow-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all';
const dateTimeInputClass =
  '[&::-webkit-calendar-picker-indicator]:opacity-0 [&::-webkit-calendar-picker-indicator]:absolute [&::-webkit-calendar-picker-indicator]:right-0 [&::-webkit-calendar-picker-indicator]:w-10 [&::-webkit-calendar-picker-indicator]:h-full [&::-webkit-calendar-picker-indicator]:cursor-pointer';
const errorTextClass = 'mt-1.5 text-xs text-red-600 dark:text-red-400';
const labelClass = 'block text-xs font-semibold text-dm-text-muted uppercase tracking-wider mb-1.5';

const openPicker = (ref: React.RefObject<HTMLInputElement | null>) => {
  const input = ref.current;
  if (!input) return;
  if ('showPicker' in input && typeof (input as any).showPicker === 'function') {
    try { (input as any).showPicker(); } catch { input.focus(); }
  } else {
    input.focus();
  }
};

export const TripFormModal: React.FC<Props> = ({
  isOpen,
  onClose,
  trip,
  onSave,
  onPreviewVesselChange,
  isLoading = false,
  initialDate,
}) => {
  const { data: vessels = [], isLoading: isLoadingVessels } = useVessels();
  const { data: routes = [], isLoading: isLoadingRoutes } = useRoutes();
  const tripIdToFetch = trip ? trip.trip_id : null;
  const { data: tripDetails, isLoading: isLoadingDetails } = useTripDetails(tripIdToFetch);
  const { captains, isLoading: isLoadingCaptains } = useCaptains();

  const dateRef = React.useRef<HTMLInputElement>(null);
  const timeRef = React.useRef<HTMLInputElement>(null);
  const departureRef = React.useRef<HTMLInputElement>(null);
  const arrivalRef = React.useRef<HTMLInputElement>(null);

  const [dateOpen, setDateOpen] = useState(false);
  const [timeOpen, setTimeOpen] = useState(false);
  const [departureOpen, setDepartureOpen] = useState(false);
  const [arrivalOpen, setArrivalOpen] = useState(false);

  const [formData, setFormData] = useState({
    route_id: 0,
    vessel_id: 0,
    trip_name: '',
    departure_datetime: '',
    can_sell_tickets: true,
    status: 'SCHEDULED',
    actual_departure_datetime: '',
    actual_arrival_datetime: '',
    captain_user_id: '',
  });

  const [errors, setErrors] = useState<any>({});
  const [datePart, setDatePart] = useState('');
  const [timePart, setTimePart] = useState('08:00');
  const [originalVesselId, setOriginalVesselId] = useState<number | null>(null);

  useEffect(() => {
    if (isOpen) {
      if (trip && tripDetails) {
        const departure = new Date(tripDetails.departure_datetime);
        setDatePart(format(departure, 'yyyy-MM-dd'));
        setTimePart(format(departure, 'HH:mm'));

        setFormData({
          route_id: tripDetails.route_id,
          vessel_id: tripDetails.vessel_id || 0,
          trip_name: tripDetails.trip_name || '',
          departure_datetime: format(new Date(tripDetails.departure_datetime), "yyyy-MM-dd'T'HH:mm"),
          can_sell_tickets: tripDetails.can_sell_tickets,
          status: tripDetails.status,
          actual_departure_datetime: tripDetails.actual_departure_datetime
            ? format(new Date(tripDetails.actual_departure_datetime), "yyyy-MM-dd'T'HH:mm")
            : '',
          actual_arrival_datetime: tripDetails.actual_arrival_datetime
            ? format(new Date(tripDetails.actual_arrival_datetime), "yyyy-MM-dd'T'HH:mm")
            : '',
          captain_user_id: tripDetails.captain_user_id || '',
        });
        setOriginalVesselId(tripDetails.vessel_id || null);
      } else if (!trip) {
        const defaultDate = initialDate ? format(initialDate, 'yyyy-MM-dd') : format(new Date(), 'yyyy-MM-dd');
        setDatePart(defaultDate);
        setTimePart('08:00');

        const defaultDateTime = initialDate ? set(initialDate, { hours: 8, minutes: 0 }) : new Date();
        setFormData({
          route_id: 0,
          vessel_id: 0,
          trip_name: '',
          departure_datetime: format(defaultDateTime, "yyyy-MM-dd'T'HH:mm"),
          can_sell_tickets: true,
          status: 'SCHEDULED',
          actual_departure_datetime: '',
          actual_arrival_datetime: '',
          captain_user_id: '',
        });
        setOriginalVesselId(null);
      }
      setErrors({});
    }
  }, [isOpen, trip, tripDetails, initialDate]);

  const handleChange = (field: string, value: any) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors((prev: any) => ({ ...prev, [field]: '' }));
    }
  };

  const validate = () => {
    const newErrors: any = {};
    if (!trip && (!formData.route_id || formData.route_id === 0)) {
      newErrors.route_id = 'Debe seleccionar una ruta.';
    }
    if (!formData.vessel_id || formData.vessel_id === 0) {
      newErrors.vessel_id = 'Debe seleccionar una embarcación.';
    }
    if (!datePart || !timePart) {
      newErrors.departure_datetime = 'La fecha y hora de salida es requerida.';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    const combinedDateTime = `${datePart}T${timePart}:00`;

    const dataToSave: any = {
      vessel_id: formData.vessel_id,
      departure_datetime: combinedDateTime,
      can_sell_tickets: formData.can_sell_tickets,
      trip_name: formData.trip_name.trim() ? formData.trip_name.trim() : undefined,
      captain_user_id: formData.captain_user_id || undefined,
    };

    if (trip) {
      dataToSave.status = formData.status;
      dataToSave.actual_departure_datetime = formData.actual_departure_datetime
        ? new Date(formData.actual_departure_datetime).toISOString()
        : undefined;
      dataToSave.actual_arrival_datetime = formData.actual_arrival_datetime
        ? new Date(formData.actual_arrival_datetime).toISOString()
        : undefined;
    } else {
      dataToSave.route_id = formData.route_id;
    }

    // Si estamos editando y cambió la embarcación, primero previsualizar
    if (trip && originalVesselId !== null && formData.vessel_id !== originalVesselId && onPreviewVesselChange) {
      onPreviewVesselChange(trip.trip_id, formData.vessel_id, dataToSave);
      return;
    }

    onSave(dataToSave);
  };

  const isFormLoading = isLoading || isLoadingDetails || isLoadingRoutes || isLoadingVessels || isLoadingCaptains;

  const sectionTitle = trip ? 'Editar Viaje' : 'Nuevo Viaje';
  const sectionSubtitle = trip
    ? `Modificando viaje #${trip.trip_id}${trip.trip_name ? ` — ${trip.trip_name}` : ''}`
    : 'Complete los datos para programar un nuevo viaje.';

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="" maxWidth="lg">
      {isFormLoading && !formData.departure_datetime ? (
        <div className="p-6 h-64 flex items-center justify-center">
          <Spinner />
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="flex flex-col max-h-[90vh]">
          {/* ── Header visual ── */}
          <div className="flex-shrink-0 px-6 pt-6 pb-4 border-b border-dm-border-secondary">
            <div className="flex items-start justify-between gap-4">
              <div className="flex items-center gap-3">
                <div className="flex items-center justify-center w-10 h-10 rounded-xl bg-primary/10 text-primary">
                  <GlobeAltIcon className="h-5 w-5" />
                </div>
                <div>
                  <h2 className="text-lg font-semibold text-dm-text-primary">{sectionTitle}</h2>
                  <p className="text-xs text-dm-text-muted mt-0.5">{sectionSubtitle}</p>
                </div>
              </div>
              <button
                type="button"
                onClick={onClose}
                className="p-1.5 rounded-lg text-dm-text-muted hover:text-dm-text-secondary hover:bg-dm-bg-hover transition-colors"
              >
                <XMarkIcon className="h-5 w-5" />
              </button>
            </div>
          </div>

          {/* ── Body scrolleable ── */}
          <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
            {/* Ruta (solo al crear) */}
            {!trip && (
              <div>
                <label className={labelClass}>
                  Ruta <span className="text-red-500 dark:text-red-400">*</span>
                </label>
                <div className={inputWrapperClass}>
                  <MapPinIcon className={iconLeftClass} />
                  <select
                    value={formData.route_id}
                    onChange={(e) => handleChange('route_id', parseInt(e.target.value))}
                    className={`${selectBaseClass} ${errors.route_id ? 'border-red-500' : 'border-dm-border-primary'}`}
                    disabled={isLoadingRoutes}
                  >
                    <option value={0}>Seleccione una ruta</option>
                    {routes.map((route) => (
                      <option key={route.id} value={route.id}>
                        {route.name} ({route.origin_port?.name} → {route.destination_port?.name})
                      </option>
                    ))}
                  </select>
                </div>
                {errors.route_id && <p className={errorTextClass}>{errors.route_id}</p>}
              </div>
            )}

            {/* Embarcación */}
            <div>
              <label className={labelClass}>
                Embarcación <span className="text-red-500 dark:text-red-400">*</span>
              </label>
              <div className={inputWrapperClass}>
                <GlobeAltIcon className={iconLeftClass} />
                <select
                  value={formData.vessel_id}
                  onChange={(e) => handleChange('vessel_id', parseInt(e.target.value))}
                  className={`${selectBaseClass} ${errors.vessel_id ? 'border-red-500' : 'border-dm-border-primary'}`}
                  disabled={isLoadingVessels}
                >
                  <option value={0}>Seleccione una embarcación</option>
                  {vessels.map((vessel) => (
                    <option key={vessel.id} value={vessel.id}>
                      {vessel.name} — {vessel.registration_number}
                    </option>
                  ))}
                </select>
              </div>
              {errors.vessel_id && <p className={errorTextClass}>{errors.vessel_id}</p>}
            </div>

            {/* Nombre del viaje */}
            <div>
              <label className={labelClass}>Nombre del Viaje (Opcional)</label>
              <div className={inputWrapperClass}>
                <TagIcon className={iconLeftClass} />
                <input
                  type="text"
                  value={formData.trip_name}
                  onChange={(e) => handleChange('trip_name', e.target.value)}
                  placeholder="Ej: Viaje Especial Navidad"
                  className={`${nativeInputBaseClass} border-dm-border-primary placeholder:text-dm-text-muted/70`}
                />
              </div>
            </div>

            {/* Fecha y hora de salida */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className={labelClass}>Fecha de Salida</label>
                <div className={inputWrapperClass}>
                  <CalendarIcon className={iconLeftClass} />
                  <input
                    type="date"
                    value={datePart}
                    onChange={(e) => setDatePart(e.target.value)}
                    ref={dateRef}
                    onFocus={() => setDateOpen(true)}
                    onBlur={() => setDateOpen(false)}
                    className={`${nativeInputBaseClass} ${dateTimeInputClass} pr-10 border-dm-border-primary`}
                    required
                  />
                  <button
                    type="button"
                    onClick={() => openPicker(dateRef)}
                    onPointerDown={(e) => e.preventDefault()}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-0.5 rounded text-dm-text-muted hover:text-dm-text-secondary transition-colors"
                    tabIndex={-1}
                  >
                    <ChevronDownIcon className={`h-4 w-4 transition-transform duration-200 ${dateOpen ? 'rotate-180' : ''}`} />
                  </button>
                </div>
              </div>
              <div>
                <label className={labelClass}>Hora de Salida</label>
                <div className={inputWrapperClass}>
                  <ClockIcon className={iconLeftClass} />
                  <input
                    type="time"
                    value={timePart}
                    onChange={(e) => setTimePart(e.target.value)}
                    ref={timeRef}
                    onFocus={() => setTimeOpen(true)}
                    onBlur={() => setTimeOpen(false)}
                    className={`${nativeInputBaseClass} ${dateTimeInputClass} pr-10 border-dm-border-primary`}
                    required
                  />
                  <button
                    type="button"
                    onClick={() => openPicker(timeRef)}
                    onPointerDown={(e) => e.preventDefault()}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-0.5 rounded text-dm-text-muted hover:text-dm-text-secondary transition-colors"
                    tabIndex={-1}
                  >
                    <ChevronDownIcon className={`h-4 w-4 transition-transform duration-200 ${timeOpen ? 'rotate-180' : ''}`} />
                  </button>
                </div>
              </div>
            </div>

            {/* Estado (solo edición) */}
            {trip && (
              <div>
                <label className={labelClass}>Estado</label>
                <div className={inputWrapperClass}>
                  <SignalIcon className={iconLeftClass} />
                  <select
                    value={formData.status}
                    onChange={(e) => handleChange('status', e.target.value)}
                    className={`${selectBaseClass} border-dm-border-primary`}
                  >
                    {TRIP_STATUS_OPTIONS.map((status) => (
                      <option key={status.value} value={status.value}>
                        {status.label}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            )}

            {/* Capitán */}
            <div>
              <label className={labelClass}>Capitán (Opcional)</label>
              <div className={inputWrapperClass}>
                <UserCircleIcon className={iconLeftClass} />
                <select
                  value={formData.captain_user_id}
                  onChange={(e) => handleChange('captain_user_id', e.target.value)}
                  className={`${selectBaseClass} border-dm-border-primary`}
                  disabled={isLoadingCaptains}
                >
                  <option value="">Seleccione un capitán</option>
                  {captains.map((captain) => (
                    <option key={captain.id} value={captain.id}>
                      {captain.full_name}
                    </option>
                  ))}
                </select>
              </div>
              {isLoadingCaptains && (
                <p className="mt-1 text-xs text-dm-text-muted">Cargando capitanes…</p>
              )}
            </div>

            {/* Fechas reales (solo edición) */}
            {trip && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className={labelClass}>Salida Real (Opcional)</label>
                  <div className={inputWrapperClass}>
                    <ArrowRightIcon className={iconLeftClass} />
                    <input
                      type="datetime-local"
                      value={formData.actual_departure_datetime}
                      onChange={(e) => handleChange('actual_departure_datetime', e.target.value)}
                      ref={departureRef}
                      onFocus={() => setDepartureOpen(true)}
                      onBlur={() => setDepartureOpen(false)}
                      className={`${nativeInputBaseClass} ${dateTimeInputClass} pr-10 border-dm-border-primary`}
                    />
                    <button
                      type="button"
                      onClick={() => openPicker(departureRef)}
                      onPointerDown={(e) => e.preventDefault()}
                      className="absolute right-3 top-1/2 -translate-y-1/2 p-0.5 rounded text-dm-text-muted hover:text-dm-text-secondary transition-colors"
                      tabIndex={-1}
                    >
                      <ChevronDownIcon className={`h-4 w-4 transition-transform duration-200 ${departureOpen ? 'rotate-180' : ''}`} />
                    </button>
                  </div>
                </div>
                <div>
                  <label className={labelClass}>Llegada Real (Opcional)</label>
                  <div className={inputWrapperClass}>
                    <ArrowLeftIcon className={iconLeftClass} />
                    <input
                      type="datetime-local"
                      value={formData.actual_arrival_datetime}
                      onChange={(e) => handleChange('actual_arrival_datetime', e.target.value)}
                      ref={arrivalRef}
                      onFocus={() => setArrivalOpen(true)}
                      onBlur={() => setArrivalOpen(false)}
                      className={`${nativeInputBaseClass} ${dateTimeInputClass} pr-10 border-dm-border-primary`}
                    />
                    <button
                      type="button"
                      onClick={() => openPicker(arrivalRef)}
                      onPointerDown={(e) => e.preventDefault()}
                      className="absolute right-3 top-1/2 -translate-y-1/2 p-0.5 rounded text-dm-text-muted hover:text-dm-text-secondary transition-colors"
                      tabIndex={-1}
                    >
                      <ChevronDownIcon className={`h-4 w-4 transition-transform duration-200 ${arrivalOpen ? 'rotate-180' : ''}`} />
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* Checkbox venta de tickets */}
            <label className="flex items-center gap-3 rounded-xl border border-dm-border-primary bg-dm-bg-secondary/50 px-4 py-3 cursor-pointer hover:bg-dm-bg-hover transition-colors">
              <TicketIcon className="h-5 w-5 text-dm-text-muted flex-shrink-0" />
              <div className="flex-1">
                <span className="text-sm font-medium text-dm-text-secondary">Permitir venta de tickets</span>
                <p className="text-xs text-dm-text-muted">Los agentes podrán vender pasajes para este viaje.</p>
              </div>
              <input
                type="checkbox"
                checked={formData.can_sell_tickets}
                onChange={(e) => handleChange('can_sell_tickets', e.target.checked)}
                className="h-4 w-4 rounded border-dm-border-primary text-primary focus:ring-primary flex-shrink-0"
              />
            </label>

            {/* Info box (solo creación) */}
            {!trip && (
              <div className="rounded-xl border border-blue-200 dark:border-blue-800/50 bg-blue-50 dark:bg-blue-950/30 p-4">
                <div className="flex items-start gap-3">
                  <div className="mt-0.5">
                    <svg
                      className="h-5 w-5 text-blue-600 dark:text-blue-400"
                      fill="none"
                      viewBox="0 0 24 24"
                      strokeWidth={1.5}
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M11.25 11.25l.041-.02a.75.75 0 011.063.852l-.708 2.836a.75.75 0 001.063.853l.041-.021M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9-3.75h.008v.008H12V8.25z"
                      />
                    </svg>
                  </div>
                  <p className="text-sm text-blue-800 dark:text-blue-300 leading-relaxed">
                    Este viaje se creará como un viaje único (no recurrente). Para viajes que se repiten
                    semanalmente, use las <strong>plantillas de viaje</strong>.
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* ── Footer con acciones ── */}
          <div className="flex-shrink-0 px-6 py-4 border-t border-dm-border-secondary bg-dm-bg-primary/50">
            <div className="flex justify-end gap-3">
              <Button
                type="button"
                variant="outline"
                onClick={onClose}
                disabled={isFormLoading}
                className="min-w-[100px]"
              >
                Cancelar
              </Button>
              <Button
                type="submit"
                variant="primary"
                disabled={isFormLoading}
                isLoading={isLoading}
                className="min-w-[140px]"
              >
                {trip ? 'Actualizar' : 'Crear'} Viaje
              </Button>
            </div>
          </div>
        </form>
      )}
    </Modal>
  );
};

// src/features/fluvial/components/seat-map/SeatMapRealtime.tsx
import React, { useMemo, useEffect, useRef } from 'react';
import { useTripDetails } from '../../hooks/useTripDetails';
import { useSeatMapRealtime } from '../../hooks/useSeatMapRealtime';
import { Spinner } from '../../../../components/common/Spinner';
import { SeatRealtime } from './SeatRealtime';
import { SeatMapItem } from '../../../../types';
import { useVessel } from '../../hooks/useVesselsData';
import { Wifi, WifiOff, AlertTriangle } from 'lucide-react';
import { getZoneTitle } from '../../utils/seatUtils';

interface SeatMapRealtimeProps {
  tripId: number;
  vesselName: string;
  selectedSeats: Set<number>;
  onSeatToggle: (seat: SeatMapItem) => void;
  isLocked?: boolean;
  userId: string;
  userName: string;
  occupiedSeatNumbers?: string[]; // Nueva prop para asientos ocupados por representantes
  isCompanyMode?: boolean; // Nueva prop para indicar si está en modo empresa (RUC)
  reservationSeatId?: number; // Nueva prop para seleccionar asiento de reservación automáticamente
}

type SeatRow = SeatMapItem[];

const ConnectionStatusIndicator: React.FC<{ status: 'connecting' | 'connected' | 'disconnected' | 'failed' }> = ({ status }) => {
  const getStatusConfig = () => {
    switch (status) {
      case 'connected':
        return {
          icon: <Wifi className="h-4 w-4" />,
          text: 'Tiempo Real Activo',
          bgColor: 'bg-green-100 dark:bg-green-900/40',
          textColor: 'text-green-800 dark:text-green-300',
          borderColor: 'border-green-200 dark:border-green-800/50'
        };
      case 'connecting':
        return {
          icon: <Wifi className="h-4 w-4 animate-pulse" />,
          text: 'Conectando...',
          bgColor: 'bg-yellow-100 dark:bg-yellow-900/40',
          textColor: 'text-yellow-800 dark:text-yellow-300',
          borderColor: 'border-yellow-200 dark:border-yellow-800/50'
        };
      case 'failed':
        return {
          icon: <AlertTriangle className="h-4 w-4" />,
          text: 'Sin tiempo real - Modo normal activo',
          bgColor: 'bg-dm-bg-secondary',
          textColor: 'text-dm-text-primary',
          borderColor: 'border-dm-border-primary'
        };
      case 'disconnected':
        return {
          icon: <WifiOff className="h-4 w-4" />,
          text: 'Sin conexión en tiempo real',
          bgColor: 'bg-red-100 dark:bg-red-900/40',
          textColor: 'text-red-800 dark:text-red-300',
          borderColor: 'border-red-200 dark:border-red-800/50'
        };
    }
  };

  const config = getStatusConfig();

  return (
    <div className={`inline-flex items-center gap-1.5 sm:gap-2 px-2.5 sm:px-3 py-1 rounded-full text-xs sm:text-sm border max-w-full ${config.bgColor} ${config.textColor} ${config.borderColor}`}>
      {config.icon}
      <span className="font-medium text-center leading-tight">{config.text}</span>
    </div>
  );
};

export const SeatMapRealtime: React.FC<SeatMapRealtimeProps> = React.memo(({ 
  tripId, 
  vesselName, 
  selectedSeats, 
  onSeatToggle, 
  isLocked = false,
  userId,
  userName,
  isCompanyMode = false, // Nueva prop con valor por defecto
  reservationSeatId // Nueva prop para asiento de reservación
}) => {
  // Referencia estable para las selecciones actuales
  const selectedSeatsRef = useRef<Set<number>>(selectedSeats);

  // Actualizar la referencia cuando cambien las selecciones
  useEffect(() => {
    selectedSeatsRef.current = selectedSeats;
  }, [selectedSeats]);

  const { data: tripDetails, isLoading: isLoadingTrip } = useTripDetails(tripId);
  const vesselId = tripDetails?.vessel?.id;
  const { data: vesselDetails, isLoading: isLoadingVessel } = useVessel(vesselId || null);

  const {
    seatMap,
    activeSeatSelections, 
    connectionStatus, 
    isLoading: isLoadingMap,
    selectSeat,
    releaseSeat,
    isWebSocketAvailable,
    canUseRealtime
  } = useSeatMapRealtime({
    tripId,
    userId,
    userName,
    enabled: !isLocked, // Solo habilitar WebSocket si no está bloqueado
    // Configuración mejorada para empresa
    companyName: undefined, // No es modo empresa en este componente
    isCompanyMode // Pasar el modo empresa al hook
  });

  // Log de los datos del mapa de asientos
  React.useEffect(() => {
    if (seatMap && seatMap.length > 0) {
      const nonAvailableSeats = seatMap.filter(seat => seat.status !== 'AVAILABLE');
      if (nonAvailableSeats.length > 0) {
        // Logging removed for production
      }

      // Log completo del estado del mapa
      // Logging removed for production
    }
  }, [seatMap?.length, connectionStatus, isWebSocketAvailable, canUseRealtime]);

  // Seleccionar automáticamente el asiento de la reservación
  React.useEffect(() => {
    if (reservationSeatId && seatMap && seatMap.length > 0 && !isLocked) {
      const reservationSeat = seatMap.find(seat => seat.id === reservationSeatId);
      if (reservationSeat && !selectedSeats.has(reservationSeatId)) {
        // Logging removed for production
        // Seleccionar el asiento automáticamente
        onSeatToggle(reservationSeat);
      } else if (reservationSeat && selectedSeats.has(reservationSeatId)) {
        // Logging removed for production
      } else if (!reservationSeat) {
        // Logging removed for production
      }
    }
  }, [reservationSeatId, seatMap, selectedSeats, onSeatToggle, isLocked]);

  // Manejar selección/deselección de asientos con notificación WebSocket
  const handleSeatToggle = (seat: SeatMapItem) => {
    if (isLocked) return;

    //  SOLUCIÓN: Verificar que el asiento no esté siendo usado por otro vendedor
    const existingSelection = activeSeatSelections?.get(seat.id);
    if (existingSelection && existingSelection.userId !== userId) {
      // El asiento está siendo usado por otro vendedor, no permitir interacción
      console.warn(`Asiento ${seat.seat_number} está siendo usado por ${existingSelection.userName}`);
      return;
    }

    // En modo empresa, NO hacer selección automática vía WebSocket
    // En modo empresa, la selección la maneja el SaleForm directamente
    if (!isCompanyMode) {
      const isCurrentlySelected = selectedSeats.has(seat.id);

      if (isCurrentlySelected) {
        // Liberar asiento
        releaseSeat(seat.id);
      } else {
        // Seleccionar asiento
        selectSeat(seat.id);
      }
    }

    // Llamar al handler original (siempre necesario para actualizar UI)
    onSeatToggle(seat);
  };

  // Liberar selección solo cuando el componente se desmonta
  const releaseSeatRef = useRef(releaseSeat);

  // Actualizar la referencia sin crear dependencia
  useEffect(() => {
    releaseSeatRef.current = releaseSeat;
  });

  useEffect(() => {
    return () => {
      // Usar la referencia actual para evitar dependencias circulares
      const currentSelectedSeats = Array.from(selectedSeatsRef.current);
      currentSelectedSeats.forEach(seatId => {
        releaseSeatRef.current(seatId);
      });
    };
  }, []); // Sin dependencias para evitar recreación infinita

  const seatLayout = useMemo(() => {
    if (!vesselDetails?.seat_configurations || !(seatMap ?? []).length) {
      return [];
    }

    const seatsByConfigId = (seatMap ?? []).reduce((acc, seat) => {
      const configId = seat.vessel_seat_config_id;
      if (!acc[configId]) acc[configId] = [];
      acc[configId].push(seat);
      return acc;
    }, {} as Record<number, SeatMapItem[]>);

    return vesselDetails.seat_configurations
      .map(config => {
        const configSeats = seatsByConfigId[config.id] || [];
        const totalColumns = vesselDetails.total_columns || 4;
        const rows: SeatRow[] = [];

        configSeats.forEach(seat => {
          const sortedSectionSeats = [...configSeats].sort((a, b) => parseInt(a.seat_number) - parseInt(b.seat_number));
          const seatIndexInSection = sortedSectionSeats.findIndex(s => s.id === seat.id);
          const rowIndex = Math.floor(seatIndexInSection / totalColumns);
          if (!rows[rowIndex]) {
            rows[rowIndex] = [];
          }
          rows[rowIndex].push(seat);
        });

        rows.forEach(row => {
          row.sort((a, b) => parseInt(a.seat_number) - parseInt(b.seat_number));
        });

        return {
          id: config.id,
          title: getZoneTitle(config.seat_type?.name || ''),
          level: config.deck_level,
          rows: rows,
          totalColumns: totalColumns,
        };
      })
      .sort((a, b) => a.level - b.level);
  }, [vesselDetails, seatMap]);

  const isLoading = isLoadingTrip || isLoadingVessel || isLoadingMap;

  if (isLoading) {
    return <div className="flex justify-center items-center h-64"><Spinner /></div>;
  }

  if (!seatLayout.length) {
    return <div className="text-center text-dm-text-muted p-8">No se pudo cargar la configuración de asientos.</div>;
  }

  //  CORRECCIÓN: Contar vendedores únicos en lugar de asientos
  // Agrupar por userId base (quitando sufijos de representantes)
  const uniqueSellers = new Set<string>();
  activeSeatSelections.forEach((selection) => {
    // Extraer userId base removiendo sufijos como -company-session-rep-X
    const baseUserId = selection.userId.split('-company-')[0];
    uniqueSellers.add(baseUserId);
  });
  const totalActiveSelections = uniqueSellers.size;

  return (
    <div className="w-full min-h-0">
      <div className="relative z-10 mb-3 sm:mb-4 overflow-hidden rounded-md bg-dm-bg-primary text-center">
        <div className="relative">
          <h2 className="text-base sm:text-lg font-bold text-dm-text-primary tracking-tight">
            Mapa de asientos
          </h2>
          <div className="mt-2 flex w-full flex-wrap items-center justify-center gap-2">
            <ConnectionStatusIndicator status={connectionStatus} />
            {canUseRealtime && totalActiveSelections > 0 && (
              <div className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-xs border bg-orange-50 dark:bg-orange-950/30 text-orange-800 dark:text-orange-300 border-orange-200/80 dark:border-orange-800/50">
                <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
                <span className="font-medium leading-tight">
                  {totalActiveSelections} vendedor{totalActiveSelections > 1 ? 'es' : ''} activo{totalActiveSelections > 1 ? 's' : ''}
                </span>
              </div>
            )}
            {connectionStatus === 'failed' && (
              <div className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-xs border bg-dm-bg-secondary text-dm-text-secondary border-dm-border-primary">
                <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
                <span className="font-medium leading-tight">Venta normal habilitada</span>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="relative z-20 -mt-4 w-full min-h-0">
        <div className="relative flex w-full justify-center overflow-x-auto overflow-y-visible touch-pan-x pb-1 pt-4">
        <div className="relative w-max max-w-full mx-auto min-w-0">
          <div className="overflow-visible rounded-lg border border-dashed border-dm-border-primary bg-dm-bg-primary shadow-sm ring-1 ring-slate-200/40 dark:ring-slate-700/40">
            <div className="relative px-5 py-2 sm:px-8 sm:py-3 bg-dm-bg-secondary">
              <div className="text-center pb-2 mb-1 border-b border-dashed border-dm-border-primary/80">
              <span className="text-[10px] sm:text-xs font-bold text-dm-text-secondary uppercase tracking-wide line-clamp-2">
                {vesselName}
              </span>
              <span className="block text-[9px] text-dm-text-muted mt-0.5">Proa</span>
              </div>

              <div className="space-y-3 sm:space-y-4">
              {seatLayout.map((section, sectionIndex) => (
                <div
                  key={section.id}
                  className={sectionIndex > 0 ? 'pt-3 border-t border-dm-border-primary/90' : ''}
                >
                  <p className="text-center text-[10px] sm:text-xs font-semibold text-dm-text-muted uppercase tracking-wider mb-2">
                    {section.title}
                  </p>
                  <div className="space-y-1.5 sm:space-y-2">
                    {section.rows.map((row, rowIndex) => (
                      <div
                        key={`${section.id}-row-${rowIndex}`}
                        className="flex justify-center items-center gap-1.5 sm:gap-2 md:gap-3"
                      >
                        <div className="flex gap-1 sm:gap-1.5 md:gap-2 shrink-0">
                          {row.slice(Math.ceil(row.length / 2)).reverse().map((seat) => {
                            const isSelected = selectedSeats.has(seat.id);
                            return (
                              <SeatRealtime
                                key={seat.id}
                                seat={seat}
                                isSelected={isSelected}
                                onClick={handleSeatToggle}
                                isLocked={isLocked}
                                activeSelection={activeSeatSelections.get(seat.id)}
                                connectionStatus={connectionStatus}
                                isWebSocketAvailable={isWebSocketAvailable}
                                isOccupiedByRepresentative={false}
                              />
                            );
                          })}
                        </div>
                        {section.totalColumns > 2 && (
                          <div className="w-4 sm:w-6 md:w-8 shrink-0 flex items-center justify-center">
                            <div className="w-px h-5 sm:h-6 md:h-7 bg-gray-300 dark:bg-gray-700" aria-hidden />
                          </div>
                        )}
                        <div className="flex gap-1 sm:gap-1.5 md:gap-2 shrink-0">
                          {row.slice(0, Math.ceil(row.length / 2)).reverse().map((seat) => {
                            const isSelected = selectedSeats.has(seat.id);
                            return (
                              <SeatRealtime
                                key={seat.id}
                                seat={seat}
                                isSelected={isSelected}
                                onClick={handleSeatToggle}
                                isLocked={isLocked}
                                activeSelection={activeSeatSelections.get(seat.id)}
                                connectionStatus={connectionStatus}
                                isWebSocketAvailable={isWebSocketAvailable}
                                isOccupiedByRepresentative={false}
                              />
                            );
                          })}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
              </div>

              <div className="text-center pt-2 mt-2 border-t border-dashed border-dm-border-primary/80">
                <span className="text-[9px] text-dm-text-muted">Trasera</span>
              </div>
            </div>
          </div>
        </div>
        </div>
      </div>
    </div>
  );
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { SeatRealtime } from './SeatRealtime';
import { SeatMapItem, SeatStatus } from '../../../../types';

vi.mock('../../utils/seatUtils', () => ({
  getSeatTypeName: (name?: string) => name || 'Estándar',
}));

describe('SeatRealtime', () => {
  const baseSeat: SeatMapItem = {
    id: 1,
    trip_id: 1,
    vessel_seat_config_id: 10,
    seat_number: 'A1',
    status: 'AVAILABLE' as SeatStatus,
    notes: '',
    seat_type: { id: 1, name: 'VIP', code: 'VIP', price_multiplier: 1 } as any,
  };

  const mockOnClick = vi.fn();

  beforeEach(() => {
    mockOnClick.mockClear();
    // Mock getBoundingClientRect for tooltip positioning
    Element.prototype.getBoundingClientRect = vi.fn(() => ({
      width: 48,
      height: 48,
      top: 100,
      left: 100,
      bottom: 148,
      right: 148,
      x: 100,
      y: 100,
      toJSON: () => {},
    }));
  });

  const renderSeat = (props: Partial<Parameters<typeof SeatRealtime>[0]> = {}) => {
    return render(
      <SeatRealtime
        seat={baseSeat}
        isSelected={false}
        onClick={mockOnClick}
        isLocked={false}
        connectionStatus="connected"
        isWebSocketAvailable={true}
        {...props}
      />
    );
  };

  it('renders seat number', () => {
    renderSeat();
    expect(screen.getByRole('button', { name: /A1/i })).toBeInTheDocument();
  });

  it('AVAILABLE seat is clickable and shows green connection indicator when connected', () => {
    renderSeat({ connectionStatus: 'connected', isWebSocketAvailable: true });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).not.toBeDisabled();
    fireEvent.click(btn);
    expect(mockOnClick).toHaveBeenCalledWith(baseSeat);
  });

  it('AVAILABLE seat shows gray indicator when connection failed', () => {
    renderSeat({ connectionStatus: 'failed' });
    const btn = screen.getByRole('button', { name: /A1/i });
    expect(btn).toBeInTheDocument();
    // The gray indicator is a child div, not directly testable by text
  });

  it('CONFIRMED seat is disabled and styled red', () => {
    renderSeat({ seat: { ...baseSeat, status: 'CONFIRMED' as SeatStatus } });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).toBeDisabled();
    expect(btn.className).toContain('bg-red-500');
  });

  it('RESERVED seat is disabled and styled yellow', () => {
    renderSeat({ seat: { ...baseSeat, status: 'RESERVED' as SeatStatus } });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).toBeDisabled();
    expect(btn.className).toContain('bg-yellow-500');
  });

  it('selected seat is blue and scaled', () => {
    renderSeat({ isSelected: true });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn.className).toContain('bg-blue-500');
    expect(btn.className).toContain('scale-105');
    expect(btn).not.toBeDisabled();
  });

  it('locked seat is not clickable', () => {
    renderSeat({ isLocked: true });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).toBeDisabled();
    fireEvent.click(btn);
    expect(mockOnClick).not.toHaveBeenCalled();
  });

  it('active selection from other user blocks click and shows orange', () => {
    renderSeat({
      activeSelection: {
        seatId: 1,
        userId: 'other-user',
        userName: 'Juan',
        timestamp: new Date().toISOString(),
        type: 'temporary',
      },
    });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).toBeDisabled();
    expect(btn.className).toContain('bg-orange-400');
  });

  it('representative active selection blocks click and shows purple', () => {
    renderSeat({
      activeSelection: {
        seatId: 1,
        userId: 'other-user',
        userName: 'Corp',
        timestamp: new Date().toISOString(),
        type: 'representative',
        companyName: 'Acme',
        representativeName: 'Rep1',
      },
    });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).toBeDisabled();
    expect(btn.className).toContain('bg-purple-500');
  });

  it('temp_reserved active selection blocks click and shows purple-400', () => {
    renderSeat({
      activeSelection: {
        seatId: 1,
        userId: 'other-user',
        userName: 'Corp',
        timestamp: new Date().toISOString(),
        type: 'temp_reserved',
        companyName: 'Acme',
      },
    });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).toBeDisabled();
    expect(btn.className).toContain('bg-purple-400');
  });

  it('isOccupiedByRepresentative blocks click and shows purple', () => {
    renderSeat({ isOccupiedByRepresentative: true });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).toBeDisabled();
    expect(btn.className).toContain('bg-purple-500');
  });

  it('click is allowed when activeSelection is from current user', () => {
    renderSeat({
      isSelected: true,
      activeSelection: {
        seatId: 1,
        userId: 'me',
        userName: 'Me',
        timestamp: new Date().toISOString(),
        type: 'temporary',
      },
    });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).not.toBeDisabled();
    fireEvent.click(btn);
    expect(mockOnClick).toHaveBeenCalled();
  });

  it('shows tooltip on mouse enter', () => {
    renderSeat();
    const btn = screen.getByRole('button', { name: /A1/i });

    fireEvent.mouseEnter(btn);
    expect(screen.getByText(/Tipo:/i)).toBeInTheDocument();
    expect(screen.getByText(/Estado:/i)).toBeInTheDocument();

    fireEvent.mouseLeave(btn);
    expect(screen.queryByText(/Tipo:/i)).not.toBeInTheDocument();
  });

  it('shows occupant tooltip for CONFIRMED seat with occupant data', () => {
    renderSeat({
      seat: {
        ...baseSeat,
        status: 'CONFIRMED' as SeatStatus,
        occupant: {
          passenger_name: 'Maria Garcia',
          origin_stop_name: 'Iquitos',
          destination_stop_name: 'Lima',
          document_number: '12345678',
          amount_paid: 150.0,
          currency_code: 'PEN',
          status_detail: 'Pagado',
        },
      },
    });

    const btn = screen.getByRole('button', { name: /A1/i });
    fireEvent.mouseEnter(btn);

    expect(screen.getByText(/Maria Garcia/i)).toBeInTheDocument();
    expect(screen.getByText(/Iquitos/i)).toBeInTheDocument();
    expect(screen.getByText(/Lima/i)).toBeInTheDocument();
  });

  it('BLOCKED seat is disabled and gray', () => {
    renderSeat({ seat: { ...baseSeat, status: 'BLOCKED' as SeatStatus } });
    const btn = screen.getByRole('button', { name: /A1/i });

    expect(btn).toBeDisabled();
    expect(btn.className).toContain('bg-gray-500');
  });
});

