// src/features/fluvial/components/seat-map/SeatRealtime.tsx
import React, { useRef, useState, useCallback } from 'react';
import { SeatMapItem, SeatStatus, SeatOccupantInfo } from '../../../../types';
import { getSeatTypeName } from '../../utils/seatUtils';

interface SeatSelection {
  seatId: number;
  userId: string;
  userName: string;
  timestamp: string;
  type?: 'temporary' | 'reserved' | 'purchasing' | 'representative' | 'temp_reserved';
  companyName?: string;
  representativeIndex?: number;
  representativeName?: string;
  ttl?: number;
  expiresAt?: string;
}

interface SeatRealtimeProps {
  seat: SeatMapItem;
  isSelected: boolean;
  onClick: (seat: SeatMapItem) => void;
  isLocked?: boolean;
  activeSelection?: SeatSelection;
  connectionStatus: 'connecting' | 'connected' | 'disconnected' | 'failed';
  isWebSocketAvailable?: boolean;
  isOccupiedByRepresentative?: boolean;
}

const getSeatStyles = (
  status: SeatStatus,
  isSelected: boolean,
  isLocked: boolean,
  activeSelection?: SeatSelection,
  connectionStatus?: string,
  isWebSocketAvailable?: boolean,
  isOccupiedByRepresentative?: boolean
): string => {
  // Si hay una selección activa de representante de otro usuario, mostrar como ocupado
  if (activeSelection && !isSelected && isWebSocketAvailable && activeSelection.type === 'representative') {
    return 'bg-purple-500 border-purple-600 text-white cursor-not-allowed animate-pulse';
  }

  // Si está ocupado por un representante (para compatibilidad)
  if (isOccupiedByRepresentative) {
    return 'bg-purple-500 border-purple-600 text-white cursor-not-allowed';
  }

  // Si hay una selección activa de otro usuario (solo si WebSocket está disponible)
  if (activeSelection && !isSelected && isWebSocketAvailable) {
    // Diferentes estilos según el tipo de selección
    if (activeSelection.type === 'representative') {
      return 'bg-purple-500 border-purple-600 text-white cursor-not-allowed animate-pulse';
    }
    // Manejar reservas temporales (SEAT_TEMP_RESERVED del backend)
    if (activeSelection.type === 'temp_reserved') {
      return 'bg-purple-400 border-purple-500 text-white cursor-not-allowed animate-pulse';
    }
    return 'bg-orange-400 border-orange-500 text-white cursor-not-allowed animate-pulse';
  }

  if (isSelected) {
    const cursorStyle = isLocked ? 'cursor-not-allowed' : '';
    return `bg-blue-500 border-blue-600 text-white shadow-lg transform scale-105 ${cursorStyle}`;
  }

  // Si está bloqueado pero el asiento NO está disponible, mostrar el estado real
  if (isLocked && status !== 'AVAILABLE') {
    switch (status) {
      case 'CONFIRMED':
        return 'bg-red-500 border-red-600 text-white cursor-not-allowed';
      case 'RESERVED':
        return 'bg-yellow-500 border-yellow-600 text-white cursor-not-allowed';
      case 'BLOCKED':
        return 'bg-gray-500 border-gray-600 dark:border-gray-400 text-white cursor-not-allowed';
      default:
        return 'bg-gray-300 dark:bg-gray-700 border-gray-400 dark:border-gray-600 dark:border-gray-400 text-dm-text-muted cursor-not-allowed';
    }
  }

  if (isLocked) {
    return 'bg-dm-bg-secondary border-dm-border-primary text-dm-text-muted cursor-not-allowed';
  }

  switch (status) {
    case 'AVAILABLE':
      // Diferentes indicadores según el estado de conexión
      let connectionIndicator = '';
      if (isWebSocketAvailable && connectionStatus === 'connected') {
        connectionIndicator = 'ring-1 ring-green-300 dark:ring-green-700';
      } else if (connectionStatus === 'failed') {
        connectionIndicator = 'ring-1 ring-dm-border-primary'; // Sin tiempo real, pero funcional
      }
      return `bg-dm-bg-primary border-dm-border-primary text-dm-text-secondary hover:border-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/30 hover:shadow-md ${connectionIndicator}`;
    case 'CONFIRMED':
      return 'bg-red-500 border-red-600 text-white cursor-not-allowed';
    case 'RESERVED':
      return 'bg-yellow-500 border-yellow-600 text-white cursor-not-allowed';
    case 'BLOCKED':
      return 'bg-gray-500 border-gray-600 dark:border-gray-400 text-white cursor-not-allowed';
    default:
      return 'bg-gray-300 dark:bg-gray-700 border-gray-400 dark:border-gray-600 dark:border-gray-400 text-dm-text-muted cursor-not-allowed';
  }
};

const OccupantTooltip: React.FC<{ occupant: SeatOccupantInfo; status: SeatStatus }> = ({ occupant, status }) => {
  const statusLabel = status === 'CONFIRMED' ? 'VENDIDO' : 'RESERVADO';
  const statusColor = status === 'CONFIRMED' ? 'text-red-300 dark:text-red-600' : 'text-yellow-300 dark:text-yellow-600';
  const mutedText = 'text-gray-300 dark:text-gray-600';
  const dimText = 'text-gray-400 dark:text-gray-500';

  return (
    <div className="text-left">
      <div className={`text-[10px] font-bold uppercase tracking-wider mb-1 ${statusColor}`}>
        {statusLabel}
      </div>
      <div className="font-semibold text-sm mb-0.5 leading-tight">{occupant.passenger_name}</div>
      {occupant.document_number && (
        <div className={`${mutedText} text-[11px] mb-0.5`}>Doc: {occupant.document_number}</div>
      )}
      <div className={`text-[11px] ${mutedText} mb-0.5`}>
        {occupant.origin_stop_name} <span className={dimText}>→</span> {occupant.destination_stop_name}
      </div>
      <div className="text-sm font-bold text-green-400 dark:text-green-600">
        {occupant.currency_code} {occupant.amount_paid.toFixed(2)}
      </div>
      {occupant.status_detail && (
        <div className={`text-[10px] ${dimText} mt-0.5`}>{occupant.status_detail}</div>
      )}
    </div>
  );
};

const SeatTooltipContent: React.FC<{
  seat: SeatMapItem;
  activeSelection?: SeatSelection;
  isOccupiedByRepresentative?: boolean;
}> = ({ seat, activeSelection, isOccupiedByRepresentative }) => {
  const seatTypeName = getSeatTypeName(seat.seat_type?.name);

  // Si tiene ocupante (CONFIRMED o RESERVED con datos del backend)
  if (seat.occupant && (seat.status === 'CONFIRMED' || seat.status === 'RESERVED')) {
    return <OccupantTooltip occupant={seat.occupant} status={seat.status} />;
  }

  // Si está ocupado por representante
  if (isOccupiedByRepresentative) {
    return (
      <div className="text-left">
        <div className="text-[10px] font-bold uppercase tracking-wider text-purple-300 dark:text-purple-600 mb-1">REPRESENTANTE</div>
        <div className="font-semibold text-sm">Asiento {seat.seat_number}</div>
        <div className="text-xs text-gray-300 dark:text-gray-600">Ocupado por representante de la empresa</div>
      </div>
    );
  }

  // Si hay una selección activa de otro usuario
  if (activeSelection) {
    if (activeSelection.type === 'representative') {
      const companyInfo = activeSelection.companyName || 'Empresa';
      const repInfo = activeSelection.representativeName || '';
      return (
        <div className="text-left">
          <div className="text-[10px] font-bold uppercase tracking-wider text-purple-300 dark:text-purple-600 mb-1">SELECCIONANDO</div>
          <div className="font-semibold text-sm">Asiento {seat.seat_number}</div>
          <div className="text-xs text-gray-300 dark:text-gray-600">Reservado para: {companyInfo}</div>
          {repInfo && <div className="text-xs text-gray-400 dark:text-gray-500">Rep: {repInfo}</div>}
        </div>
      );
    }
    if (activeSelection.type === 'temp_reserved') {
      const companyInfo = activeSelection.companyName || 'Empresa';
      const ttlInfo = activeSelection.ttl ? `Expira en ${Math.round(activeSelection.ttl / 60)} min` : '';
      return (
        <div className="text-left">
          <div className="text-[10px] font-bold uppercase tracking-wider text-purple-300 dark:text-purple-600 mb-1">RESERVA TEMPORAL</div>
          <div className="font-semibold text-sm">Asiento {seat.seat_number}</div>
          <div className="text-xs text-gray-300 dark:text-gray-600">{companyInfo}</div>
          {ttlInfo && <div className="text-xs text-orange-400 dark:text-orange-600 mt-1">{ttlInfo}</div>}
        </div>
      );
    }
    return (
      <div className="text-left">
        <div className="text-[10px] font-bold uppercase tracking-wider text-orange-300 dark:text-orange-600 mb-1">SELECCIONANDO</div>
        <div className="font-semibold text-sm">Asiento {seat.seat_number}</div>
        <div className="text-xs text-gray-300 dark:text-gray-600">Por: {activeSelection.userName}</div>
      </div>
    );
  }

  // Tooltip por defecto
  return (
    <div className="text-left">
      <div className="font-semibold text-sm">Asiento {seat.seat_number}</div>
      <div className="text-xs text-gray-300 dark:text-gray-600">Tipo: {seatTypeName}</div>
      <div className="text-xs text-gray-400 dark:text-gray-500">Estado: {seat.status}</div>
    </div>
  );
};

export const SeatRealtime: React.FC<SeatRealtimeProps> = ({
  seat,
  isSelected,
  onClick,
  isLocked = false,
  activeSelection,
  connectionStatus,
  isWebSocketAvailable = true,
  isOccupiedByRepresentative = false
}) => {
  const buttonRef = useRef<HTMLButtonElement>(null);
  const [tooltipVisible, setTooltipVisible] = useState(false);
  const [tooltipStyle, setTooltipStyle] = useState<React.CSSProperties>({});

  const showTooltip = useCallback(() => {
    if (buttonRef.current) {
      const rect = buttonRef.current.getBoundingClientRect();
      setTooltipStyle({
        position: 'fixed',
        top: rect.top - 8,
        left: rect.left + rect.width / 2,
        transform: 'translate(-50%, -100%)',
        zIndex: 9999,
        pointerEvents: 'none',
      });
      setTooltipVisible(true);
    }
  }, []);

  const hideTooltip = useCallback(() => {
    setTooltipVisible(false);
  }, []);

  // Un asiento no es clickeable si está bloqueado, su estado no es 'AVAILABLE',
  // está ocupado por un representante, o está siendo seleccionado por otro usuario (solo si WebSocket está disponible)
  const isClickable = !isLocked && seat.status === 'AVAILABLE' &&
    !isOccupiedByRepresentative &&
    !(activeSelection && isWebSocketAvailable && !isSelected);

  return (
    <div className="relative" onMouseEnter={showTooltip} onMouseLeave={hideTooltip}>
      <button
        ref={buttonRef}
        type="button"
        onClick={() => isClickable && onClick(seat)}
        disabled={!isClickable}
        className={`
          w-11 h-11 sm:w-12 sm:h-12 md:w-14 md:h-14 rounded-md sm:rounded-lg border-2 transition-all duration-200
          flex items-center justify-center text-xs sm:text-sm font-bold relative
          ${getSeatStyles(seat.status, isSelected, isLocked, activeSelection, connectionStatus, isWebSocketAvailable, isOccupiedByRepresentative)}
        `}
      >
        {seat.seat_number}

        {/* Indicador de conexión WebSocket */}
        {isWebSocketAvailable && connectionStatus === 'connected' && (
          <div className="absolute -top-1 -right-1 w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
        )}

        {/* Indicador de modo sin tiempo real */}
        {connectionStatus === 'failed' && (
          <div className="absolute -top-1 -right-1 w-2 h-2 bg-gray-400 dark:bg-gray-600 rounded-full"></div>
        )}

        {/* Indicador de selección por otro usuario (solo si WebSocket está disponible) */}
        {activeSelection && isWebSocketAvailable && (
          <div className="absolute -bottom-1 left-1/2 transform -translate-x-1/2 bg-orange-500 text-white text-xs px-1 rounded text-center whitespace-nowrap">
            {/* Diferentes indicadores según el tipo */}
            {activeSelection.type === 'representative' ? (
              <span className="bg-purple-600 px-1 rounded">
                {activeSelection.companyName ? activeSelection.companyName.substring(0, 8) : 'Empresa'}
              </span>
            ) : activeSelection.type === 'temp_reserved' ? (
              <span className="bg-purple-500 px-1 rounded">
                {activeSelection.companyName ? activeSelection.companyName.substring(0, 6) : 'Temp'}
              </span>
            ) : (
              activeSelection.userName.split(' ')[0]
            )}
          </div>
        )}
      </button>

      {/* Tooltip fixed — sale de todos los contenedores para no ser cortado */}
      {tooltipVisible && (
        <div style={tooltipStyle}>
          <div className="bg-gray-900 dark:bg-gray-100 text-white dark:text-gray-900 text-xs rounded-lg py-2 px-3 shadow-2xl border border-gray-700 dark:border-gray-300 min-w-[160px] max-w-[220px]">
            <SeatTooltipContent
              seat={seat}
              activeSelection={activeSelection}
              isOccupiedByRepresentative={isOccupiedByRepresentative}
            />
            {/* Flecha */}
            <div className="absolute top-full left-1/2 transform -translate-x-1/2 -mt-px">
              <div className="w-2 h-2 bg-gray-900 dark:bg-gray-100 border-r border-b border-gray-700 dark:border-gray-300 transform rotate-45"></div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Modal } from '../../../../components/common/Modal';
import { Button } from '../../../../components/common/Button';
import { TrashIcon, PlusIcon, InformationCircleIcon } from '@heroicons/react/24/outline';
import { useAddSeatConfiguration, useDeleteSeatConfiguration, useUpdateVessel } from '../../hooks/useVesselsData';
import { useSeatTypes } from '../../hooks/useSeatTypesData';
import { VesselWithConfigurations, SeatConfigurationCreateData, vesselValidations } from '../../../../services/vessels.service';
import { toast } from '@/utils/sileo-toast';
import { Input } from '../../../../components/common/Input';

interface ConfigRowState {
  id?: number;
  seat_type_id: number;
  total_seats: number;
  deck_level: number;
  notes?: string;
  total_rows?: number;
  total_columns?: number;
}

interface SeatConfigModalProps {
  isOpen: boolean;
  onClose: () => void;
  vessel?: VesselWithConfigurations;
}

export const SeatConfigModal: React.FC<SeatConfigModalProps> = ({ isOpen, onClose, vessel }) => {
  const addConfigsMutation = useAddSeatConfiguration();
  const deleteConfigMutation = useDeleteSeatConfiguration();
  const updateVesselMutation = useUpdateVessel();
  const { data: seatTypes = [], isLoading: isLoadingSeatTypes } = useSeatTypes();

  const [configs, setConfigs] = useState<ConfigRowState[]>([]);
  const [globalColumns, setGlobalColumns] = useState(4);
  const [errors, setErrors] = useState<string[]>([]);

  const recalculateDistribution = (prevConfigs: ConfigRowState[], columns: number): ConfigRowState[] => {
    if (columns <= 0) return prevConfigs.map(c => ({ ...c, total_rows: 0 }));
    return prevConfigs.map(config => ({
      ...config,
      total_columns: columns,
      total_rows: Math.ceil((config.total_seats || 0) / columns),
    }));
  };

  const getEmptyRow = (level: number = 1): ConfigRowState => ({
    seat_type_id: seatTypes[0]?.id || 0,
    total_seats: 0,
    deck_level: level,
    notes: '',
    total_columns: globalColumns,
    total_rows: 0,
  });

  useEffect(() => {
    if (isOpen && vessel) {
      const vesselColumns = vessel.total_columns || 4;
      setGlobalColumns(vesselColumns);

      const initialConfigs = vessel.seat_configurations?.length
        ? vessel.seat_configurations.map(c => ({ ...c }))
        : [getEmptyRow()];

      setConfigs(recalculateDistribution(initialConfigs, vesselColumns));
      setErrors([]);
    }
  }, [vessel, isOpen, seatTypes]);

  const handleGlobalColumnsChange = (value: string) => {
    const newColumns = parseInt(value) || 0;
    setGlobalColumns(newColumns);
    setConfigs(prev => recalculateDistribution(prev, newColumns));
  };

  const handleAddRow = () => {
    setConfigs(prev => {
      const lastConfig = prev[prev.length - 1];
      const newLevel = lastConfig ? (lastConfig.deck_level || 0) + 1 : 1;
      return [...prev, getEmptyRow(newLevel)];
    });
  };

  const handleRemoveRow = async (index: number, configId?: number) => {
    if (configId) {
      if (window.confirm('¿Está seguro de eliminar esta configuración guardada?')) {
        await deleteConfigMutation.mutateAsync(configId);
      }
    } else {
      setConfigs(prev => prev.filter((_, i) => i !== index));
    }
  };

  const handleChange = (index: number, field: keyof ConfigRowState, value: string) => {
    const newConfigs = [...configs];
    let parsedValue = field !== 'notes' ? parseInt(value) || 0 : value;
    newConfigs[index] = { ...newConfigs[index], [field]: parsedValue };
    if (field === 'total_seats' && globalColumns > 0) {
      const seats = typeof parsedValue === 'number' ? parsedValue : parseInt(parsedValue) || 0;
      newConfigs[index].total_rows = Math.ceil(seats / globalColumns);
      newConfigs[index].total_columns = globalColumns;
    }
    setConfigs(newConfigs);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!vessel) return;

    if (vessel.total_columns !== globalColumns) {
      await updateVesselMutation.mutateAsync({ id: vessel.id, data: { total_columns: globalColumns } });
    }

    const configsToSave: SeatConfigurationCreateData[] = configs
      .filter(c => !c.id && c.total_seats && c.total_seats > 0 && c.seat_type_id)
      .map(c => ({
        seat_type_id: c.seat_type_id,
        total_seats: c.total_seats,
        total_rows: c.total_rows!,
        total_columns: globalColumns,
        deck_level: c.deck_level,
        notes: c.notes,
      }));

    if (configsToSave.length === 0) {
      toast.info("No hay nuevas configuraciones para guardar.");
      if (!deleteConfigMutation.isPending) onClose();
      return;
    }

    const allConfigsForValidation = configs.map(c => ({
      seat_type_id: c.seat_type_id ?? 0,
      total_seats: c.total_seats ?? 0,
      total_rows: c.total_rows ?? 0,
      total_columns: c.total_columns ?? 0,
      deck_level: c.deck_level ?? 1,
      notes: c.notes ?? '',
    }));

    const validationErrors = vesselValidations.validateSeatConfiguration(allConfigsForValidation, vessel.capacity_passengers);
    if (validationErrors.length > 0) {
      setErrors(validationErrors);
      return;
    }

    try {
      await addConfigsMutation.mutateAsync({ vesselId: vessel.id, configs: configsToSave });
      onClose();
    } catch (error) {
      console.error('Failed to save seat configurations:', error);
    }
  };

  if (!vessel) return null;

  const totalConfigured = configs.reduce((sum, config) => sum + (config.total_seats || 0), 0);
  const maxPassengers = vessel.capacity_passengers || 0;

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={`Configurar Asientos: ${vessel.name}`} maxWidth="2xl">
      <form onSubmit={handleSubmit} className="p-6 flex flex-col" style={{ height: '85vh' }}>
        <p className="text-sm text-dm-text-muted mb-4">Define la distribución para cada tipo de asiento. Para modificar una configuración existente, bórrela y añádala de nuevo.</p>
        <div className="bg-dm-bg-secondary p-4 rounded-lg mb-6">
          <Input
            label="Número Total de Columnas en la Embarcación"
            type="number"
            value={globalColumns}
            onChange={(e) => handleGlobalColumnsChange(e.target.value)}
            min="1"
            required
          />
          <p className="text-xs text-dm-text-muted mt-1 flex items-center gap-1">
            <InformationCircleIcon className="h-4 w-4"/>
            Este valor define el "ancho" de la embarcación y se aplicará a todos los tipos de asiento.
          </p>
        </div>
        {errors.length > 0 && (
          <div className="mb-4 p-3 bg-red-50 dark:bg-red-950/30 text-red-700 dark:text-red-300 rounded-lg">
            <ul className="list-disc list-inside text-sm">
              {errors.map((err, i) => <li key={i}>{err}</li>)}
            </ul>
          </div>
        )}
        <div className="flex-1 space-y-4 overflow-y-auto pr-2">
          {configs.map((config, index) => (
            <div key={config.id || index} className="p-4 border border-dm-border-primary rounded-lg">
              <div className="grid grid-cols-12 gap-x-4 gap-y-3 items-end">
                <div className="col-span-12 md:col-span-4">
                  <label className="block text-sm font-medium">Tipo de Asiento</label>
                  <select
                    value={config.seat_type_id || ''}
                    onChange={(e) => handleChange(index, 'seat_type_id', e.target.value)}
                    className="w-full mt-1 p-2 border rounded-md text-sm"
                    disabled={isLoadingSeatTypes || !!config.id}
                  >
                    <option value="" disabled>Seleccionar...</option>
                    {seatTypes.map(st => <option key={st.id} value={st.id}>{st.name}</option>)}
                  </select>
                </div>
                <div className="col-span-4 md:col-span-2">
                  <label className="block text-sm font-medium">Cantidad</label>
                  <input
                    type="number"
                    value={config.total_seats || ''}
                    onChange={(e) => handleChange(index, 'total_seats', e.target.value)}
                    className="w-full mt-1 p-2 border rounded-md text-sm"
                    min="1"
                    disabled={!!config.id}
                  />
                </div>
                <div className="col-span-4 md:col-span-2">
                  <label className="block text-sm font-medium">Filas (auto)</label>
                  <input
                    type="text"
                    value={config.total_rows || 0}
                    disabled
                    className="w-full mt-1 p-2 border-dm-border-primary bg-dm-bg-secondary rounded-md text-sm text-center"
                  />
                </div>
                <div className="col-span-3 md:col-span-2">
                  <label className="block text-sm font-medium">Nivel</label>
                  <input
                    type="number"
                    value={config.deck_level || ''}
                    onChange={(e) => handleChange(index, 'deck_level', e.target.value)}
                    className="w-full mt-1 p-2 border rounded-md text-sm"
                    min="1"
                    disabled={!!config.id}
                  />
                </div>
                <div className="col-span-1 md:col-span-2 flex justify-center md:justify-end">
                  <Button
                    type="button"
                    variant="outline"
                    className="!p-2.5 text-red-600 dark:text-red-400 border-red-200 dark:border-red-800/50 hover:bg-red-50 dark:hover:bg-red-950/30"
                    onClick={() => handleRemoveRow(index, config.id)}
                    title="Eliminar"
                  >
                    <TrashIcon className="h-5 w-5" />
                  </Button>
                </div>
                <div className="col-span-12 mt-2">
                  <label className="block text-sm font-medium">Notas</label>
                  <input
                    type="text"
                    value={config.notes || ''}
                    onChange={(e) => handleChange(index, 'notes', e.target.value)}
                    className="w-full mt-1 p-2 border rounded-md text-sm"
                    placeholder="Ej: Lado ventana, cerca a salida, etc."
                    disabled={!!config.id}
                  />
                </div>
              </div>
            </div>
          ))}
        </div>
        <div className="mt-4 p-3 rounded-lg text-center" style={{ backgroundColor: totalConfigured > maxPassengers ? '#FEF2F2' : '#EFF6FF', color: totalConfigured > maxPassengers ? '#DC2626' : '#1E40AF' }}>
          <p className="text-sm font-semibold">
            Total Configurado: <strong className="text-lg">{totalConfigured}</strong> / Capacidad Máxima: <strong className="text-lg">{maxPassengers}</strong>
          </p>
        </div>
        <div className="mt-6 flex justify-between items-center border-t pt-5">
          <Button type="button" variant="outline" onClick={handleAddRow}>
            <PlusIcon className="h-4 w-4 mr-2" />
            Añadir Tipo de Asiento
          </Button>
          <div className="flex gap-3">
            <Button type="button" variant="outline" onClick={onClose}>Cancelar</Button>
            <Button type="submit" isLoading={addConfigsMutation.isPending || deleteConfigMutation.isPending}>Guardar Cambios</Button>
          </div>
        </div>
      </form>
    </Modal>
  );
};

// src/features/fluvial/contexts/WebSocketContext.tsx
import React, { createContext, useContext, useCallback, useMemo, useRef } from 'react';
import { useWebSocketConnection } from '../hooks/useWebSocketConnection';
import { WebSocketConfig, SeatUpdateMessage, ConnectionStatus } from '../types/websocket.types';

interface WebSocketContextValue {
  connectionStatus: ConnectionStatus;
  isWebSocketAvailable: boolean;
  reconnectAttempts: number;
  latency: number;
  heartbeatInterval: number;
  sendMessage: (message: any) => boolean;
  forceReconnect: () => void;
  pingConnection: () => void;
  testConnection: (testUrl?: string) => void;
  subscribe: (id: string, callback: (message: SeatUpdateMessage) => void) => () => void;
  unsubscribe: (id: string) => void;
}

const WebSocketContext = createContext<WebSocketContextValue | null>(null);

interface WebSocketProviderProps {
  children: React.ReactNode;
  config: WebSocketConfig;
}

export const WebSocketProvider: React.FC<WebSocketProviderProps> = ({ children, config }) => {
  // Mapa de suscriptores para evitar re-renders innecesarios
  const subscribersRef = useRef<Map<string, (message: SeatUpdateMessage) => void>>(new Map());

  // Handler centralizado que distribuye mensajes solo a suscriptores relevantes
  const messageHandler = useCallback((message: SeatUpdateMessage) => {
    // Filtrar suscriptores basado en el tipo de mensaje o criterios específicos
    subscribersRef.current.forEach((callback, id) => {
      try {
        // Aquí se puede implementar lógica de filtrado más sofisticada
        // Por ejemplo, solo enviar actualizaciones de asientos específicos
        callback(message);
      } catch (error) {
        console.error(`Error in subscriber ${id}:`, error);
      }
    });
  }, []);

  const connection = useWebSocketConnection(config, messageHandler);

  // Funciones de suscripción memoizadas
  const subscribe = useCallback((id: string, callback: (message: SeatUpdateMessage) => void) => {
    subscribersRef.current.set(id, callback);

    // Retornar función de cleanup
    return () => {
      subscribersRef.current.delete(id);
    };
  }, []);

  const unsubscribe = useCallback((id: string) => {
    subscribersRef.current.delete(id);
  }, []);

  // Valor del contexto memoizado para evitar re-renders
  const contextValue = useMemo(() => ({
    ...connection,
    subscribe,
    unsubscribe
  }), [
    connection.connectionStatus,
    connection.isWebSocketAvailable,
    connection.reconnectAttempts,
    connection.latency,
    connection.heartbeatInterval,
    connection.sendMessage,
    connection.forceReconnect,
    connection.pingConnection,
    connection.testConnection,
    subscribe,
    unsubscribe
  ]);

  return (
    <WebSocketContext.Provider value={contextValue}>
      {children}
    </WebSocketContext.Provider>
  );
};

// Hook personalizado para usar el contexto WebSocket
export const useWebSocket = () => {
  const context = useContext(WebSocketContext);
  if (!context) {
    throw new Error('useWebSocket must be used within a WebSocketProvider');
  }
  return context;
};

// Hook especializado para suscribirse a actualizaciones específicas
export const useWebSocketSubscription = (
  subscriberId: string,
  callback: (message: SeatUpdateMessage) => void,
  dependencies: any[] = []
) => {
  const { subscribe } = useWebSocket();

  React.useEffect(() => {
    const unsubscribe = subscribe(subscriberId, callback);
    return unsubscribe;
  }, [subscribe, subscriberId, ...dependencies]);
};

// Hook para obtener solo el estado de conexión (sin suscribirse a mensajes)
export const useWebSocketStatus = () => {
  const { connectionStatus, isWebSocketAvailable, reconnectAttempts, latency } = useWebSocket();

  return useMemo(() => ({
    connectionStatus,
    isWebSocketAvailable,
    reconnectAttempts,
    latency
  }), [connectionStatus, isWebSocketAvailable, reconnectAttempts, latency]);
};

// Hook para operaciones de conexión (sin estado)
export const useWebSocketActions = () => {
  const { sendMessage, forceReconnect, pingConnection, testConnection } = useWebSocket();

  return useMemo(() => ({
    sendMessage,
    forceReconnect,
    pingConnection,
    testConnection
  }), [sendMessage, forceReconnect, pingConnection, testConnection]);
};

