    search: vi.fn(),
    getByTrip: vi.fn(),
    create: vi.fn(),
    update: vi.fn(),
  },
}));

const createWrapper = () => {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  return ({ children }: { children: React.ReactNode }) => (
    <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
  );
};

describe('useReservations', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('useSearchReservations', () => {
    it('returns empty array when branch_office_id is missing', async () => {
      const wrapper = createWrapper();
      const { result } = renderHook(
        () => useSearchReservations({ start_date: '2024-01-01' } as any),
        { wrapper }
      );

      // Should be disabled and return no data
      expect(result.current.isLoading).toBe(false);
      expect(result.current.data).toBeUndefined();
    });

    it('fetches reservations when branch_office_id is provided', async () => {
      const mockData = [
        { id: 1, customer_name: 'John', status: 'CONFIRMED' },
      ];
      (reservationsService.search as any).mockResolvedValue(mockData);

      const wrapper = createWrapper();
      const { result } = renderHook(
        () => useSearchReservations({ branch_office_id: 1, start_date: '2024-01-01' } as any),
        { wrapper }
      );

      await waitFor(() => expect(result.current.isSuccess).toBe(true));

      expect(reservationsService.search).toHaveBeenCalledWith(
        expect.objectContaining({
          branch_office_id: 1,
          company_id: 1,
          start_date: '2024-01-01',
        })
      );
      expect(result.current.data).toEqual(mockData);
    });
  });

  describe('useReservationsByTrip', () => {
    it('does not fetch when tripId is null', () => {
      const wrapper = createWrapper();
      const { result } = renderHook(() => useReservationsByTrip(null), { wrapper });
      expect(result.current.isLoading).toBe(false);
    });

    it('fetches reservations by tripId', async () => {
      const mockData = [{ id: 2, trip_id: 42 }];
      (reservationsService.getByTrip as any).mockResolvedValue(mockData);

      const wrapper = createWrapper();
      const { result } = renderHook(() => useReservationsByTrip(42), { wrapper });

      await waitFor(() => expect(result.current.isSuccess).toBe(true));
      expect(reservationsService.getByTrip).toHaveBeenCalledWith(42);
      expect(result.current.data).toEqual(mockData);
    });
  });

  describe('useCreateReservation', () => {
    it('creates reservation and invalidates queries on success', async () => {
      const newReservation = { id: 10, trip_id: 5 };
      (reservationsService.create as any).mockResolvedValue(newReservation);

      const wrapper = createWrapper();
      const { result } = renderHook(() => useCreateReservation(), { wrapper });

      await result.current.mutateAsync({ trip_id: 5 } as any);

      expect(reservationsService.create).toHaveBeenCalledWith({ trip_id: 5 });
      // Query invalidation happens internally; we verify no error toast
      expect(mockToastError).not.toHaveBeenCalled();
    });

    it('shows 409 conflict toast on conflict error', async () => {
      const error = {
        response: { status: 409, data: { detail: 'Asiento no disponible' } },
      };
      (reservationsService.create as any).mockRejectedValue(error);

      const wrapper = createWrapper();
      const { result } = renderHook(() => useCreateReservation(), { wrapper });

      await result.current.mutateAsync({ trip_id: 5 } as any).catch(() => {});

      expect(mockToastError).toHaveBeenCalledWith('Asiento no disponible');
    });

    it('shows generic error toast on other errors', async () => {
      const error = { response: { status: 500, data: {} } };
      (reservationsService.create as any).mockRejectedValue(error);

      const wrapper = createWrapper();
      const { result } = renderHook(() => useCreateReservation(), { wrapper });

      await result.current.mutateAsync({ trip_id: 5 } as any).catch(() => {});

      expect(mockToastError).toHaveBeenCalledWith('Error al crear la reserva.');
    });
  });

  describe('useUpdateReservation', () => {
    it('updates reservation and invalidates queries on success', async () => {
      const updated = { id: 3, status: 'CONFIRMED' };
      (reservationsService.update as any).mockResolvedValue(updated);

      const wrapper = createWrapper();
      const { result } = renderHook(() => useUpdateReservation(), { wrapper });

      await result.current.mutateAsync({
        reservationId: 3,
        data: { status: 'CONFIRMED' },
        tripId: 7,
      });

      expect(reservationsService.update).toHaveBeenCalledWith(3, { status: 'CONFIRMED' });
    });

    it('shows 409 toast when reservation was already sold', async () => {
      const error = {
        response: { status: 409, data: { detail: 'Ya fue vendida' } },
      };
      (reservationsService.update as any).mockRejectedValue(error);

      const wrapper = createWrapper();
      const { result } = renderHook(() => useUpdateReservation(), { wrapper });

      await result.current.mutateAsync({
        reservationId: 3,
        data: { status: 'CONFIRMED' },
        tripId: 7,
      }).catch(() => {});

      expect(mockToastError).toHaveBeenCalledWith('Ya fue vendida');
    });

    it('shows generic error on update failure', async () => {
      const error = new Error('Network');
      (reservationsService.update as any).mockRejectedValue(error);

      const wrapper = createWrapper();
      const { result } = renderHook(() => useUpdateReservation(), { wrapper });

      await result.current.mutateAsync({
        reservationId: 3,
        data: { status: 'CONFIRMED' },
        tripId: 7,
      }).catch(() => {});

      expect(mockToastError).toHaveBeenCalledWith('Error al actualizar la reserva.');
    });
  });
});

// src/features/fluvial/hooks/useReservations.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from '@/utils/sileo-toast';
import { reservationsService, ReservationCreateData, ReservationUpdateData, ReservationSearchParams } from '../../../services/reservations.service';
import { SeatReservation } from '../../../types';
import { getErrorMessage } from '../../../utils/errorHandler';

// Hook para buscar reservas
export const useSearchReservations = (filters: Omit<ReservationSearchParams, 'company_id'>) => {
  return useQuery<SeatReservation[], Error>({
    queryKey: ['reservations', filters],
    queryFn: () => {
      // Asumimos que podemos obtener el company_id de alguna forma
      const companyId = 1; // Reemplazar con lógica real de autenticación

      if (!filters.branch_office_id) {
        // No hacemos la búsqueda si no hay una sucursal seleccionada
        return Promise.resolve([]);
      }

      return reservationsService.search({ ...filters, company_id: companyId });
    },
    enabled: !!filters.branch_office_id, // La query solo se ejecuta si hay un branch_office_id
  });
};

// Hook para obtener todas las reservas de un viaje
export const useReservationsByTrip = (tripId: number | null) => {
  return useQuery<SeatReservation[], Error>({
    queryKey: ['reservations', tripId],
    queryFn: () => (tripId ? reservationsService.getByTrip(tripId) : Promise.resolve([])),
    enabled: !!tripId,
  });
};

// Hook para crear una nueva reserva
export const useCreateReservation = () => {
  const queryClient = useQueryClient();
  return useMutation<SeatReservation, Error, ReservationCreateData>({
    mutationFn: (data) => reservationsService.create(data),
    onSuccess: (newReservation) => {
      // Toast eliminado para evitar múltiples mensajes durante el flujo de venta
      // Invalidamos el mapa de asientos para que se actualice el estado a 'RESERVED'
      queryClient.invalidateQueries({ queryKey: ['seatMap', newReservation.trip_id] });
      // Invalidamos la lista de reservas del viaje
      queryClient.invalidateQueries({ queryKey: ['reservations', newReservation.trip_id] });
    },
    onError: (error: any) => {
      if (error?.response?.status === 409) {
        const detail = error.response?.data?.detail;
        toast.error(detail || "El asiento ya no está disponible. Seleccione otro asiento.");
      } else {
        const message = getErrorMessage(error, "Error al crear la reserva.");
        toast.error(message);
      }
    },
  });
};

// Hook para actualizar una reserva (confirmar, cancelar)
export const useUpdateReservation = () => {
  const queryClient = useQueryClient();
  // La mutación ahora acepta un `tripId` para la invalidación de queries
  return useMutation<SeatReservation, Error, { reservationId: number; data: Partial<ReservationUpdateData>; tripId: number }>({
    mutationFn: ({ reservationId, data }) => reservationsService.update(reservationId, data),
    onSuccess: (_, variables) => {
      // Toast eliminado para evitar múltiples mensajes durante el flujo de venta
      // Invalidar para actualizar la lista de reservas y el mapa de asientos
      queryClient.invalidateQueries({ queryKey: ['reservations', { tripId: variables.tripId }] }); // Mejor ser específico
      queryClient.invalidateQueries({ queryKey: ['seatMap', variables.tripId] });
      queryClient.invalidateQueries({ queryKey: ['reservations'] }); // Invalidar la lista general también
    },
    onError: (error: any) => {
      if (error?.response?.status === 409) {
        const detail = error.response?.data?.detail;
        toast.error(detail || "No se puede modificar esta reserva porque ya fue vendida o está bloqueada.");
      } else {
        const message = getErrorMessage(error, "Error al actualizar la reserva.");
        toast.error(message);
      }
    },
  });
};

import { useState, useEffect, useRef, useCallback } from 'react';
import { toast } from '@/utils/sileo-toast';
import { usePortsData } from '../../../hooks/usePorts';
import {
  useUpdateRouteStops,
  routeHelpers,
} from '../hooks/useVesselsRoutesData';
import { RouteWithStops, RouteStopCreateData } from '../../../services/routes.service';
import { RouteStop } from '../../../types';

export function useRouteMap(isOpen: boolean, route?: RouteWithStops) {
  const updateRouteStops = useUpdateRouteStops();
  const { data: ports = [] } = usePortsData();

  const [stops, setStops] = useState<Partial<RouteStop>[]>([]);
  const [viewMode, setViewMode] = useState<'map' | 'list'>('map');
  const [selectedStop, setSelectedStop] = useState<Partial<RouteStop> | null>(null);
  const [isStopModalOpen, setIsStopModalOpen] = useState(false);
  const [editingStop, setEditingStop] = useState<Partial<RouteStop> | null>(null);
  const [isAddStopModalOpen, setIsAddStopModalOpen] = useState(false);
  const [addStopPosition, setAddStopPosition] = useState<number>(0);

  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [dragOverItem, setDragOverItem] = useState<number | null>(null);

  const [dynamicRiverPath, setDynamicRiverPath] = useState('');
  const [stopPositions, setStopPositions] = useState<{ x: number; y: number }[]>([]);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [viewBox, setViewBox] = useState({ x: 0, y: 0, width: 1200, height: 900 });

  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });

  const mapContainerRef = useRef<HTMLDivElement>(null);

  // Inicializar paradas
  useEffect(() => {
    if (isOpen && route) {
      if (route.stops && route.stops.length > 0) {
        const stopsWithPortObjects = route.stops.map((stop) => ({
          ...stop,
          port: ports.find((p) => p.id === stop.port_id),
        }));
        setStops(stopsWithPortObjects);
      } else {
        const originPort = ports.find((p) => p.id === route.origin_port_id);
        const destinationPort = ports.find((p) => p.id === route.destination_port_id);
        const originStop: Partial<RouteStop> = {
          port_id: route.origin_port_id,
          stop_order: 1,
          estimated_duration_from_origin: 'PT0S',
          is_boarding_allowed: true,
          is_disembarking_allowed: false,
          notes: 'Puerto de origen',
          port: originPort,
        };
        const destinationStop: Partial<RouteStop> = {
          port_id: route.destination_port_id,
          stop_order: 2,
          estimated_duration_from_origin: route.estimated_duration,
          is_boarding_allowed: false,
          is_disembarking_allowed: true,
          notes: 'Puerto de destino',
          port: destinationPort,
        };
        setStops([originStop, destinationStop]);
      }
    }
  }, [isOpen, route, ports]);

  // Calcular río y posiciones
  useEffect(() => {
    const basePositions = [
      { x: 120, y: 60 },
      { x: 280, y: 140 },
      { x: 450, y: 180 },
      { x: 580, y: 260 },
      { x: 750, y: 280 },
      { x: 820, y: 380 },
      { x: 880, y: 480 },
      { x: 820, y: 580 },
      { x: 680, y: 680 },
      { x: 520, y: 750 },
      { x: 380, y: 820 },
    ];
    const baseRiverPath =
      'M 120 60 Q 200 100, 280 140 Q 360 160, 450 180 Q 520 220, 580 260 Q 670 270, 750 280 Q 785 330, 820 380 Q 850 430, 880 480 Q 850 530, 820 580 Q 750 630, 680 680 Q 600 715, 520 750 Q 450 785, 380 820';

    if (stops.length === 0) {
      setDynamicRiverPath('');
      setStopPositions([]);
      setViewBox({ x: 0, y: 0, width: 1200, height: 900 });
      return;
    }

    let calculatedPositions: { x: number; y: number }[] = [];
    let calculatedPath = baseRiverPath;
    let maxX = 880;
    let maxY = 820;

    if (stops.length <= basePositions.length) {
      const tempPositions = [];
      for (let i = 0; i < stops.length; i++) {
        if (i === 0) {
          tempPositions.push(basePositions[0]);
          continue;
        }
        if (i === stops.length - 1) {
          tempPositions.push(basePositions[basePositions.length - 1]);
          continue;
        }
        const intermediatePositions = basePositions.slice(1, -1);
        const intermediateStopsCount = stops.length - 2;
        const currentIntermediateIndex = i - 1;
        const ratio = (currentIntermediateIndex + 1) / (intermediateStopsCount + 1);
        const targetSlotIndex = Math.floor(ratio * intermediatePositions.length);
        const finalIndex = Math.min(targetSlotIndex, intermediatePositions.length - 1);
        tempPositions.push(intermediatePositions[finalIndex]);
      }
      calculatedPositions = tempPositions;
    } else {
      calculatedPositions = [...basePositions];
      let currentPath = baseRiverPath;
      const extraStops = stops.length - basePositions.length;
      const spacingX = Math.max(80, 200 - extraStops * 5);
      const spacingY = 25;

      for (let i = basePositions.length; i < stops.length; i++) {
        const stopIndex = i - basePositions.length;
        const lastPos = calculatedPositions[calculatedPositions.length - 1];
        let nextPos;
        if (stopIndex % 4 === 0) {
          nextPos = { x: lastPos.x + spacingX, y: lastPos.y + spacingY };
        } else if (stopIndex % 4 === 1) {
          nextPos = { x: lastPos.x + spacingX * 0.7, y: lastPos.y + spacingY * 2 };
        } else if (stopIndex % 4 === 2) {
          nextPos = { x: lastPos.x + spacingX * 0.8, y: lastPos.y - spacingY * 0.5 };
        } else {
          nextPos = { x: lastPos.x + spacingX * 0.9, y: lastPos.y + spacingY * 1.5 };
        }

        calculatedPositions.push(nextPos);
        maxX = Math.max(maxX, nextPos.x);
        maxY = Math.max(maxY, nextPos.y);

        const controlPoint1 = {
          x: lastPos.x + (nextPos.x - lastPos.x) * 0.3,
          y: lastPos.y + (nextPos.y - lastPos.y) * 0.7 + Math.sin(stopIndex) * 15,
        };
        const controlPoint2 = {
          x: lastPos.x + (nextPos.x - lastPos.x) * 0.7,
          y: lastPos.y + (nextPos.y - lastPos.y) * 0.3 - Math.cos(stopIndex) * 10,
        };

        currentPath += ` C ${controlPoint1.x} ${controlPoint1.y}, ${controlPoint2.x} ${controlPoint2.y}, ${nextPos.x} ${nextPos.y}`;
      }
      calculatedPath = currentPath;
    }

    const padding = 100;
    const dynamicViewBox = {
      x: -padding,
      y: -padding,
      width: maxX + padding * 2,
      height: maxY + padding * 2,
    };

    setDynamicRiverPath(calculatedPath);
    setStopPositions(calculatedPositions);
    setViewBox(dynamicViewBox);
  }, [stops.length]);

  // Wheel zoom
  useEffect(() => {
    const mapContainer = mapContainerRef.current;
    if (!mapContainer) return;

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      const delta = e.deltaY > 0 ? -0.1 : 0.1;
      setZoomLevel((prev) => Math.max(0.3, Math.min(2, prev + delta)));
    };

    mapContainer.addEventListener('wheel', handleWheel, { passive: false });
    return () => {
      mapContainer.removeEventListener('wheel', handleWheel);
    };
  }, []);

  const getRiverPosition = (index: number) => {
    return stopPositions[index] || { x: 0, y: 0 };
  };

  const isStopFixed = useCallback((index: number) => {
    return index === 0 || index === stops.length - 1;
  }, [stops.length]);

  // Pan handlers
  // Touch pan state
  const [touchStart, setTouchStart] = useState<{ x: number; y: number } | null>(null);

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    const target = e.target as SVGElement;
    if (target.tagName === 'circle' || target.tagName === 'text') return;
    setIsPanning(true);
    setPanStart({ x: e.clientX, y: e.clientY });
    e.preventDefault();
  }, []);

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      if (!isPanning) return;
      const deltaX = e.clientX - panStart.x;
      const deltaY = e.clientY - panStart.y;
      const sensitivity = 1 / zoomLevel;
      setPanOffset({
        x: deltaX * sensitivity,
        y: deltaY * sensitivity,
      });
    },
    [isPanning, panStart, zoomLevel]
  );

  const handleMouseUp = useCallback(() => {
    if (isPanning) {
      setViewBox((prev) => ({
        x: prev.x - panOffset.x,
        y: prev.y - panOffset.y,
        width: prev.width,
        height: prev.height,
      }));
      setPanOffset({ x: 0, y: 0 });
    }
    setIsPanning(false);
  }, [isPanning, panOffset]);

  const handleMouseLeave = useCallback(() => {
    if (isPanning) {
      handleMouseUp();
    }
  }, [isPanning, handleMouseUp]);

  // Touch handlers for mobile pan
  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    if (e.touches.length === 1) {
      const target = e.target as SVGElement;
      if (target.tagName === 'circle' || target.tagName === 'text') return;
      setIsPanning(true);
      setTouchStart({ x: e.touches[0].clientX, y: e.touches[0].clientY });
    }
  }, []);

  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (!isPanning || e.touches.length !== 1 || !touchStart) return;
    e.preventDefault();
    const deltaX = e.touches[0].clientX - touchStart.x;
    const deltaY = e.touches[0].clientY - touchStart.y;
    const sensitivity = 1 / zoomLevel;
    setPanOffset({
      x: deltaX * sensitivity,
      y: deltaY * sensitivity,
    });
  }, [isPanning, touchStart, zoomLevel]);

  const handleTouchEnd = useCallback(() => {
    if (isPanning) {
      setViewBox((prev) => ({
        x: prev.x - panOffset.x,
        y: prev.y - panOffset.y,
        width: prev.width,
        height: prev.height,
      }));
      setPanOffset({ x: 0, y: 0 });
    }
    setIsPanning(false);
    setTouchStart(null);
  }, [isPanning, panOffset]);

  // Drag & drop
  const handleDragStart = useCallback(
    (e: React.DragEvent, index: number) => {
      if (isStopFixed(index)) {
        e.preventDefault();
        return;
      }
      setDraggedIndex(index);
      e.dataTransfer.effectAllowed = 'move';
    },
    [isStopFixed]
  );

  const handleDragOver = useCallback(
    (e: React.DragEvent, index: number) => {
      e.preventDefault();
      if (isStopFixed(index)) return;
      setDragOverItem(index);
    },
    [isStopFixed]
  );

  const handleDrop = useCallback(
    (e: React.DragEvent, dropIndex: number) => {
      e.preventDefault();
      if (draggedIndex === null || isStopFixed(dropIndex)) {
        setDraggedIndex(null);
        setDragOverItem(null);
        return;
      }
      if (dropIndex === 0 || dropIndex === stops.length - 1) {
        setDraggedIndex(null);
        setDragOverItem(null);
        return;
      }
      const newStops = [...stops];
      const draggedItem = newStops.splice(draggedIndex, 1)[0];
      newStops.splice(dropIndex, 0, draggedItem);
      const finalStops = newStops.map((stop, index) => ({
        ...stop,
        stop_order: index + 1,
      }));
      setStops(finalStops);
      setDraggedIndex(null);
      setDragOverItem(null);
    },
    [draggedIndex, isStopFixed, stops]
  );

  // Move stop up/down for mobile reordering (no drag & drop)
  const moveStopUp = useCallback(
    (index: number) => {
      if (index <= 1) return;
      const newStops = [...stops];
      const temp = newStops[index];
      newStops[index] = newStops[index - 1];
      newStops[index - 1] = temp;
      const finalStops = newStops.map((stop, i) => ({
        ...stop,
        stop_order: i + 1,
      }));
      setStops(finalStops);
    },
    [stops]
  );

  const moveStopDown = useCallback(
    (index: number) => {
      if (index >= stops.length - 2) return;
      const newStops = [...stops];
      const temp = newStops[index];
      newStops[index] = newStops[index + 1];
      newStops[index + 1] = temp;
      const finalStops = newStops.map((stop, i) => ({
        ...stop,
        stop_order: i + 1,
      }));
      setStops(finalStops);
    },
    [stops]
  );

  const handleStopClick = useCallback((stop: Partial<RouteStop>) => {
    setSelectedStop(stop);
    setIsStopModalOpen(true);
  }, []);

  const openAddStopModal = useCallback(() => {
    if (stops.length < 2) return;
    const insertIndex = stops.length - 1;
    setAddStopPosition(insertIndex);
    setIsAddStopModalOpen(true);
  }, [stops.length]);

  const handleAddStop = useCallback(
    (stopData: Partial<RouteStop>) => {
      const newStops = [...stops];
      newStops.splice(addStopPosition, 0, stopData);
      const finalStops = newStops.map((stop, index) => ({
        ...stop,
        stop_order: index + 1,
      }));
      setStops(finalStops);
    },
    [addStopPosition, stops]
  );

  const removeStop = useCallback(
    (index: number) => {
      if (isStopFixed(index)) return;
      const newStops = stops.filter((_, i) => i !== index);
      const finalStops = newStops.map((s, i) => ({ ...s, stop_order: i + 1 }));
      setStops(finalStops);
    },
    [isStopFixed, stops]
  );

  const updateStop = useCallback(
    (index: number, field: keyof RouteStop, value: any) => {
      const newStops = [...stops];
      let updatedStop: Partial<RouteStop> = { ...newStops[index] };
      if (field === 'estimated_duration_from_origin' && typeof value === 'object') {
        const totalHours = (value.hours || 0) + (value.minutes || 0) / 60;
        updatedStop.estimated_duration_from_origin = routeHelpers.hoursToISOString(totalHours);
      } else if (field === 'port_id') {
        updatedStop.port_id = value;
        updatedStop.port = ports.find((p) => p.id === value);
      } else {
        (updatedStop as any)[field] = value;
      }
      newStops[index] = updatedStop;
      setStops(newStops);
    },
    [ports, stops]
  );

  const startEditing = useCallback((stop: Partial<RouteStop>) => {
    setEditingStop({ ...stop });
  }, []);

  const saveEdit = useCallback(() => {
    if (editingStop) {
      setStops((prev) =>
        prev.map((stop) =>
          stop.stop_order === editingStop.stop_order ? editingStop : stop
        )
      );
      setEditingStop(null);
    }
  }, [editingStop]);

  const handleSubmit = useCallback(
    async (e: React.FormEvent, onClose: () => void) => {
      e.preventDefault();
      if (!route) return;
      const payload = stops.map(({ port, id, route_id, ...rest }) => rest) as RouteStopCreateData[];
      await updateRouteStops.mutateAsync({
        routeId: route.id,
        stops: payload,
      });
      onClose();
    },
    [route, stops, updateRouteStops]
  );

  const parseDurationForUI = useCallback((isoString?: string) => {
    const totalHours = routeHelpers.isoStringToHours(isoString || 'PT0S');
    return {
      hours: Math.floor(totalHours),
      minutes: Math.round((totalHours % 1) * 60),
    };
  }, []);

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
    const padding = 100;
    const maxX = Math.max(880, ...stopPositions.map((pos) => pos.x));
    const maxY = Math.max(820, ...stopPositions.map((pos) => pos.y));
    setViewBox({
      x: -padding,
      y: -padding,
      width: maxX + padding * 2,
      height: maxY + padding * 2,
    });
  }, [stopPositions]);

  return {
    ports,
    stops,
    viewMode,
    setViewMode,
    selectedStop,
    isStopModalOpen,
    setIsStopModalOpen,
    editingStop,
    setEditingStop,
    isAddStopModalOpen,
    setIsAddStopModalOpen,
    addStopPosition,
    draggedIndex,
    dragOverItem,
    dynamicRiverPath,
    stopPositions,
    zoomLevel,
    setZoomLevel,
    viewBox,
    isPanning,
    panOffset,
    mapContainerRef,
    getRiverPosition,
    isStopFixed,
    handleMouseDown,
    handleMouseMove,
    handleMouseUp,
    handleMouseLeave,
    handleTouchStart,
    handleTouchMove,
    handleTouchEnd,
    handleDragStart,
    handleDragOver,
    handleDrop,
    moveStopUp,
    moveStopDown,
    handleStopClick,
    openAddStopModal,
    handleAddStop,
    removeStop,
    updateStop,
    startEditing,
    saveEdit,
    handleSubmit,
    parseDurationForUI,
    resetView,
    isSaving: updateRouteStops.isPending,
  };
}

// src/features/fluvial/hooks/useScheduledTemplates.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from '@/utils/sileo-toast';
import {
  scheduledTemplatesService,
  CreateScheduledTemplateData,
  UpdateScheduledTemplateData
} from '../../../services/scheduled-templates.service';
import { ScheduledRouteTemplate } from '../../../types';
import { getErrorMessage } from '../../../utils/errorHandler';

export const useScheduledTemplates = (companyId?: number) => {
  const queryClient = useQueryClient();
  const queryKey = ['scheduled-templates', companyId];

  const {
    data: templates = [],
    isLoading,
    error,
    refetch
  } = useQuery<ScheduledRouteTemplate[]>({
    queryKey,
    queryFn: () => scheduledTemplatesService.getByCompany(companyId!),
    enabled: !!companyId && companyId > 0,
  });

  // Mutation para crear plantilla
  const createMutation = useMutation({
    mutationFn: (data: CreateScheduledTemplateData) =>
      scheduledTemplatesService.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success('Plantilla creada exitosamente');
    },
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al crear la plantilla');
      toast.error(message);
    }
  });

  // Mutation para actualizar plantilla
  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: number; data: UpdateScheduledTemplateData }) =>
      scheduledTemplatesService.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success('Plantilla actualizada exitosamente');
    },
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al actualizar la plantilla');
      toast.error(message);
    }
  });

  // Mutation para desactivar plantilla
  const deactivateMutation = useMutation({
    mutationFn: (id: number) => scheduledTemplatesService.deactivate(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success('Plantilla desactivada exitosamente');
    },
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al desactivar la plantilla');
      toast.error(message);
    }
  });

  return {
    templates,
    isLoading,
    error,
    refetch,
    createTemplate: createMutation.mutate,
    updateTemplate: updateMutation.mutate,
    deactivateTemplate: deactivateMutation.mutate,
    isCreating: createMutation.isPending,
    isUpdating: updateMutation.isPending,
    isDeactivating: deactivateMutation.isPending
  };
};

// src/features/fluvial/hooks/useSeatAssignments.ts
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from '@/utils/sileo-toast';
import { assignmentsService, SeatAssignmentCreateData } from '../../../services/assignments.service';

/**
 * Hook (mutación) para crear una nueva asignación de asiento.
 * Se debe llamar después de que la factura y su item hayan sido creados.
 */
export const useCreateSeatAssignment = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: SeatAssignmentCreateData) => assignmentsService.create(data),
    onSuccess: (newAssignment) => {
      // Opcional: notificar éxito de la asignación (puede ser redundante si ya hay un toast de venta exitosa)
      // toast.success(`Asiento ${newAssignment.seat_number} asignado correctamente.`);

      // Invalidamos el mapa de asientos para que se actualice y muestre el asiento como 'CONFIRMED'
      queryClient.invalidateQueries({ queryKey: ['seatMap', newAssignment.trip_id] });
    },
    onError: (error: any) => {
      // Este error es crítico, porque la factura ya se creó.
      // Se debe notificar al usuario para que contacte a soporte.
      console.error("Error crítico: La factura se creó pero la asignación del asiento falló.", error);
      toast.error(
        '¡Atención! La factura se generó pero hubo un error al asignar el asiento. Por favor, contacte a soporte.'
      );
    },
  });
};

// src/features/fluvial/hooks/useSeatMapRealtime.ts
import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { SeatMapItem, SeatOccupantInfo } from '../../../types';
import { useSeatMap } from './useSeatMap';
import { useWebSocketConnection } from './useWebSocketConnection';
import { useSeatSelections } from './useSeatSelections';
import { usePurchaseTimer } from './usePurchaseTimer';
import { WebSocketMessageHandler } from '../services/websocketMessageHandler';
import { SeatOperations } from '../services/seatOperations';
import { SeatMapRealtimeOptions, SeatSelection, SeatUpdateMessage } from '../types/websocket.types';

/**
 * Hook principal para gestión en tiempo real del mapa de asientos
 * Versión refactorizada y optimizada - reemplaza el hook monolítico original
 */
export const useSeatMapRealtime = (options: SeatMapRealtimeOptions) => {
  const {
    tripId,
    userId,
    userName,
    enabled = true,
    maxReconnectAttempts = 3,
    seatSelectionTimeout = 30000,
    cleanupInterval = 5000,
    enableDebugLogs = false,
    purchaseTimeout = 300000,
    onPurchaseTimeoutExpired,
    companyName,
    isCompanyMode = false
  } = options;

  // Hook para datos iniciales del mapa de asientos
  const { data: initialSeatMap = [], isLoading, refetch } = useSeatMap(tripId);

  // Estado del mapa de asientos
  const [seatMap, setSeatMap] = useState<SeatMapItem[]>([]);
  const [pendingWebSocketSelections, setPendingWebSocketSelections] = useState<SeatSelection[] | null>(null);

  // Configuración WebSocket - Memoizada para evitar recreaciones innecesarias
  const webSocketConfig = useMemo(() => ({
    tripId,
    userId,
    userName,
    enabled,
    maxReconnectAttempts,
    companyName,
    isCompanyMode
  }), [tripId, userId, userName, enabled, maxReconnectAttempts, companyName, isCompanyMode]);

  // Hooks especializados - Separación de responsabilidades (antes del messageHandler)
  const {
    activeSeatSelections,
    myReservedSeats,
    myActiveSelections, //  NUEVO: Mis selecciones activas
    myReservedSeatsRef, // Nueva referencia para evitar recreaciones
    addSelection,
    removeSelection,
    addMySelection, //  NUEVO: Agregar mi propia selección
    addReservation,
    removeReservation,
    clearAllReservations
  } = useSeatSelections({
    userId,
    seatSelectionTimeout,
    cleanupInterval
  });

  // Debouncing para actualizaciones del mapa de asientos
  const seatUpdateTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const pendingSeatUpdatesRef = useRef<Map<number, { status: string; occupant?: SeatOccupantInfo }>>(new Map());

  const debouncedSeatMapUpdate = useCallback((seatId: number, status: string, occupant?: SeatOccupantInfo) => {
    // Acumular actualizaciones pendientes (incluyendo occupant si viene del WS)
    pendingSeatUpdatesRef.current.set(seatId, { status, occupant });

    // Limpiar timeout anterior
    if (seatUpdateTimeoutRef.current) {
      clearTimeout(seatUpdateTimeoutRef.current);
    }

    // Aplicar actualizaciones después de 100ms de inactividad
    seatUpdateTimeoutRef.current = setTimeout(() => {
      const updates = new Map(pendingSeatUpdatesRef.current);
      pendingSeatUpdatesRef.current.clear();

      setSeatMap(prevMap => {
        let hasChanges = false;
        const newMap = prevMap.map(seat => {
          const update = updates.get(seat.id);
          if (update) {
            hasChanges = true;
            return { ...seat, status: update.status as any, occupant: update.occupant ?? seat.occupant };
          }
          return seat;
        });
        return hasChanges ? newMap : prevMap;
      });
    }, 100);
  }, []);

  // Refs para callbacks estables - Evitar recreaciones del messageHandler
  const addSelectionRef = useRef(addSelection);
  const removeSelectionRef = useRef(removeSelection);
  const debouncedSeatMapUpdateRef = useRef(debouncedSeatMapUpdate);

  // Actualizar refs en cada render para mantener referencias actualizadas
  useEffect(() => {
    addSelectionRef.current = addSelection;
    removeSelectionRef.current = removeSelection;
    debouncedSeatMapUpdateRef.current = debouncedSeatMapUpdate;
  }, [addSelection, removeSelection, debouncedSeatMapUpdate]);

  // Handler de mensajes WebSocket - Memoizado para evitar recreaciones
  const messageHandler = useMemo(() => {
    return new WebSocketMessageHandler(userId, {
      onSeatMapUpdate: (seatId: number, status: string, occupant?: SeatOccupantInfo) => {
        debouncedSeatMapUpdateRef.current(seatId, status, occupant);
      },
      onSelectionUpdate: (selection: SeatSelection) => {
        addSelectionRef.current(selection);
      },
      onSelectionRemove: (seatId: number, sourceUserId?: string) => {
        removeSelectionRef.current(seatId, sourceUserId);
      },
      onInitialState: (selections: SeatSelection[]) => {
        // Usar una callback function para acceder al estado actual sin dependencias
        setSeatMap(currentSeatMap => {
          if (currentSeatMap.length > 0) {
            selections.forEach(selection => addSelectionRef.current(selection));
          } else {
            setPendingWebSocketSelections(selections);
          }
          return currentSeatMap; // No modificar el estado aquí
        });
      }
    });
  }, [userId]); // Solo depende de userId

  const handleWebSocketMessage = useCallback((message: SeatUpdateMessage) => {
    messageHandler.handleMessage(message);
  }, [messageHandler]);

  const {
    connectionStatus,
    isWebSocketAvailable,
    sendMessage,
    forceReconnect,
    pingConnection,
    testConnection
  } = useWebSocketConnection(webSocketConfig, handleWebSocketMessage);

  const {
    purchaseTimeRemaining,
    isPurchaseTimerActive,
    startPurchaseTimer,
    stopPurchaseTimer,
    extendPurchaseTime
  } = usePurchaseTimer({
    purchaseTimeout,
    onPurchaseTimeoutExpired
  });

  // Servicio de operaciones de asientos - Encapsula la lógica de envío de mensajes
  const seatOperations = new SeatOperations(sendMessage, userId, userName, tripId, companyName);

  // Sincronizar datos iniciales con selecciones pendientes del WebSocket
  useEffect(() => {
    if (initialSeatMap && initialSeatMap.length > 0) {
      if (pendingWebSocketSelections) {
        pendingWebSocketSelections.forEach(selection => {
          if (selection.userId !== userId) {
            addSelection(selection);
          }
        });
        setPendingWebSocketSelections(null);
      }

      // CORRECCIÓN: Preservar actualizaciones de estado que vienen del WebSocket
      // No sobrescribir el seatMap si ya tiene datos actualizados
      setSeatMap(currentSeatMap => {
        if (currentSeatMap.length === 0) {
          // Primera carga: usar datos iniciales
          return initialSeatMap;
        } else {
          // Ya hay datos: preservar estados actualizados por WebSocket
          // Solo actualizar asientos que no han sido modificados por WebSocket
          return currentSeatMap.map(currentSeat => {
            const initialSeat = initialSeatMap.find(s => s.id === currentSeat.id);
            if (initialSeat) {
              // Preservar el estado actual si es diferente al inicial (fue actualizado por WebSocket)
              return currentSeat.status !== initialSeat.status ? currentSeat : initialSeat;
            }
            return currentSeat;
          });
        }
      });
    }
  }, [initialSeatMap, pendingWebSocketSelections, userId, addSelection]);

  // CORRECCIÓN: Solo reconectar cuando cambien valores críticos de conexión DESPUÉS del montaje inicial
  const previousConfigRef = useRef<{
    tripId?: number, 
    userId?: string, 
    userName?: string, 
    enabled?: boolean,
    companyName?: string,
    isCompanyMode?: boolean
  }>({});
  const isInitialMountRef = useRef(true);

  useEffect(() => {
    if (enabled && tripId && userId && userName) {
      const currentConfig = { tripId, userId, userName, enabled, companyName, isCompanyMode };
      const prevConfig = previousConfigRef.current;

      // En el montaje inicial, iniciar la conexión directamente
      if (isInitialMountRef.current) {
        const timer = setTimeout(() => {
          forceReconnect();
        }, 50); // Delay mínimo para asegurar que el componente esté montado

        isInitialMountRef.current = false;
        previousConfigRef.current = currentConfig;
        return () => clearTimeout(timer);
      }

      // Solo reconectar si realmente cambió algo crítico DESPUÉS del montaje inicial
      const shouldReconnect = (
        prevConfig.tripId !== tripId ||
        prevConfig.userId !== userId ||
        prevConfig.userName !== userName ||
        prevConfig.enabled !== enabled ||
        prevConfig.companyName !== companyName ||
        prevConfig.isCompanyMode !== isCompanyMode
      );

      if (shouldReconnect) {
        // Pequeño delay para asegurar que el componente esté completamente montado
        const timer = setTimeout(() => {
          forceReconnect();
        }, 100);

        previousConfigRef.current = currentConfig;
        return () => clearTimeout(timer);
      }

      previousConfigRef.current = currentConfig;
    }
  }, [tripId, userId, userName, enabled, companyName, isCompanyMode, forceReconnect]); // Dependencias críticas para reconexión

  // === API PÚBLICA DEL HOOK ===

  // Operaciones básicas de asientos
  const selectSeat = useCallback((seatId: number, selectionType: 'temporary' | 'reserved' = 'temporary') => {
    // 🔧 CORRECCIÓN: NO liberar selecciones automáticamente en modo empresa
    // En modo empresa (RUC con representantes), necesitamos mantener múltiples asientos
    if (selectionType === 'temporary' && !isCompanyMode) {
      // Solo en modo individual: Liberar la selección actual antes de hacer una nueva
      myActiveSelections.forEach((selectedSeatId) => {
        if (selectedSeatId !== seatId) {
          seatOperations.releaseSeat(selectedSeatId);
          removeSelection(selectedSeatId);
        }
      });
    }

    //  SOLUCIÓN: Verificar que el asiento no esté siendo usado por otro vendedor
    const existingSelection = activeSeatSelections.get(seatId);
    if (existingSelection && existingSelection.userId !== userId) {
      // El asiento está siendo usado por otro vendedor, no permitir la selección
      return false;
    }

    const success = seatOperations.selectSeat(seatId, selectionType);
    if (success) {
      // Agregar mi propia selección al tracking
      addMySelection(seatId);

      if (selectionType === 'reserved') {
        addReservation(seatId);
      }
    }
    return success;
  }, [seatOperations, addReservation, addMySelection, myActiveSelections, isCompanyMode, removeSelection, activeSeatSelections, userId]);

  const releaseSeat = useCallback((seatId: number, force: boolean = false) => {
    // Usar referencia para evitar dependencia en myReservedSeats que cambia constantemente
    if (myReservedSeatsRef.current?.has(seatId) && !force) {
      return false;
    }
    const success = seatOperations.releaseSeat(seatId);
    if (success) {
      removeReservation(seatId);
      //  SOLUCIÓN: Remover de mis selecciones activas
      removeSelection(seatId);
    }
    return success;
  }, [seatOperations, removeReservation, removeSelection, myReservedSeatsRef]); // Usando referencia estable

  // Operaciones para representantes (modo empresa)
  const selectSeatForRepresentative = useCallback((
    seatId: number, 
    representativeIndex: number, 
    representativeName: string
  ) => {
    return seatOperations.selectSeatForRepresentative(seatId, representativeIndex, representativeName);
  }, [seatOperations]);

  const releaseSeatForRepresentative = useCallback((seatId: number, representativeIndex?: number) => {
    return seatOperations.releaseSeatForRepresentative(seatId, representativeIndex);
  }, [seatOperations]);

  // Operaciones de compra
  const reserveSeatForPurchase = useCallback((seatId: number) => {
    const success = selectSeat(seatId, 'reserved');
    if (success) {
      addReservation(seatId);
    }
    return success;
  }, [selectSeat, addReservation]);

  const releaseReservedSeat = useCallback((seatId: number) => {
    return releaseSeat(seatId, true);
  }, [releaseSeat]);

  const confirmPurchase = useCallback((seatIds?: number[]) => {
    // Usar referencia para obtener el valor actual sin dependencia de estado
    const seatsToConfirm = seatIds || Array.from(myReservedSeatsRef.current || new Set());
    const success = seatOperations.confirmPurchase(seatsToConfirm);
    if (success) {
      clearAllReservations();
      stopPurchaseTimer();
    }
    return success;
  }, [seatOperations, clearAllReservations, stopPurchaseTimer, myReservedSeatsRef]); // Usando referencia estable

  const cancelAllReservations = useCallback(() => {
    // Usar referencia para obtener el valor actual sin dependencia de estado
    const seatsToRelease = Array.from(myReservedSeatsRef.current || new Set());

    // Usar directamente seatOperations en lugar de releaseReservedSeat para evitar loops
    seatsToRelease.forEach(seatId => {
      seatOperations.releaseSeat(seatId);
      removeReservation(seatId);
    });

    clearAllReservations();
    stopPurchaseTimer();
  }, [seatOperations, removeReservation, clearAllReservations, stopPurchaseTimer, myReservedSeatsRef]); // Evitando releaseReservedSeat

  // Función de debug mejorada (condicional)
  const debugActiveSelectionsEnhanced = useCallback(() => {
    if (enableDebugLogs) {
      // Llamar directamente sin dependencia problemática
      console.log('Active seat selections:', {
        totalSelections: activeSeatSelections.size,
        selections: Array.from(activeSeatSelections.entries()).map(([seatId, selection]) => ({
          seatId,
          userName: selection.userName,
          userId: selection.userId,
          timestamp: selection.timestamp
        }))
      });

      console.log('Enhanced Debug Info:', {
        seatMapLength: seatMap.length, // Capturar valor actual
        initialSeatMapLength: initialSeatMap?.length || 0, // Capturar valor actual
        connectionStatus,
        isWebSocketAvailable,
        myReservedSeatsCount: myReservedSeatsRef.current?.size || 0, // Usar referencia
        purchaseTimeRemaining,
        isPurchaseTimerActive,
        companyName: companyName || 'N/A',
        isCompanyMode
      });
    }
  }, [
    enableDebugLogs, activeSeatSelections,
    connectionStatus, isWebSocketAvailable, myReservedSeatsRef, // Usar referencia
    purchaseTimeRemaining, isPurchaseTimerActive, companyName, isCompanyMode
  ]); // Removido seatMap.length e initialSeatMap?.length que cambian constantemente

  // Cleanup del debouncing al desmontar
  useEffect(() => {
    return () => {
      if (seatUpdateTimeoutRef.current) {
        clearTimeout(seatUpdateTimeoutRef.current);
      }
    };
  }, []);

  // Funciones auxiliares (mantener compatibilidad con la API original)
  const setSeatTimeout = useCallback((_timeoutMs: number) => {
    // Función placeholder para cambiar timeout dinámicamente
    // Puede implementarse en el futuro si es necesario
  }, []);

  const refreshSeatMap = useCallback(() => {
    refetch();
  }, [refetch]);

  // === INTERFAZ PÚBLICA (COMPATIBLE CON VERSIÓN ORIGINAL) ===
  return {
    // Estados principales
    seatMap,
    activeSeatSelections,
    myReservedSeats,
    connectionStatus,
    isLoading,

    // Operaciones básicas
    selectSeat,
    releaseSeat,
    refreshSeatMap,

    // Operaciones para representantes
    selectSeatForRepresentative,
    releaseSeatForRepresentative,

    // Operaciones de compra
    reserveSeatForPurchase,
    releaseReservedSeat,
    confirmPurchase,
    cancelAllReservations,

    // Temporizador de compra
    startPurchaseTimer,
    stopPurchaseTimer,
    extendPurchaseTime,
    purchaseTimeRemaining,
    isPurchaseTimerActive,

    // Funciones de debugging y conexión
    pingConnection,
    testConnection,
    forceReconnect,
    debugActiveSelections: debugActiveSelectionsEnhanced,
    setSeatTimeout,

    // Estados de conexión
    isConnected: connectionStatus === 'connected',
    isWebSocketAvailable,
    canUseRealtime: connectionStatus === 'connected' && isWebSocketAvailable,

    // Debug info (solo si está habilitado)
    _debug: enableDebugLogs ? {
      seatMapLength: seatMap.length,
      initialSeatMapLength: initialSeatMap?.length || 0,
      connectionStatus,
      isWebSocketAvailable,
      hasPendingWsSelections: !!pendingWebSocketSelections,
      pendingWsSelectionsLength: pendingWebSocketSelections?.length || 0,
      activeSelectionsCount: activeSeatSelections.size,
      myReservedSeatsCount: myReservedSeatsRef.current?.size || 0, // Usar referencia
      currentTimeout: seatSelectionTimeout,
      cleanupInterval: cleanupInterval,
      purchaseTimeRemaining,
      isPurchaseTimerActive,
      companyName: companyName || 'N/A',
      isCompanyMode
    } : undefined
  };
};

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useSeatReservations } from './useSeatReservations';

const mockToastError = vi.fn();
const mockToastInfo = vi.fn();

vi.mock('@/utils/sileo-toast', () => ({
  toast: {
    error: (...args: any[]) => mockToastError(...args),
    info: (...args: any[]) => mockToastInfo(...args),
    success: vi.fn(),
    warning: vi.fn(),
  },
}));

describe('useSeatReservations', () => {
  const tripId = 42;

  beforeEach(() => {
    mockToastError.mockClear();
    mockToastInfo.mockClear();
  });

  it('starts with empty state', () => {
    const { result } = renderHook(() => useSeatReservations(tripId));
    expect(result.current.reservedSeats).toEqual([]);
    expect(result.current.isReserving).toBe(false);
    expect(result.current.sessionId).toContain('session_');
  });

  it('reserveSeat adds a new reservation', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      const ok = await result.current.reserveSeat('A1', 0, 101);
      expect(ok).toBe(true);
    });

    expect(result.current.reservedSeats).toHaveLength(1);
    expect(result.current.reservedSeats[0]).toMatchObject({
      seatNumber: 'A1',
      seatId: 101,
      representativeIndex: 0,
    });
  });

  it('reserveSeat replaces previous reservation for same representative index', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 101);
    });

    await act(async () => {
      await result.current.reserveSeat('B2', 0, 202);
    });

    expect(result.current.reservedSeats).toHaveLength(1);
    expect(result.current.reservedSeats[0].seatNumber).toBe('B2');
    expect(result.current.reservedSeats[0].seatId).toBe(202);
  });

  it('reserveSeat allows different representatives', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 101);
      await result.current.reserveSeat('B2', 1, 202);
    });

    expect(result.current.reservedSeats).toHaveLength(2);
  });

  it('updateReservationSeatId updates seatId for a representative', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 0);
    });

    act(() => {
      result.current.updateReservationSeatId(0, 999);
    });

    expect(result.current.reservedSeats[0].seatId).toBe(999);
  });

  it('releaseSeat removes reservation and calls WebSocket function', async () => {
    const releaseFn = vi.fn(() => true);
    const { result } = renderHook(() => useSeatReservations(tripId));

    act(() => {
      result.current.setWebSocketFunctions({
        releaseSeatForRepresentative: releaseFn,
      });
    });

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 101);
    });

    await act(async () => {
      await result.current.releaseSeat(0);
    });

    expect(releaseFn).toHaveBeenCalledWith(101, 0);
    expect(result.current.reservedSeats).toHaveLength(0);
  });

  it('releaseSeat does nothing if no reservation exists', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      await result.current.releaseSeat(99);
    });

    expect(result.current.reservedSeats).toHaveLength(0);
  });

  it('releaseAllReservations releases all seats via WebSocket', async () => {
    const releaseFn = vi.fn(() => true);
    const { result } = renderHook(() => useSeatReservations(tripId));

    act(() => {
      result.current.setWebSocketFunctions({
        releaseSeatForRepresentative: releaseFn,
      });
    });

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 101);
      await result.current.reserveSeat('B2', 1, 202);
    });

    await act(async () => {
      await result.current.releaseAllReservations();
    });

    // Verify both seats were released (may be called extra times due to Strict Mode)
    expect(releaseFn).toHaveBeenCalledWith(101, 0);
    expect(releaseFn).toHaveBeenCalledWith(202, 1);
    expect(result.current.reservedSeats).toHaveLength(0);
  });

  it('confirmAllReservations clears local state', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 101);
    });

    await act(async () => {
      const ok = await result.current.confirmAllReservations();
      expect(ok).toBe(true);
    });

    expect(result.current.reservedSeats).toHaveLength(0);
  });

  it('extendReservations shows info toast', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      await result.current.extendReservations(10);
    });

    expect(mockToastInfo).toHaveBeenCalledWith(
      'Las reservas se mantienen activas mientras la sesión esté abierta'
    );
  });

  it('getReservedSeatNumbers returns seat numbers', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 101);
      await result.current.reserveSeat('B2', 1, 202);
    });

    expect(result.current.getReservedSeatNumbers()).toEqual(['A1', 'B2']);
  });

  it('isSeatReservedByUser checks by seat number', async () => {
    const { result } = renderHook(() => useSeatReservations(tripId));

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 101);
    });

    expect(result.current.isSeatReservedByUser('A1')).toBe(true);
    expect(result.current.isSeatReservedByUser('Z99')).toBe(false);
  });

  it('cleans up reservations on unmount', async () => {
    const releaseFn = vi.fn(() => true);
    const { result, unmount } = renderHook(() => useSeatReservations(tripId));

    act(() => {
      result.current.setWebSocketFunctions({
        releaseSeatForRepresentative: releaseFn,
      });
    });

    await act(async () => {
      await result.current.reserveSeat('A1', 0, 101);
    });

    unmount();

    expect(releaseFn).toHaveBeenCalledWith(101, 0);
  });
});

// src/features/fluvial/hooks/useSeatReservations.ts
// MODIFICADO: Este hook ahora usa SOLO WebSocket para reservas temporales
// ya que el endpoint de API REST no existe en el backend

import { useState, useCallback, useRef, useEffect } from 'react';
import { toast } from '@/utils/sileo-toast';

interface SeatReservation {
  seatNumber: string;
  seatId: number; // ID del asiento para WebSocket
  reservationId?: string;
  expiresAt?: string;
  representativeIndex: number;
}

export const useSeatReservations = (tripId: number) => {
  const [reservedSeats, setReservedSeats] = useState<SeatReservation[]>([]);
  const [isReserving, setIsReserving] = useState(false);
  const sessionId = useRef(`session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`);

  // Referencia para las funciones de WebSocket (se inyectan desde el componente padre)
  const webSocketFunctionsRef = useRef<{
    selectSeatForRepresentative?: (seatId: number, representativeIndex: number, representativeName: string) => boolean;
    releaseSeatForRepresentative?: (seatId: number, representativeIndex?: number) => boolean;
  }>({});

  // Función para inyectar las funciones de WebSocket
  const setWebSocketFunctions = useCallback((functions: {
    selectSeatForRepresentative?: (seatId: number, representativeIndex: number, representativeName: string) => boolean;
    releaseSeatForRepresentative?: (seatId: number, representativeIndex?: number) => boolean;
  }) => {
    webSocketFunctionsRef.current = functions;
  }, []);

  // Reservar asiento temporalmente vía WebSocket
  const reserveSeat = useCallback(async (seatNumber: string, representativeIndex: number, seatId?: number): Promise<boolean> => {
    setIsReserving(true);
    try {
      // Registrar localmente con el seatId si se proporciona
      setReservedSeats(prev => [
        ...prev.filter(r => r.representativeIndex !== representativeIndex), // Remover reserva anterior del mismo representante
        {
          seatNumber,
          seatId: seatId || 0, // Usar el seatId proporcionado o 0 como fallback
          representativeIndex
        }
      ]);

      return true;
    } catch (error: any) {
      toast.error(error.message || 'Error al reservar asiento');
      return false;
    } finally {
      setIsReserving(false);
    }
  }, []);

  // Liberar asiento específico
  const releaseSeat = useCallback(async (representativeIndex: number) => {
    const reservation = reservedSeats.find(r => r.representativeIndex === representativeIndex);
    if (!reservation) return;

    // Si tenemos funciones de WebSocket, liberar vía WebSocket
    if (reservation.seatId && webSocketFunctionsRef.current.releaseSeatForRepresentative) {
      webSocketFunctionsRef.current.releaseSeatForRepresentative(reservation.seatId, representativeIndex);
    }

    setReservedSeats(prev => prev.filter(r => r.representativeIndex !== representativeIndex));
  }, [tripId, reservedSeats]);

  // Actualizar seatId de una reserva (se llama desde el padre cuando se conoce el seatId)
  const updateReservationSeatId = useCallback((representativeIndex: number, seatId: number) => {
    setReservedSeats(prev => 
      prev.map(r => 
        r.representativeIndex === representativeIndex 
          ? { ...r, seatId }
          : r
      )
    );
  }, []);

  // Confirmar todas las reservas (al completar venta exitosamente)
  const confirmAllReservations = useCallback(async (): Promise<boolean> => {
    // Ya no es necesario confirmar vía API REST
    // La confirmación se hace vía confirmPurchase en el hook useSeatMapRealtime
    setReservedSeats([]); // Limpiar reservas locales
    return true;
  }, [tripId, reservedSeats]);

  // Liberar todas las reservas (al cancelar o error)
  const releaseAllReservations = useCallback(async () => {
    if (reservedSeats.length === 0) return;

    // Liberar todas las reservas vía WebSocket
    reservedSeats.forEach(reservation => {
      if (reservation.seatId && webSocketFunctionsRef.current.releaseSeatForRepresentative) {
        webSocketFunctionsRef.current.releaseSeatForRepresentative(reservation.seatId, reservation.representativeIndex);
      }
    });

    setReservedSeats([]);
  }, [tripId, reservedSeats]);

  // Extender tiempo de reservas - Ya no es necesario sin API REST
  const extendReservations = useCallback(async (_additionalMinutes: number = 5) => {
    // No hay nada que extender sin API REST
    // Las reservas vía WebSocket tienen TTL automático en el backend
    toast.info('Las reservas se mantienen activas mientras la sesión esté abierta');
  }, [tripId, reservedSeats]);

  // Cleanup al desmontar componente
  useEffect(() => {
    return () => {
      // Liberar reservas al salir del componente
      if (reservedSeats.length > 0) {
        reservedSeats.forEach(reservation => {
          if (reservation.seatId && webSocketFunctionsRef.current.releaseSeatForRepresentative) {
            webSocketFunctionsRef.current.releaseSeatForRepresentative(reservation.seatId, reservation.representativeIndex);
          }
        });
      }
    };
  }, [tripId, reservedSeats]);

  // Obtener asientos ocupados por este usuario
  const getReservedSeatNumbers = useCallback(() => {
    return reservedSeats.map(r => r.seatNumber);
  }, [reservedSeats]);

  // Verificar si un asiento está reservado por este usuario
  const isSeatReservedByUser = useCallback((seatNumber: string) => {
    return reservedSeats.some(r => r.seatNumber === seatNumber);
  }, [reservedSeats]);

  return {
    reservedSeats,
    isReserving,
    reserveSeat,
    releaseSeat,
    confirmAllReservations,
    releaseAllReservations,
    extendReservations,
    getReservedSeatNumbers,
    isSeatReservedByUser,
    sessionId: sessionId.current,
    setWebSocketFunctions, // Nueva función para inyectar funciones de WebSocket
    updateReservationSeatId, // Nueva función para actualizar seatId
  };
};

