export const useRoutesByPort = (portId: number | null) => {
  const { data: allRoutes = [], isLoading } = useRoutes();
  const routes = portId
    ? allRoutes.filter(route =>
        route.origin_port_id === portId ||
        route.destination_port_id === portId
      )
    : [];
  return { routes, isLoading };
};

