  const [showFilters, setShowFilters] = useState(false);
  const [selectedItem, setSelectedItem] = useState<ProductService | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);

  const queryFilters = useMemo(() => ({
    name: debouncedSearch || undefined,
    item_type: filters.item_type || undefined,
    is_active: filters.is_active,
    service_category: filters.service_category || undefined,
  }), [debouncedSearch, filters]);

  const { data: productsServices, isLoading, error, refetch } = useProductsServicesData(queryFilters);
  const createMutation = useCreateProductService();
  const updateMutation = useUpdateProductService();
  // deleteMutation removed: deletion disabled from UI

  const handleFormSubmit = (data: ProductServiceFormData) => {
    if (selectedItem) {
      updateMutation.mutate({ id: selectedItem.id, data }, {
        onSuccess: () => {
          setIsModalOpen(false);
          setSelectedItem(null);
          refetch();
        }
      });
    } else {
      createMutation.mutate(data, {
        onSuccess: () => {
          setIsModalOpen(false);
          refetch();
        }
      });
    }
  };

  const openCreateModal = () => {
    setSelectedItem(null);
    setIsModalOpen(true);
  };

  const openEditModal = (item: ProductService) => {
    setSelectedItem(item);
    setIsModalOpen(true);
  };

  // handleDelete removed: deletion disabled from UI

  const handleSearch = (value: string) => {
    setSearchQuery(value);
  };

  const handleFilterChange = (key: keyof ProductServiceFilters, value: any) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const columns: Column<ProductService>[] = useMemo(() => [
    {
      key: 'internal_code',
      header: 'Código',
      accessor: (item) => item.internal_code || '',
      className: 'text-left'
    },
    {
      key: 'name',
      header: 'Nombre',
      accessor: (item) => item.name,
      className: 'text-left'
    },
    {
      key: 'item_type',
      header: 'Tipo',
      accessor: (item) => (
        <span className={`px-2 py-1 text-xs rounded-full ${
          item.item_type === 'SERVICE'
            ? 'bg-blue-100 dark:bg-blue-900/40 text-blue-800 dark:text-blue-300'
            : 'bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-300'
        }`}>
          {item.item_type === 'SERVICE' ? 'Servicio' : 'Producto'}
        </span>
      ),
      className: 'text-left'
    },
    {
      key: 'sale_price',
      header: 'Precio Venta',
      accessor: (item) =>
        `${item.currency_code} ${Number(item.sale_price).toFixed(2)}`,
      className: 'text-right'
    },
    {
      key: 'tax_category_code',
      header: 'Afectación IGV',
      accessor: (item) => getTaxCategoryLabel(item.tax_category_code),
      className: 'text-left'
    },
    {
      key: 'is_active',
      header: 'Estado',
      accessor: (item) => (
        <span className={`px-2 py-1 text-xs rounded-full ${
          item.is_active
            ? 'bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-300'
            : 'bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-300'
        }`}>
          {item.is_active ? 'Activo' : 'Inactivo'}
        </span>
      ),
      className: 'text-left'
    },
    {
      key: 'actions',
      header: 'Acciones',
      accessor: (item) => (
        <div className="flex space-x-2">
          <button
            onClick={() => { setSelectedItem(item); setShowViewModal(true); }}
            className="text-dm-text-muted hover:text-blue-700 dark:text-blue-300"
            title="Ver"
          >
            <EyeIcon className="w-5 h-5" />
          </button>
          <button
            onClick={() => openEditModal(item)}
            className="text-dm-text-muted hover:text-yellow-700 dark:text-yellow-300"
            title="Editar"
          >
            <PencilIcon className="w-5 h-5" />
          </button>
          {/* Delete action removed - deletion disabled in UI */}
        </div>
      ),
      className: 'text-left'
    },
  ], []);

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <Spinner size="lg" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800/50 rounded-md p-4">
        <p className="text-red-600 dark:text-red-400">Error al cargar productos y servicios</p>
        <Button
          onClick={() => refetch()}
          variant="outline"
          size="sm"
          className="mt-2"
        >
          Reintentar
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header - Responsive */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 sm:gap-0">
        <div>
          <h1 className="text-2xl font-bold text-dm-text-primary">Productos y Servicios</h1>
          <p className="text-dm-text-secondary">Gestiona los productos y servicios disponibles</p>
        </div>
        <Button onClick={openCreateModal} className="flex items-center gap-2 w-full sm:w-auto justify-center">
          <PlusIcon className="w-4 h-4" />
          Nuevo
        </Button>
      </div>

      {/* Search and Filters - Responsive */}
      <div className="bg-dm-bg-primary p-4 rounded-lg shadow space-y-4">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 sm:justify-between">
          <div className="flex-1 w-full sm:max-w-md">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MagnifyingGlassIcon className="h-4 w-4 text-dm-text-muted" />
              </div>
              <Input
                placeholder="Buscar productos/servicios..."
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                className="pl-10 w-full"
              />
            </div>
          </div>
          <Button
            variant="outline"
            onClick={() => setShowFilters(!showFilters)}
            className="flex items-center gap-2 justify-center w-full sm:w-auto"
          >
            <FunnelIcon className="w-4 h-4" />
            Filtros
          </Button>
        </div>

        {showFilters && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-4 border-t border-dm-border-primary">
            <div>
              <label className="block text-sm font-medium text-dm-text-secondary mb-1">
                Tipo
              </label>
              <select
                value={filters.item_type}
                onChange={(e) => handleFilterChange('item_type', e.target.value)}
                className="w-full border border-dm-border-primary rounded-md px-3 py-2 text-sm"
              >
                <option value="">Todos</option>
                {ITEM_TYPE_OPTIONS.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-dm-text-secondary mb-1">
                Categoría
              </label>
              <select
                value={filters.service_category}
                onChange={(e) => handleFilterChange('service_category', e.target.value)}
                className="w-full border border-dm-border-primary rounded-md px-3 py-2 text-sm"
              >
                <option value="">Todas</option>
                {SERVICE_CATEGORY_OPTIONS.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-dm-text-secondary mb-1">
                Estado
              </label>
              <select
                value={filters.is_active ? 'true' : 'false'}
                onChange={(e) => handleFilterChange('is_active', e.target.value === 'true')}
                className="w-full border border-dm-border-primary rounded-md px-3 py-2 text-sm"
              >
                <option value="true">Activos</option>
                <option value="false">Inactivos</option>
              </select>
            </div>
          </div>
        )}
      </div>

      {/* Mobile Card View */}
      <div className="block lg:hidden space-y-4">
        {(productsServices || []).map((item) => (
          <div key={item.id} className="bg-dm-bg-primary rounded-lg shadow-sm border border-dm-border-primary p-4">
            <div className="flex justify-between items-start mb-3">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <h3 className="text-base font-semibold text-dm-text-primary">{item.name}</h3>
                  <span className={`px-2 py-0.5 text-xs rounded-full ${
                    item.item_type === 'SERVICE'
                      ? 'bg-blue-100 dark:bg-blue-900/40 text-blue-800 dark:text-blue-300'
                      : 'bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-300'
                  }`}>
                    {item.item_type === 'SERVICE' ? 'Servicio' : 'Producto'}
                  </span>
                </div>
                {item.internal_code && (
                  <p className="text-sm text-dm-text-muted">Código: {item.internal_code}</p>
                )}
              </div>
              <span className={`px-2 py-0.5 text-xs rounded-full ${
                item.is_active
                  ? 'bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-300'
                  : 'bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-300'
              }`}>
                {item.is_active ? 'Activo' : 'Inactivo'}
              </span>
            </div>

            <div className="grid grid-cols-2 gap-3 text-sm mb-3">
              <div>
                <span className="block text-xs text-dm-text-muted">Precio Venta</span>
                <span className="font-medium text-dm-text-primary">
                  {item.currency_code} {Number(item.sale_price).toFixed(2)}
                </span>
              </div>
              <div>
                <span className="block text-xs text-dm-text-muted">IGV</span>
                <span className="font-medium text-dm-text-primary">
                  {getTaxCategoryLabel(item.tax_category_code)}
                </span>
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-3 border-t border-dm-border-secondary">
              <button
                onClick={() => { setSelectedItem(item); setShowViewModal(true); }}
                className="flex items-center text-dm-text-secondary hover:text-blue-800 dark:text-blue-300 text-sm font-medium"
              >
                <EyeIcon className="h-4 w-4 mr-1" /> Ver
              </button>
              <button
                onClick={() => openEditModal(item)}
                className="flex items-center text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:text-blue-300 text-sm font-medium"
              >
                <PencilIcon className="h-4 w-4 mr-1" /> Editar
              </button>
            </div>
          </div>
        ))}

        {(!productsServices || productsServices.length === 0) && (
          <div className="bg-dm-bg-primary rounded-lg shadow-sm p-6 text-center text-dm-text-muted">
            No se encontraron productos o servicios.
          </div>
        )}
      </div>

      {/* Desktop Table View */}
      <div className="hidden lg:block bg-dm-bg-primary rounded-lg shadow overflow-x-auto">
        <DataTable
          data={productsServices || []}
          columns={columns}
          isLoading={isLoading}
          keyExtractor={(item) => item.id.toString()}
        />
      </div>

      <ProductServiceFormModal
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false);
          setSelectedItem(null);
        }}
        onSubmit={handleFormSubmit}
        item={selectedItem}
        isLoading={createMutation.isPending || updateMutation.isPending}
      />

  {/* Delete confirmation modal removed - deletion disabled in UI */}

      <Modal
        isOpen={showViewModal}
        onClose={() => setShowViewModal(false)}
        title="Detalles del Producto/Servicio"
        maxWidth="lg"
      >
        {selectedItem && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-dm-text-secondary">Código Interno</label>
                <p className="text-sm text-dm-text-primary">{selectedItem.internal_code || '-'}</p>
              </div>
              <div>
                <label className="block text-sm font-medium text-dm-text-secondary">Tipo</label>
                <p className="text-sm text-dm-text-primary">
                  {selectedItem.item_type === 'SERVICE' ? 'Servicio' : 'Producto'}
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-dm-text-secondary">Nombre</label>
                <p className="text-sm text-dm-text-primary">{selectedItem.name}</p>
              </div>
              <div>
                <label className="block text-sm font-medium text-dm-text-secondary">Categoría</label>
                <p className="text-sm text-dm-text-primary">{selectedItem.service_category || '-'}</p>
              </div>
              <div>
                <label className="block text-sm font-medium text-dm-text-secondary">Precio de Compra</label>
                <p className="text-sm text-dm-text-primary">
                  {selectedItem.currency_code} {Number(selectedItem.purchase_price).toFixed(2)}
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-dm-text-secondary">Precio de Venta</label>
                <p className="text-sm text-dm-text-primary">
                  {selectedItem.currency_code} {Number(selectedItem.sale_price).toFixed(2)}
                </p>
              </div>
              <div>
                <label className="block text-sm font-medium text-dm-text-secondary">Afectación IGV</label>
                <p className="text-sm text-dm-text-primary">
                  {getTaxCategoryLabel(selectedItem.tax_category_code)}
                </p>
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-dm-text-secondary">Descripción</label>
              <p className="text-sm text-dm-text-primary">{selectedItem.description || '-'}</p>
            </div>
            <div className="flex justify-end">
              <Button variant="outline" onClick={() => setShowViewModal(false)}>
                Cerrar
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

// src/features/fluvial/pages/ReservationsPage.tsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { CalendarCheck, Check, Ban, MapPin, Clock, User, CreditCard, StickyNote, Eye } from 'lucide-react';
import { DataTable, Column } from '../../../components/common/DataTable';
import { useSearchReservations, useUpdateReservation } from '../hooks/useReservations';
import { SeatReservation, BranchOffice } from '../../../types';
import { Input } from '../../../components/common/Input';
import { useDebounce } from '../../../hooks/useDebounce';
import { BranchSelector } from '../components/sales-point/BranchSelector';
import { ReservationStatusBadge } from '../components/reservations/ReservationStatusBadge';
import { ReservationDetailModal } from '../components/reservations/ReservationDetailModal';

// ------------------------------------------------------------------
// Filtros
// ------------------------------------------------------------------
const ReservationFilters = ({
  onFilterChange,
  selectedBranch,
}: {
  onFilterChange: (filters: any) => void;
  selectedBranch: BranchOffice | null;
}) => {
  const [status, setStatus] = useState('');
  const [docNumber, setDocNumber] = useState('');
  const debouncedDocNumber = useDebounce(docNumber, 500);

  useEffect(() => {
    const cleanDocNumber = debouncedDocNumber?.trim() || '';
    onFilterChange({
      status: status ? [status] : undefined,
      customer_doc_number: cleanDocNumber.length >= 3 ? cleanDocNumber : undefined,
    });
  }, [status, debouncedDocNumber, onFilterChange]);

  return (
    <div className="rounded-xl border border-dm-border-primary/80 bg-dm-bg-primary p-4 shadow-sm">
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {/* Sucursal */}
        <div>
          <label className="mb-1.5 block text-[11px] font-medium uppercase tracking-wider text-dm-text-muted">
            Sucursal Activa
          </label>
          <div className="flex items-center gap-2 rounded-lg bg-dm-bg-secondary py-2.5 px-3.5">
            <MapPin className="h-4 w-4 text-primary shrink-0" />
            <span className="text-sm font-semibold text-dm-text-primary">
              {selectedBranch?.name || 'Ninguna'}
            </span>
          </div>
        </div>

        {/* Estado */}
        <div>
          <label className="mb-1.5 block text-[11px] font-medium uppercase tracking-wider text-dm-text-muted">
            Filtrar por Estado
          </label>
          <select
            value={status}
            onChange={(e) => setStatus(e.target.value)}
            className="w-full appearance-none rounded-lg border border-dm-border-primary bg-dm-bg-secondary py-2.5 px-3.5 text-sm text-dm-text-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
          >
            <option value="">Todos</option>
            <option value="RESERVED">Reservado</option>
            <option value="CONFIRMED">Confirmado</option>
            <option value="CANCELLED">Cancelado</option>
            <option value="EXPIRED">Expirado</option>
          </select>
        </div>

        {/* Documento */}
        <div>
          <label className="mb-1.5 block text-[11px] font-medium uppercase tracking-wider text-dm-text-muted">
            Buscar por DNI / RUC
          </label>
          <input
            type="text"
            value={docNumber}
            onChange={(e) => setDocNumber(e.target.value)}
            placeholder="Ingrese documento..."
            className="w-full rounded-lg border border-dm-border-primary bg-dm-bg-secondary py-2.5 px-3.5 text-sm text-dm-text-primary placeholder:text-dm-text-muted focus:outline-none focus:ring-2 focus:ring-primary/20"
          />
        </div>
      </div>
    </div>
  );
};

// ------------------------------------------------------------------
// Página principal
// ------------------------------------------------------------------
export const ReservationsPage: React.FC = () => {
  const [selectedBranch, setSelectedBranch] = useState<BranchOffice | null>(null);
  const [filters, setFilters] = useState({});
  const [detailReservation, setDetailReservation] = useState<SeatReservation | null>(null);
  const navigate = useNavigate();

  const handleBranchSelect = (branch: BranchOffice) => {
    setSelectedBranch(branch);
    localStorage.setItem('selectedSalesBranch', JSON.stringify(branch));
  };

  useEffect(() => {
    const savedBranchJson = localStorage.getItem('selectedSalesBranch');
    if (savedBranchJson) {
      setSelectedBranch(JSON.parse(savedBranchJson));
    }
  }, []);

  const { data: reservations = [], isLoading, error } = useSearchReservations({
    branch_office_id: selectedBranch?.id,
    ...filters,
  });

  const { mutate: updateReservation } = useUpdateReservation();

  const cancelReservation = (reservation: SeatReservation) => {
    updateReservation({
      reservationId: reservation.id,
      tripId: reservation.trip_id,
      data: { status: 'CANCELLED' },
    });
  };

  const handleCancelReservation = (reservation: SeatReservation) => {
    const notes = reservation.special_notes?.trim();
    const message = `¿Está seguro de que desea CANCELAR la reserva del asiento ${reservation.seat_number} para ${reservation.customer_name}?${
      notes ? `\n\nNota de la reserva: ${notes}` : ''
    }`;

    if (window.confirm(message)) {
      cancelReservation(reservation);
    }
  };

  const handleConfirmReservation = (reservation: SeatReservation) => {
    navigate(`/fluvial/operations/sales-point`, {
      state: {
        tripId: reservation.trip_id,
        reservationToConfirm: reservation,
      },
    });
  };

  // Desde el modal la decisión ya se tomó con todo el detalle a la vista
  const handleCancelFromDetail = (reservation: SeatReservation) => {
    setDetailReservation(null);
    cancelReservation(reservation);
  };

  const handleConfirmFromDetail = (reservation: SeatReservation) => {
    setDetailReservation(null);
    handleConfirmReservation(reservation);
  };

  const columns: Column<SeatReservation>[] = [
    {
      key: 'details',
      header: 'Viaje / Asiento',
      className: 'whitespace-normal',
      accessor: (item) => (
        <div className="max-w-[190px] space-y-0.5">
          <div className="text-sm font-bold text-primary">{item.trip_name || `Viaje #${item.trip_id}`}</div>
          <div className="text-[13px] font-medium text-dm-text-primary">
            Asiento {item.seat_number}
          </div>
          <div className="flex items-center gap-1 text-[11px] text-dm-text-muted">
            <MapPin className="h-3 w-3 shrink-0" />
            {item.boarding_stop?.port?.name || 'N/A'}
          </div>
        </div>
      ),
    },
    {
      key: 'customer',
      header: 'Cliente',
      className: 'whitespace-normal',
      accessor: (item) => (
        <div className="max-w-[190px] space-y-0.5">
          <div className="flex items-center gap-1.5 text-sm font-medium text-dm-text-primary">
            <User className="h-3.5 w-3.5 shrink-0 text-dm-text-muted" />
            {item.customer_name}
          </div>
          <div className="text-[11px] text-dm-text-muted">
            {item.customer_doc_type} {item.customer_doc_number}
          </div>
        </div>
      ),
    },
    {
      key: 'amount',
      header: 'Adelanto',
      accessor: (item) => (
        <div className="flex items-center gap-1.5 text-sm font-semibold text-dm-text-primary">
          <CreditCard className="h-3.5 w-3.5 shrink-0 text-dm-text-muted" />
          {new Intl.NumberFormat('es-PE', {
            style: 'currency',
            currency: item.currency_code,
          }).format(item.advance_amount)}
        </div>
      ),
    },
    {
      key: 'special_notes',
      header: 'Notas',
      className: 'whitespace-normal',
      accessor: (item) =>
        item.special_notes?.trim() ? (
          <button
            type="button"
            onClick={() => setDetailReservation(item)}
            title="Ver nota completa"
            className="flex max-w-[160px] items-start gap-1.5 text-left text-[13px] text-dm-text-primary hover:text-primary"
          >
            <StickyNote className="mt-0.5 h-3.5 w-3.5 shrink-0 text-amber-500" />
            <span className="line-clamp-2 break-words">{item.special_notes}</span>
          </button>
        ) : (
          <span className="text-[13px] text-dm-text-muted">—</span>
        ),
    },
    {
      key: 'status',
      header: 'Estado',
      accessor: (item) => (
        <div className="space-y-1">
          <ReservationStatusBadge status={item.status} />
          {item.expires_at && (
            <div className="flex items-center gap-1 text-[11px] text-dm-text-muted" title="Fecha de expiración">
              <Clock className="h-3 w-3 shrink-0" />
              {format(new Date(item.expires_at), 'dd/MM/yy HH:mm')}
            </div>
          )}
        </div>
      ),
    },
  ];

  if (!selectedBranch) {
    return (
      <div className="p-4 lg:p-6 max-w-7xl mx-auto">
        <div className="flex items-center gap-3 mb-6">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#dbe1ff]">
            <CalendarCheck className="h-5 w-5 text-primary" />
          </div>
          <h1 className="text-lg font-bold tracking-tight text-dm-text-primary">Gestionar Reservas</h1>
        </div>
        <div className="text-center mb-6">
          <h2 className="text-xl font-semibold text-dm-text-primary mb-2">Seleccione una sucursal</h2>
          <p className="text-dm-text-secondary">Elija la sucursal desde la cual gestionará las reservas.</p>
        </div>
        <BranchSelector onBranchSelect={handleBranchSelect} />
      </div>
    );
  }

  return (
    <div className="p-4 lg:p-6 space-y-4 lg:space-y-5">
      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#dbe1ff]">
          <CalendarCheck className="h-5 w-5 text-primary" />
        </div>
        <h1 className="text-lg font-bold tracking-tight text-dm-text-primary">Gestionar Reservas</h1>
      </div>

      <ReservationFilters onFilterChange={setFilters} selectedBranch={selectedBranch} />

      {/* Desktop Table View */}
      <div className="hidden lg:block">
        <DataTable
          columns={columns}
          data={reservations}
          isLoading={isLoading}
          error={error}
          keyExtractor={(item) => item.id}
          emptyMessage="No se encontraron reservas con los filtros actuales."
          showActions={true}
          customActions={(item) => (
            <div className="flex items-center justify-end gap-2">
              <button
                onClick={() => setDetailReservation(item)}
                title="Ver detalle"
                className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-dm-text-muted transition-colors hover:bg-dm-bg-secondary hover:text-primary"
              >
                <Eye className="h-4 w-4" strokeWidth={2} />
              </button>
              {item.status === 'RESERVED' && (
                <>
                  <button
                    onClick={() => handleConfirmReservation(item)}
                    title="Confirmar venta"
                    className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-dm-text-muted transition-colors hover:bg-emerald-50 dark:hover:bg-emerald-950/30 hover:text-emerald-600 dark:text-emerald-400"
                  >
                    <Check className="h-4 w-4" strokeWidth={2} />
                  </button>
                  <button
                    onClick={() => handleCancelReservation(item)}
                    title="Cancelar reserva"
                    className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-dm-text-muted transition-colors hover:bg-red-50 dark:hover:bg-red-950/30 hover:text-red-600 dark:text-red-400"
                  >
                    <Ban className="h-4 w-4" strokeWidth={2} />
                  </button>
                </>
              )}
            </div>
          )}
        />
      </div>

      {/* Mobile Card View */}
      <div className="block lg:hidden space-y-3">
        {isLoading && (
          <div className="rounded-xl border border-dm-border-primary bg-dm-bg-primary p-8 text-center text-sm text-dm-text-muted">
            Cargando reservas…
          </div>
        )}
        {error && (
          <div className="rounded-xl border border-red-200 dark:border-red-800/50 bg-red-50 dark:bg-red-950/30 p-8 text-center text-sm text-red-600 dark:text-red-400">
            Error al cargar reservas
          </div>
        )}
        {!isLoading && !error && reservations.length === 0 && (
          <div className="rounded-xl border border-dm-border-primary bg-dm-bg-primary p-8 text-center text-sm text-dm-text-muted">
            No se encontraron reservas con los filtros actuales.
          </div>
        )}
        {!isLoading &&
          !error &&
          reservations.map((reservation) => (
            <div
              key={reservation.id}
              className="rounded-xl border border-dm-border-primary/80 bg-dm-bg-primary p-4 shadow-sm"
            >
              {/* Header: viaje + estado */}
              <div className="mb-3 flex items-start justify-between border-b border-dm-border-secondary pb-3">
                <div>
                  <div className="text-sm font-bold text-primary">
                    {reservation.trip_name || `Viaje #${reservation.trip_id}`}
                  </div>
                  <div className="text-[13px] font-medium text-dm-text-primary">
                    Asiento {reservation.seat_number}
                  </div>
                </div>
                <ReservationStatusBadge status={reservation.status} />
              </div>

              {/* Info */}
              <div className="mb-3 space-y-2">
                <div>
                  <div className="text-[10px] font-medium uppercase tracking-wider text-dm-text-muted">
                    Cliente
                  </div>
                  <div className="flex items-center gap-1.5 text-sm font-medium text-dm-text-primary">
                    <User className="h-3.5 w-3.5 shrink-0 text-dm-text-muted" />
                    {reservation.customer_name}
                  </div>
                  <div className="text-[11px] text-dm-text-muted">
                    {reservation.customer_doc_type} {reservation.customer_doc_number}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <div className="text-[10px] font-medium uppercase tracking-wider text-dm-text-muted">
                      Embarque
                    </div>
                    <div className="flex items-center gap-1 text-xs font-medium text-dm-text-primary">
                      <MapPin className="h-3 w-3 shrink-0 text-dm-text-muted" />
                      {reservation.boarding_stop?.port?.name || 'N/A'}
                    </div>
                  </div>
                  <div>
                    <div className="text-[10px] font-medium uppercase tracking-wider text-dm-text-muted">
                      Adelanto
                    </div>
                    <div className="flex items-center gap-1 text-sm font-semibold text-dm-text-primary">
                      <CreditCard className="h-3 w-3 shrink-0 text-dm-text-muted" />
                      {new Intl.NumberFormat('es-PE', {
                        style: 'currency',
                        currency: reservation.currency_code,
                      }).format(reservation.advance_amount)}
                    </div>
                  </div>
                </div>

                {reservation.expires_at && (
                  <div>
                    <div className="text-[10px] font-medium uppercase tracking-wider text-dm-text-muted">
                      Expira
                    </div>
                    <div className="flex items-center gap-1 text-xs font-medium text-dm-text-secondary">
                      <Clock className="h-3 w-3 shrink-0 text-dm-text-muted" />
                      {format(new Date(reservation.expires_at), 'dd MMM yyyy, hh:mm a', {
                        locale: es,
                      })}
                    </div>
                  </div>
                )}

                <div>
                  <div className="text-[10px] font-medium uppercase tracking-wider text-dm-text-muted">
                    Notas
                  </div>
                  {reservation.special_notes?.trim() ? (
                    <div className="flex items-start gap-1 text-xs font-medium text-dm-text-primary">
                      <StickyNote className="mt-0.5 h-3 w-3 shrink-0 text-amber-500" />
                      <span className="break-words">{reservation.special_notes}</span>
                    </div>
                  ) : (
                    <div className="text-xs text-dm-text-muted">Sin notas</div>
                  )}
                </div>
              </div>

              {/* Acciones */}
              <div className="flex gap-2 pt-3 border-t border-dm-border-secondary">
                <button
                  onClick={() => setDetailReservation(reservation)}
                  className="flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-dm-border-primary bg-dm-bg-secondary py-2 text-xs font-medium text-dm-text-secondary transition-colors hover:text-primary"
                >
                  <Eye className="h-3.5 w-3.5" />
                  Ver detalle
                </button>
              </div>

              {reservation.status === 'RESERVED' && (
                <div className="flex gap-2 pt-3">
                  <button
                    onClick={() => handleConfirmReservation(reservation)}
                    className="flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-emerald-200 bg-emerald-50 dark:bg-emerald-950/30 py-2 text-xs font-medium text-emerald-700 dark:text-emerald-300 transition-colors hover:bg-emerald-100"
                  >
                    <Check className="h-3.5 w-3.5" />
                    Confirmar
                  </button>
                  <button
                    onClick={() => handleCancelReservation(reservation)}
                    className="flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-red-200 dark:border-red-800/50 bg-red-50 dark:bg-red-950/30 py-2 text-xs font-medium text-red-700 dark:text-red-300 transition-colors hover:bg-red-100 dark:hover:bg-red-900/40"
                  >
                    <Ban className="h-3.5 w-3.5" />
                    Cancelar
                  </button>
                </div>
              )}
            </div>
          ))}
      </div>

      <ReservationDetailModal
        reservation={detailReservation}
        isOpen={!!detailReservation}
        onClose={() => setDetailReservation(null)}
        onConfirmSale={handleConfirmFromDetail}
        onCancelReservation={handleCancelFromDetail}
      />
    </div>
  );
};

// src/features/fluvial/pages/ScheduleTripsPage.tsx
import React, { useState, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { PlusIcon, CalendarIcon, ArrowPathIcon } from '@heroicons/react/24/outline';
import { toast } from '@/utils/sileo-toast';
import { useTripsView } from '../hooks/useTripsView';
import { useTripMutations, usePreviewVesselChange } from '../hooks/useTrips';
import { useScheduledTemplates } from '../hooks/useScheduledTemplates';
import { authService } from '../../../services/auth.service';
import { User, ScheduledRouteTemplate } from '../../../types';
import { UnifiedTripViewItem } from '../hooks/useTripsView';
import { useCities } from '../../../hooks/useCitiesPortsData';

import { Button } from '../../../components/common/Button';
import { Spinner } from '../../../components/common/Spinner';
import { ScheduledTemplatesTable } from '../components/schedule/ScheduledTemplatesTable';
import { TripsTable } from '../components/schedule/TripsTable';
import { ScheduledTemplateFormModal } from '../components/schedule/ScheduledTemplateFormModal';
import { TripFormModal } from '../components/schedule/TripFormModal';
import { TripFilters, TripAdvancedFilters } from '../components/schedule/TripFilters';
import { CalendarView } from '../components/schedule/CalendarView';
import { ManifestGenerationModal } from '../components/schedule/ManifestGenerationModal';
import { VesselChangePreviewModal } from '../components/schedule/VesselChangePreviewModal';
import { ManifestPreviewModal } from '../../manifests/components/ManifestPreviewModal';
import { Manifest } from '../../manifests/types/manifest.types';
import { PreviewVesselChangeResponse } from '../../../types';

type ViewFilterMode = 'upcoming' | 'week' | 'history';

const VIEW_FILTER_LABELS: Record<ViewFilterMode, string> = {
  upcoming: 'Proximos Viajes',
  week: 'Vista Semanal',
  history: 'Historial',
};

export const ScheduleTripsPage: React.FC = () => {
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [isTripModalOpen, setIsTripModalOpen] = useState(false);
  const [isManifestModalOpen, setIsManifestModalOpen] = useState(false);
  const [isPreviewModalOpen, setIsPreviewModalOpen] = useState(false);
  const [isVesselPreviewModalOpen, setIsVesselPreviewModalOpen] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<ScheduledRouteTemplate | null>(null);
  const [selectedTrip, setSelectedTrip] = useState<UnifiedTripViewItem | null>(null);
  const [selectedTripForManifest, setSelectedTripForManifest] = useState<UnifiedTripViewItem | null>(null);
  const [createdManifest, setCreatedManifest] = useState<Manifest | null>(null);
  const [initialDateForNewTrip, setInitialDateForNewTrip] = useState<Date | null>(null);
  const [vesselPreviewData, setVesselPreviewData] = useState<PreviewVesselChangeResponse | null>(null);
  const [pendingTripUpdate, setPendingTripUpdate] = useState<{ id: number; data: any } | null>(null);
  const [viewMode, setViewMode] = useState<'table' | 'calendar'>('table');
  const [viewFilter, setViewFilter] = useState<ViewFilterMode>('upcoming');
  const [weekDate, setWeekDate] = useState(new Date());
  const [advancedFilters, setAdvancedFilters] = useState<TripAdvancedFilters>({
    origin_city_id: undefined,
    destination_city_id: undefined,
    status: undefined,
    search: undefined,
  });

  const COMPANY_ID = 1;

  const { isLoading: isLoadingUser } = useQuery<User>({
    queryKey: ['currentUser'],
    queryFn: () => authService.getProfile(),
  });

  const { data: rawTrips = [], isLoading: isLoadingTrips, refetch } = useTripsView({
    viewMode: viewFilter,
    weekDate,
    companyId: COMPANY_ID,
    filters: advancedFilters,
  });

  const { data: cities = [] } = useCities();

  // Filtros frontend: status, search, y ciudades de origen/destino
  const trips = useMemo(() => {
    let result = rawTrips;

    if (advancedFilters.origin_city_id || advancedFilters.destination_city_id) {
      const originCity = cities.find(c => c.id === advancedFilters.origin_city_id);
      const destCity = cities.find(c => c.id === advancedFilters.destination_city_id);

      const originName = (originCity?.name || '').toLowerCase().trim();
      const destName = (destCity?.name || '').toLowerCase().trim();

      result = result.filter(t => {
        // Los nombres de origen/destino ya vienen en origin_port_name / destination_port_name
        // del UnifiedTripViewItem. Usamos el trip_name como fallback por si el endpoint
        // no rellena esos campos.
        const oPort = (t.origin_port_name || '').toLowerCase();
        const dPort = (t.destination_port_name || '').toLowerCase();
        const tName = (t.trip_name || '').toLowerCase();

        let matchOrigin = !advancedFilters.origin_city_id;
        let matchDest   = !advancedFilters.destination_city_id;

        if (advancedFilters.origin_city_id && originName) {
          matchOrigin = oPort.includes(originName) || tName.includes(originName);
        }
        if (advancedFilters.destination_city_id && destName) {
          matchDest = dPort.includes(destName) || tName.includes(destName);
        }

        return matchOrigin && matchDest;
      });
    }

    if (advancedFilters.status) {
      result = result.filter((t) => t.status === advancedFilters.status);
    }
    if (advancedFilters.search) {
      const q = advancedFilters.search.toLowerCase();
      result = result.filter(
        (t) =>
          (t.trip_name ?? '').toLowerCase().includes(q) ||
          (t.vessel_name ?? '').toLowerCase().includes(q) ||
          String(t.trip_id).includes(q)
      );
    }
    return result;
  }, [rawTrips, advancedFilters.status, advancedFilters.search, advancedFilters.origin_city_id, advancedFilters.destination_city_id, cities]);

  const { templates: scheduledTemplates, isLoading: isLoadingTemplates } = useScheduledTemplates(COMPANY_ID);

  const { createTemplate, updateTemplate, deactivateTemplate } = useScheduledTemplates(COMPANY_ID);
  const { createTrip, updateTrip, cancelTrip, isCreating: isCreatingTrip, isUpdating: isUpdatingTrip } = useTripMutations();
  const { mutateAsync: previewVesselChange, isPending: isPreviewingVesselChange } = usePreviewVesselChange();

  const handleCreateTemplate = () => {
    setSelectedTemplate(null);
    setIsTemplateModalOpen(true);
  };

  const handleEditTemplate = (template: ScheduledRouteTemplate) => {
    setSelectedTemplate(template);
    setIsTemplateModalOpen(true);
  };

  const handleDeleteTemplate = (template: ScheduledRouteTemplate) => {
    if (window.confirm(`¿Está seguro de desactivar la plantilla "${template.template_name}"?`)) {
      deactivateTemplate(template.id);
    }
  };

  const handleSaveTemplate = (data: any) => {
    if (selectedTemplate) {
      const { company_id, ...updateData } = data;
      updateTemplate({ id: selectedTemplate.id, data: updateData });
    } else {
      createTemplate({ ...data, company_id: COMPANY_ID });
    }
    setIsTemplateModalOpen(false);
  };

  const handleCreateTrip = () => {
    setSelectedTrip(null);
    setInitialDateForNewTrip(null);
    setIsTripModalOpen(true);
  };

  const handleDateClickFromCalendar = (date: Date) => {
    setSelectedTrip(null);
    setInitialDateForNewTrip(date);
    setIsTripModalOpen(true);
  };

  const handleEditTrip = (trip: UnifiedTripViewItem) => {
    setSelectedTrip(trip);
    setInitialDateForNewTrip(null);
    setIsTripModalOpen(true);
  };

  const handleCancelTrip = async (trip: UnifiedTripViewItem) => {
    const reason = window.prompt('Ingrese el motivo de cancelación (mínimo 10 caracteres):');
    if (reason && reason.length >= 10) {
      try {
        await cancelTrip({ id: trip.trip_id, data: { reason } });
        refetch();
      } catch (error) {
        toast.error('Error al cancelar el viaje');
      }
    } else if (reason !== null) {
      toast.warn('El motivo debe tener al menos 10 caracteres.');
    }
  };

  const handleSaveTrip = async (data: any) => {
    try {
      if (selectedTrip) {
        await updateTrip({ id: selectedTrip.trip_id, data });
      } else {
        await createTrip({ ...data, company_id: COMPANY_ID });
      }
      setIsTripModalOpen(false);
      refetch();
    } catch (error) {
      toast.error('Error al guardar el viaje');
    }
  };

  const handlePreviewVesselChange = async (tripId: number, newVesselId: number, data: any) => {
    try {
      const preview = await previewVesselChange({
        tripId,
        data: { new_vessel_id: newVesselId }
      });

      // Si hay reubicaciones, mostrar modal de confirmación
      if (preview.will_relocate_seats && preview.total_relocated > 0) {
        setPendingTripUpdate({ id: tripId, data });
        setVesselPreviewData(preview);
        setIsVesselPreviewModalOpen(true);
        return;
      }

      // Si no hay reubicaciones, proceder directamente
      await updateTrip({ id: tripId, data });
      setIsTripModalOpen(false);
      refetch();
      toast.success('Viaje actualizado exitosamente');
    } catch (error) {
      // El error ya se maneja en el hook con toast
    }
  };

  const handleConfirmVesselChange = async () => {
    if (!pendingTripUpdate) return;

    try {
      await updateTrip(pendingTripUpdate);
      setIsVesselPreviewModalOpen(false);
      setIsTripModalOpen(false);
      setPendingTripUpdate(null);
      setVesselPreviewData(null);
      refetch();
      toast.success('Viaje actualizado exitosamente');
    } catch (error) {
      toast.error('Error al aplicar el cambio de embarcación');
    }
  };

  const handleCloseVesselPreview = () => {
    setIsVesselPreviewModalOpen(false);
    setPendingTripUpdate(null);
    setVesselPreviewData(null);
  };

  const handleGenerateManifest = (trip: UnifiedTripViewItem) => {
    setSelectedTripForManifest(trip);
    setIsManifestModalOpen(true);
  };

  const handleManifestGenerated = () => {
    refetch();
  };

  const handleManifestCreated = (manifest: Manifest, _type: 'PASSENGER' | 'CARGO') => {
    setCreatedManifest(manifest);
    setIsManifestModalOpen(false);
    setIsPreviewModalOpen(true);
  };

  const mapManifestToManifestData = (manifest: Manifest): Manifest => {
    const result = {
      ...manifest,
      vessel_name: selectedTripForManifest?.vessel_name || undefined,
      route_name: undefined,
      departure_datetime: selectedTripForManifest?.departure_datetime || manifest.generation_date,
      total_passengers: manifest.total_passengers || 0,
      total_cargo_weight_kg: manifest.total_cargo_weight_kg || 0,
      items: manifest.items || []
    };
    return result;
  };

  const handleClosePreview = () => {
    setIsPreviewModalOpen(false);
    setCreatedManifest(null);
  };

  const handleRefresh = () => {
    refetch();
  };

  if (isLoadingUser) {
    return (
      <div className="flex justify-center items-center h-64">
        <Spinner size="lg" />
      </div>
    );
  }

  return (
    <div className="space-y-6">

      {/* ── Encabezado de pagina ─────────────────────────────────────────── */}
      <div>
        <h1 className="text-2xl font-bold text-dm-text-primary">Programar Viajes</h1>
        <p className="text-sm text-dm-text-muted mt-1">
          Gestione las plantillas de viajes recurrentes y los viajes programados
        </p>
      </div>

      {/* ── Seccion: Plantillas de Viajes Recurrentes ────────────────────── */}
      <div className="bg-dm-bg-primary rounded-xl border border-dm-border-secondary shadow-sm overflow-hidden">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 px-5 py-4 border-b border-dm-border-secondary">
          <div>
            <h2 className="text-base font-semibold text-dm-text-primary">Plantillas de Viajes Recurrentes</h2>
            {!isLoadingTemplates && (
              <p className="text-xs text-dm-text-muted mt-0.5">
                {scheduledTemplates?.length ?? 0}{' '}
                {(scheduledTemplates?.length ?? 0) === 1 ? 'plantilla configurada' : 'plantillas configuradas'}
              </p>
            )}
          </div>
          <Button
            variant="primary"
            onClick={handleCreateTemplate}
            className="flex items-center gap-2 w-full sm:w-auto justify-center"
          >
            <PlusIcon className="h-4 w-4" />
            Nueva Plantilla
          </Button>
        </div>

        {isLoadingTemplates ? (
          <div className="flex justify-center py-10">
            <Spinner size="lg" />
          </div>
        ) : (
          <ScheduledTemplatesTable
            templates={scheduledTemplates || []}
            onEdit={handleEditTemplate}
            onDelete={handleDeleteTemplate}
          />
        )}
      </div>

      {/* ── Seccion: Viajes Programados ──────────────────────────────────── */}
      <div className="bg-dm-bg-primary rounded-xl border border-dm-border-secondary shadow-sm overflow-hidden">
        {/* Header de la seccion */}
        <div className="px-5 py-4 border-b border-dm-border-secondary">
          <div className="flex flex-col lg:flex-row lg:items-center gap-4">
            {/* Titulo + contador */}
            <div className="flex-1 min-w-0">
              <h2 className="text-base font-semibold text-dm-text-primary">Viajes Programados</h2>
              {!isLoadingTrips && (
                <p className="text-xs text-dm-text-muted mt-0.5">
                  {trips.length} {trips.length === 1 ? 'viaje encontrado' : 'viajes encontrados'}
                </p>
              )}
            </div>

            {/* Controles de accion */}
            <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2">
              {/* Toggle tabla / calendario */}
              <div className="flex bg-dm-bg-secondary rounded-lg p-1 self-start sm:self-auto">
                <button
                  onClick={() => setViewMode('table')}
                  className={`flex-1 sm:flex-initial px-3 py-1.5 rounded-md text-sm font-medium transition-colors whitespace-nowrap ${
                    viewMode === 'table'
                      ? 'bg-dm-bg-primary text-dm-text-primary shadow-sm'
                      : 'text-dm-text-muted hover:text-dm-text-secondary'
                  }`}
                >
                  Tabla
                </button>
                <button
                  onClick={() => setViewMode('calendar')}
                  className={`flex-1 sm:flex-initial px-3 py-1.5 rounded-md text-sm font-medium transition-colors flex items-center justify-center gap-1.5 whitespace-nowrap ${
                    viewMode === 'calendar'
                      ? 'bg-dm-bg-primary text-dm-text-primary shadow-sm'
                      : 'text-dm-text-muted hover:text-dm-text-secondary'
                  }`}
                >
                  <CalendarIcon className="h-4 w-4" />
                  Calendario
                </button>
              </div>

              <div className="flex gap-2">
                <Button
                  variant="outline"
                  onClick={handleRefresh}
                  className="flex-1 sm:flex-initial flex items-center justify-center gap-1.5"
                >
                  <ArrowPathIcon className="h-4 w-4" />
                  Actualizar
                </Button>
                <Button
                  variant="primary"
                  onClick={handleCreateTrip}
                  className="flex-1 sm:flex-initial flex items-center justify-center gap-1.5"
                >
                  <PlusIcon className="h-4 w-4" />
                  Nuevo Viaje
                </Button>
              </div>
            </div>
          </div>

          {/* Tabs de modo de vista */}
          <div className="mt-4 flex gap-1 p-1 bg-dm-bg-secondary rounded-xl w-full sm:w-fit">
            {(Object.keys(VIEW_FILTER_LABELS) as ViewFilterMode[]).map((mode) => (
              <button
                key={mode}
                onClick={() => setViewFilter(mode)}
                className={`flex-1 sm:flex-initial px-4 py-1.5 text-sm font-medium rounded-lg whitespace-nowrap transition-colors ${
                  viewFilter === mode
                    ? 'bg-dm-bg-primary text-indigo-700 dark:text-indigo-300 shadow-sm font-semibold'
                    : 'text-dm-text-muted hover:text-dm-text-secondary'
                }`}
              >
                {VIEW_FILTER_LABELS[mode]}
              </button>
            ))}
          </div>
        </div>

        {/* Filtros */}
        <div className="px-5 py-4 border-b border-dm-border-secondary">
          <TripFilters
            currentDate={weekDate}
            onDateChange={setWeekDate}
            filters={advancedFilters}
            onFiltersChange={(filters) => setAdvancedFilters(prev => ({ ...prev, ...filters }))}
            viewMode={viewFilter}
          />
        </div>

        {/* Contenido principal */}
        {isLoadingTrips ? (
          <div className="flex justify-center py-16">
            <Spinner size="lg" />
          </div>
        ) : viewMode === 'table' ? (
          <TripsTable
            trips={trips}
            onEdit={handleEditTrip}
            onCancel={handleCancelTrip}
            onGenerateManifest={handleGenerateManifest}
          />
        ) : (
          <div className="p-4">
            <CalendarView
              trips={trips}
              onTripClick={handleEditTrip}
              onDateClick={handleDateClickFromCalendar}
            />
          </div>
        )}
      </div>

      {/* ── Modales ──────────────────────────────────────────────────────── */}
      {isTemplateModalOpen && (
        <ScheduledTemplateFormModal
          isOpen={isTemplateModalOpen}
          onClose={() => setIsTemplateModalOpen(false)}
          template={selectedTemplate}
          onSave={handleSaveTemplate}
        />
      )}

      {isTripModalOpen && (
        <TripFormModal
          isOpen={isTripModalOpen}
          onClose={() => setIsTripModalOpen(false)}
          trip={selectedTrip}
          onSave={handleSaveTrip}
          onPreviewVesselChange={handlePreviewVesselChange}
          isLoading={isCreatingTrip || isUpdatingTrip || isPreviewingVesselChange}
          initialDate={initialDateForNewTrip}
        />
      )}

      {isVesselPreviewModalOpen && (
        <VesselChangePreviewModal
          isOpen={isVesselPreviewModalOpen}
          onClose={handleCloseVesselPreview}
          onConfirm={handleConfirmVesselChange}
          previewData={vesselPreviewData}
          isLoading={isUpdatingTrip}
        />
      )}

      {isManifestModalOpen && selectedTripForManifest && (
        <ManifestGenerationModal
          isOpen={isManifestModalOpen}
          onClose={() => setIsManifestModalOpen(false)}
          trip={selectedTripForManifest}
          onManifestGenerated={handleManifestGenerated}
          onManifestCreated={handleManifestCreated}
        />
      )}

      {isPreviewModalOpen && createdManifest && selectedTripForManifest && (
        <ManifestPreviewModal
          isOpen={isPreviewModalOpen}
          onClose={handleClosePreview}
          manifestData={mapManifestToManifestData(createdManifest)}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { PlusIcon, MagnifyingGlassIcon, PencilIcon, TrashIcon, AdjustmentsHorizontalIcon, ArrowUpIcon, ArrowDownIcon } from '@heroicons/react/24/outline';
import { Button } from '../../../components/common/Button';
import { Input } from '../../../components/common/Input';
import { Modal } from '../../../components/common/Modal';
import { DataTable, Column, useConfirmDelete } from '../../../components/common/DataTable';
import { SeatType } from '../../../types';
import {
  useSeatTypes,
  useCreateSeatType,
  useUpdateSeatType,
  useDeleteSeatType,
  useUpdateSeatTypeOrder
} from '../hooks/useSeatTypesData';
import { SeatTypeCreateData } from '../../../services/seat-types.service';

// ========================================
// FORMULARIO DE TIPOS DE ASIENTO
// ========================================
interface SeatTypeFormProps {
  isOpen: boolean;
  onClose: () => void;
  seatType?: SeatType;
}

const SeatTypeFormModal: React.FC<SeatTypeFormProps> = ({ isOpen, onClose, seatType }) => {
  const createSeatType = useCreateSeatType();
  const updateSeatType = useUpdateSeatType();

  const [formData, setFormData] = useState<SeatTypeCreateData>({
    name: '',
    code: '',
    description: '',
    price_multiplier: 1.0,
    display_order: 1,
    is_active: true
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (seatType) {
      setFormData({
        name: seatType.name,
        code: seatType.code,
        description: seatType.description || '',
        price_multiplier: seatType.price_multiplier,
        display_order: seatType.display_order,
        is_active: seatType.is_active
      });
    } else {
      setFormData({
        name: '',
        code: '',
        description: '',
        price_multiplier: 1.0,
        display_order: 1,
        is_active: true
      });
    }
    setErrors({});
  }, [seatType, isOpen]);

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.name.trim()) {
      newErrors.name = 'El nombre es requerido';
    }

    if (!formData.code.trim()) {
      newErrors.code = 'El código es requerido';
    } else if (formData.code.length > 10) {
      newErrors.code = 'El código debe tener máximo 10 caracteres';
    }

    if (formData.price_multiplier <= 0 || formData.price_multiplier > 10) {
      newErrors.price_multiplier = 'El multiplicador debe estar entre 0.1 y 10.0';
    }

    if (formData.display_order < 1) {
      newErrors.display_order = 'El orden debe ser mayor a 0';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) return;

    try {
      if (seatType) {
        await updateSeatType.mutateAsync({ id: seatType.id, data: formData });
      } else {
        await createSeatType.mutateAsync(formData);
      }
      onClose();
    } catch (error) {
      // Los errores ya se manejan en los hooks
    }
  };

  if (!isOpen) return null;

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={onClose} 
      title={seatType ? 'Editar Tipo de Asiento' : 'Nuevo Tipo de Asiento'} 
      maxWidth="lg"
    >
      <form onSubmit={handleSubmit} className="p-6 space-y-4">
        <div className="grid grid-cols-2 gap-4">
          <Input
            label="Nombre *"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            error={errors.name}
            placeholder="Ej: Premium, Económico"
            required
          />
          <Input
            label="Código *"
            value={formData.code}
            onChange={(e) => setFormData({ ...formData, code: e.target.value.toUpperCase() })}
            error={errors.code}
            placeholder="Ej: PREM, ECO"
            maxLength={10}
            required
          />
        </div>

        <Input
          label="Descripción"
          value={formData.description}
          onChange={(e) => setFormData({ ...formData, description: e.target.value })}
          placeholder="Descripción detallada del tipo de asiento"
        />

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-dm-text-secondary mb-1">
              Multiplicador de Precio *
            </label>
            <input
              type="number"
              step="0.1"
              min="0.1"
              max="10.0"
              value={formData.price_multiplier}
              onChange={(e) => setFormData({ ...formData, price_multiplier: parseFloat(e.target.value) || 1.0 })}
              className={`w-full p-2 border rounded-md ${
                errors.price_multiplier ? 'border-red-500' : 'border-dm-border-primary'
              }`}
              placeholder="1.0"
              required
            />
            {errors.price_multiplier && (
              <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.price_multiplier}</p>
            )}
            <p className="text-xs text-dm-text-muted mt-1">
              Factor que se multiplica por la tarifa base (1.0 = precio normal, 1.5 = 50% más caro, 0.8 = 20% descuento)
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium text-dm-text-secondary mb-1">
              Orden de Visualización *
            </label>
            <input
              type="number"
              min="1"
              value={formData.display_order}
              onChange={(e) => setFormData({ ...formData, display_order: parseInt(e.target.value) || 1 })}
              className={`w-full p-2 border rounded-md ${
                errors.display_order ? 'border-red-500' : 'border-dm-border-primary'
              }`}
              required
            />
            {errors.display_order && (
              <p className="mt-1 text-sm text-red-600 dark:text-red-400">{errors.display_order}</p>
            )}
            <p className="text-xs text-dm-text-muted mt-1">
              Orden en que aparece en las listas
            </p>
          </div>
        </div>

        <div className="flex items-center">
          <input
            id="is_active"
            type="checkbox"
            checked={formData.is_active}
            onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
            className="h-4 w-4 text-blue-600 dark:text-blue-400 border-dm-border-primary rounded"
          />
          <label htmlFor="is_active" className="ml-2 block text-sm text-dm-text-secondary">
            Tipo de asiento activo
          </label>
        </div>

        <div className="flex justify-end gap-3 pt-4">
          <Button type="button" variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button 
            type="submit" 
            isLoading={createSeatType.isPending || updateSeatType.isPending}
          >
            {seatType ? 'Actualizar' : 'Crear'} Tipo de Asiento
          </Button>
        </div>
      </form>
    </Modal>
  );
};

// ========================================
// COMPONENTE PARA MOSTRAR EL PREVIEW DEL PRECIO
// ========================================
const PricePreview: React.FC<{ multiplier: number; basePrice?: number }> = ({ multiplier, basePrice = 85.00 }) => {
  const finalPrice = basePrice * multiplier;
  const discount = basePrice - finalPrice;

  return (
    <div className="text-xs text-dm-text-secondary">
      {multiplier === 1.0 ? (
        <span>Precio normal</span>
      ) : multiplier > 1.0 ? (
        <span className="text-red-600 dark:text-red-400">+S/ {(finalPrice - basePrice).toFixed(2)} (+{((multiplier - 1) * 100).toFixed(0)}%)</span>
      ) : (
        <span className="text-green-600 dark:text-green-400">-S/ {Math.abs(discount).toFixed(2)} (-{((1 - multiplier) * 100).toFixed(0)}%)</span>
      )}
      <div className="text-dm-text-muted">
        Base S/ {basePrice.toFixed(2)} → Final S/ {finalPrice.toFixed(2)}
      </div>
    </div>
  );
};

// ========================================
// COMPONENTE PRINCIPAL
// ========================================
export const SeatTypesPage: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showOnlyActive, setShowOnlyActive] = useState(true);

  // Estados para modales
  const [showSeatTypeModal, setShowSeatTypeModal] = useState(false);
  const [editingSeatType, setEditingSeatType] = useState<SeatType | undefined>();

  // Queries
  const { data: seatTypes = [], isLoading, error } = useSeatTypes(showOnlyActive);

  // Mutations
  const deleteSeatType = useDeleteSeatType();
  const updateSeatTypeOrder = useUpdateSeatTypeOrder();
  const updateSeatType = useUpdateSeatType();

  // Confirmación de eliminación
  const handleDeleteSeatType = useConfirmDelete(
    (seatType: SeatType) => deleteSeatType.mutate(seatType.id),
    (seatType: SeatType) => `¿Está seguro de desactivar el tipo de asiento ${seatType.name}? Esta acción puede afectar la venta de tickets con este tipo.`
  );

  // Filtrar tipos de asiento según búsqueda
  const filteredSeatTypes = seatTypes
    .filter(seatType =>
      seatType.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      seatType.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
      seatType.description?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => a.display_order - b.display_order);

  // Manejar cambio de estado
  const handleToggleStatus = async (seatType: SeatType) => {
    try {
      await updateSeatType.mutateAsync({ 
        id: seatType.id, 
        data: { is_active: !seatType.is_active } 
      });
    } catch (error) {
      // Error ya manejado en el hook
    }
  };

  // Manejar cambio de orden
  const handleMoveOrder = async (seatTypeId: number, direction: 'up' | 'down') => {
    const index = filteredSeatTypes.findIndex(st => st.id === seatTypeId);
    if (index === -1) return;

    const updatedSeatTypes = [...filteredSeatTypes];

    if (direction === 'up' && index > 0) {
      // Intercambiar con el anterior
      const temp = updatedSeatTypes[index].display_order;
      updatedSeatTypes[index].display_order = updatedSeatTypes[index - 1].display_order;
      updatedSeatTypes[index - 1].display_order = temp;
    } else if (direction === 'down' && index < updatedSeatTypes.length - 1) {
      // Intercambiar con el siguiente
      const temp = updatedSeatTypes[index].display_order;
      updatedSeatTypes[index].display_order = updatedSeatTypes[index + 1].display_order;
      updatedSeatTypes[index + 1].display_order = temp;
    } else {
      return; // No hay cambio
    }

    // Actualizar el orden en el backend
    const seatTypesToUpdate = updatedSeatTypes.map(st => ({
      id: st.id,
      display_order: st.display_order
    }));

    await updateSeatTypeOrder.mutateAsync({ seatTypes: seatTypesToUpdate });
  };

  // Calcular estadísticas
  const stats = {
    total: seatTypes.length,
    active: seatTypes.filter(st => st.is_active).length,
    inactive: seatTypes.filter(st => !st.is_active).length,
    withDiscount: seatTypes.filter(st => st.price_multiplier < 1.0).length,
    withSurcharge: seatTypes.filter(st => st.price_multiplier > 1.0).length
  };

  // Columnas para la tabla
  const columns: Column<SeatType>[] = [
    {
      key: 'order',
      header: 'Orden',
      accessor: (seatType) => (
        <div className="flex items-center gap-2">
          <span className="font-medium text-dm-text-primary">{seatType.display_order}</span>
          <div className="flex flex-col gap-1">
            <button
              onClick={() => handleMoveOrder(seatType.id, 'up')}
              disabled={filteredSeatTypes.findIndex(st => st.id === seatType.id) === 0}
              className="text-dm-text-muted hover:text-dm-text-secondary disabled:opacity-50"
              title="Mover arriba"
            >
              <ArrowUpIcon className="h-3 w-3" />
            </button>
            <button
              onClick={() => handleMoveOrder(seatType.id, 'down')}
              disabled={filteredSeatTypes.findIndex(st => st.id === seatType.id) === filteredSeatTypes.length - 1}
              className="text-dm-text-muted hover:text-dm-text-secondary disabled:opacity-50"
              title="Mover abajo"
            >
              <ArrowDownIcon className="h-3 w-3" />
            </button>
          </div>
        </div>
      ),
    },
    {
      key: 'name',
      header: 'Tipo de Asiento',
      accessor: (seatType) => (
        <div>
          <div className="font-medium text-dm-text-primary">{seatType.name}</div>
          {seatType.description && (
            <div className="text-sm text-dm-text-muted">{seatType.description}</div>
          )}
        </div>
      ),
    },
    {
      key: 'code',
      header: 'Código',
      accessor: (seatType) => (
        <span className="px-2 py-1 text-xs font-medium rounded-full bg-blue-100 dark:bg-blue-900/40 text-blue-800 dark:text-blue-300">
