import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { SeatOperations } from './seatOperations';

describe('SeatOperations', () => {
  const sendMessage = vi.fn((_msg?: any) => true);
  const userId = 'user-123';
  const userName = 'Test User';
  const tripId = 42;
  const companyName = 'Acme Corp';

  beforeEach(() => {
    sendMessage.mockClear();
    sessionStorage.clear();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  const getLastCall = () => (sendMessage.mock.calls as any[][])[sendMessage.mock.calls.length - 1][0];

  describe('basic operations', () => {
    it('selectSeat sends SEAT_SELECTION with all required fields', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId);
      const result = ops.selectSeat(10, 'temporary');

      expect(result).toBe(true);
      expect(sendMessage).toHaveBeenCalledTimes(1);
      const msg = getLastCall();
      expect(msg).toMatchObject({
        type: 'SEAT_SELECTION',
        seatId: 10,
        userId,
        userName,
        selectionType: 'temporary',
        tripId,
      });
      expect(msg.timestamp).toBeDefined();
    });

    it('releaseSeat sends SEAT_RELEASED', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId);
      ops.releaseSeat(11);

      expect(sendMessage).toHaveBeenCalledTimes(1);
      const msg = getLastCall();
      expect(msg).toMatchObject({
        type: 'SEAT_RELEASED',
        seatId: 11,
        userId,
        userName,
        tripId,
      });
    });

    it('updateSeatStatus sends SEAT_UPDATE', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId);
      ops.updateSeatStatus(12, 'RESERVED');

      const msg = getLastCall();
      expect(msg).toMatchObject({
        type: 'SEAT_UPDATE',
        seatId: 12,
        status: 'RESERVED',
        tripId,
      });
    });
  });

  describe('representative operations', () => {
    it('selectSeatForRepresentative generates synthetic userId and sends SEAT_TEMP_RESERVE', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId, companyName);
      ops.selectSeatForRepresentative(20, 0, 'Rep One');

      const msg = getLastCall();
      expect(msg.type).toBe('SEAT_TEMP_RESERVE');
      expect(msg.seatId).toBe(20);
      expect(msg.userId).toMatch(new RegExp(`^${userId}-company-.*-rep-0$`));
      expect(msg.userName).toBe('Acme Corp - Rep One');
      expect(msg.representativeName).toBe('Rep One');
      expect(msg.reservationType).toBe('representative');
      expect(msg.tripId).toBe(tripId);
      expect(msg.sessionId).toBeDefined();
    });

    it('reuses the same sessionId across multiple representative selections', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId, companyName);
      ops.selectSeatForRepresentative(21, 0, 'Rep One');
      const sessionId1 = getLastCall().sessionId;

      ops.selectSeatForRepresentative(22, 1, 'Rep Two');
      const sessionId2 = getLastCall().sessionId;

      expect(sessionId1).toBe(sessionId2);
    });

    it('stores representative reservation in sessionStorage', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId, companyName);
      ops.selectSeatForRepresentative(23, 2, 'Rep Three');

      const key = `representative-seats-${userId}-${tripId}`;
      const stored = JSON.parse(sessionStorage.getItem(key) || '{}');
      expect(stored[2]).toMatchObject({
        seatId: 23,
        representativeName: 'Rep Three',
      });
    });

    it('releaseSeatForRepresentative with index uses synthetic userId', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId, companyName);
      // First create a session
      ops.selectSeatForRepresentative(24, 0, 'Rep');
      const sessionId = getLastCall().sessionId;

      sendMessage.mockClear();
      ops.releaseSeatForRepresentative(24, 0);

      const msg = getLastCall();
      expect(msg.type).toBe('SEAT_TEMP_RELEASE');
      expect(msg.userId).toBe(`${userId}-company-${sessionId}-rep-0`);
      expect(msg.reservationType).toBe('representative');
      expect(msg.tripId).toBe(tripId);
    });

    it('releaseSeatForRepresentative without index uses base userId', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId, companyName);
      ops.releaseSeatForRepresentative(25);

      const msg = getLastCall();
      expect(msg.type).toBe('SEAT_TEMP_RELEASE');
      expect(msg.userId).toBe(userId);
      expect(msg.reservationType).toBe('representative');
    });
  });

  describe('purchase operations', () => {
    it('confirmPurchase sends SOLD update for each seat', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId);
      ops.confirmPurchase([30, 31, 32]);

      expect(sendMessage).toHaveBeenCalledTimes(3);
      const calls = (sendMessage.mock.calls as any[][]).map(c => c[0]);
      expect(calls[0]).toMatchObject({ type: 'SEAT_UPDATE', seatId: 30, status: 'SOLD' });
      expect(calls[1]).toMatchObject({ type: 'SEAT_UPDATE', seatId: 31, status: 'SOLD' });
      expect(calls[2]).toMatchObject({ type: 'SEAT_UPDATE', seatId: 32, status: 'SOLD' });
    });

    it('returns false if any confirmPurchase send fails', () => {
      const failingSend = vi.fn(() => false);
      const ops = new SeatOperations(failingSend, userId, userName, tripId);
      const result = ops.confirmPurchase([40]);

      expect(result).toBe(false);
    });
  });

  describe('bulk operations', () => {
    it('releaseAllTemporaryReservations sends SEAT_TEMP_RELEASE_ALL', () => {
      const ops = new SeatOperations(sendMessage, userId, userName, tripId);
      ops.releaseAllTemporaryReservations();

      const msg = getLastCall();
      expect(msg).toMatchObject({
        type: 'SEAT_TEMP_RELEASE_ALL',
        userId,
        userName,
        tripId,
      });
    });
  });
});

// src/features/fluvial/services/seatOperations.ts

export interface SeatOperationMessage {
  type: string;
  seatId?: number;
  userId?: string;
  userName?: string;
  selectionType?: string;
  status?: string;
  reservationType?: string;
  companyName?: string;
  representativeName?: string;
  representativeIndex?: number;
  timestamp: string;
  tripId?: number; // ← NUEVO: Agregar tripId para que el backend pueda hacer broadcast
  // NUEVO: Campos adicionales para sesión de empresa
  sessionId?: string;
  maxGroupReservations?: number;
}

export class SeatOperations {
  private sendMessage: (message: any) => boolean;
  private userId: string;
  private userName: string;
  private companyName?: string;
  private tripId: number; // NUEVO: Agregar tripId

  constructor(
    sendMessage: (message: any) => boolean,
    userId: string,
    userName: string,
    tripId: number, // NUEVO: Agregar tripId al constructor
    companyName?: string
  ) {
    this.sendMessage = sendMessage;
    this.userId = userId;
    this.userName = userName;
    this.tripId = tripId; // NUEVO: Inicializar tripId
    this.companyName = companyName;
  }

  // Operaciones básicas de asientos
  selectSeat(seatId: number, selectionType: 'temporary' | 'reserved' = 'temporary'): boolean {
    const message: SeatOperationMessage = {
      type: 'SEAT_SELECTION',
      seatId,
      userId: this.userId, //  SOLUCIÓN: Asegurar que el userId se envíe
      userName: this.userName, //  SOLUCIÓN: Asegurar que el userName se envíe
      selectionType,
      tripId: this.tripId, // ← NUEVO: Agregar tripId
      timestamp: new Date().toISOString()
    };

    return this.sendMessage(message);
  }

  releaseSeat(seatId: number): boolean {
    const message: SeatOperationMessage = {
      type: 'SEAT_RELEASED',
      seatId,
      userId: this.userId, //  SOLUCIÓN: Asegurar que el userId se envíe
      userName: this.userName,
      tripId: this.tripId, // ← NUEVO: Agregar tripId
      timestamp: new Date().toISOString()
    };

    return this.sendMessage(message);
  }

  updateSeatStatus(seatId: number, status: string): boolean {
    const message: SeatOperationMessage = {
      type: 'SEAT_UPDATE',
      seatId,
      status,
      tripId: this.tripId, // ← NUEVO: Agregar tripId
      timestamp: new Date().toISOString()
    };

    return this.sendMessage(message);
  }

  // Operaciones para representantes
  selectSeatForRepresentative(
    seatId: number, 
    representativeIndex: number, 
    representativeName: string
  ): boolean {
    // Formato exacto que requiere el backend
    const sessionId = this.getOrCreateCompanySessionId();
    const representativeUserId = `${this.userId}-company-${sessionId}-rep-${representativeIndex}`;

    const message = {
      type: 'SEAT_TEMP_RESERVE',
      seatId: seatId,
      userId: representativeUserId,
      userName: `${this.companyName || 'Empresa'} - ${representativeName}`,
      representativeName: representativeName,
      sessionId: sessionId,
      reservationType: 'representative',
      tripId: this.tripId // ← NUEVO: Agregar tripId
    };

    this.trackRepresentativeReservation(seatId, representativeIndex, representativeName);
    return this.sendMessage(message);
  }

  private getOrCreateCompanySessionId(): string {
    const storageKey = `company-session-${this.userId}-${this.tripId}`;
    let sessionId = sessionStorage.getItem(storageKey);

    if (!sessionId) {
      sessionId = `session-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      sessionStorage.setItem(storageKey, sessionId);
    }

    return sessionId;
  }

  private trackRepresentativeReservation(seatId: number, representativeIndex: number, representativeName: string) {
    const storageKey = `representative-seats-${this.userId}-${this.tripId}`;
    let reservations = JSON.parse(sessionStorage.getItem(storageKey) || '{}');

    reservations[representativeIndex] = {
      seatId,
      representativeName,
      timestamp: new Date().toISOString()
    };

    sessionStorage.setItem(storageKey, JSON.stringify(reservations));
  }

  releaseSeatForRepresentative(seatId: number, representativeIndex?: number): boolean {
    // Si se proporciona el índice, usar la misma lógica que para reservar
    if (representativeIndex !== undefined) {
      const sessionId = this.getOrCreateCompanySessionId();
      const representativeUserId = `${this.userId}-company-${sessionId}-rep-${representativeIndex}`;
      const message = {
        type: 'SEAT_TEMP_RELEASE',
        seatId: seatId,
        userId: representativeUserId,
        sessionId: sessionId,
        reservationType: 'representative',
        tripId: this.tripId,
        timestamp: new Date().toISOString()
      };

      return this.sendMessage(message);
    } else {
      const message = {
        type: 'SEAT_TEMP_RELEASE',
        seatId: seatId,
        userId: this.userId,
        reservationType: 'representative',
        tripId: this.tripId,
        timestamp: new Date().toISOString()
      };

      return this.sendMessage(message);
    }
  }

  // Operaciones de compra
  confirmPurchase(seatIds: number[]): boolean {
    let allSuccess = true;

    seatIds.forEach(seatId => {
      const success = this.updateSeatStatus(seatId, 'SOLD');
      if (!success) allSuccess = false;
    });

    return allSuccess;
  }

  // Liberar todas las reservas temporales del usuario
  releaseAllTemporaryReservations(): boolean {
    const message: SeatOperationMessage = {
      type: 'SEAT_TEMP_RELEASE_ALL',
      userId: this.userId,
      userName: this.userName,
      tripId: this.tripId, // ← NUEVO: Agregar tripId
      timestamp: new Date().toISOString()
    };

    return this.sendMessage(message);
  }
}

