  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  const baseMessage = (overrides: Partial<SeatUpdateMessage> = {}): SeatUpdateMessage => ({
    type: 'SEAT_UPDATE',
    tripId: 1,
    timestamp: new Date().toISOString(),
    ...overrides,
  });

  describe('INITIAL_STATE', () => {
    it('processes seatMap from backend official format', () => {
      const msg = baseMessage({
        type: 'INITIAL_STATE',
        seatMap: [
          { id: 153893, seat_number: '1', status: 'AVAILABLE' },
          { id: 153894, seat_number: '2', status: 'RESERVED' },
          { id: 153895, seat_number: '3', status: 'CONFIRMED' },
          { id: 153896, seat_number: '4', status: 'SOLD' },
        ],
      });

      handler.handleMessage(msg);

      // Todos los asientos del seatMap deben actualizarse
      expect(onSeatMapUpdate).toHaveBeenCalledWith(153893, 'AVAILABLE', undefined);
      expect(onSeatMapUpdate).toHaveBeenCalledWith(153894, 'RESERVED', undefined);
      expect(onSeatMapUpdate).toHaveBeenCalledWith(153895, 'CONFIRMED', undefined);
      expect(onSeatMapUpdate).toHaveBeenCalledWith(153896, 'SOLD', undefined);
    });

    it('processes seatMap with occupants and marks confirmedSeats', () => {
      const occupant: SeatOccupantInfo = {
        passenger_name: 'John',
        origin_stop_name: 'A',
        destination_stop_name: 'B',
        amount_paid: 100,
        currency_code: 'PEN',
      };
      const msg = baseMessage({
        type: 'INITIAL_STATE',
        seatMap: [
          { id: 153895, seat_number: '3', status: 'CONFIRMED', occupant },
        ],
      });

      handler.handleMessage(msg);

      expect(onSeatMapUpdate).toHaveBeenCalledWith(153895, 'CONFIRMED', occupant);

      // Tras confirmar, SEAT_RELEASED debe ignorar este asiento
      onSelectionRemove.mockClear();
      handler.handleMessage(baseMessage({ type: 'SEAT_RELEASED', seatId: 153895, userId: 'other' }));
      expect(onSelectionRemove).not.toHaveBeenCalled();
    });

    it('processes selecctionSeats from other users and occupiedSeats', () => {
      const msg = baseMessage({
        type: 'INITIAL_STATE',
        selecctionSeats: [
          { seatId: 1, userId: 'other-user', userName: 'Other', timestamp: new Date().toISOString(), status: 'SEAT_SELECTION' },
          { seatId: 2, userId: `${userId}-company-session1-rep-0`, userName: 'Me Rep', timestamp: new Date().toISOString(), status: 'SEAT_SELECTION' },
        ],
        occupiedSeats: [
          { seatId: 3, userId: 'seller', userName: 'Seller', timestamp: new Date().toISOString(), status: 'OCCUPIED', invoiceId: 101 },
        ],
      });

      handler.handleMessage(msg);

      // selecctionSeats: filtra la del mismo user base
      expect(onInitialState).toHaveBeenCalledTimes(1);
      const selections = onInitialState.mock.calls[0][0] as SeatSelection[];
      expect(selections).toHaveLength(1);
      expect(selections[0].seatId).toBe(1);
      expect(selections[0].type).toBe('temporary');

      // occupiedSeats → CONFIRMED
      expect(onSeatMapUpdate).toHaveBeenCalledWith(3, 'CONFIRMED', undefined);
    });

    it('extracts occupant from occupants map for occupied seats', () => {
      const occupant: SeatOccupantInfo = {
        passenger_name: 'John',
        origin_stop_name: 'A',
        destination_stop_name: 'B',
        amount_paid: 100,
        currency_code: 'PEN',
      };
      const msg = baseMessage({
        type: 'INITIAL_STATE',
        occupiedSeats: [
          { seatId: 5, userId: 'seller', userName: 'Seller', timestamp: new Date().toISOString(), status: 'OCCUPIED', invoiceId: 102 },
        ],
        occupants: { '5': occupant },
      });

      handler.handleMessage(msg);
      expect(onSeatMapUpdate).toHaveBeenCalledWith(5, 'CONFIRMED', occupant);
    });

    it('falls back to legacy seats field when selecctionSeats is absent', () => {
      const msg = baseMessage({
        type: 'INITIAL_STATE',
        seats: [
          { seatId: 10, userId: 'legacy-user', userName: 'Legacy' },
          { seatId: 11, userId: userId, userName: 'Me' },
        ],
      });

      handler.handleMessage(msg);

      expect(onInitialState).toHaveBeenCalledTimes(1);
      const selections = onInitialState.mock.calls[0][0] as SeatSelection[];
      expect(selections).toHaveLength(1);
      expect(selections[0].seatId).toBe(10);
    });
  });

  describe('SEAT_UPDATE', () => {
    it('updates seat and adds to confirmedSeats for SOLD', () => {
      const msg = baseMessage({ type: 'SEAT_UPDATE', seatId: 7, status: 'SOLD' });
      handler.handleMessage(msg);

      expect(onSeatMapUpdate).toHaveBeenCalledWith(7, 'SOLD');
      expect(onSelectionRemove).toHaveBeenCalledWith(7);
    });

    it('adds CONFIRMED and OCCUPIED to confirmedSeats', () => {
      handler.handleMessage(baseMessage({ type: 'SEAT_UPDATE', seatId: 8, status: 'CONFIRMED' }));
      handler.handleMessage(baseMessage({ type: 'SEAT_UPDATE', seatId: 9, status: 'occupied' }));

      // Tras confirmar, SEAT_RELEASED debe ignorar estos asientos
      onSelectionRemove.mockClear();
      handler.handleMessage(baseMessage({ type: 'SEAT_RELEASED', seatId: 8, userId: 'other' }));
      handler.handleMessage(baseMessage({ type: 'SEAT_RELEASED', seatId: 9, userId: 'other' }));
      expect(onSelectionRemove).not.toHaveBeenCalled();
    });
  });

  describe('SEAT_SELECTION', () => {
    it('adds selection from different user', () => {
      const msg = baseMessage({
        type: 'SEAT_SELECTION',
        seatId: 20,
        userId: 'other-user',
        userName: 'Other',
      });
      handler.handleMessage(msg);

      expect(onSelectionUpdate).toHaveBeenCalledWith(
        expect.objectContaining({
          seatId: 20,
          userId: 'other-user',
          type: 'temporary',
        })
      );
    });

    it('ignores selection from same base user (including representative suffix)', () => {
      const msg = baseMessage({
        type: 'SEAT_SELECTION',
        seatId: 21,
        userId: `${userId}-company-session1-rep-0`,
        userName: 'Rep',
      });
      handler.handleMessage(msg);
      expect(onSelectionUpdate).not.toHaveBeenCalled();
    });
  });

  describe('SEAT_RELEASED', () => {
    it('removes selection for non-confirmed seats', () => {
      handler.handleMessage(baseMessage({ type: 'SEAT_RELEASED', seatId: 30, userId: 'other' }));
      expect(onSelectionRemove).toHaveBeenCalledWith(30, 'other');
    });

    it('ignores release for confirmed seats', () => {
      // Marcar como vendido primero
      handler.handleMessage(baseMessage({ type: 'SEAT_UPDATE', seatId: 31, status: 'SOLD' }));
      onSelectionRemove.mockClear();

      handler.handleMessage(baseMessage({ type: 'SEAT_RELEASED', seatId: 31, userId: 'other' }));
      expect(onSelectionRemove).not.toHaveBeenCalled();
    });
  });

  describe('SEAT_RESERVED', () => {
    it('updates seat to RESERVED and removes selection', () => {
      handler.handleMessage(baseMessage({ type: 'SEAT_RESERVED', seatId: 40 }));

      expect(onSeatMapUpdate).toHaveBeenCalledWith(40, 'RESERVED');
      expect(onSelectionRemove).toHaveBeenCalledWith(40);
    });

    it('handles full backend payload with seatTypeId, reservationId, etc.', () => {
      const msg = baseMessage({
        type: 'SEAT_RESERVED',
        seatId: 153908,
        seatNumber: '16',
        seatTypeId: 2,
        reservationId: 1971,
        customerId: 0,
        quantity: 1,
      });

      handler.handleMessage(msg);

      expect(onSeatMapUpdate).toHaveBeenCalledWith(153908, 'RESERVED');
      expect(onSelectionRemove).toHaveBeenCalledWith(153908);
    });
  });

  describe('SEATS_RELEASED', () => {
    it('marks multiple seats as AVAILABLE and removes selections', () => {
      // Primero marcar como confirmado para probar que se libera
      handler.handleMessage(baseMessage({ type: 'SEAT_UPDATE', seatId: 100, status: 'SOLD' }));
      handler.handleMessage(baseMessage({ type: 'SEAT_UPDATE', seatId: 101, status: 'CONFIRMED' }));
      onSelectionRemove.mockClear();

      const msg = baseMessage({
        type: 'SEATS_RELEASED',
        seatIds: [100, 101],
        reason: 'CANCELLED_RESERVATION',
      });

      handler.handleMessage(msg);

      expect(onSeatMapUpdate).toHaveBeenCalledWith(100, 'AVAILABLE');
      expect(onSeatMapUpdate).toHaveBeenCalledWith(101, 'AVAILABLE');
      expect(onSelectionRemove).toHaveBeenCalledWith(100);
      expect(onSelectionRemove).toHaveBeenCalledWith(101);
    });

    it('handles single seat release', () => {
      const msg = baseMessage({
        type: 'SEATS_RELEASED',
        seatIds: [102],
        reason: 'TIMEOUT',
      });

      handler.handleMessage(msg);

      expect(onSeatMapUpdate).toHaveBeenCalledWith(102, 'AVAILABLE');
      expect(onSelectionRemove).toHaveBeenCalledWith(102);
    });

    it('ignores empty seatIds array', () => {
      const msg = baseMessage({
        type: 'SEATS_RELEASED',
        seatIds: [],
        reason: 'TIMEOUT',
      });

      handler.handleMessage(msg);

      expect(onSeatMapUpdate).not.toHaveBeenCalled();
      expect(onSelectionRemove).not.toHaveBeenCalled();
    });
  });

  describe('SEATS_OCCUPIED', () => {
    it('marks multiple seats as CONFIRMED with occupants', () => {
      const occupant: SeatOccupantInfo = {
        passenger_name: 'Jane',
        origin_stop_name: 'X',
        destination_stop_name: 'Y',
        amount_paid: 100,
        currency_code: 'PEN',
      };
      const msg = baseMessage({
        type: 'SEATS_OCCUPIED',
        seatIds: [50, 51],
        occupants: { '50': occupant },
      });

      handler.handleMessage(msg);

      expect(onSeatMapUpdate).toHaveBeenCalledWith(50, 'CONFIRMED', occupant);
      expect(onSeatMapUpdate).toHaveBeenCalledWith(51, 'CONFIRMED', undefined);
      expect(onSelectionRemove).toHaveBeenCalledWith(50);
      expect(onSelectionRemove).toHaveBeenCalledWith(51);
    });
  });

  describe('SEAT_MAP_UPDATE', () => {
    it('processes batch seat updates', () => {
      const msg = baseMessage({
        type: 'SEAT_MAP_UPDATE',
        seats: [
          { seatId: 60, userId: 'seller', userName: 'Seller', status: 'SOLD' },
          { seatId: 61, userId: 'seller', userName: 'Seller', status: 'AVAILABLE' },
        ],
      });

      handler.handleMessage(msg);

      expect(onSeatMapUpdate).toHaveBeenCalledWith(60, 'SOLD');
      expect(onSeatMapUpdate).toHaveBeenCalledWith(61, 'AVAILABLE');
    });

    it('processes single seatId update', () => {
      const msg = baseMessage({ type: 'SEAT_MAP_UPDATE', seatId: 62, status: 'CONFIRMED' });
      handler.handleMessage(msg);
      expect(onSeatMapUpdate).toHaveBeenCalledWith(62, 'CONFIRMED');
    });
  });

  describe('SEAT_TEMP_RESERVED', () => {
    it('adds representative reservation from different user', () => {
      const msg = baseMessage({
        type: 'SEAT_TEMP_RESERVED',
        seatId: 70,
        userId: 'other-user',
        userName: 'Other',
        reservationType: 'representative',
        ttl: 1800,
        companyName: 'Acme',
        representativeName: 'Rep1',
        representativeIndex: 0,
      });

      handler.handleMessage(msg);

      expect(onSelectionUpdate).toHaveBeenCalledWith(
        expect.objectContaining({
          seatId: 70,
          type: 'representative',
          companyName: 'Acme',
          representativeName: 'Rep1',
          ttl: 1800,
        })
      );
    });

    it('ignores temp reserved from same base user', () => {
      const msg = baseMessage({
        type: 'SEAT_TEMP_RESERVED',
        seatId: 71,
        userId: userId,
        userName: 'Me',
      });
      handler.handleMessage(msg);
      expect(onSelectionUpdate).not.toHaveBeenCalled();
    });
  });

  describe('SEAT_TEMP_RELEASED', () => {
    it('removes temp reservation for non-confirmed seats', () => {
      handler.handleMessage(baseMessage({ type: 'SEAT_TEMP_RELEASED', seatId: 80, userId: 'other' }));
      expect(onSelectionRemove).toHaveBeenCalledWith(80, 'other');
    });

    it('ignores temp release for confirmed seats', () => {
      handler.handleMessage(baseMessage({ type: 'SEAT_UPDATE', seatId: 81, status: 'SOLD' }));
      onSelectionRemove.mockClear();

      handler.handleMessage(baseMessage({ type: 'SEAT_TEMP_RELEASED', seatId: 81 }));
      expect(onSelectionRemove).not.toHaveBeenCalled();
    });
  });

  describe('SEAT_TEMP_RESERVE_RESPONSE', () => {
    it('shows toast error on failed reservation', () => {
      vi.useFakeTimers();
      const msg = baseMessage({
        type: 'SEAT_TEMP_RESERVE_RESPONSE',
        seatId: 90,
        success: false,
        error: 'Asiento ocupado',
      });

      handler.handleMessage(msg);

      // showReserveError usa setTimeout(..., 50)
      vi.advanceTimersByTime(100);

      vi.useRealTimers();
    });

    it('does nothing on successful reservation response', () => {
      const msg = baseMessage({
        type: 'SEAT_TEMP_RESERVE_RESPONSE',
        seatId: 91,
        success: true,
      });
      handler.handleMessage(msg);
      expect(onSeatMapUpdate).not.toHaveBeenCalled();
      expect(onSelectionUpdate).not.toHaveBeenCalled();
    });
  });

  describe('PONG', () => {
    it('does nothing', () => {
      handler.handleMessage(baseMessage({ type: 'PONG' }));
      expect(onSeatMapUpdate).not.toHaveBeenCalled();
      expect(onSelectionUpdate).not.toHaveBeenCalled();
      expect(onSelectionRemove).not.toHaveBeenCalled();
      expect(onInitialState).not.toHaveBeenCalled();
    });
  });

  describe('unknown message type', () => {
    it('does nothing for unhandled types', () => {
      handler.handleMessage(baseMessage({ type: 'UNKNOWN_TYPE' as any }));
      expect(onSeatMapUpdate).not.toHaveBeenCalled();
    });
  });
});

// src/features/fluvial/services/websocketMessageHandler.ts
import { SeatUpdateMessage, SeatSelection, SelectionSeat, OccupiedSeat } from '../types/websocket.types';
import { SeatOccupantInfo } from '../../../types';

export class WebSocketMessageHandler {
  private userId: string;
  private onSeatMapUpdate: (seatId: number, status: string, occupant?: SeatOccupantInfo) => void;
  private onSelectionUpdate: (selection: SeatSelection) => void;
  private onSelectionRemove: (seatId: number, sourceUserId?: string) => void;
  private onInitialState: (selections: SeatSelection[]) => void;
  private confirmedSeats: Set<number> = new Set(); // Rastrear asientos vendidos definitivamente

  constructor(
    userId: string,
    callbacks: {
      onSeatMapUpdate: (seatId: number, status: string, occupant?: SeatOccupantInfo) => void;
      onSelectionUpdate: (selection: SeatSelection) => void;
      onSelectionRemove: (seatId: number, sourceUserId?: string) => void;
      onInitialState: (selections: SeatSelection[]) => void;
    }
  ) {
    this.userId = userId;
    this.onSeatMapUpdate = callbacks.onSeatMapUpdate;
    this.onSelectionUpdate = callbacks.onSelectionUpdate;
    this.onSelectionRemove = callbacks.onSelectionRemove;
    this.onInitialState = callbacks.onInitialState;
  }

  handleMessage(message: SeatUpdateMessage): void {
    switch (message.type) {
      case 'INITIAL_STATE':
        this.handleInitialState(message);
        break;

      case 'SEAT_UPDATE':
        this.handleSeatUpdate(message);
        break;

      case 'SEAT_SELECTION':
        this.handleSeatSelection(message);
        break;

      case 'SEAT_RELEASED':
        this.handleSeatReleased(message);
        break;

      case 'SEAT_TEMP_RESERVE_RESPONSE':
        this.handleTempReserveResponse(message);
        break;

      case 'SEAT_TEMP_RESERVED':
        this.handleTempReserved(message);
        break;

      case 'SEAT_TEMP_RELEASED':
        this.handleTempReleased(message);
        break;

      case 'SEATS_OCCUPIED':
        this.handleSeatsOccupied(message);
        break;

      case 'SEATS_RELEASED':
        this.handleSeatsReleased(message);
        break;

      case 'SEAT_MAP_UPDATE':
        this.handleSeatMapUpdate(message);
        break;

      case 'SEAT_RESERVED':
        this.handleSeatReserved(message);
        break;

      case 'PONG':
        break;

      default:
        break;
    }
  }

  private handleInitialState(message: SeatUpdateMessage): void {
    // NUEVO: Formato oficial del backend — seatMap completo con estados actualizados
    if (message.seatMap && message.seatMap.length > 0) {
      message.seatMap.forEach((seat) => {
        if (seat.id) {
          const statusUpper = (seat.status || 'AVAILABLE').toUpperCase();
          // Proteger asientos vendidos/ocupados
          const confirmedStatuses = ['SOLD', 'CONFIRMED', 'OCCUPIED'];
          if (confirmedStatuses.includes(statusUpper)) {
            this.confirmedSeats.add(seat.id);
          }
          // Actualizar el estado del asiento en el mapa local
          this.onSeatMapUpdate(seat.id, seat.status, seat.occupant);

          // Si el asiento está marcado como SEAT_SELECTION por otro usuario,
          // agregarlo a las selecciones activas
          if (statusUpper === 'SEAT_SELECTION') {
            // No sabemos el userId exacto del otro vendedor desde seatMap,
            // así que no lo agregamos a activeSelections desde aquí.
            // El backend debería enviar selecctionSeats para eso.
          }
        }
      });
    }

    // Procesar selecciones temporales usando el formato legacy selecctionSeats
    if (message.selecctionSeats && message.selecctionSeats.length > 0) {
      const initialSelections: SeatSelection[] = message.selecctionSeats
        .filter((selection: SelectionSeat) => {
          //  CORRECCIÓN: Filtrar por userId base
          const selectionBaseUserId = selection.userId.split('-company-')[0];
          return selectionBaseUserId !== this.userId;
        })
        .map((selection: SelectionSeat) => ({
          seatId: selection.seatId,
          userId: selection.userId,
          userName: selection.userName,
          timestamp: selection.timestamp,
          type: 'temporary'
        }));

      if (initialSelections.length > 0) {
        this.onInitialState(initialSelections);
      }
    }

    // Procesar asientos ocupados/vendidos usando el formato legacy occupiedSeats
    if (message.occupiedSeats && message.occupiedSeats.length > 0) {
      message.occupiedSeats.forEach((occupiedSeat: OccupiedSeat) => {
        if (occupiedSeat.seatId) {
          // Agregar al conjunto de asientos confirmados
          this.confirmedSeats.add(occupiedSeat.seatId);
          // Extraer occupant si existe en el payload
          const occupant = message.occupants?.[String(occupiedSeat.seatId)];
          // Actualizar el estado del asiento a CONFIRMED (rojo) para asientos vendidos
          this.onSeatMapUpdate(occupiedSeat.seatId, 'CONFIRMED', occupant);
        }
      });
    }

    // Mantener compatibilidad con el formato anterior (seats) por si acaso
    if (message.seats && (!message.selecctionSeats || message.selecctionSeats.length === 0)) {
      const initialSelections: SeatSelection[] = message.seats
        .filter(selection => {
          // CORRECCIÓN: Filtrar por userId base
          const selectionBaseUserId = selection.userId?.split('-company-')[0] || '';
          return selectionBaseUserId !== this.userId;
        })
        .map(selection => ({
          seatId: selection.seatId,
          userId: selection.userId!,
          userName: selection.userName!,
          timestamp: message.timestamp,
          type: 'temporary'
        }));

      if (initialSelections.length > 0) {
        this.onInitialState(initialSelections);
      }
    }
  }

  private handleSeatUpdate(message: SeatUpdateMessage): void {
    if (message.seatId !== undefined && message.status) {
      // Si el asiento esta vendido/confirmado, agregarlo a confirmedSeats
      // para protegerlo de ser liberado accidentalmente por otros eventos
      const confirmedStatuses = ['SOLD', 'CONFIRMED', 'OCCUPIED'];
      if (confirmedStatuses.includes(message.status.toUpperCase())) {
        this.confirmedSeats.add(message.seatId);
      }

      this.onSeatMapUpdate(message.seatId, message.status);
      this.onSelectionRemove(message.seatId);
    }
  }

  private handleSeatSelection(message: SeatUpdateMessage): void {
    // Comparar userId base
    const messageBaseUserId = message.userId?.split('-company-')[0] || '';
    const isFromDifferentUser = messageBaseUserId !== this.userId;

    if (isFromDifferentUser && message.seatId !== undefined) {
      const selection: SeatSelection = {
        seatId: message.seatId,
        userId: message.userId!,
        userName: message.userName!,
        timestamp: message.timestamp,
        type: 'temporary'
      };

      this.onSelectionUpdate(selection);
    }
  }

  private handleSeatReleased(message: SeatUpdateMessage): void {
    if (message.seatId !== undefined) {
      // No liberar asientos que han sido vendidos definitivamente
      if (this.confirmedSeats.has(message.seatId)) {
        return;
      }

      // Procesar liberaciones, pasando el sourceUserId para validación
      this.onSelectionRemove(message.seatId, message.userId);
    }
  }

  private handleTempReserveResponse(message: SeatUpdateMessage): void {
    if (message.seatId !== undefined) {
      if (!message.success) {
        this.showReserveError(message);
      }
    }
  }

  private handleTempReserved(message: SeatUpdateMessage): void {
    const isRepresentativeReservation = message.reservationType === 'REPRESENTATIVE_TEMP_RESERVATION' ||
                                       message.reservationType === 'representative' ||
                                       (message as any).reservationCategory === 'representative';

    // Extraer userId base para comparar correctamente
    // Los representantes tienen userId como "user123-company-session-rep-0", 
    // necesitamos comparar solo el userId base "user123"
    const messageBaseUserId = message.userId?.split('-company-')[0] || '';
    const isFromDifferentUser = messageBaseUserId !== this.userId;

    // Solo agregar si es de un usuario diferente
    const shouldAddSelection = isFromDifferentUser;

    if (shouldAddSelection && message.seatId !== undefined) {
      const expiresAt = new Date(Date.now() + (message.ttl || 1800) * 1000).toISOString();

      const selection: SeatSelection = {
        seatId: message.seatId,
        userId: message.userId!,
        userName: message.userName!,
        timestamp: message.timestamp,
        type: isRepresentativeReservation ? 'representative' : 'temp_reserved',
        ttl: message.ttl,
        expiresAt: expiresAt,
        companyName: message.companyName,
        representativeName: message.representativeName,
        representativeIndex: message.representativeIndex
      };

      this.onSelectionUpdate(selection);
    }
  }

  private handleTempReleased(message: SeatUpdateMessage): void {
    // Procesar liberaciones temporales
    if (message.seatId !== undefined) {
      // No liberar asientos que han sido vendidos definitivamente
      if (this.confirmedSeats.has(message.seatId)) {
        return;
      }

      // Procesar liberación pasando el sourceUserId para validación
      this.onSelectionRemove(message.seatId, message.userId);
    }
  }

  private handleSeatsOccupied(message: SeatUpdateMessage): void {
    // Marcar los asientos como vendidos definitivamente (CONFIRMED)
    if (message.seatIds && Array.isArray(message.seatIds)) {
      message.seatIds.forEach((seatId: number) => {
        // Agregar al conjunto de asientos confirmados
        this.confirmedSeats.add(seatId);
        // Extraer occupant del payload si existe (indexado por seatId como string)
        const occupant = message.occupants?.[String(seatId)];
        // Actualizar el estado del asiento a CONFIRMED (rojo) + datos del pasajero
        this.onSeatMapUpdate(seatId, 'CONFIRMED', occupant);
        // Remover cualquier seleccion temporal de este asiento
        this.onSelectionRemove(seatId);
      });
    }
  }

  private handleSeatMapUpdate(message: SeatUpdateMessage): void {
    // Procesar actualizacion masiva del mapa de asientos
    // El backend envia esto despues de una venta para sincronizar el estado
    if (message.seats && Array.isArray(message.seats)) {
      message.seats.forEach((seat) => {
        if (seat.seatId && seat.status) {
          // Si el asiento esta vendido/ocupado, agregarlo a confirmedSeats
          const confirmedStatuses = ['SOLD', 'CONFIRMED', 'OCCUPIED'];
          if (confirmedStatuses.includes(seat.status.toUpperCase())) {
            this.confirmedSeats.add(seat.seatId);
          }
          this.onSeatMapUpdate(seat.seatId, seat.status);
          this.onSelectionRemove(seat.seatId);
        }
      });
    }

    // Tambien puede venir con seatId individual
    if (message.seatId !== undefined && message.status) {
      const confirmedStatuses = ['SOLD', 'CONFIRMED', 'OCCUPIED'];
      if (confirmedStatuses.includes(message.status.toUpperCase())) {
        this.confirmedSeats.add(message.seatId);
      }
      this.onSeatMapUpdate(message.seatId, message.status);
      this.onSelectionRemove(message.seatId);
    }
  }

  private handleSeatsReleased(message: SeatUpdateMessage): void {
    // Procesar liberación masiva de asientos (anulación, timeout, cancelación)
    // Payload: { type: 'SEATS_RELEASED', tripId, seatIds, reason, timestamp }
    if (message.seatIds && Array.isArray(message.seatIds)) {
      message.seatIds.forEach((seatId: number) => {
        // Remover de asientos confirmados si estaba vendido
        this.confirmedSeats.delete(seatId);
        // Actualizar estado a AVAILABLE
        this.onSeatMapUpdate(seatId, 'AVAILABLE');
        // Remover cualquier selección temporal de este asiento
        this.onSelectionRemove(seatId);
      });
    }
  }

  private handleSeatReserved(message: SeatUpdateMessage): void {
    // Procesar reserva confirmada en tiempo real
    // Payload según backend: { type: 'SEAT_RESERVED', tripId, seatTypeId, reservationId, customerId, quantity, seatId, seatNumber, timestamp }
    if (message.seatId !== undefined) {
      this.onSeatMapUpdate(message.seatId, 'RESERVED');
      this.onSelectionRemove(message.seatId);
    }
  }

  private showReserveError(message: SeatUpdateMessage): void {
    const errorMessage = message.error || 'Este asiento ya no está disponible';

    setTimeout(() => {
      import('@/utils/sileo-toast').then(({ toast }) => {
        toast.error(`Asiento ${message.seatId}: ${errorMessage}`, {
          position: 'top-right',
          autoClose: 4000,
        });
      }).catch(() => {
        // Silenciar error de importación
      });
    }, 50);
  }
}

