    COMPLETED: { label: 'Completado', className: 'bg-dm-bg-secondary text-dm-text-secondary' },
    CANCELLED: { label: 'Cancelado', className: 'bg-red-50 dark:bg-red-950/30 text-red-700 dark:text-red-300' },
