          <h3 className="text-[18px] font-medium text-dm-text-primary mb-2">
            Error al cargar los manifiestos
          </h3>
          <p className="text-[14px] text-dm-text-muted max-w-md mx-auto mb-4">
            El servidor no puede procesar la solicitud debido a un problema de configuración en la API.
          </p>
        </div>
      ) : tripGroups.length === 0 ? (
        <div className="bg-dm-bg-primary rounded-2xl border border-dm-border-primary p-12 text-center">
          <div className="w-16 h-16 bg-dm-bg-secondary rounded-2xl flex items-center justify-center mx-auto mb-5">
            <Ship className="w-8 h-8 text-dm-text-muted" strokeWidth={1.5} />
          </div>
          <h3 className="text-[18px] font-medium text-dm-text-primary mb-2">
            No hay viajes programados
          </h3>
          <p className="text-[14px] text-dm-text-muted max-w-sm mx-auto">
            No se encontraron viajes para{' '}
            <span className="font-medium text-dm-text-secondary">{formatDateLabel(selectedDate)}</span>.
            <br />
            Selecciona otra fecha o verifica la programación.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {tripGroups.map((trip) => (
            <TripManifestCard
              key={trip.id}
              trip={trip}
              isGenerating={isGenerating}
              onGenerate={handleGenerateManifest}
              onDownloadPDF={handleDownloadPDF}
              onNavigateToTrip={navigateToTrip}
            />
          ))}
        </div>
      )}
    </div>
  );
};

import api from '../../../config/api';
import { 
  Manifest,
  ManifestFormData, 
  ManifestResponse,
  Trip,
  DailyManifestViewResponse
} from '../types/manifest.types';

export const manifestService = {
  // Función helper para parsear fechas de diferentes formatos
  parseDate(dateString: string | null | undefined): Date | null {
    if (!dateString) return null;

    try {
      // Intentar parsear directamente
      const date = new Date(dateString);
      if (!isNaN(date.getTime())) {
        return date;
      }

      // Si falla, intentar con diferentes formatos
      // Formato ISO sin Z
      if (dateString.includes('T') && !dateString.includes('Z')) {
        return new Date(dateString + 'Z');
      }

      return null;
    } catch (error) {
      return null;
    }
  },
  // Función helper para enriquecer manifiestos con información del usuario
  async enrichManifestsWithUserData(manifests: Manifest[]): Promise<Manifest[]> {
    // Simplificar: usar solo la información ya disponible en el manifiesto
    // sin hacer llamadas adicionales a la API de usuarios
    return manifests.map((manifest) => {
      // Si ya tiene información del usuario, mantenerla
      if (manifest.generated_by_user) return manifest;

      // Si no tiene información del usuario pero tiene generated_by_name, crear un objeto básico
      if (manifest.generated_by_name) {
        return {
          ...manifest,
          generated_by_user: {
            id: manifest.generated_by,
            full_name: manifest.generated_by_name,
            email: '',
            role_id: 0,
            is_active: true,
            created_at: manifest.created_at,
            updated_at: manifest.updated_at,
            first_name: '',
            company_id: 0
          } as any
        };
      }

      // Si no tiene ninguna información, devolver el manifiesto sin cambios
      return manifest;
    });
  },
  // Obtener manifiestos por sucursal
  getManifestsByBranchOffice: async (
    branchOfficeId: number,
    filters?: {
      status?: string;
      date_from?: string;
      date_to?: string;
      skip?: number;
      limit?: number;
    }
  ): Promise<Manifest[]> => {
    try {
      const params: Record<string, any> = {
        skip: filters?.skip || 0,
        limit: filters?.limit || 100,
        ...(filters?.status && { status: filters.status }),
        ...(filters?.date_from && { date_from: filters.date_from }),
        ...(filters?.date_to && { date_to: filters.date_to }),
      };

      const response = await api.get(`/dispatch/manifests/by-branch-office/${branchOfficeId}`, { params });
      const manifests = response.data || [];
      // Enriquecer con información del usuario
      return await manifestService.enrichManifestsWithUserData(manifests);
    } catch (error: any) {
      console.error('Error fetching manifests by branch office:', error);
      throw new Error(
        error.response?.data?.message || 
        error.response?.data?.detail || 
        'Error al obtener los manifiestos de la sucursal'
      );
    }
  },

  // Vista diaria unificada: viajes + manifiestos ya agrupados por sucursal y fecha
  getDailyManifestView: async (
    branchOfficeId: number,
    date: string
  ): Promise<DailyManifestViewResponse> => {
    try {
      const response = await api.get('/dispatch/manifests/daily-view', {
        params: {
          branch_office_id: branchOfficeId,
          date,
        },
      });
      return response.data;
    } catch (error: any) {
      console.error('Error fetching daily manifest view:', error);
      // Loguear el cuerpo completo del error para diagnóstico (especialmente útil para 422 de FastAPI)
      if (error.response?.data) {
        console.error('Detalle del error 422:', JSON.stringify(error.response.data, null, 2));
      }
      throw new Error(
        error.response?.data?.message ||
        error.response?.data?.detail ||
        'Error al obtener la vista diaria de manifiestos'
      );
    }
  },

  // Obtener manifiestos por trip_id
  getManifestsByTripId: async (tripId: number): Promise<Manifest[]> => {
    // Endpoint problemático - devolver array vacío para evitar errores
    console.debug(`Endpoint by-trip/${tripId} deshabilitado - devolviendo array vacío`);
    return [];
  },

  // Obtener todos los manifiestos
  getManifests: async (): Promise<Manifest[]> => {
    try {
      const response = await api.get('/dispatch/manifests/');
      const manifests = response.data.results || response.data;
      // Enriquecer con información del usuario
      return await manifestService.enrichManifestsWithUserData(manifests);
    } catch (error: any) {
      console.error('Error fetching manifests:', error);
      throw new Error(
        error.response?.data?.message || 
        error.response?.data?.detail || 
        'Error al obtener los manifiestos'
      );
    }
  },

  // Obtener un manifiesto por ID
  getManifestById: async (id: number): Promise<Manifest> => {
    try {
      // Intentar GET con slash. Si el servidor responde 307/redirect a http o falla,
      // reintentar sin slash final. Usamos la cabecera X-Skip-Auth-Redirect para que
      // el interceptor no fuerce el logout en caso de 401 durante el diagnóstico.
      // Intentar SIN barra final primero para evitar redirecciones que rompen el preflight CORS
      let manifest: Manifest;
      try {
        const response = await api.get(`/dispatch/manifests/${id}`, { headers: { 'X-Skip-Auth-Redirect': '1' } });
        manifest = response.data;
      } catch (err: any) {
        // Si falla, reintentar con slash final como fallback
        try {
          const response2 = await api.get(`/dispatch/manifests/${id}/`, { headers: { 'X-Skip-Auth-Redirect': '1' } });
          manifest = response2.data;
        } catch (err2: any) {
          throw err2;
        }
      }

      // Enriquecer con información del usuario
      const enrichedManifests = await manifestService.enrichManifestsWithUserData([manifest]);
      return enrichedManifests[0];
    } catch (error: any) {
      console.error('Error fetching manifest:', error);
      throw new Error(
        error.response?.data?.message || 
        error.response?.data?.detail || 
        'Error al obtener el manifiesto'
      );
    }
  },

  // Crear un nuevo manifiesto
  createManifest: async (data: ManifestFormData): Promise<ManifestResponse> => {
    try {
      // El endpoint de "regenerate" en el backend crea o regenera el manifiesto.
      // Usamos ese endpoint en lugar del POST original para unificar comportamiento.
      const response = await api.put('/dispatch/manifests/regenerate', data);
      // Si la respuesta no incluye los items completos, obtener el manifiesto completo
      let manifestData = response.data;
      if (!manifestData.items || manifestData.items.length === 0) {
        manifestData = await manifestService.getManifestById(response.data.id);
      } else {
        // Enriquecer con información del usuario
        const enrichedManifests = await manifestService.enrichManifestsWithUserData([manifestData]);
        manifestData = enrichedManifests[0];
      }
      return {
        success: true,
        data: manifestData,
        message: 'Manifiesto creado/regenerado exitosamente'
      };
    } catch (error: any) {
      // Manejo específico de errores de validación (422)
      if (error.response?.status === 422) {
        const validationErrors = error.response.data?.detail || [];
        const errorMessages = validationErrors.map((err: any) => err.msg).join(', ');
        throw new Error(errorMessages || 'Error de validación en los datos del manifiesto');
      }
      // Manejo específico de conflicto (409) - mantener el error original para que createOrRegenerateManifest pueda detectarlo
      if (error.response?.status === 409) {
        throw error; // Preservar el error original con status 409 (compatibilidad)
      }
      throw new Error(
        error.response?.data?.message || 
        error.response?.data?.detail ||
        error.response?.data?.non_field_errors?.[0] ||
        'Error al crear el manifiesto'
      );
    }
  },

  // Regenerar un manifiesto existente
  regenerateManifest: async (data: ManifestFormData): Promise<ManifestResponse> => {
    try {
      // Usar la API de regeneración según la documentación - SIN barra final para evitar CORS
      const response = await api.put('/dispatch/manifests/regenerate', data);
      // Si la respuesta no incluye los items completos, obtener el manifiesto completo
      let manifestData = response.data;
      if (!manifestData.items || manifestData.items.length === 0) {
        manifestData = await manifestService.getManifestById(response.data.id);
      } else {
        // Enriquecer con información del usuario
        const enrichedManifests = await manifestService.enrichManifestsWithUserData([manifestData]);
        manifestData = enrichedManifests[0];
      }
      return {
        success: true,
        data: manifestData,
        message: 'Manifiesto regenerado exitosamente'
      };
    } catch (error: any) {
      console.error('Error regenerating manifest:', error);

      // Manejo específico de errores de validación (422)
      if (error.response?.status === 422) {
        const validationErrors = error.response.data?.detail || [];
        const errorMessages = validationErrors.map((err: any) => err.msg).join(', ');
        throw new Error(errorMessages || 'Error de validación en los datos del manifiesto');
      }
      throw new Error(
        error.response?.data?.message || 
        error.response?.data?.detail ||
        error.response?.data?.non_field_errors?.[0] ||
        'Error al regenerar el manifiesto'
      );
    }
  },

  // Crear o regenerar manifiesto automáticamente
  createOrRegenerateManifest: async (data: ManifestFormData): Promise<ManifestResponse> => {
    try {
      // Primero intentamos crear un manifiesto nuevo
      const result = await manifestService.createManifest(data);
      return {
        ...result,
        isRegeneration: false
      };
    } catch (error: any) {
      // Si el error indica que ya existe un manifiesto (status 409), intentamos regenerarlo
      if (error.response?.status === 409) {
        try {
          const result = await manifestService.regenerateManifest(data);
          return {
            ...result,
            isRegeneration: true
          };
        } catch (regenerateError: any) {
          console.error('Error en regeneración:', regenerateError);
          throw new Error(
            regenerateError.response?.data?.message || 
            regenerateError.response?.data?.detail || 
            regenerateError.message ||
            'Error al regenerar el manifiesto'
          );
        }
      }
      // Si es otro tipo de error, lo propagamos
      throw error;
    }
  },

  // Verificar si existe un manifiesto para un viaje y tipo específico
  checkExistingManifest: async (tripId: number, manifestType: 'PASSENGER' | 'CARGO'): Promise<Manifest | null> => {
    try {
      const response = await api.get(`/dispatch/manifests/check`, {
        params: {
          trip_id: tripId,
          manifest_type: manifestType
        }
      });
      return response.data || null;
    } catch (error: any) {
      // Si no encuentra el manifiesto, devuelve null
      if (error.response?.status === 404) {
        return null;
      }
      console.error('Error checking existing manifest:', error);
      throw new Error('Error al verificar manifiesto existente');
    }
  },

  // Obtener viajes disponibles para manifiestos
  getAvailableTrips: async (): Promise<Trip[]> => {
    try {
      // Obtener viajes que están programados pero no tienen manifiesto generado
      const response = await api.get('/trips/', {
        params: {
          status: 'SCHEDULED',
          has_manifest: false
        }
      });
      return response.data.results || response.data;
    } catch (error: any) {
      console.error('Error fetching available trips:', error);
      throw new Error(
        error.response?.data?.message || 
        error.response?.data?.detail || 
        'Error al obtener los viajes disponibles'
      );
    }
  },

  // Subir PDF del manifiesto al backend
  uploadManifestPDF: async (manifestId: number, pdfFile: File, pdfType: 'a4' | 'ticket'): Promise<void> => {
    try {
      const formData = new FormData();
      formData.append('pdf_file', pdfFile);
      formData.append('pdf_type', pdfType);

      await api.post(`/dispatch/manifests/${manifestId}/upload-pdf`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });
    } catch (error: any) {
      console.error('Error uploading manifest PDF:', error);
      throw new Error(
        error.response?.data?.message || 
        error.response?.data?.detail || 
        'Error al subir el PDF del manifiesto'
      );
    }
  },

  // Generar PDF del manifiesto
  generateManifestPDF: async (manifestId: number): Promise<Blob> => {
    try {
      const response = await api.get(`/dispatch/manifests/${manifestId}/pdf/`, {
        responseType: 'blob'
      });
      return response.data;
    } catch (error: any) {
      console.error('Error generating manifest PDF:', error);
      throw new Error(
        error.response?.data?.message || 
        'Error al generar el PDF del manifiesto'
      );
    }
  },

  // Cancelar un manifiesto
  cancelManifest: async (manifestId: number, reason?: string): Promise<void> => {
    try {
      await api.patch(`/dispatch/manifests/${manifestId}/cancel/`, {
        reason: reason
      });
    } catch (error: any) {
      console.error('Error cancelling manifest:', error);
      throw new Error(
        error.response?.data?.message || 
        error.response?.data?.detail || 
        'Error al cancelar el manifiesto'
      );
    }
  },

  // Obtener estadísticas de manifiestos
  getManifestStats: async (): Promise<{
    total: number;
    generated: number;
    draft: number;
    cancelled: number;
    passenger_manifests: number;
    cargo_manifests: number;
  }> => {
    try {
      const response = await api.get('/dispatch/manifests/stats/');
      return response.data;
    } catch (error: any) {
      console.error('Error fetching manifest stats:', error);
      throw new Error(
        error.response?.data?.message || 
        'Error al obtener las estadísticas'
      );
    }
  },

  // Validar si se puede generar manifiesto de carga para un viaje específico
  validateCargoManifest: async (tripId: number): Promise<{ canGenerate: boolean; message: string; itemCount?: number }> => {
    // Estrategia optimizada: No hacer validaciones previas costosas
    // En su lugar, permitir la generación y que el error real se maneje en createOrRegenerateManifest
    // Esto evita errores 404/422 innecesarios en la consola

    try {
      // Solo verificar si existe un manifiesto previo sin generar errores
      // Si existe, sabemos que hay datos
      const existingManifests = await manifestService.getManifestsByTripId(tripId);

      const cargoManifest = existingManifests.find(m => m.manifest_type === 'CARGO');
      if (cargoManifest) {
        return {
          canGenerate: true,
          message: `Manifiesto de carga encontrado con ${cargoManifest.items?.length || 0} elementos`,
          itemCount: cargoManifest.items?.length || 0
        };
      }

      // Si no hay manifiesto existente, permitir el intento
      // La validación real se hará al crear el manifiesto
      return {
        canGenerate: true,
        message: 'Listo para generar manifiesto de carga'
      };

    } catch (error: any) {
      // Si hay error obteniendo manifiestos existentes, es probable que sea el primer intento
      // Permitir la generación y que el error se maneje correctamente en el flujo principal

      if (error.message === 'ENDPOINT_NOT_AVAILABLE') {
        return {
          canGenerate: true,
          message: 'Sistema listo para generar manifiesto'
        };
      }

      // Para cualquier otro error, ser optimista
      // El usuario verá el error real al intentar generar
      return {
        canGenerate: true,
        message: 'Validación completada - listo para generar'
      };
    }
  }
};

import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { Manifest } from "../types/manifest.types";
import { drawLogoInPdf, drawLogoPlaceholder } from "../../../utils/pdfLogo";
import { getDocumentCompanyInfo } from "../../../utils/documentCompanyInfo";

export const generatePassengerManifestPDF = async (
  manifestData: Manifest
): Promise<{ pdf: jsPDF; blob: Blob }> => {
  const rawManifest = manifestData as any;
  const passengerItems = Array.isArray(rawManifest.data) && rawManifest.data.length > 0
    ? rawManifest.data
    : (manifestData.items || []);
  const cargoItems = manifestData.items && manifestData.items.length > 0
    ? manifestData.items
    : (Array.isArray(rawManifest.data) ? rawManifest.data : []);

  // OrientaciÃ³n: horizontal para ambos tipos (pasajeros y carga)
  const orientation = "l"; // Siempre horizontal
  const pdf = new jsPDF(orientation, "mm", "a4");
  const pageWidth = pdf.internal.pageSize.width;
  // Margen optimizado de 6mm para ambos tipos para mejor legibilidad
  const margin = 6;
  let currentY = 20;
  const company = await getDocumentCompanyInfo();

  // NUEVO HEADER SEGÃšN DISEÃ‘O DEL CLIENTE
  // Lado izquierdo: Logo y datos de empresa
  const logoX = margin;
  const logoY = currentY;
  const logoW = 45;
  const logoH = 20;

  try {
    if (company.logoUrl) {
      const hasLogo = await drawLogoInPdf(pdf, company.logoUrl, {
        x: logoX,
        y: logoY,
        width: logoW,
        height: logoH,
      });

      if (!hasLogo) {
        drawLogoPlaceholder(pdf, logoX, logoY, logoW, logoH);
      }
    } else {
      drawLogoPlaceholder(pdf, logoX, logoY, logoW, logoH);
    }
  } catch (e) {
    drawLogoPlaceholder(pdf, logoX, logoY, logoW, logoH);
  }

  // Info empresa (al lado del logo)
  const infoX = logoX + logoW + 5;
  const maxInfoWidth = pageWidth - infoX - 75; // Dejar mÃ¡s espacio para el recuadro

  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(10);
  pdf.text(company.businessName, infoX, logoY + 4);

  pdf.setFont("helvetica", "normal");
  pdf.setFontSize(8);
  // Dividir la direcciÃ³n en lÃ­neas si es muy larga
  const addressLines = pdf.splitTextToSize(company.address, maxInfoWidth);
  let addressY = logoY + 8;
  for (let i = 0; i < Math.min(addressLines.length, 2); i++) {
    pdf.text(addressLines[i], infoX, addressY);
    addressY += 4;
  }

  pdf.text(`Tel: ${company.phone}`, infoX, addressY);
  pdf.text(company.email, infoX, addressY + 4);

  // Lado derecho: Recuadro con RUC, TIPO DE DOC, CORRELATIVO
  const boxW = 50;
  const boxH = 25;
  const boxX = pageWidth - margin - boxW;
  const boxY = logoY;

  pdf.setDrawColor(0, 0, 0);
  pdf.setLineWidth(0.5);
  pdf.rect(boxX, boxY, boxW, boxH);

  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(9);
  pdf.text(company.ruc, boxX + boxW / 2, boxY + 5, { align: "center" });

  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(9);
  const docType =
    manifestData.manifest_type === "CARGO"
      ? "MANIFIESTO DE CARGA"
      : "MANIFIESTO DE PASAJEROS";
  pdf.text(docType, boxX + boxW / 2, boxY + 13, { align: "center" });

  pdf.setFont("helvetica", "normal");
  pdf.setFontSize(8);
  pdf.text(manifestData.manifest_number, boxX + boxW / 2, boxY + 21, {
    align: "center",
  });

  currentY += Math.max(logoH, boxH) + 8;

  // InformaciÃ³n de viaje en la parte inferior del header
  const departureDateTime = manifestData.departure_datetime || rawManifest.trip_info?.departure_datetime;
  const depInfo = departureDateTime
    ? new Date(departureDateTime)
    : null;
  const fechaSalida = depInfo ? depInfo.toLocaleDateString("es-PE") : "N/A";
  const horaSalida = depInfo
    ? depInfo.toLocaleTimeString("es-PE", {
      hour: "2-digit",
      minute: "2-digit",
    })
    : "N/A";

  // TamaÃ±o de fuente optimizado: 10 para ambos tipos
  const infoFontSize = 10;
  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(infoFontSize);

  // DiseÃ±o de 3 columnas para ambos tipos (pasajeros y carga)
  if (manifestData.manifest_type === "PASSENGER") {
    // Calcular anchos de columna para mejor distribuciÃ³n en horizontal
    const col1X = margin;
    const col2X = margin + 95;
    const col3X = margin + 190;

    // Primera fila
    pdf.setFont("helvetica", "bold");
    pdf.text("FECHA SALIDA:", col1X, currentY);
    pdf.setFont("helvetica", "normal");
    pdf.text(fechaSalida, col1X + 32, currentY);

    pdf.setFont("helvetica", "bold");
    pdf.text("ORIGEN:", col2X, currentY);
    pdf.setFont("helvetica", "normal");
    const originPort = manifestData.origin_port_name || rawManifest.trip_info?.origin_port_name || "N/A";
    pdf.text(originPort, col2X + 20, currentY);

    pdf.setFont("helvetica", "bold");
    pdf.text("PLACA:", col3X, currentY);
    pdf.setFont("helvetica", "normal");
    const vesselPlate = manifestData.vessel_registration_number || rawManifest.trip_info?.vehicle_license_plate || "N/A";
    pdf.text(vesselPlate, col3X + 17, currentY);

    currentY += 6;

    // Segunda fila
    pdf.setFont("helvetica", "bold");
    pdf.text("HORA DE SALIDA:", col1X, currentY);
    pdf.setFont("helvetica", "normal");
    pdf.text(horaSalida, col1X + 35, currentY);

    pdf.setFont("helvetica", "bold");
    pdf.text("DESTINO:", col2X, currentY);
    pdf.setFont("helvetica", "normal");
    const destinationPort = manifestData.destination_port_name || rawManifest.trip_info?.destination_port_name || "N/A";
    pdf.text(destinationPort, col2X + 22, currentY);

    const vehicleName = manifestData.trip_info?.vehicle_model || rawManifest.trip_info?.vehicle_model || "N/A";
    pdf.setFont("helvetica", "bold");
    pdf.text("Embarcacion:", col3X - 5, currentY);
    pdf.setFont("helvetica", "normal");
    pdf.text(vehicleName, col3X + 23, currentY);

    currentY += 6;

    // Tercera fila - Total
    pdf.setFont("helvetica", "bold");
    const totalPassengers = manifestData.total_passengers || passengerItems.length;
    pdf.text(`Total de Pasajeros: ${totalPassengers}`, col1X, currentY);

    currentY += 10;
  } else {
    // Diseño de 3 columnas para carga (igual que pasajeros)
    const col1X = margin;
    const col2X = margin + 95;
    const col3X = margin + 190;

    // Primera fila
    pdf.setFont("helvetica", "bold");
    pdf.text("FECHA SALIDA:", col1X, currentY);
    pdf.setFont("helvetica", "normal");
    pdf.text(fechaSalida, col1X + 32, currentY);

    pdf.setFont("helvetica", "bold");
    pdf.text("ORIGEN:", col2X, currentY);
    pdf.setFont("helvetica", "normal");
    const originPort = manifestData.origin_port_name || rawManifest.trip_info?.origin_port_name || "N/A";
    pdf.text(originPort, col2X + 20, currentY);

    pdf.setFont("helvetica", "bold");
    pdf.text("PLACA:", col3X, currentY);
    pdf.setFont("helvetica", "normal");
    const vesselPlate = manifestData.vessel_registration_number || rawManifest.trip_info?.vehicle_license_plate || "N/A";
    pdf.text(vesselPlate, col3X + 17, currentY);

    currentY += 6;

    // Segunda fila
    pdf.setFont("helvetica", "bold");
    pdf.text("HORA DE SALIDA:", col1X, currentY);
    pdf.setFont("helvetica", "normal");
    pdf.text(horaSalida, col1X + 35, currentY);

    pdf.setFont("helvetica", "bold");
    pdf.text("DESTINO:", col2X, currentY);
    pdf.setFont("helvetica", "normal");
    const destinationPort = manifestData.destination_port_name || rawManifest.trip_info?.destination_port_name || "N/A";
    pdf.text(destinationPort, col2X + 22, currentY);

    const vehicleName = manifestData.trip_info?.vehicle_model || rawManifest.trip_info?.vehicle_model || "N/A";
    pdf.setFont("helvetica", "bold");
    pdf.text("Embarcacion:", col3X - 5, currentY);
    pdf.setFont("helvetica", "normal");
    pdf.text(vehicleName, col3X + 23, currentY);

    currentY += 6;

    // Tercera fila - Total
    pdf.setFont("helvetica", "bold");
    const rawTotalCargo = manifestData.total_cargo_weight_kg;
    const totalCargo = rawTotalCargo && !isNaN(Number(rawTotalCargo))
      ? Math.round(Number(rawTotalCargo))
      : (cargoItems.length || 0);
    pdf.text(`Total de carga: ${totalCargo}`, col1X, currentY);

    currentY += 10;
  }

  // TABLAS
  if (manifestData.manifest_type === "CARGO") {
    // Reutilizar la lÃ³gica existente para cargo (agrupado o plano)
    const grouped = (manifestData as any).cargo_grouped_by_stops;
    if (grouped && Array.isArray(grouped.groups) && grouped.groups.length > 0) {
      let globalItemNumber = 1; // NumeraciÃ³n continua entre grupos
      const pageHeight = pdf.internal.pageSize.height;
      const bottomMargin = 20; // Margen inferior mÃ­nimo
      const minSpaceForGroupHeader = 50; // Espacio mÃ­nimo necesario para tÃ­tulo + al menos 1 fila de tabla

      // Ordenar grupos por disembarking_stop_order ascendente
      const sortedGroups = [...grouped.groups].sort(
        (a: any, b: any) => (a.disembarking_stop_order ?? 0) - (b.disembarking_stop_order ?? 0)
      );

      for (const group of sortedGroups) {
        // Verificar si hay espacio suficiente para el tÃ­tulo del grupo + header de tabla
        // Si no hay espacio, crear nueva pÃ¡gina
        if (currentY + minSpaceForGroupHeader > pageHeight - bottomMargin) {
          pdf.addPage();
          currentY = 20; // Reiniciar posiciÃ³n Y en la nueva pÃ¡gina
        }

        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(10);
        const origin = (group.origin_port_name || "N/A").toString();
        const dest = (group.destination_port_name || "N/A").toString();
        pdf.text(`${origin} - ${dest}`, pageWidth / 2, currentY, {
          align: "center",
        });
        currentY += 8;

        // Ordenar ítems del grupo por parcel_number (ascendente)
        const sortedItems = [...(group.items || [])].sort(
          (a: any, b: any) => (a.parcel_number ?? 0) - (b.parcel_number ?? 0)
        );

        const tableData = sortedItems.map((item: any) => {
          // Formatear contactos: R: (remitente) D: (destinatario) con salto de línea
          let contactos = "";
          const remitentePhone = item.remitente_phone && item.remitente_phone.trim() !== "" ? item.remitente_phone : null;
          const destinatarioPhone = item.destinatario_phone && item.destinatario_phone.trim() !== "" ? item.destinatario_phone : null;

          if (remitentePhone) contactos += `R: ${remitentePhone}`;
          if (destinatarioPhone) {
            if (contactos) contactos += "\n";
            contactos += `D: ${destinatarioPhone}`;
          }
          if (!contactos) contactos = "N/A";

          // Formatear descripción: separar por "-" y agregar asteriscos (jsPDF helvetica no soporta •)
          let formattedDescription = item.cargo_description || "N/A";
          if (formattedDescription !== "N/A" && formattedDescription.includes("-")) {
            const parts = formattedDescription.split("-").map((i: string) => i.trim()).filter((i: string) => i.length > 0);
            if (parts.length > 1) {
              formattedDescription = parts.map((i: string) => `* ${i}`).join("\n");
            }
          }

          return [
            (item.parcel_number ?? item.item_order ?? globalItemNumber++).toString(), // Nro. de la boleta/factura
            formattedDescription,
            item.remitente_nombre || "N/A",
            item.remitente_doc?.replace("1-", "DNI: ") || "N/A",
            item.destinatario_nombre || "N/A",
            item.destinatario_doc?.replace("1-", "DNI: ") || "N/A",
            contactos, // Mostrar telÃ©fonos en formato R: D:
            item.amount ? `S/ ${item.amount.toFixed(2)}` : "N/A",
            item.payment_status === "PAID"
              ? "PAGADO"
              : item.payment_status === "PENDING"
                ? "PENDIENTE"
                : item.payment_status || "N/A",
          ];
        });

        // Anchos optimizados para formato horizontal con mejor legibilidad (sin columna CANTIDAD)
        const initialColWidths = [12, 52, 40, 28, 40, 28, 32, 22, 24];
        const availableWidth = pageWidth - margin * 2;
        let totalTableWidth = initialColWidths.reduce((s, w) => s + w, 0);
        let adjustedColWidths = [...initialColWidths];

        if (totalTableWidth > availableWidth) {
          const scale = availableWidth / totalTableWidth;
          adjustedColWidths = initialColWidths.map((w) => Math.floor(w * scale));
          let sumAdj = adjustedColWidths.reduce((s, w) => s + w, 0);
          let i = adjustedColWidths.length - 1;
          while (sumAdj > availableWidth && i >= 0) {
            const reduceBy = Math.min(sumAdj - availableWidth, 1);
            adjustedColWidths[i] = Math.max(8, adjustedColWidths[i] - reduceBy);
            sumAdj = adjustedColWidths.reduce((s, w) => s + w, 0);
            i -= 1;
          }
          totalTableWidth = adjustedColWidths.reduce((s, w) => s + w, 0);
        }

        // Centrar la tabla
        const leftMargin = (pageWidth - totalTableWidth) / 2;

        const columnStyles: any = {
          0: { halign: "center", cellWidth: adjustedColWidths[0] },
          1: { halign: "left", cellWidth: adjustedColWidths[1] },
          2: { halign: "left", cellWidth: adjustedColWidths[2] },
          3: { halign: "center", cellWidth: adjustedColWidths[3] },
          4: { halign: "left", cellWidth: adjustedColWidths[4] },
          5: { halign: "center", cellWidth: adjustedColWidths[5] },
          6: { halign: "center", cellWidth: adjustedColWidths[6] },
          7: { halign: "center", cellWidth: adjustedColWidths[7] },
          8: { halign: "center", cellWidth: adjustedColWidths[8] },
        };

        autoTable(pdf, {
          startY: currentY,
          head: [
            [
              "N\u00B0",
              "DESCRIPCI\u00D3N",
              "REMITENTE",
              "DOC. REM.",
              "DESTINATARIO",
              "DOC. DEST.",
              "CONTACTO",
              "MONTO",
              "ESTADO",
            ],
          ],
          body: tableData,
          styles: {
            fontSize: 9.5,
            cellPadding: 3,
            halign: "center",
            valign: "middle",
          },
          headStyles: {
            fillColor: [100, 100, 100],
            textColor: 255,
            fontStyle: "bold",
            fontSize: 9.5,
            halign: "center",
            valign: "middle",
          },
          columnStyles,
          margin: { left: leftMargin, right: leftMargin },
          tableWidth: "auto",
          theme: "grid",
        });

        const finalY = (pdf as any).lastAutoTable?.finalY || currentY + 8;
        const groupItemCount = group.items?.length || 0; // Contar elementos en lugar de sumar pesos
        pdf.setFont("helvetica", "bold");
        pdf.setFontSize(9);
        pdf.text(`Total: ${groupItemCount}`, margin, finalY + 8); // Mostrar cantidad de elementos
        currentY = finalY + 16;
      }
    } else if (cargoItems && cargoItems.length > 0) {
      const tableData = [...cargoItems]
        .sort((a: any, b: any) => (a.item_order ?? 0) - (b.item_order ?? 0))
        .map((item: any, idx: number) => {
          // Formatear contactos: R: (remitente) D: (destinatario) con salto de línea
          let contactos = "";
          const remitentePhone = item.remitente_phone && item.remitente_phone.trim() !== "" ? item.remitente_phone : null;
          const destinatarioPhone = item.destinatario_phone && item.destinatario_phone.trim() !== "" ? item.destinatario_phone : null;

          if (remitentePhone) contactos += `R: ${remitentePhone}`;
          if (destinatarioPhone) {
            if (contactos) contactos += "\n";
            contactos += `D: ${destinatarioPhone}`;
          }
          if (!contactos) contactos = "N/A";

          // Formatear descripción: separar por "-" y agregar asteriscos (jsPDF helvetica no soporta •)
          let formattedDescription = item.cargo_description || "N/A";
          if (formattedDescription !== "N/A" && formattedDescription.includes("-")) {
            const parts = formattedDescription.split("-").map((i: string) => i.trim()).filter((i: string) => i.length > 0);
            if (parts.length > 1) {
              formattedDescription = parts.map((i: string) => `* ${i}`).join("\n");
            }
          }

          return [
            (item.parcel_number ?? item.item_order ?? idx + 1).toString(), // Nro. de la boleta/factura
            formattedDescription,
            item.remitente_nombre || "N/A",
            item.remitente_doc?.replace("1-", "DNI: ") || "N/A",
            item.destinatario_nombre || "N/A",
            item.destinatario_doc?.replace("1-", "DNI: ") || "N/A",
            contactos, // Mostrar telÃ©fonos en formato R: D:
            item.amount ? `S/ ${item.amount.toFixed(2)}` : "N/A",
            item.payment_status === "PAID"
              ? "PAGADO"
              : item.payment_status === "PENDING"
                ? "PENDIENTE"
                : item.payment_status || "N/A",
          ];
        });

      // Anchos optimizados para formato horizontal con mejor legibilidad (sin columna CANTIDAD)
      const initialColWidths = [12, 52, 40, 28, 40, 28, 32, 22, 24];
      const availableWidth = pageWidth - margin * 2;
      let totalTableWidth = initialColWidths.reduce((s, w) => s + w, 0);
      let adjustedColWidths = [...initialColWidths];

      if (totalTableWidth > availableWidth) {
        const scale = availableWidth / totalTableWidth;
        adjustedColWidths = initialColWidths.map((w) => Math.floor(w * scale));
        let sumAdj = adjustedColWidths.reduce((s, w) => s + w, 0);
        let i = adjustedColWidths.length - 1;
        while (sumAdj > availableWidth && i >= 0) {
          const reduceBy = Math.min(sumAdj - availableWidth, 1);
          adjustedColWidths[i] = Math.max(8, adjustedColWidths[i] - reduceBy);
          sumAdj = adjustedColWidths.reduce((s, w) => s + w, 0);
          i -= 1;
        }
        totalTableWidth = adjustedColWidths.reduce((s, w) => s + w, 0);
      }

      // Centrar la tabla
      const leftMargin = (pageWidth - totalTableWidth) / 2;

      const columnStyles2: any = {
        0: { halign: "center", cellWidth: adjustedColWidths[0] },
        1: { halign: "left", cellWidth: adjustedColWidths[1] },
        2: { halign: "left", cellWidth: adjustedColWidths[2] },
        3: { halign: "center", cellWidth: adjustedColWidths[3] },
        4: { halign: "left", cellWidth: adjustedColWidths[4] },
        5: { halign: "center", cellWidth: adjustedColWidths[5] },
        6: { halign: "center", cellWidth: adjustedColWidths[6] },
        7: { halign: "center", cellWidth: adjustedColWidths[7] },
        8: { halign: "center", cellWidth: adjustedColWidths[8] },
      };

      autoTable(pdf, {
        startY: currentY,
        head: [
          [
            "N\u00B0",
            "DESCRIPCI\u00D3N",
            "REMITENTE",
            "DOC. REM.",
            "DESTINATARIO",
            "DOC. DEST.",
            "CONTACTO",
            "MONTO",
            "ESTADO",
          ],
        ],
        body: tableData,
        styles: {
          fontSize: 9.5,
          cellPadding: 3,
          halign: "center",
          valign: "middle",
        },
        headStyles: {
          fillColor: [100, 100, 100],
          textColor: 255,
          fontStyle: "bold",
          fontSize: 9.5,
          halign: "center",
          valign: "middle",
        },
        columnStyles: columnStyles2,
        margin: { left: leftMargin, right: leftMargin },
        tableWidth: "auto",
        theme: "grid",
      });
    } else {
      pdf.setFont("helvetica", "normal");
      pdf.setFontSize(9);
      pdf.text("No hay registros de carga para mostrar.", margin, currentY);
      currentY += 8;
    }
  } else {
    // PASAJEROS: construir tabla centrada y con estilo similar a carga
    if (passengerItems && passengerItems.length > 0) {
      const tableData = passengerItems
        .sort((a: any, b: any) => a.item_order - b.item_order)
        .map((item: any, idx: number) => {
          const rawSeller =
            item.seller_name ??
            item?.seller?.name ??
            manifestData.generated_by_user?.full_name ??
            manifestData.generated_by_name ??
            manifestData.generated_by;
          const sellerDisplay = rawSeller
            ? String(rawSeller).trim().split(" ")[0]
            : "VENDEDOR";
          const passengerDocType = item.passenger_doc_type || item.document_type;
          const identityLabel =
            passengerDocType === "1"
              ? "DNI"
              : passengerDocType === "2"
                ? "CE"
                : "PAS";
          let nationality = "N/A";
          if (item.passenger_country_name)
            nationality = item.passenger_country_name;
          else if (item.passenger_country_code) {
            nationality =
              item.passenger_country_code === "PE"
                ? "PERÃš"
                : item.passenger_country_code;
          }
          return [
            (idx + 1).toString(),
            item.passenger_name || item.full_name || "N/A",
            `${identityLabel}: ${item.passenger_doc_number || item.document_number || "N/A"}`,
            nationality,
            sellerDisplay,
            item.seat_number || "N/A",
            item.boarding_port_name || item.boarding_port || "N/A",
            item.disembarking_port_name || item.destination_port || "N/A",
            item.passenger_phone || item.phone || "N/A",
          ];
        });

      // Column widths (mm) y centrado
      // Ajuste de anchos optimizado para mejor visualizaciÃ³n de todas las columnas
      const colWidths = [12, 54, 28, 20, 22, 20, 22, 22, 20];
      // Ajustar si la tabla excede el ancho disponible
      const availableWidth = pageWidth - margin * 2;
      let totalTableWidth = colWidths.reduce((s, w) => s + w, 0);
      let adjustedColWidths = [...colWidths];
      if (totalTableWidth > availableWidth) {
        const scale = availableWidth / totalTableWidth;
        adjustedColWidths = colWidths.map((w) => Math.floor(w * scale));
        // corregir redondeo si hace falta
        let sumAdj = adjustedColWidths.reduce((s, w) => s + w, 0);
        let i = adjustedColWidths.length - 1;
        while (sumAdj > availableWidth && i >= 0) {
          const reduceBy = Math.min(sumAdj - availableWidth, 1);
          adjustedColWidths[i] = Math.max(6, adjustedColWidths[i] - reduceBy);
          sumAdj = adjustedColWidths.reduce((s, w) => s + w, 0);
          i -= 1;
        }
        totalTableWidth = adjustedColWidths.reduce((s, w) => s + w, 0);
      } else {
        // Si hay espacio, ampliar la tabla moderadamente (hasta 30%) para buena legibilidad
        // NOTA: permitimos que la tabla quede fuera del margen si es necesario, siempre y cuando estÃ© centrada
        const expansionFactor = 1.30; // hasta +30%
        const desiredWidth = Math.round(totalTableWidth * expansionFactor);
        if (desiredWidth > totalTableWidth) {
          let extra = desiredWidth - totalTableWidth;
          // distribuir extra: favorecer columna 1 (nombres), 5 (asiento) y 3 (nacionalidad)
          const priority = [1, 5, 3, 2, 4, 6, 7, 8, 0];
          let pi = 0;
          while (extra > 0) {
            const col = priority[pi % priority.length];
            adjustedColWidths[col] = adjustedColWidths[col] + 1;
            extra -= 1;
            pi += 1;
          }
          totalTableWidth = adjustedColWidths.reduce((s, w) => s + w, 0);
        }
      }
      // Centrar la tabla incluso si eso significa reducir el leftMargin por debajo del margen habitual
      const leftMargin = (pageWidth - totalTableWidth) / 2;
      const passengerColumnStyles: any = {
        0: { halign: "center", cellWidth: adjustedColWidths[0] },
        1: { halign: "left", cellWidth: adjustedColWidths[1] },
        2: {
          halign: "center",
          cellWidth: adjustedColWidths[2],
          overflow: "ellipsize",
        }, // DOC DE IDENT
        3: { halign: "center", cellWidth: adjustedColWidths[3] }, // NACIONALIDAD
        4: { halign: "center", cellWidth: adjustedColWidths[4] }, // VENDEDOR
        5: { halign: "center", cellWidth: adjustedColWidths[5] }, // ASIENTO (sin overflow para mostrar texto completo)
        6: { halign: "center", cellWidth: adjustedColWidths[6] }, // ORIGEN
        7: { halign: "center", cellWidth: adjustedColWidths[7] }, // DESTINO
        8: { halign: "center", cellWidth: adjustedColWidths[8] }, // TELÉFONO
      };

      autoTable(pdf, {
        startY: currentY,
        head: [
          [
            "N°",
            "APELLIDOS Y NOMBRES",
            "DOC DE IDENT",
            "NACIONALIDAD",
            "VENDEDOR",
            "ASIENTO",
            "ORIGEN",
            "DESTINO",
            "TELÉFONO",
          ],
        ],
        body: tableData,
        theme: "grid",
        headStyles: {
          fillColor: [100, 100, 100],
          textColor: 255,
          fontSize: 9.5,
          fontStyle: "bold",
          halign: "center",
          valign: "middle",
        },
        bodyStyles: { fontSize: 9.5, cellPadding: 3, valign: "middle" },
        columnStyles: passengerColumnStyles,
        margin: { left: leftMargin, right: leftMargin },
        tableWidth: "auto",
        styles: {
          overflow: "linebreak",
          fontSize: 9.5,
          lineColor: [0, 0, 0],
          lineWidth: 0.1,
        },
      });
      const lastY = (pdf as any).lastAutoTable?.finalY || currentY;
      currentY = lastY + 8;
    } else {
      pdf.setFont("helvetica", "normal");
      pdf.setFontSize(9);
      pdf.text(
        "No hay registros para mostrar en este manifiesto.",
        margin,
        currentY
      );
      currentY += 8;
    }
  }

  // OBSERVACIONES
  if (manifestData.observations) {
    const finalY = (pdf as any).lastAutoTable?.finalY || currentY + 20;
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(9);
    pdf.text("Observaciones:", margin, finalY + 8);
    pdf.setFont("helvetica", "normal");
    pdf.setFontSize(8);
    pdf.text(
      pdf.splitTextToSize(manifestData.observations, pageWidth - margin * 2),
      margin,
      finalY + 14
    );
    currentY = finalY + 24;
  }

  // FOOTER
  const footerY = pdf.internal.pageSize.height - 25;
  pdf.setDrawColor(0, 0, 0);
  pdf.setLineWidth(0.3);
  pdf.line(margin, footerY - 5, pageWidth - margin, footerY - 5);
  pdf.setFont("helvetica", "normal");
  pdf.setFontSize(8);
  pdf.text(
    `Generado el: ${new Date().toLocaleString("es-PE")}`,
    margin,
    footerY + 3
  );
  if (manifestData.generated_by_user?.full_name)
    pdf.text(`Por: ${manifestData.generated_by_user.full_name}`, margin, footerY + 8);
  else if (manifestData.generated_by_name)
    pdf.text(`Por: ${manifestData.generated_by_name}`, margin, footerY + 8);
  const systemName = company.businessName !== "N/A" ? `Sistema de Gestion - ${company.businessName.trim()}` : "Sistema de Gestion";
  pdf.text(
    systemName,
    pageWidth - margin - 80,
    footerY + 3
  );

  // Crear blob del PDF y devolver
  const blob = new Blob([pdf.output("blob")], { type: "application/pdf" });
  return { pdf, blob };
};

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { Quotation } from '../types';

export const generateQuotationPDF = (
  quotationData: Quotation
): { pdf: jsPDF; blob: Blob } => {

  const pdf = new jsPDF('p', 'mm', 'a4');
  const pageWidth = pdf.internal.pageSize.width;
  const margin = 15;
  let currentY = 20;

  // ============ HEADER CON INFORMACIÓN DE LA EMPRESA ============
  if (quotationData.company) {
    const company = quotationData.company;

    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(12);
    pdf.text(company.business_name, pageWidth / 2, currentY, { align: 'center' });

    currentY += 6;
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(8);
    const infoText = `RUC: ${company.ruc} | ${company.address} | Tel: ${company.phone}`;
    pdf.text(infoText, pageWidth / 2, currentY, { align: 'center' });

    currentY += 15;
  }

  // ============ TÍTULO DE LA COTIZACIÓN ============
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(12);
  pdf.text('COTIZACIÓN', margin, currentY);

  // Número de la cotización
  pdf.setFontSize(10);
  pdf.text(`N° ${quotationData.series}-${quotationData.number.toString().padStart(6, '0')}`, pageWidth - margin - 30, currentY, { align: 'right' });

  currentY += 8;

  // ============ INFORMACIÓN EN UNA LÍNEA ============
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(9);

  let quotationInfo = `Fecha: ${new Date(quotationData.issue_date).toLocaleDateString('es-PE')}`;
  quotationInfo += ` | Válida hasta: ${new Date(quotationData.valid_until).toLocaleDateString('es-PE')}`;
  quotationInfo += ` | Moneda: ${quotationData.currency_code}`;

  pdf.text(quotationInfo, margin, currentY);
  currentY += 6;

  // Línea separadora
  pdf.setDrawColor(0, 0, 0);
  pdf.setLineWidth(0.5);
  pdf.line(margin, currentY, pageWidth - margin, currentY);
  currentY += 6;

  // Información del cliente
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(9);
  pdf.text(`Cliente: ${quotationData.client.name}`, margin, currentY);
  pdf.setFont('helvetica', 'normal');
  const clientDoc = quotationData.client.doc_type === '1' ? 'DNI' : quotationData.client.doc_type === '6' ? 'RUC' : 'Documento';
  pdf.text(`${clientDoc}: ${quotationData.client.doc_number}`, margin + 80, currentY);
  currentY += 10;

  // ============ TABLA DE SERVICIOS ============
  if (quotationData.items && quotationData.items.length > 0) {
    const tableData = quotationData.items.map((item, index) => [
      (index + 1).toString(),
      item.item_description || 'N/A',
      item.quantity.toString(),
      item.unit_code || 'UND',
      `${quotationData.currency_code} ${parseFloat(item.unit_price.toString()).toFixed(2)}`,
      `${quotationData.currency_code} ${item.discount.toString()}`,
      `${quotationData.currency_code} ${(parseFloat(item.unit_price.toString()) * item.quantity - parseFloat(item.discount.toString())).toFixed(2)}`
    ]);

    autoTable(pdf, {
      startY: currentY,
      head: [['N°', 'DESCRIPCIÓN', 'CANT.', 'UND.', 'P. UNITARIO', 'DESCUENTO', 'SUBTOTAL']],
      body: tableData,
      styles: {
        fontSize: 7,
        cellPadding: 1.5,
        halign: 'center',
        valign: 'middle',
      },
      headStyles: {
        fillColor: [100, 100, 100],
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        fontSize: 7,
      },
      columnStyles: {
        0: { halign: 'center', cellWidth: 10 },
        1: { halign: 'left', cellWidth: 60 },
        2: { halign: 'center', cellWidth: 15 },
        3: { halign: 'center', cellWidth: 15 },
        4: { halign: 'right', cellWidth: 25 },
        5: { halign: 'right', cellWidth: 25 },
        6: { halign: 'right', cellWidth: 30 },
      },
      margin: { left: margin, right: margin },
      tableWidth: 'wrap',
      theme: 'grid',
    });

    let contentY = (pdf as any).lastAutoTable.finalY || currentY + 50;
    contentY += 10;

    // ============ OBSERVACIONES ============
    if (quotationData.notes && quotationData.notes.trim() !== '') {
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(9);
      pdf.text('Observaciones:', margin, contentY);
      contentY += 6;

      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(8);
      const splitNotes = pdf.splitTextToSize(quotationData.notes, pageWidth - (margin * 2));
      pdf.text(splitNotes, margin, contentY);
      contentY += splitNotes.length * 5 + 10;
    }

    // ============ TABLA DE CUENTAS BANCARIAS ============
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(9);
    pdf.text('DEPOSITAR A NUESTRAS CTAS:', margin, contentY);
    contentY += 8;

    const bankAccountsData = [
      ['BBVA SOLES', '0011-0301-01001363-48', '011-301-000100136348-98'],
      ['BCP SOLES', '390-71637705-0-89', '002390171637705088933'],
      ['BBVA DÓLARES', '0011-0301-02016350-78', '011-301-000201635078-93'],
      ['BCP DÓLARES', '390-71637719-1-03', '002390171637719103336']
    ];

    autoTable(pdf, {
      startY: contentY,
      head: [['ENTIDAD FINANCIERA', 'NÚMERO DE CUENTA', 'CCI']],
      body: bankAccountsData,
      styles: {
        fontSize: 7,
        cellPadding: 1.5,
        halign: 'center',
        valign: 'middle',
      },
      headStyles: {
        fillColor: [100, 100, 100],
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        fontSize: 7,
      },
      columnStyles: {
        0: { halign: 'left', cellWidth: 50 },
        1: { halign: 'center', cellWidth: 60 },
        2: { halign: 'center', cellWidth: 70 },
      },
      margin: { left: margin, right: margin },
      tableWidth: 'wrap',
      theme: 'grid',
    });

    contentY = (pdf as any).lastAutoTable.finalY + 15;

    // ============ TOTALES AL FINAL DEL DOCUMENTO ============
    const totalsX = pageWidth - margin - 70;

    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(9);

    let totalY = contentY;
    // Subtotal Neto = total con descuento ya aplicado (coherente con la tabla de ítems)
    const subtotalNeto = parseFloat(quotationData.total_payable) - parseFloat(quotationData.total_igv);
    pdf.text('Subtotal:', totalsX, totalY);
    pdf.text(`${quotationData.currency_code} ${subtotalNeto.toFixed(2)}`, totalsX + 40, totalY, { align: 'right' });
    totalY += 6;

    // IGV (siempre visible, aunque sea 0, para transparencia fiscal)
    pdf.text('IGV (18%):', totalsX, totalY);
    pdf.text(`${quotationData.currency_code} ${parseFloat(quotationData.total_igv).toFixed(2)}`, totalsX + 40, totalY, { align: 'right' });
    totalY += 6;

    pdf.setDrawColor(0, 0, 0);
    pdf.setLineWidth(0.3);
    pdf.line(totalsX, totalY + 1, totalsX + 40, totalY + 1);
    totalY += 5;

    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(10);
    pdf.text('TOTAL:', totalsX, totalY);
    pdf.text(`${quotationData.currency_code} ${parseFloat(quotationData.total_payable).toFixed(2)}`, totalsX + 40, totalY, { align: 'right' });

    totalY += 10;

    // ============ TOTAL EN PALABRAS ============
    pdf.setFont('helvetica', 'italic');
    pdf.setFontSize(8);
    pdf.text(`Total en palabras: ${quotationData.total_in_words}`, margin, totalY);

    totalY += 15;

    // ============ FOOTER ============
    // Asegurar que haya suficiente espacio para el footer
    const footerHeight = 30;
    const minFooterY = pdf.internal.pageSize.height - footerHeight;
    const finalFooterY = Math.max(totalY + 10, minFooterY);

    pdf.setDrawColor(0, 0, 0);
    pdf.setLineWidth(0.3);
    pdf.line(margin, finalFooterY - 5, pageWidth - margin, finalFooterY - 5);

    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(8);
    pdf.text(
      `Generado el: ${new Date().toLocaleString('es-PE')}`,
      margin,
      finalFooterY + 3
    );

    if (quotationData.seller && quotationData.seller.full_name) {
      pdf.text(
        `Vendedor: ${quotationData.seller.full_name}`,
        margin,
        finalFooterY + 8
      );
    }

    const systemName = quotationData.company?.business_name ? `Sistema de Gestión - ${quotationData.company.business_name}` : "Sistema de Gestión";
    pdf.text(
      systemName,
      pageWidth - margin - 70,
      finalFooterY + 3
    );

    pdf.text(
      `Válida hasta: ${new Date(quotationData.valid_until).toLocaleDateString('es-PE')}`,
      pageWidth - margin - 70,
      finalFooterY + 8
    );
  }

  const blob = new Blob([pdf.output('blob')], { type: 'application/pdf' });
  return { pdf, blob };
};

