import React, { useState } from 'react';
import { 
  DocumentTextIcon, 
  ArrowDownTrayIcon,
  ExclamationTriangleIcon 
} from '@heroicons/react/24/outline';
import { Button } from '../../../components/common/Button';
import { Quotation } from '../types';

interface QuotationPDFViewerProps {
  quotation: Quotation;
  pdfUrl: string; // URL del PDF real almacenado en el servidor
}

export const QuotationPDFViewer: React.FC<QuotationPDFViewerProps> = ({
  quotation,
  pdfUrl
}) => {
  const [showPdfError, setShowPdfError] = useState(false);

  return (
    <div className="bg-dm-bg-primary rounded-lg shadow-sm border border-dm-border-primary">
      {/* Header del visor PDF */}
      <div className="px-6 py-4 border-b bg-dm-bg-secondary rounded-t-lg">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <DocumentTextIcon className="h-5 w-5 text-blue-600 dark:text-blue-400" />
            <h2 className="font-semibold text-dm-text-primary">
              Cotización {quotation.series}-{quotation.number.toString().padStart(6, '0')}
            </h2>
          </div>
          <div className="text-sm text-dm-text-muted">
            Cliente: {quotation.client.name}
          </div>
        </div>
      </div>

      {/* Visor PDF */}
      <div className="p-6">
        <div className="relative bg-dm-bg-secondary rounded-lg overflow-hidden" style={{ minHeight: '600px' }}>
          {!showPdfError ? (
            <iframe
              src={`${pdfUrl}#toolbar=0&navpanes=0&scrollbar=0`}
              className="w-full h-full border-0"
              style={{ minHeight: '600px' }}
              title={`Cotización ${quotation.series}-${quotation.number.toString().padStart(6, '0')}`}
              onError={() => setShowPdfError(true)}
              onLoad={(e) => {
                // Verificar si el iframe se cargó correctamente
                try {
                  const iframe = e.target as HTMLIFrameElement;
                  if (!iframe.contentWindow) {
                    setShowPdfError(true);
                  }
                } catch (error) {
                  setShowPdfError(true);
                }
              }}
            />
          ) : (
            <div className="flex flex-col items-center justify-center h-96 text-dm-text-muted">
              <ExclamationTriangleIcon className="h-12 w-12 mb-4 text-dm-text-muted" />
              <h3 className="text-lg font-medium mb-2">No se pudo cargar la cotización</h3>
              <p className="text-sm text-center mb-4">
                El PDF no se puede mostrar en el navegador. 
                Puedes abrirlo en una nueva ventana usando el botón de abajo.
              </p>
              <Button
                variant="primary"
                size="sm"
                onClick={() => window.open(pdfUrl, '_blank')}
                className="flex items-center"
              >
                <ArrowDownTrayIcon className="h-4 w-4 mr-2" />
                Abrir en nueva ventana
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// src/features/quotations/components/QuotationPreviewModal.tsx

import React, { useState, useEffect } from 'react';
import { toast } from '@/utils/sileo-toast';
import { 
  DocumentArrowDownIcon, 
  XMarkIcon,
  PrinterIcon
} from '@heroicons/react/24/outline';
import { MessageCircle } from 'lucide-react';
import { Button } from '../../../components/common/Button';
import { Modal } from '../../../components/common/Modal';
import { useQuotationPDFGeneration } from '../hooks/useQuotationPDFGeneration';
import { QuotationWhatsAppModal } from './QuotationWhatsAppModal';
import { Quotation } from '../types';

interface QuotationPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  onNewQuotation: () => void;
  quotation: Quotation;
}

export const QuotationPreviewModal: React.FC<QuotationPreviewModalProps> = ({
  isOpen,
  onClose,
  onNewQuotation,
  quotation
}) => {
  const [pdfUrl, setPdfUrl] = useState<string | null>(null);
  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);
  const [showWhatsAppModal, setShowWhatsAppModal] = useState(false);

  const { generateAndUploadPDF, generatePreviewPDF } = useQuotationPDFGeneration();

  // Generar PDF cuando se abra el modal
  useEffect(() => {
    if (isOpen && quotation) {
      generatePDFPreview();
    }
  }, [isOpen, quotation]);

  // Limpiar URL del PDF cuando se cierre el modal
  useEffect(() => {
    return () => {
      if (pdfUrl) {
        URL.revokeObjectURL(pdfUrl);
      }
    };
  }, [pdfUrl]);

  const generatePDFPreview = async () => {
    setIsGeneratingPDF(true);
    try {
      const { url } = await generatePreviewPDF(quotation);

      // Limpiar URL anterior si existe
      if (pdfUrl) {
        URL.revokeObjectURL(pdfUrl);
      }

      setPdfUrl(url);

      // Auto-subir el PDF al backend después de generarlo
      try {
        const token = localStorage.getItem('authToken') || '';

        await generateAndUploadPDF(quotation, token);
        toast.success('PDF generado y subido automáticamente al sistema');
      } catch (uploadError) {
        console.error('❌ Error al subir PDF automáticamente:', uploadError);
        toast.warn('PDF generado correctamente, pero no se pudo subir automáticamente al sistema');
      }
    } catch (error) {
      console.error('Error generating PDF preview:', error);
      toast.error('Error al generar la previsualización del PDF');
    } finally {
      setIsGeneratingPDF(false);
    }
  };

  const handleDownloadPDF = async () => {
    try {
      if (!pdfUrl) {
        toast.error('PDF no disponible');
        return;
      }
      // Crear link de descarga
      const link = document.createElement('a');
      link.href = pdfUrl;
      link.download = `cotizacion-${quotation.series}-${quotation.number.toString().padStart(6, '0')}.pdf`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      toast.success('PDF descargado correctamente');
    } catch (error) {
      console.error('Error downloading PDF:', error);
      toast.error('Error al descargar el PDF');
    }
  };

  const handlePrint = () => {
    if (pdfUrl) {
      const printWindow = window.open(pdfUrl);
      printWindow?.focus();
      printWindow?.print();
    }
  };

  const handleClose = () => {
    if (pdfUrl) {
      URL.revokeObjectURL(pdfUrl);
      setPdfUrl(null);
    }
    setShowWhatsAppModal(false);
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="" maxWidth="6xl">
      <div className="space-y-4">
        {/* Header */}
        <div className="flex items-start justify-between pb-4 border-b border-dm-border-primary">
          <div>
            <h2 className="text-xl font-semibold text-dm-text-primary">
              Vista Previa - Cotización
            </h2>
            <p className="text-sm text-dm-text-secondary mt-1">
              N° {quotation.series}-{quotation.number.toString().padStart(6, '0')}
            </p>
          </div>

          <button
            onClick={handleClose}
            className="p-2 hover:bg-dm-bg-hover rounded-lg transition-colors"
          >
            <XMarkIcon className="w-5 h-5 text-dm-text-muted" />
          </button>
        </div>

        {/* PDF Viewer */}
        <div className="bg-dm-bg-secondary rounded-lg" style={{ height: '70vh' }}>
          {isGeneratingPDF ? (
            <div className="flex items-center justify-center h-full">
              <div className="text-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-4"></div>
                <p className="text-dm-text-secondary">Generando previsualización del PDF...</p>
              </div>
            </div>
          ) : pdfUrl ? (
            <iframe
              src={pdfUrl}
              className="w-full h-full rounded-lg border-0"
              title="Previsualización de la Cotización"
            />
          ) : (
            <div className="flex items-center justify-center h-full">
              <p className="text-dm-text-muted">Error al generar la previsualización</p>
            </div>
          )}
        </div>

        {/* Botones de acción */}
        <div className="flex justify-between items-center pt-4 border-t border-dm-border-primary">
          <div className="text-sm text-dm-text-secondary">
            Total: {quotation.currency_code} {parseFloat(quotation.total_payable).toFixed(2)}
          </div>

          <div className="flex space-x-3">
            <Button
              variant="secondary"
              onClick={handleClose}
            >
              Cerrar
            </Button>

            <Button
              variant="outline"
              onClick={handlePrint}
              disabled={!pdfUrl}
              className="flex items-center space-x-2"
            >
              <PrinterIcon className="w-4 h-4" />
              <span>Imprimir</span>
            </Button>

            <Button
              variant="outline"
              onClick={handleDownloadPDF}
              disabled={!pdfUrl}
              className="flex items-center space-x-2"
            >
              <DocumentArrowDownIcon className="w-4 h-4" />
              <span>Descargar PDF</span>
            </Button>

            <Button
              variant="outline"
              onClick={() => setShowWhatsAppModal(true)}
              disabled={!pdfUrl}
              className="flex items-center space-x-2 bg-green-50 dark:bg-green-950/30 border-green-300 dark:border-green-700 text-green-700 dark:text-green-300 hover:bg-green-100 dark:hover:bg-green-900/40"
            >
              <MessageCircle className="w-4 h-4" />
              <span>WhatsApp</span>
            </Button>

            <Button
              variant="primary"
              onClick={onNewQuotation}
            >
              Nueva Cotización
            </Button>
          </div>
        </div>
      </div>

      {/* Modal de WhatsApp */}
      <QuotationWhatsAppModal
        isOpen={showWhatsAppModal}
        onClose={() => setShowWhatsAppModal(false)}
        quotation={quotation}
        pdfUrl={pdfUrl}
      />
    </Modal>
  );
};

// src/features/quotations/components/QuotationWhatsAppModal.tsx
// ACTUALIZADO: Ahora usa la instancia de WhatsApp de la sucursal correspondiente

import React, { useState } from 'react';
import { Modal } from '../../../components/common/Modal';
import { Button } from '../../../components/common/Button';
import { Input } from '../../../components/common/Input';
import { Spinner } from '../../../components/common/Spinner';
import { MessageCircle, Send, CheckCircle, AlertCircle } from 'lucide-react';
import { whatsappService, WhatsAppSendResponse } from '../../../services/whatsapp.service';
import { Quotation } from '../types';
import { useWhatsAppInstanceByName } from '../../../hooks/useWhatsAppInstance';

interface QuotationWhatsAppModalProps {
  isOpen: boolean;
  onClose: () => void;
  quotation: Quotation;
  pdfUrl?: string | null; // Ahora opcional ya que no lo necesitamos
}

export const QuotationWhatsAppModal: React.FC<QuotationWhatsAppModalProps> = ({
  isOpen,
  onClose,
  quotation
}) => {
  const [phoneNumber, setPhoneNumber] = useState(quotation.client?.phone || '');
  const [customMessage, setCustomMessage] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [sendResult, setSendResult] = useState<WhatsAppSendResponse | null>(null);

  const businessName = quotation.branch_office_name || 'Nuestra Empresa';

  // Obtener la instancia de WhatsApp de la sucursal de la cotización
  const whatsAppInstance = useWhatsAppInstanceByName(quotation.branch_office_name);

  const defaultMessage = `¡Hola!

Nos complace enviarle su cotización correspondiente.
Adjuntamos el documento PDF para su revisión.

*Cotización N°:* ${quotation.series}-${quotation.number.toString().padStart(6, '0')}
*Total:* ${quotation.currency_code} ${parseFloat(quotation.total_payable).toFixed(2)}
*Válida hasta:* ${new Date(quotation.valid_until).toLocaleDateString('es-PE')}

Gracias por su confianza.
Atentamente,
El equipo de ${businessName}`;

  const handleSend = async () => {
    if (!phoneNumber.trim()) {
      setSendResult({
        success: false,
        error: 'Por favor ingresa un número de teléfono válido'
      });
      return;
    }

    // Verificar que la sucursal tenga WhatsApp configurado
    if (!whatsAppInstance.hasInstance || !whatsAppInstance.instanceName) {
      setSendResult({
        success: false,
        error: whatsAppInstance.error || 'Esta sucursal no tiene WhatsApp configurado'
      });
      return;
    }

    try {
      setIsSending(true);
      setSendResult(null);

      // Usar el nuevo endpoint específico para cotizaciones
      const result = await whatsappService.sendQuotationPdf({
        quotationId: quotation.id,
        phoneNumber,
        customMessage: customMessage.trim() || undefined,
        instanceName: whatsAppInstance.instanceName,
        businessName: businessName
      });

      setSendResult(result);

      if (result.success) {
        // Limpiar el formulario después del éxito
        setTimeout(() => {
          onClose();
          setPhoneNumber(quotation.client?.phone || '');
          setCustomMessage('');
          setSendResult(null);
        }, 2000);
      }

    } catch (error: any) {
      setSendResult({
        success: false,
        error: error.message || 'Error desconocido al procesar el envío'
      });
    } finally {
      setIsSending(false);
    }
  };

  const handleClose = () => {
    if (!isSending) {
      onClose();
      // Reset form state
      setPhoneNumber(quotation.client?.phone || '');
      setCustomMessage('');
      setSendResult(null);
    }
  };

  const isValidPhoneNumber = (phone: string): boolean => {
    const cleaned = phone.replace(/[^\d]/g, '');
    return cleaned.length >= 9; // Mínimo 9 dígitos
  };

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={handleClose}
      title="Enviar Cotización por WhatsApp"
      maxWidth="md"
    >
      <div className="p-6">
        <div className="flex items-center mb-4">
          <MessageCircle className="h-6 w-6 text-green-600 dark:text-green-400 mr-2" />
          <div>
            <h3 className="font-semibold text-dm-text-primary">
              Envío de Cotización
            </h3>
            <p className="text-sm text-dm-text-secondary">
              Cotización: {quotation.series}-{quotation.number.toString().padStart(6, '0')}
            </p>
          </div>
        </div>

        {/* Campo de número de teléfono */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-dm-text-secondary mb-2">
            Número de WhatsApp
          </label>
          <Input
            type="tel"
            value={phoneNumber}
            onChange={(e) => setPhoneNumber(e.target.value)}
            placeholder="Ej: +51 987 654 321 o 987654321"
            disabled={isSending}
            className={`${
              phoneNumber && !isValidPhoneNumber(phoneNumber) 
                ? 'border-red-300 focus:border-red-500' 
                : ''
            }`}
          />
          {phoneNumber && !isValidPhoneNumber(phoneNumber) && (
            <p className="text-xs text-red-600 dark:text-red-400 mt-1">
              Ingresa un número válido (mínimo 9 dígitos)
            </p>
          )}
          <p className="text-xs text-dm-text-muted mt-1">
            Se agregará automáticamente el código de país +51 si no se especifica
          </p>
        </div>

        {/* Campo de mensaje personalizado */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-dm-text-secondary mb-2">
            Mensaje (opcional)
          </label>
          <textarea
            value={customMessage}
            onChange={(e) => setCustomMessage(e.target.value)}
            placeholder={defaultMessage}
            disabled={isSending}
            rows={8}
            className="w-full px-3 py-2 border border-dm-border-primary rounded-md bg-dm-bg-primary text-dm-text-primary focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
          />
          <p className="text-xs text-dm-text-muted mt-1">
            Si dejas vacío, se usará el mensaje predeterminado
          </p>
        </div>

        {/* Resultado del envío */}
        {sendResult && (
          <div className={`mb-4 p-3 rounded-lg flex items-center ${
            sendResult.success 
              ? 'bg-green-50 dark:bg-green-950/30 border border-green-200 dark:border-green-800/50' 
              : 'bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800/50'
          }`}>
            {sendResult.success ? (
              <>
                <CheckCircle className="h-5 w-5 text-green-600 dark:text-green-400 mr-2 flex-shrink-0" />
                <div className="text-green-800 dark:text-green-300">
                  <p className="font-medium">¡Enviado exitosamente!</p>
                  <p className="text-sm">{sendResult.message}</p>
                </div>
              </>
            ) : (
              <>
                <AlertCircle className="h-5 w-5 text-red-600 dark:text-red-400 mr-2 flex-shrink-0" />
                <div className="text-red-800 dark:text-red-300">
                  <p className="font-medium">Error al enviar</p>
                  <p className="text-sm">{sendResult.error}</p>
                </div>
              </>
            )}
          </div>
        )}

        {/* Botones de acción */}
        <div className="flex gap-3">
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isSending}
            className="flex-1"
          >
            {sendResult?.success ? 'Cerrar' : 'Cancelar'}
          </Button>

          <Button
            onClick={handleSend}
            disabled={isSending || !phoneNumber.trim() || !isValidPhoneNumber(phoneNumber) || !whatsAppInstance.hasInstance}
            className="flex-1 bg-green-600 hover:bg-green-700 disabled:bg-dm-text-muted disabled:cursor-not-allowed"
          >
            {isSending ? (
              <>
                <Spinner size="sm" className="mr-2" />
                Enviando...
              </>
            ) : (
              <>
                <Send className="h-4 w-4 mr-2" />
                Enviar por WhatsApp
              </>
            )}
          </Button>
        </div>

        {/* Advertencia si no hay WhatsApp configurado para la sucursal */}
        {!whatsAppInstance.hasInstance && !whatsAppInstance.isLoading && (
          <div className="mt-4 p-3 bg-yellow-50 dark:bg-yellow-950/30 border border-yellow-200 dark:border-yellow-800/50 rounded-lg">
            <div className="flex items-start">
              <AlertCircle className="h-4 w-4 text-yellow-600 dark:text-yellow-400 mr-2 mt-0.5 flex-shrink-0" />
              <div className="text-yellow-800 dark:text-yellow-300 text-xs">
                <p className="font-medium mb-1">WhatsApp no configurado</p>
                <p>
                  {whatsAppInstance.error || `La sucursal "${quotation.branch_office_name || 'desconocida'}" no tiene una instancia de WhatsApp configurada.`}
                </p>
                <p className="mt-1">
                  Contacta al administrador para configurar WhatsApp en esta sucursal.
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Nota informativa - Solo mostrar si hay WhatsApp configurado */}
        {whatsAppInstance.hasInstance && (
          <div className="mt-4 p-3 bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 rounded-lg">
            <div className="flex items-start">
              <MessageCircle className="h-4 w-4 text-blue-600 dark:text-blue-400 mr-2 mt-0.5 flex-shrink-0" />
              <div className="text-blue-800 dark:text-blue-300 text-xs">
                <p className="font-medium mb-1">Información:</p>
                <ul className="list-disc list-inside space-y-1">
                  <li>Verifica que el número tenga WhatsApp activo</li>
                  <li>El envío puede tardar unos segundos</li>
                  <li>Sucursal: <strong>{whatsAppInstance.branchOfficeName}</strong></li>
