// Hook personalizado para series de guías de remisión del transportista
const useRemissionGuideSeries = (branchId: number | null) => {
  const companyId = 1; // Asumiendo que siempre es la compañía 1 por ahora
  const { data: allSeries = [], isLoading, error } = useDocumentSeries(companyId);

  const remissionGuideSeries = allSeries.filter(
    s => s.branch_office_id === branchId && 
         s.document_type_code === '31' && 
         s.is_active
  );

  return {
    availableSeries: remissionGuideSeries,
    isLoading,
    error,
  };
};

interface FormStepContentProps {
  selectedTrip: AvailableTripByPort;
  onBack: () => void;
}

export const FormStepContent: React.FC<FormStepContentProps> = ({
  selectedTrip,
  onBack,
}) => {
  const navigate = useNavigate();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedSeries, setSelectedSeries] = useState('');
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [generationResult, setGenerationResult] = useState<AutoGenerateRemissionGuidesResponse | null>(null);

  const { data: tripDetails, isLoading: isLoadingTrip } = useTripDetails(selectedTrip.id);

  // Obtener branch_id de localStorage como en SaleForm
  const savedBranch = localStorage.getItem('selectedSalesBranch');
  const branchId = savedBranch ? JSON.parse(savedBranch).id : null;

  const { availableSeries, isLoading: isLoadingSeries } = useRemissionGuideSeries(branchId);

  // Efecto para seleccionar automáticamente la primera serie disponible
  useEffect(() => {
    if (availableSeries.length > 0 && !selectedSeries) {
      setSelectedSeries(availableSeries[0].series_code);
    }
  }, [availableSeries, selectedSeries]);

  const { control, setValue, getValues, formState: { errors } } = useForm<RemissionGuideTransportistaFormData>({
    resolver: zodResolver(remissionGuideTransportistaSchema),
    defaultValues: {
      document_type_code: '31',
      series: 'T001',
      issue_date: new Date(),
      transfer_start_date: new Date(),
      transfer_reason_code: '01', // Venta
      transfer_reason_description: 'Venta de mercancías',
      gross_total_weight: 0,
      number_of_packages: 1,
      transport_mode_code: '01', // Transporte público
      trip_id: 0,
      vessel_id: 0,
      sender: {
        document_type_code: '6', // RUC
        document_number: '',
        business_name: '',
      },
      receiver: {
        document_type_code: '1', // DNI
        document_number: '',
        business_name: '',
      },
      origin_address: {
        ubigeo_code: '',
        address: '',
      },
      destination_address: {
        ubigeo_code: '',
        address: '',
      },
      driver_doc_type: '1', // DNI
      driver_doc_number: '',
      driver_name: '',
      driver_license: '',
      observation: '',
      items: [],
    }
  });

  useEffect(() => {
    if (tripDetails && tripDetails.vessel && tripDetails.route) {
      setValue('trip_id', tripDetails.id);
      setValue('vessel_id', tripDetails.vessel.id);

      // Solo autocompletar remitente si los campos están vacíos para no sobreescribir ediciones del usuario
      if (tripDetails.company) {
        if (!getValues('sender.document_number')) {
          setValue('sender.document_number', tripDetails.company.ruc);
        }
        if (!getValues('sender.business_name')) {
          setValue('sender.business_name', tripDetails.company.business_name);
        }
        if (!getValues('sender.document_type_code')) {
          setValue('sender.document_type_code', '6'); // RUC
        }
      }

      // Autocompletar dirección de partida solo si está vacía
      if (tripDetails.route.origin_port) {
        const originAddress = getValues('origin_address') || {};
        if (!originAddress.address && !originAddress.ubigeo_code) {
          setValue('origin_address', {
            address: tripDetails.route.origin_port.address || 'Puerto de Origen',
            ubigeo_code: tripDetails.route.origin_port.ubigeo
          });
        } else {
          // Si alguno de los dos está vacío, rellenar solo el faltante
          if (!originAddress.address) {
            setValue('origin_address.address', tripDetails.route.origin_port.address || 'Puerto de Origen');
          }
          if (!originAddress.ubigeo_code) {
            setValue('origin_address.ubigeo_code', tripDetails.route.origin_port.ubigeo);
          }
        }
      }
    }
  }, [tripDetails, setValue, getValues]);

  const handleAutoGenerate = async () => {
    // Validar que el viaje tenga múltiples destinos/paradas
    if (!tripDetails?.stops || tripDetails.stops.length < 2) {
      toast.error("El viaje seleccionado no tiene suficientes destinos para generar guías automáticamente. Debe tener al menos un destino además del origen.");
      return;
    }

    const driverData = getValues();
    if (!driverData.driver_name || !driverData.driver_doc_number || !driverData.driver_license) {
      toast.error("Complete todos los datos del conductor antes de generar las guías.");
      return;
    }

    if (!selectedSeries) {
      toast.error("Seleccione una serie de guía de remisión.");
      return;
    }

    // Encontrar el ID de la serie seleccionada
    const selectedSeriesData = availableSeries.find(s => s.series_code === selectedSeries);
    if (!selectedSeriesData) {
      toast.error("La serie seleccionada no es válida.");
      return;
    }

    setIsSubmitting(true);

    try {
      const payload = {
        trip_id: selectedTrip.id,
        company_id: 1, // Siempre usar compañía ID 1
        document_series_id: selectedSeriesData.id,
        series: selectedSeries,
        transport_mode_code: '02', // Marítimo según el ejemplo
        captain_name: driverData.driver_name,
        captain_doc_type: driverData.driver_doc_type,
        captain_doc_number: driverData.driver_doc_number,
        captain_license: driverData.driver_license,
      };

      const response = await remissionGuidesService.autoGenerate(payload);

      toast.success(`Se generaron ${response.guides_generated.length} guías de remisión automáticamente para ${response.destinations_processed} destinos.`);

      // Guardar resultado y mostrar modal de previsualización
      setGenerationResult(response);
      setShowPreviewModal(true);
    } catch (error) {
      console.error('Error al generar guías automáticamente:', error);
      // Mostrar mensaje específico del backend si está disponible
      const errorMessage = (error as any)?.detail || (error as any)?.response?.data?.detail || "Error al generar las guías de remisión. Intente nuevamente.";
      toast.error(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      <div className="space-y-8">
        {/* Información del viaje seleccionado */}
        <div className="bg-gradient-to-r from-green-50 to-blue-50 border border-green-200 dark:border-green-800/50 rounded-xl p-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <div className="flex items-center justify-center w-12 h-12 bg-green-100 dark:bg-green-900/40 rounded-lg">
                <CheckCircleIcon className="h-6 w-6 text-green-600 dark:text-green-400" />
              </div>
              <div>
                <h4 className="text-lg font-semibold text-dm-text-primary">
                  Viaje Seleccionado: {selectedTrip?.trip_name || tripDetails?.trip_name || `ID: ${selectedTrip.id}`}
                </h4>
                {(selectedTrip?.vessel_name || tripDetails?.vessel?.name) && (
                  <p className="text-sm text-dm-text-secondary">
                    <TruckIcon className="h-4 w-4 inline mr-1" />
                    Embarcación: {selectedTrip?.vessel_name || tripDetails?.vessel?.name}
                  </p>
                )}
              </div>
            </div>
            <Button 
              variant="outline" 
              size="sm" 
              type="button"
              onClick={onBack}
              className="flex items-center"
            >
              <ArrowLeftIcon className="h-4 w-4 mr-1" />
              Cambiar Viaje
            </Button>
          </div>
        </div>

        {/* Indicador de paradas del viaje */}
        {tripDetails?.stops && tripDetails.stops.length > 1 && (
          <div className="bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800/50 rounded-xl p-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-4">
                <div className="flex items-center justify-center w-12 h-12 bg-blue-100 dark:bg-blue-900/40 rounded-lg">
                  <MapPinIcon className="h-6 w-6 text-blue-600 dark:text-blue-400" />
                </div>
                <div>
                  <h4 className="text-lg font-semibold text-dm-text-primary">
                    Viaje Multi-Parada Detectado
                  </h4>
                  <p className="text-sm text-dm-text-secondary">
                    {tripDetails.stops.length} destinos encontrados. Se generarán guías automáticamente para cada destino.
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Render condicional basado en el modo de generación */}
        <div className="bg-dm-bg-primary rounded-xl shadow-sm border border-dm-border-primary overflow-hidden">
          <div className="p-8">
            <div className="text-center mb-8">
              <div className="flex items-center justify-center w-16 h-16 bg-blue-100 dark:bg-blue-900/40 rounded-full mx-auto mb-4">
                <DocumentTextIcon className="h-8 w-8 text-blue-600 dark:text-blue-400" />
              </div>
              <h3 className="text-lg font-semibold text-dm-text-primary mb-2">Generación Automática de Guías</h3>
              <p className="text-dm-text-secondary">
                Se generarán guías automáticamente para cada destino del viaje seleccionado.
                Solo necesitas proporcionar los datos del conductor.
              </p>
            </div>

            {/* Conductor - solo para auto generación */}
            <div className="border border-dm-border-primary rounded-xl p-6 max-w-2xl mx-auto">
              <div className="flex items-center space-x-3 mb-6">
                <div className="flex items-center justify-center w-10 h-10 bg-orange-100 dark:bg-orange-900/40 rounded-lg">
                  <UserIcon className="h-6 w-6 text-orange-600 dark:text-orange-400" />
                </div>
                <h3 className="text-lg font-semibold text-dm-text-primary">Datos del Conductor</h3>
              </div>

              {/* Selector de Serie */}
              <div className="mb-6">
                <label className="block text-sm font-medium text-dm-text-secondary mb-2">
                  <DocumentTextIcon className="h-4 w-4 inline mr-1" />
                  Serie de Guía de Remisión*
                </label>
                {isLoadingSeries ? (
                  <div className="flex items-center space-x-2">
                    <Spinner size="sm" />
                    <span className="text-sm text-dm-text-muted">Cargando series...</span>
                  </div>
                ) : (
                  <select
                    value={selectedSeries}
                    onChange={(e) => setSelectedSeries(e.target.value)}
                    className="w-full p-3 border border-dm-border-primary rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
                    disabled={availableSeries.length === 0}
                  >
                    <option value="">
                      {availableSeries.length === 0 ? 'No hay series disponibles' : 'Seleccionar serie...'}
                    </option>
                    {availableSeries.map((series) => (
                      <option key={series.id} value={series.series_code}>
                        {series.series_code}
                      </option>
                    ))}
                  </select>
                )}
                {availableSeries.length === 0 && !isLoadingSeries && (
                  <p className="text-sm text-dm-text-muted mt-1">
                    No se encontraron series activas para guías de remisión en esta sucursal.
                  </p>
                )}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Input 
                  label="Nombre Completo*" 
                  {...control.register('driver_name')} 
                  error={errors.driver_name?.message} 
                />

                <Input 
                  label="Licencia de Conducir*" 
                  {...control.register('driver_license')} 
                  error={errors.driver_license?.message} 
                />

                <div>
                  <label className="block text-sm font-medium text-dm-text-secondary mb-2">Tipo Doc*</label>
                  <Controller
                    name="driver_doc_type"
                    control={control}
                    render={({ field }) => (
                      <select 
                        {...field}
                        className="w-full p-3 border border-dm-border-primary rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
                      >
                        {DOCUMENT_TYPES.map(docType => (
                          <option key={docType.code} value={docType.code}>
                            {docType.name}
                          </option>
                        ))}
                      </select>
                    )}
                  />
                  {errors.driver_doc_type && (
                    <p className="text-red-500 dark:text-red-400 text-xs mt-1">{errors.driver_doc_type.message}</p>
                  )}
                </div>

                <Input 
                  label="N° Documento*" 
                  {...control.register('driver_doc_number')} 
                  error={errors.driver_doc_number?.message} 
                />
              </div>
            </div>
          </div>

          {/* Botones de acción para auto-generación */}
          <div className="bg-dm-bg-secondary px-8 py-6 border-t border-dm-border-primary">
            <div className="flex items-center justify-end space-x-4">
              <Button 
                type="button" 
                variant="outline" 
                onClick={() => navigate('/remission-guides')}
                disabled={isSubmitting}
                className="px-6 py-2"
              >
                Cancelar
              </Button>
              <Button 
                type="button"
                onClick={handleAutoGenerate}
                disabled={isLoadingTrip || isSubmitting || !tripDetails?.stops || tripDetails.stops.length < 2 || !selectedSeries || availableSeries.length === 0}
                className="px-8 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-dm-text-muted text-white font-medium rounded-lg flex items-center transition-colors"
              >
                {isSubmitting ? (
                  <>
                    <Spinner size="sm" />
                    <span className="ml-2">Generando Guías...</span>
                  </>
                ) : (
                  <>
                    <DocumentTextIcon className="h-5 w-5 mr-2" />
                    Generar Guías Automáticamente
                  </>
                )}
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Modal de previsualización de PDFs */}
      {showPreviewModal && generationResult && (
        <RemissionGuidePreviewModal
          isOpen={showPreviewModal}
          onClose={() => {
            setShowPreviewModal(false);
            setGenerationResult(null);
            navigate('/remission-guides');
          }}
          generationResult={generationResult}
        />
      )}

    </div>
  );
};

// src/features/remissionGuides/components/RemissionGuideSenderPreviewModal.tsx

import React, { useState, useEffect } from 'react';
import { 
  XMarkIcon,
  DocumentArrowDownIcon,
  EyeIcon,
  CheckCircleIcon
} from '@heroicons/react/24/outline';
import { Button } from '../../../components/common/Button';
import { RemissionGuideRemitente } from '../../../types';
import { convertSenderGuideToAutoGenerate } from '../utils/guideConversion';
import { generateRemissionGuidePDF } from './pdf/RemissionGuidePDFGenerator';
import { remissionGuidesSenderService } from '../../../services/remissionGuidesSender.service';
import { toast } from '@/utils/sileo-toast';

interface RemissionGuideSenderPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  guide: RemissionGuideRemitente | any; // Permitir any para datos del backend con estructura diferente
}

export const RemissionGuideSenderPreviewModal: React.FC<RemissionGuideSenderPreviewModalProps> = ({
  isOpen,
  onClose,
  guide
}) => {
  const [pdfUrl, setPdfUrl] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);

  // Generar PDF cuando se abre el modal
  useEffect(() => {
    if (isOpen && guide) {
      generatePDFForPreview();
    }

    return () => {
      if (pdfUrl) {
        URL.revokeObjectURL(pdfUrl);
      }
    };
  }, [isOpen, guide?.id]); // Usar optional chaining para guide.id

  const generatePDFForPreview = async () => {
    if (!guide) {
      toast.error('No se encontraron datos de la guía');
      return;
    }

    setIsGenerating(true);
    try {
      const convertedGuide = convertSenderGuideToAutoGenerate(guide);
      if (!convertedGuide) {
        toast.error('Error al procesar los datos de la guía');
        return;
      }

      const { blob } = await generateRemissionGuidePDF(convertedGuide, 'remitente');
      const url = URL.createObjectURL(blob);
      setPdfUrl(url);
    } catch (error) {
      console.error('Error generando PDF:', error);
      toast.error('Error al generar el PDF de previsualización');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownloadPDF = async () => {
    try {
      const convertedGuide = convertSenderGuideToAutoGenerate(guide);
      if (!convertedGuide) return;

      const { pdf, blob } = await generateRemissionGuidePDF(convertedGuide, 'remitente');

      // Subir al backend
      try {
        const fileName = `${guide.series}-${guide.number.toString().padStart(8, '0')}`;
        const pdfFile = new File([blob], `guia-remision-remitente-${fileName}.pdf`, {
          type: 'application/pdf'
        });

        await remissionGuidesSenderService.uploadRemissionGuidePDF(guide.id, pdfFile, 'a4');
        toast.success('PDF descargado y actualizado en el sistema');
      } catch (uploadError) {
        console.warn('Error al subir PDF:', uploadError);
        toast.success('PDF descargado (no se pudo actualizar en el sistema)');
      }

      // Descargar
      const fileName = `${guide.series}-${guide.number.toString().padStart(8, '0')}`;
      pdf.save(`guia-remision-remitente-${fileName}.pdf`);
    } catch (error) {
      console.error('Error descargando PDF:', error);
      toast.error('Error al descargar el PDF');
    }
  };

  const handlePrintPDF = () => {
    if (pdfUrl) {
      window.open(pdfUrl, '_blank');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex items-center justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
        {/* Fondo del modal */}
        <div 
          className="fixed inset-0 bg-black/50 backdrop-blur-sm transition-opacity"
          onClick={onClose}
        />

        {/* Contenido del modal */}
        <div className="inline-block align-bottom bg-dm-bg-primary rounded-lg text-left overflow-hidden shadow-xl border border-dm-border-primary transform transition-all sm:my-8 sm:align-middle sm:max-w-6xl sm:w-full">
          {/* Header */}
          <div className="bg-dm-bg-primary px-4 pt-5 pb-4 sm:p-6 sm:pb-4 border-b border-dm-border-primary">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-lg leading-6 font-medium text-dm-text-primary flex items-center">
                  <CheckCircleIcon className="h-6 w-6 text-green-500 mr-2" />
                  Guía de Remisión del Remitente Creada
                </h3>
                <p className="text-sm text-dm-text-muted mt-1">
                  {guide.series}-{guide.number.toString().padStart(8, '0')} - Vista previa del PDF generado
                </p>
              </div>

              <button
                onClick={onClose}
                className="rounded-md text-dm-text-muted hover:text-dm-text-muted focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <XMarkIcon className="h-6 w-6" />
              </button>
            </div>
          </div>

          {/* Contenido */}
          <div className="bg-dm-bg-primary px-4 pt-5 pb-4 sm:p-6">
            {/* Información de la guía */}
            <div className="bg-green-50 dark:bg-green-950/30 border border-green-200 dark:border-green-800/50 rounded-lg p-4 mb-6">
              <div className="flex items-center">
                <CheckCircleIcon className="h-5 w-5 text-green-400 mr-2" />
                <div className="text-sm">
                  <p className="text-green-800 dark:text-green-300 font-medium">
                    La guía de remisión del remitente ha sido creada exitosamente
                  </p>
                  <p className="text-green-700 dark:text-green-300 mt-1">
                    Destinatario: {guide.receiver?.business_name || guide.recipient_name || 'N/A'} | 
                    Origen: {guide.origin_address?.address || guide.origin_address || 'N/A'} → 
                    Destino: {guide.destination_address?.address || guide.destination_address || 'N/A'}
                  </p>
                </div>
              </div>
            </div>

            {/* Visor PDF */}
            <div className="bg-dm-bg-secondary rounded-lg" style={{ height: '70vh' }}>
              {isGenerating ? (
                <div className="flex items-center justify-center h-full">
                  <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                    <p className="text-dm-text-secondary mt-4">Generando PDF...</p>
                  </div>
                </div>
              ) : pdfUrl ? (
                <iframe
                  src={pdfUrl}
                  className="w-full h-full rounded-lg"
                  title="Vista previa del PDF"
                />
              ) : (
                <div className="flex items-center justify-center h-full">
                  <p className="text-dm-text-muted">No se pudo cargar la vista previa del PDF</p>
                </div>
              )}
            </div>
          </div>

          {/* Footer */}
          <div className="bg-dm-bg-secondary px-4 py-3 sm:px-6 sm:flex sm:flex-row-reverse">
            <div className="flex space-x-3">
              <Button
                onClick={handleDownloadPDF}
                className="flex items-center"
                disabled={isGenerating}
              >
                <DocumentArrowDownIcon className="w-4 h-4 mr-2" />
                Descargar PDF
              </Button>

              <Button
                variant="outline"
                onClick={handlePrintPDF}
                className="flex items-center"
                disabled={isGenerating || !pdfUrl}
              >
                <EyeIcon className="w-4 h-4 mr-2" />
                Imprimir
              </Button>

              <Button
                variant="secondary"
                onClick={onClose}
              >
                Cerrar
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// src/features/remissionGuides/components/pdf/RemissionGuidePDFGenerator.tsx

import React from 'react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { AutoGenerateRemissionGuide } from '../../../../types';
import { drawLogoInPdf } from '../../../../utils/pdfLogo';
import { getDocumentCompanyInfo } from '../../../../utils/documentCompanyInfo';

// Tipo para especificar el tipo de guía de remisión
export type RemissionGuideType = 'transportista' | 'remitente';

/**
 * Genera un PDF A4 para una guía de remisión
 * Soporta tanto guías de transportista como de remitente
 * @param guideData Datos de la guía
 * @param guideType Tipo de guía (transportista o remitente)
 */
export const generateRemissionGuidePDF = async (
  guideData: AutoGenerateRemissionGuide,
  guideType: RemissionGuideType = 'transportista'
): Promise<{ pdf: jsPDF; blob: Blob }> => {
  const pdf = new jsPDF('p', 'mm', 'a4');
  const pageWidth = pdf.internal.pageSize.width; // 210mm
  const pageHeight = pdf.internal.pageSize.height; // 297mm
  const margin = 8; // Margen mínimo optimizado para impresión (8mm)
  let currentY = 12;
  const company = await getDocumentCompanyInfo();

  // ============ HEADER CON LOGO Y DATOS DE LA EMPRESA ============
  // Logo mejorado en el lado izquierdo
  const logoX = margin;
  const logoY = currentY;
  const logoW = 50;
  const logoH = 25;

  try {
    const hasLogo = await drawLogoInPdf(pdf, company.logoUrl, {
      x: logoX,
      y: logoY,
      width: logoW,
      height: logoH,
      padding: 5,
    });

    if (!hasLogo) {
      throw new Error('No se pudo renderizar el logo');
    }
  } catch (err) {
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(11);
    pdf.setTextColor(0, 0, 0);
    pdf.text(company.businessName, logoX + logoW / 2, logoY + logoH / 2 - 2, { align: 'center' });
    pdf.setFontSize(7);
    const companyType = guideType === 'transportista' ? 'TRANSPORTISTA' : 'REMITENTE';
    pdf.text(`S.A.C. - ${companyType}`, logoX + logoW / 2, logoY + logoH / 2 + 4, { align: 'center' });
  }

  // Colocamos la información de la compañía al mismo nivel que el logo (a la derecha)
  const companyX = logoX + logoW + 10;
  const companyMaxWidth = pageWidth - companyX - margin;
  const companyStartY = logoY + 4; // un poco desde arriba del logo

  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(12);
  pdf.text(company.businessName, companyX, companyStartY);

  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(9);
  let companyInfoY = companyStartY + 6;
  // Dirección (puede ocupar varias líneas)
  const addressLines = pdf.splitTextToSize(company.address, companyMaxWidth);
  addressLines.forEach((line: string) => {
    pdf.text(line, companyX, companyInfoY);
    companyInfoY += 4;
  });
  // RUC
  pdf.text(`RUC: ${company.ruc}`, companyX, companyInfoY);
  companyInfoY += 5;
  // Teléfono y email si existen
  if (company.phone !== 'N/A') {
    pdf.text(`Tel: ${company.phone}`, companyX, companyInfoY);
    companyInfoY += 4;
  }
  if (company.email !== 'N/A') {
    pdf.text(company.email, companyX, companyInfoY);
    companyInfoY += 4;
  }

  // Ajustar currentY al mayor entre la base del logo y la info de la compañía
  const bottomOfLogo = logoY + logoH;
  const bottomOfCompanyInfo = companyInfoY;
  currentY = Math.max(bottomOfLogo, bottomOfCompanyInfo) + 6;

  // La observación se moverá para colocarla antes de la sección BIENES TRANSPORTADOS

  // ============ TÍTULO CENTRADO ============
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(13);

  // Título diferente según el tipo de guía
  const guideTitle = guideType === 'transportista' 
    ? 'GUÍA DE REMISIÓN TRANSPORTISTA'
    : 'GUÍA DE REMISIÓN REMITENTE';

  pdf.text(guideTitle, pageWidth / 2, currentY, { align: 'center' });
  currentY += 5;
  pdf.text('ELECTRÓNICA', pageWidth / 2, currentY, { align: 'center' });
  currentY += 8;

  // Número de documento centrado
  pdf.setFontSize(11);
  pdf.text(guideData.document_number, pageWidth / 2, currentY, { align: 'center' });
  currentY += 12;

  // ============ SECCIONES DEL DOCUMENTO (2 COLUMNAS SIN RAYAS) ============

  // Helper functions para el nuevo diseño
  const checkPageSpace = (requiredSpace: number): number => {
    // Margen inferior más agresivo - solo 20mm desde el final
    if (currentY + requiredSpace > pageHeight - 20) {
      pdf.addPage();
      return 20; // Nueva Y en nueva página (más arriba)
    }
    return currentY;
  };

  const addTwoColumnSection = (title: string, leftData: string[], rightData: string[]): void => {
    currentY = checkPageSpace(30 + Math.max(leftData.length, rightData.length) * 5); // Reducido de 35 a 30

    // Título de la sección con fondo gris claro
    pdf.setFillColor(248, 249, 250);
    pdf.rect(margin, currentY, pageWidth - 2 * margin, 8, 'F');
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(9);
    pdf.setTextColor(60, 60, 60);
    pdf.text(title, margin + 3, currentY + 6);
    currentY += 12;

    // Definir ancho de columnas
    const columnWidth = (pageWidth - 2 * margin) / 2;

    // Columna izquierda
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(8);
    pdf.setTextColor(0, 0, 0);
    let leftY = currentY;
    leftData.forEach(line => {
      if (line.trim()) {
        pdf.text(line, margin + 3, leftY);
        leftY += 5;
      }
    });

    // Columna derecha
    let rightY = currentY;
    rightData.forEach(line => {
      if (line.trim()) {
        pdf.text(line, margin + columnWidth + 3, rightY);
        rightY += 5;
      }
    });

    currentY = Math.max(leftY, rightY) + 5; // Reducido de 6 a 5
  };

  // Formatear fechas correctamente
  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr + 'T12:00:00');
    return date.toLocaleDateString('es-PE', {
      day: '2-digit',
      month: '2-digit', 
      year: 'numeric'
    });
  };

  // REMITENTE Y DESTINATARIO en 2 columnas
  addTwoColumnSection(
    'DATOS DEL REMITENTE Y DESTINATARIO',
    [
      'REMITENTE:',
      `Razón Social: ${guideData.sender_name}`,
      `RUC: ${guideData.sender_doc_number}`,
      '',
      'DIRECCIÓN:',
      `${guideData.origin_address}`
    ],
    [
      'DESTINATARIO:',
      `Nombres: ${guideData.recipient_name}`,
      `DNI: ${guideData.recipient_doc_number}`,
      '',
      'DESTINO:',
      `${guideData.destination_address}`
    ]
  );

  // TRASLADO Y TRANSPORTE en 2 columnas
  addTwoColumnSection(
    'DATOS DEL TRASLADO Y TRANSPORTE',
    [
      'FECHAS DEL TRASLADO:',
      `Fecha de Emisión: ${formatDate(guideData.issue_date)}`,
      `Fecha Inicio: ${formatDate(guideData.shipment_start_date)}`,
      '',
      'MODALIDAD:',
      'Transporte Fluvial'
    ],
    [
      'DATOS DE LA EMBARCACIÓN:',
      `Embarcación: ${guideData.vessel_name}`,
      `Matrícula: ${guideData.vessel_plate}`,
      '',
      'CAPITÁN:',
      `${guideData.captain_name}`,
      `DNI: ${guideData.captain_doc_number}`
    ]
  );

  // DATOS DEL COMPROBANTE RELACIONADO (si existen)
  if (guideData.related_doc_type && guideData.related_doc_number) {
    const tiposDoc = {
      '01': 'FACTURA',
      '03': 'BOLETA',
      '07': 'NOTA DE CRÉDITO',
      '08': 'NOTA DE DÉBITO',
      '09': 'GUÍA DE REMISIÓN REMITENTE',
      '31': 'GUÍA DE REMISIÓN TRANSPORTISTA'
    };

    const tipoDoc = tiposDoc[guideData.related_doc_type as keyof typeof tiposDoc] || guideData.related_doc_type;

    // Convertimos a any para acceder a las propiedades no definidas en el tipo pero que existen en el JSON
    const guideDataExtended = guideData as any;

    addTwoColumnSection(
      'DATOS DEL COMPROBANTE RELACIONADO',
      [
        'COMPROBANTE:',
        `Tipo: ${tipoDoc}`,
        `Número: ${guideData.related_doc_number}`,
        guideDataExtended.related_doc_ruc ? `RUC: ${guideDataExtended.related_doc_ruc}` : '',
      ],
      [
        'DESCRIPCIÓN:',
        guideDataExtended.related_doc_description || 'No especificada'
      ]
    );
  }

  // Imprimir observación si existe (campo que en log.md está como "observation")
  if (guideData.observation) {
    // Asegurar que hay suficiente espacio para la observación
    currentY = checkPageSpace(15); // Espacio estimado para observación

    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(9);
    // Dejar un pequeño espacio y luego escribir la observación en una línea amplia
    const obsLines = pdf.splitTextToSize(`Observación: ${guideData.observation}`, pageWidth - 2 * margin);
    obsLines.forEach((line: string) => {
      pdf.text(line, margin, currentY);
      currentY += 4;
    });
    currentY += 2;
  }

  // ============ BIENES TRANSPORTADOS (CON CONTROL DE PAGINACIÓN) ============
  currentY = checkPageSpace(35); // Reducido de 40 a 35

  // Título de la sección
  pdf.setFillColor(248, 249, 250);
  pdf.rect(margin, currentY, pageWidth - 2 * margin, 8, 'F');
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(9);
  pdf.setTextColor(60, 60, 60);
  pdf.text('BIENES TRANSPORTADOS', margin + 3, currentY + 6);
  currentY += 12;

  // Tabla de bienes con mejor formato y paginación automática
  const tableColumns = ['CANT.', 'UNIDAD', 'PESO (KGM)', 'DESCRIPCIÓN'];
  const tableData = guideData.package_items.map(item => [
    item.quantity.toFixed(2),
    item.unit_code,
    guideData.total_weight.toFixed(2),
    item.description
  ]);

  autoTable(pdf, {
    startY: currentY,
    head: [tableColumns],
    body: tableData,
    theme: 'striped',
    headStyles: {
      fillColor: [245, 245, 245],
      textColor: [0, 0, 0],
      fontSize: 8, // Reducido de 9 a 8
      fontStyle: 'bold',
      halign: 'center',
      cellPadding: 3, // Reducido de 4 a 3
    },
    bodyStyles: {
      fontSize: 7, // Reducido de 8 a 7
      cellPadding: 2, // Reducido de 3 a 2
      halign: 'center',
      textColor: [0, 0, 0],
    },
    alternateRowStyles: { 
      fillColor: [252, 252, 252] 
    },
    columnStyles: {
      0: { cellWidth: 25, halign: 'center' }, // CANT
      1: { cellWidth: 25, halign: 'center' }, // UNIDAD  
      2: { cellWidth: 30, halign: 'center' }, // PESO
      3: { cellWidth: 'auto', halign: 'left' }, // DESCRIPCIÓN
    },
    margin: { left: margin, right: margin },
    styles: {
      overflow: 'linebreak',
      lineColor: [200, 200, 200],
      lineWidth: 0.2,
    }
  });

  currentY = (pdf as any).lastAutoTable.finalY + 6; // Reducido de 8 a 6

  // ============ FOOTER CON QR Y DATOS DE GENERACIÓN (CON CONTROL DE PAGINACIÓN) ============
  const footerHeight = 25; // Reducido aún más de 35 a 25
  currentY = checkPageSpace(footerHeight);

  // Verificación más precisa para el footer - solo saltar si realmente no cabe
  const availableSpace = pageHeight - currentY - 15; // 15mm de margen inferior mínimo
  if (availableSpace < footerHeight) {
    pdf.addPage();
    currentY = 15; // Comenzar más arriba en nueva página
  }

  // Separador sutil
  pdf.setFillColor(240, 240, 240);
  pdf.rect(margin, currentY, pageWidth - 2 * margin, 1, 'F');
  currentY += 4; // Reducido de 6 a 4

  // Layout en 2 columnas: QR + Información
  const qrSize = 20; // Reducido aún más de 22 a 20mm
  const qrX = margin;
  const qrY = currentY;

  try {
    if (guideData.qr_code_data) {
      // Agregar QR real desde base64
      pdf.addImage(
        `data:image/png;base64,${guideData.qr_code_data}`,
        'PNG',
        qrX,
        qrY,
        qrSize,
        qrSize
      );
    } else {
      // Fallback: rectángulo con texto
      pdf.setDrawColor(180, 180, 180);
      pdf.setLineWidth(0.5);
      pdf.rect(qrX, qrY, qrSize, qrSize);
      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(6);
      pdf.setTextColor(120, 120, 120);
      pdf.text('QR Code', qrX + qrSize/2, qrY + qrSize/2, { align: 'center' });
    }
  } catch (error) {
    console.warn('Error al agregar QR code, usando fallback:', error);
    pdf.setDrawColor(180, 180, 180);
    pdf.setLineWidth(0.5);
    pdf.rect(qrX, qrY, qrSize, qrSize);
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(6);
    pdf.setTextColor(120, 120, 120);
    pdf.text('QR Code', qrX + qrSize/2, qrY + qrSize/2, { align: 'center' });
  }

  // Información al lado del QR
  const infoX = qrX + qrSize + 6; // Reducido de 8 a 6
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(7);
  pdf.setTextColor(80, 80, 80);

  let footerInfoY = qrY + 3; // Reducido de 4 a 3
  pdf.text('Representación impresa de la Guía de Remisión Electrónica', infoX, footerInfoY);
  footerInfoY += 4; // Reducido de 5 a 4

  const currentDate = new Date();
  const generationInfo = `Generado: ${currentDate.toLocaleDateString('es-PE')} ${currentDate.toLocaleTimeString('es-PE')}`;
  pdf.text(generationInfo, infoX, footerInfoY);
  footerInfoY += 4; // Reducido de 5 a 4

  if (guideData.document_number) {
    pdf.text(`Documento: ${guideData.document_number}`, infoX, footerInfoY);
  }

  currentY += qrSize + 4; // Reducido de 6 a 4

  // ============ BORDE FINAL ============
  pdf.setLineWidth(0.6);
  pdf.line(margin, currentY, pageWidth - margin, currentY);

  // Crear blob del PDF
  const blob = new Blob([pdf.output('blob')], { type: 'application/pdf' });

  return { pdf, blob };
};

// ============ FUNCIÓN PARA GENERAR MÚLTIPLES PDFs ============
export const generateMultipleRemissionGuidePDFs = (
  guidesData: AutoGenerateRemissionGuide[]
): { pdfs: jsPDF[]; blobs: Blob[]; zipBlob?: Blob } => {
  const pdfs: jsPDF[] = [];
  const blobs: Blob[] = [];

  // Generar PDF para cada guía (notar: generateRemissionGuidePDF es async)
  // Para mantener compatibilidad con consumidores sin async, generamos en serie
  const gen = async () => {
    for (const guide of guidesData) {
      // eslint-disable-next-line no-await-in-loop
      const { pdf, blob } = await generateRemissionGuidePDF(guide);
      pdfs.push(pdf);
      blobs.push(blob);
    }
  };
  // Ejecutar generación síncrona bloqueante corta
  // Nota: esta función devuelve inmediatamente las referencias; los pdfs y blobs
  // se poblarán cuando finalice la generación. Para la mayoría de usos se
  // invoca generateMultipleRemissionGuidePDFs seguido de acciones que esperan
  // o se usa la variante en memoria del componente.
  gen();

  return { pdfs, blobs };
};

// ============ PROPS DEL COMPONENTE ============
interface RemissionGuidePDFGeneratorProps {
  guideData: AutoGenerateRemissionGuide;
  onPDFGenerated?: (blob: Blob) => void;
}

// ============ COMPONENTE REACT ============
export const RemissionGuidePDFGenerator: React.FC<RemissionGuidePDFGeneratorProps> = ({
  guideData,
  onPDFGenerated
}) => {

  const handleGeneratePDF = () => {
    (async () => {
      const { blob } = await generateRemissionGuidePDF(guideData);
      // Abrir PDF en nueva ventana para previsualización
      const url = URL.createObjectURL(blob);
      window.open(url, '_blank');
      // Limpiar URL después de un tiempo
      setTimeout(() => URL.revokeObjectURL(url), 10000);
      // Callback si se proporciona
      if (onPDFGenerated) {
        onPDFGenerated(blob);
      }
    })();
  };

  const handleDownloadPDF = () => {
    (async () => {
      const { pdf } = await generateRemissionGuidePDF(guideData);
      pdf.save(`guia-remision-${guideData.document_number}.pdf`);
    })();
  };

  return (
    <div className="flex space-x-3">
      <button
        onClick={handleGeneratePDF}
        className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm"
      >
        Vista Previa PDF
      </button>

      <button
        onClick={handleDownloadPDF}
        className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors text-sm"
      >
        Descargar PDF
      </button>
    </div>
  );
};

// ============ COMPONENTE PARA MÚLTIPLES GUÍAS ============
interface MultipleRemissionGuidePDFGeneratorProps {
  guidesData: AutoGenerateRemissionGuide[];
  onPDFsGenerated?: (blobs: Blob[]) => void;
}

export const MultipleRemissionGuidePDFGenerator: React.FC<MultipleRemissionGuidePDFGeneratorProps> = ({
  guidesData,
  onPDFsGenerated
}) => {

  const handleGenerateAllPDFs = () => {
    (async () => {
      // Esperar generación completa
      const genResult = await (async () => {
        const pdfs: jsPDF[] = [];
        const blobs: Blob[] = [];
        for (const guide of guidesData) {
          // eslint-disable-next-line no-await-in-loop
          const { pdf, blob } = await generateRemissionGuidePDF(guide);
          pdfs.push(pdf);
          blobs.push(blob);
        }
        return { pdfs, blobs };
      })();

      // Abrir cada PDF en una nueva ventana
      genResult.blobs.forEach(blob => {
        const url = URL.createObjectURL(blob);
        window.open(url, '_blank');
        setTimeout(() => URL.revokeObjectURL(url), 10000);
      });

      if (onPDFsGenerated) {
        onPDFsGenerated(genResult.blobs);
      }
    })();
  };

  const handleDownloadAllPDFs = () => {
    (async () => {
      for (const guide of guidesData) {
        // eslint-disable-next-line no-await-in-loop
        const { pdf } = await generateRemissionGuidePDF(guide);
        pdf.save(`guia-remision-${guide.document_number}.pdf`);
      }
    })();
  };

  const handleDownloadSinglePDF = (guide: AutoGenerateRemissionGuide) => {
    (async () => {
      const { pdf } = await generateRemissionGuidePDF(guide);
      pdf.save(`guia-remision-${guide.document_number}.pdf`);
    })();
  };

  return (
    <div className="space-y-4">
      {/* Botones de acción general */}
      <div className="flex space-x-3 pb-4 border-b border-dm-border-primary">
        <button
          onClick={handleGenerateAllPDFs}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm"
        >
          Vista Previa Todos ({guidesData.length})
        </button>

        <button
          onClick={handleDownloadAllPDFs}
          className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors text-sm"
        >
          Descargar Todos
        </button>
      </div>

      {/* Lista de guías individuales */}
      <div className="space-y-3">
        {guidesData.map(guide => (
          <div key={guide.guide_id} className="flex items-center justify-between p-3 bg-dm-bg-secondary rounded-lg">
            <div className="flex-1">
              <div className="font-medium text-sm text-dm-text-primary">
                Guía #{guide.document_number}
              </div>
              <div className="text-sm text-dm-text-secondary">
                Destino: {guide.destination_port_name} | 
                Destinatario: {guide.recipient_name}
              </div>
            </div>

            <div className="flex space-x-2">
              <button
                onClick={() => {
                  (async () => {
                    const { blob } = await generateRemissionGuidePDF(guide);
                    const url = URL.createObjectURL(blob);
                    window.open(url, '_blank');
                    setTimeout(() => URL.revokeObjectURL(url), 10000);
                  })();
                }}
                className="px-3 py-1 bg-blue-500 text-white rounded text-xs hover:bg-blue-600 transition-colors"
              >
                Ver PDF
              </button>

              <button
                onClick={() => handleDownloadSinglePDF(guide)}
                className="px-3 py-1 bg-green-500 text-white rounded text-xs hover:bg-green-600 transition-colors"
              >
                Descargar
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// src/features/remissionGuides/hooks/useRemissionGuidePDFGeneration.ts

import { useState } from 'react';
import { toast } from '@/utils/sileo-toast';
import { generateRemissionGuidePDF } from '../components/pdf/RemissionGuidePDFGenerator';
import { AutoGenerateRemissionGuide } from '../../../types';

export interface RemissionGuidePDFResult {
  pdf: any; // jsPDF instance
  blob: Blob;
}

export const useRemissionGuidePDFGeneration = () => {
  const [isGenerating, setIsGenerating] = useState(false);

  /**
   * Genera PDF para una sola guía de remisión
   */
  const generateSinglePDF = async (
    guideData: AutoGenerateRemissionGuide
  ): Promise<RemissionGuidePDFResult | null> => {
    setIsGenerating(true);
    try {
      const result = await generateRemissionGuidePDF(guideData);
      toast.success(`PDF generado para guía ${guideData.document_number}`);
      return result;
    } catch (error) {
      console.error('Error generating remission guide PDF:', error);
      toast.error('Error al generar el PDF de la guía de remisión');
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Genera PDFs para múltiples guías de remisión
   */
  const generateMultiplePDFs = async (
    guidesData: AutoGenerateRemissionGuide[]
  ): Promise<{ pdfs: any[]; blobs: Blob[] } | null> => {
    setIsGenerating(true);
    try {
      const pdfs: any[] = [];
      const blobs: Blob[] = [];
      // Generar en serie para controlar memoria y requests
      for (const guide of guidesData) {
        // eslint-disable-next-line no-await-in-loop
        const res = await generateRemissionGuidePDF(guide);
        pdfs.push(res.pdf);
        blobs.push(res.blob);
      }
      toast.success(`${guidesData.length} PDFs generados exitosamente`);
      return { pdfs, blobs };
    } catch (error) {
      console.error('Error generating multiple remission guide PDFs:', error);
      toast.error('Error al generar los PDFs de las guías de remisión');
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Descarga un PDF individual
   */
  const downloadSinglePDF = async (
    guideData: AutoGenerateRemissionGuide
  ): Promise<void> => {
    setIsGenerating(true);
    try {
      const { pdf } = await generateRemissionGuidePDF(guideData);
      pdf.save(`guia-remision-${guideData.document_number}.pdf`);
      toast.success(`PDF descargado: ${guideData.document_number}`);
    } catch (error) {
      console.error('Error downloading remission guide PDF:', error);
      toast.error('Error al descargar el PDF');
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Descarga múltiples PDFs
   */
  const downloadMultiplePDFs = async (
    guidesData: AutoGenerateRemissionGuide[]
  ): Promise<void> => {
    setIsGenerating(true);
    try {
      // Generar y descargar en serie para evitar bloqueos y uso excesivo de memoria
      for (let i = 0; i < guidesData.length; i++) {
        const guide = guidesData[i];
        // eslint-disable-next-line no-await-in-loop
        const { pdf } = await generateRemissionGuidePDF(guide);
        // Programar el guardado con pequeño delay para no colapsar el navegador
        setTimeout(() => pdf.save(`guia-remision-${guide.document_number}.pdf`), i * 200);
      }

      toast.success(`${guidesData.length} PDFs programados para descarga`);
    } catch (error) {
      console.error('Error downloading multiple remission guide PDFs:', error);
      toast.error('Error al descargar los PDFs');
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Abre vista previa de un PDF individual
   */
  const previewSinglePDF = async (
    guideData: AutoGenerateRemissionGuide
  ): Promise<void> => {
    setIsGenerating(true);
    try {
      const { blob } = await generateRemissionGuidePDF(guideData);
      if (!(blob instanceof Blob)) throw new Error('generateRemissionGuidePDF no devolvió un Blob válido');
      const url = URL.createObjectURL(blob);
      window.open(url, '_blank');

      // Limpiar URL después de 10 segundos
      setTimeout(() => URL.revokeObjectURL(url), 10000);

    } catch (error) {
      console.error('Error previewing remission guide PDF:', error);
      toast.error('Error al mostrar vista previa del PDF');
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Abre vista previa de múltiples PDFs
   */
  const previewMultiplePDFs = async (
    guidesData: AutoGenerateRemissionGuide[]
  ): Promise<void> => {
    setIsGenerating(true);
    try {
      // Generar cada PDF en serie y abrir su vista previa
      for (let i = 0; i < guidesData.length; i++) {
        const guide = guidesData[i];
        // eslint-disable-next-line no-await-in-loop
        const { blob } = await generateRemissionGuidePDF(guide);
        if (!(blob instanceof Blob)) {
          console.warn(`Guía ${guide.guide_id} no generó un blob válido`);
          continue;
        }
        setTimeout(() => {
          const url = URL.createObjectURL(blob);
          window.open(url, '_blank');
          setTimeout(() => URL.revokeObjectURL(url), 10000);
        }, i * 300);
      }

    } catch (error) {
      console.error('Error previewing multiple remission guide PDFs:', error);
      toast.error('Error al mostrar vista previa de los PDFs');
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Genera PDF y retorna como Blob para upload al servidor
   */
  const generatePDFBlob = async (
    guideData: AutoGenerateRemissionGuide
  ): Promise<Blob | null> => {
    try {
      const { blob } = await generateRemissionGuidePDF(guideData);
      if (!(blob instanceof Blob)) return null;
      return blob;
    } catch (error) {
      console.error('Error generating PDF blob:', error);
      return null;
    }
  };

  return {
    isGenerating,
    generateSinglePDF,
    generateMultiplePDFs,
    downloadSinglePDF,
    downloadMultiplePDFs,
    previewSinglePDF,
    previewMultiplePDFs,
    generatePDFBlob
  };
};

// src/features/remissionGuides/hooks/useRemissionGuideSenderPDFGeneration.ts

import { useState } from 'react';
import { toast } from '@/utils/sileo-toast';
import { generateRemissionGuidePDF } from '../components/pdf/RemissionGuidePDFGenerator';
import { convertSenderGuideToAutoGenerate } from '../utils/guideConversion';
import { remissionGuidesSenderService } from '../../../services/remissionGuidesSender.service';

export interface RemissionGuideSenderPDFResult {
  pdf: any; // jsPDF instance
  blob: Blob;
}

export const useRemissionGuideSenderPDFGeneration = () => {
  const [isGenerating, setIsGenerating] = useState(false);

  /**
   * Genera PDF para una sola guía de remisión del remitente
   */
  const generateSinglePDF = async (
    guideData: any
  ): Promise<RemissionGuideSenderPDFResult | null> => {
    setIsGenerating(true);
    try {
      const convertedGuide = convertSenderGuideToAutoGenerate(guideData);
      if (!convertedGuide) {
        toast.error('Error al procesar los datos de la guía del remitente');
        return null;
      }

      const result = await generateRemissionGuidePDF(convertedGuide, 'remitente');
      toast.success(`PDF generado para guía ${convertedGuide.document_number}`);
      return result;
    } catch (error) {
      console.error('Error generating remission guide sender PDF:', error);
      toast.error('Error al generar el PDF de la guía del remitente');
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Genera múltiples PDFs para guías del remitente
   */
  const generateMultiplePDFs = async (
    guidesData: any[]
  ): Promise<RemissionGuideSenderPDFResult[] | null> => {
    setIsGenerating(true);
    try {
      const results: RemissionGuideSenderPDFResult[] = [];

      for (const guide of guidesData) {
        const convertedGuide = convertSenderGuideToAutoGenerate(guide);
        if (convertedGuide) {
          const result = await generateRemissionGuidePDF(convertedGuide, 'remitente');
          results.push(result);
        }
      }

      toast.success(`${results.length} PDFs generados para guías del remitente`);
      return results;
    } catch (error) {
      console.error('Error generating multiple remission guide sender PDFs:', error);
      toast.error('Error al generar los PDFs de las guías del remitente');
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Descarga un PDF individual y opcionalmente lo sube al backend
   */
  const downloadSinglePDF = async (
    guideData: any,
    uploadToBackend: boolean = true
  ): Promise<void> => {
    setIsGenerating(true);
    try {
      const convertedGuide = convertSenderGuideToAutoGenerate(guideData);
      if (!convertedGuide) {
        toast.error('Error al procesar los datos de la guía del remitente');
        return;
      }

      const { pdf, blob } = await generateRemissionGuidePDF(convertedGuide, 'remitente');

      // Subir al backend si se solicita
      if (uploadToBackend) {
        try {
          const fileName = `${guideData.series}-${guideData.number.toString().padStart(8, '0')}`;
          const pdfFile = new File([blob], `guia-remision-remitente-${fileName}.pdf`, {
            type: 'application/pdf'
          });

          await remissionGuidesSenderService.uploadRemissionGuidePDF(guideData.id, pdfFile, 'a4');
          toast.success('PDF generado, descargado y subido al sistema');
        } catch (uploadError) {
          console.warn('Error al subir PDF automáticamente:', uploadError);
          toast.success('PDF descargado (error al subir al sistema)');
        }
      } else {
        toast.success(`PDF descargado: ${convertedGuide.document_number}`);
      }

      // Descargar el PDF
      const fileName = `${guideData.series}-${guideData.number.toString().padStart(8, '0')}`;
      pdf.save(`guia-remision-remitente-${fileName}.pdf`);
    } catch (error) {
      console.error('Error downloading remission guide sender PDF:', error);
      toast.error('Error al descargar el PDF del remitente');
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Descarga múltiples PDFs con delay entre cada uno
   */
  const downloadMultiplePDFs = async (
    guidesData: any[],
    uploadToBackend: boolean = true
  ): Promise<void> => {
    setIsGenerating(true);
    try {
      // Programar descarga en cadena para evitar generar muchos blobs simultáneamente
      for (let i = 0; i < guidesData.length; i++) {
        const guide = guidesData[i];

        setTimeout(() => {
          (async () => {
            try {
              const convertedGuide = convertSenderGuideToAutoGenerate(guide);
              if (!convertedGuide) return;

              const { pdf, blob } = await generateRemissionGuidePDF(convertedGuide, 'remitente');

              // Subir al backend si se solicita
              if (uploadToBackend) {
                try {
                  const fileName = `${guide.series}-${guide.number.toString().padStart(8, '0')}`;
                  const pdfFile = new File([blob], `guia-remision-remitente-${fileName}.pdf`, {
                    type: 'application/pdf'
                  });

                  await remissionGuidesSenderService.uploadRemissionGuidePDF(guide.id, pdfFile, 'a4');
                } catch (uploadError) {
                  console.warn(`Error al subir PDF de guía ${guide.id}:`, uploadError);
                }
              }

              // Descargar
              const fileName = `${guide.series}-${guide.number.toString().padStart(8, '0')}`;
              pdf.save(`guia-remision-remitente-${fileName}.pdf`);
            } catch (err) {
              console.error('Error generando PDF para descarga masiva:', err);
            }
          })();
        }, i * 300); // 300ms delay between downloads
      }

      toast.success(`${guidesData.length} PDFs del remitente programados para descarga`);
    } catch (error) {
      console.error('Error downloading multiple sender PDFs:', error);
      toast.error('Error al descargar los PDFs del remitente');
    } finally {
      setIsGenerating(false);
    }
  };

  /**
   * Previsualiza un PDF en nueva ventana y opcionalmente lo sube al backend
   */
  const previewSinglePDF = async (
    guideData: any,
    uploadToBackend: boolean = true
  ): Promise<void> => {
    setIsGenerating(true);
    try {
      const convertedGuide = convertSenderGuideToAutoGenerate(guideData);
      if (!convertedGuide) {
        toast.error('Error al procesar los datos de la guía del remitente');
        return;
      }

      const { blob } = await generateRemissionGuidePDF(convertedGuide, 'remitente');

      // Subir al backend si se solicita
      if (uploadToBackend) {
        try {
          const fileName = `${guideData.series}-${guideData.number.toString().padStart(8, '0')}`;
          const pdfFile = new File([blob], `guia-remision-remitente-${fileName}.pdf`, {
            type: 'application/pdf'
          });

          await remissionGuidesSenderService.uploadRemissionGuidePDF(guideData.id, pdfFile, 'a4');
          toast.success('PDF generado y subido al sistema');
        } catch (uploadError) {
          console.warn('Error al subir PDF automáticamente:', uploadError);
          toast.success('PDF generado (error al subir al sistema)');
        }
      } else {
        toast.success(`PDF generado: ${convertedGuide.document_number}`);
      }

      // Abrir en nueva ventana
      const url = URL.createObjectURL(blob);
      window.open(url, '_blank');
      setTimeout(() => URL.revokeObjectURL(url), 10000);
    } catch (error) {
      console.error('Error previewing remission guide sender PDF:', error);
      toast.error('Error al previsualizar el PDF del remitente');
    } finally {
      setIsGenerating(false);
    }
  };

  return {
    isGenerating,
    generateSinglePDF,
    generateMultiplePDFs,
    downloadSinglePDF,
    downloadMultiplePDFs,
    previewSinglePDF
  };
};

