/**
 * Verifica si una guía del remitente puede ser convertida para generar PDF
 */
export const canGenerateSenderPDF = (guide: any): boolean => {
  return !!(
    guide.sender_name &&
    guide.recipient_name &&
    guide.origin_address &&
    guide.destination_address &&
    guide.series &&
    guide.number
  );
};

/**
