              <div className="space-y-1.5">
                <label className={labelClass}>Usuario SOL *</label>
                <div className="relative">
                  <UserIcon className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-dm-text-muted" />
                  <input className={`${fieldClass} pl-10`} {...register('sunat_username')} />
                </div>
                {errors.sunat_username && (
                  <p className="text-[12px] text-red-600 dark:text-red-400">{errors.sunat_username.message}</p>
                )}
              </div>
              <div className="space-y-1.5">
                <label className={labelClass}>Contraseña SOL (dejar en blanco para no cambiar)</label>
                <div className="relative">
                  <LockClosedIcon className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-dm-text-muted" />
                  <input
                    type={showSunatPassword ? 'text' : 'password'}
                    className={`${fieldClass} pl-10 pr-10`}
                    {...register('sunat_password_sol')}
                  />
                  <button
                    type="button"
                    onClick={() => setShowSunatPassword(!showSunatPassword)}
                    className="absolute right-3.5 top-1/2 -translate-y-1/2 text-dm-text-muted hover:text-dm-text-primary transition-colors"
                    tabIndex={-1}
                  >
                    {showSunatPassword ? (
                      <EyeSlashIcon className="h-4 w-4" />
                    ) : (
                      <EyeIcon className="h-4 w-4" />
                    )}
                  </button>
                </div>
              </div>
              <div className="p-3.5 rounded-[8px] border border-[#1F4690]/10 bg-[#1F4690]/[0.02]">
                <p className="text-[11px] leading-relaxed text-dm-text-secondary">
                  <span className="font-semibold text-[#1F4690] uppercase">Importante:</span>{' '}
                  Estas credenciales son necesarias para la emisión de comprobantes electrónicos a
                  través del sistema OSE/PSE.
                </p>
              </div>
            </div>
          </section>

          {/* Archivos Digitales */}
          <section className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary flex flex-col overflow-hidden">
            <div className="px-6 py-4 border-b border-dm-border-primary flex items-center gap-2.5">
              <div className="w-7 h-7 rounded-[6px] bg-dm-bg-secondary flex items-center justify-center">
                <FolderOpenIcon className="h-4 w-4 text-[#1F4690]" />
              </div>
              <h2 className="text-[15px] font-semibold text-dm-text-primary">Archivos digitales</h2>
            </div>
            <div className="p-6 space-y-6 flex-1">
              {/* Logo */}
              <div className="flex items-center gap-5">
                <div className="relative w-20 h-20 shrink-0 bg-dm-bg-secondary rounded-[12px] border-2 border-dashed border-dm-border-primary flex items-center justify-center overflow-hidden">
                  {company?.logo_url ? (
                    <img src={company.logo_url} alt="Logo" className="w-full h-full object-contain" />
                  ) : (
                    <div className="bg-[#1F4690]/10 p-2 rounded-full">
                      <PhotoIcon className="h-8 w-8 text-[#1F4690]" />
                    </div>
                  )}
                  {isUploadingLogo && (
                    <div className="absolute inset-0 bg-dm-bg-primary/80 flex items-center justify-center">
                      <Spinner size="sm" />
                    </div>
                  )}
                </div>
                <div className="space-y-1.5">
                  <p className="text-[13px] font-semibold text-dm-text-primary">Logo de la empresa</p>
                  <p className="text-[11px] text-dm-text-muted">
                    Recomendado: SVG, PNG o WEBP (400×400 px)
                  </p>
                  <button
                    type="button"
                    onClick={() => logoInputRef.current?.click()}
                    disabled={isUploadingLogo}
                    className="text-[11px] font-medium text-[#1F4690] bg-[#1F4690]/5 hover:bg-[#1F4690]/10 px-3 py-1.5 rounded-full transition-colors disabled:opacity-60"
                  >
                    {isUploadingLogo ? 'Subiendo logo...' : 'Cambiar logo'}
                  </button>
                  <input
                    type="file"
                    ref={logoInputRef}
                    className="hidden"
                    accept=".jpg,.jpeg,.png,.svg,.webp,image/jpeg,image/png,image/svg+xml,image/webp"
                    onChange={(e) => handleLogoUpload(e.target.files?.[0])}
                  />
                </div>
              </div>

              <div className="border-t border-dm-border-primary" />

              {/* Certificate */}
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-[8px] bg-emerald-50 dark:bg-emerald-950/30 flex items-center justify-center">
                      <ShieldCheckIcon className="h-4 w-4 text-emerald-600 dark:text-emerald-400" />
                    </div>
                    <div>
                      <p className="text-[13px] font-semibold text-dm-text-primary">Certificado digital</p>
                      <p className="text-[11px] text-dm-text-muted">
                        {company?.certificate_path
                          ? 'Certificado cargado'
                          : 'No se ha cargado un certificado'}
                      </p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => certificateInputRef.current?.click()}
                    className="text-[11px] font-medium text-[#1F4690] hover:underline"
                  >
                    {company?.certificate_path ? 'Reemplazar' : 'Seleccionar'}
                  </button>
                  <input
                    type="file"
                    ref={certificateInputRef}
                    className="hidden"
                    accept=".pfx,.p12"
                    onChange={(e) =>
                      handleFileUpload(
                        e.target.files?.[0],
                        companiesService.uploadCertificate,
                        {
                          password: certificatePasswordForUpload,
                          successMsg: 'Certificado actualizado',
                          errorMsg: 'Error al subir certificado',
                        }
                      )
                    }
                  />
                </div>
                <div className="space-y-1.5">
                  <label className={labelClass}>Password del certificado</label>
                  <div className="relative">
                    <input
                      type={showCertPassword ? 'text' : 'password'}
                      className={`${fieldClass} pr-10`}
                      placeholder="Ingrese para cambiar o para subir nuevo"
                      {...register('certificate_password')}
                    />
                    <button
                      type="button"
                      onClick={() => setShowCertPassword(!showCertPassword)}
                      className="absolute right-3.5 top-1/2 -translate-y-1/2 text-dm-text-muted hover:text-dm-text-primary transition-colors"
                      tabIndex={-1}
                    >
                      {showCertPassword ? (
                        <EyeSlashIcon className="h-4 w-4" />
                      ) : (
                        <EyeIcon className="h-4 w-4" />
                      )}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>

        {/* ── Save button ── */}
        <div className="flex justify-end pt-2">
          <button
            type="submit"
            disabled={updateMutation.isPending}
            className="inline-flex items-center gap-2 bg-[#1F4690] text-white px-8 py-3 rounded-full text-[13px] font-medium hover:bg-[#16377a] transition-colors disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {updateMutation.isPending ? (
              <Spinner size="sm" color="text-white" />
            ) : (
              <ArrowDownTrayIcon className="h-4 w-4" />
            )}
            Guardar cambios
          </button>
        </div>
      </form>
    </div>
  );
};

// src/features/settings/pages/RolesPage.tsx
import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { PlusIcon, PencilIcon, TrashIcon, UserGroupIcon } from '@heroicons/react/24/outline';
import { toast } from '@/utils/sileo-toast';

import { Spinner } from '../../../components/common/Spinner';
import { Button } from '../../../components/common/Button';
import { Modal } from '../../../components/common/Modal';
import { Input } from '../../../components/common/Input';
import { rolesService, CreateRoleData, UpdateRoleData } from '../../../services/roles.service';
import { Role } from '../../../types';
import { usePermissions } from '../../../hooks/usePermissions';
import { getErrorMessage } from '../../../utils/errorHandler';

export const RolesPage: React.FC = () => {
  const queryClient = useQueryClient();
  const { hasPermission } = usePermissions();
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);
  const [roleName, setRoleName] = useState('');
  const [roleDescription, setRoleDescription] = useState('');
  const [roleIsActive, setRoleIsActive] = useState(true);
  const [roleNameError, setRoleNameError] = useState('');

  const formatRoleName = (name: string): string => {
    return name.toLowerCase().trim().replace(/\s+/g, '_');
  };

  // Query para obtener todos los roles
  const { data: roles, isLoading, error } = useQuery({
    queryKey: ['roles'],
    queryFn: () => rolesService.getAll(),
    retry: 1
  });

  // Mutación para crear rol
  const createRoleMutation = useMutation({
    mutationFn: (data: CreateRoleData) => rolesService.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      toast.success('Rol creado correctamente');
      setIsCreateModalOpen(false);
      resetForm();
    },
    onError: (error: any) => {
      if (error.response?.status === 409) {
        setRoleNameError('Ya existe un rol con este nombre');
      } else {
        const message = getErrorMessage(error, 'Error al crear rol');
        toast.error(message);
      }
    }
  });

  // Mutación para actualizar rol
  const updateRoleMutation = useMutation({
    mutationFn: ({ id, data }: { id: number; data: UpdateRoleData }) => 
      rolesService.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      toast.success('Rol actualizado correctamente');
      setIsEditModalOpen(false);
      resetForm();
    },
    onError: (error: any) => {
      if (error.response?.status === 409) {
        setRoleNameError('Ya existe un rol con este nombre');
      } else {
        const message = getErrorMessage(error, 'Error al actualizar rol');
        toast.error(message);
      }
    }
  });

  // Mutación para desactivar rol
  const deleteRoleMutation = useMutation({
    mutationFn: (id: number) => rolesService.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      toast.success('Rol desactivado correctamente');
      setIsDeleteModalOpen(false);
    },
    onError: (error: any) => {
      if (error.response?.status === 409) {
        toast.error('No se puede desactivar el rol porque está asignado a usuarios activos');
      } else {
        const message = getErrorMessage(error, 'Error al desactivar rol');
        toast.error(message);
      }
    }
  });

  const resetForm = () => {
    setRoleName('');
    setRoleDescription('');
    setRoleIsActive(true);
    setRoleNameError('');
  };

  const handleOpenCreateModal = () => {
    resetForm();
    setIsCreateModalOpen(true);
  };

  const handleOpenEditModal = (role: Role) => {
    setSelectedRole(role);
    setRoleName(role.name);
    setRoleDescription(role.description || '');
    setRoleIsActive(role.is_active ?? true);
    setIsEditModalOpen(true);
  };

  const handleOpenDeleteModal = (role: Role) => {
    setSelectedRole(role);
    setIsDeleteModalOpen(true);
  };

  const validateForm = (): boolean => {
    setRoleNameError('');

    if (!roleName.trim()) {
      setRoleNameError('El nombre del rol es requerido');
      return false;
    }

    // Formatear el nombre automáticamente
    const formattedName = formatRoleName(roleName);
    setRoleName(formattedName);

    return true;
  };

  const handleCreateRole = () => {
    if (!validateForm()) return;

    createRoleMutation.mutate({ 
      name: formatRoleName(roleName), 
      description: roleDescription || undefined,
      is_active: roleIsActive 
    });
  };

  const handleUpdateRole = () => {
    if (!validateForm() || !selectedRole) return;

    updateRoleMutation.mutate({ 
      id: selectedRole.id, 
      data: { 
        name: formatRoleName(roleName), 
        description: roleDescription || undefined,
        is_active: roleIsActive 
      } 
    });
  };

  const handleDeleteRole = () => {
    if (!selectedRole) return;
    deleteRoleMutation.mutate(selectedRole.id);
  };

  if (isLoading) return <Spinner />;

  if (error) {
    return (
      <div className="text-center py-8">
        <p className="text-red-600 dark:text-red-400">Error al cargar los roles. Por favor, intente nuevamente.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="bg-dm-bg-primary rounded-lg shadow-sm p-4 lg:p-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
          <h1 className="text-2xl font-bold text-dm-text-primary">Roles del Sistema</h1>
          {hasPermission('settings', 'roles', 'admin') && (
            <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
              <Button
                onClick={handleOpenCreateModal}
                className="flex items-center justify-center w-full"
              >
                <PlusIcon className="h-5 w-5 mr-2" />
                Nuevo Rol
              </Button>
            </div>
          )}
        </div>
      </div>

      {/* Desktop Table */}
      <div className="hidden md:block bg-dm-bg-primary rounded-lg shadow-sm overflow-x-auto">
        <table className="min-w-full divide-y divide-dm-border-primary">
          <thead className="bg-dm-bg-secondary">
            <tr>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-dm-text-muted uppercase tracking-wider">
                ID
              </th>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-dm-text-muted uppercase tracking-wider">
                Nombre
              </th>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-dm-text-muted uppercase tracking-wider">
                Descripción
              </th>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-dm-text-muted uppercase tracking-wider">
                Estado
              </th>
              <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-dm-text-muted uppercase tracking-wider">
                Acciones
              </th>
            </tr>
          </thead>
          <tbody className="bg-dm-bg-primary divide-y divide-dm-border-primary">
            {roles?.map((role) => (
              <tr key={role.id} className="hover:bg-dm-bg-hover">
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="text-sm text-dm-text-primary">{role.id}</div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="font-medium text-dm-text-primary">{role.name}</div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <div className="text-sm text-dm-text-muted">{role.description || '-'}</div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                    role.is_active ? 'bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-300' : 'bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-300'
                  }`}>
                    {role.is_active ? 'Activo' : 'Inactivo'}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                  {hasPermission('settings', 'roles', 'admin') && (
                    <>
                      <button
                        onClick={() => handleOpenEditModal(role)}
                        className="text-primary hover:text-primary/80 mr-4"
                      >
                        <PencilIcon className="h-5 w-5" />
                      </button>
                      <button
                        onClick={() => handleOpenDeleteModal(role)}
                        className="text-red-600 dark:text-red-400 hover:text-red-900 dark:hover:text-red-200"
                        disabled={!role.is_active}
                      >
                        <TrashIcon className="h-5 w-5" />
                      </button>
                    </>
                  )}
                </td>
              </tr>
            ))}

            {(!roles || roles.length === 0) && (
              <tr>
                <td colSpan={5} className="px-6 py-4 text-center text-dm-text-muted">
                  No hay roles disponibles
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile Cards */}
      <div className="md:hidden space-y-4">
        {roles?.map((role) => (
          <div
            key={role.id}
            className="bg-dm-bg-primary rounded-xl shadow-sm border border-dm-border-primary p-4 transition-all hover:shadow-md"
          >
            <div className="flex items-start justify-between gap-3 mb-3">
              <div className="flex items-center gap-3 min-w-0">
                <div className="h-10 w-10 rounded-lg bg-dm-bg-secondary flex items-center justify-center text-dm-text-muted shrink-0">
                  <UserGroupIcon className="w-5 h-5" />
                </div>
                <div className="min-w-0">
                  <h3 className="text-sm font-bold text-dm-text-primary truncate">{role.name}</h3>
                  <p className="text-xs text-dm-text-muted truncate">{role.description || 'Sin descripción'}</p>
                </div>
              </div>
              <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full shrink-0 self-center ${
                role.is_active ? 'bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-300' : 'bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-300'
              }`}>
                {role.is_active ? 'Activo' : 'Inactivo'}
              </span>
            </div>

            {hasPermission('settings', 'roles', 'admin') && (
              <div className="flex items-center justify-end gap-2 border-t border-dm-border-primary pt-3">
                <button
                  onClick={() => handleOpenEditModal(role)}
                  className="flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-primary hover:bg-primary/10 rounded-lg transition-colors"
                >
                  <PencilIcon className="h-4 w-4" />
                  Editar
                </button>
                <button
                  onClick={() => handleOpenDeleteModal(role)}
                  className="flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors disabled:opacity-50"
                  disabled={!role.is_active}
                >
                  <TrashIcon className="h-4 w-4" />
                  Desactivar
                </button>
              </div>
            )}
          </div>
        ))}

        {(!roles || roles.length === 0) && (
          <div className="bg-dm-bg-primary rounded-xl shadow-sm border border-dm-border-primary py-14 text-center">
            <UserGroupIcon className="w-12 h-12 text-dm-text-muted mx-auto mb-4" />
            <p className="text-dm-text-muted">No hay roles disponibles</p>
          </div>
        )}
      </div>

      {/* Modal para crear rol */}
      <Modal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        title="Nuevo Rol"
        maxWidth="md"
      >
        <div className="p-6">
          <div className="space-y-4">
            <div>
              <Input
                label="Nombre del Rol *"
                type="text"
                value={roleName}
                onChange={(e) => {
                  setRoleName(e.target.value);
                  setRoleNameError('');
                }}
                error={roleNameError}
                placeholder="ej. admin, vendedor, almacenero"
              />
              <p className="mt-1 text-sm text-dm-text-muted">
                El nombre se convertirá automáticamente a minúsculas y los espacios se reemplazarán por guiones bajos (_)
              </p>
              {roleName && roleName !== formatRoleName(roleName) && (
                <p className="mt-1 text-sm text-blue-600 dark:text-blue-400">
                  Se guardará como: {formatRoleName(roleName)}
                </p>
              )}
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium text-dm-text-secondary mb-1">
                Descripción
              </label>
              <textarea
                className="block w-full rounded-md border-dm-border-primary shadow-sm p-2 border"
                value={roleDescription}
                onChange={(e) => setRoleDescription(e.target.value)}
                rows={3}
                placeholder="Descripción del rol y sus funciones"
              />
            </div>

            <div className="flex items-center">
              <input
                type="checkbox"
                id="is_active_create"
                checked={roleIsActive}
                onChange={(e) => setRoleIsActive(e.target.checked)}
                className="rounded border-dm-border-primary text-primary focus:ring-primary"
              />
              <label htmlFor="is_active_create" className="ml-2 text-sm text-dm-text-secondary">
                Rol Activo
              </label>
            </div>
          </div>

          <div className="flex justify-end space-x-3 mt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => setIsCreateModalOpen(false)}
            >
              Cancelar
            </Button>
            <Button
              type="button"
              onClick={handleCreateRole}
              isLoading={createRoleMutation.isPending}
            >
              Crear Rol
            </Button>
          </div>
        </div>
      </Modal>

      {/* Modal para editar rol */}
      <Modal
        isOpen={isEditModalOpen}
        onClose={() => setIsEditModalOpen(false)}
        title="Editar Rol"
        maxWidth="md"
      >
        <div className="p-6">
          <div className="space-y-4">
            <div>
              <Input
                label="Nombre del Rol *"
                type="text"
                value={roleName}
                onChange={(e) => {
                  setRoleName(e.target.value);
                  setRoleNameError('');
                }}
                error={roleNameError}
                placeholder="ej. admin, vendedor, almacenero"
              />
              <p className="mt-1 text-sm text-dm-text-muted">
                El nombre se convertirá automáticamente a minúsculas y los espacios se reemplazarán por guiones bajos (_)
              </p>
              {roleName && roleName !== formatRoleName(roleName) && (
                <p className="mt-1 text-sm text-blue-600 dark:text-blue-400">
                  Se guardará como: {formatRoleName(roleName)}
                </p>
              )}
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium text-dm-text-secondary mb-1">
                Descripción
              </label>
              <textarea
                className="block w-full rounded-md border-dm-border-primary shadow-sm p-2 border"
                value={roleDescription}
                onChange={(e) => setRoleDescription(e.target.value)}
                rows={3}
                placeholder="Descripción del rol y sus funciones"
              />
            </div>

            <div className="flex items-center">
              <input
                type="checkbox"
                id="is_active_edit"
                checked={roleIsActive}
                onChange={(e) => setRoleIsActive(e.target.checked)}
                className="rounded border-dm-border-primary text-primary focus:ring-primary"
              />
              <label htmlFor="is_active_edit" className="ml-2 text-sm text-dm-text-secondary">
                Rol Activo
              </label>
            </div>
          </div>

          <div className="flex justify-end space-x-3 mt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => setIsEditModalOpen(false)}
            >
              Cancelar
            </Button>
            <Button
              type="button"
              onClick={handleUpdateRole}
              isLoading={updateRoleMutation.isPending}
            >
              Actualizar Rol
            </Button>
          </div>
        </div>
      </Modal>

      {/* Modal para confirmar eliminación */}
      <Modal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        title="Confirmar Desactivación"
        maxWidth="sm"
      >
        <div className="p-6">
          <p className="mb-6">
            ¿Está seguro que desea desactivar el rol <strong>{selectedRole?.name}</strong>?
            Este rol no podrá ser asignado a nuevos usuarios.
          </p>

          <div className="flex justify-end space-x-3">
            <Button
              type="button"
              variant="outline"
              onClick={() => setIsDeleteModalOpen(false)}
            >
              Cancelar
            </Button>
            <Button
              type="button"
              variant="danger"
              onClick={handleDeleteRole}
              isLoading={deleteRoleMutation.isPending}
            >
              Desactivar
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

// src/features/settings/pages/WhatsAppConfigPage.tsx
import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { toast } from '@/utils/sileo-toast';
import {
  ChatBubbleLeftRightIcon,
  BuildingOffice2Icon,
  QrCodeIcon,
  CheckCircleIcon,
  ArrowPathIcon,
  PlusIcon,
  PhoneIcon,
  ExclamationTriangleIcon,
  SignalIcon,
  SignalSlashIcon,
  ShieldCheckIcon,
  ArrowsRightLeftIcon,
  LinkSlashIcon,
  DevicePhoneMobileIcon,
} from '@heroicons/react/24/outline';
import { useBranchOffices } from '../../../hooks/useBranchOffices';
import {
  useCreateWhatsAppInstance,
  useGetQRCode,
  useLogoutInstance,
  useRestartInstance,
  useWhatsAppEventPolling,
  useCheckConnectionStatus,
} from '../../../hooks/useWhatsAppConfig';
import { whatsappConfigService } from '../../../services/whatsappConfig.service';
import { BranchOffice } from '../../../types';
import { Button } from '../../../components/common/Button';
import { Spinner } from '../../../components/common/Spinner';
import { Modal } from '../../../components/common/Modal';

type ConnectionState = 'open' | 'close' | 'connecting' | 'unknown';

interface BranchWithStatus extends BranchOffice {
  connectionState?: ConnectionState;
  isLoading?: boolean;
}

export const WhatsAppConfigPage: React.FC = () => {
  const companyId = Number(localStorage.getItem('company_id')) || 1;

  // Estados
  const [selectedBranch, setSelectedBranch] = useState<BranchWithStatus | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showQRModal, setShowQRModal] = useState(false);
  const [showChangePhoneModal, setShowChangePhoneModal] = useState(false);
  const [qrCode, setQrCode] = useState<string | null>(null);
  const [newInstanceName, setNewInstanceName] = useState('');
  const [isChangingPhone, setIsChangingPhone] = useState(false);
  const [connectionStates, setConnectionStates] = useState<Record<string, ConnectionState>>({});
  const [checkingInstances, setCheckingInstances] = useState<Set<string>>(new Set());
  const [isCheckingAll, setIsCheckingAll] = useState(false);

  // Queries y mutations
  const { data: branchOffices = [], isLoading: loadingBranches, refetch: refetchBranches } = useBranchOffices(companyId);
  const createInstanceMutation = useCreateWhatsAppInstance();
  const getQRCodeMutation = useGetQRCode();
  const logoutMutation = useLogoutInstance();
  const restartMutation = useRestartInstance();
  const checkStatusMutation = useCheckConnectionStatus();

  const handleOpenCreateFromHeader = useCallback(() => {
    const branchWithoutInstance = branchOffices.find((branch) => !branch.whatsapp_instance_name);

    if (!branchWithoutInstance) {
      toast.info('Todas las sucursales ya tienen instancia de WhatsApp');
      return;
    }

    setSelectedBranch(branchWithoutInstance);
    setNewInstanceName(whatsappConfigService.generateInstanceName(branchWithoutInstance.name));
    setShowCreateModal(true);
  }, [branchOffices]);

  // Verificar estados de conexión para sucursales con instancia
  const checkConnectionStates = useCallback(async () => {
    const branchesWithInstance = branchOffices.filter(b => b.whatsapp_instance_name);
    const newStates: Record<string, ConnectionState> = {};

    setIsCheckingAll(true);

    // Usar Promise.all para verificar en paralelo
    await Promise.all(
      branchesWithInstance.map(async (branch) => {
        if (branch.whatsapp_instance_name) {
          try {
            const status = await whatsappConfigService.getConnectionStatus(branch.whatsapp_instance_name);
            newStates[branch.whatsapp_instance_name] = status.connection_state;
          } catch (error) {
            newStates[branch.whatsapp_instance_name] = 'unknown';
          }
        }
      })
    );

    setConnectionStates(newStates);
    setIsCheckingAll(false);
  }, [branchOffices]);

  // Verificar estado de una instancia individual
  const checkSingleInstanceStatus = useCallback(async (instanceName: string) => {
    setCheckingInstances(prev => new Set(prev).add(instanceName));

    try {
      const status = await checkStatusMutation.mutateAsync(instanceName);
      setConnectionStates(prev => ({
        ...prev,
        [instanceName]: status.connection_state
      }));

      // Mostrar mensaje según el estado
      if (status.is_connected) {
        toast.success(`${instanceName}: Conectado correctamente`);
      } else if (status.requires_qr) {
        toast.warning(`${instanceName}: Requiere escanear código QR`);
      } else {
        toast.info(`${instanceName}: ${status.message}`);
      }
    } catch (error) {
      setConnectionStates(prev => ({
        ...prev,
        [instanceName]: 'unknown'
      }));
      toast.error(`Error verificando ${instanceName}`);
    } finally {
      setCheckingInstances(prev => {
        const newSet = new Set(prev);
        newSet.delete(instanceName);
        return newSet;
      });
    }
  }, [checkStatusMutation]);

  // Callbacks memorizados para el polling de eventos
  const eventCallbacks = useMemo(() => ({
    onConnected: () => {
      toast.success('¡WhatsApp conectado exitosamente!');
      setShowQRModal(false);
      setQrCode(null);
      refetchBranches();
      checkConnectionStates();
    },
    onDisconnected: () => {
      // Solo informar si estamos esperando
    },
    onQRCodeUpdated: (newQR: string) => {
      // Actualizar el QR cuando el webhook notifique un nuevo código
      setQrCode(newQR);
      toast.info('El código QR se ha actualizado');
    },
    onError: (error: Error) => {
      void error;
    }
  }), [refetchBranches, checkConnectionStates]);

  // Hook de polling de eventos de WhatsApp
  const eventPolling = useWhatsAppEventPolling(
    selectedBranch?.whatsapp_instance_name || undefined,
    showQRModal, // Solo activo cuando el modal de QR está abierto
    eventCallbacks
  );

  useEffect(() => {
    if (branchOffices.length > 0) {
      checkConnectionStates();
      const interval = setInterval(checkConnectionStates, 15000); // Cada 15 segundos
      return () => clearInterval(interval);
    }
  }, [branchOffices, checkConnectionStates]);

  // Iniciar polling de eventos cuando se abre el modal de QR
  useEffect(() => {
    if (showQRModal && selectedBranch?.whatsapp_instance_name) {
      eventPolling.startPolling();
    } else {
      eventPolling.stopPolling();
    }
  }, [showQRModal, selectedBranch?.whatsapp_instance_name, eventPolling]);

  // Handlers
  const handleCreateInstance = async () => {
    if (!selectedBranch || !newInstanceName.trim()) {
      toast.error('Ingresa un nombre para la instancia');
      return;
    }

    try {
      const result = await createInstanceMutation.mutateAsync({
        instance_name: newInstanceName.trim(),
        branch_office_id: selectedBranch.id,
        integration: 'WHATSAPP-BAILEYS',
        qrcode: true,
      });

      setShowCreateModal(false);
      setNewInstanceName('');

      // Refrescar sucursales para obtener la nueva instancia
      await refetchBranches();

      // Actualizar el selectedBranch con el nuevo instance_name
      setSelectedBranch(prev => prev ? {
        ...prev,
        whatsapp_instance_name: newInstanceName.trim()
      } : null);

      if (result.qr_code) {
        setQrCode(result.qr_code);
        setShowQRModal(true);
        // El polling se inicia automáticamente al abrir el modal (via useEffect)
      }
    } catch (error) {
      void error;
    }
  };

  const handleGetQR = async (instanceName: string) => {
    try {
      const result = await getQRCodeMutation.mutateAsync(instanceName);
      setQrCode(result.qr_code);
      setShowQRModal(true);
      // El polling se inicia automáticamente al abrir el modal (via useEffect)
    } catch (error) {
      void error;
    }
  };

  const handleLogout = async (instanceName: string) => {
    try {
      await logoutMutation.mutateAsync(instanceName);
      checkConnectionStates();
    } catch (error) {
      void error;
    }
  };

  const handleRestart = async (instanceName: string) => {
    try {
      await restartMutation.mutateAsync(instanceName);
      checkConnectionStates();
    } catch (error) {
      void error;
    }
  };

  // Cambiar de teléfono: logout + nuevo QR
  const handleChangePhone = async () => {
    if (!selectedBranch?.whatsapp_instance_name) return;

    const instanceName = selectedBranch.whatsapp_instance_name;
    setIsChangingPhone(true);

    try {
      // Paso 1: Logout de la instancia actual
      await logoutMutation.mutateAsync(instanceName);

      // Paso 2: Esperar un momento para que el logout se procese
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Paso 3: Obtener nuevo QR
      const result = await getQRCodeMutation.mutateAsync(instanceName);

      // Paso 4: Cerrar modal de cambio y abrir modal de QR
      setShowChangePhoneModal(false);
      setQrCode(result.qr_code);
      setShowQRModal(true);
      // El polling se inicia automáticamente al abrir el modal (via useEffect)

      toast.info('Escanea el nuevo código QR con el teléfono que deseas vincular');
    } catch (error) {
      void error;
      toast.error('Error al cambiar de teléfono. Intenta nuevamente.');
    } finally {
      setIsChangingPhone(false);
    }
  };

  const getStatusBadge = (state: ConnectionState | undefined) => {
    switch (state) {
      case 'open':
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-300">
            <SignalIcon className="w-3 h-3 mr-1" />
            Conectado
          </span>
        );
      case 'connecting':
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-yellow-100 dark:bg-yellow-900/40 text-yellow-800 dark:text-yellow-300">
            <ArrowPathIcon className="w-3 h-3 mr-1 animate-spin" />
            Conectando
          </span>
        );
      case 'close':
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-300">
            <SignalSlashIcon className="w-3 h-3 mr-1" />
            Desconectado
          </span>
        );
      default:
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-dm-bg-secondary text-dm-text-primary">
            <ExclamationTriangleIcon className="w-3 h-3 mr-1" />
            Sin verificar
          </span>
        );
    }
  };

  // Estadísticas
  const branchesWithInstance = branchOffices.filter(b => b.whatsapp_instance_name);
  const connectedCount = Object.values(connectionStates).filter(s => s === 'open').length;

  const getBranchStatusMeta = (branch: BranchOffice, isChecking: boolean) => {
    if (!branch.whatsapp_instance_name) {
      return {
        label: 'Sin instancia',
        badgeClass: 'bg-dm-bg-secondary text-dm-text-secondary',
        dotClass: 'bg-slate-400',
      };
    }

    if (isChecking) {
      return {
        label: 'Verificando',
        badgeClass: 'bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300',
        dotClass: 'bg-blue-500',
      };
    }

    const state = connectionStates[branch.whatsapp_instance_name];
    switch (state) {
      case 'open':
        return {
          label: 'Conectado',
          badgeClass: 'bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-300',
          dotClass: 'bg-green-500',
        };
      case 'connecting':
        return {
          label: 'Conectando',
          badgeClass: 'bg-yellow-100 dark:bg-yellow-900/40 text-yellow-800 dark:text-yellow-300',
          dotClass: 'bg-yellow-500',
        };
      case 'close':
        return {
          label: 'Desconectado',
          badgeClass: 'bg-dm-bg-secondary text-dm-text-secondary',
          dotClass: 'bg-slate-500',
        };
      default:
        return {
          label: 'Sin verificar',
          badgeClass: 'bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300',
          dotClass: 'bg-red-500',
        };
    }
  };

  if (loadingBranches) {
    return (
      <div className="flex justify-center items-center h-64">
        <Spinner size="lg" />
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6 max-w-7xl mx-auto bg-dm-bg-secondary min-h-screen">
      <header className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 sm:gap-6 mb-8 sm:mb-10">
        <div className="flex-1">
          <h1 className="text-2xl sm:text-3xl lg:text-4xl font-extrabold tracking-tight text-dm-text-primary">
            Configuración de WhatsApp
          </h1>
        </div>
        <div className="flex shrink-0">
          <Button onClick={handleOpenCreateFromHeader} className="flex items-center justify-center gap-2 w-full sm:w-auto">
            <PlusIcon className="w-4 h-4" />
            <span>Crear Instancia</span>
          </Button>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
        <div className="bg-dm-bg-primary p-6 rounded-xl shadow-sm border border-dm-border-primary flex items-center gap-5">
          <div className="bg-primary/10 text-primary p-3 rounded-lg">
            <BuildingOffice2Icon className="w-7 h-7" />
          </div>
          <div>
            <p className="text-sm font-medium text-dm-text-muted uppercase tracking-wider">Total Sucursales</p>
            <p className="text-3xl font-bold text-dm-text-primary">{branchOffices.length}</p>
          </div>
        </div>

        <div className="bg-dm-bg-primary p-6 rounded-xl shadow-sm border border-dm-border-primary flex items-center gap-5">
          <div className="bg-green-100 dark:bg-green-900/40 text-green-600 dark:text-green-400 p-3 rounded-lg">
            <PhoneIcon className="w-7 h-7" />
          </div>
          <div>
            <p className="text-sm font-medium text-dm-text-muted uppercase tracking-wider">Con WhatsApp</p>
            <p className="text-3xl font-bold text-dm-text-primary">{branchesWithInstance.length}</p>
          </div>
        </div>

        <div className="bg-dm-bg-primary p-6 rounded-xl shadow-sm border border-dm-border-primary flex items-center gap-5">
          <div className="bg-blue-100 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 p-3 rounded-lg">
            <CheckCircleIcon className="w-7 h-7" />
          </div>
          <div>
            <p className="text-sm font-medium text-dm-text-muted uppercase tracking-wider">Conectadas</p>
            <p className="text-3xl font-bold text-dm-text-primary">{connectedCount}</p>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <div className="px-2">
          <h2 className="text-2xl font-bold text-dm-text-primary">Listado de Sucursales</h2>
        </div>

        {branchOffices.map((branch) => {
          const instanceName = branch.whatsapp_instance_name;
          const connectionState = instanceName ? connectionStates[instanceName] : undefined;
          const isCheckingThis = instanceName ? checkingInstances.has(instanceName) : false;
          const statusMeta = getBranchStatusMeta(branch, isCheckingThis);

          return (
            <div
              key={branch.id}
              className="bg-dm-bg-primary rounded-xl shadow-sm border border-dm-border-primary overflow-hidden transition-all hover:shadow-md"
            >
              <div className="p-4 sm:p-5 lg:p-6 flex flex-col lg:flex-row lg:items-center justify-between gap-4 sm:gap-6">
                <div className="flex items-center gap-3 sm:gap-4 min-w-0">
                  <div className="h-12 w-12 sm:h-14 sm:w-14 bg-dm-bg-secondary rounded-lg flex items-center justify-center text-dm-text-muted shrink-0">
                    <BuildingOffice2Icon className="w-6 h-6 sm:w-8 sm:h-8" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-col sm:flex-row sm:items-center gap-1.5 sm:gap-3">
                      <h3 className="text-base sm:text-lg font-bold text-dm-text-primary truncate">{branch.name}</h3>
                      <span className={`inline-flex items-center self-start sm:self-auto px-2.5 py-0.5 rounded-full text-xs font-medium ${statusMeta.badgeClass}`}>
                        <span className={`w-1.5 h-1.5 rounded-full ${statusMeta.dotClass} mr-1.5`} />
                        {statusMeta.label}
                      </span>
                    </div>
                    <p className="text-dm-text-muted text-sm flex items-center gap-1 mt-1 truncate">
                      <BuildingOffice2Icon className="w-4 h-4 shrink-0" />
                      <span className="truncate">{branch.port_name || branch.address_line || 'Sin dirección'}</span>
                    </p>
                  </div>
                </div>

                <div className="flex flex-wrap items-center justify-center sm:justify-end gap-3 sm:gap-4 lg:gap-6 border-t lg:border-t-0 pt-3 sm:pt-4 lg:pt-0 w-full lg:w-auto">
                  {instanceName ? (
                    <>
                      <button
                        onClick={() => checkSingleInstanceStatus(instanceName)}
                        disabled={isCheckingThis}
                        className="flex flex-col items-center gap-1 text-dm-text-secondary hover:text-primary transition-colors group disabled:opacity-60 min-w-[4rem]"
                        title="Verificar"
                      >
                        <div className="h-10 w-10 rounded-full bg-dm-bg-secondary flex items-center justify-center group-hover:bg-primary/10">
                          <ShieldCheckIcon className={`w-5 h-5 ${isCheckingThis ? 'animate-pulse' : ''}`} />
                        </div>
                        <span className="text-xs font-semibold text-center leading-tight">Verificar</span>
                      </button>

                      {connectionState !== 'open' && (
                        <button
                          onClick={() => {
                            setSelectedBranch({ ...branch, connectionState });
                            handleGetQR(instanceName);
                          }}
                          disabled={getQRCodeMutation.isPending}
                          className="flex flex-col items-center gap-1 text-primary hover:text-primary/80 transition-colors group disabled:opacity-60"
                        >
                          <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center group-hover:bg-primary/20">
                            <QrCodeIcon className="w-5 h-5" />
                          </div>
                          <span className="text-xs font-semibold">Conectar</span>
                        </button>
                      )}

                      {connectionState === 'open' && (
                        <>
                          <button
                            onClick={() => {
                              setSelectedBranch({ ...branch, connectionState });
                              setShowChangePhoneModal(true);
                            }}
                            className="flex flex-col items-center gap-1 text-dm-text-secondary hover:text-primary transition-colors group min-w-[4rem]"
                          >
                            <div className="h-10 w-10 rounded-full bg-dm-bg-secondary flex items-center justify-center group-hover:bg-primary/10">
                              <ArrowsRightLeftIcon className="w-5 h-5" />
                            </div>
                            <span className="text-xs font-semibold text-center leading-tight">Cambiar</span>
                          </button>

                          <button
                            onClick={() => handleLogout(instanceName)}
                            disabled={logoutMutation.isPending}
                            className="flex flex-col items-center gap-1 text-dm-text-secondary hover:text-orange-500 transition-colors group disabled:opacity-60 min-w-[4rem]"
                          >
                            <div className="h-10 w-10 rounded-full bg-dm-bg-secondary flex items-center justify-center group-hover:bg-orange-100 dark:group-hover:bg-orange-900/40">
                              <LinkSlashIcon className="w-5 h-5" />
                            </div>
                            <span className="text-xs font-semibold text-center leading-tight">Desconectar</span>
                          </button>
                        </>
                      )}

                      <button
                        onClick={() => handleRestart(instanceName)}
                        disabled={restartMutation.isPending}
                        className="flex flex-col items-center gap-1 text-dm-text-secondary hover:text-primary transition-colors group disabled:opacity-60 min-w-[4rem]"
                        title="Reiniciar"
                      >
                        <div className="h-10 w-10 rounded-full bg-dm-bg-secondary flex items-center justify-center group-hover:bg-primary/10">
                          <ArrowPathIcon className={`w-5 h-5 ${restartMutation.isPending ? 'animate-spin' : ''}`} />
                        </div>
                        <span className="text-xs font-semibold text-center leading-tight">Reiniciar</span>
                      </button>
                    </>
                  ) : (
                    <Button
                      onClick={() => {
                        setSelectedBranch(branch);
                        setNewInstanceName(whatsappConfigService.generateInstanceName(branch.name));
                        setShowCreateModal(true);
                      }}
                      className="whitespace-nowrap"
                      size="sm"
                    >
                      <PlusIcon className="w-4 h-4 mr-2" />
                      Crear Instancia
                    </Button>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {branchOffices.length === 0 && (
          <div className="bg-dm-bg-primary rounded-xl shadow-sm border border-dm-border-primary py-14 text-center">
            <BuildingOffice2Icon className="w-12 h-12 text-dm-text-muted mx-auto mb-4" />
            <p className="text-dm-text-muted">No hay sucursales configuradas</p>
          </div>
        )}
      </div>

      {/* Create Instance Modal */}
      <Modal
        isOpen={showCreateModal}
        onClose={() => {
          setShowCreateModal(false);
          setNewInstanceName('');
        }}
        title="Crear Nueva Instancia de WhatsApp"
      >
        <div className="space-y-4">
          <div>
            <p className="text-sm text-dm-text-secondary mb-4">
              Crear una instancia de WhatsApp para la sucursal: <strong>{selectedBranch?.name}</strong>
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium text-dm-text-secondary mb-1">
              Nombre de la Instancia
            </label>
            <input
              type="text"
              value={newInstanceName}
              onChange={(e) => setNewInstanceName(e.target.value.toUpperCase().replace(/[^A-Z0-9_]/g, '_'))}
              className="w-full px-3 py-2 border border-dm-border-primary rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 font-mono"
              placeholder="ej: [EMPRESA]_IQUITOS"
            />
            <p className="text-xs text-dm-text-muted mt-1">
              Solo letras mayúsculas, números y guiones bajos
            </p>
          </div>

          <div className="flex justify-end space-x-3 pt-4">
            <Button
              variant="outline"
              onClick={() => {
                setShowCreateModal(false);
                setNewInstanceName('');
              }}
            >
              Cancelar
            </Button>
            <Button
              onClick={handleCreateInstance}
              disabled={createInstanceMutation.isPending || !newInstanceName.trim()}
            >
              {createInstanceMutation.isPending ? (
                <>
                  <Spinner size="sm" className="mr-2" />
                  Creando...
                </>
              ) : (
                <>
                  <PlusIcon className="w-4 h-4 mr-2" />
                  Crear Instancia
                </>
              )}
            </Button>
          </div>
        </div>
      </Modal>

      {/* QR Code Modal */}
      <Modal
        isOpen={showQRModal}
        onClose={() => {
          setShowQRModal(false);
          setQrCode(null);
          eventPolling.reset();
        }}
        title="Escanea el Código QR"
        maxWidth="lg"
      >
        <div className="text-center space-y-4">
          <div className="bg-green-50 dark:bg-green-950/30 border border-green-200 dark:border-green-800/50 rounded-lg p-4 mb-4">
            <p className="text-sm text-green-800 dark:text-green-300">
              <strong>Instrucciones:</strong> Abre WhatsApp en tu teléfono → Configuración → Dispositivos vinculados → Vincular un dispositivo
            </p>
          </div>

          {qrCode ? (
            <div className="flex justify-center p-4 bg-dm-bg-primary rounded-lg border-2 border-dm-border-primary">
              <img
                src={qrCode}
                alt="QR Code"
                className="w-72 h-72"
              />
            </div>
          ) : getQRCodeMutation.isPending ? (
            <div className="flex justify-center items-center h-72">
              <Spinner size="lg" />
            </div>
          ) : (
            <div className="flex justify-center items-center h-72 text-dm-text-muted">
              <p>Error al cargar el código QR</p>
            </div>
          )}

          {eventPolling.isPolling && (
            <div className="flex items-center justify-center space-x-2 text-sm text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-950/30 p-3 rounded-lg">
              <ArrowPathIcon className="w-4 h-4 animate-spin" />
              <span>Esperando que escanees el código QR...</span>
            </div>
          )}

          <div className="flex justify-center space-x-3 pt-4">
            <Button
              variant="outline"
              onClick={() => {
                if (selectedBranch?.whatsapp_instance_name) {
                  handleGetQR(selectedBranch.whatsapp_instance_name);
                }
              }}
              disabled={getQRCodeMutation.isPending}
            >
              <ArrowPathIcon className="w-4 h-4 mr-2" />
              Regenerar QR
            </Button>
            <Button
              variant="outline"
              onClick={() => {
                setShowQRModal(false);
                setQrCode(null);
                eventPolling.reset();
              }}
            >
              Cerrar
            </Button>
          </div>
        </div>
      </Modal>

      {/* Change Phone Modal */}
      <Modal
        isOpen={showChangePhoneModal}
        onClose={() => !isChangingPhone && setShowChangePhoneModal(false)}
        title="Cambiar de Teléfono"
      >
        <div className="space-y-4">
          <div className="flex items-center space-x-3 p-4 bg-blue-50 dark:bg-blue-950/30 rounded-lg">
            <DevicePhoneMobileIcon className="w-6 h-6 text-blue-600 dark:text-blue-400 flex-shrink-0" />
            <p className="text-sm text-blue-700 dark:text-blue-300">
              Esta acción desvinculará el teléfono actual y generará un nuevo código QR para vincular otro dispositivo.
            </p>
          </div>

          <p className="text-sm text-dm-text-secondary">
            ¿Deseas cambiar el teléfono vinculado a la instancia{' '}
            <strong className="font-mono text-blue-600 dark:text-blue-400">{selectedBranch?.whatsapp_instance_name}</strong>{' '}
            de la sucursal <strong>{selectedBranch?.name}</strong>?
          </p>

          <div className="bg-yellow-50 dark:bg-yellow-950/30 border border-yellow-200 dark:border-yellow-800/50 rounded-lg p-3">
            <p className="text-xs text-yellow-800 dark:text-yellow-300">
              <strong>Nota:</strong> El teléfono actual perderá acceso inmediatamente. Tendrás que escanear el nuevo QR con el dispositivo que deseas vincular.
            </p>
          </div>

          <div className="flex justify-end space-x-3 pt-4">
            <Button
              variant="outline"
              onClick={() => setShowChangePhoneModal(false)}
              disabled={isChangingPhone}
            >
              Cancelar
            </Button>
            <Button
              onClick={handleChangePhone}
              disabled={isChangingPhone}
            >
              {isChangingPhone ? (
                <>
                  <Spinner size="sm" className="mr-2" />
                  Procesando...
                </>
              ) : (
                <>
                  <DevicePhoneMobileIcon className="w-4 h-4 mr-2" />
                  Cambiar Teléfono
                </>
              )}
            </Button>
          </div>
        </div>
      </Modal>

    </div>
  );
};

export default WhatsAppConfigPage;

// src/features/supervisor/pages/CancellationRequestsPage.tsx

import React, { useState, useEffect } from 'react';
import { toast } from '@/utils/sileo-toast';
import {
  BellAlertIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
  MagnifyingGlassIcon,
  InboxIcon,
  ShieldCheckIcon,
} from '@heroicons/react/24/outline';
import { useCancellationRequests } from '../../../hooks/useCancellationRequests';
import { cancellationRequestsService } from '../../accounting/services/cancellationRequests.service';
import {
  CancellationRequestListItem,
  CancellationRequestStatus,
} from '../../accounting/types/cancellationRequests';
import ApprovalModal from '../components/ApprovalModal';
import RejectionModal from '../components/RejectionModal';
import { Spinner } from '../../../components/common/Spinner';

const CancellationRequestsPage: React.FC = () => {
  const [statusFilter, setStatusFilter] = useState<CancellationRequestStatus | 'ALL'>('PENDING');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedRequest, setSelectedRequest] = useState<CancellationRequestListItem | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState(false);
  const [showRejectionModal, setShowRejectionModal] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);

  const {
    pendingRequests,
    allRequests,
    pendingCount,
    isLoading,
    error,
    fetchPendingRequests,
    fetchAllRequests,
    refresh,
  } = useCancellationRequests();

  // Escuchar eventos globales del WebSocket
  useEffect(() => {
    const handleCreated = () => refresh();
    const handleResolved = () => refresh();

    window.addEventListener('cancellation-request-created', handleCreated as EventListener);
    window.addEventListener('cancellation-request-resolved', handleResolved as EventListener);

    return () => {
      window.removeEventListener('cancellation-request-created', handleCreated as EventListener);
      window.removeEventListener('cancellation-request-resolved', handleResolved as EventListener);
    };
  }, [refresh]);

  // Cargar datos iniciales
  useEffect(() => {
    fetchPendingRequests();
    fetchAllRequests();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const getFilteredRequests = (): CancellationRequestListItem[] => {
    let base: CancellationRequestListItem[];
    if (statusFilter === 'PENDING') {
      base = pendingRequests;
    } else if (statusFilter === 'ALL') {
      base = allRequests;
    } else {
      base = allRequests.filter((req) => req.status === statusFilter);
    }
    if (!searchQuery.trim()) return base;
    const q = searchQuery.toLowerCase();
    return base.filter(
      (r) =>
        r.requester_name.toLowerCase().includes(q) ||
        `${r.series}-${r.number}`.toLowerCase().includes(q) ||
        (r.passenger_name || '').toLowerCase().includes(q)
    );
  };

  const filteredRequests = getFilteredRequests();

  const handleApprove = async (creditNoteSeries: string) => {
    if (!selectedRequest) return;
    try {
      setActionLoading(true);
      await cancellationRequestsService.approve(selectedRequest.id, {
        credit_note_series: creditNoteSeries,
      });
      toast.success(
        `Solicitud aprobada. Nota de Crédito ${creditNoteSeries} generada exitosamente.`
      );
      setShowApprovalModal(false);
      setSelectedRequest(null);
      await Promise.all([fetchPendingRequests(), fetchAllRequests()]);
      window.dispatchEvent(new CustomEvent('cancellation-request-resolved'));
    } catch (err: any) {
      const errorMessage =
        err?.response?.data?.detail || err?.message || 'Error al aprobar solicitud';
      toast.error(errorMessage);
    } finally {
      setActionLoading(false);
    }
  };

  const handleReject = async (reason: string) => {
    if (!selectedRequest) return;
    try {
      setActionLoading(true);
      await cancellationRequestsService.reject(selectedRequest.id, {
        rejection_reason: reason,
      });
      toast.success('Solicitud rechazada correctamente.');
      setShowRejectionModal(false);
      setSelectedRequest(null);
      await Promise.all([fetchPendingRequests(), fetchAllRequests()]);
      window.dispatchEvent(new CustomEvent('cancellation-request-resolved'));
    } catch (err: any) {
      const errorMessage =
        err?.response?.data?.detail || err?.message || 'Error al rechazar solicitud';
      toast.error(errorMessage);
    } finally {
      setActionLoading(false);
    }
  };

  const openApprovalModal = (request: CancellationRequestListItem) => {
    setSelectedRequest(request);
    setShowApprovalModal(true);
  };

  const openRejectionModal = (request: CancellationRequestListItem) => {
    setSelectedRequest(request);
    setShowRejectionModal(true);
  };

  const closeModals = () => {
    if (!actionLoading) {
      setShowApprovalModal(false);
      setShowRejectionModal(false);
      setSelectedRequest(null);
    }
  };

  const getStatusBadge = (status: CancellationRequestStatus) => {
    switch (status) {
      case 'PENDING':
        return (
          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-amber-50 dark:bg-amber-950/30 text-amber-700 dark:text-amber-300 border border-amber-100 dark:border-amber-900/40">
            <ClockIcon className="w-3 h-3" />
            Pendiente
          </span>
        );
      case 'APPROVED':
        return (
          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-emerald-50 dark:bg-emerald-950/30 text-emerald-700 dark:text-emerald-300 border border-emerald-100">
            <CheckCircleIcon className="w-3 h-3" />
            Aprobada
          </span>
        );
      case 'REJECTED':
        return (
          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-red-50 dark:bg-red-950/30 text-red-700 dark:text-red-300 border border-red-100">
            <XCircleIcon className="w-3 h-3" />
            Rechazada
          </span>
        );
    }
  };

  const getInitials = (name: string) =>
    name
      .split(' ')
      .slice(0, 2)
      .map((n) => n[0])
      .join('')
      .toUpperCase();

  const approvedCount = allRequests.filter((r) => r.status === 'APPROVED').length;
  const rejectedCount = allRequests.filter((r) => r.status === 'REJECTED').length;

  const FILTERS = [
    { value: 'PENDING' as const, label: 'Pendientes' },
    { value: 'APPROVED' as const, label: 'Aprobadas' },
    { value: 'REJECTED' as const, label: 'Rechazadas' },
    { value: 'ALL' as const, label: 'Todas' },
  ];

  const formatDate = (dateStr: string) => {
    const d = new Date(dateStr);
    return {
      date: d.toLocaleDateString('es-PE', { day: '2-digit', month: 'short', year: 'numeric' }),
      time: d.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' }),
    };
  };

  return (
    <div className="space-y-6">
      {/* ── Header ── */}
      <header>
        <div className="flex items-center gap-3 mb-2">
          <div className="flex items-center justify-center w-9 h-9 rounded-[8px] bg-[#1F4690]/10">
            <ShieldCheckIcon className="w-5 h-5 text-[#1F4690]" />
          </div>
          <h1 className="text-[22px] font-semibold text-dm-text-primary tracking-tight">
            Solicitudes de anulación
          </h1>
        </div>
        <p className="text-[14px] text-dm-text-muted max-w-2xl">
          Gestiona y revisa el estado de las solicitudes de anulación enviadas por los vendedores.
        </p>
      </header>

      {/* ── Stats ── */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-dm-bg-primary p-5 rounded-[12px] border border-dm-border-primary flex flex-col gap-2">
          <div className="flex items-center justify-between">
            <span className="text-[12px] font-medium text-dm-text-muted uppercase tracking-wider">
              Pendientes
            </span>
            <div className="w-8 h-8 rounded-[8px] bg-amber-50 dark:bg-amber-950/30 flex items-center justify-center">
              <ClockIcon className="w-4 h-4 text-amber-600 dark:text-amber-400" />
            </div>
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-[28px] font-bold text-dm-text-primary leading-none">{pendingCount}</span>
            {pendingCount > 0 && (
              <span className="text-[12px] font-medium text-amber-600 dark:text-amber-400">requieren atención</span>
            )}
          </div>
        </div>

        <div className="bg-dm-bg-primary p-5 rounded-[12px] border border-dm-border-primary flex flex-col gap-2">
          <div className="flex items-center justify-between">
            <span className="text-[12px] font-medium text-dm-text-muted uppercase tracking-wider">
              Aprobadas
            </span>
            <div className="w-8 h-8 rounded-[8px] bg-emerald-50 dark:bg-emerald-950/30 flex items-center justify-center">
              <CheckCircleIcon className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
            </div>
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-[28px] font-bold text-dm-text-primary leading-none">{approvedCount}</span>
            <span className="text-[12px] text-dm-text-muted">total</span>
          </div>
        </div>

        <div className="bg-dm-bg-primary p-5 rounded-[12px] border border-dm-border-primary flex flex-col gap-2">
          <div className="flex items-center justify-between">
            <span className="text-[12px] font-medium text-dm-text-muted uppercase tracking-wider">
              Rechazadas
            </span>
            <div className="w-8 h-8 rounded-[8px] bg-red-50 dark:bg-red-950/30 flex items-center justify-center">
              <XCircleIcon className="w-4 h-4 text-red-500 dark:text-red-400" />
            </div>
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-[28px] font-bold text-dm-text-primary leading-none">{rejectedCount}</span>
            <span className="text-[12px] text-dm-text-muted">total</span>
          </div>
        </div>
      </div>

      {/* ── Filtros y búsqueda ── */}
      <div className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary p-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex flex-wrap items-center gap-2">
            {FILTERS.map(({ value, label }) => (
              <button
                key={value}
                onClick={() => setStatusFilter(value)}
                className={`px-4 py-2 rounded-full text-[13px] font-medium transition-colors ${
                  statusFilter === value
                    ? 'bg-[#1F4690] text-white'
                    : 'bg-dm-bg-secondary text-dm-text-secondary hover:bg-dm-bg-hover'
                }`}
              >
                {label}
              </button>
            ))}
          </div>

          <div className="relative w-full md:w-80">
            <MagnifyingGlassIcon className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-dm-text-muted" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Buscar por vendedor o comprobante..."
              className="w-full pl-10 pr-4 py-2.5 text-[13px] text-dm-text-primary bg-dm-bg-secondary border border-dm-border-primary rounded-[12px] focus:outline-none focus:ring-2 focus:ring-[#1F4690]/20 focus:border-[#1F4690] transition-colors"
            />
          </div>
        </div>
      </div>

      {/* ── Error ── */}
      {error && (
        <div className="rounded-[12px] border border-red-200 dark:border-red-800/50 bg-red-50 dark:bg-red-950/40 p-4">
          <p className="text-[13px] text-red-700 dark:text-red-300">{error}</p>
        </div>
      )}

      {/* ── Tabla ── */}
      <div className="bg-dm-bg-primary rounded-[12px] border border-dm-border-primary overflow-hidden">
        {isLoading && filteredRequests.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-3">
            <Spinner size="lg" color="text-[#1F4690]" />
            <p className="text-[13px] text-dm-text-muted">Cargando solicitudes...</p>
          </div>
        ) : filteredRequests.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-4">
            <div className="flex items-center justify-center w-16 h-16 rounded-[20px] bg-dm-bg-secondary">
              <InboxIcon className="w-8 h-8 text-dm-text-muted" />
            </div>
            <div className="text-center">
              <p className="text-[15px] font-medium text-dm-text-primary">
                No hay solicitudes para mostrar
              </p>
              <p className="text-[13px] text-dm-text-muted mt-1">
                {searchQuery
                  ? `No se encontraron resultados para "${searchQuery}"`
                  : 'Las solicitudes aparecerán aquí cuando los vendedores las envíen.'}
              </p>
            </div>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-dm-bg-secondary border-b border-dm-border-primary">
                  <th className="px-6 py-3.5 text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider">
                    Vendedor
                  </th>
                  <th className="px-6 py-3.5 text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider">
                    Comprobante
                  </th>
                  <th className="px-6 py-3.5 text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider">
                    Pasajero
                  </th>
                  <th className="px-6 py-3.5 text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider">
                    Motivo
                  </th>
                  <th className="px-6 py-3.5 text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider">
                    Fecha
                  </th>
                  <th className="px-6 py-3.5 text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider">
                    Estado
                  </th>
                  <th className="px-6 py-3.5 text-[11px] font-semibold text-dm-text-muted uppercase tracking-wider text-right">
                    Acciones
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#f5f5f5]">
                {filteredRequests.map((request) => {
                  const { date, time } = formatDate(request.created_at);
                  return (
                    <tr key={request.id} className="hover:bg-dm-bg-secondary/60 transition-colors">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-[#1F4690]/10 flex items-center justify-center text-[#1F4690] font-bold text-[11px] flex-shrink-0">
                            {getInitials(request.requester_name)}
                          </div>
                          <span className="text-[13px] font-medium text-dm-text-primary">
                            {request.requester_name}
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-[13px] font-mono font-medium text-[#1F4690]">
                          {request.series}-{request.number}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-[13px] text-dm-text-secondary">
                        {request.passenger_name || (
                          <span className="text-dm-text-muted">—</span>
                        )}
                      </td>
                      <td className="px-6 py-4">
                        <p
                          className="text-[13px] text-dm-text-secondary max-w-xs truncate"
                          title={request.request_reason}
                        >
                          {request.request_reason}
                        </p>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className="text-[13px] text-dm-text-secondary">{date}</span>
                        <div className="text-[11px] text-dm-text-muted">{time}</div>
                      </td>
                      <td className="px-6 py-4">{getStatusBadge(request.status)}</td>
                      <td className="px-6 py-4 text-right">
                        {request.status === 'PENDING' ? (
                          <div className="flex items-center justify-end gap-2">
                            <button
                              onClick={() => openApprovalModal(request)}
                              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-[12px] font-medium text-emerald-700 dark:text-emerald-300 bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-100 rounded-full hover:bg-emerald-100 transition-colors"
                            >
                              <CheckCircleIcon className="w-3.5 h-3.5" />
                              Aprobar
                            </button>
                            <button
                              onClick={() => openRejectionModal(request)}
                              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-[12px] font-medium text-red-700 dark:text-red-300 bg-red-50 dark:bg-red-950/30 border border-red-100 rounded-full hover:bg-red-100 dark:hover:bg-red-900/40 transition-colors"
                            >
                              <XCircleIcon className="w-3.5 h-3.5" />
                              Rechazar
                            </button>
                          </div>
                        ) : (
                          <span className="text-[13px] text-dm-text-muted">—</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* Footer de tabla */}
        {filteredRequests.length > 0 && (
          <div className="px-6 py-3.5 bg-dm-bg-secondary border-t border-dm-border-primary">
            <p className="text-[12px] text-dm-text-muted">
              Mostrando {filteredRequests.length} resultado
              {filteredRequests.length !== 1 ? 's' : ''}
              {searchQuery && ` para "${searchQuery}"`}
            </p>
          </div>
        )}
      </div>

      {/* ── Modales ── */}
      {showApprovalModal && (
        <ApprovalModal
          request={selectedRequest}
          onClose={closeModals}
          onApprove={handleApprove}
          isLoading={actionLoading}
        />
      )}

      {showRejectionModal && (
        <RejectionModal
          request={selectedRequest}
          onClose={closeModals}
          onReject={handleReject}
          isLoading={actionLoading}
        />
      )}
    </div>
  );
};

export default CancellationRequestsPage;

