import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import fareService, { RouteGroupedFare, UpdateFareData } from '../services/fareService';
import { ServiceCategory } from '../types';

interface UseFaresByRouteParams {
  company_id: number;
  service_category?: ServiceCategory;
  route_id?: number;
  only_active_routes?: boolean;
}

export const useFaresByRoute = (params: UseFaresByRouteParams) => {
  const queryClient = useQueryClient();

  const {
    data: routeGroupedFares = [],
    isLoading,
    error,
    refetch
  } = useQuery<RouteGroupedFare[], Error>({
    queryKey: ['fares-by-route', params],
    queryFn: () => fareService.getFaresByRouteGrouped({
      ...params,
      skip: 0,
      limit: 100
    }),
    enabled: !!params.company_id,
  });

  const updateFareMutation = useMutation({
    mutationFn: ({ fareId, data }: { fareId: number; data: UpdateFareData }) =>
      fareService.updateFare(fareId, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['fares-by-route'] });
    },
  });

  const createFareMutation = useMutation({
    mutationFn: (data: any) => fareService.createFare(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['fares-by-route'] });
    },
  });

  return {
    routeGroupedFares,
    isLoading,
    error: error?.message,
    refetch,
    updateFare: updateFareMutation.mutateAsync,
    createFare: createFareMutation.mutateAsync,
    isUpdating: updateFareMutation.isPending,
    isCreating: createFareMutation.isPending,
  };
};

// src/hooks/useLocation.ts
import { useState, useEffect } from 'react';
import { UseFormSetValue } from 'react-hook-form';
// ...
import { geonamesService } from '../services/geonames.service';

interface LocationData {
  country_code?: string;
  department?: string;
  province?: string;
  district?: string;
}

interface UseLocationProps {
  setValue: UseFormSetValue<any>;
  initialData?: LocationData;
}

export const useLocation = ({ setValue, initialData }: UseLocationProps) => {
  const [isInitialized, setIsInitialized] = useState(false);

  // Inicializar datos si se proporcionan
  useEffect(() => {
    if (initialData && !isInitialized) {
      if (initialData.country_code) {
        setValue('country_code', initialData.country_code);
      }
      if (initialData.department) {
        setValue('department', initialData.department);
      }
      if (initialData.province) {
        setValue('province', initialData.province);
      }
      if (initialData.district) {
        setValue('district', initialData.district);
      }
      setIsInitialized(true);
    }
  }, [initialData, setValue, isInitialized]);

  const handleLocationChange = {
    onCountryChange: (countryCode: string) => {
      setValue('country_code', countryCode, { shouldValidate: true });
      // Limpiar campos dependientes
      setValue('department', '', { shouldValidate: true });
      setValue('province', '', { shouldValidate: true });
      setValue('district', '', { shouldValidate: true });
    },

    onDepartmentChange: (department: string) => {
      setValue('department', department, { shouldValidate: true });
      // Limpiar campos dependientes
      setValue('province', '', { shouldValidate: true });
      setValue('district', '', { shouldValidate: true });
    },

    onProvinceChange: (province: string) => {
      setValue('province', province, { shouldValidate: true });
      // Limpiar campos dependientes
      setValue('district', '', { shouldValidate: true });
    },

    onDistrictChange: (district: string) => {
      setValue('district', district, { shouldValidate: true });
    },
  };

  // Función para obtener la dirección formateada
  const getFormattedAddress = (data: LocationData): string => {
    const parts: string[] = [];

    if (data.district) parts.push(data.district);
    if (data.province) parts.push(data.province);
    if (data.department) parts.push(data.department);

    return parts.join(', ');
  };

  // Función para validar que la ubicación esté completa
  const validateLocation = (data: LocationData): boolean => {
    if (!data.country_code) return false;

    // Para Perú, requerir al menos departamento
    if (data.country_code === 'PE') {
      return !!data.department;
    }

    // Para otros países, al menos el departamento/estado
    return !!data.department;
  };

  // Función para obtener sugerencias de ubicación basadas en texto
  const searchLocation = async (query: string, countryCode?: string) => {
    try {
      if (query.length < 3) return [];

      const results = await geonamesService.searchPlaces(query, countryCode, 5);
      return results.map(place => ({
        value: place.geonameId,
        label: `${place.name}, ${place.adminName1}, ${place.countryName}`,
        country: place.countryCode,
        department: place.adminName1,
        province: place.adminName2,
        district: place.name,
      }));
    } catch (error) {
      console.error('Error searching locations:', error);
      return [];
    }
  };

  return {
    handleLocationChange,
    getFormattedAddress,
    validateLocation,
    searchLocation,
    isInitialized,
  };
};

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act, waitFor } from '@testing-library/react';

// ─── Mocks ───

const mockToastInfo = vi.fn();
const mockToastSuccess = vi.fn();
const mockToastWarning = vi.fn();

vi.mock('@/utils/sileo-toast', () => ({
  toast: {
    info: (...args: any[]) => mockToastInfo(...args),
    success: (...args: any[]) => mockToastSuccess(...args),
    warning: (...args: any[]) => mockToastWarning(...args),
  },
}));

vi.mock('../config/env', () => ({
  getWebSocketUrl: () => 'ws://localhost:8000',
  API_PREFIX: '/api/v1',
}));

class MockWebSocket {
  static CONNECTING = 0;
  static OPEN = 1;
  static CLOSING = 2;
  static CLOSED = 3;

  static instances: MockWebSocket[] = [];
  url: string;
  readyState = MockWebSocket.CONNECTING;
  onopen: ((ev?: Event) => void) | null = null;
  onclose: ((ev: CloseEvent) => void) | null = null;
  onmessage: ((ev: MessageEvent) => void) | null = null;
  onerror: ((ev?: Event) => void) | null = null;
  sentMessages: any[] = [];

  constructor(url: string) {
    this.url = url;
    MockWebSocket.instances.push(this);
  }

  send(data: string) {
    this.sentMessages.push(JSON.parse(data));
  }

  close(code = 1000, reason = '') {
    this.readyState = MockWebSocket.CLOSED;
    if (this.onclose) {
      this.onclose({ code, reason, wasClean: code === 1000 } as CloseEvent);
    }
  }

  simulateOpen() {
    this.readyState = MockWebSocket.OPEN;
    if (this.onopen) this.onopen();
  }

  simulateMessage(data: any) {
    if (this.onmessage) {
      this.onmessage({ data: JSON.stringify(data) } as MessageEvent);
    }
  }

  static clear() {
    MockWebSocket.instances = [];
  }

  static last(): MockWebSocket {
    return MockWebSocket.instances[MockWebSocket.instances.length - 1];
  }
}

Object.defineProperty(globalThis, 'WebSocket', {
  writable: true,
  value: MockWebSocket,
});

describe('useWebSocketNotifications', () => {
  const authToken = 'test-token-123';

  beforeEach(() => {
    MockWebSocket.clear();
    mockToastInfo.mockClear();
    mockToastSuccess.mockClear();
    mockToastWarning.mockClear();
    vi.useFakeTimers({ shouldAdvanceTime: true });
    localStorage.setItem('authToken', authToken);
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
    localStorage.clear();
  });

  const importHook = async () => {
    vi.resetModules();
    const mod = await import('./useWebSocketNotifications');
    return mod.useWebSocketNotifications;
  };

  it('does not connect when enabled is false', async () => {
    const useWebSocketNotifications = await importHook();
    renderHook(() => useWebSocketNotifications({ enabled: false }));
    expect(MockWebSocket.instances.length).toBe(0);
  });

  it('connects on mount and builds URL with token', async () => {
    const useWebSocketNotifications = await importHook();
    renderHook(() => useWebSocketNotifications({ enabled: true }));

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws = MockWebSocket.last();
    expect(ws.url).toContain('/api/v1/ws/notifications');
    expect(ws.url).toContain(`token=${encodeURIComponent(authToken)}`);
  });

  it('does not connect when token is missing', async () => {
    localStorage.removeItem('authToken');
    const useWebSocketNotifications = await importHook();
    renderHook(() => useWebSocketNotifications({ enabled: true }));

    // Allow any async effects to settle
    act(() => vi.advanceTimersByTime(500));
    expect(MockWebSocket.instances.length).toBe(0);
  });

  it('sets isConnected to true after open', async () => {
    const useWebSocketNotifications = await importHook();
    const { result } = renderHook(() => useWebSocketNotifications({ enabled: true }));

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws = MockWebSocket.last();

    expect(result.current.isConnected).toBe(false);
    act(() => ws.simulateOpen());
    expect(result.current.isConnected).toBe(true);
  });

  it('handles CANCELLATION_REQUEST_CREATED with toast, handler and custom event', async () => {
    const useWebSocketNotifications = await importHook();
    const onCreated = vi.fn();
    const dispatchSpy = vi.spyOn(window, 'dispatchEvent').mockImplementation(() => true);

    renderHook(() =>
      useWebSocketNotifications({
        enabled: true,
        onCancellationRequestCreated: onCreated,
      })
    );

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws = MockWebSocket.last();
    act(() => ws.simulateOpen());

    act(() =>
      ws.simulateMessage({
        type: 'CANCELLATION_REQUEST_CREATED',
        data: {
          id: 1,
          requesterName: 'Seller A',
          invoice: 'F001-123',
          message: 'New request',
          passenger_name: 'John Doe',
          trip_info: 'IQT-LIM',
        },
      })
    );

    expect(mockToastInfo).toHaveBeenCalledWith(
      expect.stringContaining('New request'),
      expect.objectContaining({ position: 'top-right' })
    );
    expect(onCreated).toHaveBeenCalledWith(expect.objectContaining({ id: 1, requesterName: 'Seller A' }));
    expect(dispatchSpy).toHaveBeenCalled();
    const dispatchedEvent = dispatchSpy.mock.calls[dispatchSpy.mock.calls.length - 1][0] as CustomEvent;
    expect(dispatchedEvent.type).toBe('cancellation-request-created');

    dispatchSpy.mockRestore();
  });

  it('handles CANCELLATION_REQUEST_RESOLVED APPROVED with success toast', async () => {
    const useWebSocketNotifications = await importHook();
    const onResolved = vi.fn();
    const dispatchSpy = vi.spyOn(window, 'dispatchEvent').mockImplementation(() => true);

    renderHook(() =>
      useWebSocketNotifications({
        enabled: true,
        onCancellationRequestResolved: onResolved,
      })
    );

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws = MockWebSocket.last();
    act(() => ws.simulateOpen());

    act(() =>
      ws.simulateMessage({
        type: 'CANCELLATION_REQUEST_RESOLVED',
        data: {
          id: 2,
          status: 'APPROVED',
          message: 'Approved!',
          credit_note_series: 'NC01',
          credit_note_number: 99,
        },
      })
    );

    expect(mockToastSuccess).toHaveBeenCalledWith(
      expect.stringContaining('Approved!'),
      expect.objectContaining({ autoClose: 6000 })
    );
    expect(onResolved).toHaveBeenCalledWith(expect.objectContaining({ id: 2, status: 'APPROVED' }));
    expect(dispatchSpy).toHaveBeenCalled();

    dispatchSpy.mockRestore();
  });

  it('handles CANCELLATION_REQUEST_RESOLVED REJECTED with warning toast', async () => {
    const useWebSocketNotifications = await importHook();

    renderHook(() => useWebSocketNotifications({ enabled: true }));

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws = MockWebSocket.last();
    act(() => ws.simulateOpen());

    act(() =>
      ws.simulateMessage({
        type: 'CANCELLATION_REQUEST_RESOLVED',
        data: {
          id: 3,
          status: 'REJECTED',
          message: 'Rejected!',
          rejection_reason: 'Too late',
        },
      })
    );

    expect(mockToastWarning).toHaveBeenCalledWith(
      expect.stringContaining('Rejected!'),
      expect.objectContaining({ autoClose: 8000 })
    );
  });

  it('reconnects automatically on unexpected close', async () => {
    const useWebSocketNotifications = await importHook();
    renderHook(() => useWebSocketNotifications({ enabled: true }));

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws1 = MockWebSocket.last();
    act(() => ws1.simulateOpen());

    act(() => ws1.close(1006));

    // Exponential backoff: 1000 * 2^0 = 1000
    act(() => vi.advanceTimersByTime(1500));
    await waitFor(() => expect(MockWebSocket.instances.length).toBe(2));
  });

  it('does not reconnect on auth error (code 1008)', async () => {
    const useWebSocketNotifications = await importHook();
    renderHook(() => useWebSocketNotifications({ enabled: true }));

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws1 = MockWebSocket.last();
    act(() => ws1.simulateOpen());

    act(() => ws1.close(1008));

    act(() => vi.advanceTimersByTime(60000));
    expect(MockWebSocket.instances.length).toBe(1);
  });

  it('PONG does not trigger toast or handlers', async () => {
    const useWebSocketNotifications = await importHook();
    renderHook(() => useWebSocketNotifications({ enabled: true }));

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws = MockWebSocket.last();
    act(() => ws.simulateOpen());

    act(() => ws.simulateMessage({ type: 'PONG' }));

    expect(mockToastInfo).not.toHaveBeenCalled();
    expect(mockToastSuccess).not.toHaveBeenCalled();
  });

  it('sends PING via heartbeat after open', async () => {
    const useWebSocketNotifications = await importHook();
    renderHook(() => useWebSocketNotifications({ enabled: true }));

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    const ws = MockWebSocket.last();
    act(() => ws.simulateOpen());

    act(() => vi.advanceTimersByTime(31000));
    expect(ws.sentMessages.some((m: any) => m.type === 'PING')).toBe(true);
  });

  it('cleans up connection listener on unmount', async () => {
    const useWebSocketNotifications = await importHook();
    const { unmount } = renderHook(() => useWebSocketNotifications({ enabled: true }));

    await waitFor(() => expect(MockWebSocket.instances.length).toBe(1));
    unmount();

    // After unmount, closing the socket should not throw
    const ws = MockWebSocket.last();
    expect(() => act(() => ws.close(1000))).not.toThrow();
  });
});

// src/hooks/useWebSocketNotifications.ts

import { useEffect, useRef, useCallback, useState } from 'react';
import { toast } from '@/utils/sileo-toast';
import { getWebSocketUrl as getWsBaseUrl, API_PREFIX } from '../config/env';

// Datos del evento cuando se crea una solicitud
interface CancellationRequestCreatedData {
  id: number;
  requesterName: string;
  invoice: string;
  message: string;
  requester_id?: string;
  request_reason?: string;
  passenger_name?: string;
  trip_info?: string;
  created_at?: string;
}

// Datos del evento cuando se resuelve una solicitud
interface CancellationRequestResolvedData {
  id: number;
  status: 'APPROVED' | 'REJECTED';
  message: string;
  rejection_reason?: string;
  credit_note_series?: string;
  credit_note_number?: number;
}

interface WebSocketMessage {
  type: 'PING' | 'PONG' | 'CANCELLATION_REQUEST_CREATED' | 'CANCELLATION_REQUEST_RESOLVED' | 'PAGO_DIGITAL_RECIBIDO' | string;
  data?: CancellationRequestCreatedData | CancellationRequestResolvedData | any;
  pago?: {
    monto?: number;
    nombre_emisor?: string;
    canal?: string;
  };
  invoice_id?: number | null;
  timestamp?: string;
}

interface UseWebSocketNotificationsOptions {
  onCancellationRequestCreated?: (data: CancellationRequestCreatedData) => void;
  onCancellationRequestResolved?: (data: CancellationRequestResolvedData) => void;
  enabled?: boolean;
}

// Singleton para evitar múltiples conexiones WebSocket
let globalWs: WebSocket | null = null;
let globalPingInterval: NodeJS.Timeout | null = null;
let connectionListeners: Set<(connected: boolean) => void> = new Set();
let messageHandlers: Map<string, Set<(data: any) => void>> = new Map();

export const useWebSocketNotifications = (options: UseWebSocketNotificationsOptions = {}) => {
  const {
    onCancellationRequestCreated,
    onCancellationRequestResolved,
    enabled = true
  } = options;

  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [reconnectAttempts, setReconnectAttempts] = useState(0);

  const getWebSocketUrl = () => {
    const token = localStorage.getItem('authToken');
    if (!token) {
      console.warn('[WebSocket] No se encontró token de autenticación');
      return null;
    }

    const wsBaseUrl = getWsBaseUrl();
    const wsUrl = `${wsBaseUrl}${API_PREFIX}/ws/notifications`;

    return `${wsUrl}?token=${encodeURIComponent(token)}`;
  };

  const sendPing = () => {
    if (globalWs && globalWs.readyState === WebSocket.OPEN) {
      globalWs.send(JSON.stringify({ type: 'PING' }));
    }
  };

  const handleGlobalMessage = (event: MessageEvent) => {
    try {
      const message: WebSocketMessage = JSON.parse(event.data);

      switch (message.type) {
        case 'PONG':
          // Heartbeat recibido
          break;

        case 'CANCELLATION_REQUEST_CREATED':
          if (message.data) {
            const data = message.data as CancellationRequestCreatedData;

            // Construir mensaje más informativo con los nuevos datos
            let toastMessage = data.message || `Nueva solicitud de anulación de ${data.requesterName}`;

            // Agregar información adicional si está disponible
            const details: string[] = [];
            if (data.invoice) details.push(`Comprobante: ${data.invoice}`);
            if (data.passenger_name) details.push(`Pasajero: ${data.passenger_name}`);
            if (data.trip_info) details.push(`Viaje: ${data.trip_info}`);

            if (details.length > 0) {
              toastMessage += '\n' + details.join(' | ');
            }

            toast.info(toastMessage, {
              position: 'top-right',
              autoClose: 6000,
            });

            const handlers = messageHandlers.get('CANCELLATION_REQUEST_CREATED');
            if (handlers) {
              handlers.forEach(handler => handler(data));
            }

            window.dispatchEvent(new CustomEvent('cancellation-request-created', { detail: data }));
          }
          break;

        case 'CANCELLATION_REQUEST_RESOLVED':
          if (message.data) {
            const data = message.data as CancellationRequestResolvedData;
            const isApproved = data.status === 'APPROVED';
            const toastFn = isApproved ? toast.success : toast.warning;

            // Construir mensaje más informativo
            let toastMessage = data.message || `Solicitud ${data.status}`;

            // Agregar información adicional
            if (isApproved && data.credit_note_series && data.credit_note_number) {
              toastMessage += `\nNota de Crédito: ${data.credit_note_series}-${data.credit_note_number}`;
            } else if (!isApproved && data.rejection_reason) {
              toastMessage += `\nMotivo: ${data.rejection_reason}`;
            }

            toastFn(toastMessage, {
              position: 'top-right',
              autoClose: isApproved ? 6000 : 8000,
            });

            const handlers = messageHandlers.get('CANCELLATION_REQUEST_RESOLVED');
            if (handlers) {
              handlers.forEach(handler => handler(data));
            }

            window.dispatchEvent(new CustomEvent('cancellation-request-resolved', { detail: data }));
          }
          break;

        case 'PAGO_DIGITAL_RECIBIDO': {
          const pago = (message as any).pago || message.data?.pago;
          if (pago) {
            const canal = pago.canal || 'YAPE';
            const monto = Number(pago.monto || 0).toFixed(2);
            const nombre = pago.nombre_emisor || 'cliente';
            toast.info(`${canal} S/ ${monto} de ${nombre}`, {
              position: 'top-right',
              autoClose: 5000,
            });
            window.dispatchEvent(new CustomEvent('pago-digital-recibido', { detail: pago }));
            const handlers = messageHandlers.get('PAGO_DIGITAL_RECIBIDO');
            if (handlers) {
              handlers.forEach((handler) => handler(pago));
            }
          }
          break;
        }

        default:
          break;
      }
    } catch (error) {
      console.error('[WebSocket] Error al procesar mensaje:', error);
    }
  };

  const connectGlobal = useCallback(() => {
    if (globalWs?.readyState === WebSocket.OPEN || globalWs?.readyState === WebSocket.CONNECTING) {
      setIsConnected(true);
      return;
    }

    const wsUrl = getWebSocketUrl();
    if (!wsUrl) {
      console.warn('[WebSocket] No se puede conectar: token no disponible');
      return;
    }

    try {
      globalWs = new WebSocket(wsUrl);

      globalWs.onopen = () => {
        setIsConnected(true);
        setReconnectAttempts(0);
        connectionListeners.forEach(listener => listener(true));

        if (globalPingInterval) {
          clearInterval(globalPingInterval);
        }
        globalPingInterval = setInterval(sendPing, 30000);
      };

      globalWs.onmessage = handleGlobalMessage;

      globalWs.onerror = () => {
        console.error('[WebSocket] Error de conexión');
      };

      globalWs.onclose = (event) => {
        setIsConnected(false);
        connectionListeners.forEach(listener => listener(false));

        if (globalPingInterval) {
          clearInterval(globalPingInterval);
          globalPingInterval = null;
        }

        // No reconectar si es error de autenticación
        if (event.code === 1008) {
          console.error('[WebSocket] Token inválido');
          globalWs = null;
          return;
        }

        // Reconectar con backoff exponencial
        if (reconnectAttempts < 5) {
          const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);

          reconnectTimeoutRef.current = setTimeout(() => {
            setReconnectAttempts(prev => prev + 1);
            connectGlobal();
          }, delay);
        } else {
          console.error('[WebSocket] Máximo de reintentos alcanzado');
          globalWs = null;
        }
      };
    } catch (error) {
      console.error('[WebSocket] Error al crear conexión:', error);
    }
  }, [reconnectAttempts]);

  // Registrar callbacks
  useEffect(() => {
    if (onCancellationRequestCreated) {
      if (!messageHandlers.has('CANCELLATION_REQUEST_CREATED')) {
        messageHandlers.set('CANCELLATION_REQUEST_CREATED', new Set());
      }
      messageHandlers.get('CANCELLATION_REQUEST_CREATED')!.add(onCancellationRequestCreated);
    }

    if (onCancellationRequestResolved) {
      if (!messageHandlers.has('CANCELLATION_REQUEST_RESOLVED')) {
        messageHandlers.set('CANCELLATION_REQUEST_RESOLVED', new Set());
      }
      messageHandlers.get('CANCELLATION_REQUEST_RESOLVED')!.add(onCancellationRequestResolved);
    }

    return () => {
      if (onCancellationRequestCreated) {
        messageHandlers.get('CANCELLATION_REQUEST_CREATED')?.delete(onCancellationRequestCreated);
      }
      if (onCancellationRequestResolved) {
        messageHandlers.get('CANCELLATION_REQUEST_RESOLVED')?.delete(onCancellationRequestResolved);
      }
    };
  }, [onCancellationRequestCreated, onCancellationRequestResolved]);

  // Conectar solo una vez
  useEffect(() => {
    if (!enabled) return;

    const onConnectionChange = (connected: boolean) => {
      setIsConnected(connected);
    };

    connectionListeners.add(onConnectionChange);

    if (!globalWs || globalWs.readyState === WebSocket.CLOSED) {
      connectGlobal();
    } else if (globalWs.readyState === WebSocket.OPEN) {
      setIsConnected(true);
    }

    return () => {
      connectionListeners.delete(onConnectionChange);

      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
        reconnectTimeoutRef.current = null;
      }
    };
  }, [enabled, connectGlobal]);

  return {
    isConnected,
    reconnectAttempts
  };
};

