// src/hooks/useWhatsAppConfig.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useEffect, useRef, useState, useCallback } from 'react';
import { toast } from '@/utils/sileo-toast';
import { 
  whatsappConfigService, 
  WhatsAppCreateInstanceRequest,
  WhatsAppStatusResponse,
  WhatsAppEventsResponse 
} from '../services/whatsappConfig.service';
import { getErrorMessage } from '../utils/errorHandler';

const QUERY_KEY = 'whatsappConfig';

/**
 * Hook para crear una instancia de WhatsApp
 */
export const useCreateWhatsAppInstance = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: WhatsAppCreateInstanceRequest) => 
      whatsappConfigService.createInstance(data),
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: [QUERY_KEY] });
      queryClient.invalidateQueries({ queryKey: ['branchOffices'] });
      if (result.qr_code) {
        toast.success('Instancia creada. Escanea el código QR para conectar.');
      } else {
        toast.success(result.message || 'Instancia creada exitosamente.');
      }
    },
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al crear la instancia de WhatsApp.');
      toast.error(message);
    },
  });
};

/**
 * Hook para obtener el código QR de una instancia
 */
export const useGetQRCode = () => {
  return useMutation({
    mutationFn: (instanceName: string) => 
      whatsappConfigService.getQRCode(instanceName),
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al obtener el código QR.');
      toast.error(message);
    },
  });
};

/**
 * Hook para obtener el estado de conexión de una instancia
 */
export const useConnectionStatus = (instanceName: string | undefined, enabled: boolean = true) => {
  return useQuery<WhatsAppStatusResponse, Error>({
    queryKey: [QUERY_KEY, 'status', instanceName],
    queryFn: () => whatsappConfigService.getConnectionStatus(instanceName!),
    enabled: !!instanceName && enabled,
    refetchInterval: enabled ? 10000 : false, // Verificar cada 10 segundos cuando enabled
    refetchIntervalInBackground: false,
    retry: 1,
  });
};

/**
 * Hook para verificar estado manualmente
 */
export const useCheckConnectionStatus = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (instanceName: string) => 
      whatsappConfigService.getConnectionStatus(instanceName),
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: [QUERY_KEY] });
      if (result.is_connected) {
        toast.success('WhatsApp conectado correctamente.');
      }
    },
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al verificar el estado.');
      toast.error(message);
    },
  });
};

/**
 * Hook para desconectar una instancia (logout)
 */
export const useLogoutInstance = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (instanceName: string) => 
      whatsappConfigService.logoutInstance(instanceName),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [QUERY_KEY] });
      toast.success('Sesión de WhatsApp cerrada correctamente.');
    },
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al cerrar la sesión.');
      toast.error(message);
    },
  });
};

/**
 * Hook para eliminar una instancia
 */
export const useDeleteWhatsAppInstance = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (instanceName: string) => 
      whatsappConfigService.deleteInstance(instanceName),
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: [QUERY_KEY] });
      queryClient.invalidateQueries({ queryKey: ['branchOffices'] });
      toast.success(result.message || 'Instancia eliminada correctamente.');
    },
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al eliminar la instancia.');
      toast.error(message);
    },
  });
};

/**
 * Hook para reiniciar una instancia
 */
export const useRestartInstance = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (instanceName: string) => 
      whatsappConfigService.restartInstance(instanceName),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [QUERY_KEY] });
      toast.success('Instancia reiniciada correctamente.');
    },
    onError: (error: any) => {
      const message = getErrorMessage(error, 'Error al reiniciar la instancia.');
      toast.error(message);
    },
  });
};

/**
 * Hook para obtener eventos de WhatsApp (para polling)
 */
export const useWhatsAppEvents = (instanceName: string | undefined, sinceTs?: string, enabled: boolean = true) => {
  return useQuery<WhatsAppEventsResponse, Error>({
    queryKey: [QUERY_KEY, 'events', instanceName, sinceTs],
    queryFn: () => whatsappConfigService.getEvents(instanceName!, sinceTs),
    enabled: !!instanceName && enabled,
    refetchInterval: 2500, // Polling cada 2.5 segundos
    retry: 1,
    staleTime: 0, // Siempre considerar los datos como stale para forzar refetch
  });
};

/**
 * Tipo para los callbacks del polling de eventos
 */
export interface WhatsAppEventPollingCallbacks {
  onConnected?: () => void;
  onDisconnected?: () => void;
  onQRCodeUpdated?: (qrCode: string) => void;
  onError?: (error: Error) => void;
}

/**
 * Hook avanzado para polling de eventos con callbacks
 * Maneja automáticamente la actualización del QR y la detección de conexión
 * 
 * Optimización: Usa since_ts del último evento recibido para evitar
 * procesar eventos duplicados y reducir carga de red
 */
export const useWhatsAppEventPolling = (
  instanceName: string | undefined,
  enabled: boolean = false,
  callbacks?: WhatsAppEventPollingCallbacks
) => {
  const [isPolling, setIsPolling] = useState(false);
  const [lastQRCode, setLastQRCode] = useState<string | null>(null);
  const [connectionState, setConnectionState] = useState<'open' | 'close' | 'connecting' | null>(null);

  // Usamos un ref para el timestamp que se actualiza con cada evento
  const lastEventTimestampRef = useRef<string | null>(null);
  const processedEventsRef = useRef<Set<string>>(new Set());

  // Contador para forzar re-fetch con nuevo timestamp
  const [fetchCounter, setFetchCounter] = useState(0);

  // Iniciar polling
  const startPolling = useCallback(() => {
    if (!instanceName) return;
    // Iniciar desde ahora, luego se actualizará con cada evento
    lastEventTimestampRef.current = new Date().toISOString();
    processedEventsRef.current.clear();
    setFetchCounter(0);
    setIsPolling(true);
  }, [instanceName]);

  // Detener polling
  const stopPolling = useCallback(() => {
    setIsPolling(false);
    lastEventTimestampRef.current = null;
  }, []);

  // Query de eventos - usa fetchCounter para invalidar cuando hay nuevos eventos
  const eventsQuery = useQuery<WhatsAppEventsResponse, Error>({
    queryKey: [QUERY_KEY, 'events-polling', instanceName, fetchCounter],
    queryFn: () => whatsappConfigService.getEvents(instanceName!, lastEventTimestampRef.current || undefined),
    enabled: !!instanceName && isPolling && enabled,
    refetchInterval: 3000, // Cada 3 segundos (un poco más ligero)
    retry: 2,
    staleTime: 0,
    // No refetch en focus/reconnect para evitar duplicados
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
  });

  // Procesar eventos cuando lleguen
  useEffect(() => {
    if (!eventsQuery.data?.events || !isPolling) return;

    const events = eventsQuery.data.events;
    let hasNewEvents = false;
    let latestTimestamp: string | null = null;

    for (const event of events) {
      // Crear un ID único para evitar procesar el mismo evento dos veces
      const eventId = `${event.type}-${event.timestamp}`;
      if (processedEventsRef.current.has(eventId)) continue;

      processedEventsRef.current.add(eventId);
      hasNewEvents = true;

      // Trackear el timestamp más reciente
      if (!latestTimestamp || event.timestamp > latestTimestamp) {
        latestTimestamp = event.timestamp;
      }

      // Procesar según el tipo de evento
      switch (event.type) {
        case 'connection.update':
          const state = event.data?.state as 'open' | 'close' | 'connecting' | undefined;
          if (state) {
            setConnectionState(state);

            if (state === 'open') {
              callbacks?.onConnected?.();
              // Auto-detener el polling cuando se conecta
              stopPolling();
            } else if (state === 'close') {
              callbacks?.onDisconnected?.();
            }
          }
          break;

        case 'qrcode.updated':
          const qrCode = event.data?.qrcode;
          if (qrCode && qrCode !== lastQRCode) {
            setLastQRCode(qrCode);
            callbacks?.onQRCodeUpdated?.(qrCode);
          }
          break;
      }
    }

    // Actualizar el timestamp para el próximo fetch si hubo eventos nuevos
    if (hasNewEvents && latestTimestamp) {
      lastEventTimestampRef.current = latestTimestamp;
      // Incrementar contador para que el próximo query use el nuevo timestamp
      setFetchCounter(prev => prev + 1);
    }
  }, [eventsQuery.data, isPolling, callbacks, lastQRCode, stopPolling]);

  // Manejar errores
  useEffect(() => {
    if (eventsQuery.error && isPolling) {
      callbacks?.onError?.(eventsQuery.error);
    }
  }, [eventsQuery.error, isPolling, callbacks]);

  return {
    isPolling,
    startPolling,
    stopPolling,
    lastQRCode,
    connectionState,
    eventsQuery,
    // Reset state
    reset: useCallback(() => {
      stopPolling();
      setLastQRCode(null);
      setConnectionState(null);
      processedEventsRef.current.clear();
      setFetchCounter(0);
    }, [stopPolling]),
  };
};

// src/services/auth.service.ts
import api from '../config/api';
import { User } from '../types';
import { cacheService } from './cache.service';

interface LoginCredentials {
  email: string;
  password: string;
}

interface LoginResponse {
  access_token: string;
  token_type: string;
  user?: User;
}

export const authService = {
  login: async (credentials: LoginCredentials): Promise<LoginResponse> => {
    try {
      // Utilizamos la forma de autenticación de OAuth2 que requiere la API
      const formData = new URLSearchParams();
      formData.append('username', credentials.email); // La API espera 'username' como correo
      formData.append('password', credentials.password);

      const response = await api.post<LoginResponse>('/auth/token', formData, {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'X-Skip-Auth-Redirect': '1'
        }
      });

      // Guardamos el token en localStorage
      localStorage.setItem('authToken', response.data.access_token);

      try {
        // Obtenemos los datos del usuario actual
        const userResponse = await api.get('/auth/me');
        localStorage.setItem('user', JSON.stringify(userResponse.data));

        return {
          ...response.data,
          user: userResponse.data
        };
      } catch (userError) {
        // Continuamos con el token aunque no se pueda obtener datos del usuario
        return response.data;
      }
    } catch (error) {
      throw error;
    }
  },

  logout: async (): Promise<void> => {
    try {
      const token = localStorage.getItem('authToken');
      if (token) {
        // 1. Llamar al backend para destruir la sesión y el token
        await api.post('/auth/logout');
      }
    } catch (error) {
      console.error('Error al cerrar sesión en el servidor:', error);
    } finally {
      // 2. Borrar datos locales SIEMPRE, incluso si el servidor falla
      localStorage.removeItem('authToken');
      localStorage.removeItem('user');

      // Limpieza completa de caché usando el servicio centralizado
      cacheService.clearAll({
        preserveKeys: [] // Por defecto, limpia todo
      });

      // Redirigir de vuelta a la página de login
      window.location.href = '/login';
    }
  },

  getCurrentUser: (): User | null => {
    const user = localStorage.getItem('user');
    return user ? JSON.parse(user) : null;
  },

  isAuthenticated: (): boolean => {
    return !!localStorage.getItem('authToken');
  },

  // Obtener el perfil del usuario actual
  getProfile: async (): Promise<User> => {
    const response = await api.get('/auth/me');
    return response.data;
  }
};

// src/services/cache.service.ts
/**
 * Servicio centralizado para manejo de caché y limpieza de datos de sesión
 */

import { queryClient } from '../App';

export interface CacheCleanupOptions {
  clearQueryClient?: boolean;
  preserveKeys?: string[];
}

export const cacheService = {
  /**
   * Limpia completamente todos los datos de localStorage y sessionStorage
   * relacionados con la sesión del usuario
   */
  clearAll: (options: CacheCleanupOptions = {}): void => {
    const { preserveKeys = [], clearQueryClient: shouldClearQueryClient = true } = options;

    // Limpiar React Query cache si está habilitado
    if (shouldClearQueryClient) {
      try {
        queryClient.clear();
      } catch (error) {
        // Silenciosamente manejar error de limpieza
      }
    }

    // Keys específicas de localStorage que deben limpiarse al logout
    const localStorageKeysToRemove = [
      // Autenticación
      'authToken',
      'user',
      'token',
      'userInfo',

      // Dashboard y UI
      'dashboard_expanded_menus',
      'dashboard_sidebar_hidden', 
      'dashboard_sidebar_scroll',

      // Punto de venta y sucursales
      'selectedSalesBranch',
      'lastSoldTripId',

      // Series de documentos
      'lastUsedBoletaSeries',
      'lastUsedFacturaSeries',
      'lastUsedCreditNoteSeries',
      'lastUsedDebitNoteSeries',

      // Series de cotizaciones (patrón dinámico)
      // Estas se limpiarán con el método de pattern matching
    ];

    // Limpiar keys específicas de localStorage
    localStorageKeysToRemove.forEach(key => {
      if (!preserveKeys.includes(key)) {
        localStorage.removeItem(key);
      }
    });

    // Limpiar keys con patrones específicos de localStorage
    const localStoragePatterns = [
      /^quotationSeries_branch_\d+$/, // Series de cotizaciones por sucursal
      /^lastUsed.*Series$/,           // Cualquier serie "lastUsed"
      /^selectedSalesBranch_.*$/,     // Variaciones de sucursal seleccionada
    ];

    cacheService.removeByPattern(localStorage, localStoragePatterns, preserveKeys);

    // Keys específicas de sessionStorage que deben limpiarse
    const sessionStorageKeysToRemove = [
      'debitNoteAffectedInvoice',
      'creditNoteAffectedInvoice',
      'tempFormData',
    ];

    sessionStorageKeysToRemove.forEach(key => {
      if (!preserveKeys.includes(key)) {
        sessionStorage.removeItem(key);
      }
    });

    // Limpiar keys con patrones específicos de sessionStorage
    const sessionStoragePatterns = [
      /^seat_reservations_trip_\d+$/,    // Reservas de asientos por viaje
      /^temp_session_\w+$/,             // Sesiones temporales
      /^seatSelection_.*$/,             // Selecciones de asientos
    ];

    cacheService.removeByPattern(sessionStorage, sessionStoragePatterns, preserveKeys);
  },

  /**
   * Remueve items de storage basado en patrones regex
   */
  removeByPattern: (storage: Storage, patterns: RegExp[], preserveKeys: string[] = []): void => {
    const keysToRemove: string[] = [];

    // Iterar sobre todas las keys del storage
    for (let i = 0; i < storage.length; i++) {
      const key = storage.key(i);
      if (key && !preserveKeys.includes(key)) {
        // Verificar si la key coincide con algún patrón
        const matchesPattern = patterns.some(pattern => pattern.test(key));
        if (matchesPattern) {
          keysToRemove.push(key);
        }
      }
    }

    // Remover las keys encontradas
    keysToRemove.forEach(key => {
      storage.removeItem(key);
    });
  },

  /**
   * Limpia solo datos específicos de autenticación
   */
  clearAuthData: (): void => {
    const authKeys = ['authToken', 'user', 'token', 'userInfo'];
    authKeys.forEach(key => localStorage.removeItem(key));
  },

  /**
   * Limpia solo datos de UI y preferencias del usuario
   */
  clearUIPreferences: (): void => {
    const uiKeys = [
      'dashboard_expanded_menus',
      'dashboard_sidebar_hidden',
      'dashboard_sidebar_scroll'
    ];
    uiKeys.forEach(key => localStorage.removeItem(key));
  },

  /**
   * Limpia solo datos de sesión operacional (punto de venta, reservas, etc.)
   */
  clearOperationalData: (): void => {
    // localStorage operacional
    const operationalKeys = [
      'selectedSalesBranch',
      'lastSoldTripId',
      'lastUsedBoletaSeries',
      'lastUsedFacturaSeries', 
      'lastUsedCreditNoteSeries',
      'lastUsedDebitNoteSeries'
    ];

    operationalKeys.forEach(key => localStorage.removeItem(key));

    // Limpiar sessionStorage operacional
    cacheService.removeByPattern(sessionStorage, [
      /^seat_reservations_trip_\d+$/,
      /^temp_session_\w+$/,
      /^seatSelection_.*$/,
    ]);

    // Limpiar keys de series específicas de cotizaciones
    cacheService.removeByPattern(localStorage, [
      /^quotationSeries_branch_\d+$/
    ]);
  },

  /**
   * Obtiene información de debug sobre el estado actual del cache
   */
  getCacheInfo: (): { localStorage: string[]; sessionStorage: string[]; total: number } => {
    const localStorageKeys: string[] = [];
    const sessionStorageKeys: string[] = [];

    // Obtener keys de localStorage
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) localStorageKeys.push(key);
    }

    // Obtener keys de sessionStorage  
    for (let i = 0; i < sessionStorage.length; i++) {
      const key = sessionStorage.key(i);
      if (key) sessionStorageKeys.push(key);
    }

    return {
      localStorage: localStorageKeys.sort(),
      sessionStorage: sessionStorageKeys.sort(),
      total: localStorageKeys.length + sessionStorageKeys.length
    };
  }
};

// src/services/companies.service.ts
import api from '../config/api';
import { Company, CompanyCreate, CompanyUpdate } from '../types';

// Definimos la interfaz para los filtros del listado
export interface CompanyListFilters {
  skip?: number;
  limit?: number;
  is_active?: boolean;
}

class CompaniesService {
  private readonly basePath = '/companies';

  // GET /companies/ (Listar)
  async getList(filters: CompanyListFilters = {}): Promise<Company[]> {
    const params = new URLSearchParams();
    if (filters.skip !== undefined) params.append('skip', String(filters.skip));
    if (filters.limit !== undefined) params.append('limit', String(filters.limit));
    if (filters.is_active !== undefined) params.append('is_active', String(filters.is_active));

    const response = await api.get<Company[]>(`${this.basePath}/`, { params });
    return response.data;
  }

  // GET /companies/{id} (Obtener uno)
  async getById(id: number): Promise<Company> {
    const response = await api.get<Company>(`${this.basePath}/${id}`);
    return response.data;
  }

  // POST /companies/ (Crear)
  async create(data: CompanyCreate): Promise<Company> {
    const response = await api.post<Company>(`${this.basePath}/`, data);
    return response.data;
  }

  // PATCH /companies/{id} (Actualizar)
  async update(id: number, data: CompanyUpdate): Promise<Company> {
    const response = await api.patch<Company>(`${this.basePath}/${id}`, data);
    return response.data;
  }

  // DELETE /companies/{id} (Desactivar - Borrado Lógico)
  async delete(id: number): Promise<Company> {
    const response = await api.delete<Company>(`${this.basePath}/${id}`);
    return response.data;
  }

  // --- MÉTODOS DE SUBIDA DE ARCHIVOS ---
  /**
   * Sube el logo de la empresa junto con los datos actuales de la empresa.
   * @param id ID de la empresa
   * @param file Archivo de logo
   * @param companyData Datos actuales de la empresa (CompanyUpdate o similar)
   */
  /**
   * Sube el logo de la empresa (y opcionalmente datos) usando PATCH y FormData, siguiendo la guía del backend.
   */
  async uploadLogo(id: number, file: File | undefined, companyData: any): Promise<{ logo_url: string }> {
    const formData = new FormData();
    // Agregar cada campo individualmente (no como JSON)
    Object.entries(companyData).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        formData.append(key, String(value));
      }
    });
    if (file) {
      formData.append('logo_file', file);
    }
    // No enviar Content-Type, dejar que el navegador lo ponga
    const response = await api.patch<{ logo_url: string }>(`${this.basePath}/${id}`, formData);
    return response.data;
  }

  async uploadCertificate(id: number, file: File, password?: string): Promise<{ certificate_path: string }> {
    const formData = new FormData();
    formData.append('certificate', file);
    if (password) {
      formData.append('password', password);
    }

    const response = await api.post<{ certificate_path: string }>(`${this.basePath}/${id}/certificate`, formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
    return response.data;
  }
}

export const companiesService = new CompaniesService();

// src/services/fareService.ts
import api from '../config/api';
import { Fare, ServiceCategory, FareType } from '../types';

export interface CreateFareData {
  company_id: number;
  origin_port_id: number;
  destination_port_id: number;
  service_category: ServiceCategory;
  price: number;
  currency_code: string;
  tax_category_code: string;
  description: string;
  fare_type: FareType;
  route_id?: number;
  is_active?: boolean;
  effective_date: string;
  expiration_date?: string;
}

export interface UpdateFareData {
  price?: number;
  currency_code?: string;
  tax_category_code?: string;
  description?: string;
  is_active?: boolean;
  expiration_date?: string | null;
}

export interface FareFilters {
  company_id: number;
  origin_port_id?: number;
  destination_port_id?: number;
  is_active?: boolean;
  skip?: number;
  limit?: number;
}

export interface FindFareParams {
  company_id: number;
  origin_port_id: number;
  destination_port_id: number;
  service_category: ServiceCategory;
  on_date?: string;
}

class FareService {
  async createFare(data: CreateFareData): Promise<Fare> {
    const response = await api.post('/config/fares/', data);
    return response.data;
  }

  async listFares(filters: FareFilters): Promise<Fare[]> {
    if (!filters.company_id) {
      throw new Error("El 'company_id' es requerido para listar tarifas.");
    }

    const params = new URLSearchParams({
      company_id: filters.company_id.toString(),
    });

    if (filters.origin_port_id !== undefined) {
      params.append('origin_port_id', filters.origin_port_id.toString());
    }
    if (filters.destination_port_id !== undefined) {
      params.append('destination_port_id', filters.destination_port_id.toString());
    }
    if (filters.is_active !== undefined) {
      params.append('is_active', filters.is_active.toString());
    }
    if (filters.skip !== undefined) {
      params.append('skip', filters.skip.toString());
    }
    if (filters.limit !== undefined) {
      params.append('limit', filters.limit.toString());
    } else {
      // Sin límite por defecto, cargar todos los registros
      params.append('limit', '10000');
    }

    const response = await api.get(`/config/fares/`, { params });
    return response.data;
  }

  async findFare(params: FindFareParams): Promise<Fare | null> {
    try {
      const response = await api.get(`/config/fares/find`, { params });
      return response.data;
    } catch (error: any) {
      if (error.response?.status === 404) {
        return null;
      }
      throw error;
    }
  }

  async updateFare(fareId: number, data: UpdateFareData): Promise<Fare> {
    const response = await api.patch(`/config/fares/${fareId}`, data);
    return response.data;
  }

  async deactivateFare(fareId: number): Promise<Fare> {
    console.log(`Desactivando tarifa con ID: ${fareId}`);
    return this.updateFare(fareId, { is_active: false });
  }

  async createBatchFares(fares: CreateFareData[]): Promise<Fare[]> {
    const promises = fares.map(fare => this.createFare(fare));
    return Promise.all(promises);
  }

  async getMissingFaresForRoute(
    routeId: number,
    companyId: number,
    portIds: number[],
    serviceCategories: ServiceCategory[]
  ): Promise<{ origin_port_id: number; destination_port_id: number; service_category: ServiceCategory }[]> {
    const existingFares = await this.listFares({
      company_id: companyId,
      is_active: true,
      limit: 2000
    });

    const missingCombinations: { origin_port_id: number; destination_port_id: number; service_category: ServiceCategory }[] = [];

    for (let i = 0; i < portIds.length; i++) {
      for (let j = i + 1; j < portIds.length; j++) {
        for (const category of serviceCategories) {
          const originId = portIds[i];
          const destinationId = portIds[j];

          const exists = existingFares.some(fare =>
            fare.origin_port_id === originId &&
            fare.destination_port_id === destinationId &&
            fare.service_category === category &&
            fare.route_id === routeId
          );

          if (!exists) {
            missingCombinations.push({
              origin_port_id: originId,
              destination_port_id: destinationId,
              service_category: category
            });
          }
        }
      }
    }

    return missingCombinations;
  }

  async getFaresByRoute(routeId: number, companyId: number): Promise<Fare[]> {
    const allFares = await this.listFares({
      company_id: companyId,
      is_active: true,
      limit: 1000
    });

    return allFares.filter(fare => fare.route_id === routeId);
  }

  async cloneFaresFromRoute(
    sourceRouteId: number,
    targetRouteId: number,
    companyId: number,
    portMapping?: { [sourcePortId: number]: number }
  ): Promise<Fare[]> {
    const sourceFares = await this.getFaresByRoute(sourceRouteId, companyId);

    const newFares: CreateFareData[] = sourceFares.map(fare => ({
      company_id: companyId,
      origin_port_id: portMapping ? (portMapping[fare.origin_port_id] || fare.origin_port_id) : fare.origin_port_id,
      destination_port_id: portMapping ? (portMapping[fare.destination_port_id] || fare.destination_port_id) : fare.destination_port_id,
      service_category: fare.service_category,
      price: fare.price,
      currency_code: fare.currency_code,
      tax_category_code: fare.tax_category_code,
      description: fare.description || '',
      fare_type: fare.fare_type,
      route_id: targetRouteId,
      is_active: true,
      effective_date: new Date().toISOString().split('T')[0],
      expiration_date: fare.expiration_date
    }));

    return this.createBatchFares(newFares);
  }

  async saveFareMatrix(
    faresToCreate: CreateFareData[],
    faresToUpdate: { fareId: number; data: UpdateFareData }[]
  ): Promise<{ created: Fare[]; updated: Fare[] }> {
    const createPromises = faresToCreate.map(data => this.createFare(data));
    const updatePromises = faresToUpdate.map(item => this.updateFare(item.fareId, item.data));

    const [created, updated] = await Promise.all([
      Promise.all(createPromises),
      Promise.all(updatePromises),
    ]);

    return { created, updated };
  }

  /**
   * Obtiene las tarifas agrupadas por ruta
   */
  async getFaresByRouteGrouped(params: {
    company_id: number;
    service_category?: ServiceCategory;
    route_id?: number;
    only_active_routes?: boolean;
    skip?: number;
    limit?: number;
  }): Promise<RouteGroupedFare[]> {
    const response = await api.get('/config/fares/by-route', { params });
    return response.data;
  }
}

export interface RouteSegmentFare {
  stop_order: number;
  to_port_id: number;
  to_port_name: string;
  price: number | null;
  currency_code: string | null;
  label: string;
  fare_id: number | null;
  fare_type: FareType | null;
  tax_category_code: string | null;
  effective_date: string | null;
  expiration_date: string | null;
  is_route_specific: boolean;
