import axios from 'axios';

const GEONAMES_USERNAME = 'zeltux';
const GEONAMES_BASE_URL = 'http://api.geonames.org';

// Interfaces para los datos de GeoNames
export interface Country {
  geonameId: number;
  countryCode: string;
