export const routesService = {
  getAll: async (params: RouteListParams): Promise<Route[]> => {
    const response = await api.get<Route[]>('/config/routes/', { params });
    return response.data;
  },

  getById: async (routeId: number): Promise<RouteWithStops> => {
    const response = await api.get<RouteWithStops>(`/config/routes/${routeId}`);
    return response.data;
  },

  create: async (routeData: RouteCreateData): Promise<RouteWithStops> => {
    // Excluimos el campo de UI 'estimated_duration_hours' antes de enviarlo
    const { estimated_duration_hours, ...payload } = routeData;
    const response = await api.post<RouteWithStops>('/config/routes/', payload);
    return response.data;
  },

  update: async (routeId: number, routeData: RouteUpdateData): Promise<Route> => {
    // Excluimos el campo de UI 'estimated_duration_hours' antes de enviarlo
    const { estimated_duration_hours, ...payload } = routeData;
    const response = await api.patch<Route>(`/config/routes/${routeId}`, payload);
    return response.data;
  },

  delete: async (routeId: number): Promise<Route> => {
    // Borrado lógico. El backend debería cambiar is_active a false.
    const response = await api.delete<Route>(`/config/routes/${routeId}`);
    return response.data;
  },

  updateStops: async (routeId: number, stops: RouteStopCreateData[]): Promise<RouteStop[]> => {
    const response = await api.put<RouteStop[]>(`/config/routes/${routeId}/stops`, stops);
    return response.data;
  },

  syncTripStops: async (routeId: number, mode: string = 'append_new'): Promise<string> => {
    const response = await api.post<string>(`/config/routes/${routeId}/sync-trip-stops`, null, {
      params: { mode }
    });
    return response.data;
  }
};

// ========================================
// HELPERS (Lógica de conversión de duración)
// ========================================

export const routeHelpers = {
  hoursToISOString: (totalHours: number): string => {
    if (isNaN(totalHours) || totalHours <= 0) return "PT0S";

    const days = Math.floor(totalHours / 24);
    const remainingHours = Math.floor(totalHours) % 24;
    const minutes = Math.round((totalHours % 1) * 60);

    let duration = "P";
    if (days > 0) duration += `${days}D`;

    let timePart = "T";
    if (remainingHours > 0) timePart += `${remainingHours}H`;
    if (minutes > 0) timePart += `${minutes}M`;

    if (timePart === "T") {
      return duration === "P" ? "PT0S" : duration;
    }

    return duration + timePart;
  },

  isoStringToHours: (isoString: string | undefined | null): number => {
    if (!isoString || isoString === "PT0S") return 0;

    const regex = /P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?/;
    const matches = isoString.match(regex);
    if (!matches) return 0;

    const days = parseInt(matches[1] || '0');
    const hours = parseInt(matches[2] || '0');
    const minutes = parseInt(matches[3] || '0');

    return (days * 24) + hours + (minutes / 60);
  },

  generateBasicStops: (originPortId: number, destinationPortId: number, totalDurationHours: number): RouteStopCreateData[] => {
    return [
      {
        port_id: originPortId,
        stop_order: 1,
        estimated_duration_from_origin: 'PT0S',
        is_boarding_allowed: true,
        is_disembarking_allowed: false,
        notes: 'Origen'
      },
      {
        port_id: destinationPortId,
        stop_order: 2,
        estimated_duration_from_origin: routeHelpers.hoursToISOString(totalDurationHours),
        is_boarding_allowed: false,
        is_disembarking_allowed: true,
        notes: 'Destino'
      }
    ];
  },

  getCurrentCompanyId: (): number => {
    const userInfo = localStorage.getItem('userInfo');
    if (userInfo) {
      try {
        const user = JSON.parse(userInfo);
        return user.company_id || 1;
      } catch (e) {
        return 1;
      }
    }
    return 1;
  }
};

// ========================================
// VALIDACIONES (Manteniendo las validaciones originales)
// ========================================

export const routeValidations = {
  validatePorts: (originPortId: number, destinationPortId: number): string | null => {
    if (originPortId === destinationPortId) {
      return 'El puerto de origen y destino deben ser diferentes';
    }
    return null;
  },

  validateStops: (stops: RouteStopCreateData[], originPortId: number, destinationPortId: number): string[] => {
    const errors: string[] = [];

    if (stops.length === 0) {
      errors.push('La ruta debe tener al menos las paradas de origen y destino');
      return errors;
    }

    if (stops[0].port_id !== originPortId) {
      errors.push('La primera parada debe ser el puerto de origen');
    }

    if (stops[stops.length - 1].port_id !== destinationPortId) {
      errors.push('La última parada debe ser el puerto de destino');
    }

    const orders = stops.map(s => s.stop_order);
    const sortedOrders = [...orders].sort((a, b) => a - b);
    if (JSON.stringify(orders) !== JSON.stringify(sortedOrders)) {
      errors.push('El orden de las paradas debe ser secuencial');
    }

    for (let i = 1; i < stops.length; i++) {
      if (stops[i].port_id === stops[i - 1].port_id) {
        errors.push(`Puerto duplicado en paradas consecutivas ${i} y ${i + 1}`);
      }
    }

    stops.forEach((stop, index) => {
      if (index === 0 && stop.is_disembarking_allowed) {
        errors.push('No se permite desembarque en el puerto de origen');
      }
      if (index === stops.length - 1 && stop.is_boarding_allowed) {
        errors.push('No se permite embarque en el puerto de destino');
      }
    });

    stops.forEach((stop, index) => {
      if (stop.estimated_duration_from_origin) {
        if (index === 0 && stop.estimated_duration_from_origin !== 'PT0S') {
          errors.push('La duración desde el origen en la primera parada debe ser PT0S');
        }

        const durationPattern = /^PT(\d+H)?(\d+M)?(\d+S)?$/;
        if (!durationPattern.test(stop.estimated_duration_from_origin)) {
          errors.push(`Formato de duración inválido en parada ${index + 1}. Use formato ISO 8601 Duration`);
        }
      }
    });

    return errors;
  }
};

// src/services/seatReservation.service.ts
import api from '../config/api';

export interface TempSeatReservation {
  trip_id: number;
  seat_number: string;
  reserved_for: string; // Identificador temporal (ej: "temp_representative_1")
  duration_minutes?: number; // Duración de la reserva temporal (default: 10 min)
}

export interface SeatReservationResponse {
  success: boolean;
  reservation_id?: string;
  expires_at?: string;
  message?: string;
}

class SeatReservationService {
  // Crear reserva temporal para un asiento
  async createTempReservation(data: TempSeatReservation): Promise<SeatReservationResponse> {
    try {
      const response = await api.post('/operations/seats/temp-reserve', {
        ...data,
        duration_minutes: data.duration_minutes || 10 // 10 minutos por defecto
      });
      return response.data;
    } catch (error: any) {
      console.error('Error creando reserva temporal:', error);
      throw new Error(error.response?.data?.message || 'Error al reservar asiento temporalmente');
    }
  }

  // Liberar reserva temporal
  async releaseTempReservation(tripId: number, seatNumber: string): Promise<void> {
    try {
      await api.delete(`/operations/seats/temp-reserve/${tripId}/${seatNumber}`);
    } catch (error: any) {
      console.error('Error liberando reserva temporal:', error);
      // No lanzamos error aquí para no interrumpir el flujo
    }
  }

  // Confirmar reservas temporales (convertir a definitivas)
  async confirmTempReservations(tripId: number, seatNumbers: string[]): Promise<void> {
    try {
      await api.post(`/operations/seats/confirm-temp-reservations`, {
        trip_id: tripId,
        seat_numbers: seatNumbers
      });
    } catch (error: any) {
      console.error('Error confirmando reservas:', error);
      throw new Error(error.response?.data?.message || 'Error al confirmar reservas de asientos');
    }
  }

  // Liberar todas las reservas temporales de un viaje para un usuario
  async releaseAllTempReservations(tripId: number, reservedFor: string): Promise<void> {
    try {
      await api.delete(`/operations/seats/temp-reserve-all/${tripId}/${reservedFor}`);
    } catch (error: any) {
      console.error('Error liberando todas las reservas temporales:', error);
    }
  }

  // Extender tiempo de reserva temporal
  async extendTempReservation(tripId: number, seatNumber: string, additionalMinutes: number = 5): Promise<void> {
    try {
      await api.patch(`/operations/seats/temp-reserve/${tripId}/${seatNumber}/extend`, {
        additional_minutes: additionalMinutes
      });
    } catch (error: any) {
      console.error('Error extendiendo reserva temporal:', error);
      throw new Error('Error al extender tiempo de reserva');
    }
  }
}

export const seatReservationService = new SeatReservationService();

// src/services/seatValidation.service.ts
import api from '../config/api';

export interface SeatValidationResponse {
  isAvailable: boolean;
  reason?: string;
  conflictDetails?: {
    occupiedBy: string;
    occupiedAt: string;
    invoiceNumber?: string;
  };
}

export interface ValidateSeatRequest {
  tripId: number;
  seatId: number;
  userId: string;
}

class SeatValidationService {
  private basePath = '/seat-validation';

  /**
   * Valida si un asiento está disponible antes de proceder con la venta
   */
  async validateSeatAvailability(request: ValidateSeatRequest): Promise<SeatValidationResponse> {
    try {
      const response = await api.post<SeatValidationResponse>(
        `${this.basePath}/validate`,
        request
      );
      return response.data;
    } catch (error: any) {
      console.error('Error validando disponibilidad del asiento:', error);

      // Si hay error del servidor, interpretamos la respuesta
      if (error.response?.status === 409) {
        // Conflicto - asiento ya ocupado
        return {
          isAvailable: false,
          reason: error.response.data?.message || 'El asiento seleccionado ya no está disponible',
          conflictDetails: error.response.data?.conflictDetails
        };
      }

      throw error;
    }
  }

  /**
   * Reserva temporalmente un asiento por unos minutos durante el proceso de venta
   * NOTA: El backend no tiene endpoint separado para reserva temporal,
   * la validación maneja esto internamente
   */
  async reserveSeatTemporarily(request: ValidateSeatRequest): Promise<{ success: boolean; expiresAt?: string }> {
    try {
      // El backend maneja la reserva temporal durante la validación
      // Por ahora, simplemente validamos nuevamente
      const validation = await this.validateSeatAvailability(request);
      return { 
        success: validation.isAvailable,
        expiresAt: validation.isAvailable ? new Date(Date.now() + 5 * 60 * 1000).toISOString() : undefined
      };
    } catch (error: any) {
      console.error('Error en reserva temporal (usando validación):', error);
      return { success: false };
    }
  }

  /**
   * Libera una reserva temporal de asiento
   */
  async releaseSeatReservation(request: ValidateSeatRequest): Promise<{ success: boolean }> {
    try {
      const response = await api.post<{ success: boolean }>(
        `${this.basePath}/release-reservation`,
        {
          tripId: request.tripId,
          seatId: request.seatId
          // Nota: userId no es requerido por el backend según las instrucciones
        }
      );
      return response.data;
    } catch (error: any) {
      console.error('Error liberando reserva temporal:', error);
      return { success: false };
    }
  }
}

export const seatValidationService = new SeatValidationService();

// src/services/trips.service.ts
import api from '../config/api';
import { Trip, AvailableTrip, TripStop, Vessel, TripSeatAvailability, SeatMapItem, PreviewVesselChangeRequest, PreviewVesselChangeResponse } from '../types';
import { AxiosRequestConfig } from 'axios';
import { stringify } from 'qs';

export interface CreateTripData {
  company_id: number;
  route_id: number;
  vessel_id: number;
  departure_datetime: string; // ISO datetime
  can_sell_tickets?: boolean;
  notes?: string;
  trip_name?: string;
  captain_user_id?: string;
}

export interface UpdateTripData {
  vessel_id?: number;
  departure_datetime?: string;
  status?: string;
  captain_user_id?: string;
  can_sell_tickets?: boolean;
  notes?: string;
  actual_departure_datetime?: string;
  actual_arrival_datetime?: string;
}

export interface CancelTripData {
  reason: string; // mínimo 10 caracteres según la API
}

export interface SearchTripsParams {
  company_id: number;
  start_date?: string; // formato YYYY-MM-DD
  end_date?: string; // formato YYYY-MM-DD
  status?: string[]; // Siempre como array
  origin_city_id?: number;
  destination_city_id?: number;
  trip_name_like?: string; // Para buscar por nombre
  skip?: number;
  limit?: number;
}

export interface AvailableTripByPort {
  id: number;
  trip_name: string;
  status: string;
  vessel_name: string;
  estimated_arrival_time?: string;
  estimated_departure_time: string;
  departure_datetime?: string; // Campo principal de fecha/hora de salida
  route_name?: string;
  origin_port_name?: string;
  destination_port_name?: string;
  total_seats?: number;
  available_seats?: number;
  boarding_date?: string; // OPCIONAL: Incluido cuando se usa end_date en la query
  departure_date?: string; // OPCIONAL: Incluido cuando se usa end_date en la query
}

export interface TripDetailsResponse extends Trip {
  vessel: Vessel;
  route: Trip['route']; // Asumimos que el tipo Route ya está definido en Trip
  stops: TripStop[];
  availability: TripSeatAvailability[]; // El backend lo llama 'availability'
}

class TripsService {
  private basePath = '/operations/trips/';

  async create(data: CreateTripData): Promise<Trip> {
    const response = await api.post(this.basePath, data);
    return response.data;
  }

  async getById(tripId: number): Promise<TripDetailsResponse> {
    const response = await api.get<TripDetailsResponse>(`${this.basePath}${tripId}`);
    return response.data;
  }

  async update(tripId: number, data: UpdateTripData): Promise<Trip> {
    const response = await api.patch(`${this.basePath}${tripId}`, data);
    return response.data;
  }

  async cancel(tripId: number, data: CancelTripData): Promise<Trip> {
    const response = await api.post(`${this.basePath}${tripId}/cancel`, data);
    return response.data;
  }

  async getAllForCompany(params: { company_id: number; skip?: number; limit?: number }): Promise<Trip[]> {
    const response = await api.get(this.basePath, { params });
    return response.data;
  }

  async getUpcoming(params: { company_id: number; limit?: number }): Promise<AvailableTrip[]> {
    const response = await api.get(`${this.basePath}upcoming`, { params });
    return response.data;
  }

  async getForWeek(params: { company_id: number; start_date: string }): Promise<Trip[]> {
    const response = await api.get(`${this.basePath}week-view`, { params });
    return response.data;
  }

  async search(params: SearchTripsParams): Promise<Trip[]> {
    const config: AxiosRequestConfig = {
      params,
      paramsSerializer: p => stringify(p, { arrayFormat: 'comma', allowDots: true }),
    };
    const response = await api.get(`${this.basePath}search`, config);
    // Normalizar respuesta: puede ser un array directo o un objeto paginado { results: [...] }
    const data = response.data;
    if (Array.isArray(data)) return data;
    return data?.results || data?.items || data?.data || [];
  }

  async searchAvailable(params: {
    start_date: string;
    company_id: number;
    origin_city_id?: number;
    destination_city_id?: number;
  }): Promise<AvailableTrip[]> {
    const response = await api.get(`${this.basePath}available`, { params });
    return response.data;
  }

  async getTripsByBoardingPort(
    companyId: number, 
    portId: number, 
    onDate: string,
    endDate?: string
  ): Promise<AvailableTripByPort[]> {
    const params: any = {
      company_id: companyId,
      port_id: portId,
      on_date: onDate,
    };

    // Usar el parámetro end_date si se proporciona (optimización para rangos)
    if (endDate) {
      params.end_date = endDate;
    }

    const response = await api.get<AvailableTripByPort[]>('/operations/trips/by-boarding-port', {
      params,
    });
    return response.data;
  }

  async getSeatMap(tripId: number): Promise<SeatMapItem[]> {
    const response = await api.get<SeatMapItem[]>(`${this.basePath}${tripId}/seat-map`);
    return response.data;
  }

  async previewVesselChange(tripId: number, data: PreviewVesselChangeRequest): Promise<PreviewVesselChangeResponse> {
    const response = await api.post<PreviewVesselChangeResponse>(`${this.basePath}${tripId}/preview-vessel-change`, data);
    return response.data;
  }
}

export const tripsService = new TripsService();

// src/services/userStatistics.service.ts
import api from '../config/api';
import { getLocalDateString, getDaysAgo, getMonthsAgo } from '../utils/dateUtils';

export interface UserStatisticsFilters {
  user_id: string;
  period: 'day' | 'month' | 'year';
  date: string; // Formato: YYYY-MM-DD
}

export interface UserStatisticsBranchOffice {
  id: number;
  name: string;
}

export interface UserStatisticsBreakdown {
  tickets: {
    count: number;
    revenue: string; // La API devuelve string
  };
  cargo: {
    count: number;
    revenue: string; // La API devuelve string
  };
}

export interface UserStatisticsResponse {
  user_id: string;
  period: 'day' | 'month' | 'year';
  date: string;
  branch_office: UserStatisticsBranchOffice;
  total_sales: number;
  total_revenue: number; // Mantener por compatibilidad (será igual a gross)
  total_revenue_gross?: number; // NUEVO: Ventas brutas (solo facturas/boletas)
  total_revenue_net?: number; // NUEVO: Ventas netas (resta notas crédito, suma notas débito)
  total_credit_notes?: number; // NUEVO: Total de notas de crédito
  total_debit_notes?: number; // NUEVO: Total de notas de débito
  currency: string;
  breakdown: UserStatisticsBreakdown;
}

export const userStatisticsService = {
  /**
   * Obtiene estadísticas de ventas para un usuario específico
   */
  getUserStatistics: async (filters: UserStatisticsFilters): Promise<UserStatisticsResponse> => {
    try {
      const params = new URLSearchParams();
      params.append('period', filters.period);
      params.append('date', filters.date);

      const response = await api.get<UserStatisticsResponse>(
        `/users/${filters.user_id}/sales-stats?${params.toString()}`
      );

      return response.data;
    } catch (error) {
      throw error;
    }
  },

  /**
   * Obtiene estadísticas del día actual para un usuario
   */
  getTodayStatistics: async (userId: string): Promise<UserStatisticsResponse> => {
    const today = getLocalDateString();
    return userStatisticsService.getUserStatistics({
      user_id: userId,
      period: 'day',
      date: today
    });
  },

  /**
   * Obtiene estadísticas del mes actual para un usuario
   */
  getCurrentMonthStatistics: async (userId: string): Promise<UserStatisticsResponse> => {
    const today = getLocalDateString();
    return userStatisticsService.getUserStatistics({
      user_id: userId,
      period: 'month',
      date: today
    });
  },

  /**
   * Obtiene estadísticas del año actual para un usuario
   */
  getCurrentYearStatistics: async (userId: string): Promise<UserStatisticsResponse> => {
    const today = getLocalDateString();
    return userStatisticsService.getUserStatistics({
      user_id: userId,
      period: 'year',
      date: today
    });
  },

  /**
   * Obtiene estadísticas de múltiples períodos para crear gráficos de tendencias
   * OPTIMIZADO: Usa el endpoint de rango del backend para evitar N+1 queries
   */
  getStatisticsTrends: async (
    userId: string,
    period: 'day' | 'month',
    startDate: string,
    endDate: string
  ): Promise<UserStatisticsResponse[]> => {
    try {
      // Usar el nuevo endpoint optimizado del backend
      const params = new URLSearchParams();
      params.append('period', period);
      params.append('start_date', startDate);
      params.append('end_date', endDate);

      const response = await api.get<UserStatisticsResponse[]>(
        `/users/${userId}/sales-stats-range?${params.toString()}`
      );

      return response.data;
    } catch (error) {
      throw error;
    }
  },

  /**
   * Obtiene estadísticas de los últimos 7 días para el usuario
   */
  getLast7DaysStatistics: async (userId: string): Promise<UserStatisticsResponse[]> => {
    const startDate = getDaysAgo(6); // 6 días atrás más hoy = 7 días
    const endDate = getLocalDateString();

    return userStatisticsService.getStatisticsTrends(userId, 'day', startDate, endDate);
  },

  /**
   * Obtiene estadísticas de los últimos 12 meses para el usuario
   */
  getLast12MonthsStatistics: async (userId: string): Promise<UserStatisticsResponse[]> => {
    const startDate = getMonthsAgo(11); // 11 meses atrás más este mes = 12 meses
    const endDate = getLocalDateString();

    return userStatisticsService.getStatisticsTrends(userId, 'month', startDate, endDate);
  }
};

